test "CK-VER1-002: modo plan bloquea el despacho del motor antes de workers y escrituras" {
    const a = std.testing.allocator;
    var runtime = try openRuntime(a);
    defer runtime.close();
    var mp = planner.MockPlanner.init(a);
    const backend = mp.backend();
    defer backend.deinit();
    var sa = Superagent.init(a, runtime, null, NoopMemory.backend(), 1);
    sa.wait_for_plan_approval = true;
    var outcome = try sa.processOrder("plan-test", "crea un modulo en C", &.{}, backend, null, null);
    defer outcome.deinit();
    const Worker = struct {
        calls: usize = 0,
        fn call(ctx: *anyopaque, _: []const u8, _: []const u8) []const u8 {
            const self: *@This() = @ptrCast(@alignCast(ctx));
            self.calls += 1;
            return "[]";
        }
    };
    var worker = Worker{};
    if (sa.approveAndDispatch(&outcome, Worker.call, &worker, null)) |value| {
        var result = value;
        result.deinit(a);
        return error.ExpectedPlanApprovalRequired;
    } else |failure| {
        try std.testing.expectEqual(error.PlanApprovalRequired, failure);
    }
    try std.testing.expectEqual(@as(usize, 0), worker.calls);
    const stmt = try runtime.prepare("SELECT COUNT(*) FROM tasks WHERE status != 'planned'");
    defer runtime.finalize(stmt);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
    try std.testing.expectEqual(@as(i64, 0), db.c.sqlite3_column_int64(stmt, 0));
}

