/// cola acotada dentro de una ola; las tareas locales siguen
/// serializadas en el hilo llamador salvo opt-in explícito.
fn dispatchWaveTasks(allocator: std.mem.Allocator, tasks: []const planner.PlannedTask, max_in_flight: usize, context: anytype, comptime run: anytype, comptime is_local: anytype, allow_local_parallel: bool) !usize {
    if (max_in_flight == 0) return error.InvalidConcurrencyLimit;
    const capacity = @min(tasks.len, max_in_flight);
    const threads = try allocator.alloc(std.Thread, capacity);
    defer allocator.free(threads);
    var peak: usize = 0;
    var offset: usize = 0;
    while (offset < tasks.len) {
        const batch = tasks[offset..][0..@min(capacity, tasks.len - offset)];
        var spawned: usize = 0;
        var sequential: usize = 0;
        var fallback: usize = 0;
        for (batch) |task| {
            if (!allow_local_parallel and is_local(context, task)) {
                sequential += 1;
                continue;
            }
            threads[spawned] = std.Thread.spawn(.{}, run, .{ context, task }) catch {
                // El llamador también ocupa un puesto de este lote.
                fallback = @max(fallback, spawned + 1);
                run(context, task);
                continue;
            };
            spawned += 1;
        }
        for (batch) |task| {
            if (allow_local_parallel or !is_local(context, task)) continue;
            run(context, task);
        }
        for (threads[0..spawned]) |thread| thread.join();
        peak = @max(peak, @max(fallback, spawned + @min(sequential, 1)));
        offset += batch.len;
    }
    return peak;
}

/// nivel de tools que la tarea declara al LLM en el loop V2.
/// - `governed_exec`: `run_command` + `ui_action` (corrección, que itera
///   inspeccionando y ejecutando).
/// - `governed_read`: solo `read_file`/`list_dir`/`grep_files` in-process,
///   confinadas al worktree (auditoría — nunca `run_command`: sus args no están
///   sandboxados y un exe allowlisted leería fuera del worktree, p. ej.
///   catalog.db con claves).
/// - `none`: la generación inicial produce un artefacto y el Core lo ejecuta
///   después mediante governedExecute; declarar run_command ahí duplica
///   autoridad y hace fallar modelos que sí generan código pero no soportan
///   bien tools.
const TaskToolMode = enum { none, governed_exec, governed_read, agentic };

/// D-C1 (E5.11): firma del seam de la sesión agéntica — recibe el LiveLlm ya
/// configurado (tools, gobernanza, cancelación) y devuelve la prosa final.
/// El contrato de cierre lo escribe la tool `finish` en `llm.last_agentic_*`.
pub const AgenticRunFn = *const fn (ctx: ?*anyopaque, llm: *live_worker.LiveLlm, system_prompt: []const u8, user_prompt: []const u8) []const u8;

fn defaultAgenticRun(_: ?*anyopaque, llm: *live_worker.LiveLlm, system_prompt: []const u8, user_prompt: []const u8) []const u8 {
    return live_worker.LiveLlm.agenticFn(llm, system_prompt, user_prompt);
}

/// el system prompt del trabajador de una tarea de prosa incorpora
/// la instrucción explícita de idioma cuando el de la orden es concluyente. Un
/// texto no concluyente (o una tarea que no es de prosa) no impone nada — el
/// mismo criterio que `lang_detect`. Cubre a la vez el worker nativo, el modo
/// agéntico y el agente externo, que parten de este system prompt.
/// `.auditar` solo es prosa entregable en una auditoría independiente
/// (`es_auditoria`); el informe interno de una orden de código no recibe la
/// instrucción, igual que el gate lo deja fuera.
fn buildWorkerSystemPrompt(allocator: std.mem.Allocator, base: []const u8, task_type: model_router.TaskType, description: []const u8, es_auditoria: bool) ![]const u8 {
    if (task_type == .auditar and !es_auditoria) return allocator.dupe(u8, base);
    if (prose_artifact.proseLanguageInstruction(task_type, description)) |instruction| {
        return std.fmt.allocPrint(allocator, "{s}\n\n[IDIOMA DEL ENTREGABLE]\n{s}", .{ base, instruction });
    }
    return allocator.dupe(u8, base);
}

fn taskToolMode(task_type: model_router.TaskType) TaskToolMode {
    return switch (task_type) {
        .corregir => .governed_exec,
        // `auditar` verifica por LECTURA del worktree: sin tools quedaba ciego
        // (, ronda 3: 0 lecturas reales → informes fabricados). `testear`
        // sigue sin tools: consume la evidencia producida y el Core ejecuta el
        // artefacto con governedExecute.
        .auditar => .governed_read,
        .programar, .programar_c, .programar_cpp, .programar_zig, .planificar, .testear, .documentar, .investigar, .resumir, .ejecutar, .disenar, .ui => .none,
    };
}

/// D-C1 (E5.11): conjunto de tareas productoras candidatas al modo agéntico.
fn agenticEligible(task_type: model_router.TaskType) bool {
    return switch (task_type) {
        .programar, .programar_c, .programar_cpp, .programar_zig, .testear, .documentar, .ui, .disenar => true,
        else => false,
    };
}

/// D-C1 (E5.11): modo de tools resuelto para (tarea, modelo asignado). Las
/// productoras prefieren `.agentic`, pero SOLO con `cap_tool_calls` medida en
/// vivo (live_probe) — sin esa evidencia cae a `.none` y `motivo` dice por qué
/// (va en el evento `agentic_unavailable`). Función pura: el evento lo emite
/// el llamador, que es quien tiene el contexto de la orden.
const AgenticModeDecision = struct { mode: TaskToolMode, motivo: ?[]const u8 = null };

fn decideTaskToolMode(catalog: ?db.Connection, now: i64, task_type: model_router.TaskType, provider: []const u8, model: []const u8) AgenticModeDecision {
    const base = taskToolMode(task_type);
    // #874: la reparación (.corregir = governed_exec) abre una sesión de
    // herramientas nativas. Antes lo hacía SIEMPRE, sin mirar la matriz, y con
    // Cohere command-a-reasoning-08-2025 gastó la reparación en un HTTP 422.
    // Ahora consulta la MISMA puerta medida que las productoras: solo con
    // `cap_tool_calls='yes'` (live_probe, foto fresca) se abren tools; cualquier
    // otra evidencia degrada a `.none` con motivo. `.auditar` (governed_read) y
    // el resto de tipos conservan su base intacta.
    const needs_gate = (base == .governed_exec) or (base == .none and agenticEligible(task_type));
    if (!needs_gate) return .{ .mode = base };
    const open_mode: TaskToolMode = if (base == .governed_exec) .governed_exec else .agentic;
    const conn = catalog orelse return .{ .mode = .none, .motivo = "sin_catalogo" };
    return switch (model_router.agenticGateFor(conn, provider, model, now)) {
        .ok => .{ .mode = open_mode },
        .sin_fila => .{ .mode = .none, .motivo = "sin_fila_en_discovery_snapshots_v2" },
        .sin_medicion_viva => .{ .mode = .none, .motivo = "cap_tool_calls sin provenance live_probe" },
        .medido_no => .{ .mode = .none, .motivo = "cap_tool_calls medida 'no' en vivo" },
        .foto_caducada => .{ .mode = .none, .motivo = "foto de capacidades caducada" },
    };
}

/// Techo de rondas del bucle agéntico: el ajuste «pasos del agente» de la
/// cabina, acotado a [2, 32] (el bridge no acepta más de 32 y con menos de 2
/// el modelo no podría ni ejecutar una tool y leer su resultado).
fn agenticMaxRounds(setting: usize) usize {
    return @min(@max(setting, 2), 32);
}

fn governedToolsCancelled(ctx: ?*anyopaque) bool {
    const token: *const live_worker.CancellationToken = @ptrCast(@alignCast(ctx.?));
    return token.isCancelled();
}

fn bindTaskBrowser(llm: *live_worker.LiveLlm, service: ?*browser_service.Service, worker_id: []const u8) void {
    const browser = service orelse return;
    if (llm.governed_tools_source) |*source| {
        source.browser = browser;
        source.browser_identity = browser.identity(worker_id, browser.nextAttempt());
        llm.order_id = browser.owner.order_id;
        llm.task_id = worker_id;
    }
}

test "E2P1 dispatch grants workers the same order service and overwrites untrusted identity" {
    const a = std.testing.allocator;
    const service = try browser_service.Service.create(a, .{ .order_id = 41, .space_id = 7, .workspace_root = "C:\\fixture" });
    defer service.release();
    var first = live_worker.LiveLlm{ .allocator = a, .lives = &.{}, .buffer = .empty, .catalog_path = "", .order_id = 999 };
    defer first.deinit();
    var second = live_worker.LiveLlm{ .allocator = a, .lives = &.{}, .buffer = .empty, .catalog_path = "" };
    defer second.deinit();
    configureTaskLiveLlm(&first, .agentic, "C:\\fixture", .{}, true, .local, null, null, 3);
    configureTaskLiveLlm(&second, .governed_exec, "C:\\fixture", .{}, true, .local, null, null, 3);
    bindTaskBrowser(&first, service, "a");
    bindTaskBrowser(&second, service, "b");
    try std.testing.expectEqual(@as(i64, 41), first.order_id);
    try std.testing.expectEqual(first.order_id, second.order_id);
    try std.testing.expectEqual(first.governed_tools_source.?.browser.?, second.governed_tools_source.?.browser.?);
    try std.testing.expectEqual(@as(i64, 7), first.governed_tools_source.?.browser_identity.?.space_id);
    try std.testing.expectEqualStrings("a", first.governed_tools_source.?.browser_identity.?.worker_id);
    try std.testing.expectEqualStrings("b", second.governed_tools_source.?.browser_identity.?.worker_id);
    try std.testing.expect(first.governed_tools_source.?.browser_identity.?.attempt_id != second.governed_tools_source.?.browser_identity.?.attempt_id);
}

fn configureTaskLiveLlm(
    llm: *live_worker.LiveLlm,
    mode: TaskToolMode,
    workspace_root: []const u8,
    permission_config: executor.PermissionConfig,
    plan_approved: bool,
    origin: executor.Origin,
    spawn_fn: ?executor.SpawnFn,
    cancel_token: ?*const live_worker.CancellationToken,
    agentic_rounds: usize,
) void {
    if (cancel_token) |token| llm.setCancelToken(token);
    if (mode == .none) return;
    llm.setUseConnectorV2Dispatch(true);
    // una auditoría real necesita decenas de lecturas — 5 rondas (el
    // default de `corregir`) no alcanzan ni para listar el árbol. Las tools de
    // auditar son solo lectura, así que el coste de más rondas es solo tiempo
    // de proveedor. El techo duro del bridge es 32.
    if (mode == .governed_read) llm.max_tool_rounds = 28;
    // D-C1: las rondas del modo agéntico salen del ajuste de pasos de la
    // cabina, acotado a [2, 32] por agenticMaxRounds.
    if (mode == .agentic) llm.max_tool_rounds = agenticMaxRounds(agentic_rounds);
    llm.setGovernedTools(.{
        .policy = .{ .workspace_root = workspace_root, .origin = origin },
        .permission_config = permission_config,
        .plan_approved = plan_approved,
        .read_only = mode == .governed_read,
        .agentic = mode == .agentic,
        .spawn_fn = spawn_fn,
        .is_cancelled_fn = if (cancel_token != null) governedToolsCancelled else null,
        .cancelled_ctx = if (cancel_token) |token| @constCast(token) else null,
    });
}

/// Superagente: cerebro de la pirámide (spec 009, Fase 4 del ROADMAP).
///
/// Loop: entender → (clarificar si procede) → descubrir herramientas → plan con
/// grafo de tareas tipadas → contratos por pieza → asignar modelo por tarea (router F3)
/// → esperar aprobación → despachar al scheduler (F1) con sandbox por worker → reporte.
///
/// Todo el loop es testeable de punta a punta sin red usando `MockPlanner` y el
/// backend de descubrimiento por reglas (FR-007).
pub const OrderStatus = enum {
    pending,
    clarifying,
    planned,
    approved,
    running,
    awaiting_approval,
    done,
    failed,
    rejected,
    /// TERMINAL-STATE-DESIGN-2026-07-12: estado terminal añadido al enum y a sus
    /// conversiones C. Todavía sin ningún call-site que lo emita (P0 solo prepara
    /// el terreno; la cancelación real queda para un incremento posterior).
    cancelled,
    /// RESUME-INTERRUPTED: la orden quedó en un estado que implica hilo vivo
    /// (pending/approved/running) cuando el proceso murió. La reconciliación de
    /// arranque en da_core_init la escribe; reanudarla exige consentimiento del
    /// usuario — el motor nunca gasta cuota re-lanzándola por su cuenta.
    interrupted,
    /// AUDIT-UNAVAILABLE-P0 (S22, orden 500): la ejecución y los gates pasaron,
    /// pero ninguna tarea `auditar` produjo un veredicto usable (proveedor
    /// agotado, respuesta sin JSON, campo `verdict` ausente o irreconocible).
    /// No es `done` — la entrega queda bloqueada hasta que exista una
    /// auditoría válida — ni `failed` — no hay defecto del producto medido.
    /// El usuario decide si reintenta la auditoría a mano (da_order_resume_async);
    /// nunca hay reintento automático ni gasto nuevo sin su orden. NO entra en
    /// la lista de terminales de tryCommitTerminal/updateOrderStatus: el
    /// reintento debe poder comprometer done/failed después.
    audit_unavailable,
    /// E5.18 (D-C5): orden best-of-N con las N candidatas ya terminadas y
    /// rankeadas, esperando que el usuario elija ganadora. Espera honesta:
    /// las candidatas y sus métricas ya están persistidas, así que el estado
    /// sobrevive a reinicios. Tampoco entra en la lista de terminales de
    /// tryCommitTerminal — la elección del usuario la compromete a done.
    awaiting_best_of_n,

    pub fn toText(self: OrderStatus) []const u8 {
        return @tagName(self);
    }
};

/// ENJAMBRE: un miembro del conjunto de modelos elegido por el usuario.
/// El reparto es determinista (ver pickSwarmIndex) y CERRADO: las tareas
/// productoras solo usan miembros del conjunto, igual que sus respaldos.
/// El auditor sale del conjunto si ya no queda miembro independiente.
pub const SwarmMember = struct {
    provider: []const u8,
    model: []const u8,
};

/// FIX-5 / FALLBACK-01: un (proveedor, modelo) candidato para una tarea.
pub const ModelChoice = struct {
    provider_name: []const u8,
    model_name: []const u8,
    is_free: bool,

    pub fn deinit(self: ModelChoice, allocator: std.mem.Allocator) void {
        allocator.free(self.provider_name);
        allocator.free(self.model_name);
    }
};

/// CHECKPOINT-T2: una tarea que el checkpoint persistido declara COMPLETADA
/// antes de la interrupción. Al reanudar no vuelve a correr — se restaura como
/// resultado ya integrado para que las dependencias de las tareas pendientes
/// sigan resolviendo y su artefacto alimente el contexto upstream.
/// `task_id` y `artifact_path` son prestados: el llamador los posee durante
/// todo el despacho (en c_api los carga la arena del CoreState).
pub const RestoredTask = struct {
    task_id: []const u8,
    artifact_path: ?[]const u8,
};

/// CHECKPOINT-T2: el estado persistido de una orden interrumpida, leído de la
/// tabla `tasks` al reanudar. Todas las slices son prestadas (arena del Core).
pub const ResumeCheckpoint = struct {
    /// Tareas 'completed' — se restauran, NO se re-ejecutan.
    restored: []const RestoredTask,
    /// Tareas que quedaron 'running' cuando el proceso murió — NO hay
    /// continuidad interna que fingir: se reportan explícitamente como
    /// incompletas y se re-ejecutan ENTERAS.
    interrupted: []const []const u8,
};

/// Modelo asignado a una tarea del plan por el router (FR-005).
pub const ModelAssignment = struct {
    /// Referencia al id lógico de la tarea (vive tanto como `OrderOutcome.plan`).
    task_id: []const u8,
    assigned: bool,
    provider_name: []const u8,
    model_name: []const u8,
    is_free: bool,
    reason: []const u8,
    /// FIX-5 / FALLBACK-01: modelos de respaldo (ordenados, free) a intentar si el primario
    /// falla. Precomputados en assignModel (un hilo); NO incluyen el primario.
    fallbacks: []ModelChoice = &.{},

    pub fn deinit(self: ModelAssignment, allocator: std.mem.Allocator) void {
        allocator.free(self.provider_name);
        allocator.free(self.model_name);
        allocator.free(self.reason);
        for (self.fallbacks) |fc| fc.deinit(allocator);
        allocator.free(self.fallbacks);
    }
};

/// Resultado de procesar una orden. Posee el plan y las asignaciones.
pub const OrderOutcome = struct {
    allocator: std.mem.Allocator,
    order_id: i64,
    plan_id: ?i64,
    status: OrderStatus,
    /// autorización de ejecución separada de la planificación.
    wait_for_plan_approval: bool = false,
    plan: planner.Plan,
    assignments: []ModelAssignment,
    discovery_needed: [][]const u8,
    discovery_missing: [][]const u8,
    /// Resources completos descubiertos como necesarios para esta orden.
    discovery_needed_resources: []tool_discovery.Resource,

    pub fn deinit(self: *OrderOutcome) void {
        const a = self.allocator;
        self.plan.deinit();
        for (self.assignments) |asg| asg.deinit(a);
        a.free(self.assignments);
        for (self.discovery_needed) |n| a.free(n);
        a.free(self.discovery_needed);
        for (self.discovery_missing) |m| a.free(m);
        a.free(self.discovery_missing);
        freeResources(a, self.discovery_needed_resources);
    }
};

/// Salida de ejecución gobernada para volcar a consolas/IDE (EXEC-01).
pub const WorkerOutput = struct {
    worker_id: []const u8,
    stream: []const u8,
    text: []const u8,
    /// P05: task_id asociado (para consolidar worker_output con shell_command en la UI).
    task_id: []const u8 = "",
};

/// Solicitud de aprobación generada cuando una acción escapa de la política.
pub const ApprovalRequest = struct {
    task_id: []const u8,
    description: []const u8,
    /// Prefix del comando que generó la aprobación (P2: scope session/always).
    command_prefix: ?[]const u8 = null,
    /// P-EXEC-4: exe + args_json para re-ejecutar el comando al aprobar.
    exe: ?[]const u8 = null,
    args_json: ?[]const u8 = null,

    pub fn deinit(self: ApprovalRequest, allocator: std.mem.Allocator) void {
        allocator.free(self.task_id);
        allocator.free(self.description);
        if (self.command_prefix) |p| allocator.free(p);
        if (self.exe) |e| allocator.free(e);
        if (self.args_json) |a| allocator.free(a);
    }
};

/// persiste una aprobación pendiente en `approvals` (runtime.db).
///
/// Existía SOLO dentro de `c_api.zig` (camino cabina). El CLI se limitaba a
/// imprimir «Aprobaciones pendientes: N» y no escribía nada, así que una orden
/// que quedaba en `awaiting_approval` desde el CLI no tenía fila que resolver:
/// ni `devagents approvals` ni la cabina la veían, y la orden se quedaba
/// bloqueada para siempre. Medido el 2026-08-15: 54 órdenes en ese estado con
/// la tabla `approvals` VACÍA.
///
/// Devuelve el `rowid` insertado.
pub fn persistApprovalRequest(
    conn: db.Connection,
    req: ApprovalRequest,
    order_id: i64,
    created_at: i64,
) !i64 {
    const stmt = try conn.prepare("INSERT INTO approvals (task_id, description, approved, resolved, created_at, command_prefix, exe, args_json, order_id) VALUES (?, ?, 0, 0, ?, ?, ?, ?, ?)");
    defer conn.finalize(stmt);
    try db.bindText(stmt, 1, req.task_id);
    try db.bindText(stmt, 2, req.description);
    try db.bindInt(stmt, 3, created_at);
    try db.bindText(stmt, 4, req.command_prefix orelse "");
    try db.bindText(stmt, 5, req.exe orelse "");
    try db.bindText(stmt, 6, req.args_json orelse "");
    try db.bindInt(stmt, 7, order_id);
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE) return error.ExecFailed;
    return db.c.sqlite3_last_insert_rowid(conn.db);
}

/// P5b: entrada de audit_ledger generada por el dispatch del superagente.
/// Se persiste en ledger.db por dispatchApprovedOrder (c_api.zig).
pub const AuditEntry = struct {
    ts: i64,
    subject_kind: []const u8,
    subject_id: i64,
    /// AUDIT-INDEP: subject_id es el índice DENTRO de la orden ("T1"→1); sin
    /// order_id dos órdenes comparten subject y sus auditorías se fusionan.
    order_id: i64 = 0,
    action: []const u8,
    verdict: []const u8,
    model_id: []const u8,
    provider: []const u8,
    evidence_ref: []const u8,
    notes: []const u8,
    /// T8: qué auditor del plan firmó el veredicto. 0 = evidencia
    /// del motor (puerta determinista, checkpoint), 1 = primer auditor,
    /// 2 = segundo auditor (rol `second_audit` del compositor). Viaja en el
    /// evento `task_audit` para que el grafo no adivine por el nombre.
    auditor_index: u8 = 0,

    pub fn deinit(self: AuditEntry, allocator: std.mem.Allocator) void {
        allocator.free(self.subject_kind);
        allocator.free(self.action);
        allocator.free(self.verdict);
        allocator.free(self.model_id);
        allocator.free(self.provider);
        allocator.free(self.evidence_ref);
        allocator.free(self.notes);
    }
};

/// Resultado del despacho: reporte consolidado + salidas + aprobaciones pendientes.
pub const DispatchResult = struct {
    report: []const u8,
    outputs: []const WorkerOutput,
    pending_approvals: []const ApprovalRequest,
    failed_count: usize = 0,
    completed_count: usize = 0,
    integrated_count: usize = 0,
    /// P5b: entradas de audit_ledger para persistir en ledger.db.
    audit_entries: []const AuditEntry = &.{},
    /// P10-T4: ruta opcional a screenshot de autoevaluación visual.
    screenshot_path: ?[]const u8 = null,
    /// FASE-AGENTIC-2: el ENTREGABLE real que se muestra al usuario como respuesta
    /// del asistente (evento agent_message) — distinto de `report`, que es el
    /// meta-reporte de estadísticas de tareas. Ver synthesizeFinalAnswer().
    final_answer: []const u8 = "",
    /// AUDIT-UNAVAILABLE-P0: cuántas tareas `auditar` terminaron sin veredicto
    /// usable. Se informa aparte de failed_count — no son fallos del producto.
    audit_unavailable_count: usize = 0,
    /// AUDIT-UNAVAILABLE-P0: la iteración cerró sin auditoría válida y sin
    /// fallos reales — el terminal a comprometer es audit_unavailable.
    order_audit_unavailable: bool = false,
    /// Resultado terminal calculado por la iteración. El coordinador del loop usa
    /// este valor para finalizar la orden una sola vez, después del último paso.
    order_failed: bool = false,
    paid_budget_exhausted: bool = false,
    paid_budget_reason: []const u8 = "",
    /// C2: espejo de cancelled_now en el momento en que esta iteración terminó.
    /// finalizeDeferredOrder lo usa para decidir el terminal cuando defer_order_
    /// finalization está activo (agentic loop) — mismo rol que order_failed.
    order_cancelled: bool = false,

    pub fn deinit(self: *DispatchResult, allocator: std.mem.Allocator) void {
        allocator.free(self.report);
        if (self.paid_budget_reason.len > 0) allocator.free(self.paid_budget_reason);
        for (self.outputs) |o| {
            allocator.free(o.worker_id);
            allocator.free(o.stream);
            if (o.task_id.len > 0) allocator.free(o.task_id);
            allocator.free(o.text);
        }
        allocator.free(self.outputs);
        for (self.pending_approvals) |a| a.deinit(allocator);
        allocator.free(self.pending_approvals);
        for (self.audit_entries) |e| e.deinit(allocator);
        if (self.audit_entries.len > 0) allocator.free(self.audit_entries);
        if (self.screenshot_path) |sp| allocator.free(sp);
        if (self.final_answer.len > 0) allocator.free(self.final_answer);
    }
};

/// Interfaz de memoria de proyecto (FR-009). Implementación no-op hasta F6 (Engram vía MCP).
pub const MemoryBackend = struct {
    ptr: *anyopaque,
    loadContextFn: *const fn (ctx: *anyopaque, allocator: std.mem.Allocator, project: []const u8) ?[]const u8,
    saveFindingFn: *const fn (ctx: *anyopaque, finding: []const u8) void,
    sessionSummaryFn: *const fn (ctx: *anyopaque, summary: []const u8, project: []const u8) void,
    saveLessonFn: *const fn (ctx: *anyopaque, lesson: []const u8, project: []const u8) bool,
    loadLessonsFn: *const fn (ctx: *anyopaque, allocator: std.mem.Allocator, project: []const u8, limit: usize) ?[]const u8,

    pub fn loadContext(self: MemoryBackend, allocator: std.mem.Allocator, project: []const u8) ?[]const u8 {
        return self.loadContextFn(self.ptr, allocator, project);
    }

    pub fn saveFinding(self: MemoryBackend, finding: []const u8) void {
        self.saveFindingFn(self.ptr, finding);
    }

    pub fn saveSessionSummary(self: MemoryBackend, summary: []const u8, project: []const u8) void {
        self.sessionSummaryFn(self.ptr, summary, project);
    }

    /// T8: true solo si el backend la guardó de verdad (la memoria no-op y un
    /// fallo de escritura dan false: el grafo no anuncia lo que no ocurrió).
    pub fn saveLesson(self: MemoryBackend, lesson: []const u8, project: []const u8) bool {
        return self.saveLessonFn(self.ptr, lesson, project);
    }

    pub fn loadLessons(self: MemoryBackend, allocator: std.mem.Allocator, project: []const u8, limit: usize) ?[]const u8 {
        return self.loadLessonsFn(self.ptr, allocator, project, limit);
    }
};

/// Memoria no-op: no carga contexto ni persiste hallazgos (placeholder de F6).
pub const NoopMemory = struct {
    pub fn backend() MemoryBackend {
        return .{ .ptr = undefined, .loadContextFn = load, .saveFindingFn = save, .sessionSummaryFn = summary, .saveLessonFn = saveLesson, .loadLessonsFn = loadLessons };
    }
    fn load(_: *anyopaque, _: std.mem.Allocator, _: []const u8) ?[]const u8 {
        return null;
    }
    fn save(_: *anyopaque, _: []const u8) void {}
    fn summary(_: *anyopaque, _: []const u8, _: []const u8) void {}
    fn saveLesson(_: *anyopaque, _: []const u8, _: []const u8) bool {
        return false;
    }
    fn loadLessons(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: usize) ?[]const u8 {
        return null;
    }
};

/// Tarjeta compartida: lo mostrado coincide con el argv/cwd que se reanudará.
fn executionApproval(allocator: std.mem.Allocator, config: executor.PermissionConfig, exe: []const u8, args: []const []const u8, cwd: []const u8, task_id: []const u8, origin: executor.Origin) !ApprovalRequest {
    var root_buf: [4096]u8 = undefined;
    const exact = command_policy.decide(exe, args, config.deny_prefixes, .{ .allocator = allocator, .workspace_root = workspace.effectiveRoot(&root_buf), .cwd = cwd, .read_only_only = origin.requiresHumanApproval() }) != .exempt;
    const display = try executor.renderCommandLine(allocator, exe, args);
    defer allocator.free(display);
    const task = try allocator.dupe(u8, task_id);
    errdefer allocator.free(task);
    const description = try std.fmt.allocPrint(allocator, "Ejecutar {s} en {s} requiere aprobación (modo: {s})", .{ display, cwd, @tagName(config.mode) });
    errdefer allocator.free(description);
    const prefix = try allocator.dupe(u8, if (exact) "shell_command" else executor.stripExe(executor.basename(exe)));
    errdefer allocator.free(prefix);
    const executable = try allocator.dupe(u8, exe);
    errdefer allocator.free(executable);
    // El contrato antiguo de arrays sigue siendo legible. Las aprobaciones
    // exactas incluyen cwd para que la reanudación ejecute lo que vio la UI.
    const payload = if (exact)
        try std.json.Stringify.valueAlloc(allocator, .{ .args = args, .cwd = cwd, .timeout_ms = 10_000 }, .{})
    else
        try serializeArgsJson(allocator, args);
    return .{ .task_id = task, .description = description, .command_prefix = prefix, .exe = executable, .args_json = payload };
}

fn serializeArgsJson(allocator: std.mem.Allocator, args: []const []const u8) ![]const u8 {
    var out: std.Io.Writer.Allocating = .init(allocator);
    errdefer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    try js.beginArray();
    for (args) |a| {
        try js.write(a);
    }
    try js.endArray();
    return out.toOwnedSlice();
}

test "SEC2 superagent approval shows exact command and forbids prefix scope for inline" {
    const allocator = std.testing.allocator;
    const args = &[_][]const u8{ "-c", "print('a & | ^ % ! < > ( ) \\\"')\nprint(2)" };
    const request = try executionApproval(allocator, .{ .mode = .bypass }, "python", args, "C:\\workspace\\a & b", "task", .local);
    defer request.deinit(allocator);
    try std.testing.expectEqualStrings("shell_command", request.command_prefix.?);
    try std.testing.expect(std.mem.indexOf(u8, request.description, "print(2)") != null);
    try std.testing.expect(std.mem.indexOf(u8, request.description, "C:\\workspace\\a & b") != null);
    var parsed = try std.json.parseFromSlice(std.json.Value, allocator, request.args_json.?, .{});
    defer parsed.deinit();
    try std.testing.expectEqualStrings(args[1], parsed.value.object.get("args").?.array.items[1].string);
    try std.testing.expectEqualStrings("C:\\workspace\\a & b", parsed.value.object.get("cwd").?.string);
    const denied = try executionApproval(allocator, .{ .deny_prefixes = &.{"rm"} }, "bash", &.{ "script.sh", "RM.EXE" }, ".", "task", .local);
    defer denied.deinit(allocator);
    try std.testing.expectEqualStrings("shell_command", denied.command_prefix.?);
    const old = try executionApproval(allocator, .{}, "zig", &.{"version"}, ".", "task", .local);
    defer old.deinit(allocator);
    try std.testing.expectEqualStrings("zig", old.command_prefix.?);
    try std.testing.expect(std.mem.startsWith(u8, old.args_json.?, "["));
}

/// E3.16: marcador honesto de truncado. Si el cap de `max_output_bytes` dejó
/// fuera bytes del pipe, devuelve una línea visible que lo dice; si no, "".
/// Antes de esto un comando de 50 MB reportaba "exit=0" con 256 KB y nadie
/// sabía que el 99,5% de la salida se había descartado.
fn execTruncationNote(allocator: std.mem.Allocator, r: executor.RunResult) ![]const u8 {
    if (!r.stdoutTruncated() and !r.stderrTruncated()) return try allocator.dupe(u8, "");
    return std.fmt.allocPrint(allocator, "\n[salida truncada al cap: stdout {d} B mostrados de {d} B, stderr {d} B de {d} B]", .{ r.stdout.len, r.stdout_total_bytes, r.stderr.len, r.stderr_total_bytes });
}

pub const Superagent = struct {
    rules_context: ?project_rules.Context = null,
    rules_catalog: ?db.Connection = null,
    browser_registry: ?*browser_service.Registry = null,
    allocator: std.mem.Allocator,
    runtime: db.Connection,
    /// Router opcional: si es null, el plan se genera pero las tareas quedan sin modelo asignado.
    router: ?*model_router.Router,
    memory: MemoryBackend,
    now: i64,
    /// Contexto requerido por defecto al rutear (afecta el factor de ventana del router).
    required_context: i32 = 32000,
    /// Spawn inyectable para tests de EXEC-01; null usa `spawnWin32` real.
    executor_spawn_fn: ?executor.SpawnFn = null,
    /// Origen de la orden actual. Por defecto `.local`; IDE-REMOTE podrá marcar `.untrusted`.
    order_origin: executor.Origin = .local,
    /// Aprobación humana en línea de ESTE argv/cwd exactos, como la de las tools
    /// nativas. Solo las pruebas la fijan para simular la tarjeta de la cabina;
    /// producción la deja en null y publica la tarjeta. Un origen MCP nunca la usa.
    approve_command_fn: ?*const fn (?*anyopaque, []const u8, []const []const u8, []const u8) anyerror!bool = null,
    approve_command_ctx: ?*anyopaque = null,
    /// P2: configuración de permisos (modo + allow/deny prefix lists).
    permission_config: executor.PermissionConfig = .{},
    /// BUG-1: eventos que no llegaron a la base. Ver `recordEvent`.
    eventos_perdidos: std.atomic.Value(usize) = std.atomic.Value(usize).init(0),
    /// P-EXEC-6: true cuando la orden fue aprobada vía plan-card.
    /// Hace que checkPrefix .ask se trate como .auto EXCEPTO denylist y código inline.
    plan_approved: bool = false,
    wait_for_plan_approval: bool = false,
    /// Registro unificado de especialistas (nativos + Pixel). PIXEL-DEVTEAM-05.
    registry: ?*pixel_registry.UnifiedRegistry = null,
    /// UX-08/F0: conexión opcional para emitir eventos de ciclo de vida en events().
    event_conn: ?db.Connection = null,
    /// Orden asociada a los eventos de ciclo de vida (0 = sin orden).
    event_order_id: i64 = 0,
    /// MODELO-MANUAL-ORQUESTACION: modelo fijado por el usuario vía plan_set_model.
    /// Antes solo alimentaba la llamada de PLANIFICACIÓN (llm_planner.initForced);
    /// la asignación de modelo POR TAREA (assignModel, usada en dispatch/ejecución)
    /// lo ignoraba por completo y siempre enrutaba free-first. Si está seteado,
    /// assignModel lo usa como PRIMARIO obligatorio (con fallbacks del router
    /// como respaldo si el forzado falla) — cumple "prioridad obligatoria" para
    /// planificación Y orquestación, pedido explícito del propietario.
    /// ROLES-MODELO: este es el pin del EJECUTOR (constructoras + correcciones),
    /// ya resuelto aguas arriba como exec_pin ?? plan_pin.
    forced_provider: ?[]const u8 = null,
    forced_model: ?[]const u8 = null,
    /// ROLES-MODELO: pin del AUDITOR — solo lo usan las tareas `.auditar`.
    /// Resuelto aguas arriba como audit_pin ?? plan_pin. NUNCA hereda del pin
    /// del ejecutor: un auditor con el modelo constructor no es auditoría
    /// independiente (deriveStatus tampoco la contaría).
    audit_forced_provider: ?[]const u8 = null,
    audit_forced_model: ?[]const u8 = null,
    /// MODO-DETERMINISTA: con un modelo fijado, prohibe los respaldos. La orden
    /// entera la hace ese modelo o falla diciendo cual fue.
    ///
    /// Sin esto, fijar un modelo solo elegia el PRIMARIO: `assignModel` seguia
    /// rellenando hasta 5 respaldos gratis + 2 de pago, asi que al primer fallo
    /// la tarea se iba a otro modelo sin avisar. Eso hace imposible responder
    /// "¿este modelo cumple el contrato de artefactos?", que es justo la pregunta
    /// abierta con la epidemia de `empty`.
    ///
    /// Sin `forced_provider` no hace nada: un determinista sin modelo fijado no
    /// significa nada, y desactivar los respaldos del ruteo automatico solo
    /// serviria para que las ordenes fallaran mas.
    deterministic: bool = false,
    /// ENJAMBRE: conjunto cerrado de modelos para las tareas productoras,
    /// elegido por el usuario (da_swarm_set_models_json). Vacío = automático
    /// (el router decide por tarea, como siempre). Con un pin de rol fijado,
    /// el pin gana: es la elección explícita más específica.
    swarm: []const SwarmMember = &.{},
    /// P09-T3: cliente MCP del bridge de Open Design (opcional, inyectado desde c_api).
    od_mcp_state: ?*od_mcp.OdMcpState = null,
    /// P12-T3: selector agéntico por-tarea (opcional, inyectado desde c_api).
    discovery_llm: ?*tool_discovery.LlmDiscovery = null,
    /// P12-T3: inventario cacheado (opcional, inyectado desde c_api).
    inventory_ptr: ?*const tool_discovery.Inventory = null,
    /// P12-T3: texto de la orden original (para selectPerTask).
    order_text: ?[]const u8 = null,
    /// fila de `orders` que processOrder debe REUTILIZAR en vez de
    /// insertar una nueva. La fija quien ya reservó la fila (submit async) o
    /// quien replanifica tras una aclaración: antes cada replan insertaba otra
    /// fila y la original quedaba `clarifying` para siempre (14 huérfanas
    /// medidas), y el submit async devolvía un contador en memoria que no era
    /// el rowid (dos procesos, dos contadores).
    reuse_order_id: ?i64 = null,
    /// T8: cambios que el usuario pidió al plan (da_order_replan_async).
    /// Si está puesto, processOrder anuncia `replan_v1` al insertar el plan nuevo.
    replan_changes: ?[]const u8 = null,
    /// GOBERNANZA-EJECUCION (2026-07-08): rutas ya lanzadas como app GUI detached en
    /// ESTA orden. Confirmado en vivo: una tarea "programar" que genera código con
    /// tkinter/pygame se auto-lanza (FASE-0/EXEC-02, más abajo) para vista previa
    /// inmediata; si el plan TAMBIÉN incluye una tarea "ejecutar" dedicada para el
    /// mismo archivo (patrón normal cuando el usuario pide "créalo Y ejecútalo"), esa
    /// tarea lanzaba el MISMO ejecutable OTRA VEZ — dos procesos/ventanas duplicados
    /// para un solo resultado. Ninguna de las dos rutas de código (governedExecute se
    /// llama desde programar Y desde ejecutar) sabía de la otra. Lista corta —
    /// una orden normal genera pocos archivos — así que un scan lineal es correcto
    /// y evita gestionar el ciclo de vida de un HashMap con claves propias.
    launched_gui_paths: std.ArrayList([]const u8) = .empty,
    /// FASE-AGENTIC-3: máximo de iteraciones del loop observe→re-planifica.
    /// DEFAULT 1 = un solo paso (comportamiento idéntico al de hoy; el código del
    /// loop en agenticExecute NO se ejecuta). El propietario lo sube (vía config) para
    /// activar el loop autónomo estilo Devin una vez verificado en vivo.
    max_agent_iterations: usize = 1,
    /// Las iteraciones internas no son órdenes completas: no publican estados ni
    /// eventos terminales hasta que agenticExecute cierra el loop.
    defer_order_finalization: bool = false,
    /// C2: token de cancelación PRESTADO para el despacho actual (ver doc de
    /// live_worker.CancellationToken). dispatchApprovedOrder lo crea e inyecta aquí
    /// antes de llamar agenticExecute/approveAndDispatch; Superagent NUNCA lo posee
    /// ni lo libera — solo lo propaga a FanoutContext y a los LiveLlm por-tarea.
    cancel_token: ?*const live_worker.CancellationToken = null,
    /// CHECKPOINT-T2: cuando este despacho ES una reanudación, el checkpoint
    /// persistido de la orden (tabla tasks): qué se restaura y qué se reporta
    /// como interrumpido a medias. Sus slices son prestados — el llamador los
    /// posee durante todo el despacho.
    resume_checkpoint: ?ResumeCheckpoint = null,
    /// E5.08: seam de ejecución del agente externo (proveedores `agent:*`).
    /// Producción = external_agents.defaultRun (adaptador headless o ACP);
    /// tests inyectan uno (mismo patrón que test_llm_fn).
    external_run_fn: ?external_agents.RunFn = null,
    external_run_ctx: ?*anyopaque = null,
    /// D-C1 (E5.11): seam de la llamada LLM del modo agéntico por-tarea.
    /// Producción = LiveLlm.agenticFn (bucle de tools real); tests inyectan
    /// una sesión scriptada que fija `last_agentic_*` y escribe en el
    /// worktree — sin proveedor ni bucle de red.
    agentic_run_fn: ?AgenticRunFn = null,
    agentic_run_ctx: ?*anyopaque = null,
    /// E5.08: límites de reloj/turnos por tarea y por orden, configurables
    /// (por defecto 15 min y 40 turnos por tarea).
    external_limits: external_agents.Limits = .{},
    external_catalog_json: ?[]const u8 = null,
    /// E5.08: seam de detección de CLIs (versión vía `<exe> --version`).
    /// Producción = captura real de proceso; tests inyectan una.
    external_capture_fn: ?headless_adapter.CaptureFn = null,
    /// E5.08: seam de entorno para los avisos de facturación por API.
    external_getenv_fn: ?headless_adapter.GetEnvFn = null,

    composer_order_id: i64 = 0,

    pub fn init(allocator: std.mem.Allocator, runtime: db.Connection, router: ?*model_router.Router, memory: MemoryBackend, now: i64) Superagent {
        return .{ .allocator = allocator, .runtime = runtime, .router = router, .memory = memory, .now = now, .executor_spawn_fn = null, .order_origin = .local, .registry = null, .event_conn = null, .event_order_id = 0 };
    }

    /// C2: señal explícita y comprobable, a nivel del componente que gobierna la
    /// orden, de que el despacho en curso debe cancelarse. No-op si nadie inyectó
    /// un cancel_token (dispatch síncrono/de test sin cancelación habilitada).
    pub fn requestCancel(self: *Superagent) void {
        if (self.cancel_token) |token| {
            @constCast(token).cancel();
        }
    }

    /// Fija el modelo forzado por el usuario para esta orden (planificación + orquestación).
    /// Ambos deben tener contenido (len>0) para activarse; si alguno falta, sin efecto
    /// (assignModel sigue el ruteo free-first normal).
    /// El pin general cubre al ejecutor. El auditor conserva su pin explícito
    /// o se enruta automáticamente con exclusión del fabricante productor.
    pub fn setForcedModel(self: *Superagent, provider: ?[]const u8, model: ?[]const u8) void {
        if (provider) |p| {
            if (p.len > 0) {
                if (model) |m| {
                    if (m.len > 0) {
                        self.forced_provider = p;
                        self.forced_model = m;
                        return;
                    }
                }
            }
        }
        self.forced_provider = null;
        self.forced_model = null;
    }

    /// ROLES-MODELO: fija solo el pin del EJECUTOR sin tocar el del auditor.
    pub fn setExecForcedModel(self: *Superagent, provider: ?[]const u8, model: ?[]const u8) void {
        const audit_p = self.audit_forced_provider;
        const audit_m = self.audit_forced_model;
        self.setForcedModel(provider, model);
        self.audit_forced_provider = audit_p;
        self.audit_forced_model = audit_m;
    }

    /// ROLES-MODELO: fija solo el pin del AUDITOR. null/vacío lo limpia: las
    /// tareas `.auditar` vuelven al ruteo con exclusión del constructor.
    pub fn setAuditForcedModel(self: *Superagent, provider: ?[]const u8, model: ?[]const u8) void {
        if (provider) |p| {
            if (p.len > 0) {
                if (model) |m| {
                    if (m.len > 0) {
                        self.audit_forced_provider = p;
                        self.audit_forced_model = m;
                        return;
                    }
                }
            }
        }
        self.audit_forced_provider = null;
        self.audit_forced_model = null;
    }

    /// ENJAMBRE: fija el conjunto desde el JSON persistido por
    /// da_swarm_set_models_json (`[{provider,model}]`). JSON inválido deja el
    /// enjambre vacío — el caller decide si lo reporta (da_swarm_* valida en
    /// la frontera, así que aquí solo llega lo que ya pasó por ahí).
    /// Reemplazar el conjunto libera el anterior (deinitSwarm), así que en
    /// producción lo absorbe la arena y en tests no quedan fugas.
    pub fn setSwarmJson(self: *Superagent, json: ?[]const u8) void {
        self.deinitSwarm();
        const j = json orelse return;
        var parsed = std.json.parseFromSlice(std.json.Value, self.allocator, j, .{}) catch return;
        defer parsed.deinit();
        if (parsed.value != .array) return;
        var list = std.ArrayList(SwarmMember).empty;
        for (parsed.value.array.items) |item| {
            if (item != .object) continue;
            const pv = item.object.get("provider") orelse continue;
            const mv = item.object.get("model") orelse continue;
            if (pv != .string or mv != .string) continue;
            if (pv.string.len == 0 or mv.string.len == 0) continue;
            list.append(self.allocator, .{
                .provider = self.allocator.dupe(u8, pv.string) catch continue,
                .model = self.allocator.dupe(u8, mv.string) catch continue,
            }) catch continue;
            if (list.items.len >= 8) break; // tope duro: 8 miembros
        }
        // toOwnedSlice recorta la capacidad exacta para que free() sea válido
        // también fuera de arena (DebugAllocator exige el largo exacto).
        self.swarm = list.toOwnedSlice(self.allocator) catch list.items;
    }

    /// ENJAMBRE: libera los miembros del conjunto y lo deja vacío (Automático).
    /// Con allocator arena es prácticamente no-op (la arena libera en bloque);
    /// con un allocator real libera de verdad — los tests lo llaman en defer.
    pub fn deinitSwarm(self: *Superagent) void {
        for (self.swarm) |m| {
            self.allocator.free(m.provider);
            self.allocator.free(m.model);
        }
        if (self.swarm.len > 0) self.allocator.free(self.swarm);
        self.swarm = &.{};
    }

    /// ROLES-MODELO: pin efectivo por tipo de tarea. `auditar` usa el pin de
    /// auditor; todo lo demás (construir, corregir, probar) el del ejecutor.
    /// Un rol sin pin (provider/model null) se rutea normal.
    fn pinFor(self: *const Superagent, task_type: model_router.TaskType) struct { provider: ?[]const u8, model: ?[]const u8 } {
        if (task_type == .auditar)
            return .{ .provider = self.audit_forced_provider, .model = self.audit_forced_model };
        return .{ .provider = self.forced_provider, .model = self.forced_model };
    }

    /// F0: inyecta la conexión de runtime.db y la orden asociada para emitir
    /// eventos de ciclo de vida (order_running, task_started, task_done, etc.).
    pub fn setEventConn(self: *Superagent, conn: db.Connection, order_id: i64) void {
        self.event_conn = conn;
        self.event_order_id = order_id;
    }

    /// F0: registra un evento de timeline (best-effort). No propaga errores.
    /// TERMINAL-STATE-DESIGN-2026-07-12: ya NO deduplica eventos terminales por su
    /// cuenta (SELECT→INSERT no es atómico — dos hilos pueden pasar el SELECT antes
    /// de que cualquiera complete el INSERT). La autoridad terminal ahora es
    /// `db.Connection.tryCommitTerminal` + el índice único parcial de la migración
    /// #24; este método vuelve a ser un INSERT liso, igual para todo tipo de evento
    /// (incluye los repetibles como agent_message/progress/order_running, que nunca
    /// deben deduplicarse solo por kind).
    /// BUG-1 (2026-08-12): un evento perdido dejaba de ser invisible.
    ///
    /// La orden #237, lanzada desde la cabina, termino `done` con sus tres
    /// archivos escritos y emitio CERO eventos de tarea. El CLI, misma
    /// maquinaria, emitio 59. La causa estaba en la ultima linea de esta
    /// funcion: `_ = db.c.sqlite3_step(stmt)` — el resultado se TIRABA, asi que
    /// un `SQLITE_BUSY` (runtime.db va en `journal_mode = DELETE`, un solo
    /// escritor, y hay hasta tres conexiones escribiendo a la vez: hilo
    /// principal, hilo de despacho y la propia del planificador) hacia
    /// desaparecer el evento sin dejar rastro de que se habia perdido.
    ///
    /// Ahora se reintenta ante contencion y, si aun asi se pierde, se CUENTA.
    /// Un contador que nadie mira sigue siendo mejor que un silencio: lo lee
    /// `eventosPerdidos()` y lo publica el reporte de la orden.
    pub fn recordEvent(self: *const Superagent, kind: []const u8, payload: []const u8) void {
        const conn = self.event_conn orelse {
            self.notarEventoPerdido();
            return;
        };
        const stmt = conn.prepare("INSERT INTO events (ts, source, kind, payload_json, order_id) VALUES (?, ?, ?, ?, ?)") catch {
            self.notarEventoPerdido();
            return;
        };
        defer conn.finalize(stmt);
        db.bindInt(stmt, 1, health.nowMillis(conn)) catch return;
        db.bindText(stmt, 2, "superagente") catch return;
        db.bindText(stmt, 3, kind) catch return;
        db.bindText(stmt, 4, payload) catch return;
        db.bindInt(stmt, 5, self.event_order_id) catch return;

        // `busy_timeout` ya reintenta dentro de SQLite; esto cubre el caso en
        // que se agote. Tres intentos con reset entre medias: si la contencion
        // dura mas que eso, el evento se pierde pero QUEDA CONTADO.
        var intento: usize = 0;
        while (intento < 3) : (intento += 1) {
            const rc = db.c.sqlite3_step(stmt);
            if (rc == db.c.SQLITE_DONE) return;
            if (rc != db.c.SQLITE_BUSY and rc != db.c.SQLITE_LOCKED) break;
            _ = db.c.sqlite3_reset(stmt);
        }
        self.notarEventoPerdido();
    }

    /// T8: evento con la orden explícita. processOrder escribe antes de que
    /// nadie llame a setEventConn (la fila acaba de nacer), igual que
    /// `order_plan_mode_v1`; mismo contador de perdidos que recordEvent.
    fn recordOrderEvent(self: *const Superagent, order_id: i64, kind: []const u8, payload: []const u8) void {
        const conn = self.event_conn orelse self.runtime;
        const stmt = conn.prepare("INSERT INTO events (ts, source, kind, payload_json, order_id) VALUES (?, 'superagente', ?, ?, ?)") catch {
            self.notarEventoPerdido();
            return;
        };
        defer conn.finalize(stmt);
        db.bindInt(stmt, 1, health.nowMillis(conn)) catch return self.notarEventoPerdido();
        db.bindText(stmt, 2, kind) catch return self.notarEventoPerdido();
        db.bindText(stmt, 3, payload) catch return self.notarEventoPerdido();
        db.bindInt(stmt, 4, order_id) catch return self.notarEventoPerdido();
        if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE) self.notarEventoPerdido();
    }

    /// T8: ids de las tareas que corren con el modelo del rol `sidekick`.
    fn collectSidekickTasks(self: *Superagent, router: *model_router.Router, outcome: *const OrderOutcome, out: *std.ArrayList([]const u8)) !void {
        const roles_json = try composer_roles.forOrder(self.allocator, self.runtime, router.catalog, outcome.order_id);
        defer self.allocator.free(roles_json);
        const roles = try std.json.parseFromSlice([]composer_roles.Pin, self.allocator, roles_json, .{});
        defer roles.deinit();
        for (roles.value) |pin| {
            if (!std.mem.eql(u8, pin.role, "sidekick")) continue;
            for (outcome.plan.tasks) |pt| {
                switch (pt.task_type) {
                    .investigar, .resumir, .documentar => {},
                    else => continue,
                }
                const a = findAssignment(outcome.assignments, pt.id) orelse continue;
                if (a.assigned and std.mem.eql(u8, a.provider_name, pin.provider) and std.mem.eql(u8, a.model_name, pin.model))
                    try out.append(self.allocator, pt.id);
            }
        }
    }

    /// T8: plan más reciente de la orden (el que un replan va a reemplazar).
    fn latestPlanId(self: *const Superagent, order_id: i64) ?i64 {
        const stmt = self.runtime.prepare("SELECT MAX(id) FROM plans WHERE order_id = ?") catch return null;
        defer self.runtime.finalize(stmt);
        db.bindInt(stmt, 1, order_id) catch return null;
        if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return null;
        if (db.c.sqlite3_column_type(stmt, 0) == db.c.SQLITE_NULL) return null;
        return db.c.sqlite3_column_int64(stmt, 0);
    }

    /// T8: `replan_v1` {reason, from_plan_id, to_plan_id, same_row, tasks,
    /// changes ≤512 bytes}. `changes` es lo que pidió el usuario o el objetivo
    /// de seguimiento del evaluador; se corta sin partir un carácter.
    fn recordReplan(self: *const Superagent, order_id: i64, reason: []const u8, from_plan_id: ?i64, to_plan_id: i64, same_row: bool, changes: []const u8, tasks: usize) void {
        const payload = std.json.Stringify.valueAlloc(self.allocator, .{
            .reason = reason,
            .from_plan_id = from_plan_id,
            .to_plan_id = to_plan_id,
            .same_row = same_row,
            .tasks = tasks,
            .changes = utf8PrefixWithin(std.mem.trim(u8, changes, " \t\r\n"), 512),
        }, .{}) catch return self.notarEventoPerdido();
        defer self.allocator.free(payload);
        self.recordOrderEvent(order_id, "replan_v1", payload);
    }

    /// T8: `swarm_group_v1` {wave, members:[task_id…], parallel}. Los miembros
    /// se acotan a 32 ids (cada uno a 64 bytes): el grafo no necesita más y el
    /// evento no crece con un plan enorme.
    fn recordSwarmGroup(self: *const Superagent, wave: usize, members: []const planner.PlannedTask, parallel: bool) void {
        var out: std.Io.Writer.Allocating = .init(self.allocator);
        defer out.deinit();
        var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
        js.beginObject() catch return;
        js.objectField("wave") catch return;
        js.write(wave) catch return;
        js.objectField("members") catch return;
        js.beginArray() catch return;
        for (members[0..@min(members.len, 32)]) |m| js.write(utf8PrefixWithin(m.id, 64)) catch return;
        js.endArray() catch return;
        js.objectField("size") catch return;
        js.write(members.len) catch return;
        js.objectField("parallel") catch return;
        js.write(parallel) catch return;
        js.endObject() catch return;
        self.recordEvent("swarm_group_v1", out.written());
    }

    fn notarEventoPerdido(self: *const Superagent) void {
        // `*const Superagent` en toda la ruta de emision: el contador es
        // atomico para no exigir mutabilidad ni cerrojo.
        _ = @constCast(self).eventos_perdidos.fetchAdd(1, .monotonic);
    }

    /// CHECKPOINT-T2: persiste el estado de UNA tarea en cuanto cambia — es lo
    /// que permite a la reanudación saber qué quedó hecho cuando el proceso
    /// muere a mitad de orden. La clave es el contrato (contracts.name ==
    /// task_id): la descripción no identifica a la tarea (dos pueden llevar el
    /// mismo texto). Best-effort como recordEvent: un fallo no detiene la
    /// orden; la escritura final de cada tarea se rehace al cerrar el despacho.
    fn persistTaskCheckpoint(self: *const Superagent, plan_id: i64, task_id: []const u8, status: []const u8) void {
        const conn = self.event_conn orelse self.runtime;
        const stmt = conn.prepare(
            \\UPDATE tasks SET status = ?
            \\WHERE plan_id = ? AND contract_id IN (SELECT id FROM contracts WHERE plan_id = ? AND name = ?)
        ) catch return;
        defer conn.finalize(stmt);
        db.bindText(stmt, 1, status) catch return;
        db.bindInt(stmt, 2, plan_id) catch return;
        db.bindInt(stmt, 3, plan_id) catch return;
        db.bindText(stmt, 4, task_id) catch return;
        var intento: usize = 0;
        while (intento < 3) : (intento += 1) {
            const rc = db.c.sqlite3_step(stmt);
            if (rc == db.c.SQLITE_DONE) return;
            if (rc != db.c.SQLITE_BUSY and rc != db.c.SQLITE_LOCKED) break;
            _ = db.c.sqlite3_reset(stmt);
        }
    }

    /// / E-GOV.1: procedencia del artefacto para la reanudación.
    /// Guarda solo rutas, presencia y huellas de marcadores — nunca el fuente.
    const CheckpointProvenanceArtifact = struct {
        path: []const u8,
        content: []const u8,
        inherited_placeholders: ?[]const artifact_quality.LineHash = null,
    };
    const CheckpointProvenance = struct {
        version: u8,
        root: []const u8,
        artifacts: []const CheckpointProvenanceArtifact,
    };

    fn persistArtifactProvenance(self: *Superagent, plan_id: i64, result: TaskRunResult) !void {
        // Una reanudación no debe reemplazar el origen heredado por el archivo de hoy.
        if (result.restored) return;
        const root = result.worktree_root orelse return;
        const metadata = try self.allocator.alloc(CheckpointProvenanceArtifact, result.artifacts.len);
        defer self.allocator.free(metadata);
        for (result.artifacts, 0..) |artifact, i| metadata[i] = .{
            .path = artifact.path,
            .content = if (artifact.content.len == 0) "" else "present",
            .inherited_placeholders = artifact.inherited_placeholders,
        };
        const json = try std.json.Stringify.valueAlloc(self.allocator, CheckpointProvenance{ .version = 1, .root = root, .artifacts = metadata }, .{});
        defer self.allocator.free(json);
        const conn = self.event_conn orelse self.runtime;
        const stmt = try conn.prepare(
            \\UPDATE tasks SET artifact_provenance = ?
            \\WHERE plan_id = ? AND contract_id IN (SELECT id FROM contracts WHERE plan_id = ? AND name = ?)
        );
        defer conn.finalize(stmt);
        try db.bindText(stmt, 1, json);
        try db.bindInt(stmt, 2, plan_id);
        try db.bindInt(stmt, 3, plan_id);
        try db.bindText(stmt, 4, result.task_id);
        if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE) return error.CheckpointProvenanceWriteFailed;
    }

    fn restoreArtifactProvenance(self: *Superagent, plan_id: i64, result: *TaskRunResult) !void {
        const conn = self.event_conn orelse self.runtime;
        const stmt = try conn.prepare(
            \\SELECT artifact_provenance FROM tasks
            \\WHERE plan_id = ? AND contract_id IN (SELECT id FROM contracts WHERE plan_id = ? AND name = ?)
        );
        defer conn.finalize(stmt);
        try db.bindInt(stmt, 1, plan_id);
        try db.bindInt(stmt, 2, plan_id);
        try db.bindText(stmt, 3, result.task_id);
        const rc = db.c.sqlite3_step(stmt);
        if (rc == db.c.SQLITE_DONE) return; // Tarea legacy: gate estricto.
        if (rc != db.c.SQLITE_ROW) return error.CheckpointProvenanceReadFailed;
        const raw = db.c.sqlite3_column_text(stmt, 0) orelse return;
        const parsed = try std.json.parseFromSlice(CheckpointProvenance, self.allocator, std.mem.span(raw), .{});
        defer parsed.deinit();
        if (parsed.value.version != 1 or !std.fs.path.isAbsolute(parsed.value.root)) return error.CheckpointProvenanceInvalid;
        // La raíz persistida debe seguir dentro del espacio efectivo actual:
        // una base manipulada no puede redirigir la procedencia fuera del espacio.
        var space_buf: [4096]u8 = undefined;
        const space = try std.fs.path.resolve(self.allocator, &.{workspace.effectiveRoot(&space_buf)});
        defer self.allocator.free(space);
        const candidate = try std.fs.path.resolve(self.allocator, &.{parsed.value.root});
        defer self.allocator.free(candidate);
        const within = try std.fs.path.relative(self.allocator, space, null, space, candidate);
        defer self.allocator.free(within);
        if (std.fs.path.isAbsolute(within) or std.mem.eql(u8, within, "..") or std.mem.startsWith(u8, within, ".." ++ std.fs.path.sep_str)) return error.CheckpointProvenanceRootMismatch;
        var sb = try sandbox.Sandbox.init(self.allocator, candidate);
        defer sb.deinit();
        for (parsed.value.artifacts) |artifact| {
            if (!sb.isAllowed(artifact.path) or (artifact.content.len != 0 and !std.mem.eql(u8, artifact.content, "present"))) return error.CheckpointProvenanceInvalid;
        }
        // Bind metadata to THIS order's checkpoint before accepting any artifact.
        const saved = result.saved_path orelse return;
        if (!std.fs.path.isAbsolute(saved)) return error.CheckpointProvenanceRootMismatch;
        var matched = false;
        var any_present = false;
        const artifacts = try self.allocator.alloc(worker_backend.Artifact, parsed.value.artifacts.len);
        var built: usize = 0;
        errdefer {
            for (artifacts[0..built]) |*art| art.deinit(self.allocator);
            self.allocator.free(artifacts);
        }
        for (parsed.value.artifacts, 0..) |artifact, i| {
            const path = try self.allocator.dupe(u8, artifact.path);
            errdefer self.allocator.free(path);
            const content = try self.allocator.dupe(u8, artifact.content);
            errdefer self.allocator.free(content);
            const inherited = if (artifact.inherited_placeholders) |lines| try self.allocator.dupe(artifact_quality.LineHash, lines) else null;
            errdefer if (inherited) |lines| self.allocator.free(lines);
            if (artifact.content.len != 0) {
                any_present = true;
                const real = try std.fs.path.resolve(self.allocator, &.{ candidate, artifact.path });
                defer self.allocator.free(real);
                if (@import("platform.zig").pathEqual(real, saved)) matched = true;
            }
            artifacts[i] = .{ .path = path, .content = content, .inherited_placeholders = inherited };
            built = i + 1;
        }
        if (!any_present) matched = true;
        if (!matched) return error.CheckpointProvenanceRootMismatch;
        const root = try self.allocator.dupe(u8, candidate);
        errdefer self.allocator.free(root);
        const saved_copy = try self.allocator.dupe(u8, saved);
        errdefer self.allocator.free(saved_copy);
        if (result.saved_path) |old| self.allocator.free(old);
        result.saved_path = saved_copy;
        result.worktree_root = root;
        result.artifacts = artifacts;
    }

    /// Cuantos eventos no llegaron a la base en esta orden. Cero es lo normal;
    /// cualquier otra cosa significa que la traza que ve el usuario esta
    /// incompleta y NO debe leerse como «no paso nada».
    pub fn eventosPerdidos(self: *const Superagent) usize {
        return self.eventos_perdidos.load(.monotonic);
    }

    /// TERMINAL-STATE-DESIGN-2026-07-12: transición terminal atómica (UPDATE+INSERT
    /// en una sola transacción vía db.Connection.tryCommitTerminal). Reemplaza el
    /// par updateOrderStatus(done/failed)+recordEvent(order_done/order_failed) en
    /// los call-sites reales de despacho. Propaga errores genuinos de DB (igual que
    /// updateOrderStatus ya hacía vía `try`); el resultado `false` (alguien más ganó
    /// la carrera) NO es un error — el llamador debe reflejar en memoria solo si
    /// esto devuelve `true`.
    fn commitTerminal(self: *Superagent, order_id: i64, status: OrderStatus, event_kind: []const u8, payload: []const u8) !bool {
        return self.runtime.tryCommitTerminal(order_id, status.toText(), event_kind, "superagente", payload, health.nowMillis(self.runtime));
    }

    pub const DelegationTally = struct { count: i64 = 0, integrated: i64 = 0, unaudited: i64 = 0 };

    /// Remate D1: lo que `delegate_tasks` dejó en el ledger de esta vuelta
    /// (`delegation_finished_v1` por llamada y `delegation_subtask_finished_v1`
    /// por subtarea). Sin delegación, todo a cero. Un fallo de lectura se
    /// propaga: cerrar «hecha» sin poder comprobarlo sería mentir.
    /// FASE0-B2: un reintento de auditoría (`delegation_audit_retry_v1`, solo
    /// de hijas que seguían sin auditar) suma lo que integró y resta las que
    /// dejaron de estar sin auditar.
    pub fn delegationTally(self: *Superagent, order_id: i64) !DelegationTally {
        const stmt = try self.runtime.prepare(
            "SELECT COALESCE(SUM(CASE WHEN kind = 'delegation_finished_v1' THEN json_extract(payload_json, '$.count') END), 0), " ++
                "COALESCE(SUM(CASE WHEN kind = 'delegation_finished_v1' THEN json_extract(payload_json, '$.integrated') END), 0) + " ++
                "COALESCE(SUM(CASE WHEN kind = 'delegation_audit_retry_v1' AND json_extract(payload_json, '$.integrated') = 1 THEN 1 END), 0), " ++
                "COALESCE(SUM(CASE WHEN kind = 'delegation_subtask_finished_v1' AND json_extract(payload_json, '$.unaudited') = 1 THEN 1 END), 0) - " ++
                "COALESCE(SUM(CASE WHEN kind = 'delegation_audit_retry_v1' AND json_extract(payload_json, '$.resolved') = 1 THEN 1 END), 0) " ++
                "FROM events WHERE order_id = ? AND kind IN ('delegation_finished_v1', 'delegation_subtask_finished_v1', 'delegation_audit_retry_v1')",
        );
        defer self.runtime.finalize(stmt);
        try db.bindInt(stmt, 1, order_id);
        if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return error.StepFailed;
        return .{
            .count = db.c.sqlite3_column_int64(stmt, 0),
            .integrated = db.c.sqlite3_column_int64(stmt, 1),
            .unaudited = db.c.sqlite3_column_int64(stmt, 2),
        };
    }

    /// Procesa una orden: persiste, planifica, clarifica o asigna modelos.
    /// `inventory`/`discovery` opcionales: si se aportan, se incorpora la selección de herramientas.
    pub fn processOrder(
        self: *Superagent,
        project_id: []const u8,
        order_text: []const u8,
        answers: []const planner.ClarificationAnswer,
        backend: planner.PlannerBackend,
        discovery: ?tool_discovery.DiscoveryBackend,
        inventory: ?*const tool_discovery.Inventory,
    ) anyerror!OrderOutcome {
        // Memoria de proyecto (MEM-02): cargar, truncar a ~4KB, y pasar al planner.
        var memory_context: ?[]const u8 = null;
        if (self.memory.loadContext(self.allocator, project_id)) |ctx| {
            memory_context = try planner.dupeTruncated(self.allocator, ctx, 4096);
            self.allocator.free(ctx);
        }
        errdefer if (memory_context) |m| self.allocator.free(m);

        // T8: qué lecciones se consultaron, para el nodo Memoria
        // del grafo. Se arma aquí y se escribe en cuanto existe la fila de la
        // orden (abajo); sin backend que devuelva lecciones no hay evento.
        var lessons_event: ?[]u8 = null;
        defer if (lessons_event) |e| self.allocator.free(e);
        // P10-T2: Inyectar las 3 lecciones más relevantes al contexto del planner.
        if (self.memory.loadLessons(self.allocator, project_id, 3)) |lessons| {
            defer self.allocator.free(lessons);
            lessons_event = memoryLessonsPayload(self.allocator, lessons) catch blk: {
                self.notarEventoPerdido();
                break :blk null;
            };
            // Combinar memoria + lecciones en un solo contexto.
            const combined = std.fmt.allocPrint(self.allocator, "{s}\n\n[LECCIONES APRENDIDAS]\n{s}", .{ memory_context orelse "", lessons }) catch null;
            if (combined) |c| {
                if (memory_context) |m| self.allocator.free(m);
                memory_context = null;
                memory_context = try planner.dupeTruncated(self.allocator, c, 4096);
                self.allocator.free(c);
            }
        }

        const order_id = if (self.reuse_order_id) |rid| blk: {
            try self.updateOrderStatus(rid, OrderStatus.pending.toText());
            break :blk rid;
        } else try self.insertOrder(project_id, order_text, OrderStatus.pending.toText());
        // Cualquier fallo posterior al INSERT debe dejar la sesión en estado terminal.
        // Antes solo se cubría el fallo del planner; si discovery/asignación fallaba,
        // la orden quedaba persistida como pending y la UI mostraba estado obsoleto.
        errdefer |failure| {
            const detail = std.json.Stringify.valueAlloc(self.allocator, .{ .cause = "order_error", .reason = @errorName(failure) }, .{}) catch null;
            defer if (detail) |text| self.allocator.free(text);
            _ = self.commitTerminal(order_id, .failed, "order_failed", detail orelse "{\"cause\":\"order_error\",\"reason\":\"No se pudo preparar la orden\"}") catch |e| blk: {
                std.debug.print("order terminal persistence failed: {s}\n", .{@errorName(e)});
                break :blk false;
            };
        }

        if (lessons_event) |payload| self.recordOrderEvent(order_id, "memory_lessons_v1", payload);

        if (self.router) |router| {
            const captured_roles = try composer_roles.forOrder(self.allocator, self.runtime, router.catalog, order_id);
            self.allocator.free(captured_roles);
            _ = try composer_roles.swarmForOrder(self.runtime, router.catalog, order_id);
        }

        // Persistencia aditiva en la traza existente: también se restaura tras reiniciar.
        const mode_stmt = try self.runtime.prepare("INSERT INTO events(order_id,kind,payload_json,ts,source) VALUES (?,'order_plan_mode_v1',?,?, 'superagente')");
        defer self.runtime.finalize(mode_stmt);
        try db.bindInt(mode_stmt, 1, order_id);
        try db.bindText(mode_stmt, 2, if (self.wait_for_plan_approval) "{\"wait_for_plan_approval\":true}" else "{\"wait_for_plan_approval\":false}");
        try db.bindInt(mode_stmt, 3, health.nowMillis(self.runtime));
        if (db.c.sqlite3_step(mode_stmt) != db.c.SQLITE_DONE) return error.ExecFailed;

        // memory_context NO se libera aquí: el errdefer de arriba ya lo hace al
        // propagar `e` (liberarlo también en el catch era un double-free real —
        // el primer error de planner que llegó hasta aquí, ClarifyRoundsExhausted,
        // lo cazó en la suite).
        var plan = backend.plan(self.allocator, order_text, answers, memory_context) catch |e| {
            const payload = try std.json.Stringify.valueAlloc(self.allocator, .{ .cause = "planner_error", .reason = @errorName(e) }, .{});
            defer self.allocator.free(payload);
            _ = try self.commitTerminal(order_id, .failed, "order_failed", payload);
            return @as(anyerror!OrderOutcome, e);
        };
        // 10-nov: se anula al liberarlo. El errdefer de arriba sigue vivo hasta
        // el final de la función y, con el puntero aún puesto, cualquier error
        // posterior al plan lo liberaba otra vez: la cabina se cerraba de golpe
        // (orden 933, Directo con Cohere, violación de acceso en memset).
        if (memory_context) |m| self.allocator.free(m);
        memory_context = null;
        errdefer plan.deinit();

        // Clarificación pendiente: no se genera grafo ni se persiste plan.
        if (plan.needsClarification()) {
            try self.updateOrderStatus(order_id, OrderStatus.clarifying.toText());
            return .{
                .allocator = self.allocator,
                .order_id = order_id,
                .plan_id = null,
                .status = .clarifying,
                .wait_for_plan_approval = self.wait_for_plan_approval,
                .plan = plan,
                .assignments = try self.allocator.alloc(ModelAssignment, 0),
                .discovery_needed = try self.allocator.alloc([]const u8, 0),
                .discovery_missing = try self.allocator.alloc([]const u8, 0),
                .discovery_needed_resources = try self.allocator.alloc(tool_discovery.Resource, 0),
            };
        }

        try expandExplicitMultiFilePlan(self.allocator, &plan, order_text);
        // H3: encadena tambien cuando el plan ya venia con varios productores,
        // que es como llego el de la orden 437.
        try chainSiblingProducers(self.allocator, &plan);
        // una orden que se declara auditoría termina en una tarea
        // `auditar`. Queda en la traza para que se vea que la puso el motor.
        if (esOrdenDeAuditoria(order_text)) {
            if (try aseguraAuditoriaTerminal(&plan)) |nueva| {
                var ev: std.Io.Writer.Allocating = .init(self.allocator);
                defer ev.deinit();
                var ejs: std.json.Stringify = .{ .writer = &ev.writer, .options = .{} };
                ejs.beginObject() catch {};
                ejs.objectField("task_id") catch {};
                ejs.write(nueva) catch {};
                ejs.objectField("depends_on") catch {};
                ejs.write(plan.tasks[plan.tasks.len - 1].depends_on) catch {};
                ejs.objectField("reason") catch {};
                ejs.write("la orden declara una auditoria y el plan no traia ninguna tarea auditar") catch {};
                ejs.endObject() catch {};
                self.recordEvent("plan_audit_enforced_v1", ev.written());
            }
        }

        // Descubrimiento de herramientas (spec 010): needed[] / missing[].
        var needed = try self.allocator.alloc([]const u8, 0);
        errdefer freeStrings(self.allocator, needed);
        var missing = try self.allocator.alloc([]const u8, 0);
        errdefer freeStrings(self.allocator, missing);
        var needed_resources = try self.allocator.alloc(tool_discovery.Resource, 0);
        errdefer freeResources(self.allocator, needed_resources);
        if (discovery != null and inventory != null) {
            var sel = try discovery.?.select(self.allocator, order_text, inventory.?);
            defer sel.deinit(self.allocator);
            self.allocator.free(needed);
            needed = try dupeNames(self.allocator, sel.needed);
            self.allocator.free(missing);
            missing = try dupeStringList(self.allocator, sel.missing);
            self.allocator.free(needed_resources);
            needed_resources = try dupeResources(self.allocator, sel.needed);
        }

        // FIX-4b / XFILE-03: normalizar el plan (coherencia dept↔tipo) ANTES de rutear,
        // para que el router asigne el mejor modelo por tarea (diversidad multi-modelo).
        normalizePlan(plan.tasks);

        // E5.17: descomposición paralela determinista — pasada del motor entre
        // el plan analizado y el cálculo de olas. Las hermanas nuevas quedan
        // persistidas y ruteadas como cualquier otra (van antes de
        // insertPlan/assignAndPersist). El repo-map solo se carga cuando hay
        // candidata real (guardia de imports mutuos, regla d).
        {
            var fb_map: ?*repo_map.RepoMap = null;
            var fb_threaded: ?std.Io.Threaded = null;
            defer {
                if (fb_map) |m| m.deinit();
                if (fb_threaded) |*t| t.deinit();
            }
            if (plan_fanout.needsRepoMap(plan.tasks)) {
                fb_threaded = std.Io.Threaded.init(self.allocator, .{});
                var fb_root_buf: [4096]u8 = undefined;
                const fb_root = workspace.effectiveRoot(&fb_root_buf);
                fb_map = repo_map.buildOrLoad(self.allocator, fb_threaded.?.io(), fb_root, .{}, self.runtime) catch null;
            }
            if (try plan_fanout.apply(&plan, .{ .map = fb_map })) |rep| {
                var rep_mut = rep;
                defer rep_mut.deinit(self.allocator);
                var ev: std.Io.Writer.Allocating = .init(self.allocator);
                defer ev.deinit();
                var ejs: std.json.Stringify = .{ .writer = &ev.writer, .options = .{} };
                ejs.beginObject() catch {};
                ejs.objectField("antes") catch {};
                ejs.write(rep.antes) catch {};
                ejs.objectField("despues") catch {};
                ejs.write(rep.despues) catch {};
                ejs.objectField("reglas") catch {};
                ejs.write(rep.reglas) catch {};
                ejs.endObject() catch {};
                self.recordEvent("plan_fanout_applied", ev.written());
            }
        }

        // C-11/E4.23: plan sin tareas tras el chequeo de clarificación. El
        // discriminador es plan.kind, no el vacío: `chat` = respuesta
        // conversacional deliberada → `done` con el reply persistido (62% de
        // las órdenes planned de la muestra eran chat ya respondido). Cualquier
        // otro kind con 0 tareas = el planificador no produjo nada para una
        // orden de trabajo → `failed` honesto, nunca `done` ni `planned`
        // eterno (antes moría en dispatch como no_tasks_in_plan; se cierra
        // aquí, en el punto donde se sabe que no hay nada que ejecutar).
        if (plan.tasks.len == 0) {
            const empty_plan_id = try self.insertPlan(order_id, plan.understanding, answers);
            var chat_status: OrderStatus = .done;
            if (plan.kind == .chat) {
                // Remate D1 (10-nov): una vuelta de «DevAgents» que delegó y
                // no integró todas sus subtareas no es un trabajo hecho. Se
                // cierra con el estado que ya existe para cada caso: «sin
                // auditar» (P0.1: entrega bloqueada) si alguna quedó sin
                // auditar, `failed` si no se integró ninguna, y `done` con el
                // recuento si se integró una parte.
                const tally = try self.delegationTally(order_id);
                if (tally.count > 0 and tally.integrated < tally.count) {
                    const resumen = try std.fmt.allocPrint(self.allocator, "{d} de {d} subtareas integradas", .{ tally.integrated, tally.count });
                    defer self.allocator.free(resumen);
                    const body = try std.json.Stringify.valueAlloc(self.allocator, .{
                        .cause = "delegation_not_integrated",
                        .reason = resumen,
                        .integrated = tally.integrated,
                        .count = tally.count,
                        .unaudited = tally.unaudited,
                        .tasks = 0,
                    }, .{});
                    defer self.allocator.free(body);
                    if (tally.unaudited > 0) {
                        chat_status = .audit_unavailable;
                        _ = try self.commitTerminal(order_id, .audit_unavailable, "order_audit_unavailable_v1", body);
                    } else if (tally.integrated == 0) {
                        chat_status = .failed;
                        _ = try self.commitTerminal(order_id, .failed, "order_failed", body);
                    } else {
                        _ = try self.commitTerminal(order_id, .done, "order_done", body);
                    }
                } else {
                    _ = try self.commitTerminal(order_id, .done, "order_done", "{\"cause\":\"plan_conversacional\",\"tasks\":0}");
                }
            } else {
                const failure = try std.json.Stringify.valueAlloc(self.allocator, .{ .cause = if (plan.failure_cause == .paid_budget_exhausted) "paid_budget_exhausted" else if (plan.kind == .failed) "planner_failed" else "planner_empty_plan", .reason = plan.understanding, .tasks = 0 }, .{});
                defer self.allocator.free(failure);
                _ = try self.commitTerminal(order_id, .failed, "order_failed", failure);
            }
            return .{
                .allocator = self.allocator,
                .order_id = order_id,
                .plan_id = empty_plan_id,
                .status = if (plan.kind == .chat) chat_status else .failed,
                .wait_for_plan_approval = self.wait_for_plan_approval,
                .plan = plan,
                .assignments = try self.allocator.alloc(ModelAssignment, 0),
                .discovery_needed = needed,
                .discovery_missing = missing,
                .discovery_needed_resources = needed_resources,
            };
        }

        // Las imágenes pertenecen a la orden y nunca se eliminan al planificar.
        if (try order_attachments.hasImages(self.runtime, order_id)) {
            for (plan.tasks) |*task| task.needs_vision = true;
        }
        try self.ensureComposerAudits(&plan, order_id);
        // T8: el plan que se reemplaza (si lo hay) se lee antes de insertar.
        const replaced_plan: ?i64 = if (self.replan_changes != null) self.latestPlanId(order_id) else null;
        // Persistir plan y tareas + contratos; asignar modelo a cada tarea.
        const plan_id = try self.insertPlan(order_id, plan.understanding, answers);
        if (self.replan_changes) |changes| self.recordReplan(order_id, "user_changes", replaced_plan, plan_id, self.reuse_order_id != null, changes, plan.tasks.len);
        const assignments = try self.assignAndPersist(plan_id, plan.tasks);
        errdefer {
            for (assignments) |a| a.deinit(self.allocator);
            self.allocator.free(assignments);
        }

        try self.updateOrderStatus(order_id, OrderStatus.planned.toText());
        return .{
            .allocator = self.allocator,
            .order_id = order_id,
            .plan_id = plan_id,
            .status = .planned,
            .wait_for_plan_approval = self.wait_for_plan_approval,
            .plan = plan,
            .assignments = assignments,
            .discovery_needed = needed,
            .discovery_missing = missing,
            .discovery_needed_resources = needed_resources,
        };
    }

    const MAX_AUDIT_CYCLES = 2;

    /// BGATE-1: presupuesto de la comprobación en navegador. Suficiente para
    /// cargar una página local y pulsar sus controles; corto para que un
    /// entregable que cuelga el navegador no se lleve por delante la orden.
    const BROWSER_GATE_TIMEOUT_MS: u32 = 20_000;

    /// Resultado de la ejecución gobernada de un artefacto.
    const ExecOutcome = struct {
        ran: bool,
        exit_code: i32,
        needs_approval: bool,
        stderr: []const u8,
        /// Solo governedExecuteRaw la llena: permite enlazar la evidencia de
        /// testing con la salida exacta, sin reconstruirla desde eventos.
        stdout: ?[]const u8 = null,
        /// EXEC-SHOW: el proceso corrió y se mostró su salida, pero no terminó dentro del
        /// timeout (reloj/servidor continuo). NO es un fallo de auditoría por exit!=0.
        timed_out: bool = false,
        /// la ejecución terminó con exit != 0 pero su salida es solo
        /// un mensaje de uso (el motor la lanzó SIN argumentos): no es un
        /// veredicto sobre el artefacto. taskExecutionSucceeded y los criterios
        /// de exit del auto-auditor la tratan como no-comprobable, no como fallo.
        usage_only: bool = false,
    };

    /// Resultado intermedio de una tarea tras ejecución en paralelo.
    const TaskRunResult = struct {
        task_id: []const u8,
        artifacts: []const worker_backend.Artifact,
        success: bool,
        error_msg: []const u8,
        paid_budget_exhausted: bool = false,
        integrated: bool,
        model_used: []const u8,
        exec: ExecOutcome,
        saved_path: ?[]const u8,
        /// Una tarea de testing solo prueba la revisión exacta del productor que
        /// estaba materializada cuando ejecutó su comando.  No se acepta un PASS
        /// narrativo como sustituto de esta referencia ejecutable.
        tested_producer_id: ?[]const u8 = null,
        tested_producer_revision: u64 = 0,
        test_command: ?[]const u8 = null,
        /// CHECKPOINT-T2: resultado rehidratado desde el checkpoint persistido
        /// de una orden interrumpida — NO corrió en este proceso. La evidencia
        /// en memoria (exit codes, comandos de test) no existe; la auditoría
        /// final solo puede re-verificar lo que sobrevivió en disco.
        restored: bool = false,
        /// AUDIT-UNAVAILABLE-P0: veredicto estricto de una tarea `auditar`
        /// (`.none` para el resto de tipos). Lo fija runTaskInWave a partir de
        /// los artefactos y errores REALES del worker — nunca de una cadena
        /// genérica. `.unavailable` = el auditor no produjo veredicto usable:
        /// no es un PASS implícito ni un FAIL del producto.
        audit_verdict: AuditVerdict = .none,
        /// E5.09: si el productor corrió en un worktree (agente externo), su
        /// raíz real — los saved_path de esta tarea son `<root>/<rel>` y los
        /// consumidores (test cwd, gate semántico) resuelven contra ella.
        worktree_root: ?[]const u8 = null,
        /// D-C1 (E5.11): la sesión agéntica terminó sin `finish` — la tarea
        /// es INCOMPLETE, un estado distinto de un fallo de proveedor o de
        /// contrato: el modelo trabajó pero no cerró su entrega.
        incomplete: bool = false,
    };

    fn deinitTaskRunResult(allocator: std.mem.Allocator, result: TaskRunResult) void {
        allocator.free(result.task_id);
        freeOwnedArtifacts(allocator, result.artifacts);
        allocator.free(result.error_msg);
        allocator.free(result.model_used);
        allocator.free(result.exec.stderr);
        if (result.exec.stdout) |stdout| allocator.free(stdout);
        if (result.saved_path) |path| allocator.free(path);
        if (result.tested_producer_id) |id| allocator.free(id);
        if (result.test_command) |command| allocator.free(command);
        if (result.worktree_root) |wr| allocator.free(wr);
    }

    /// r2: candidato elegido para re-despachar una tarea en el ciclo
    /// de corrección. `is_free` habilita la política de gasto del reintento por
    /// `worker_failed` (solo gratis, salvo pin manual).
    const CorrectionChoice = struct {
        provider_name: []const u8,
        model_name: []const u8,
        is_free: bool,
    };

    /// r2 (P1): ¿`name` forma parte del tramo de la cadena
    /// (primario + respaldos) YA PROBADO por el despacho original, hasta
    /// `used_model` inclusive? Evita que la corrección vuelva a elegir un
    /// candidato que el despacho original ya intentó.
    fn chainModelAlreadyTried(a: ModelAssignment, name: []const u8, used_model: []const u8) bool {
        if (std.mem.eql(u8, name, a.model_name)) return true;
        for (a.fallbacks) |fb| {
            if (std.mem.eql(u8, fb.model_name, name)) return true;
            if (std.mem.eql(u8, fb.model_name, used_model)) break;
        }
        return false;
    }

    /// r2 (P1): política de gasto del reintento por `worker_failed`.
    /// Un candidato GRATUITO siempre se permite; uno de pago solo bajo un pin
    /// manual de proveedor/modelo (el pin manda y no rota).
    fn workerRetryAllowed(is_free: bool, pinned_manual: bool) bool {
        return pinned_manual or is_free;
    }

    /// r2 (P1): (tarea, modelo) ya despachado como corrección en esta
    /// orden. El bucle de auditoría acumula estas entradas entre ciclos: si una
    /// corrección falla sin artefacto, `res.model_used` NO avanza (solo se
    /// actualiza en la corrección exitosa), así que sin este registro el ciclo
    /// siguiente de MAX_AUDIT_CYCLES volvía a elegir el mismo candidato. Posesivo
    /// (dupes propios): el modelo registrado puede vivir en `res.model_used`,
    /// que la corrección exitosa libera y reemplaza.
    const CorrectionAttempt = struct {
        task_id: []const u8,
        model_name: []const u8,
    };

    /// r3 (P1): cuando la cadena de corrección agotó todos sus
    /// candidatos, la selección devuelve «sin candidato» y la tarea queda
    /// fallida con esta causa visible en `order_failed.reason`. Repetir el
    /// modelo que ya falló no es un reintento: puede volver a gastar cuota y
    /// a producir el mismo fallo.
    const correction_chain_exhausted_note = "cadena de modelos agotada: no queda un candidato sin probar y no se repite un modelo ya intentado";

    fn markCorrectionHandoffFailure(self: *Superagent, result: *TaskRunResult, provider: []const u8, model: []const u8, reason_name: []const u8) !void {
        const reason = try std.fmt.allocPrint(self.allocator, "{s}\nHANDOFF_BLOCKED: {s}", .{ result.error_msg, reason_name });
        self.allocator.free(result.error_msg);
        result.error_msg = reason;
        result.success = false;
        const payload = try std.json.Stringify.valueAlloc(self.allocator, .{ .task_id = result.task_id, .provider = provider, .model = model, .reason = reason_name }, .{});
        defer self.allocator.free(payload);
        self.recordEvent("handoff_blocked_v1", payload);
    }

    fn markCorrectionChainExhausted(self: *Superagent, res: *TaskRunResult) void {
        if (std.mem.indexOf(u8, res.error_msg, correction_chain_exhausted_note) != null) return;
        const updated = std.fmt.allocPrint(self.allocator, "{s}; {s}", .{ res.error_msg, correction_chain_exhausted_note }) catch return;
        self.allocator.free(res.error_msg);
        res.error_msg = updated;
    }

    /// r2 (P1): ¿esta tarea ya intentó exactamente `name`?
    fn attemptAlreadyTried(tried: []const CorrectionAttempt, task_id: []const u8, name: []const u8) bool {
        for (tried) |t| {
            if (std.mem.eql(u8, t.task_id, task_id) and std.mem.eql(u8, t.model_name, name)) return true;
        }
        return false;
    }

    /// r2 (P1): registra (tarea, modelo) si no estaba ya. El
    /// llamador posee la lista y libera sus dupes.
    fn rememberCorrectionAttempt(allocator: std.mem.Allocator, tried: *std.ArrayListUnmanaged(CorrectionAttempt), task_id: []const u8, model_name: []const u8) !void {
        if (attemptAlreadyTried(tried.items, task_id, model_name)) return;
        const tid = try allocator.dupe(u8, task_id);
        errdefer allocator.free(tid);
        const name = try allocator.dupe(u8, model_name);
        errdefer allocator.free(name);
        try tried.append(allocator, .{ .task_id = tid, .model_name = name });
    }

    fn isRepairableContractRejection(result: TaskRunResult) bool {
        if (result.integrated or result.artifacts.len == 0) return false;
        return std.mem.indexOf(u8, result.error_msg, "falta el campo obligatorio") != null or
            std.mem.indexOf(u8, result.error_msg, "el ensamblador rechazo la pieza") != null or
            std.mem.indexOf(u8, result.error_msg, "El entregable enlaza") != null;
    }

    /// una tarea que terminó SIN artefacto porque el worker o su
    /// proveedor devolvió algo ilegible (`InvalidArtifact`, JSON vacío, respuesta
    /// vacía, timeout de transporte) es REINTENTABLE una vez.
    ///
    /// Medido el 2026-09-18 (orden #595 t12): el lazo de corrección solo despachaba
    /// tras `validation_failed` (pieza con artefactos que no cumple el contrato) y
    /// tras `execution_failed`; un `worker_failed`/`InvalidArtifact` sin artefactos
    /// moría sin segundo intento y, en una cadena serial, condenaba la orden
    /// entera. La condición `artifacts.len == 0` de `isRepairableContractRejection`
    /// dejaba fuera justo ese caso.
    ///
    /// NO se reintentan: el presupuesto agotado (reintentar no compra nada), la
    /// auditoría sin veredicto (`audit_unavailable` tiene reintento manual
    /// explícito), la sesión agéntica incompleta (el modelo trabajó y no cerró),
    /// el bloqueo por dependencia (lo cubre `rerunRecoveredConsumers` cuando el
    /// productor se corrige), ni los fallos que NO son del artefacto:
    /// transporte/red (`LlmCallFailed`, «sin respuesta HTTP»), timeout,
    /// agotamiento de proveedor (`provider_exhausted`, `AllKeysExhausted`),
    /// política/seguridad, cancelación o presupuesto.
    ///
    /// r2 (P1): el reconocimiento se apoya en las CAUSAS
    /// ESTRUCTURADAS del backend — variantes de `worker_backend.WorkerError`
    /// (`InvalidArtifact`, `JsonParseError`) — que el motor embebe textuales en
    /// `error_msg` al construir el fallo (superagent.zig:2802 para el candidato
    /// de catálogo, 2929 para el worker por `llm_fn`). No se clasifica por prosa:
    /// un `InvalidArtifact` real lleva «sin respuesta HTTP» como STATUS por
    /// defecto porque el proveedor no devolvió cabecera (superagent.zig:2798),
    /// así que rechazar por esa frase tiraría casos recuperables. Cualquier
    /// mensaje que no nombre una causa de artefacto queda fuera.
    fn isRepairableWorkerFailure(result: TaskRunResult) bool {
        if (result.integrated or result.success) return false;
        if (std.mem.indexOf(u8, result.error_msg, "HANDOFF_BLOCKED") != null) return false;
        if (result.artifacts.len != 0) return false;
        if (result.paid_budget_exhausted) return false;
        if (result.audit_verdict == .unavailable) return false;
        if (result.incomplete) return false;
        const artifact_causes = [_][]const u8{
            "InvalidArtifact",
            "JsonParseError",
            "sin artefactos validos",
        };
        for (artifact_causes) |marker| {
            if (std.mem.indexOf(u8, result.error_msg, marker) != null) return true;
        }
        return false;
    }

    /// Reintenta solo consumidores que no llegaron a ejecutarse porque un productor
    /// falló y que ahora tienen todas sus dependencias corregidas. Reemplaza el
    /// resultado bloqueado antes de reusar `runTaskInWave`, para no duplicar tareas.
    fn rerunRecoveredConsumers(ctx: *FanoutContext) void {
        if (ctx.cancel_token) |token| if (token.isCancelled()) return;
        const waves = resolveWaves(ctx.outcome.plan.tasks, ctx.sa.allocator) catch return;
        defer {
            for (waves) |wave| ctx.sa.allocator.free(wave);
            ctx.sa.allocator.free(waves);
        }
        for (waves) |wave| {
            for (wave) |task| {
                var blocked_index: ?usize = null;
                for (ctx.results.items, 0..) |result, index| {
                    if (std.mem.eql(u8, result.task_id, task.id) and
                        (std.mem.eql(u8, result.error_msg, "dependency failed or missing") or
                            std.mem.eql(u8, result.error_msg, "dependency evidence stale after producer correction")))
                    {
                        blocked_index = index;
                        break;
                    }
                }
                const index = blocked_index orelse continue;
                if (!dependenciesSucceeded(ctx.sa.allocator, task, ctx.outcome.plan.tasks, ctx.results.items)) continue;
                const blocked = ctx.results.orderedRemove(index);
                deinitTaskRunResult(ctx.sa.allocator, blocked);
                runTaskInWave(ctx, task);
            }
        }
    }

    fn artifactRevision(artifacts: []const worker_backend.Artifact) u64 {
        var hasher = std.hash.Wyhash.init(0);
        for (artifacts) |artifact| {
            hasher.update(artifact.path);
            hasher.update(&.{0});
            hasher.update(artifact.content);
            hasher.update(&.{0});
        }
        return hasher.final();
    }

    /// La identidad de una entrega no depende del orden de los campos JSON.
    /// Un productor D3 debe cambiar algún path/contenido real antes de que se
    /// invalide y reaudite a sus consumidores.
    fn artifactSetsEqual(
        _: std.mem.Allocator,
        left: []const worker_backend.Artifact,
        right: []const worker_backend.Artifact,
    ) bool {
        if (left.len != right.len) return false;
        // Multiconjunto sin allocation: OOM no puede abrir el gate de cambios.
        for (left) |candidate| {
            var left_count: usize = 0;
            var right_count: usize = 0;
            for (left) |other| {
                if (std.mem.eql(u8, candidate.path, other.path) and std.mem.eql(u8, candidate.content, other.content)) left_count += 1;
            }
            for (right) |other| {
                if (std.mem.eql(u8, candidate.path, other.path) and std.mem.eql(u8, candidate.content, other.content)) right_count += 1;
            }
            if (left_count != right_count) return false;
        }
        return true;
    }

    fn taskDependsOn(task: planner.PlannedTask, task_id: []const u8) bool {
        for (task.depends_on) |dependency| {
            if (std.mem.eql(u8, dependency, task_id)) return true;
        }
        return false;
    }

    fn hasExecutableTestEvidence(result: TaskRunResult) bool {
        return result.tested_producer_id != null and result.test_command != null and
            result.exec.ran and result.exec.exit_code == 0 and
            !result.exec.timed_out and !result.exec.needs_approval;
    }

    /// Un productor corregido invalida todos los consumidores transitivos. Cada
    /// uno vuelve a la ola que le corresponde; no puede heredar contenido ni
    /// evidencia de una revisión anterior.
    fn invalidateDependentEvidence(ctx: *FanoutContext, producer_id: []const u8) void {
        for (ctx.results.items) |*result| {
            const task = findPlannedTask(ctx.outcome.plan.tasks, result.task_id) orelse continue;
            if (!taskDependsOn(task, producer_id)) continue;
            if (std.mem.eql(u8, result.error_msg, "dependency evidence stale after producer correction")) continue;
            result.success = false;
            result.integrated = false;
            ctx.sa.allocator.free(result.error_msg);
            result.error_msg = ctx.sa.allocator.dupe(u8, "dependency evidence stale after producer correction") catch "";
            invalidateDependentEvidence(ctx, result.task_id);
        }
    }

    fn promoteFailedTestEvidence(ctx: *FanoutContext) void {
        for (ctx.results.items) |test_result| {
            const test_task = findPlannedTask(ctx.outcome.plan.tasks, test_result.task_id) orelse continue;
            // A missing command, cancellation, timeout, environment failure or a
            // pending approval is a QA/runner problem. It must fail closed, but
            // it is not evidence that the producer implementation is defective.
            if (test_task.task_type != .testear or test_task.depends_on.len == 0 or
                !test_result.exec.ran or test_result.exec.exit_code == 0 or
                test_result.exec.timed_out or execFailureIsEnvironmental(test_result.exec.stderr)) continue;
            for (test_task.depends_on) |producer_id| {
                for (ctx.results.items) |*producer| {
                    if (!std.mem.eql(u8, producer.task_id, producer_id) or !producer.integrated) continue;
                    if (std.mem.indexOf(u8, producer.error_msg, "CORRECTION_NO_PRODUCER_CHANGE") != null) continue;
                    ctx.sa.allocator.free(producer.error_msg);
                    producer.error_msg = std.fmt.allocPrint(
                        ctx.sa.allocator,
                        "TEST_EVIDENCE_FAILED: command `{s}` exited {d}; stdout: {s}; stderr: {s}",
                        .{ test_result.test_command orelse "", test_result.exec.exit_code, test_result.exec.stdout orelse "", test_result.exec.stderr },
                    ) catch "";
                    producer.success = false;
                }
            }
        }
    }

    /// Un auditor dependiente aporta evidencia contra sus productores cuando el
    /// veredicto contiene un motivo concreto. El auditor no se corrige a sí
    /// mismo: se marca el productor materializado para que el ciclo normal lo
    /// corrija, invalide sus consumidores y los reejecute.
    /// FR-001 / AUDIT-INDEP: el veredicto de una tarea `auditar` ejecutada por un
    /// MODELO queda asentado en el ledger sobre el subject del PRODUCTOR, firmado
    /// por el modelo auditor real (audit_result.model_used) — no por el productor.
    /// Es la única fila AUDIT que cuenta para deriveStatus como auditoría
    /// independiente: el gate determinista firma con model_id="" y las
    /// auto-auditorías quedan descartadas por la regla "auditor != constructor".
    fn auditVerdictRecorded(entries: []const AuditEntry, subject_id: i64, auditor_model: []const u8, verdict: []const u8, auditor_index: u8) bool {
        for (entries) |e| {
            if (e.subject_id == subject_id and
                e.auditor_index == auditor_index and
                std.mem.eql(u8, e.action, "AUDIT") and
                std.mem.eql(u8, e.model_id, auditor_model) and
                std.mem.eql(u8, e.verdict, verdict)) return true;
        }
        return false;
    }

    /// T8: 1 = primer auditor, 2 = segundo auditor. Mismo criterio que el
    /// rol del compositor en assignModel: la tarea `auditar` en posición impar
    /// (0-based) entre las `auditar` del plan es la del segundo auditor.
    fn auditorIndexOf(tasks: []const planner.PlannedTask, audit_id: []const u8) u8 {
        var ordinal: usize = 0;
        for (tasks) |task| {
            if (std.mem.eql(u8, task.id, audit_id)) break;
            if (task.task_type == .auditar) ordinal += 1;
        }
        return if (ordinal % 2 == 1) 2 else 1;
    }

    fn promoteFailedAuditEvidence(ctx: *FanoutContext) void {
        for (ctx.results.items) |audit_result| {
            const audit_task = findPlannedTask(ctx.outcome.plan.tasks, audit_result.task_id) orelse continue;
            if (audit_task.task_type != .auditar or !audit_result.integrated) continue;
            const auditor_model = audit_result.model_used;
            const auditor_provider = if (findAssignment(ctx.outcome.assignments, audit_task.id)) |a| a.provider_name else "unknown";
            // T8: el mismo criterio que asigna el rol `second_audit` en
            // assignModel (posición impar entre las tareas `auditar`).
            const auditor_index = auditorIndexOf(ctx.outcome.plan.tasks, audit_task.id);
            // AUDIT-UNAVAILABLE-P0: el veredicto se lee ESTRICTO. Antes
            // `reason == null` fabricaba "PASS" y lo asentaba en el ledger sobre
            // el productor — la orden 500 quedó "auditada" sin que el auditor
            // respondiera. Sin veredicto usable no hay asiento AUDIT y el
            // productor no se toca: si solo falta esto, la orden cierra
            // 'audit_unavailable' (entrega bloqueada, reintento manual).
            const verdict_state = auditVerdictOf(audit_result.artifacts);
            if (verdict_state == .unavailable) continue;
            const reason = concreteAuditFailureReason(audit_result.artifacts);
            const verdict: []const u8 = if (verdict_state == .fail) "FAIL" else "PASS";
            // D3: un auditor SIN depends_on declaradas es un auditor genérico de
            // la orden entera — auditó el entregable completo. Sus hallazgos van
            // a TODOS los productores del plan; antes se saltaba con `continue`
            // y el veredicto no llegaba a nadie: ni asiento en el ledger ni
            // corrección, aunque el auditor hubiera dicho FAIL con motivo.
            const maybe_ancestors: ?[]const []const u8 = if (audit_task.depends_on.len > 0)
                subagent.ancestrosDe(ctx.sa.allocator, ctx.outcome.plan.tasks, audit_task.id) catch null
            else blk: {
                var all = std.ArrayList([]const u8).empty;
                for (ctx.outcome.plan.tasks) |pt| {
                    if (isProducerType(pt.task_type)) all.append(ctx.sa.allocator, pt.id) catch {
                        all.deinit(ctx.sa.allocator);
                        break :blk null;
                    };
                }
                break :blk all.toOwnedSlice(ctx.sa.allocator) catch null;
            };
            const ancestors = maybe_ancestors orelse continue;
            defer ctx.sa.allocator.free(ancestors);
            var marked_any = false;
            for (ancestors) |ancestor_id| {
                const producer_task = findPlannedTask(ctx.outcome.plan.tasks, ancestor_id) orelse continue;
                if (!isProducerType(producer_task.task_type)) continue;
                // Sin resultado del productor no hay artefacto auditado: un
                // asiento AUDIT aquí certificaría una revisión que no ocurrió.
                var producer_res: ?*TaskRunResult = null;
                for (ctx.results.items) |*pr| {
                    if (std.mem.eql(u8, pr.task_id, ancestor_id)) {
                        producer_res = pr;
                        break;
                    }
                }
                const pres = producer_res orelse continue;
                const subject_id = idToInt(ancestor_id);
                // Asiento del veredicto del auditor-modelo sobre el productor.
                // Dedup por (subject, auditor, verdict): el ciclo de corrección
                // relee los mismos resultados y no debe duplicar el mismo voto.
                if (!auditVerdictRecorded(ctx.audit_entries.items, subject_id, auditor_model, verdict, auditor_index)) {
                    appendAuditEntry(ctx.sa.allocator, &ctx.audit_entries, ctx.sa.event_conn, ctx.sa.event_order_id, .{
                        .ts = 0,
                        .subject_kind = "task",
                        .subject_id = subject_id,
                        .action = "AUDIT",
                        .verdict = verdict,
                        .model_id = auditor_model,
                        .provider = auditor_provider,
                        .evidence_ref = audit_result.saved_path orelse "",
                        .notes = reason orelse (if (verdict_state == .fail) "model audit fail" else "model audit pass"),
                        .auditor_index = auditor_index,
                    });
                }
                if (reason == null) continue;
                const producer = pres;
                {
                    if (!producer.integrated or producer.saved_path == null) continue;
                    if (std.mem.indexOf(u8, producer.error_msg, "AUDIT_EVIDENCE_FAILED") != null) continue;
                    // Conservar la evidencia QA previa: el veredicto del auditor
                    // orienta la corrección, pero no sustituye comando/stdout/stderr
                    // ya capturados. Ambos campos se acotan en límites UTF-8.
                    const marker = std.fmt.allocPrint(
                        ctx.sa.allocator,
                        "AUDIT_EVIDENCE_FAILED: audit_task={s}; reason={s}\nPRIOR_EVIDENCE: {s}",
                        .{
                            audit_result.task_id,
                            utf8PrefixWithin(reason.?, 4096),
                            utf8PrefixWithin(producer.error_msg, 4096),
                        },
                    ) catch continue;
                    ctx.sa.allocator.free(producer.error_msg);
                    producer.error_msg = marker;
                    producer.success = false;
                    marked_any = true;
                }
            }
            // El auditor genérico no tiene aristas depends_on, así que la
            // invalidación por dependencia nunca lo toca: si su veredicto ya se
            // consumió (marcó productores) hay que invalidarlo a mano. Así el
            // ciclo siguiente no relee el veredicto VIEJO contra el artefacto
            // corregido, y rerunRecoveredConsumers lo reejecuta para auditar la
            // nueva revisión — mismo ciclo de vida que un auditor dependiente.
            if (audit_task.depends_on.len == 0 and marked_any) {
                // audit_result llega por valor (for |x| copia): hay que tocar
                // el elemento real del array o el invalidado se pierde.
                for (ctx.results.items) |*ar| {
                    if (!std.mem.eql(u8, ar.task_id, audit_result.task_id)) continue;
                    ar.success = false;
                    ar.integrated = false;
                    ctx.sa.allocator.free(ar.error_msg);
                    ar.error_msg = ctx.sa.allocator.dupe(u8, "dependency evidence stale after producer correction") catch "";
                    break;
                }
            }
        }
    }

    /// BGATE-1: comprobación funcional del entregable web en un navegador real.
    ///
    /// Se ejecuta al principio de cada ciclo de auditoría, junto a las otras dos
    /// promociones de evidencia, y por el mismo motivo: lo que decide si una
    /// orden está bien no puede ser el informe de quien la escribió. La orden 437
    /// pasó su propio test (un DOM inventado dentro del propio test), obtuvo un
    /// PASS textual del auditor y entregó una calculadora que no calculaba.
    ///
    /// El hallazgo que produce es CONCRETO y va dirigido: nombra el control que
    /// no reacciona y marca sólo a los productores que pueden repararlo —el HTML
    /// que declara el control y el script que debería engancharlo—, no a todos
    /// los ancestros materializados de la rama.
    fn runBrowserGateEvidence(ctx: *FanoutContext) void {
        const allocator = ctx.sa.allocator;

        // Carpeta del entregable: la del primer HTML realmente escrito en disco.
        var order_dir: ?[]const u8 = null;
        var page_name: []const u8 = "";
        for (ctx.saved.items) |path| {
            const ext = std.fs.path.extension(path);
            if (!std.ascii.eqlIgnoreCase(ext, ".html") and !std.ascii.eqlIgnoreCase(ext, ".htm")) continue;
            order_dir = std.fs.path.dirname(path) orelse continue;
            page_name = std.fs.path.basename(path);
            break;
        }
        // Sin página no hay nada que comprobar EN NAVEGADOR. No es un aprobado
        // implícito de nada: es que este gate no aplica a este entregable.
        const dir = order_dir orelse return;

        var result = browser_gate.run(allocator, dir, BROWSER_GATE_TIMEOUT_MS) catch |e| {
            var out: std.Io.Writer.Allocating = .init(allocator);
            defer out.deinit();
            var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
            js.beginObject() catch {};
            js.objectField("ran") catch {};
            js.write(false) catch {};
            js.objectField("reason") catch {};
            js.write(@errorName(e)) catch {};
            js.objectField("page") catch {};
            js.write(page_name) catch {};
            js.endObject() catch {};
            ctx.sa.recordEvent("browser_gate_v1", out.written());
            return;
        };
        defer result.deinit(allocator);

        {
            var out: std.Io.Writer.Allocating = .init(allocator);
            defer out.deinit();
            var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
            js.beginObject() catch {};
            js.objectField("ran") catch {};
            js.write(result.ran) catch {};
            js.objectField("verdict") catch {};
            js.write(@tagName(result.verdict)) catch {};
            // El alcance va EN el evento, no solo en la documentacion: un
            // `pass` de este gate significa «los controles reaccionan», nunca
            // «el resultado es correcto». Una auditoria independiente demostro
            // el 09-09 que una calculadora que devuelve 999 para 6+3 aprueba
            // igual, asi que la etiqueta viaja con el dato.
            js.objectField("alcance") catch {};
            js.write(@as([]const u8, "efecto_observable_no_correccion_semantica")) catch {};
            js.objectField("page") catch {};
            js.write(result.page) catch {};
            js.objectField("browser") catch {};
            js.write(result.browser) catch {};
            js.objectField("gate_dir") catch {};
            js.write(result.gate_dir) catch {};
            js.objectField("files_checked") catch {};
            js.write(result.files_checked) catch {};
            // Huella de los BYTES LEÍDOS DE DISCO, no de los artefactos en memoria.
            var digest_buf: [16]u8 = undefined;
            const digest_text = std.fmt.bufPrint(&digest_buf, "{x}", .{result.files_digest}) catch "0";
            js.objectField("files_digest") catch {};
            js.write(digest_text) catch {};
            js.objectField("fields_seeded") catch {};
            js.write(result.fields_seeded) catch {};
            js.objectField("dead_controls") catch {};
            js.write(result.deadControls()) catch {};
            // C1: cuántos controles devolvieron la MISMA salida con dos juegos
            // de entradas distintos. No cambia el veredicto —el alcance sigue
            // siendo efecto observable— pero la señal viaja: una salida
            // constante es el falso verde que la auditoria demostro el 09-09.
            js.objectField("controles_invariantes") catch {};
            js.write(result.invariantControls()) catch {};
            if (result.reason.len > 0) {
                js.objectField("reason") catch {};
                js.write(result.reason) catch {};
            }
            js.objectField("controls") catch {};
            js.beginArray() catch {};
            for (result.controls) |c| {
                js.beginObject() catch {};
                js.objectField("control") catch {};
                js.write(c.control) catch {};
                js.objectField("changed_dom") catch {};
                js.write(c.changed_dom) catch {};
                js.objectField("errors") catch {};
                js.write(c.errors) catch {};
                // QUE cambio, no solo que cambiara: es lo unico que permite
                // leer «6 + 3 dio 999» en vez de «hizo algo».
                if (c.cambio.len > 0) {
                    js.objectField("cambio") catch {};
                    js.write(c.cambio) catch {};
                }
                if (c.entrada_ignorada) {
                    js.objectField("entrada_ignorada") catch {};
                    js.write(true) catch {};
                }
                if (c.threw) |t| {
                    js.objectField("threw") catch {};
                    js.write(t) catch {};
                }
                js.endObject() catch {};
            }
            js.endArray() catch {};
            js.objectField("js_errors") catch {};
            js.beginArray() catch {};
            for (result.js_errors) |e| js.write(e) catch {};
            js.endArray() catch {};
            js.endObject() catch {};
            ctx.sa.recordEvent("browser_gate_v1", out.written());
        }

        // Un gate que no pudo correr no aprueba ni suspende: deja el estado como
        // estaba y ya ha dicho por qué en su evento.
        if (!result.ran) return;

        if (result.verdict == .pass) {
            // Reverificación: si una corrección arregló de verdad la página, el
            // productor deja de estar marcado. Sólo se tocan los resultados que
            // este gate había marcado; nada más se reinterpreta como éxito.
            for (ctx.results.items) |*res| {
                if (std.mem.indexOf(u8, res.error_msg, "BROWSER_GATE_FAILED") == null) continue;
                allocator.free(res.error_msg);
                res.error_msg = allocator.dupe(u8, "CORREGIDO Y VERIFICADO EN NAVEGADOR REAL") catch "";
                res.success = true;
            }
            return;
        }

        const detail = browser_gate.describeFailure(allocator, result) catch return;
        defer allocator.free(detail);

        for (ctx.results.items) |*res| {
            const path = res.saved_path orelse continue;
            if (!res.integrated) continue;
            const name = std.fs.path.basename(path);
            const ext = std.fs.path.extension(name);
            // Dirigido: la página que declara el control y el script que debería
            // engancharlo. La hoja de estilos no puede reparar un manejador que
            // no existe, y marcarla sólo produciría una corrección inútil.
            const is_page = std.ascii.eqlIgnoreCase(name, result.page);
            const is_script = std.ascii.eqlIgnoreCase(ext, ".js") or
                std.ascii.eqlIgnoreCase(ext, ".mjs") or
                std.ascii.eqlIgnoreCase(ext, ".cjs");
            if (!is_page and !is_script) continue;
            if (std.mem.indexOf(u8, res.error_msg, "CORRECTION_NO_PRODUCER_CHANGE") != null) continue;
            if (std.mem.indexOf(u8, res.error_msg, "BROWSER_GATE_FAILED") != null) continue;
            const marker = std.fmt.allocPrint(
                allocator,
                "{s}\nARCHIVOS COMPROBADOS EN DISCO: {d} (huella {x}). Pagina: {s}.\nEVIDENCIA PREVIA: {s}",
                .{ detail, result.files_checked, result.files_digest, result.page, utf8PrefixWithin(res.error_msg, 4096) },
            ) catch continue;
            allocator.free(res.error_msg);
            res.error_msg = marker;
            res.success = false;
        }
    }

    const SemanticGateOutcome = struct {
        /// El gate corrió (había observable declarado que comprobar).
        ran: bool = false,
        /// El gate corrió y alguna aserción declarada no se cumplió.
        failed: bool = false,
        /// Texto de las diferencias observadas (owned). null si no corrió o pasó.
        note: ?[]const u8 = null,
    };

    /// SEMANTIC-GATE-T3: evalúa el observable declarado de la orden.
    ///
    /// Declaración (dos fuentes, misma forma — array JSON de aserciones, ver
    /// semantic_gate.zig): el campo `orders.expected_result` escrito por
    /// da_order_set_expected tiene prioridad; si está vacío se deriva del
    /// plan (contract field 'expects' por tarea). Sin nada declarado el gate
    /// informa ran:false y NO cambia el veredicto — no fabrica un chequeo
    /// que nadie pidió, y el evento lo dice.
    ///
    /// Se corre UNA vez, después de los ciclos de auditoría y antes del
    /// veredicto terminal: es una capa ENCIMA del gate de ejecución, no un
    /// reemplazo. Un FAIL impide 'done' aunque todas las tareas hayan
    /// completado — el ejecutor midió que las tareas corrieron, no que la
    /// intención se cumpliera (falso verde C1).
    fn evaluateSemanticGate(self: *Superagent, ctx: *FanoutContext, outcome: *OrderOutcome) !SemanticGateOutcome {
        const a = self.allocator;
        var assertions = std.ArrayList(semantic_gate.Assertion).empty;
        defer {
            for (assertions.items) |as| as.deinit(a);
            assertions.deinit(a);
        }
        var from_order = false;
        var from_plan = false;
        var invalid_declaration = false;

        // Fuente 1: campo explícito de la orden.
        if (self.runtime.prepare("SELECT expected_result FROM orders WHERE id = ?")) |stmt| {
            defer self.runtime.finalize(stmt);
            db.bindInt(stmt, 1, outcome.order_id) catch {};
            if (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW) {
                const ptr = db.c.sqlite3_column_text(stmt, 0);
                const len = db.c.sqlite3_column_bytes(stmt, 0);
                if (ptr != null and len > 0) {
                    const json = ptr[0..@intCast(len)];
                    if (semantic_gate.parseAssertions(a, json)) |list| {
                        defer a.free(list);
                        for (list) |as| try assertions.append(a, as);
                        from_order = list.len > 0;
                    } else |_| {
                        // Una declaración inválida no se ignora en silencio:
                        // el evento lo dice y el gate cuenta como no-declarado.
                        self.recordEvent("semantic_gate_v1", "{\"ran\":false,\"reason\":\"declaracion_invalida\"}");
                        invalid_declaration = true;
                    }
                }
            }
        } else |_| {}

        // Fuente 2 (derivado del plan): contract field 'expects' por tarea —
        // su value es el mismo array JSON de aserciones. Solo se usa cuando la
        // orden no declaró nada explícito.
        // en una orden que SE DECLARA auditoría, lo que el planificador
        // escribe como `expects` de la tarea `auditar` es la hipótesis que se
        // audita, no el resultado de la orden (que es el veredicto). Evaluarlo
        // como criterio de éxito, y además en la carpeta de la orden, tumbaba
        // auditorías que acertaban (orden 7 de la prueba del 22-09:
        // «file_contains core/src/db.zig busy_timeout» buscado donde la orden
        // escribe). Lo que declara el usuario y lo de las tareas productoras
        // sigue valiendo; en un encargo de construcción, también lo del auditar.
        const es_auditoria = ordenEsAuditoria(self, outcome.order_id);
        var omitidas: usize = 0;
        if (!from_order and !invalid_declaration) {
            for (outcome.plan.tasks) |pt| {
                const hipotesis = es_auditoria and pt.task_type == .auditar;
                for (pt.contract_fields) |f| {
                    if (!std.mem.eql(u8, f.name, "expects")) continue;
                    const v = f.value orelse continue;
                    if (hipotesis) {
                        omitidas += 1;
                        continue;
                    }
                    const list = semantic_gate.parseAssertions(a, v) catch continue;
                    defer a.free(list);
                    for (list) |as| {
                        // Las aserciones de archivo de una tarea que no declara
                        // task_id se evalúan igual; las de salida sin task_id
                        // miran todas las salidas registradas.
                        try assertions.append(a, as);
                        from_plan = true;
                    }
                }
            }
        }

        var prose = std.ArrayList(semantic_gate.ProseEvidence).empty;
        defer prose.deinit(a);
        for (ctx.saved.items, ctx.saved_owner.items) |path, owner| {
            const pt = findPlannedTask(outcome.plan.tasks, owner) orelse continue;
            // An internal audit report is evidence about the product, not a
            // prose deliverable of a code order. Standalone audits still count.
            if (pt.task_type == .auditar and !es_auditoria) continue;
            if (!prose_artifact.isProseDelivery(path, pt.task_type)) continue;
            // the line above already dropped the internal audit
            // report of a code order, so anything reaching here is either a
            // non-audit prose task or a standalone audit. Both must be measured
            // against their REAL description — clearing it here let a trivial
            // "OK" pass an independent audit that had asked for an explanation.
            try prose.append(a, .{ .path = path, .description = pt.description, .task_id = pt.id });
        }

        if (assertions.items.len == 0 and prose.items.len == 0) {
            if (invalid_declaration) return .{};
            if (omitidas > 0) {
                self.recordEvent("semantic_gate_v1", "{\"ran\":false,\"reason\":\"orden_de_auditoria\",\"detalle\":\"lo que declara la tarea auditar es la hipotesis auditada; el resultado de la orden es su veredicto\"}");
            } else {
                self.recordEvent("semantic_gate_v1", "{\"ran\":false,\"reason\":\"sin_observable_declarado\"}");
            }
            return .{};
        }

        // Raíz de los artefactos: el directorio del primer archivo guardado
        // (funciona también para órdenes en space/worktree); sin artefactos,
        // la carpeta convencional orden-<id> bajo la raíz efectiva.
        // E5.09: si el productor fue un agente externo, sus archivos viven en
        // el layout REAL del worktree (src/index.js, test/…) — las aserciones
        // se resuelven contra la raíz del worktree, no contra el dirname del
        // primer archivo (que daría <wt>/src y buscaría src/src/index.js).
        var root_buf: [4096]u8 = undefined;
        const order_dir = blk: {
            for (ctx.results.items) |res| {
                if (res.worktree_root) |wr| {
                    if (res.saved_path != null) break :blk try a.dupe(u8, wr);
                }
            }
            if (ctx.saved.items.len > 0) {
                // D2: con subcarpetas (`docs\uno.txt`) el dirname del primer
                // archivo ya no es la carpeta de la orden; si el archivo cuelga
                // de donde escribe persistTaskFiles, las aserciones se
                // resuelven desde allí.
                const produced = try workspace.producerOutputDir(a, outcome.order_id);
                if (std.mem.startsWith(u8, ctx.saved.items[0], produced) and ctx.saved.items[0].len > produced.len and
                    (ctx.saved.items[0][produced.len] == '\\' or ctx.saved.items[0][produced.len] == '/')) break :blk produced;
                a.free(produced);
                if (std.fs.path.dirname(ctx.saved.items[0])) |d| break :blk try a.dupe(u8, d);
            }
            const root = workspace.effectiveRoot(&root_buf);
            break :blk try std.fmt.allocPrint(a, "{s}" ++ std.fs.path.sep_str ++ "orden-{d}", .{ root, outcome.order_id });
        };
        defer a.free(order_dir);

        var outputs = std.ArrayList(semantic_gate.OutputEvidence).empty;
        defer outputs.deinit(a);
        for (ctx.results.items) |res| {
            if (res.exec.stdout) |so| {
                if (so.len > 0) try outputs.append(a, .{ .task_id = res.task_id, .stdout = so });
            }
        }

        var result = try semantic_gate.runWithProse(a, order_dir, assertions.items, outputs.items, prose.items);
        defer result.deinit(a);

        // Evento con el detalle COMPLETO: cada comprobación, lo esperado y lo
        // observado — el fail trae la diferencia concreta, no un «falló».
        {
            var out: std.Io.Writer.Allocating = .init(a);
            defer out.deinit();
            var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
            js.beginObject() catch {};
            js.objectField("ran") catch {};
            js.write(result.ran) catch {};
            js.objectField("verdict") catch {};
            js.write(@tagName(result.verdict)) catch {};
            js.objectField("fuente") catch {};
            js.write(if (from_order) "orden" else if (from_plan) "plan" else "entregables_prosa") catch {};
            js.objectField("declaradas") catch {};
            js.write(assertions.items.len) catch {};
            if (omitidas > 0) {
                js.objectField("omitidas_auditoria") catch {};
                js.write(omitidas) catch {};
            }
            js.objectField("order_dir") catch {};
            js.write(order_dir) catch {};
            js.objectField("checks") catch {};
            js.beginArray() catch {};
            for (result.checks) |c| {
                js.beginObject() catch continue;
                js.objectField("kind") catch continue;
                js.write(@tagName(c.assertion.kind)) catch continue;
                if (c.assertion.path.len > 0) {
                    js.objectField("path") catch continue;
                    js.write(c.assertion.path) catch continue;
                }
                if (c.assertion.task_id.len > 0) {
                    js.objectField("task_id") catch continue;
                    js.write(c.assertion.task_id) catch continue;
                }
                if (c.assertion.needle.len > 0) {
                    js.objectField("needle") catch continue;
                    js.write(c.assertion.needle) catch continue;
                }
                js.objectField("ok") catch continue;
                js.write(c.ok) catch continue;
                js.objectField("actual") catch continue;
                js.write(c.actual) catch continue;
                if (c.difference.len > 0) {
                    js.objectField("diferencia") catch continue;
                    js.write(c.difference) catch continue;
                }
                js.endObject() catch continue;
            }
            js.endArray() catch {};
            if (result.differences_text.len > 0) {
                js.objectField("diferencias") catch {};
                js.write(result.differences_text) catch {};
            }
            js.endObject() catch {};
            self.recordEvent("semantic_gate_v1", out.written());
        }

        // Narrador: el veredicto semántico también se cuenta en lenguaje claro.
        {
            var out: std.Io.Writer.Allocating = .init(a);
            defer out.deinit();
            var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
            js.beginObject() catch {};
            js.objectField("text") catch {};
            const line = if (result.verdict == .pass)
                std.fmt.allocPrint(a, "Gate semántico: PASS — {d} comprobación(es) del observable declarado satisfechas", .{result.checks.len}) catch "Gate semántico: PASS"
            else
                std.fmt.allocPrint(a, "Gate semántico: FAIL — el observable declarado no se cumple. {s}", .{result.differences_text}) catch "Gate semántico: FAIL";
            defer a.free(line);
            js.write(line) catch {};
            js.endObject() catch {};
            self.recordEvent("superagent_thinking", out.written());
        }

        return .{
            .ran = true,
            .failed = result.verdict == .fail,
            .note = if (result.verdict == .fail)
                try a.dupe(u8, result.differences_text)
            else
                null,
        };
    }

    /// Contexto compartido protegido por mutex para la ejecución paralela por olas.
    const FanoutContext = struct {
        browser: ?*browser_service.Service = null,
        /// T8: tareas cuyo modelo lo decidió el pin `sidekick`
        /// del compositor. Solo lectura durante las olas.
        sidekick_ids: []const []const u8 = &.{},
        mutex: sync.Mutex,
        completed: usize,
        failed: usize,
        integrated: usize,
        rejected: usize,
        outputs: std.ArrayList(WorkerOutput),
        pending: std.ArrayList(ApprovalRequest),
        saved: std.ArrayList([]const u8),
        /// D7: quien produjo cada entrada de `saved`, en paralelo y con la misma
        /// longitud. Sin esto no se puede saber que ve cada subagente: la lista
        /// de rutas sola no dice de que rama viene cada archivo.
        saved_owner: std.ArrayList([]const u8),
        results: std.ArrayList(TaskRunResult),
        sa: *Superagent,
        outcome: *OrderOutcome,
        llm_fn: ?worker_backend.NativeWorker.LlmFn,
        llm_ctx: ?*anyopaque,
        catalog_path: ?[]const u8,
        /// Resources de herramientas relevantes para esta orden, propagadas al worker.
        needed_resources: []const tool_discovery.Resource,
        /// P12-T3: selecciones por-tarea del selector agéntico (opcional).
        /// Si está set, runTaskInWave usa la selección específica de cada tarea.
        task_selections: ?[]tool_discovery.TaskSelection = null,
        /// FIX-3: contexto de archivos producidos por olas previas (inyectado a los workers de la ola actual).
        current_upstream: ?[]const u8 = null,
        /// FIX-4a: manifiesto del plan (estatico), inyectado a cada worker de la orden.
        plan_manifest: ?[]const u8 = null,
        /// P5b: entradas de audit_ledger recogidas durante el dispatch.
        audit_entries: std.ArrayList(AuditEntry) = .empty,
        /// C2: espejo de Superagent.cancel_token — vive mientras dura ESTA llamada a
        /// approveAndDispatch, visible por todos los hilos de tarea de todas las olas
        /// de esta orden (mismo puntero, nunca poseído por FanoutContext).
        cancel_token: ?*const live_worker.CancellationToken = null,
        /// ORDER-ROOT-WORKERS: raíz de la orden (worktree del space) capturada en
        /// el hilo de dispatch. El override de workspace es thread-local y los
        /// hilos worker nacen sin él: sin esto persistTask escribía en la raíz
        /// global y los artefactos quedaban fuera del worktree (orden #457).
        /// Propiedad del allocator del FanoutContext; null = raíz global.
        order_root: ?[]const u8 = null,
        /// E5.08: presupuesto de ORDEN ya consumido por agentes externos
        /// (reloj y turnos acumulados por despachos anteriores de esta orden).
        /// Se lee y acumula bajo ctx.mutex.
        external_ms_used: u64 = 0,
        external_turns_used: u32 = 0,
        /// E5.13 (D-C3): mapa del repo renderizado para los workers (~3k
        /// tokens), construido una vez por despacho e inyectado read-only a
        /// cada prompt (nativo, agéntico y externo). Propiedad del ctx.
        repo_map_text: ?[]const u8 = null,
        images: []const providers.connector.ImagePart = &.{},
        /// respaldos realmente ocurridos (quién falló, motivo,
        /// quién siguió), para declararlos en el resumen final del chat.
        /// Se escribe bajo `mutex` desde los hilos de tarea.
        fallback_notes: std.ArrayList(FallbackNote) = .empty,
    };

    /// P09-T3/T4: Llama al bridge MCP de Open Design para tareas 'disenar'.
    /// 1. Verifica si el bridge está conectado.
    /// 2. Llama od_status para obtener la URL de OpenDesign.
    /// 3. Si no está corriendo, intenta od_start_daemon.
    /// 4. Emite previewAvailable con la URL para el chat UI.
    /// 5. Si falla, emite un evento de degradación con mensaje accionable.
    fn handleDesignTaskBridge(ctx: *FanoutContext, pt: planner.PlannedTask, artifacts: []const worker_backend.Artifact) void {
        const allocator = ctx.sa.allocator;
        const od = ctx.sa.od_mcp_state orelse {
            // Sin bridge configurado — degradación graceful.
            emitDesignDegradation(ctx, pt.id, "Bridge MCP de Open Design no configurado. Usa el botón 'Open Design' para iniciarlo.");
            return;
        };

        // Verificar si está conectado (lectura sin lock — safe porque solo leemos).
        if (!od.connected) {
            emitDesignDegradation(ctx, pt.id, "Bridge MCP no conectado. Ejecuta 'DevAgents: Open Design' o verifica la configuración devagents.openDesign.bridgePath.");
            return;
        }

        // Llamar od_status para verificar si OpenDesign está corriendo.
        const status_result = od.callToolJson(allocator, "od_status", "{}") catch |e| {
            emitDesignDegradation(ctx, pt.id, std.fmt.allocPrint(allocator, "Error al consultar od_status: {s}. Verifica que el bridge y WSL estén disponibles.", .{@errorName(e)}) catch "Error al consultar od_status");
            return;
        };
        defer allocator.free(status_result);

        // Extraer URL del resultado. El formato es {"content":"...","is_error":false}
        // donde content es un JSON con running, url, etc.
        const url = extractOdUrl(allocator, status_result) catch null;
        defer if (url) |u| allocator.free(u);

        if (url) |u| {
            // OpenDesign está corriendo — crear un run real con el runtime DevAgents.
            submitDesignRun(ctx, pt, od, u, artifacts);
        } else {
            // No está corriendo — intentar od_start_daemon.
            const start_result = od.callToolJson(allocator, "od_start_daemon", "{\"target\":\"web\"}") catch |e| {
                emitDesignDegradation(ctx, pt.id, std.fmt.allocPrint(allocator, "No se pudo iniciar OpenDesign: {s}. Inicia WSL y OpenDesign manualmente.", .{@errorName(e)}) catch "No se pudo iniciar OpenDesign");
                return;
            };
            defer allocator.free(start_result);

            // Re-verificar status después de iniciar.
            const status2 = od.callToolJson(allocator, "od_status", "{}") catch {
                emitDesignDegradation(ctx, pt.id, "OpenDesign iniciado pero no se pudo verificar el estado. Revisa WSL manualmente.");
                return;
            };
            defer allocator.free(status2);

            const url2 = extractOdUrl(allocator, status2) catch null;
            defer if (url2) |u| allocator.free(u);

            if (url2) |u| {
                submitDesignRun(ctx, pt, od, u, artifacts);
            } else {
                emitDesignDegradation(ctx, pt.id, "OpenDesign iniciado pero no se detectó URL. Verifica que el daemon esté corriendo en WSL.");
            }
        }
    }

    fn selectDesignPrompt(pt: planner.PlannedTask, artifacts: []const worker_backend.Artifact) []const u8 {
        for (artifacts) |art| {
            if (std.mem.eql(u8, art.path, "prompt") or std.mem.eql(u8, art.path, "content") or std.mem.eql(u8, art.path, "response") or std.mem.eql(u8, art.path, "answer") or std.mem.eql(u8, art.path, "result")) {
                const trimmed = std.mem.trim(u8, art.content, " \t\r\n");
                if (trimmed.len > 0) return trimmed;
            }
        }
        return pt.description;
    }

    fn buildDesignSubmitArgs(allocator: std.mem.Allocator, prompt: []const u8) ![]const u8 {
        var out: std.Io.Writer.Allocating = .init(allocator);
        defer out.deinit();
        var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
        try js.beginObject();
        try js.objectField("prompt");
        try js.write(prompt);
        try js.objectField("project_name");
        try js.write(@as([]const u8, "DevAgents design task"));
        try js.endObject();
        return try allocator.dupe(u8, out.written());
    }

    fn extractOdSuccess(allocator: std.mem.Allocator, json_str: []const u8) !?bool {
        var parsed = std.json.parseFromSlice(std.json.Value, allocator, json_str, .{}) catch return null;
        defer parsed.deinit();
        const root = parsed.value;
        if (root != .object) return null;
        const content_val = root.object.get("content") orelse return null;
        if (content_val != .string) return null;
        var content_parsed = std.json.parseFromSlice(std.json.Value, allocator, content_val.string, .{}) catch return null;
        defer content_parsed.deinit();
        const content_root = content_parsed.value;
        if (content_root != .object) return null;
        if (content_root.object.get("success")) |success_val| {
            if (success_val == .bool) return success_val.bool;
        }
        return null;
    }

    fn emitOpenDesignRunEvent(ctx: *FanoutContext, task_id: []const u8, submit_result: []const u8) void {
        const allocator = ctx.sa.allocator;
        var out: std.Io.Writer.Allocating = .init(allocator);
        defer out.deinit();
        var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
        js.beginObject() catch return;
        js.objectField("task_id") catch return;
        js.write(task_id) catch return;
        js.objectField("source") catch return;
        js.write("open-design") catch return;
        js.objectField("result") catch return;
        js.write(submit_result) catch return;
        js.endObject() catch return;
        // MULTISESSION-P0 (2026-07-12): recordEvent corre en un hilo de una ola de
        // fan-out — serializar contra los hilos hermanos con el mismo mutex por
        // dispatch que ya protege el resto de FanoutContext (sin rediseño).
        ctx.mutex.lock();
        defer ctx.mutex.unlock();
        ctx.sa.recordEvent("open_design_run_started", out.written());
    }

    fn submitDesignRun(ctx: *FanoutContext, pt: planner.PlannedTask, od: *od_mcp.OdMcpState, url: []const u8, artifacts: []const worker_backend.Artifact) void {
        const allocator = ctx.sa.allocator;
        const prompt = selectDesignPrompt(pt, artifacts);
        const args_json = buildDesignSubmitArgs(allocator, prompt) catch {
            emitDesignDegradation(ctx, pt.id, "No se pudieron serializar los argumentos para OpenDesign.");
            return;
        };
        defer allocator.free(args_json);

        const submit_result = od.callToolJson(allocator, "od_submit_design", args_json) catch |e| {
            emitDesignDegradation(ctx, pt.id, std.fmt.allocPrint(allocator, "OpenDesign está disponible, pero no se pudo crear el run: {s}.", .{@errorName(e)}) catch "OpenDesign está disponible, pero no se pudo crear el run.");
            return;
        };
        defer allocator.free(submit_result);

        const ok = extractOdSuccess(allocator, submit_result) catch null;
        if (ok != true) {
            emitDesignDegradation(ctx, pt.id, "OpenDesign no pudo iniciar un run con el runtime DevAgents. Revisa que `devagents` exista en WSL y que OpenDesign detecte el runtime.");
            // MULTISESSION-P0: mismo mutex por dispatch que el resto de FanoutContext.
            ctx.mutex.lock();
            ctx.sa.recordEvent("open_design_submit_failed", submit_result);
            ctx.mutex.unlock();
            return;
        }

        emitOpenDesignRunEvent(ctx, pt.id, submit_result);
        const preview_url = extractOdUrl(allocator, submit_result) catch null;
        defer if (preview_url) |u| allocator.free(u);
        emitDesignPreview(ctx, pt.id, preview_url orelse url, artifacts);
    }

    /// P09-T3: Emite un evento previewAvailable con la URL de OpenDesign.
    fn emitDesignPreview(ctx: *FanoutContext, task_id: []const u8, url: []const u8, artifacts: []const worker_backend.Artifact) void {
        const allocator = ctx.sa.allocator;
        var out: std.Io.Writer.Allocating = .init(allocator);
        defer out.deinit();
        var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
        js.beginObject() catch return;
        js.objectField("task_id") catch return;
        js.write(task_id) catch return;
        js.objectField("url") catch return;
        js.write(url) catch return;
        js.objectField("source") catch return;
        js.write("open-design") catch return;
        // Incluir el prompt del worker si está disponible.
        if (artifacts.len > 0) {
            for (artifacts) |art| {
                if (std.mem.eql(u8, art.path, "prompt") or std.mem.eql(u8, art.path, "content") or std.mem.eql(u8, art.path, "response")) {
                    js.objectField("prompt") catch return;
                    js.write(art.content) catch return;
                    break;
                }
            }
        }
        js.endObject() catch return;
        // MULTISESSION-P0: mismo mutex por dispatch que el resto de FanoutContext.
        ctx.mutex.lock();
        defer ctx.mutex.unlock();
        ctx.sa.recordEvent("previewAvailable", out.written());
    }

    /// P09-T4: Emite un evento de degradación con mensaje accionable.
    fn emitDesignDegradation(ctx: *FanoutContext, task_id: []const u8, msg: []const u8) void {
        const allocator = ctx.sa.allocator;
        var out: std.Io.Writer.Allocating = .init(allocator);
        defer out.deinit();
        var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
        js.beginObject() catch return;
        js.objectField("task_id") catch return;
        js.write(task_id) catch return;
        js.objectField("error") catch return;
        js.write(msg) catch return;
        js.objectField("source") catch return;
        js.write("open-design") catch return;
        js.endObject() catch return;
        // MULTISESSION-P0: mismo mutex por dispatch que el resto de FanoutContext.
        ctx.mutex.lock();
        defer ctx.mutex.unlock();
        ctx.sa.recordEvent("design_degraded", out.written());
    }

    /// Ejecuta una tarea con su modelo asignado (o mock/inyectado) y actualiza el
    /// contexto compartido bajo mutex. Se invoca desde cada hilo de una ola.
    /// MODELO-LOCAL: ¿la tarea va a correr sobre un proveedor de la máquina
    /// (Ollama)? La fuente de verdad es la ASIGNACIÓN resuelta (pin, enjambre
    /// o router ya aplicados); si no la hay, el camino de respaldo del worker
    /// usa el pin del rol (pinFor), así que también se consulta.
    fn taskUsesLocalProvider(ctx: *const FanoutContext, pt: planner.PlannedTask) bool {
        if (findAssignment(ctx.outcome.assignments, pt.id)) |a| {
            if (a.assigned and providers.providers.isLocalProviderName(a.provider_name)) return true;
        }
        const pin = ctx.sa.pinFor(pt.task_type);
        if (pin.provider) |p| return providers.providers.isLocalProviderName(p);
        return false;
    }

    fn recordVisionAllocationFailure(ctx: *FanoutContext, task_id: []const u8, failure: anyerror) void {
        ctx.mutex.lock();
        defer ctx.mutex.unlock();
        ctx.failed += 1;
        std.debug.print("[vision dispatch] task {s}: {s}\n", .{ task_id, @errorName(failure) });
        var event_buf: [4096]u8 = undefined;
        const event = std.fmt.bufPrint(&event_buf, "{{\"task_id\":{f},\"success\":false,\"cause\":\"allocation_failed\",\"error_msg\":\"OutOfMemory\"}}", .{std.json.fmt(task_id, .{})}) catch |format_error| {
            std.debug.print("[vision dispatch] failure event: {s}\n", .{@errorName(format_error)});
            ctx.sa.recordEvent("task_failed", "{\"success\":false,\"cause\":\"allocation_failed\",\"error_msg\":\"OutOfMemory; task identifier exceeds event buffer\"}");
            return;
        };
        ctx.sa.recordEvent("task_failed", event);
    }

    fn runTaskInWave(ctx: *FanoutContext, pt: planner.PlannedTask) void {
        const allocator = ctx.sa.allocator;

        // ORDER-ROOT-WORKERS: este código corre en hilos worker (spawn) donde el
        // override TLS no existe, y también síncrono en el hilo de dispatch
        // (rerunRecoveredConsumers / fallback de spawn) donde ya está puesto.
        // Guardar el valor previo y restaurarlo al salir cubre ambos casos.
        var prev_root_buf: [4096]u8 = undefined;
        const prev_root: ?[]const u8 = workspace.getOrderRootOverride(&prev_root_buf);
        if (ctx.order_root) |orr| workspace.setOrderRootOverride(orr);
        defer if (ctx.order_root != null) workspace.setOrderRootOverride(prev_root);

        // P0-DAG: una tarea consumidora nunca puede ejecutarse si un productor
        // requerido falló o no produjo resultado. Antes testing/auditoria corrían
        // igualmente y podían inventar PASS sobre un archivo inexistente (orden 356).
        const asg = findAssignment(ctx.outcome.assignments, pt.id);
        const vision_unavailable = pt.needs_vision and (ctx.images.len == 0 or asg == null or !asg.?.assigned or !ctx.sa.visionMeasured(asg.?.provider_name, asg.?.model_name));
        ctx.mutex.lock();
        const deps_ok = dependenciesSucceeded(allocator, pt, ctx.outcome.plan.tasks, ctx.results.items);
        if (!deps_ok or vision_unavailable) {
            const failure_reason = if (vision_unavailable) "ningún modelo con visión medida disponible" else "dependency failed or missing";
            ctx.failed += 1;
            const run_res = TaskRunResult{
                .task_id = allocator.dupe(u8, pt.id) catch "",
                .artifacts = &.{},
                .success = false,
                .error_msg = allocator.dupe(u8, failure_reason) catch "",
                .integrated = false,
                .model_used = allocator.dupe(u8, "not-run") catch "",
                .exec = .{ .ran = false, .exit_code = 0, .needs_approval = false, .stderr = allocator.dupe(u8, failure_reason) catch "" },
                .saved_path = null,
            };
            ctx.results.append(allocator, run_res) catch {};
            var out: std.Io.Writer.Allocating = .init(allocator);
            defer out.deinit();
            var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
            js.beginObject() catch {};
            js.objectField("task_id") catch {};
            js.write(pt.id) catch {};
            js.objectField("worker_id") catch {};
            js.write(pt.id) catch {};
            js.objectField("success") catch {};
            js.write(false) catch {};
            js.objectField("cause") catch {};
            js.write(if (vision_unavailable) "vision_unavailable" else "dependency_failed") catch {};
            js.objectField("error_msg") catch {};
            js.write(failure_reason) catch {};
            if (findAssignment(ctx.outcome.assignments, pt.id)) |a| {
                js.objectField("provider") catch {};
                js.write(a.provider_name) catch {};
                js.objectField("assigned_model") catch {};
                js.write(a.model_name) catch {};
            }
            js.objectField("model_used") catch {};
            js.write("not-run") catch {};
            js.objectField("integrated") catch {};
            js.write(false) catch {};
            js.endObject() catch {};
            ctx.sa.recordEvent("task_failed", out.written());
            ctx.mutex.unlock();
            return;
        }
        ctx.mutex.unlock();

        // P12-T3: Find per-task selection if available.
        var task_sel: ?*const tool_discovery.TaskSelection = null;
        if (ctx.task_selections) |selections| {
            for (selections) |*ts| {
                if (std.mem.eql(u8, ts.task_id, pt.id)) {
                    task_sel = ts;
                    break;
                }
            }
        }
        const effective_resources: []const tool_discovery.Resource = if (task_sel) |ts| ts.needed else ctx.needed_resources;
        const selection_reason: []const u8 = if (task_sel) |ts| ts.reason else "";

        // F0: emitir evento task_started (P06: enriquecido con model, provider, description, skills, mcps)
        // P12-T3: skills/mcps son las ELEGIDAS por-tarea + reason del selector.
        // MULTISESSION-P0 (2026-07-12): mutex por dispatch — recordEvent no se
        // coordina solo, y este bloque corre en cada hilo de la ola en paralelo.
        {
            ctx.mutex.lock();
            defer ctx.mutex.unlock();
            var out: std.Io.Writer.Allocating = .init(allocator);
            defer out.deinit();
            var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
            js.beginObject() catch {};
            js.objectField("task_id") catch {};
            js.write(pt.id) catch {};
            js.objectField("worker_id") catch {};
            js.write(pt.id) catch {};
            js.objectField("department") catch {};
            js.write(pt.department) catch {};
            js.objectField("task_type") catch {};
            js.write(@tagName(pt.task_type)) catch {};
            js.objectField("description") catch {};
            js.write(pt.description) catch {};
            // P06: modelo y provider asignados por el router
            if (asg) |a| {
                if (a.assigned) {
                    js.objectField("model") catch {};
                    js.write(a.model_name) catch {};
                    js.objectField("provider") catch {};
                    js.write(a.provider_name) catch {};
                }
            }
            // P12-T3: skills y MCPs ELEGIDAS para esta tarea (no todas las disponibles)
            js.objectField("skills") catch {};
            js.beginArray() catch {};
            for (effective_resources) |r| {
                if (r.kind == .skill) js.write(r.name) catch {};
            }
            js.endArray() catch {};
            js.objectField("mcps") catch {};
            js.beginArray() catch {};
            for (effective_resources) |r| {
                if (r.kind == .mcp_server or r.kind == .mcp_tool) js.write(r.name) catch {};
            }
            js.endArray() catch {};
            // P12-T3: reason del selector agéntico
            if (selection_reason.len > 0) {
                js.objectField("selection_reason") catch {};
                js.write(selection_reason) catch {};
            }
            js.endObject() catch {};
            ctx.sa.recordEvent("task_started", out.written());
            // CHECKPOINT-T2: la tarea empieza a correr — si el proceso muere
            // aquí dentro, el checkpoint la declara NO completada y la
            // reanudación la re-ejecuta entera (no hay continuidad interna).
            if (ctx.outcome.plan_id) |pid| {
                ctx.sa.persistTaskCheckpoint(pid, pt.id, "running");
            }
        }

        var tools_block: ?[]const u8 = null;
        defer if (tools_block) |t| allocator.free(t);
        // P12-T3: formatToolBlock usa solo las herramientas elegidas para esta tarea.
        tools_block = formatToolBlock(allocator, effective_resources) catch null;

        // F2: Web search para tareas investigar — buscar antes del LLM e inyectar resultados.
        var web_search_owned: ?[]const u8 = null;
        defer if (web_search_owned) |wso| allocator.free(wso);

        // D7 — contexto POR SUBAGENTE, no uno solo para toda la ola.
        //
        // Antes: `ctx.current_upstream` era un unico bloque con TODOS los
        // artefactos guardados, concatenados en orden de guardado y cortados al
        // llegar a 32 KB. Dos defectos en una linea: cada rama veia lo de las
        // demas, y la primera en guardar se comia el presupuesto de las otras.
        //
        // Ahora cada tarea recibe solo lo de sus ANCESTROS (cierre transitivo de
        // `depends_on`), con su parte del tope. Excepcion deliberada: auditar y
        // testear ven la entrega entera — la entrega es la ORDEN, y aislar al
        // auditor reabriria M4 (ordenes #184 y #186).
        //
        // Si algo falla al construirlo se cae al bloque comun de la ola, que es
        // lo que habia antes: degradar es aceptable, quedarse sin contexto no.
        const context_budget = subagent.presupuestoPorRama(ctx.outcome.plan.tasks.len).bytes_contexto;
        var subagent_upstream: ?[]const u8 = null;
        defer if (subagent_upstream) |su| allocator.free(su);
        {
            ctx.mutex.lock();
            const visibles = subagent.indicesVisibles(
                allocator,
                ctx.outcome.plan.tasks,
                pt.id,
                pt.task_type,
                ctx.saved.items,
                ctx.saved_owner.items,
            ) catch &[_]usize{};
            defer allocator.free(visibles);
            var rutas = std.ArrayList([]const u8).empty;
            defer rutas.deinit(allocator);
            for (visibles) |i| rutas.append(allocator, ctx.saved.items[i]) catch {};
            subagent_upstream = buildUpstreamContextCapped(allocator, rutas.items, context_budget) catch null;
            ctx.mutex.unlock();
        }

        var effective_upstream: ?[]const u8 = subagent_upstream orelse ctx.current_upstream;
        var audit_upstream_owned: ?[]const u8 = null;
        defer if (audit_upstream_owned) |owned| allocator.free(owned);
        if (pt.task_type == .auditar) {
            const upstream_marker_reserve = if (effective_upstream != null) @min(context_budget, audit_upstream_truncated_marker.len) else 0;
            const qa_budget = @min(max_audit_qa_bytes, context_budget - upstream_marker_reserve);
            ctx.mutex.lock();
            const evidence = buildAuditTestContext(allocator, ctx.outcome.plan.tasks, pt.id, ctx.results.items, qa_budget) catch null;
            ctx.mutex.unlock();
            if (evidence) |block| {
                defer allocator.free(block);
                audit_upstream_owned = combineAuditContextWithinBudget(allocator, block, effective_upstream, context_budget) catch null;
                if (audit_upstream_owned) |owned| effective_upstream = owned;
            }
        }
        if (pt.task_type == .investigar) {
            if (performWebSearchForTask(allocator, ctx, pt.description)) |ws| {
                defer allocator.free(ws);
                web_search_owned = combineSearchUpstreamContext(allocator, ws, effective_upstream, context_budget) catch null;
                if (web_search_owned) |wso| effective_upstream = wso;
            } else |e| {
                // GOBERNANZA-WEBSEARCH (FASE-AGENTIC-2): antes este error se tragaba
                // en silencio (catch null) — el worker respondía con lo que sabe de
                // memoria SIN decir que la búsqueda real falló, y el usuario recibía
                // una "comparativa" que en realidad nunca consultó la web. Ahora se
                // avisa con un evento visible Y se le dice HONESTAMENTE al worker en
                // su propio contexto que la búsqueda falló, para que su respuesta
                // (que synthesizeFinalAnswer muestra tal cual al usuario) no finja
                // haber buscado cuando no pudo.
                const reason = webSearchFailureReason(e);
                {
                    // MULTISESSION-P0: mismo mutex por dispatch que el resto de FanoutContext.
                    ctx.mutex.lock();
                    defer ctx.mutex.unlock();
                    var wf_out: std.Io.Writer.Allocating = .init(allocator);
                    defer wf_out.deinit();
                    var wf_js: std.json.Stringify = .{ .writer = &wf_out.writer, .options = .{} };
                    wf_js.beginObject() catch {};
                    wf_js.objectField("query") catch {};
                    wf_js.write(pt.description) catch {};
                    wf_js.objectField("reason") catch {};
                    wf_js.write(reason) catch {};
                    wf_js.endObject() catch {};
                    ctx.sa.recordEvent("web_search_failed", wf_out.written());
                }
                const note = std.fmt.allocPrint(
                    allocator,
                    "[BUSQUEDA WEB FALLIDA: {s}]\nNo se pudo consultar la web para esta tarea. En tu respuesta, di explícitamente que no pudiste verificar esto con una búsqueda en vivo — no finjas haber buscado ni inventes URLs.\n\n{s}",
                    .{ reason, ctx.current_upstream orelse "" },
                ) catch null;
                if (note) |n| {
                    web_search_owned = n;
                    effective_upstream = n;
                }
            }
        }

        var sb = ctx.sa.sandboxForTask(pt.id) catch {
            ctx.mutex.lock();
            defer ctx.mutex.unlock();
            ctx.failed += 1;
            const run_res = TaskRunResult{
                .task_id = allocator.dupe(u8, pt.id) catch "",
                .artifacts = &.{},
                .success = false,
                .error_msg = allocator.dupe(u8, "sandbox failed") catch "",
                .integrated = false,
                .model_used = allocator.dupe(u8, "mock") catch "",
                .exec = .{ .ran = false, .exit_code = 0, .needs_approval = false, .stderr = allocator.dupe(u8, "") catch "" },
                .saved_path = null,
            };
            ctx.results.append(allocator, run_res) catch {};
            return;
        };
        defer sb.deinit();

        // P-EXEC-3: Para tareas `ejecutar`, resolver el comando DETERMINISTAMENTE
        // (sin worker LLM). El comando viene del plan (deps o description), no de un
        // artefacto del worker. Si se resuelve, se ejecuta y se salta el worker.
        if (pt.task_type == .ejecutar) {
            var det_exec = ExecOutcome{
                .ran = false,
                .exit_code = 0,
                .needs_approval = false,
                .stderr = "",
            };
            var det_resolved = false;

            // (a) Dependencia productora con saved_path (caso "crea y ejecuta").
            for (pt.depends_on) |dep_id| {
                var dep_path_owned: ?[]u8 = null;
                ctx.mutex.lock();
                for (ctx.results.items) |res| {
                    if (std.mem.eql(u8, res.task_id, dep_id) and res.saved_path != null) {
                        dep_path_owned = allocator.dupe(u8, res.saved_path.?) catch null;
                        break;
                    }
                }
                ctx.mutex.unlock();
                if (dep_path_owned) |dep_path| {
                    defer allocator.free(dep_path);
                    ctx.mutex.lock();
                    det_exec = ctx.sa.governedExecute(dep_path, pt.id, &ctx.outputs, &ctx.pending) catch |e| ExecOutcome{
                        .ran = false,
                        .exit_code = 0,
                        .needs_approval = false,
                        .stderr = allocator.dupe(u8, @errorName(e)) catch "",
                    };
                    ctx.mutex.unlock();
                    det_resolved = det_exec.ran or det_exec.needs_approval;
                }
                if (det_resolved) break;
            }

            // (b) Comando en contract_field `command` (P-EXEC-5: valor
            //     estructurado). commandToParsed aplica la misma política que
            //     la ruta post-worker: exe allowlisted directo, sintaxis de
            //     shell envuelta, intérpretes sujetos a aprobación y prosa rechazada.
            if (!det_resolved) {
                if (extractCommandFromContract(pt.contract_fields)) |cmd| {
                    var parsed_opt = commandToParsed(allocator, cmd) catch null;
                    if (parsed_opt) |*parsed| {
                        defer parsed.deinit();
                        ctx.mutex.lock();
                        det_exec = ctx.sa.governedExecuteRaw(parsed.exe, parsed.args, pt.id, &ctx.outputs, &ctx.pending) catch |e| ExecOutcome{
                            .ran = false,
                            .exit_code = 0,
                            .needs_approval = false,
                            .stderr = allocator.dupe(u8, @errorName(e)) catch "",
                        };
                        ctx.mutex.unlock();
                        det_resolved = det_exec.ran or det_exec.needs_approval;
                    }
                }
            }

            // (c) Comando en la description (prefijo "Ejecutar <cmd>").
            if (!det_resolved) {
                if (extractCommandFromDesc(pt.description)) |cmd| {
                    var parsed_opt = commandToParsed(allocator, cmd) catch null;
                    if (parsed_opt) |*parsed| {
                        defer parsed.deinit();
                        ctx.mutex.lock();
                        det_exec = ctx.sa.governedExecuteRaw(parsed.exe, parsed.args, pt.id, &ctx.outputs, &ctx.pending) catch |e| ExecOutcome{
                            .ran = false,
                            .exit_code = 0,
                            .needs_approval = false,
                            .stderr = allocator.dupe(u8, @errorName(e)) catch "",
                        };
                        ctx.mutex.unlock();
                        det_resolved = det_exec.ran or det_exec.needs_approval;
                    }
                }
            }

            if (det_resolved) {
                // Comando ejecutado deterministamente — skip worker, registrar resultado.
                ctx.mutex.lock();
                defer ctx.mutex.unlock();

                // R2-1: la marca de uso sin argumentos vive en
                // governedExecute (ejecucion por archivo). Las rutas raw de aqui
                // llevan parsed.args y un fallo suyo es real.
                const det_success = taskExecutionSucceeded(.ejecutar, true, true, det_exec);
                if (det_success) ctx.completed += 1 else ctx.failed += 1;
                ctx.integrated += 1;

                var run_res = TaskRunResult{
                    .task_id = allocator.dupe(u8, pt.id) catch "",
                    .artifacts = &.{},
                    .success = det_success,
                    .error_msg = allocator.dupe(u8, "") catch "",
                    .integrated = true,
                    .model_used = allocator.dupe(u8, "deterministic") catch "",
                    .exec = det_exec,
                    .saved_path = null,
                };
                recordOmittedExecution(ctx, &run_res, dependencySavedPath(pt, ctx.results.items) orelse "");
                ctx.results.append(allocator, run_res) catch {};

                // F0: emit task_done/task_failed.
                {
                    var out: std.Io.Writer.Allocating = .init(allocator);
                    defer out.deinit();
                    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
                    js.beginObject() catch {};
                    js.objectField("task_id") catch {};
                    js.write(pt.id) catch {};
                    js.objectField("worker_id") catch {};
                    js.write(pt.id) catch {};
                    js.objectField("success") catch {};
                    js.write(det_success) catch {};
                    js.objectField("model_used") catch {};
                    js.write("deterministic") catch {};
                    js.objectField("integrated") catch {};
                    js.write(true) catch {};
                    if (det_exec.usage_only) {
                        js.objectField("exec_omitted") catch {};
                        js.write(true) catch {};
                        js.objectField("exec_omitted_reason") catch {};
                        js.write("programa_requiere_argumentos") catch {};
                    }
                    if (!det_success) {
                        const cause: []const u8 = if (det_exec.needs_approval) "approval_required" else if (det_exec.timed_out) "execution_timeout" else "execution_failed";
                        const err = if (det_exec.stderr.len > 0) det_exec.stderr else cause;
                        js.objectField("cause") catch {};
                        js.write(cause) catch {};
                        js.objectField("error_msg") catch {};
                        js.write(err) catch {};
                        if (asg) |a| {
                            js.objectField("provider") catch {};
                            js.write(a.provider_name) catch {};
                            js.objectField("assigned_model") catch {};
                            js.write(a.model_name) catch {};
                        }
                    }
                    js.endObject() catch {};
                    ctx.sa.recordEvent(if (det_success) "task_done" else "task_failed", out.written());
                }
                return;
            }
            // No resuelto deterministamente — caer al worker LLM como fallback.
        }

        // UI-ACTION: una tarea `ui` NUNCA llama a un modelo. El plan declara la
        // acción en contract_fields (`action` + args conocidos); el ejecutor la
        // valida contra el allowlist y emite un evento `ui_action` que la cabina
        // aplica al drenar eventos de la orden. Acción desconocida → task_failed
        // honesto (nunca se inventa ni se ejecuta nada fuera del allowlist).
        if (pt.task_type == .ui) {
            ctx.mutex.lock();
            defer ctx.mutex.unlock();

            const ui_payload = buildUiActionPayload(allocator, pt);
            const ui_ok = ui_payload != null;
            defer if (ui_payload) |p| allocator.free(p);

            if (ui_payload) |payload| {
                ctx.sa.recordEvent("ui_action", payload);
            }
            if (ui_ok) ctx.completed += 1 else ctx.failed += 1;
            ctx.integrated += 1;

            const run_res = TaskRunResult{
                .task_id = allocator.dupe(u8, pt.id) catch "",
                .artifacts = &.{},
                .success = ui_ok,
                .error_msg = if (ui_ok) allocator.dupe(u8, "") catch "" else allocator.dupe(u8, "ui_action no válida o fuera del allowlist") catch "",
                .integrated = true,
                .model_used = allocator.dupe(u8, "deterministic") catch "",
                .exec = .{ .ran = false, .exit_code = 0, .needs_approval = false, .stderr = "" },
                .saved_path = null,
            };
            ctx.results.append(allocator, run_res) catch {};

            {
                var out: std.Io.Writer.Allocating = .init(allocator);
                defer out.deinit();
                var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
                js.beginObject() catch {};
                js.objectField("task_id") catch {};
                js.write(pt.id) catch {};
                js.objectField("worker_id") catch {};
                js.write(pt.id) catch {};
                js.objectField("success") catch {};
                js.write(ui_ok) catch {};
                js.objectField("model_used") catch {};
                js.write("deterministic") catch {};
                js.objectField("integrated") catch {};
                js.write(true) catch {};
                if (!ui_ok) {
                    js.objectField("cause") catch {};
                    js.write("ui_action_rejected") catch {};
                    js.objectField("error_msg") catch {};
                    js.write("ui_action no válida o fuera del allowlist") catch {};
                }
                js.endObject() catch {};
                ctx.sa.recordEvent(if (ui_ok) "task_done" else "task_failed", out.written());
            }
            return;
        }

        var model_used: []const u8 = if (ctx.llm_fn != null) "generic" else "mock";
        var model_used_owned: ?[]u8 = null;
        defer if (model_used_owned) |owned| allocator.free(owned);

        const command_only_test = commandOnlyTest(pt);
        const result = blk: {
            if (pt.needs_vision and (ctx.images.len == 0 or asg == null or !asg.?.assigned))
                break :blk visionUnavailableResult(allocator, pt.id) catch |e| {
                    recordVisionAllocationFailure(ctx, pt.id, e);
                    return;
                };
            // El contrato ya contiene todo el trabajo: validar y ejecutar ese
            // comando no requiere generar otra afirmación con un proveedor.
            // El gate QA posterior decide éxito usando el proceso real.
            if (command_only_test) {
                model_used = "deterministic";
                break :blk commandTestArtifact(allocator, pt) catch return;
            }
            // / E-GOV.3 (rama e5-gov, reaplicado el 11-nov): una
            // asignación restaurada (reanudación) no puede saltarse el ejecutor
            // que el usuario fijó después. Se falla ANTES de llamar a nadie, con
            // los dos nombres, en vez de ejecutar el modelo viejo o un respaldo.
            const active_pin = ctx.sa.pinFor(pt.task_type);
            if (active_pin.provider) |pinned_provider| {
                const pinned_model = active_pin.model orelse "";
                // Adaptado: una tarea SIN asignación usable ya falla más abajo
                // con su causa (sin clave, enjambre agotado); aquí solo se corta
                // la asignación que existe y apunta a otro ejecutor.
                const mismatch = if (asg) |assigned_choice|
                    assigned_choice.assigned and active_pin.model != null and
                        (!std.ascii.eqlIgnoreCase(assigned_choice.provider_name, pinned_provider) or !std.mem.eql(u8, assigned_choice.model_name, pinned_model))
                else
                    false;
                if (mismatch) {
                    model_used = pinned_model;
                    const message = std.fmt.allocPrint(allocator, "PIN_ASSIGNMENT_MISMATCH: elegido {s}/{s}; asignación {s}/{s}; no se ejecutó ningún modelo", .{ pinned_provider, pinned_model, if (asg) |assigned_choice| assigned_choice.provider_name else "sin proveedor", if (asg) |assigned_choice| assigned_choice.model_name else "sin modelo" }) catch return;
                    const task_id = allocator.dupe(u8, pt.id) catch {
                        allocator.free(message);
                        return;
                    };
                    break :blk worker_backend.WorkerResult{ .task_id = task_id, .artifacts = &.{}, .success = false, .error_msg = message };
                }
            }
            // Preferir modelo asignado por el router + LiveLlm.initForced si hay catalog_path.
            // E5.08: el chequeo `agent:` va FUERA del guard de catalog_path —
            // un agente externo es un proceso CLI, no depende del catálogo.
            if (asg) |a| {
                if (a.assigned) {
                    const system_prompt = ctx.sa.systemPromptForTask(pt.department, pt.task_type, pt.description) catch |e| {
                        break :blk worker_backend.WorkerResult{ .task_id = allocator.dupe(u8, pt.id) catch "", .artifacts = &.{}, .success = false, .error_msg = std.fmt.allocPrint(allocator, "system_prompt failed: {s}", .{@errorName(e)}) catch "" };
                    };
                    defer allocator.free(system_prompt);
                    // FIX-5 / FALLBACK-01: intentar el primario y, ante FALLO, los respaldos
                    // del router (free-tier-first con fallback, prompt madre 1.9). Un éxito
                    // corta el loop; en el último candidato se devuelve su resultado (honesto).
                    const total_choices = 1 + a.fallbacks.len;
                    // un ejecutor FIJADO por el usuario (pin de
                    // rol, ROLES-MODELO) no cae a otro proveedor en silencio.
                    // Antes de este cambio, un fallo del CLI fijado (orden
                    // #890: Claude Code salió con código 1 en 2,8 s) seguía la
                    // cadena de respaldos y el chat presentaba el trabajo de
                    // otro proveedor como si lo hubiera hecho el fijado. El
                    // único permiso explícito de respaldo vigente es
                    // DEVAGENTS_LOCAL_ALLOW_FALLBACK (modelos locales, ya
                    // aplicado en assignModel); un pin de rol no lo tiene →
                    // la tarea falla con el motivo real y sin provider_fallback.
                    const exec_pin = ctx.sa.pinFor(pt.task_type);
                    const pinned_executor = exec_pin.provider != null and exec_pin.model != null;
                    const pin_fallback_allowed = pinned_executor and
                        providers.providers.isLocalProviderName(exec_pin.provider.?) and
                        providers.providers.envFlagEnabled("DEVAGENTS_LOCAL_ALLOW_FALLBACK");
                    const strict_pin = pinned_executor and !pin_fallback_allowed;
                    var ci: usize = 0;
                    var previous_provider: ?[]const u8 = null;
                    var previous_model: ?[]const u8 = null;
                    // Motivo del último candidato fallido: viaja al evento
                    // provider_fallback y a la nota de respaldo del resumen.
                    var previous_failure_reason: ?[]u8 = null;
                    defer if (previous_failure_reason) |reason| allocator.free(reason);
                    while (ci < total_choices) : (ci += 1) {
                        const prov = if (ci == 0) a.provider_name else a.fallbacks[ci - 1].provider_name;
                        const mdl = if (ci == 0) a.model_name else a.fallbacks[ci - 1].model_name;
                        if (ctx.sa.deterministic and ci > 0) break;
                        if (previous_provider) |previous| {
                            if (std.mem.eql(u8, previous, prov) and std.mem.eql(u8, previous_model.?, mdl)) continue;
                        }
                        if (pt.needs_vision and !ctx.sa.visionMeasured(prov, mdl)) continue;
                        const attempt_event = std.json.Stringify.valueAlloc(allocator, .{ .task_id = pt.id, .provider = prov, .model = mdl, .from_provider = previous_provider, .from_model = previous_model, .to_provider = prov, .to_model = mdl, .reason = previous_failure_reason orelse "" }, .{}) catch return;
                        ctx.mutex.lock();
                        ctx.sa.recordEvent(if (previous_provider != null) "provider_fallback" else "provider_attempt", attempt_event);
                        if (previous_provider) |from_prov| {
                            ctx.sa.recordFallbackNote(ctx, pt.id, from_prov, previous_model.?, previous_failure_reason orelse "sin detalle del ejecutor", prov, mdl);
                        }
                        ctx.mutex.unlock();
                        allocator.free(attempt_event);
                        previous_provider = prov;
                        previous_model = mdl;
                        // E5.08 — GOBIERNO ENCIMA: un proveedor `agent:<cli>` va por
                        // la rama del agente externo (worker headless o ACP) con el
                        // MISMO WorkerResult, gates, eventos, auditoría, ship y
                        // checkpoint/resume que el worker nativo — no es una
                        // tubería paralela. La cadena de respaldo se comporta
                        // igual: éxito o último candidato devuelven el resultado.
                        if (external_agents.metaForProvider(prov)) |agent_meta| {
                            model_used = mdl;
                            const ext_res = dispatchExternalAgent(ctx, allocator, pt, agent_meta, prov, mdl);
                            if (ext_res.success) break :blk ext_res;
                            // el ejecutor fijado que falla NO se
                            // sustituye por otro proveedor por defecto.
                            if (strict_pin) break :blk pinnedExecutorFailed(allocator, prov, mdl, ext_res);
                            if (ci + 1 == total_choices) break :blk ext_res;
                            rememberFailureReason(&previous_failure_reason, allocator, ext_res.error_msg);
                            ext_res.deinit(allocator);
                            continue;
                        }
                        // Candidato de catálogo sin catalog_path: cae al
                        // fallback llm_fn de abajo (comportamiento previo).
                        const cp = ctx.catalog_path orelse break;
                        // ModelAssignment ya administra el primario y sus fallbacks.
                        // Cada vuelta debe probar SOLO ese candidato; initForced añade
                        // otra cadena interna y producía intentos combinatorios.
                        var llm_opt = live_worker.LiveLlm.initExact(allocator, cp, prov, mdl);
                        if (llm_opt) |*llm| {
                            defer llm.deinit();
                            if (pt.needs_vision) llm.images = ctx.images;
                            llm.setOwnedHealthConnFromCatalogPath();
                            var tool_root_buf: [4096]u8 = undefined;
                            const tool_root = workspace.effectiveRoot(&tool_root_buf);
                            // D-C1 (E5.11): el modo de tools se decide por el
                            // modelo EFECTIVO de este candidato — `agentic`
                            // solo con cap_tool_calls medida en vivo; si no,
                            // cae a `none` y queda el evento agentic_unavailable.
                            const tool_mode = resolveTaskToolMode(ctx, allocator, pt.task_type, pt.id, prov, mdl);
                            configureTaskLiveLlm(
                                llm,
                                tool_mode,
                                tool_root,
                                ctx.sa.permission_config,
                                ctx.sa.plan_approved,
                                ctx.sa.order_origin,
                                ctx.sa.executor_spawn_fn,
                                ctx.cancel_token,
                                ctx.sa.max_agent_iterations,
                            );
                            // TELEMETRIA-FANOUT: `event_conn` aquí NO es el handle por el
                            // que se escribe. Es la señal de "este propietario quiere eventos":
                            // `callWithDeadline` abre una conexión PROPIA por llamada
                            // (`owned_event_conn`, live_worker.zig) y emite por ella. Eso
                            // es justo lo que desactiva el segfault que este punto temía
                            // —varios hilos fanout compartiendo un solo `sqlite3*`—, en
                            // vez de renunciar a la telemetría para esquivarlo.
                            //
                            // Sin esta línea, el despacho del CLI —y con él `selftest`—
                            // perdía TODA la traza del worker: cero `content_delta` y cero
                            // filas en `usage_records`, mientras la cabina sí las dejaba.
                            // Dos caminos otra vez: uno midiendo el gasto y el otro a
                            // ciegas. Con el modo de pago activo, el gate quemaba cuota
                            // sin dejar un solo apunte contable.
                            //
                            // No duplica nada: `emitLlmAttempts` emite `task_provider_*`
                            // bajo el mutex del despacho; lo de aquí son `content_delta`,
                            // `provider_failed`/`provider_fallback` y la fila de consumo.
                            // Ambos conviven ya en la cabina desde siempre.
                            if (ctx.sa.event_conn) |ec| {
                                llm.setEventConn(ec, ctx.sa.event_order_id);
                            }
                            llm.task_id = pt.id;
                            llm.handoff_required = ci > 0;
                            bindTaskBrowser(llm, ctx.browser, pt.id);
                            // D-C1 (E5.11): el modo agéntico corre su propio
                            // camino — sesión de tools + artefactos del diff,
                            // nunca el parser de array JSON del worker nativo.
                            if (tool_mode == .agentic) {
                                const r = runAgenticTask(ctx, allocator, pt, llm, system_prompt, effective_upstream);
                                emitLlmAttempts(ctx, pt, llm);
                                if (llm.handoff_blocked) {
                                    r.deinit(allocator);
                                    const reason = std.fmt.allocPrint(allocator, "HANDOFF_BLOCKED: {s}", .{llm.last_error_name}) catch return;
                                    defer allocator.free(reason);
                                    break :blk externalFail(allocator, pt.id, reason);
                                }
                                if (r.success) break :blk r;
                                if (strict_pin) break :blk pinnedExecutorFailed(allocator, prov, mdl, r);
                                if (ci + 1 == total_choices) break :blk r;
                                rememberFailureReason(&previous_failure_reason, allocator, r.error_msg);
                                r.deinit(allocator);
                                continue;
                            }
                            var nw = worker_backend.NativeWorker.init(system_prompt);
                            nw.enableDeterministicFallback();
                            if (tools_block) |t| nw.setAvailableTools(t);
                            if (effective_upstream) |uc| nw.setUpstreamContext(uc);
                            if (ctx.plan_manifest) |pm| nw.setPlanManifest(pm);
                            if (ctx.repo_map_text) |mt| nw.setRepoMapContext(mt);
                            nw.setLlmFn(llm, live_worker.LiveLlm.llmFn);
                            model_used = mdl;
                            const r = nw.backend().run(allocator, pt, sb) catch |e| {
                                emitLlmAttempts(ctx, pt, llm);
                                // AUDIT-UNAVAILABLE-P0: la causa REAL del fallo viaja en
                                // error_msg ("native worker failed" a secas borraba si fue
                                // LlmCallFailed, InvalidArtifact o Timeout — justo lo que
                                // distingue un auditor sin respuesta de un fallo de otro tipo).
                                if (strict_pin or ci + 1 == total_choices or llm.handoff_blocked or std.mem.eql(u8, llm.last_error_name, "BudgetDenied")) {
                                    var status_buf: [32]u8 = undefined;
                                    const status = if (llm.last_http_failure.http_status) |code| std.fmt.bufPrint(&status_buf, "HTTP {d}", .{code}) catch "HTTP desconocido" else "sin respuesta HTTP";
                                    const budget_reason = if (std.mem.eql(u8, llm.last_error_name, "BudgetDenied") and llm.cm != null) @import("spend_budget.zig").motivoDenegacion(allocator, prov, mdl, @import("spend_budget.zig").estado(llm.cm.?.db)) catch null else null;
                                    defer if (budget_reason) |owned| allocator.free(owned);
                                    const reason = if (budget_reason) |detail| detail else if (std.mem.eql(u8, llm.last_error_name, "Timeout")) "timeout: el proveedor no respondio dentro del plazo" else if (llm.last_http_failure.http_status == null and llm.last_error_name.len == 0) "respuesta vacia o sin artefactos validos" else llm.last_http_failure.reason();
                                    const built = worker_backend.WorkerResult{ .task_id = allocator.dupe(u8, pt.id) catch "", .artifacts = &.{}, .success = false, .paid_budget_exhausted = std.mem.eql(u8, llm.last_error_name, "BudgetDenied"), .error_msg = std.fmt.allocPrint(allocator, "{s}/{s}: {s}; {s}; {s}; {s}", .{ prov, mdl, if (llm.handoff_blocked) "HANDOFF_BLOCKED" else if (llm.last_error_name.len > 0) llm.last_error_name else @errorName(e), status, if (llm.handoff_blocked) llm.last_error_name else reason, llm.last_http_failure.message() }) catch (allocator.dupe(u8, "native worker failed") catch "") };
                                    // un pin fijado no cae a otro proveedor.
                                    break :blk if (strict_pin) pinnedExecutorFailed(allocator, prov, mdl, built) else built;
                                }
                                // el motivo del fallo viaja al
                                // provider_fallback del siguiente candidato.
                                rememberFailureReason(&previous_failure_reason, allocator, if (llm.last_http_failure.reason().len > 0) llm.last_http_failure.reason() else if (llm.last_error_name.len > 0) llm.last_error_name else @errorName(e));
                                continue;
                            };
                            // Los intentos de ESTA tarea se emiten aquí, con el
                            // mutex del despacho, porque el LiveLlm por-tarea no
                            // tiene conexión propia a propósito. Sin esto, la
                            // traza solo enseñaba los intentos del selector de
                            // herramientas y parecía que la tarea había probado
                            // modelos que nunca tocó.
                            emitLlmAttempts(ctx, pt, llm);
                            if (llm.handoff_blocked) {
                                r.deinit(allocator);
                                const reason = std.fmt.allocPrint(allocator, "HANDOFF_BLOCKED: {s}", .{llm.last_error_name}) catch return;
                                defer allocator.free(reason);
                                break :blk externalFail(allocator, pt.id, reason);
                            }
                            if (r.success) break :blk r;
                            if (strict_pin) break :blk pinnedExecutorFailed(allocator, prov, mdl, r);
                            if (ci + 1 == total_choices) break :blk r;
                            // worker devolvió success=false y quedan candidatos → descartar y reintentar
                            rememberFailureReason(&previous_failure_reason, allocator, r.error_msg);
                            r.deinit(allocator);
                        }
                    }
                    // ningún candidato pudo inicializarse → caer al fallback de abajo (llm_fn/mock)
                }
            }
            // An unavailable live assignment cannot fall through into a mock success.
            if (ctx.catalog_path != null and (ctx.llm_fn == null or ctx.llm_fn.? == live_worker.LiveLlm.llmFn)) {
                const detail = if (asg) |assignment| std.fmt.allocPrint(allocator, "{s}/{s}: modelo sin candidato elegible o clave activa. {s}", .{ assignment.provider_name, assignment.model_name, assignment.reason }) catch return else allocator.dupe(u8, "sin asignacion de modelo elegible para esta tarea") catch return;
                defer allocator.free(detail);
                break :blk externalFail(allocator, pt.id, detail);
            }
            // Fallback: explicit test injection, or the offline mock without a live catalog.
            if (pt.needs_vision) break :blk visionUnavailableResult(allocator, pt.id) catch |e| {
                recordVisionAllocationFailure(ctx, pt.id, e);
                return;
            };
            if (ctx.llm_fn) |f| {
                const system_prompt = ctx.sa.systemPromptForTask(pt.department, pt.task_type, pt.description) catch return;
                defer allocator.free(system_prompt);
                var nw = worker_backend.NativeWorker.init(system_prompt);
                if (tools_block) |t| nw.setAvailableTools(t);
                if (effective_upstream) |uc| nw.setUpstreamContext(uc);
                if (ctx.plan_manifest) |pm| nw.setPlanManifest(pm);
                if (ctx.repo_map_text) |mt| nw.setRepoMapContext(mt);
                // FIX ALTO: en fallback, si hay catálogo, construimos LiveLlm propia del hilo
                // (buffer propio, sin health_conn/event_conn → sin escrituras concurrentes a db_conn).
                // Si no hay catálogo, serializamos el uso del ctx compartido para evitar carrera.
                const run_result = blk2: {
                    if (if (f == live_worker.LiveLlm.llmFn) ctx.catalog_path else null) |cp| {
                        // Un plan editado lleva asignaciones pendientes. La instancia
                        // privada del worker conserva el pin y el modo de la orden.
                        // ROLES-MODELO: el pin es el del ROL de la tarea — una
                        // auditoría usa el pin de auditor, no el del ejecutor.
                        const task_pin = ctx.sa.pinFor(pt.task_type);
                        const pinned = task_pin.provider != null and task_pin.model != null;
                        var local_llm_opt = if (pinned)
                            (if (ctx.sa.deterministic)
                                live_worker.LiveLlm.initExact(allocator, cp, task_pin.provider.?, task_pin.model.?)
                            else
                                live_worker.LiveLlm.initForced(allocator, cp, task_pin.provider.?, task_pin.model.?))
                        else
                            live_worker.LiveLlm.init(allocator, cp);
                        if (local_llm_opt) |*local_llm| {
                            defer local_llm.deinit();
                            if (!local_llm.setOwnedTraceConn(ctx.sa.event_order_id)) {
                                local_llm.order_id = ctx.sa.event_order_id;
                                local_llm.setOwnedHealthConnFromCatalogPath();
                            }
                            var tool_root_buf: [4096]u8 = undefined;
                            const tool_root = workspace.effectiveRoot(&tool_root_buf);
                            // D-C1 (E5.11): el candidato efectivo de esta rama
                            // es el pin del rol o, sin pin, el primero de la
                            // cadena del router. El gate de capacidad se aplica
                            // sobre ese par, igual que en la rama asignada.
                            const fb_prov: []const u8 = if (pinned) task_pin.provider.? else if (local_llm.lives.len > 0) local_llm.lives[0].cfg.name else "";
                            const fb_mdl: []const u8 = if (pinned) task_pin.model.? else if (local_llm.lives.len > 0) local_llm.lives[0].model else "";
                            const fb_mode = if (fb_mdl.len > 0)
                                resolveTaskToolMode(ctx, allocator, pt.task_type, pt.id, fb_prov, fb_mdl)
                            else
                                taskToolMode(pt.task_type);
                            configureTaskLiveLlm(
                                local_llm,
                                fb_mode,
                                tool_root,
                                ctx.sa.permission_config,
                                ctx.sa.plan_approved,
                                ctx.sa.order_origin,
                                ctx.sa.executor_spawn_fn,
                                ctx.cancel_token,
                                ctx.sa.max_agent_iterations,
                            );
                            bindTaskBrowser(local_llm, ctx.browser, pt.id);
                            // FIX-SEGFAULT-P0: NO inyectar event_conn en LiveLlm local
                            // en hilos fanout — causa escrituras concurrentes a SQLite.
                            local_llm.task_id = pt.id;
                            // D-C1: el modo agéntico corre su propio camino —
                            // sesión de tools + artefactos del diff, nunca el
                            // parser de array JSON del worker nativo.
                            if (fb_mode == .agentic) {
                                const local_result = runAgenticTask(ctx, allocator, pt, local_llm, system_prompt, effective_upstream);
                                setModelUsedFromLive(allocator, local_llm, &model_used, &model_used_owned);
                                ctx.mutex.lock();
                                emitLlmAttempts(ctx, pt, local_llm);
                                ctx.mutex.unlock();
                                break :blk2 local_result;
                            }
                            nw.enableDeterministicFallback();
                            nw.setLlmFn(local_llm, f);
                            const local_result = nw.backend().run(allocator, pt, sb);
                            setModelUsedFromLive(allocator, local_llm, &model_used, &model_used_owned);
                            ctx.mutex.lock();
                            emitLlmAttempts(ctx, pt, local_llm);
                            ctx.mutex.unlock();
                            break :blk2 local_result;
                        }
                        // Un pin no disponible nunca cae a un callback con otro pool.
                        if (pinned) break :blk2 error.LlmCallFailed;
                    }
                    // FIX-SEGFAULT-P0: setEventConn y task_id dentro del mutex para
                    // evitar data race en el llm_ctx compartido.
                    ctx.mutex.lock();
                    defer ctx.mutex.unlock();
                    nw.setLlmFn(ctx.llm_ctx.?, f);
                    if (if (f == live_worker.LiveLlm.llmFn) ctx.sa.event_conn else null) |ec| {
                        const shared_llm: *live_worker.LiveLlm = @ptrCast(@alignCast(ctx.llm_ctx.?));
                        shared_llm.setEventConn(ec, ctx.sa.event_order_id);
                        shared_llm.task_id = pt.id;
                    }
                    const shared_result = nw.backend().run(allocator, pt, sb);
                    if (f == live_worker.LiveLlm.llmFn) {
                        const shared_llm: *live_worker.LiveLlm = @ptrCast(@alignCast(ctx.llm_ctx.?));
                        setModelUsedFromLive(allocator, shared_llm, &model_used, &model_used_owned);
                    }
                    break :blk2 shared_result;
                };
                break :blk run_result catch |e| {
                    break :blk worker_backend.WorkerResult{ .task_id = allocator.dupe(u8, pt.id) catch "", .artifacts = &.{}, .success = false, .error_msg = std.fmt.allocPrint(allocator, "native worker failed: {s}", .{@errorName(e)}) catch (allocator.dupe(u8, "native worker failed") catch "") };
                };
            } else {
                var mw = worker_backend.MockWorker.init();
                break :blk mw.backend().run(allocator, pt, sb) catch |e| {
                    break :blk worker_backend.WorkerResult{ .task_id = allocator.dupe(u8, pt.id) catch "", .artifacts = &.{}, .success = false, .error_msg = std.fmt.allocPrint(allocator, "mock worker failed: {s}", .{@errorName(e)}) catch (allocator.dupe(u8, "mock worker failed") catch "") };
                };
            }
        };
        defer result.deinit(allocator);

        // P09-T3: Para tareas 'disenar', llamar al bridge MCP de Open Design
        // después de que el worker genere el prompt de diseño.
        // El worker produce el prompt; nosotros llamamos od_status para obtener
        // la URL de OpenDesign y emitir un previewAvailable para el chat UI.
        if (pt.task_type == .disenar) {
            handleDesignTaskBridge(ctx, pt, result.artifacts);
        }

        // El motivo del rechazo viaja hasta el evento `task_failed` y hasta el
        // worker de corrección: "validation_failed" a secas no le decía a nadie
        // qué había que arreglar.
        var rechazo = ctx.sa.validatePieceForTaskDetallado(pt, result.artifacts) catch
            RechazoPieza{ .motivo = allocator.dupe(u8, "no se pudo evaluar el contrato de la tarea") catch null };
        defer rechazo.deinit(allocator);
        var ok = rechazo.motivo == null;
        // D-C1 (E5.11): una sesión agéntica sin `finish` nunca integra — lo que
        // quedó en el worktree a medias no es una entrega, aunque el diff
        // contenga archivos válidos.
        if (result.incomplete) ok = false;
        // M4: apunta a la dependencia prometida y no entregada. Es un slice de
        // `result.artifacts`, que sigue vivo mientras se construye `run_res`.
        var incoherent_dep: ?[]const u8 = null;

        ctx.mutex.lock();
        defer ctx.mutex.unlock();

        // M4 — el contrato dice "hay un campo con contenido"; eso no basta.
        // Medido el 2026-08-11 (órdenes #184 y #186): un `index.html` que enlaza un
        // `styles.css` y un `script.js` que nadie entrega pasaba el contrato, se
        // integraba, aprobaba la auto-auditoría y cerraba la orden en `done`. El
        // usuario abría una calculadora sin estilos donde no funcionaba ni un botón.
        // Un entregable que promete archivos que no entrega NO está completo, y decirlo
        // aquí hace que el lazo de corrección lo arregle en vez de darlo por bueno.
        if (ok) {
            // La entrega es la ORDEN, no la tarea. Lo cazó el gate de aceptación
            // en la #218: el plan repartió la web en tres tareas y M4 tumbó el
            // `index.html` por enlazar los archivos que sus HERMANAS entregaban.
            // Quedaron `styles.css` y `script.js` en disco y ningún punto de
            // entrada — una comprobación contra entregas rotas produciendo una.
            const hermanos = workspace.siblingDeliverables(allocator, ctx.outcome.plan.tasks, pt.id) catch &[_][]const u8{};
            defer allocator.free(hermanos);
            if (workspace.missingCompanionFileInOrder(allocator, pt, result.artifacts, hermanos) catch null) |missing| {
                ok = false;
                incoherent_dep = missing;
                var mc_out: std.Io.Writer.Allocating = .init(allocator);
                defer mc_out.deinit();
                var mc_js: std.json.Stringify = .{ .writer = &mc_out.writer, .options = .{} };
                if (mc_js.beginObject()) {
                    mc_js.objectField("task_id") catch {};
                    mc_js.write(pt.id) catch {};
                    mc_js.objectField("missing_file") catch {};
                    mc_js.write(missing) catch {};
                    mc_js.objectField("reason") catch {};
                    mc_js.write("el entregable enlaza un archivo que no entrega") catch {};
                    mc_js.endObject() catch {};
                    ctx.sa.recordEvent("artifact_incoherent", mc_out.written());
                } else |_| {}
            }
        }

        if (result.success) {
            ctx.completed += 1;
        } else {
            ctx.failed += 1;
        }

        var exec_outcome = ExecOutcome{
            .ran = false,
            .exit_code = 0,
            .needs_approval = false,
            .stderr = allocator.dupe(u8, "") catch "",
        };
        var saved_path: ?[]const u8 = null;
        var tested_producer_id: ?[]const u8 = null;
        var tested_producer_revision: u64 = 0;
        var tested_producer_count: usize = 0;
        var test_command: ?[]const u8 = null;
        var test_cwd: ?[]const u8 = null;

        if (ok) {
            ctx.integrated += 1;
            // P-EXEC-3: para ejecutar, NO persistir output del worker ni ejecutarlo —
            // el comando se resuelve deterministamente en el bloque P-EXEC abajo.
            if (pt.task_type != .ejecutar and !command_only_test and (ctx.llm_fn != null or ctx.catalog_path != null)) {
                // E5.09: un agente externo ya escribió los archivos REALES en
                // el worktree con el layout del proyecto (artifacts[].path son
                // relativas a worktree_root, validadas por sandbox en el diff).
                // Se registran esas rutas — re-materializarlas aplanadas bajo
                // `orden-<id>` rompía el gate semántico y el cwd de los tests
                // (medido en la orden 770: buscaban test/resta.test.js dentro
                // de orden-770/orden-770/).
                if (result.worktree_root) |wt| {
                    var first_real: ?[]const u8 = null;
                    var first_code: ?[]const u8 = null;
                    for (result.artifacts) |art| {
                        if (art.path.len == 0) continue;
                        const real = std.fs.path.join(allocator, &.{ wt, art.path }) catch continue;
                        if (ctx.saved.append(allocator, real)) |_| {
                            ctx.saved_owner.append(allocator, pt.id) catch {
                                _ = ctx.saved.pop();
                                allocator.free(real);
                                continue;
                            };
                        } else |_| {
                            allocator.free(real);
                            continue;
                        }
                        if (first_real == null) first_real = real;
                        if (first_code == null and workspace.hasKnownCodeExtension(std.fs.path.basename(real))) first_code = real;
                        var fw_out: std.Io.Writer.Allocating = .init(allocator);
                        defer fw_out.deinit();
                        var fw_js: std.json.Stringify = .{ .writer = &fw_out.writer, .options = .{} };
                        fw_js.beginObject() catch continue;
                        fw_js.objectField("file_path") catch continue;
                        fw_js.write(real) catch continue;
                        fw_js.objectField("task_id") catch continue;
                        fw_js.write(pt.id) catch continue;
                        fw_js.objectField("artifact_name") catch continue;
                        fw_js.write(std.fs.path.basename(real)) catch continue;
                        fw_js.objectField("content") catch continue;
                        fw_js.write(art.content) catch continue;
                        fw_js.endObject() catch continue;
                        ctx.sa.recordEvent("file_written", fw_out.written());
                    }
                    // El principal es el primer archivo de código (el ejecutable
                    // de la entrega), no el lockfile/artefacto auxiliar del diff.
                    if (first_code orelse first_real) |path| {
                        saved_path = path;
                        if (ctx.sa.event_conn) |rt| {
                            const upd = rt.prepare("UPDATE tasks SET artifact_path = ? WHERE plan_id = ? AND description = ?") catch null;
                            if (upd) |stmt| {
                                defer rt.finalize(stmt);
                                db.bindText(stmt, 1, path) catch {};
                                db.bindInt(stmt, 2, ctx.outcome.plan_id.?) catch {};
                                db.bindText(stmt, 3, pt.description) catch {};
                                _ = db.c.sqlite3_step(stmt);
                            }
                        }
                        const asg_local = findAssignment(ctx.outcome.assignments, pt.id);
                        const build_provider = if (asg_local) |ba| ba.provider_name else "mock";
                        const build_model = if (asg_local) |ba| ba.model_name else model_used;
                        appendAuditEntry(allocator, &ctx.audit_entries, ctx.sa.event_conn, ctx.sa.event_order_id, .{
                            .ts = 0,
                            .subject_kind = "task",
                            .subject_id = idToInt(pt.id),
                            .action = "BUILD",
                            .verdict = "PASS",
                            .model_id = build_model,
                            .provider = build_provider,
                            .evidence_ref = path,
                            .notes = "artifact generated",
                        });
                    }
                } else if (workspace.persistTaskFiles(allocator, ctx.outcome.order_id, pt, result.artifacts)) |maybe_paths| {
                    if (maybe_paths) |paths| {
                        defer allocator.free(paths);
                        const path = paths[0];
                        saved_path = path;
                        // D7: cada ruta se anota con la tarea que la produjo. Los
                        // dos arrays van en paralelo — si uno crece, el otro
                        // tambien, o `indicesVisibles` no puede casarlos.
                        if (ctx.saved.append(allocator, path)) |_| {
                            ctx.saved_owner.append(allocator, pt.id) catch {
                                _ = ctx.saved.pop();
                                allocator.free(path);
                            };
                        } else |_| allocator.free(path);
                        for (paths[1..]) |extra| {
                            if (ctx.saved.append(allocator, extra)) |_| {
                                ctx.saved_owner.append(allocator, pt.id) catch {
                                    _ = ctx.saved.pop();
                                    allocator.free(extra);
                                };
                            } else |_| allocator.free(extra);
                        }
                        // Un `file_written` POR ARCHIVO ESCRITO, recorriendo las rutas
                        // reales en vez de los nombres de campo del contrato.
                        //
                        // Regresión medida en las órdenes #201 y #202 (2026-08-11): el
                        // evento se emitía buscando un artefacto llamado `source`, `code`,
                        // `content`… y desde que el prompt de M1 pide la entrega con el
                        // NOMBRE DEL ARCHIVO en `field`, el modelo devuelve `index.html` y
                        // ese bucle no casaba con nada. El archivo se escribía en disco y
                        // la orden cerraba en `done` SIN UN SOLO `file_written`: el chat no
                        // mencionaba el archivo, el panel de Cambios salía vacío y el botón
                        // «Abrir» no llegaba a existir. Lo que el motor hace y lo que el
                        // motor cuenta habían vuelto a separarse.
                        //
                        // La ruta escrita es la única fuente honesta: si hay archivo, hay
                        // evento; si no lo hay, no lo hay.
                        for (paths) |written| {
                            // D2: ruta relativa a la carpeta de la orden
                            // (`docs\dos.txt`), no solo el último componente.
                            const written_name = workspace.displayName(written);
                            var fw_out: std.Io.Writer.Allocating = .init(allocator);
                            defer fw_out.deinit();
                            var fw_js: std.json.Stringify = .{ .writer = &fw_out.writer, .options = .{} };
                            fw_js.beginObject() catch continue;
                            fw_js.objectField("file_path") catch continue;
                            fw_js.write(written) catch continue;
                            fw_js.objectField("task_id") catch continue;
                            fw_js.write(pt.id) catch continue;
                            fw_js.objectField("artifact_name") catch continue;
                            fw_js.write(written_name) catch continue;
                            // El contenido alimenta la tarjeta de diff del chat (P3). Se
                            // busca el artefacto que corresponda a ESTE archivo; si no se
                            // identifica, el evento va sin contenido antes que con el de
                            // otro archivo.
                            if (artifactContentFor(result.artifacts, written_name)) |body| {
                                fw_js.objectField("content") catch continue;
                                fw_js.write(body) catch continue;
                            }
                            fw_js.endObject() catch continue;
                            ctx.sa.recordEvent("file_written", fw_out.written());
                        }
                        // D1: persist artifact_path to tasks table for GUI retrieval.
                        if (ctx.sa.event_conn) |rt| {
                            const upd = rt.prepare("UPDATE tasks SET artifact_path = ? WHERE plan_id = ? AND description = ?") catch null;
                            if (upd) |stmt| {
                                defer rt.finalize(stmt);
                                db.bindText(stmt, 1, path) catch {};
                                db.bindInt(stmt, 2, ctx.outcome.plan_id.?) catch {};
                                db.bindText(stmt, 3, pt.description) catch {};
                                _ = db.c.sqlite3_step(stmt);
                            }
                        }
                        // P5b: BUILD audit entry — producer task generated an artifact.
                        const asg_local = findAssignment(ctx.outcome.assignments, pt.id);
                        const build_provider = if (asg_local) |a| a.provider_name else "mock";
                        const build_model = if (asg_local) |a| a.model_name else model_used;
                        appendAuditEntry(allocator, &ctx.audit_entries, ctx.sa.event_conn, ctx.sa.event_order_id, .{
                            .ts = 0, // filled by caller via health.nowMillis in c_api
                            .subject_kind = "task",
                            .subject_id = idToInt(pt.id),
                            .action = "BUILD",
                            .verdict = "PASS",
                            .model_id = build_model,
                            .provider = build_provider,
                            .evidence_ref = path,
                            .notes = "artifact generated",
                        });
                        // GOBERNANZA-EJECUCION: la vista previa automática (FASE-0/EXEC-02)
                        // solo tiene sentido cuando el plan NO trae una tarea "ejecutar"
                        // dedicada para este mismo artefacto — si la trae, esa tarea es la
                        // única responsable de lanzarlo (evita abrir una ventana GUI de
                        // "preview" que un instante después la tarea ejecutar reemplazaría).
                        // Para programas no-GUI esto no aplica: su ejecución aquí sirve para
                        // probar/capturar salida del código recién generado, no es "preview".
                        const skip_gui_preview = isGuiProgram(allocator, path) and
                            hasDedicatedExecutorTask(ctx.outcome.plan.tasks, pt.id);
                        // un `.js` de navegador no se lanza con `node`. No
                        // es «no probarlo»: es que ejecutarlo con el intérprete
                        // equivocado no prueba nada y además tumba la orden.
                        const skip_browser_js = isBrowserScript(allocator, path);
                        if (skip_browser_js) {
                            var sb_out: std.Io.Writer.Allocating = .init(allocator);
                            defer sb_out.deinit();
                            var sb_js: std.json.Stringify = .{ .writer = &sb_out.writer, .options = .{} };
                            sb_js.beginObject() catch {};
                            sb_js.objectField("task_id") catch {};
                            sb_js.write(pt.id) catch {};
                            sb_js.objectField("file") catch {};
                            sb_js.write(path) catch {};
                            sb_js.objectField("razon") catch {};
                            sb_js.write("js_de_navegador_no_se_ejecuta_con_node") catch {};
                            sb_js.endObject() catch {};
                            // Se DICE que no se ejecutó y por qué. Saltarse una
                            // comprobación en silencio es lo que R14 llama un
                            // SKIP sin razón, y eso es un fallo.
                            ctx.sa.recordEvent("exec_skipped", sb_out.written());
                        }
                        if (!skip_gui_preview and !skip_browser_js and pt.task_type != .testear) {
                            exec_outcome = ctx.sa.governedExecute(path, pt.id, &ctx.outputs, &ctx.pending) catch |e| blk: {
                                break :blk ExecOutcome{
                                    .ran = false,
                                    .exit_code = 0,
                                    .needs_approval = false,
                                    .stderr = allocator.dupe(u8, @errorName(e)) catch "",
                                };
                            };
                        }
                        // governedExecute ya marco el uso sin argumentos
                        // (ejecucion por archivo). No se repite aqui.
                    }
                } else |_| {}
            }
        } else {
            ctx.rejected += 1;
        }

        // P-EXEC-5: dispatch para tareas 'ejecutar'. Resuelve el comando en orden
        // determinista: (a) dependencia productora, (b) contract_field `command`,
        // (c) description (prefijo "Ejecutar"), (d) artefacto del worker como
        // último fallback no-determinista.
        if (pt.task_type == .ejecutar and ok) {
            // (a) Buscar path guardado de las dependencias (productor upstream).
            for (pt.depends_on) |dep_id| {
                for (ctx.results.items) |res| {
                    if (std.mem.eql(u8, res.task_id, dep_id) and res.saved_path != null) {
                        const dep_path = res.saved_path.?;
                        exec_outcome = ctx.sa.governedExecute(dep_path, pt.id, &ctx.outputs, &ctx.pending) catch |e| ExecOutcome{
                            .ran = false,
                            .exit_code = 0,
                            .needs_approval = false,
                            .stderr = allocator.dupe(u8, @errorName(e)) catch "",
                        };
                        // governedExecute ya marco el uso sin argumentos.
                        break;
                    }
                }
                if (exec_outcome.ran or exec_outcome.needs_approval) break;
            }
            // (b) Comando efectivo de la tarea: resolveTaskCommand prueba
            //     TODAS las fuentes en orden de precedencia contractual y se
            //     queda con la primera que produce un comando ejecutable.
            //     Ninguna fuente gana por tener texto — gana la ejecutable
            //     (orden #528: el planner volcó prosa en `command` y el
            //     artefacto `command` del worker traía el comando real).
            if (!exec_outcome.ran and !exec_outcome.needs_approval) {
                var resolved = resolveTaskCommand(allocator, pt, result.artifacts) catch null;
                if (resolved) |*parsed| {
                    defer parsed.deinit();
                    exec_outcome = ctx.sa.governedExecuteRaw(parsed.exe, parsed.args, pt.id, &ctx.outputs, &ctx.pending) catch |e| ExecOutcome{
                        .ran = false,
                        .exit_code = 0,
                        .needs_approval = false,
                        .stderr = allocator.dupe(u8, @errorName(e)) catch "",
                    };
                    // R2-1: este comando se lanzo CON parsed.args. Un exit != 0
                    // aqui es un fallo real aunque imprima un usage; NO se marca.
                } else if (firstCommandCandidate(pt, result.artifacts)) |rechazado| {
                    const detalle = std.fmt.allocPrint(allocator, "comando no ejecutable: {s}", .{rechazado}) catch "comando no ejecutable";
                    exec_outcome = ExecOutcome{
                        .ran = false,
                        .exit_code = 0,
                        .needs_approval = false,
                        .stderr = detalle,
                    };
                    var ce_out: std.Io.Writer.Allocating = .init(allocator);
                    defer ce_out.deinit();
                    var ce_js: std.json.Stringify = .{ .writer = &ce_out.writer, .options = .{} };
                    ce_js.beginObject() catch {};
                    ce_js.objectField("task_id") catch {};
                    ce_js.write(pt.id) catch {};
                    ce_js.objectField("command") catch {};
                    ce_js.write(rechazado) catch {};
                    ce_js.objectField("razon") catch {};
                    ce_js.write("sin_ejecutable_allowlisted") catch {};
                    ce_js.endObject() catch {};
                    ctx.sa.recordEvent("exec_skipped", ce_out.written());
                }
            }
            // (c) `target` como ARCHIVO: solo cuando ninguna fuente produjo un
            //     comando — el path lo resuelve governedExecute por extensión.
            if (!exec_outcome.ran and !exec_outcome.needs_approval) {
                const target_path = extractArtifactField(result.artifacts, "target") orelse
                    extractContractField(pt.contract_fields, "target");
                if (target_path) |path| {
                    exec_outcome = ctx.sa.governedExecute(path, pt.id, &ctx.outputs, &ctx.pending) catch |e| ExecOutcome{
                        .ran = false,
                        .exit_code = 0,
                        .needs_approval = false,
                        .stderr = allocator.dupe(u8, @errorName(e)) catch "",
                    };
                    // governedExecute ya marco el uso sin argumentos.
                }
            }
        }

        // QA-V1: `tests_passed` es una afirmación del worker, no una prueba. Un
        // consumidor de testing solo puede cerrar si ejecutó el comando del
        // contrato contra una revisión materializada de su productor.
        if (pt.task_type == .testear and pt.depends_on.len > 0 and ok) {
            var revision_hasher = std.hash.Wyhash.init(0);
            for (pt.depends_on) |dependency| {
                for (ctx.results.items) |producer| {
                    if (!std.mem.eql(u8, producer.task_id, dependency) or !producer.integrated) continue;
                    const producer_path = producer.saved_path orelse break;
                    if (tested_producer_id == null) tested_producer_id = allocator.dupe(u8, producer.task_id) catch null;
                    // E5.09: si el productor corrió en un worktree (agente
                    // externo), el comando del test corre en la RAÍZ del
                    // worktree — las rutas del contrato (test/..., src/...)
                    // son relativas a ella, no al directorio del archivo.
                    if (test_cwd == null) test_cwd = producer.worktree_root orelse std.fs.path.dirname(producer_path) orelse break;
                    const revision = artifactRevision(producer.artifacts);
                    revision_hasher.update(producer.task_id);
                    revision_hasher.update(std.mem.asBytes(&revision));
                    tested_producer_count += 1;
                    break;
                }
            }
            if (tested_producer_count > 0) tested_producer_revision = revision_hasher.final();

            if (tested_producer_count != pt.depends_on.len or tested_producer_id == null or test_cwd == null) {
                exec_outcome = .{ .ran = false, .exit_code = 0, .needs_approval = false, .stderr = allocator.dupe(u8, "missing materialized producer for executable test evidence") catch "" };
            } else if (extractCommandFromContract(pt.contract_fields)) |command| {
                test_command = allocator.dupe(u8, command) catch null;
                var parsed_opt: ?ParsedCommand = parseRawCommand(allocator, command) catch null;
                if (parsed_opt) |*parsed| {
                    defer parsed.deinit();
                    if (ctx.cancel_token) |token| {
                        if (token.isCancelled()) {
                            exec_outcome = .{ .ran = false, .exit_code = 0, .needs_approval = false, .stderr = allocator.dupe(u8, "Cancelled") catch "" };
                        } else {
                            exec_outcome = ctx.sa.governedExecuteTestRawAtCwd(parsed.exe, parsed.args, pt.id, &ctx.outputs, &ctx.pending, test_cwd.?) catch |e| .{ .ran = false, .exit_code = 0, .needs_approval = false, .stderr = allocator.dupe(u8, @errorName(e)) catch "" };
                        }
                    } else {
                        exec_outcome = ctx.sa.governedExecuteTestRawAtCwd(parsed.exe, parsed.args, pt.id, &ctx.outputs, &ctx.pending, test_cwd.?) catch |e| .{ .ran = false, .exit_code = 0, .needs_approval = false, .stderr = allocator.dupe(u8, @errorName(e)) catch "" };
                    }
                } else {
                    exec_outcome = .{ .ran = false, .exit_code = 0, .needs_approval = false, .stderr = allocator.dupe(u8, "test command is missing or not allowlisted") catch "" };
                }
            } else {
                exec_outcome = .{ .ran = false, .exit_code = 0, .needs_approval = false, .stderr = allocator.dupe(u8, "test task requires a command contract with an executable assertion") catch "" };
            }

            // governedExecuteRaw emits the authoritative shell_command event with
            // captured stdout/stderr. This event binds that execution to the exact
            // producer revision it checked.
            var evidence_out: std.Io.Writer.Allocating = .init(allocator);
            defer evidence_out.deinit();
            var evidence_json: std.json.Stringify = .{ .writer = &evidence_out.writer, .options = .{} };
            var revision_buf: [16]u8 = undefined;
            const revision_text = std.fmt.bufPrint(&revision_buf, "{x}", .{tested_producer_revision}) catch "0";
            evidence_json.beginObject() catch {};
            evidence_json.objectField("task_id") catch {};
            evidence_json.write(pt.id) catch {};
            evidence_json.objectField("producer_task_id") catch {};
            evidence_json.write(tested_producer_id orelse "") catch {};
            evidence_json.objectField("producer_task_ids") catch {};
            evidence_json.beginArray() catch {};
            for (pt.depends_on) |producer_id| evidence_json.write(producer_id) catch {};
            evidence_json.endArray() catch {};
            evidence_json.objectField("producer_count") catch {};
            evidence_json.write(tested_producer_count) catch {};
            evidence_json.objectField("producer_revision") catch {};
            // JSON/JS cannot faithfully represent all u64 values as Number.
            evidence_json.write(revision_text) catch {};
            evidence_json.objectField("command") catch {};
            evidence_json.write(test_command orelse "") catch {};
            evidence_json.objectField("cwd") catch {};
            evidence_json.write(test_cwd orelse "") catch {};
            evidence_json.objectField("ran") catch {};
            evidence_json.write(exec_outcome.ran) catch {};
            evidence_json.objectField("exit_code") catch {};
            evidence_json.write(exec_outcome.exit_code) catch {};
            evidence_json.objectField("timed_out") catch {};
            evidence_json.write(exec_outcome.timed_out) catch {};
            evidence_json.objectField("stderr") catch {};
            evidence_json.write(exec_outcome.stderr) catch {};
            evidence_json.objectField("stdout") catch {};
            evidence_json.write(exec_outcome.stdout orelse "") catch {};
            evidence_json.objectField("output_event") catch {};
            evidence_json.write("shell_command") catch {};
            evidence_json.endObject() catch {};
            ctx.sa.recordEvent("test_evidence_v1", evidence_out.written());
        }

        for (ctx.sidekick_ids) |sid| {
            if (!std.mem.eql(u8, sid, pt.id)) continue;
            ctx.sa.recordSidekickTask(pt, asg, model_used);
            break;
        }

        const owned_artifacts = cloneArtifacts(allocator, result.artifacts) catch &.{};
        var run_success = taskExecutionSucceeded(pt.task_type, result.success, ok, exec_outcome);
        if (pt.task_type == .testear and pt.depends_on.len > 0) {
            run_success = run_success and tested_producer_id != null and test_command != null and
                exec_outcome.ran and exec_outcome.exit_code == 0 and !exec_outcome.timed_out and !exec_outcome.needs_approval;
        }
        var run_res = TaskRunResult{
            .paid_budget_exhausted = result.paid_budget_exhausted,
            .task_id = allocator.dupe(u8, pt.id) catch "",
            .artifacts = owned_artifacts,
            .success = run_success,
            // M4: la evidencia que recibe el worker de corrección tiene que decirle QUÉ
            // le falta. Sin esto, el lazo de corrección reintenta a ciegas lo mismo.
            .error_msg = if (incoherent_dep) |missing|
                (std.fmt.allocPrint(
                    allocator,
                    "El entregable enlaza «{s}» y no lo entrega. Devuelve TAMBIEN ese archivo como un objeto propio del array (con su nombre en \"field\"), o incrusta su contenido dentro del HTML (<style> / <script>) y quita el enlace.",
                    .{missing},
                ) catch (allocator.dupe(u8, result.error_msg) catch ""))
            else if (result.error_msg.len == 0 and rechazo.motivo != null)
                // El worker respondió sin error y aun así la pieza se rechazó:
                // el único que sabe por qué es el validador. Sin esto el evento
                // repetía "validation_failed" como si fuera una explicación.
                (allocator.dupe(u8, rechazo.motivo.?) catch "")
            else
                allocator.dupe(u8, result.error_msg) catch "",
            .integrated = if (pt.task_type == .ejecutar) run_success else ok,
            .model_used = allocator.dupe(u8, model_used) catch "",
            .exec = exec_outcome,
            .saved_path = if (saved_path) |p| allocator.dupe(u8, p) catch null else null,
            .tested_producer_id = tested_producer_id,
            .tested_producer_revision = tested_producer_revision,
            .test_command = test_command,
            .worktree_root = if (result.worktree_root) |wr| allocator.dupe(u8, wr) catch null else null,
            // D-C1: una sesión agéntica sin `finish` nunca se cuenta como
            // entregada — la tarea queda incompleta aunque el diff tenga
            // archivos (el modelo no cerró su propio contrato).
            .incomplete = result.incomplete,
        };
        recordOmittedExecution(ctx, &run_res, run_res.saved_path orelse "");
        if (result.incomplete) {
            run_res.success = false;
            run_res.integrated = false;
        }
        // AUDIT-UNAVAILABLE-P0: una tarea `auditar` sin veredicto usable no es un
        // fallo del producto ni un PASS implícito — el auditor no llegó a revisar.
        // Se clasifica aparte para que la orden pueda cerrar 'audit_unavailable'
        // (entrega bloqueada, reintento manual) en vez de 'failed' o 'done'.
        if (pt.task_type == .auditar) {
            run_res.audit_verdict = auditVerdictOf(run_res.artifacts);
            if (run_res.audit_verdict == .unavailable) {
                run_res.success = false;
                run_res.integrated = false;
                if (run_res.error_msg.len == 0) {
                    allocator.free(run_res.error_msg);
                    run_res.error_msg = allocator.dupe(u8, "audit_unavailable: el auditor no produjo un veredicto usable (campo verdict ausente, vacío o irreconocible)") catch "";
                }
            } else {
                // un veredicto usable solo vale si sus citas se
                // sostienen al abrir el archivo. Una cita inventada (la #739)
                // deja el informe sin valor: misma clasificación que un auditor
                // que no llegó a revisar, con las citas falsas nombradas.
                verificaCitasDelInforme(ctx.sa, allocator, ctx.outcome.order_id, pt.id, &run_res);
            }
        }
        ctx.results.append(allocator, run_res) catch {
            allocator.free(run_res.task_id);
            freeOwnedArtifacts(allocator, run_res.artifacts);
            allocator.free(run_res.error_msg);
            allocator.free(run_res.model_used);
            allocator.free(run_res.exec.stderr);
            if (run_res.exec.stdout) |stdout| allocator.free(stdout);
            if (run_res.tested_producer_id) |id| allocator.free(id);
            if (run_res.test_command) |command| allocator.free(command);
            if (run_res.saved_path) |p| allocator.free(p);
        };

        // F0: emitir evento task_done o task_failed (P06: incluye worker_id)
        {
            var out: std.Io.Writer.Allocating = .init(allocator);
            defer out.deinit();
            var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
            js.beginObject() catch {};
            js.objectField("task_id") catch {};
            js.write(pt.id) catch {};
            js.objectField("worker_id") catch {};
            js.write(pt.id) catch {};
            js.objectField("success") catch {};
            js.write(run_res.success) catch {};
            js.objectField("model_used") catch {};
            js.write(model_used) catch {};
            js.objectField("integrated") catch {};
            js.write(run_res.integrated) catch {};
            if (exec_outcome.usage_only) {
                // R2-3: el evento de la tarea tambien dice que NO se verifico.
                js.objectField("exec_omitted") catch {};
                js.write(true) catch {};
                js.objectField("exec_omitted_reason") catch {};
                js.write("programa_requiere_argumentos") catch {};
            }
            if (!run_res.success) {
                const cause: []const u8 = if (result.paid_budget_exhausted) "paid_budget_exhausted" else if (run_res.audit_verdict == .unavailable) "audit_unavailable" else if (run_res.incomplete) "agentic_incomplete" else if (!result.success) "worker_failed" else if (!ok) "validation_failed" else if (exec_outcome.needs_approval) "approval_required" else if (exec_outcome.timed_out) "execution_timeout" else if (exec_outcome.ran) "execution_failed" else "task_failed";
                const err = if (run_res.error_msg.len > 0) run_res.error_msg else if (exec_outcome.stderr.len > 0) exec_outcome.stderr else cause;
                js.objectField("cause") catch {};
                js.write(cause) catch {};
                js.objectField("error_msg") catch {};
                js.write(err) catch {};
                if (asg) |a| {
                    js.objectField("provider") catch {};
                    js.write(a.provider_name) catch {};
                    js.objectField("assigned_model") catch {};
                    js.write(a.model_name) catch {};
                }
            }
            js.endObject() catch {};
            // AUDIT-UNAVAILABLE-P0: la tarea de auditoría sin veredicto emite su
            // propio evento versionado — no `task_failed` (no es un defecto del
            // producto) ni `task_done` (no entregó veredicto).
            ctx.sa.recordEvent(if (run_res.success) "task_done" else if (run_res.audit_verdict == .unavailable) "task_audit_unavailable_v1" else "task_failed", out.written());
        }
    }

    /// P5b: convierte un task_id ("T1", "T2", ...) a entero para subject_id.
    fn idToInt(task_id: []const u8) i64 {
        return @intCast(std.fmt.parseInt(i64, task_id[1..], 10) catch 1);
    }

    /// preservar diagnosticos y registrar una sola omision por ejecucion.
    fn recordOmittedExecution(ctx: *FanoutContext, run_res: *TaskRunResult, evidence_ref: []const u8) void {
        const allocator = ctx.sa.allocator;
        if (run_res.exec.usage_only) {
            const nota = "EJECUCION OMITIDA (programa_requiere_argumentos): el motor lanzo el programa sin argumentos y solo obtuvo su mensaje de uso; su comportamiento no se verifico.";
            const texto = std.fmt.allocPrint(allocator, "{s}{s}{s}", .{ run_res.error_msg, if (run_res.error_msg.len > 0) "\n" else "", nota }) catch |err| {
                std.log.err("no se pudo registrar la ejecucion omitida: {s}", .{@errorName(err)});
                return;
            };
            allocator.free(run_res.error_msg);
            run_res.error_msg = texto;
            appendAuditEntry(allocator, &ctx.audit_entries, ctx.sa.event_conn, ctx.sa.event_order_id, .{
                .ts = 0,
                .subject_kind = "task",
                .subject_id = idToInt(run_res.task_id),
                .action = "EXEC",
                .verdict = "SKIP",
                .model_id = "",
                .provider = "deterministic-gate",
                .evidence_ref = evidence_ref,
                .notes = "ejecucion omitida: programa_requiere_argumentos",
            });
        }
    }

    fn recordRecoveredExecOmission(ctx: *FanoutContext, result: *TaskRunResult, evidence_ref: []const u8) void {
        if (!result.exec.usage_only) return;
        recordOmittedExecution(ctx, result, evidence_ref);
        var out: std.Io.Writer.Allocating = .init(ctx.sa.allocator);
        defer out.deinit();
        var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
        js.beginObject() catch return;
        js.objectField("task_id") catch return;
        js.write(result.task_id) catch return;
        js.objectField("worker_id") catch return;
        js.write(result.task_id) catch return;
        js.objectField("success") catch return;
        js.write(result.success) catch return;
        js.objectField("integrated") catch return;
        js.write(result.integrated) catch return;
        js.objectField("model_used") catch return;
        js.write(result.model_used) catch return;
        js.objectField("error_msg") catch return;
        js.write(result.error_msg) catch return;
        js.objectField("exec_omitted") catch return;
        js.write(true) catch return;
        js.objectField("exec_omitted_reason") catch return;
        js.write("programa_requiere_argumentos") catch return;
        js.endObject() catch return;
        ctx.sa.recordEvent("task_done", out.written());
    }

    /// P5b: append an audit entry to the shared list (called under mutex or from main thread).
    fn appendAuditEntry(
        allocator: std.mem.Allocator,
        list: *std.ArrayList(AuditEntry),
        event_conn: ?db.Connection,
        order_id: i64,
        info: AuditEntry,
    ) void {
        _ = event_conn;
        const entry = AuditEntry{
            .ts = info.ts,
            .subject_kind = allocator.dupe(u8, info.subject_kind) catch return,
            .subject_id = info.subject_id,
            .order_id = order_id,
            .action = allocator.dupe(u8, info.action) catch return,
            .verdict = allocator.dupe(u8, info.verdict) catch return,
            .model_id = allocator.dupe(u8, info.model_id) catch return,
            .provider = allocator.dupe(u8, info.provider) catch return,
            .evidence_ref = allocator.dupe(u8, info.evidence_ref) catch return,
            .notes = allocator.dupe(u8, info.notes) catch return,
            .auditor_index = info.auditor_index,
        };
        list.append(allocator, entry) catch entry.deinit(allocator);
    }

    /// Detecta ciclos en el grafo de dependencias y devuelve las tareas ordenadas por
    /// niveles topológicos (cada nivel contiene tareas independientes entre sí).
    pub fn resolveWaves(tasks: []const planner.PlannedTask, allocator: std.mem.Allocator) ![][]const planner.PlannedTask {
        var indeg = std.StringHashMap(usize).init(allocator);
        defer {
            indeg.deinit();
        }
        var adj = std.StringHashMap(std.ArrayList([]const u8)).init(allocator);
        defer {
            var it = adj.valueIterator();
            while (it.next()) |list| list.deinit(allocator);
            adj.deinit();
        }

        for (tasks) |pt| {
            try indeg.put(pt.id, 0);
            const list = std.ArrayList([]const u8).empty;
            try adj.put(pt.id, list);
        }

        for (tasks) |pt| {
            const deps = try effectiveDependencyIds(allocator, pt, tasks);
            defer allocator.free(deps);
            for (deps) |dep| {
                if (adj.getPtr(dep)) |ptr| {
                    try ptr.append(allocator, pt.id);
                } else {
                    // FIX BAJO: dependencia hacia un id inexistente en el grafo.
                    // No confundir con ciclo: devolvemos error tipado.
                    return error.UnknownDependency;
                }
                if (indeg.getPtr(pt.id)) |iptr| {
                    iptr.* += 1;
                }
            }
        }

        var waves = std.ArrayList([]const planner.PlannedTask).empty;
        defer {
            for (waves.items) |w| allocator.free(w);
            waves.deinit(allocator);
        }

        var remaining: usize = tasks.len;
        while (remaining > 0) {
            var wave = std.ArrayList(planner.PlannedTask).empty;
            defer wave.deinit(allocator);

            for (tasks) |pt| {
                const d = indeg.get(pt.id) orelse 0;
                if (d == 0) {
                    try wave.append(allocator, pt);
                    // Marcar como procesado poniendo indeg = max
                    if (indeg.getPtr(pt.id)) |iptr| iptr.* = std.math.maxInt(usize);
                }
            }

            if (wave.items.len == 0) return error.DependencyCycle;

            for (wave.items) |pt| {
                if (adj.getPtr(pt.id)) |ptr| {
                    for (ptr.items) |next_id| {
                        if (indeg.getPtr(next_id)) |iptr| {
                            if (iptr.* != std.math.maxInt(usize)) iptr.* -= 1;
                        }
                    }
                }
                remaining -= 1;
            }

            const owned = try allocator.dupe(planner.PlannedTask, wave.items);
            try waves.append(allocator, owned);
        }

        return waves.toOwnedSlice(allocator);
    }

    /// Aprueba el plan y despacha sus tareas a workers con sandbox por worker (FR-006).
    /// Si `catalog_path` o `llm_fn` están disponibles, usa NativeWorker con el modelo
    /// asignado por tarea (vía LiveLlm.initForced); si no, MockWorker como fallback.
    ///
    /// Ejecuta en paralelo por olas topológicas (respetando depends_on), luego
    /// consolida, auto-audita y corrige piezas fallidas (acotado a MAX_AUDIT_CYCLES).
    pub fn approveAndDispatch(self: *Superagent, outcome: *OrderOutcome, llm_fn: ?worker_backend.NativeWorker.LlmFn, llm_ctx: ?*anyopaque, catalog_path: ?[]const u8) !DispatchResult {
        // Antes de aprobar en DB, crear espacios, escribir artefactos o llamar workers.
        if (outcome.wait_for_plan_approval and !self.plan_approved) return error.PlanApprovalRequired;
        if (outcome.plan_id == null) return error.NoPlanToApprove;
        try self.markPlanApproved(outcome.plan_id.?);
        try self.updateOrderStatus(outcome.order_id, OrderStatus.approved.toText());
        try self.updateOrderStatus(outcome.order_id, OrderStatus.running.toText());

        // F0: emitir evento order_running
        {
            var out: std.Io.Writer.Allocating = .init(self.allocator);
            defer out.deinit();
            var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
            js.beginObject() catch {};
            js.objectField("order_id") catch {};
            js.write(outcome.order_id) catch {};
            js.endObject() catch {};
            self.recordEvent("order_running", out.written());
        }

        // Edited plans deliberately carry placeholder assignments. Recompute the
        // owned routing snapshot immediately before fanout so a pin or governance
        // change made after planning cannot dispatch with stale model choices.
        if (self.router != null) try self.refreshAssignmentsForDispatch(outcome);

        var visual = false;
        for (outcome.plan.tasks) |task| if (task.needs_vision) {
            visual = true;
            break;
        };
        const images = if (visual) try self.loadOrderImageParts(outcome.order_id) else &.{};
        defer freeOrderImageParts(self.allocator, images);

        const waves = try resolveWaves(outcome.plan.tasks, self.allocator);
        defer {
            for (waves) |w| self.allocator.free(w);
            self.allocator.free(waves);
        }

        // ORDER-ROOT-WORKERS: el override es TLS del hilo de dispatch; capturarlo
        // aquí (mismo hilo) para que cada worker lo reinstale en el suyo.
        var order_root_buf: [4096]u8 = undefined;
        const order_root_owned: ?[]const u8 = if (workspace.getOrderRootOverride(&order_root_buf)) |r|
            self.allocator.dupe(u8, r) catch null
        else
            null;

        defer if (order_root_owned) |root| self.allocator.free(root);
        var rules_root_buf: [4096]u8 = undefined;
        const rules_root = order_root_owned orelse (workspace.selectedProjectRoot(&rules_root_buf) orelse workspace.effectiveRoot(&rules_root_buf));
        const old_rules = self.rules_context;
        const order_rules = old_rules orelse try project_rules.loadContext(self.allocator, self.rules_catalog orelse (if (self.router) |r| r.catalog else null), rules_root);
        self.rules_context = order_rules;
        defer {
            self.rules_context = old_rules;
            if (old_rules == null) order_rules.deinit(self.allocator);
        }

        // T8: el sidekick «se usa» cuando una tarea de investigar,
        // resumir o documentar lleva el modelo que fijó el rol `sidekick`.
        var sidekick_ids = std.ArrayList([]const u8).empty;
        defer sidekick_ids.deinit(self.allocator);
        // Es telemetría del grafo: si no se puede leer el rol, el evento se
        // cuenta como perdido y la orden se despacha igual (no se aborta).
        if (self.router) |router| self.collectSidekickTasks(router, outcome, &sidekick_ids) catch {
            sidekick_ids.clearRetainingCapacity();
            self.notarEventoPerdido();
        };

        var ctx = FanoutContext{
            .mutex = sync.Mutex.init(),
            .completed = 0,
            .failed = 0,
            .integrated = 0,
            .rejected = 0,
            .outputs = std.ArrayList(WorkerOutput).empty,
            .pending = std.ArrayList(ApprovalRequest).empty,
            .saved = std.ArrayList([]const u8).empty,
            .saved_owner = std.ArrayList([]const u8).empty,
            .results = std.ArrayList(TaskRunResult).empty,
            .sa = self,
            .outcome = outcome,
            .llm_fn = llm_fn,
            .llm_ctx = llm_ctx,
            .catalog_path = catalog_path,
            .needed_resources = outcome.discovery_needed_resources,
            .task_selections = null,
            .current_upstream = null,
            .cancel_token = self.cancel_token,
            .plan_manifest = null,
            .order_root = order_root_owned,
            .images = images,
            .sidekick_ids = sidekick_ids.items,
        };
        // E5.13 (D-C3): mapa del repositorio para los workers — un build por
        // despacho (la caché por (raíz, HEAD, config) lo hace barato cuando el
        // planner ya lo construyó segundos antes). La semilla es la orden.
        {
            var mroot_buf: [4096]u8 = undefined;
            const map_root = if (ctx.order_root) |orr| orr else workspace.effectiveRoot(&mroot_buf);
            var map_threaded = std.Io.Threaded.init(self.allocator, .{});
            defer map_threaded.deinit();
            if (repo_map.renderForPrompt(self.allocator, map_threaded.io(), map_root, self.order_text orelse "", 3000, .{}, self.runtime)) |rm| {
                ctx.repo_map_text = rm.text;
                if (self.event_conn) |ec| repo_map.emitBuiltEvent(ec, self.event_order_id, rm);
            }
        }
        // P12-T3: Compute per-task selections if LlmDiscovery + inventory available.
        if (self.discovery_llm != null and self.inventory_ptr != null and self.order_text != null) {
            // El selector NO puede usar el `llm_fn` del worker.
            //
            // Comparten la cadena de proveedores, pero piden contratos distintos:
            // el worker espera artefactos y el selector contesta
            // `[{"task_id":...,"skills":[],...}]`. Con el validador del worker,
            // cada respuesta correcta del selector se anotaba `empty` y la cadena
            // se recorría entera para acabar en el selector por palabras clave.
            // Medido en la orden #289: cinco proveedores quemados por orden, con
            // respuesta real en los cinco. `arrayJsonFn` es la misma cadena
            // exigiendo lo que el selector sí devuelve.
            //
            // La sustitución va atada a QUIEN llama: `arrayJsonFn` hace
            // `@ptrCast` del ctx a `*LiveLlm`, así que solo es legítima cuando la
            // función entrante es la del LiveLlm. Las pruebas inyectan su propio
            // par (ctx, fn) que no es un LiveLlm — castearlo sería corromper
            // memoria. Si no es el par conocido, se respeta el que venga.
            if (llm_fn) |f| {
                if (llm_ctx) |c| {
                    const es_live_llm = f == live_worker.LiveLlm.llmFn;
                    const sel_fn: tool_discovery.LlmCallFn = if (es_live_llm)
                        live_worker.LiveLlm.arrayJsonFn
                    else
                        @ptrCast(f);
                    self.discovery_llm.?.setLlm(c, sel_fn);
                }
            }
            const task_ids = self.allocator.alloc([]const u8, outcome.plan.tasks.len) catch null;
            const task_descs = self.allocator.alloc([]const u8, outcome.plan.tasks.len) catch null;
            if (task_ids != null and task_descs != null) {
                for (outcome.plan.tasks, 0..) |t, i| {
                    task_ids.?[i] = t.id;
                    task_descs.?[i] = t.description;
                }
                ctx.task_selections = self.discovery_llm.?.selectPerTask(
                    self.allocator,
                    self.order_text.?,
                    task_ids.?,
                    task_descs.?,
                    self.inventory_ptr.?,
                ) catch null;
                self.allocator.free(task_ids.?);
                self.allocator.free(task_descs.?);
            }
        }
        defer if (ctx.task_selections) |ts| {
            for (ts) |*t| t.deinit(self.allocator);
            self.allocator.free(ts);
        };
        defer {
            for (ctx.outputs.items) |o| {
                self.allocator.free(o.worker_id);
                self.allocator.free(o.stream);
                self.allocator.free(o.text);
            }
            ctx.outputs.deinit(self.allocator);
            for (ctx.pending.items) |a| a.deinit(self.allocator);
            ctx.pending.deinit(self.allocator);
            for (ctx.saved.items) |p| self.allocator.free(p);
            ctx.saved.deinit(self.allocator);
            // `saved_owner` guarda prestamos de `plan.tasks[i].id`, que vive mas
            // que el despacho: se libera el array, no los elementos.
            ctx.saved_owner.deinit(self.allocator);
            for (ctx.results.items) |r| {
                deinitTaskRunResult(self.allocator, r);
            }
            ctx.results.deinit(self.allocator);
            // P5b: limpiar audit_entries no transferidas (toOwnedSlice las mueve).
            for (ctx.audit_entries.items) |e| e.deinit(self.allocator);
            ctx.audit_entries.deinit(self.allocator);
            // las notas de respaldo se liberan aquí; el resumen
            // final ya las consumió (se construyó antes de este defer).
            for (ctx.fallback_notes.items) |*note| note.deinit(self.allocator);
            ctx.fallback_notes.deinit(self.allocator);
            if (ctx.current_upstream) |uc| self.allocator.free(uc);
            if (ctx.plan_manifest) |pm| self.allocator.free(pm);
            if (ctx.repo_map_text) |mt| self.allocator.free(mt);
        }

        {
            const stmt = try self.runtime.prepare("SELECT COALESCE(space_id, 0) FROM orders WHERE id = ?");
            defer self.runtime.finalize(stmt);
            try db.bindInt(stmt, 1, outcome.order_id);
            if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return error.InvalidOrderContext;
            var browser_root_buf: [4096]u8 = undefined;
            const browser_owner: browser_service.OrderContext = .{
                .order_id = outcome.order_id,
                .space_id = db.c.sqlite3_column_int64(stmt, 0),
                .workspace_root = ctx.order_root orelse workspace.effectiveRoot(&browser_root_buf),
            };
            ctx.browser = if (self.browser_registry) |registry| try registry.acquire(self.allocator, browser_owner) else try browser_service.Service.create(self.allocator, browser_owner);
            errdefer ctx.browser.?.release();
            try ctx.browser.?.beginDispatch();
            // 10-nov: la cabina abre y engancha el panel al ver la primera
            // petición; se le da margen para hacerlo (browser_service).
            ctx.browser.?.attach_grace_ms = 8000;
        }
        defer if (ctx.browser) |browser| {
            browser.cancelOrder();
            browser.release();
        };
        // FIX-4a / XFILE-02: manifiesto estatico del plan, inyectado a CADA worker para
        // que coordinen nombres entre tareas hermanas aunque corran en la misma ola.
        ctx.plan_manifest = self.buildDispatchManifest(outcome) catch null;

        // CHECKPOINT-T2: cuando este despacho ES una reanudación, las tareas que
        // el checkpoint persistido declara 'completed' NO vuelven a correr — se
        // siembran como resultados restaurados (success+integrated) para que
        // sus dependientes sigan pudiendo arrancar y su artefacto alimente el
        // contexto upstream. Todo lo no completado corre ENTERO: una tarea
        // interrumpida a medias no tiene continuidad interna que preservar.
        var completed_set = std.StringHashMap(void).init(self.allocator);
        defer completed_set.deinit();
        var restored_count: usize = 0;
        if (self.resume_checkpoint) |checkpoint| {
            for (checkpoint.restored) |rt| {
                const pt = findPlannedTask(outcome.plan.tasks, rt.task_id) orelse continue;
                if (completed_set.contains(pt.id)) continue;
                completed_set.put(pt.id, {}) catch continue;
                var run_res = TaskRunResult{
                    .task_id = self.allocator.dupe(u8, pt.id) catch continue,
                    .artifacts = &.{},
                    .success = true,
                    .error_msg = self.allocator.dupe(u8, "restored from checkpoint") catch "",
                    .integrated = true,
                    .model_used = self.allocator.dupe(u8, "checkpoint") catch "",
                    .exec = .{ .ran = false, .exit_code = 0, .needs_approval = false, .stderr = self.allocator.dupe(u8, "") catch "" },
                    .saved_path = if (rt.artifact_path) |p| self.allocator.dupe(u8, p) catch null else null,
                    .restored = true,
                };
                if (outcome.plan_id) |pid| {
                    self.restoreArtifactProvenance(pid, &run_res) catch |err| {
                        deinitTaskRunResult(self.allocator, run_res);
                        return err;
                    };
                }
                ctx.results.append(self.allocator, run_res) catch {
                    deinitTaskRunResult(self.allocator, run_res);
                    continue;
                };
                ctx.completed += 1;
                ctx.integrated += 1;
                restored_count += 1;
                if (rt.artifact_path) |p| {
                    const saved_copy = self.allocator.dupe(u8, p) catch continue;
                    if (ctx.saved.append(self.allocator, saved_copy)) |_| {
                        ctx.saved_owner.append(self.allocator, pt.id) catch {
                            _ = ctx.saved.pop();
                            self.allocator.free(saved_copy);
                        };
                    } else |_| self.allocator.free(saved_copy);
                }
            }
            // Evento honesto: qué se saltó por ya hecho, qué se reporta como
            // interrumpido a medias (se re-ejecuta ENTERO) y qué corre de nuevo.
            {
                var out: std.Io.Writer.Allocating = .init(self.allocator);
                defer out.deinit();
                var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
                js.beginObject() catch {};
                js.objectField("order_id") catch {};
                js.write(outcome.order_id) catch {};
                js.objectField("restored") catch {};
                js.write(restored_count) catch {};
                js.objectField("rerun") catch {};
                js.write(outcome.plan.tasks.len - restored_count) catch {};
                js.objectField("restored_tasks") catch {};
                js.beginArray() catch {};
                for (checkpoint.restored) |rt| js.write(rt.task_id) catch {};
                js.endArray() catch {};
                js.objectField("interrupted_tasks") catch {};
                js.beginArray() catch {};
                for (checkpoint.interrupted) |tid| js.write(tid) catch {};
                js.endArray() catch {};
                js.endObject() catch {};
                self.recordEvent("order_resumed", out.written());
            }
        }

        var concurrency_peak: usize = 0;

        for (waves, 0..) |wave_index, wave_num| {
            if (wave_index.len == 0) continue;
            // CHECKPOINT-T2: filtrar las restauradas — sus resultados ya están
            // sembrados en ctx.results; relanzarlas reharía trabajo ya hecho.
            var run_list: std.ArrayList(planner.PlannedTask) = .empty;
            defer run_list.deinit(self.allocator);
            for (wave_index) |pt| {
                if (completed_set.contains(pt.id)) continue;
                run_list.append(self.allocator, pt) catch continue;
            }
            if (run_list.items.len == 0) continue;

            // P7: Narrador del Superagente — emitir superagent_thinking entre olas
            {
                var out: std.Io.Writer.Allocating = .init(self.allocator);
                defer out.deinit();
                var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
                js.beginObject() catch {};
                js.objectField("text") catch {};
                if (waves.len == 1) {
                    js.write(@as([]const u8, "Ejecutando tareas en paralelo…")) catch {};
                } else {
                    const label = std.fmt.allocPrint(self.allocator, "Ola {d} de {d}: ejecutando {d} tarea(s) en paralelo…", .{ wave_num + 1, waves.len, run_list.items.len }) catch "Ejecutando…";
                    defer self.allocator.free(label);
                    js.write(label) catch {};
                }
                js.endObject() catch {};
                self.recordEvent("superagent_thinking", out.written());
            }

            // FIX-3 / XFILE-01: reconstruir el contexto de archivos ya creados por
            // olas PREVIAS, para que los consumidores (tests/auditoría/docs) referencien
            // los archivos y símbolos REALES. En la primera ola ctx.saved está vacío → null.
            if (ctx.current_upstream) |old| {
                self.allocator.free(old);
                ctx.current_upstream = null;
            }
            ctx.current_upstream = buildUpstreamContext(self.allocator, ctx.saved.items) catch null;

            // Reutilizar la concurrencia del scheduler (4 por defecto),
            // incluyendo la tarea local que corre en el hilo llamador.
            const max_in_flight = (scheduler.SchedulerConfig{}).num_workers;
            const allow_local_parallel = providers.providers.envFlagEnabled("DEVAGENTS_LOCAL_ALLOW_PARALLEL");
            var local_seq: usize = 0;
            if (!allow_local_parallel) {
                for (run_list.items) |pt| {
                    if (taskUsesLocalProvider(&ctx, pt)) local_seq += 1;
                }
            }
            if (local_seq > 0) {
                var out: std.Io.Writer.Allocating = .init(self.allocator);
                defer out.deinit();
                var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
                js.beginObject() catch {};
                js.objectField("tasks") catch {};
                js.write(local_seq) catch {};
                js.endObject() catch {};
                self.recordEvent("local_wave_sequential", out.written());
            }
            // T8: la colmena del grafo sale de la ola REAL que se
            // despacha aquí, con sus miembros; nunca de la cercanía de horas.
            // `parallel` es falso solo si toda la ola es local y serializada.
            if (run_list.items.len > 1) self.recordSwarmGroup(wave_num + 1, run_list.items, allow_local_parallel or local_seq < run_list.items.len);
            const wave_peak = try dispatchWaveTasks(self.allocator, run_list.items, max_in_flight, &ctx, runTaskInWave, taskUsesLocalProvider, allow_local_parallel);
            concurrency_peak = @max(concurrency_peak, wave_peak);

            // CHECKPOINT-T2: al cerrar la ola, cada resultado queda persistido —
            // si el proceso muere en la siguiente ola, la reanudación sabe qué
            // quedó hecho. La escritura final de más abajo vuelve a cubrir todo.
            if (outcome.plan_id) |pid| {
                ctx.mutex.lock();
                defer ctx.mutex.unlock();
                for (ctx.results.items) |res| {
                    // AUDIT-UNAVAILABLE-P0: la tarea sin veredicto usable se
                    // persiste como 'audit_unavailable' — no 'completed' (el
                    // checkpoint la restauraría) ni 'failed' (no es defecto del
                    // producto). En la reanudación vuelve a correr sola.
                    // la procedencia va ANTES del estado para que una
                    // reanudación no pierda el origen de los marcadores heredados.
                    try self.persistArtifactProvenance(pid, res);
                    self.persistTaskCheckpoint(pid, res.task_id, if (res.audit_verdict == .unavailable) "audit_unavailable" else if (res.success) "completed" else "failed");
                }
            }
        }

        // ── Auto-auditoría / corrección ───────────────────────────────────
        var audit_cycles: usize = 0;
        var audit_pass: usize = 0;
        var audit_fail: usize = 0;
        var corrected: usize = 0;
        // r2 (P1): candidatos de corrección ya despachados por tarea
        // en esta orden, acumulados entre los ciclos de MAX_AUDIT_CYCLES para
        // que ninguno se repita (ver CorrectionAttempt).
        var correction_attempts: std.ArrayListUnmanaged(CorrectionAttempt) = .empty;
        defer {
            for (correction_attempts.items) |t| {
                self.allocator.free(t.task_id);
                self.allocator.free(t.model_name);
            }
            correction_attempts.deinit(self.allocator);
        }
        // a standalone audit order ("audita …") produces a prose
        // deliverable that must meet the prose rule; an internal audit report
        // inside a code order is evidence, not a delivery. Computed once so the
        // deterministic prose checks use the same distinction as the semantic
        // gate's inventory.
        const es_auditoria = ordenEsAuditoria(self, outcome.order_id);

        while (audit_cycles < MAX_AUDIT_CYCLES) : (audit_cycles += 1) {
            var any_fail = false;
            const corrected_before = corrected;
            audit_pass = 0;
            audit_fail = 0;
            // Las pruebas de la ola ya terminaron. Promover su exit real antes
            // de visitar productores deja una pasada completa para reejecutar y
            // revisar consumidores recuperados dentro de MAX_AUDIT_CYCLES.
            promoteFailedTestEvidence(&ctx);
            promoteFailedAuditEvidence(&ctx);
            // BGATE-1: la comprobación en navegador real va con las otras dos
            // promociones de evidencia; ninguna de ellas cree lo que el modelo dice
            // de su propio trabajo.
            runBrowserGateEvidence(&ctx);
            audit_results: for (ctx.results.items) |*res| {
                // AUDIT-UNAVAILABLE-P0: una auditoría sin veredicto usable no
                // entra al gate determinista ni a la corrección automática.
                // Reintentarla gasta cuota y es decisión explícita del usuario
                // ("Reintentar auditoría" → resume), no un reintento implícito
                // del ciclo — ni un PASS ni un FAIL que nadie emitió.
                if (res.audit_verdict == .unavailable) continue;
                if (std.mem.indexOf(u8, res.error_msg, "HANDOFF_BLOCKED") != null) continue;
                const repairable_contract_rejection = isRepairableContractRejection(res.*);
                // una tarea que murió con `worker_failed`/`InvalidArtifact`
                // (sin artefacto) también entra a la corrección. Antes se saltaba
                // (`!integrated` + sin rechazo de contrato) y la orden moría por ella.
                const repairable_worker_failure = isRepairableWorkerFailure(res.*);
                if (!res.integrated and !repairable_contract_rejection and !repairable_worker_failure) continue;
                var audit_failed = repairable_contract_rejection or repairable_worker_failure;

                const original_task = findPlannedTask(outcome.plan.tasks, res.task_id);

                // CHECKPOINT-T2: un resultado restaurado no tiene evidencia en
                // memoria — solo se re-verifica que su artefacto siga en disco
                // y válido. Si desapareció o se corrompió, el checkpoint ya no
                // vale: se declara inválido y cae al flujo normal de
                // corrección/re-ejecución. Una restaurada sin artefacto solo
                // es creíble en tipos que no materializan archivo (auditar,
                // documentar…); un productor 'completed' sin archivo en disco
                // no tiene evidencia que validar.
                if (res.restored) {
                    const needs_artifact = if (original_task) |pt|
                        !correctionMaySucceedWithoutArtifact(pt.task_type)
                    else
                        true;
                    const artifact_ok = if (res.saved_path) |path|
                        self.savedFileExists(path) and !self.isResultContentTriviallyInvalid(res.*, path, original_task, es_auditoria)
                    else
                        !needs_artifact;
                    if (!artifact_ok) {
                        audit_failed = true;
                        res.success = false;
                        res.integrated = false;
                        self.allocator.free(res.error_msg);
                        res.error_msg = self.allocator.dupe(u8, "CHECKPOINT_INVALID: el artefacto restaurado no existe en disco o no es válido; la tarea se re-ejecuta entera") catch "";
                    } else {
                        audit_pass += 1;
                        appendAuditEntry(self.allocator, &ctx.audit_entries, self.event_conn, self.event_order_id, .{
                            .ts = 0,
                            .subject_kind = "task",
                            .subject_id = idToInt(res.task_id),
                            .action = "AUDIT",
                            .verdict = "PASS",
                            .model_id = "",
                            .provider = "deterministic-gate",
                            .evidence_ref = res.saved_path orelse "",
                            .notes = "checkpoint artifact revalidated",
                        });
                        continue :audit_results;
                    }
                }

                // Criterio 1 (compatibilidad): BUG_SEEDED sembrado en tests previos.
                if (std.mem.indexOf(u8, res.error_msg, "BUG_SEEDED") != null) {
                    audit_failed = true;
                }
                // Un test ejecutable fallido es evidencia contra su productor,
                // aunque este hubiera terminado con exit=0 al arrancar.
                if (std.mem.indexOf(u8, res.error_msg, "TEST_EVIDENCE_FAILED") != null) {
                    audit_failed = true;
                }
                if (std.mem.indexOf(u8, res.error_msg, "AUDIT_EVIDENCE_FAILED") != null) {
                    audit_failed = true;
                }
                // BGATE-1: un control que no reacciona en un navegador real es
                // un hecho observado, no un veredicto opinable. Vale como fallo
                // aunque el test propio del entregable haya devuelto exit 0.
                if (std.mem.indexOf(u8, res.error_msg, "BROWSER_GATE_FAILED") != null) {
                    audit_failed = true;
                }
                // Criterio 2 (FIRE-05): ejecutó y devolvió exit_code != 0.
                // EXEC-SHOW: un proceso continuo terminado por timeout (timed_out) NO es un
                // fallo de exit — corrió y mostró su salida; no se re-despacha como corrección.
                // usage_only tampoco — un mensaje de uso tras lanzar SIN
                // argumentos no es un fallo del artefacto (se emitió exec_skipped).
                if (res.exec.ran and res.exec.exit_code != 0 and !res.exec.timed_out and !res.exec.usage_only) {
                    audit_failed = true;
                }
                // Criterio 3 (FIRE-02): contenido trivialmente inválido para su lenguaje.
                if (res.saved_path) |path| {
                    if (self.isResultContentTriviallyInvalid(res.*, path, original_task, es_auditoria)) {
                        audit_failed = true;
                    }
                }
                // P1-FALSE-GREEN: un worker de testing/auditoria puede cumplir el
                // contrato estructural y, correctamente, reportar FAIL. Ese FAIL
                // es evidencia de producto, no un artefacto exitoso. Antes se
                // ignoraba y la orden terminaba done (orden E2E 352).
                if (original_task) |pt| {
                    if (self.hasInvalidSavedProse(&ctx, pt, es_auditoria)) {
                        audit_failed = true;
                        const prose_error = try self.allocator.dupe(u8, "entregable de prosa en disco: metadatos o contenido insuficiente para la orden");
                        self.allocator.free(res.error_msg);
                        res.error_msg = prose_error;
                    }
                    if (taskArtifactsDeclareFailure(pt.task_type, res.artifacts)) {
                        audit_failed = true;
                    }
                    // Un PASS narrativo no cierra testing: exige un comando que
                    // haya terminado con éxito contra la revisión del productor.
                    if (pt.task_type == .testear and pt.depends_on.len > 0 and !hasExecutableTestEvidence(res.*)) {
                        audit_failed = true;
                    }
                }
                // Criterio 4: artefacto que requiere aprobación de ejecución NO es fallo
                // de auditoría (no se pudo ejecutar por política, no "ejecutó y falló").
                // Este caso se distingue porque res.exec.ran == false y
                // res.exec.needs_approval == true → NO marcamos audit_failed.

                if (audit_failed) {
                    any_fail = true;
                    audit_fail += 1;
                    // E-GOV.1 (rama e5-gov, reescrito en la tanda 3): el FAIL del
                    // gate explica siempre archivo, esperado, observado y causa.
                    // Va solo a la fila del libro mayor: `error_msg` no se toca,
                    // porque el ciclo de corrección decide con sus marcas.
                    const gate_notes = try deterministicFailureNotes(self.allocator, res.*, original_task);
                    defer self.allocator.free(gate_notes);
                    // P5b: AUDIT FAIL entry. La firma es el gate determinista del
                    // motor — NO el modelo productor (que es quien construyó lo
                    // que aquí se rechaza; su identidad ya está en la fila BUILD).
                    // Firmarlo con res.model_used hacía que el ledger mintiera:
                    // un AUDIT PASS/FAIL atribuido al productor simulaba
                    // auto-auditoría independiente.
                    appendAuditEntry(self.allocator, &ctx.audit_entries, self.event_conn, self.event_order_id, .{
                        .ts = 0,
                        .subject_kind = "task",
                        .subject_id = idToInt(res.task_id),
                        .action = "AUDIT",
                        .verdict = "FAIL",
                        .model_id = "",
                        .provider = "deterministic-gate",
                        .evidence_ref = res.saved_path orelse "",
                        .notes = gate_notes,
                    });
                    // Una corrección que no alteró al productor ya fue probada.
                    // Mantener su evidencia y no repetir el mismo prompt en el
                    // último ciclo evita que un PASS textual posterior la tape.
                    if (std.mem.indexOf(u8, res.error_msg, "CORRECTION_NO_PRODUCER_CHANGE") != null) {
                        continue :audit_results;
                    }
                    // P5: si el fallo de ejecución es del ENTORNO y no del modelo,
                    // no se reintenta. Medido en la orden 157: el script moría en
                    // `input()` con EOFError porque el proceso no tiene stdin, y la
                    // orden lo re-ejecutó cuatro veces idéntico (determinista + el
                    // retry del ciclo de auditoría que, con MAX_AUDIT_CYCLES=2,
                    // audita el MISMO resultado dos veces). Re-ejecutar el mismo
                    // artefacto con el mismo entorno produce el mismo EOF; pedirle
                    // al LLM una "corrección" tampoco cambia el entorno. Se deja la
                    // tarea fallida con la evidencia real y se sale del ciclo.
                    if (execFailureIsEnvironmental(res.exec.stderr)) {
                        self.allocator.free(res.error_msg);
                        res.error_msg = try self.allocator.dupe(
                            u8,
                            "FALLO DEL ENTORNO (no del modelo): el entorno no puede ejecutar esto (p. ej. stdin cerrado). No se reejecuta.",
                        );
                        continue :audit_results;
                    }
                    // Si la tarea es ejecutar y su productor fue corregido en esta
                    // misma pasada, la única corrección válida es volver a ejecutar
                    // el artefacto real. Un LLM no puede declarar reparado un exit=1.
                    if (original_task) |pt| {
                        // / E-GOV.3 (rama e5-gov): con un agente CLI
                        // fijado no hay política aprobada de reintento por la
                        // nube; se conserva la causa real sin «corregir» con
                        // otro proveedor.
                        const fixed_pin = self.pinFor(pt.task_type);
                        if (fixed_pin.provider != null and external_agents.isAgentProvider(fixed_pin.provider.?)) continue :audit_results;
                        if (pt.task_type == .ejecutar) {
                            if (dependencySavedPath(pt, ctx.results.items)) |dep_path| {
                                const retry_exec = self.governedExecute(dep_path, pt.id, &ctx.outputs, &ctx.pending) catch ExecOutcome{
                                    .ran = false,
                                    .exit_code = 0,
                                    .needs_approval = false,
                                    .stderr = self.allocator.dupe(u8, "retry execution failed") catch "",
                                };
                                // governedExecute ya marco el uso sin
                                // argumentos de este reintento por archivo.
                                if (taskExecutionSucceeded(.ejecutar, true, true, retry_exec)) {
                                    self.allocator.free(res.exec.stderr);
                                    if (res.exec.stdout) |stdout| self.allocator.free(stdout);
                                    res.exec = retry_exec;
                                    res.success = true;
                                    res.integrated = true;
                                    self.allocator.free(res.error_msg);
                                    res.error_msg = try self.allocator.dupe(u8, if (retry_exec.usage_only) "CORREGIDO" else "CORREGIDO Y REEJECUTADO");
                                    recordRecoveredExecOmission(&ctx, res, dep_path);
                                    corrected += 1;
                                    appendAuditEntry(self.allocator, &ctx.audit_entries, self.event_conn, self.event_order_id, .{
                                        .ts = 0,
                                        .subject_kind = "task",
                                        .subject_id = idToInt(res.task_id),
                                        .action = "FIX",
                                        .verdict = "PASS",
                                        .model_id = res.model_used,
                                        .provider = "executor",
                                        .evidence_ref = dep_path,
                                        .notes = if (retry_exec.usage_only) "dependency correction accepted; execution not verified: programa_requiere_argumentos" else "corrected dependency re-executed",
                                    });
                                    continue :audit_results;
                                }
                                self.allocator.free(retry_exec.stderr);
                                continue :audit_results;
                            }
                        }
                        // La corrección de una prueba no puede sustituir un
                        // exit fallido con texto o JSON. Solo la reejecución del
                        // comando del contrato, tras corregir su productor,
                        // puede producir evidencia nueva.
                        if (!genericCorrectionAllowed(pt, res.artifacts)) {
                            continue :audit_results;
                        }
                    }
                    // dejar constancia en los eventos (Monitor) de que
                    // esta tarea se reintenta por un fallo del worker y no por un
                    // rechazo de contrato. El motivo real viaja en `reason`.
                    // r2 (P1): antes de emitir el reintento y
                    // re-despachar se comprueban cancelación y gasto. `worker_retry_choice`
                    // guarda el candidato elegido para reusarlo en el re-despacho.
                    var worker_retry_choice: ?CorrectionChoice = null;
                    if (repairable_worker_failure and !repairable_contract_rejection) {
                        // El plazo vencido de la orden ya pidió cancelación al
                        // watchdog (c_api.zig:6485), así que el token cubre
                        // cancelación del usuario Y plazo agotado: no se arranca
                        // una corrección que nadie espera.
                        if (ctx.cancel_token) |token| {
                            if (token.isCancelled()) continue :audit_results;
                        }
                        const choice = self.correctionChoice(outcome.assignments, res.task_id, res.model_used, correction_attempts.items) orelse {
                            // r3 (P1): cadena agotada — no se repite
                            // un modelo ya intentado. La tarea queda fallida y
                            // la causa honesta viaja a `order_failed.reason`.
                            self.markCorrectionChainExhausted(res);
                            continue :audit_results;
                        };
                        // Gasto acotado: un reintento por worker_failed no usa
                        // modelos de pago salvo pin manual (que manda y no rota).
                        // r2 (P1): con catálogo REAL la corrección
                        // re-despacha un candidato vivo y la política protege el
                        // gasto; sin catálogo (llm_fn inyectado, p.ej. tests o el
                        // despacho embebido) no hay proveedor al que cobrar, así
                        // que la política no aplica — bloquear ahí mataba el
                        // reintento de un worker_failed sin gasto que evitar.
                        const pinned_manual = self.forced_provider != null and self.forced_model != null;
                        const live_catalog = if (catalog_path) |cp| cp.len > 0 and !std.mem.eql(u8, cp, ":memory:") else false;
                        if (live_catalog and !workerRetryAllowed(choice.is_free, pinned_manual)) continue :audit_results;
                        worker_retry_choice = choice;
                        // r2 (P1): el candidato queda registrado para
                        // que el ciclo siguiente no lo repita si esta corrección
                        // también falla sin artefacto (res.model_used no avanza).
                        try rememberCorrectionAttempt(self.allocator, &correction_attempts, res.task_id, choice.model_name);
                        var retry_out: std.Io.Writer.Allocating = .init(self.allocator);
                        defer retry_out.deinit();
                        var retry_js: std.json.Stringify = .{ .writer = &retry_out.writer, .options = .{} };
                        retry_js.beginObject() catch {};
                        retry_js.objectField("task_id") catch {};
                        retry_js.write(res.task_id) catch {};
                        retry_js.objectField("cause") catch {};
                        retry_js.write("worker_failed") catch {};
                        retry_js.objectField("failed_model") catch {};
                        retry_js.write(res.model_used) catch {};
                        if (findAssignment(outcome.assignments, res.task_id)) |a| {
                            retry_js.objectField("provider") catch {};
                            retry_js.write(a.provider_name) catch {};
                            retry_js.objectField("assigned_model") catch {};
                            retry_js.write(a.model_name) catch {};
                        }
                        retry_js.objectField("retry_provider") catch {};
                        retry_js.write(choice.provider_name) catch {};
                        retry_js.objectField("retry_model") catch {};
                        retry_js.write(choice.model_name) catch {};
                        retry_js.objectField("reason") catch {};
                        retry_js.write(res.error_msg) catch {};
                        retry_js.endObject() catch {};
                        self.recordEvent("task_retry", retry_out.written());
                    }
                    // Re-despacho como corrección: recreamos la tarea con tipo corregir.
                    var sb = self.sandboxForTask(res.task_id) catch continue;
                    defer sb.deinit();
                    for (outcome.plan.tasks) |pt| {
                        if (std.mem.eql(u8, pt.id, res.task_id)) {
                            var corr_task = pt;
                            corr_task.task_type = .corregir;
                            const correction_evidence = if (res.error_msg.len > 0)
                                res.error_msg
                            else if (res.exec.stderr.len > 0)
                                res.exec.stderr
                            else
                                "La verificación real falló sin detalle adicional.";
                            corr_task.description = try buildCorrectionDescription(
                                self.allocator,
                                outcome.plan.understanding,
                                pt.description,
                                correction_evidence,
                            );
                            defer self.allocator.free(corr_task.description);
                            var correction_model_used: ?[]const u8 = null;
                            defer if (correction_model_used) |model| self.allocator.free(model);
                            const corr_result = blk: {
                                if (catalog_path) |cp| {
                                    // #874: la reparación consulta la MISMA puerta
                                    // medida que las productoras. Si el candidato
                                    // elegido no admite tools, se usa el siguiente
                                    // apto o se degrada sin herramientas — nunca se
                                    // gasta la reparación en un HTTP 422.
                                    var repair_gate_conn: ?db.Connection = null;
                                    if (cp.len > 0 and !std.mem.eql(u8, cp, ":memory:")) repair_gate_conn = db.Connection.open(self.allocator, cp) catch null;
                                    defer if (repair_gate_conn) |*gc| gc.close();
                                    const repair_choice = self.repairToolChoice(repair_gate_conn, outcome.assignments, pt.id, res.model_used, correction_attempts.items);
                                    // r3 (P1): sin candidato de
                                    // reparación tampoco se re-despacha: misma
                                    // cadena agotada, mismo motivo honesto.
                                    if (repair_choice == null and worker_retry_choice == null) {
                                        self.markCorrectionChainExhausted(res);
                                        continue :audit_results;
                                    }
                                    // r2 (P1): la corrección de un
                                    // rechazo de contrato también registra su
                                    // candidato — mismo riesgo de repetirlo en
                                    // el ciclo siguiente si vuelve a fracasar.
                                    if (worker_retry_choice == null and repair_choice != null)
                                        try rememberCorrectionAttempt(self.allocator, &correction_attempts, pt.id, repair_choice.?.model_name);
                                    // un reintento por worker_failed fija su candidato gratuito;
                                    // su modo de tools sale de la MISMA puerta medida (#874).
                                    const model_to_use = if (worker_retry_choice) |c| c.model_name else repair_choice.?.model_name;
                                    const provider_to_use = if (worker_retry_choice) |c| c.provider_name else repair_choice.?.provider_name;
                                    const repair_mode: TaskToolMode = if (worker_retry_choice == null) repair_choice.?.mode else if (repair_gate_conn != null and model_router.agenticGateFor(repair_gate_conn.?, provider_to_use, model_to_use, self.now) == .ok) .governed_exec else .none;
                                    var llm_opt = live_worker.LiveLlm.initExact(self.allocator, cp, provider_to_use, model_to_use);
                                    if (llm_opt) |*llm| {
                                        correction_model_used = self.allocator.dupe(u8, model_to_use) catch null;
                                        defer llm.deinit();
                                        llm.task_id = pt.id;
                                        if (!llm.setOwnedTraceConn(self.event_order_id)) llm.setOwnedHealthConnFromCatalogPath();
                                        var tool_root_buf: [4096]u8 = undefined;
                                        const tool_root = workspace.effectiveRoot(&tool_root_buf);
                                        // Las correcciones re-despachan como `corregir`;
                                        // su modo lo fija la puerta medida (#874): o
                                        // governed_exec con un candidato apto, o none.
                                        configureTaskLiveLlm(
                                            llm,
                                            repair_mode,
                                            tool_root,
                                            self.permission_config,
                                            self.plan_approved,
                                            self.order_origin,
                                            self.executor_spawn_fn,
                                            self.cancel_token,
                                            self.max_agent_iterations,
                                        );
                                        bindTaskBrowser(llm, ctx.browser, pt.id);
                                        const sp = self.systemPromptForDept("correccion") catch break;
                                        defer self.allocator.free(sp);
                                        var nw = worker_backend.NativeWorker.init(sp);
                                        if (ctx.plan_manifest) |pm| nw.setPlanManifest(pm);
                                        if (ctx.current_upstream) |uc| nw.setUpstreamContext(uc);
                                        nw.setLlmFn(llm, live_worker.LiveLlm.llmFn);
                                        // Keep the full correction/evidence and worker envelope.
                                        // LiveLlm selects the transcript with EACH candidate's window.
                                        llm.prepared_handoff = true;
                                        const repaired = nw.backend().run(self.allocator, corr_task, sb) catch {
                                            if (llm.handoff_blocked) {
                                                try self.markCorrectionHandoffFailure(res, provider_to_use, model_to_use, llm.last_error_name);
                                                continue :audit_results;
                                            }
                                            break;
                                        };
                                        break :blk repaired;
                                    }
                                    // No reparar un pin no disponible con un pool genérico.
                                    if (self.forced_provider != null and self.forced_model != null) break;
                                }
                                if (llm_fn) |f| {
                                    const sp = self.systemPromptForDept("correccion") catch break;
                                    defer self.allocator.free(sp);
                                    var nw = worker_backend.NativeWorker.init(sp);
                                    if (ctx.plan_manifest) |pm| nw.setPlanManifest(pm);
                                    if (ctx.current_upstream) |uc| nw.setUpstreamContext(uc);
                                    nw.setLlmFn(llm_ctx.?, f);
                                    // An injected offline backend has no catalog/provider
                                    // window. Preserve its transcript without inventing a
                                    // production model window or performing network I/O.
                                    const shared_live: ?*live_worker.LiveLlm = if (f == live_worker.LiveLlm.llmFn) @ptrCast(@alignCast(llm_ctx.?)) else null;
                                    const previous_prepared = if (shared_live) |l| l.prepared_handoff else false;
                                    defer if (shared_live) |l| {
                                        l.prepared_handoff = previous_prepared;
                                    };
                                    if (shared_live) |l| {
                                        l.prepared_handoff = true;
                                    } else {
                                        const description = buildCorrectionHandoffDescription(self.allocator, self.event_conn orelse self.runtime, self.event_order_id, outcome.plan.understanding, &nw, corr_task, std.math.maxInt(u32), null) catch |err| {
                                            try self.markCorrectionHandoffFailure(res, "", "", @errorName(err));
                                            continue :audit_results;
                                        };
                                        self.allocator.free(corr_task.description);
                                        corr_task.description = description;
                                    }
                                    break :blk nw.backend().run(self.allocator, corr_task, sb) catch {
                                        if (shared_live) |l| {
                                            if (l.handoff_blocked) {
                                                try self.markCorrectionHandoffFailure(res, "", "", l.last_error_name);
                                                continue :audit_results;
                                            }
                                        }
                                        break;
                                    };
                                }
                                var mw = worker_backend.MockWorker.init();
                                break :blk mw.backend().run(self.allocator, corr_task, sb) catch break;
                            };
                            defer corr_result.deinit(self.allocator);
                            const corr_ok = self.validatePieceForTask(corr_task, corr_result.artifacts) catch false;
                            const corr_semantic_ok = !taskArtifactsDeclareFailure(pt.task_type, corr_result.artifacts);
                            if (corr_ok and corr_semantic_ok) {
                                const evidence_requires_producer_change = isProducerType(pt.task_type) and
                                    (std.mem.indexOf(u8, res.error_msg, "TEST_EVIDENCE_FAILED") != null or
                                        std.mem.indexOf(u8, res.error_msg, "AUDIT_EVIDENCE_FAILED") != null or
                                        std.mem.indexOf(u8, res.error_msg, "BROWSER_GATE_FAILED") != null);
                                if (evidence_requires_producer_change and artifactSetsEqual(self.allocator, res.artifacts, corr_result.artifacts)) {
                                    const no_change = try std.fmt.allocPrint(
                                        self.allocator,
                                        "{s}\nCORRECTION_NO_PRODUCER_CHANGE: la corrección repitió los mismos artefactos; no se puede reauditar ni aceptar PASS sin cambio del productor.",
                                        .{utf8PrefixWithin(res.error_msg, 8192)},
                                    );
                                    self.allocator.free(res.error_msg);
                                    res.error_msg = no_change;
                                    res.success = false;
                                    // No persistir ni invalidar consumidores: siguen
                                    // ligados a la revisión original aún defectuosa.
                                    continue :audit_results;
                                }
                                if (correction_model_used) |actual_model| {
                                    self.allocator.free(res.model_used);
                                    res.model_used = self.allocator.dupe(u8, actual_model) catch "";
                                }
                                // FANOUT-02: la corrección NO se da por buena solo por presencia de
                                // campos. Re-persiste el artefacto corregido y lo RE-VERIFICA por
                                // EJECUCIÓN (cierra el falso-verde: una corrección que sigue sin
                                // compilar/correr o que es basura NO se marca como exitosa).
                                var corr_exec = ExecOutcome{ .ran = false, .exit_code = 0, .needs_approval = false, .stderr = self.allocator.dupe(u8, "") catch "" };
                                var new_path: ?[]const u8 = null;
                                if (workspace.persistTask(self.allocator, outcome.order_id, pt, corr_result.artifacts)) |maybe_path| {
                                    if (maybe_path) |p| {
                                        new_path = p;
                                        self.allocator.free(corr_exec.stderr);
                                        corr_exec = self.governedExecute(p, pt.id, &ctx.outputs, &ctx.pending) catch ExecOutcome{ .ran = false, .exit_code = 0, .needs_approval = false, .stderr = self.allocator.dupe(u8, "") catch "" };
                                    }
                                } else |_| {}
                                // governedExecute ya marco el uso sin
                                // argumentos de esta re-verificacion por archivo.
                                const runs_ok = !(corr_exec.ran and corr_exec.exit_code != 0 and !corr_exec.timed_out and !corr_exec.usage_only);
                                const content_ok = if (new_path) |p| !self.isResultContentTriviallyInvalid(res.*, p, pt, es_auditoria) else false;

                                if (new_path == null and correctionMaySucceedWithoutArtifact(pt.task_type)) {
                                    const updated_artifacts = try cloneArtifacts(self.allocator, corr_result.artifacts);
                                    freeOwnedArtifacts(self.allocator, res.artifacts);
                                    res.artifacts = updated_artifacts;
                                    invalidateDependentEvidence(&ctx, res.task_id);
                                    // Tarea sin artefacto materializable (p.ej. auditoría/documentación):
                                    // no hay nada que ejecutar; basta la validación de contrato.
                                    corrected += 1;
                                    // P5b: FIX entry — correction succeeded (no artifact).
                                    appendAuditEntry(self.allocator, &ctx.audit_entries, self.event_conn, self.event_order_id, .{
                                        .ts = 0,
                                        .subject_kind = "task",
                                        .subject_id = idToInt(res.task_id),
                                        .action = "FIX",
                                        .verdict = "PASS",
                                        .model_id = res.model_used,
                                        .provider = "correccion",
                                        .evidence_ref = "",
                                        .notes = "corrected (no artifact)",
                                    });
                                    res.integrated = true;
                                    res.success = true;
                                    self.allocator.free(res.error_msg);
                                    res.error_msg = try self.allocator.dupe(u8, "CORREGIDO");
                                    res.exec.ran = false;
                                    res.exec.exit_code = 0;
                                    self.allocator.free(corr_exec.stderr);
                                } else if (new_path != null and runs_ok and content_ok) {
                                    const updated_artifacts = try cloneArtifacts(self.allocator, corr_result.artifacts);
                                    freeOwnedArtifacts(self.allocator, res.artifacts);
                                    res.artifacts = updated_artifacts;
                                    invalidateDependentEvidence(&ctx, res.task_id);
                                    // La correccion es valida; usage_only deja la ejecucion sin verificar.
                                    corrected += 1;
                                    // P5b: FIX entry — correction succeeded with artifact.
                                    appendAuditEntry(self.allocator, &ctx.audit_entries, self.event_conn, self.event_order_id, .{
                                        .ts = 0,
                                        .subject_kind = "task",
                                        .subject_id = idToInt(res.task_id),
                                        .action = "FIX",
                                        .verdict = "PASS",
                                        .model_id = res.model_used,
                                        .provider = "correccion",
                                        .evidence_ref = new_path.?,
                                        .notes = "corrected",
                                    });
                                    if (res.saved_path) |old| self.allocator.free(old);
                                    res.saved_path = self.allocator.dupe(u8, new_path.?) catch null;
                                    // D7: la correccion la firma la MISMA tarea, para
                                    // que su artefacto corregido siga en su rama.
                                    if (ctx.saved.append(self.allocator, new_path.?)) |_| {
                                        ctx.saved_owner.append(self.allocator, res.task_id) catch {
                                            _ = ctx.saved.pop();
                                            self.allocator.free(new_path.?);
                                        };
                                    } else |_| self.allocator.free(new_path.?);
                                    self.allocator.free(res.exec.stderr);
                                    if (res.exec.stdout) |stdout| self.allocator.free(stdout);
                                    res.exec = corr_exec; // adopta ownership de corr_exec.stderr
                                    res.integrated = true;
                                    res.success = true;
                                    self.allocator.free(res.error_msg);
                                    res.error_msg = try self.allocator.dupe(u8, "CORREGIDO");
                                    recordRecoveredExecOmission(&ctx, res, res.saved_path orelse "");
                                } else {
                                    // La corrección no produce un artefacto que corra → liberar y
                                    // dejar la tarea fallida (el post-loop la marcará).
                                    if (new_path != null and !content_ok) {
                                        self.allocator.free(res.error_msg);
                                        res.error_msg = try self.allocator.dupe(u8, "La corrección fue rechazada: contiene simulación, pseudocódigo, TODOs u omisiones explícitas. Implementa el comportamiento real completo.");
                                    }
                                    if (new_path) |p| self.allocator.free(p);
                                    self.allocator.free(corr_exec.stderr);
                                    if (corr_exec.stdout) |stdout| self.allocator.free(stdout);
                                }
                            }
                            break;
                        }
                    }
                } else {
                    audit_pass += 1;
                    // P5b: AUDIT PASS entry del gate determinista (evidencia de
                    // ejecución/contrato del motor). model_id vacío a propósito:
                    // deriveStatus solo cuenta auditores con modelo real y
                    // distinto del constructor — esta fila es evidencia del
                    // motor, no una auditoría de modelo independiente.
                    appendAuditEntry(self.allocator, &ctx.audit_entries, self.event_conn, self.event_order_id, .{
                        .ts = 0,
                        .subject_kind = "task",
                        .subject_id = idToInt(res.task_id),
                        .action = "AUDIT",
                        .verdict = "PASS",
                        .model_id = "",
                        .provider = "deterministic-gate",
                        .evidence_ref = res.saved_path orelse "",
                        .notes = "",
                    });
                }
            }
            // Un consumidor recuperado necesita una pasada de auditoría completa.
            // Si la corrección cae en el último ciclo, se conserva bloqueado y la
            // orden falla por esa dependencia en vez de declarar éxito sin revisión.
            if (corrected > corrected_before and audit_cycles + 1 < MAX_AUDIT_CYCLES) {
                rerunRecoveredConsumers(&ctx);
            }
            if (!any_fail) break;
        }

        // P10-T3: Alimentar verdicts de auditoría al score real del modelo.
        if (self.router) |router| {
            for (ctx.results.items) |res| {
                // Buscar el task_type original de la tarea planificada.
                var task_type: model_router.TaskType = .programar;
                for (outcome.plan.tasks) |pt| {
                    if (std.mem.eql(u8, pt.id, res.task_id)) {
                        task_type = pt.task_type;
                        break;
                    }
                }
                // Resolver model_id numérico desde el nombre del modelo usado.
                if (self.lookupModelId(res.model_used) catch null) |mid| {
                    const verdict: model_router.AuditVerdict = if (res.success) .pass else .fail;
                    router.recordAuditVerdict(mid, task_type, verdict) catch {};
                }

                // P12-T5: Record tool verdicts for (tool_name, task_type) learning.
                if (ctx.task_selections) |sels| {
                    for (sels) |sel| {
                        if (!std.mem.eql(u8, sel.task_id, res.task_id)) continue;
                        var tool_score_store = tool_discovery.ToolScoreStore.init(self.runtime, health.nowSeconds(self.runtime));
                        const tt_str = task_type.toText();
                        for (sel.needed) |tool_res| {
                            tool_score_store.recordVerdict(tool_res.name, tt_str, res.success);
                        }
                    }
                }
            }
        }

        // P7: Narrador — auditoría completada
        if (audit_cycles > 0) {
            var out: std.Io.Writer.Allocating = .init(self.allocator);
            defer out.deinit();
            var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
            js.beginObject() catch {};
            js.objectField("text") catch {};
            const label = std.fmt.allocPrint(self.allocator, "Auditoría completada: {d} pasada(s), {d} corregida(s), {d} fallida(s)", .{ audit_pass, corrected, audit_fail }) catch "Auditoría completada";
            defer self.allocator.free(label);
            js.write(label) catch {};
            js.endObject() catch {};
            self.recordEvent("superagent_thinking", out.written());
        }

        // Post-auditoría: si tras todos los ciclos una tarea integrada sigue fallando,
        // la marcamos como NO integrada / NO exitosa para que el reporte refleje la realidad.
        for (ctx.results.items) |*res| {
            if (!res.integrated) continue;
            var still_failing = false;
            if (std.mem.indexOf(u8, res.error_msg, "BUG_SEEDED") != null) still_failing = true;
            if (std.mem.indexOf(u8, res.error_msg, "AUDIT_EVIDENCE_FAILED") != null) still_failing = true;
            // EXEC-SHOW: un proceso continuo terminado por timeout (timed_out) corrió y mostró
            // su salida; NO es un fallo de exit (igual que el criterio 2 de la auto-auditoría).
            // usage_only tampoco (uso por ejecución sin argumentos).
            if (res.exec.ran and res.exec.exit_code != 0 and !res.exec.timed_out and !res.exec.usage_only) still_failing = true;
            if (res.saved_path) |path| {
                if (self.isResultContentTriviallyInvalid(res.*, path, findPlannedTask(outcome.plan.tasks, res.task_id), es_auditoria)) still_failing = true;
            }
            if (findPlannedTask(outcome.plan.tasks, res.task_id)) |pt| {
                if (self.hasInvalidSavedProse(&ctx, pt, es_auditoria)) still_failing = true;
                if (taskArtifactsDeclareFailure(pt.task_type, res.artifacts)) still_failing = true;
                if (pt.task_type == .testear and pt.depends_on.len > 0 and !hasExecutableTestEvidence(res.*)) {
                    still_failing = true;
                }
                if (pt.task_type == .ejecutar and
                    !res.exec.needs_approval and
                    (!res.exec.ran or (res.exec.exit_code != 0 and !res.exec.timed_out and !res.exec.usage_only)))
                {
                    still_failing = true;
                }
            }
            if (still_failing) {
                res.success = false;
                res.integrated = false;
            }
        }

        // Recalcular conteos finales a partir del estado REAL de cada TaskRunResult.
        var final_completed: usize = 0;
        var final_failed: usize = 0;
        var final_integrated: usize = 0;
        // AUDIT-UNAVAILABLE-P0: las auditorías sin veredicto usable se cuentan
        // APARTE — ni completadas (no entregaron veredicto) ni fallidas (el
        // fallo no es del producto). De este conteo sale el cierre
        // 'audit_unavailable' de la orden.
        var audit_unavailable_count: usize = 0;
        for (ctx.results.items) |res| {
            if (res.audit_verdict == .unavailable) {
                audit_unavailable_count += 1;
                continue;
            }
            if (res.success) final_completed += 1 else final_failed += 1;
            if (res.integrated) final_integrated += 1;
        }

        // D2: Persistir el estado de CADA tarea en la DB según su resultado real.
        // Antes, las tareas quedaban en 'planned' para siempre porque solo se
        // actualizaban a 'failed' cuando la orden entera fallaba — nunca a
        // 'completed' cuando tenía éxito.
        if (outcome.plan_id) |pid| {
            for (ctx.results.items) |res| {
                // AUDIT-UNAVAILABLE-P0: mismo criterio que el checkpoint por ola —
                // la auditoría sin veredicto no es 'completed' ni 'failed'.
                const task_status: []const u8 = if (res.audit_verdict == .unavailable) "audit_unavailable" else if (res.success) "completed" else "failed";
                const ts_stmt = self.runtime.prepare("UPDATE tasks SET status = ? WHERE plan_id = ? AND description = ?") catch continue;
                defer self.runtime.finalize(ts_stmt);
                db.bindText(ts_stmt, 1, task_status) catch continue;
                db.bindInt(ts_stmt, 2, pid) catch continue;
                // Find the task description from the plan
                var desc: []const u8 = "";
                for (outcome.plan.tasks) |pt| {
                    if (std.mem.eql(u8, pt.id, res.task_id)) {
                        desc = pt.description;
                        break;
                    }
                }
                if (desc.len == 0) continue;
                db.bindText(ts_stmt, 3, desc) catch continue;
                _ = db.c.sqlite3_step(ts_stmt);
            }
        }

        // Guardar programas materializados en disco.
        // Owned: se liberan tras construir el reporte.
        var saved = std.ArrayList([]const u8).empty;
        defer {
            for (saved.items) |p| self.allocator.free(p);
            saved.deinit(self.allocator);
        }

        // Copiar saved de ctx al array local para el reporte.
        for (ctx.saved.items) |p| {
            try saved.append(self.allocator, try self.allocator.dupe(u8, p));
        }

        // P-EXEC-4: si hay aprobaciones de ejecución pendientes (con exe), la orden
        // queda pausada en awaiting_approval — NO se marca done. La orden avanza a
        // done cuando todas las aprobaciones de ejecución se resuelven.
        const has_exec_approvals = blk: {
            for (ctx.pending.items) |pa| {
                if (pa.exe != null) break :blk true;
            }
            break :blk false;
        };

        // P1-FALSE-GREEN: si NINGUNA tarea completó con éxito (0 tasks, o todas
        // falladas por provider/auth/quota/empty), la orden NO puede terminar como
        // done — sería un falso verde. Se marca failed con causa accionable.
        // D2: también verifica si alguna tarea con success=true tuvo ejecución con
        // exit_code != 0 (y no fue timeout) — eso es un fallo real, no un done.
        // D2: si ctx.results.items.len < plan.tasks.len, algunas tareas nunca se
        // ejecutaron (siguen en 'planned') — la orden NO puede ser done.
        var exec_failed: bool = false;
        for (ctx.results.items) |res| {
            // usage_only (mensaje de uso por ejecución sin argumentos)
            // tampoco bloquea el cierre done — no es un fallo real de exit.
            if (res.exec.ran and res.exec.exit_code != 0 and !res.exec.timed_out and !res.exec.usage_only) {
                exec_failed = true;
                break;
            }
        }
        const tasks_missing = ctx.results.items.len < outcome.plan.tasks.len;
        // C2 requisito D: la cancelación gana la decisión terminal sobre
        // done/failed/awaiting_approval — se comprueba UNA vez aquí, después de que
        // todas las olas de esta llamada a approveAndDispatch ya terminaron.
        const cancelled_now = ctx.cancel_token != null and ctx.cancel_token.?.isCancelled();

        // SEMANTIC-GATE-T3: capa SOBRE el gate de ejecución — 'done' exige que
        // el observable declarado (orders.expected_result o 'expects' del plan)
        // se cumpla de verdad. No corre si la orden se pausa en aprobación de
        // ejecución ni si fue cancelada: esta pasada no es la que la cierra.
        // Sin nada declarado el gate informa ran:false y no altera el veredicto.
        var semantic_ran = false;
        var semantic_failed = false;
        var semantic_note: ?[]const u8 = null;
        defer if (semantic_note) |n| self.allocator.free(n);
        if (!has_exec_approvals and !cancelled_now) {
            const sem = try self.evaluateSemanticGate(&ctx, outcome);
            semantic_ran = sem.ran;
            semantic_failed = sem.failed;
            semantic_note = sem.note;
        }
        // AUDIT-UNAVAILABLE-P0: si lo ÚNICO que falta es la revisión del auditor
        // (cero fallos reales, cero ejecución rota, cero tareas sin correr y el
        // gate semántico en verde), la orden cierra 'audit_unavailable': el
        // entregable está construido y conservado, pero la entrega queda
        // bloqueada hasta una auditoría válida. Nunca 'done' (falso verde) ni
        // 'failed' (no hay defecto medido). Una cancelación o una aprobación de
        // ejecución pendiente ganan antes — igual que en el resto de la máquina.
        const budget_failed = for (ctx.results.items) |res| {
            if (!res.success and res.paid_budget_exhausted) break true;
        } else false;
        const order_audit_unavailable = !budget_failed and audit_unavailable_count > 0 and
            final_failed == 0 and !exec_failed and !tasks_missing and
            !semantic_failed and !has_exec_approvals and !cancelled_now;
        const order_really_failed = !order_audit_unavailable and
            (budget_failed or final_failed > 0 or final_completed == 0 or exec_failed or tasks_missing or semantic_failed) and !has_exec_approvals;

        if (!self.defer_order_finalization and has_exec_approvals) {
            try self.updateOrderStatus(outcome.order_id, OrderStatus.awaiting_approval.toText());
        } else if (!self.defer_order_finalization and order_really_failed) {
            // TERMINAL-STATE-DESIGN-2026-07-12: el status 'failed' ya no se escribe
            // aquí — se une al evento order_failed más abajo en una sola transición
            // atómica (commitTerminal). D2: no blanket-update all tasks to failed —
            // individual statuses were already set above based on actual results.
            // Only mark tasks that are STILL in 'planned' (never ran) as 'failed'.
            if (outcome.plan_id) |pid| {
                const ps = self.runtime.prepare("UPDATE tasks SET status = 'failed' WHERE plan_id = ? AND status = 'planned'") catch null;
                if (ps) |stmt| {
                    defer self.runtime.finalize(stmt);
                    db.bindInt(stmt, 1, pid) catch {};
                    _ = db.c.sqlite3_step(stmt);
                }
            }
        }
        // El caso 'done' (!order_really_failed, !has_exec_approvals) ya no escribe
        // status aquí tampoco: se une al evento order_done más abajo (commitTerminal).

        // P10-T2: Persistir lección estructurada cuando la orden falla. C2: una
        // cancelación explícita no es una lección de fallo técnico — se excluye.
        if (order_really_failed and !self.defer_order_finalization and !cancelled_now) {
            // Fetch order info from DB for the lesson.
            // T8: se copian antes de finalizar la sentencia. Antes las rebanadas
            // apuntaban a memoria de SQLite ya liberada (la lección se guardaba
            // con un prompt y un proyecto basura o vacíos; lo destapó la prueba
            // de memory_lesson_saved_v1).
            var user_prompt: []const u8 = "";
            var project_id: []const u8 = "";
            defer if (user_prompt.len > 0) self.allocator.free(user_prompt);
            defer if (project_id.len > 0) self.allocator.free(project_id);
            {
                const ostmt = self.runtime.prepare("SELECT user_prompt, project_id FROM orders WHERE id = ?") catch null;
                if (ostmt) |os| {
                    defer self.runtime.finalize(os);
                    db.bindInt(os, 1, outcome.order_id) catch {};
                    if (db.c.sqlite3_step(os) == db.c.SQLITE_ROW) {
                        const uptr = db.c.sqlite3_column_text(os, 0);
                        const ulen = db.c.sqlite3_column_bytes(os, 0);
                        if (uptr != null and ulen > 0) user_prompt = self.allocator.dupe(u8, uptr[0..@intCast(ulen)]) catch "";
                        const pptr = db.c.sqlite3_column_text(os, 1);
                        const plen = db.c.sqlite3_column_bytes(os, 1);
                        if (pptr != null and plen > 0) project_id = self.allocator.dupe(u8, pptr[0..@intCast(plen)]) catch "";
                    }
                }
            }
            var lesson: std.Io.Writer.Allocating = .init(self.allocator);
            defer lesson.deinit();
            var ljs: std.json.Stringify = .{ .writer = &lesson.writer, .options = .{} };
            ljs.beginObject() catch {};
            ljs.objectField("order_id") catch {};
            ljs.write(outcome.order_id) catch {};
            ljs.objectField("prompt") catch {};
            ljs.write(user_prompt) catch {};
            ljs.objectField("cause") catch {};
            if (outcome.plan.tasks.len == 0) {
                ljs.write("planner_empty_plan") catch {};
            } else if (tasks_missing) {
                ljs.write("tasks_not_executed") catch {};
            } else if (exec_failed and final_completed > 0) {
                ljs.write("execution_failed") catch {};
            } else if (final_failed > 0) {
                ljs.write("all_tasks_failed") catch {};
            } else {
                ljs.write("no_tasks_completed") catch {};
            }
            // Detalles por tarea fallida.
            ljs.objectField("failed_tasks") catch {};
            ljs.beginArray() catch {};
            for (ctx.results.items) |res| {
                if (res.success) continue;
                ljs.beginObject() catch continue;
                ljs.objectField("task_id") catch continue;
                ljs.write(res.task_id) catch continue;
                ljs.objectField("model") catch continue;
                ljs.write(res.model_used) catch continue;
                ljs.objectField("error") catch continue;
                ljs.write(res.error_msg) catch continue;
                ljs.endObject() catch continue;
            }
            ljs.endArray() catch {};
            ljs.objectField("recommendation") catch {};
            ljs.write("Consider alternative models or simplify the task decomposition.") catch {};
            ljs.endObject() catch {};
            if (self.memory.saveLesson(lesson.written(), project_id)) {
                // T8: mismo título que verá el nodo Memoria.
                var title_arena = std.heap.ArenaAllocator.init(self.allocator);
                defer title_arena.deinit();
                const title = lessonTitle(title_arena.allocator(), lesson.written());
                if (std.json.Stringify.valueAlloc(self.allocator, .{ .title = title }, .{})) |payload| {
                    defer self.allocator.free(payload);
                    self.recordEvent("memory_lesson_saved_v1", payload);
                } else |_| self.notarEventoPerdido();
            }
        }

        // P7: Narrador — resumen final de la orden antes del evento order_done/order_failed.
        {
            var out: std.Io.Writer.Allocating = .init(self.allocator);
            defer out.deinit();
            var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
            js.beginObject() catch {};
            js.objectField("text") catch {};
            const audit_suffix = if (audit_unavailable_count > 0)
                std.fmt.allocPrint(self.allocator, ", {d} sin auditar", .{audit_unavailable_count}) catch ""
            else
                "";
            defer if (audit_suffix.len > 0) self.allocator.free(audit_suffix);
            const label = if (self.defer_order_finalization)
                std.fmt.allocPrint(self.allocator, "Iteración finalizada: {d} completada(s), {d} fallida(s), {d} integrada(s){s}", .{ final_completed, final_failed, final_integrated, audit_suffix }) catch "Iteración finalizada"
            else
                std.fmt.allocPrint(self.allocator, "Orden finalizada: {d} completada(s), {d} fallida(s), {d} integrada(s){s}", .{ final_completed, final_failed, final_integrated, audit_suffix }) catch "Orden finalizada";
            defer self.allocator.free(label);
            js.write(label) catch {};
            js.endObject() catch {};
            self.recordEvent("superagent_thinking", out.written());
        }

        // F0: emitir evento order_done u order_failed con causa accionable.
        {
            var out: std.Io.Writer.Allocating = .init(self.allocator);
            defer out.deinit();
            var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
            js.beginObject() catch {};
            js.objectField("completed") catch {};
            js.write(final_completed) catch {};
            js.objectField("failed") catch {};
            js.write(final_failed) catch {};
            js.objectField("integrated") catch {};
            js.write(final_integrated) catch {};
            js.objectField("has_pending_approvals") catch {};
            js.write(ctx.pending.items.len > 0) catch {};
            js.objectField("audit_unavailable") catch {};
            js.write(audit_unavailable_count) catch {};
            if (order_audit_unavailable) {
                // AUDIT-UNAVAILABLE-P0: causa accionable + qué tareas quedaron
                // sin veredicto — la UI lo muestra como "Sin auditar" y ofrece
                // el reintento manual de la auditoría.
                js.objectField("cause") catch {};
                js.write("audit_unavailable") catch {};
                js.objectField("audit_unavailable_tasks") catch {};
                js.beginArray() catch {};
                for (ctx.results.items) |res| {
                    if (res.audit_verdict == .unavailable) js.write(res.task_id) catch {};
                }
                js.endArray() catch {};
            }
            if (order_really_failed) {
                // Causa accionable: explicar por qué la orden falló sin inspeccionar logs.
                js.objectField("cause") catch {};
                if (budget_failed) {
                    js.write("paid_budget_exhausted") catch return error.OutOfMemory;
                } else if (semantic_failed) {
                    // SEMANTIC-GATE-T3: las tareas corrieron y pasaron el gate
                    // de ejecución, pero el observable declarado no se cumple.
                    js.write("semantic_gate_failed") catch {};
                    js.objectField("diferencias") catch {};
                    js.write(semantic_note orelse "") catch {};
                } else if (outcome.plan.tasks.len == 0) {
                    js.write("planner_empty_plan") catch {};
                } else if (tasks_missing) {
                    js.write("tasks_not_executed") catch {};
                } else if (exec_failed and final_completed > 0) {
                    js.write("execution_failed") catch {};
                } else if (final_failed > 0) {
                    js.write(if (final_completed == 0) "all_tasks_failed" else "tasks_failed") catch {};
                } else {
                    js.write("no_tasks_completed") catch {};
                }
            }
            if (final_failed > 0 or budget_failed) {
                for (ctx.results.items) |res| {
                    if (res.success or std.mem.startsWith(u8, res.error_msg, "dependency")) continue;
                    js.objectField("reason") catch return error.OutOfMemory;
                    js.write(res.error_msg) catch return error.OutOfMemory;
                    break;
                }
            }
            js.endObject() catch {};
            if (self.defer_order_finalization) {
                self.recordEvent("iteration_completed", out.written());
            } else if (cancelled_now) {
                // C2 requisito D: la cancelación gana incluso sobre awaiting_approval —
                // una orden cancelada no debe quedar esperando una aprobación que ya
                // nadie va a resolver. Único terminal posible en esta rama: cancelled.
                _ = try self.commitTerminal(outcome.order_id, .cancelled, "order_cancelled", out.written());
            } else if (has_exec_approvals) {
                // awaiting_approval no es terminal (P-EXEC-4): todavía sin evento
                // terminal. El status ya quedó en awaiting_approval más arriba.
            } else {
                // AUDIT-UNAVAILABLE-P0: tercer cierre honesto — ni done ni failed.
                const terminal_status: OrderStatus = if (order_audit_unavailable) .audit_unavailable else if (order_really_failed) .failed else .done;
                const terminal_kind: []const u8 = if (order_audit_unavailable) "order_audit_unavailable_v1" else if (order_really_failed) "order_failed" else "order_done";
                _ = try self.commitTerminal(outcome.order_id, terminal_status, terminal_kind, out.written());
            }
        }

        const report = try self.buildReport(outcome, final_completed, final_failed, final_integrated, ctx.rejected, saved.items, audit_pass, audit_fail, audit_unavailable_count, corrected, concurrency_peak, restored_count, semantic_ran, semantic_note, null);

        // B6: el veredicto del auditor SE VE.
        //
        // Hasta ahora `appendAuditEntry` recibia `event_conn` y `order_id` y los
        // DESCARTABA (`_ = event_conn;`): el veredicto quedaba solo en
        // `audit_ledger`, que el usuario no mira nunca. Medido el 2026-08-15: la
        // orden #283 cerro en `done` con el auditor diciendo FAIL sobre un Python
        // correcto, y por la interfaz no se veia nada.
        //
        // Se emite AQUI y no en `appendAuditEntry` a proposito: aquel se llama
        // desde `runTaskInWave`, que corre en hilos fanout. Escribir a la conexion
        // compartida desde ahi es justo el molde del segfault que costo FIX-SEGFAULT-P0.
        // Este punto es el hilo del despacho, con las olas ya terminadas: un solo
        // escritor, sin carreras.
        //
        // NO bloquea (decision B6 opcion b): informa. Quien decide si vuelve a
        // intentarlo es el usuario, no un modelo evaluador que ya ha dado falsos
        // positivos.
        for (ctx.audit_entries.items) |e| {
            if (!std.mem.eql(u8, e.action, "AUDIT")) continue;
            var ev: std.Io.Writer.Allocating = .init(self.allocator);
            defer ev.deinit();
            var js: std.json.Stringify = .{ .writer = &ev.writer, .options = .{} };
            js.beginObject() catch continue;
            js.objectField("task_id") catch continue;
            js.write(e.subject_id) catch continue;
            js.objectField("verdict") catch continue;
            js.write(e.verdict) catch continue;
            js.objectField("model") catch continue;
            js.write(e.model_id) catch continue;
            js.objectField("provider") catch continue;
            js.write(e.provider) catch continue;
            js.objectField("notes") catch continue;
            js.write(e.notes) catch continue;
            // T8: campos aditivos; los lectores actuales de
            // task_audit (chat_activity, chat_panel, ui_diag, best_of_n,
            // order_graph) leen task_id/verdict/model/provider y los ignoran.
            js.objectField("auditor_index") catch continue;
            js.write(e.auditor_index) catch continue;
            js.objectField("role") catch continue;
            js.write(switch (e.auditor_index) {
                1 => "audit",
                2 => "second_audit",
                else => "deterministic_gate",
            }) catch continue;
            js.endObject() catch continue;
            self.recordEvent("task_audit", ev.written());
        }

        const audit_slice = try ctx.audit_entries.toOwnedSlice(self.allocator);

        // FASE-AGENTIC-2: el entregable real (no el meta-reporte) — se muestra al
        // usuario como respuesta del asistente en el chat (evento agent_message)
        // y se persiste como turno "agent" en messages (alimenta la memoria de
        // conversación de FASE 1 con el resultado real, no solo el entendimiento).
        const final_answer = synthesizeFinalAnswer(self.allocator, ctx.results.items, outcome.plan.tasks, ctx.outputs.items, final_completed, ctx.fallback_notes.items) catch
            try self.allocator.dupe(u8, report);
        if (!self.defer_order_finalization) {
            var fa_out: std.Io.Writer.Allocating = .init(self.allocator);
            defer fa_out.deinit();
            var fa_js: std.json.Stringify = .{ .writer = &fa_out.writer, .options = .{} };
            fa_js.beginObject() catch {};
            fa_js.objectField("text") catch {};
            fa_js.write(final_answer) catch {};
            fa_js.endObject() catch {};
            self.recordEvent("agent_message", fa_out.written());
        }

        return DispatchResult{
            .report = report,
            .outputs = try ctx.outputs.toOwnedSlice(self.allocator),
            .pending_approvals = try ctx.pending.toOwnedSlice(self.allocator),
            .failed_count = final_failed,
            .completed_count = final_completed,
            .integrated_count = final_integrated,
            .audit_entries = audit_slice,
            .final_answer = final_answer,
            .audit_unavailable_count = audit_unavailable_count,
            .order_audit_unavailable = order_audit_unavailable,
            .order_failed = order_really_failed and !cancelled_now,
            .paid_budget_exhausted = budget_failed,
            .paid_budget_reason = if (budget_failed) blk: {
                for (ctx.results.items) |res| {
                    if (res.paid_budget_exhausted) break :blk try self.allocator.dupe(u8, res.error_msg);
                }
                break :blk "";
            } else "",
            .order_cancelled = cancelled_now,
        };
    }

    /// Cierra una ejecución agéntica exactamente una vez, después de que el
    /// evaluador haya decidido terminar o se alcance el límite de iteraciones.
    fn finalizeDeferredOrder(self: *Superagent, order_id: i64, dr: *const DispatchResult) !void {
        const has_exec_approvals = blk: {
            for (dr.pending_approvals) |approval| {
                if (approval.exe != null) break :blk true;
            }
            break :blk false;
        };

        // C2 requisito D: mismo criterio que approveAndDispatch — cancelled gana
        // incluso sobre awaiting_approval (una orden cancelada no debe quedar
        // esperando una aprobación que ya nadie va a resolver).
        if (has_exec_approvals and !dr.order_cancelled) {
            try self.updateOrderStatus(order_id, OrderStatus.awaiting_approval.toText());
        }

        // Una orden pendiente de aprobación todavía no es terminal. Para el resto,
        // TERMINAL-STATE-DESIGN-2026-07-12: status + evento se escriben juntos vía
        // commitTerminal (antes eran updateOrderStatus + recordEvent por separado).
        if (dr.order_cancelled) {
            var out: std.Io.Writer.Allocating = .init(self.allocator);
            defer out.deinit();
            var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
            js.beginObject() catch {};
            js.objectField("completed") catch {};
            js.write(dr.completed_count) catch {};
            js.objectField("failed") catch {};
            js.write(dr.failed_count) catch {};
            js.endObject() catch {};
            _ = try self.commitTerminal(order_id, .cancelled, "order_cancelled", out.written());
        } else if (!has_exec_approvals) {
            var out: std.Io.Writer.Allocating = .init(self.allocator);
            defer out.deinit();
            var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
            js.beginObject() catch {};
            js.objectField("completed") catch {};
            js.write(dr.completed_count) catch {};
            js.objectField("failed") catch {};
            js.write(dr.failed_count) catch {};
            js.objectField("integrated") catch {};
            js.write(dr.integrated_count) catch {};
            js.objectField("has_pending_approvals") catch {};
            js.write(false) catch {};
            js.objectField("audit_unavailable") catch {};
            js.write(dr.audit_unavailable_count) catch {};
            if (dr.paid_budget_exhausted) {
                js.objectField("cause") catch return error.OutOfMemory;
                js.write("paid_budget_exhausted") catch return error.OutOfMemory;
                js.objectField("reason") catch return error.OutOfMemory;
                js.write(dr.paid_budget_reason) catch return error.OutOfMemory;
            } else if (dr.order_audit_unavailable) {
                js.objectField("cause") catch {};
                js.write("audit_unavailable") catch {};
            }
            js.endObject() catch {};
            // AUDIT-UNAVAILABLE-P0: mismo tercer terminal en la finalización
            // diferida del loop agéntico.
            const terminal_status: OrderStatus = if (dr.order_failed) .failed else if (dr.order_audit_unavailable) .audit_unavailable else .done;
            const terminal_kind: []const u8 = if (dr.order_failed) "order_failed" else if (dr.order_audit_unavailable) "order_audit_unavailable_v1" else "order_done";
            _ = try self.commitTerminal(order_id, terminal_status, terminal_kind, out.written());
        }

        var fa_out: std.Io.Writer.Allocating = .init(self.allocator);
        defer fa_out.deinit();
        var fa_js: std.json.Stringify = .{ .writer = &fa_out.writer, .options = .{} };
        fa_js.beginObject() catch {};
        fa_js.objectField("text") catch {};
        fa_js.write(dr.final_answer) catch {};
        fa_js.endObject() catch {};
        self.recordEvent("agent_message", fa_out.written());
    }

    /// A requested second auditor must get an actual task even if the LLM
    /// only planned one audit. Reuse the existing contract and dependencies.
    fn ensureComposerAudits(self: *Superagent, plan: *planner.Plan, order_id: i64) !void {
        const router = self.router orelse return;
        if (plan.kind != .build or plan.tasks.len == 0) return;
        const json = try composer_roles.forOrder(self.allocator, self.runtime, router.catalog, order_id);
        defer self.allocator.free(json);
        const parsed = try std.json.parseFromSlice([]composer_roles.Pin, self.allocator, json, .{});
        defer parsed.deinit();
        var second_requested = false;
        for (parsed.value) |pin| if (std.mem.eql(u8, pin.role, "second_audit")) {
            second_requested = true;
        };
        if (!second_requested) return;
        var count: usize = 0;
        for (plan.tasks) |task| if (task.task_type == .auditar) {
            count += 1;
        };
        if (count >= 2) return;
        if (count == 0) _ = try aseguraAuditoriaTerminal(plan);
        var first: ?planner.PlannedTask = null;
        for (plan.tasks) |task| if (task.task_type == .auditar) {
            first = task;
            break;
        };
        var second = try cloneD2Task(plan.allocator, first orelse return error.AuditTaskMissing);
        errdefer freeD2Task(plan.allocator, second);
        var serial: usize = 1;
        var id = try std.fmt.allocPrint(plan.allocator, "composer-second-audit-{d}", .{serial});
        while (idUsado(plan.tasks, id)) {
            plan.allocator.free(id);
            serial += 1;
            id = try std.fmt.allocPrint(plan.allocator, "composer-second-audit-{d}", .{serial});
        }
        plan.allocator.free(second.id);
        second.id = id;
        const expanded = try plan.allocator.alloc(planner.PlannedTask, plan.tasks.len + 1);
        @memcpy(expanded[0..plan.tasks.len], plan.tasks);
        expanded[plan.tasks.len] = second;
        plan.allocator.free(plan.tasks);
        plan.tasks = expanded;
    }

    /// FASE-AGENTIC-3: re-planifica un objetivo de seguimiento (`next_goal`) bajo
    /// la MISMA orden — inserta un plan NUEVO ligado a `order_id` (el esquema ya
    /// permite varios planes por orden). Es processOrder SIN insertOrder ni
    /// descubrimiento de herramientas (un paso de seguimiento reusa el contexto
    /// de la orden; no re-escanea skills/MCP). El OrderOutcome devuelto lo posee
    /// el llamador y debe deinit()earse.
    fn replanFollowUp(self: *Superagent, order_id: i64, from_plan_id: ?i64, next_goal: []const u8, backend: planner.PlannerBackend) !OrderOutcome {
        var plan = try backend.plan(self.allocator, next_goal, &.{}, null);
        errdefer plan.deinit();
        // Un follow-up autónomo no debe quedar bloqueado pidiendo clarificación:
        // si el planner la pide, se trata como "sin paso accionable" y se aborta
        // el follow-up (el loop se detiene, fail-safe).
        if (plan.needsClarification()) return error.FollowUpNeedsClarification;
        try expandExplicitMultiFilePlan(self.allocator, &plan, next_goal);
        try chainSiblingProducers(self.allocator, &plan);
        normalizePlan(plan.tasks);
        try self.ensureComposerAudits(&plan, order_id);
        const plan_id = try self.insertPlan(order_id, plan.understanding, &.{});
        // T8: el lazo Plan→Plan del grafo sale de aquí.
        self.recordReplan(order_id, "agent_follow_up", from_plan_id, plan_id, true, next_goal, plan.tasks.len);
        const assignments = try self.assignAndPersist(plan_id, plan.tasks);
        return .{
            .allocator = self.allocator,
            .order_id = order_id,
            .plan_id = plan_id,
            .status = .planned,
            .plan = plan,
            .assignments = assignments,
            .discovery_needed = try self.allocator.alloc([]const u8, 0),
            .discovery_missing = try self.allocator.alloc([]const u8, 0),
            .discovery_needed_resources = try self.allocator.alloc(tool_discovery.Resource, 0),
        };
    }

    /// FASE-AGENTIC-3: ejecuta una orden con el loop autónomo observe→re-planifica.
    ///
    /// Con `max_agent_iterations <= 1` (DEFAULT) o sin evaluador, es EXACTAMENTE
    /// `approveAndDispatch` una vez — ni el evaluador ni el re-plan corren, así que
    /// la ruta estable de hoy queda intacta (cero regresión). Con el gate abierto:
    ///   1. despacha el plan inicial;
    ///   2. OBSERVE: el evaluador (LLM) decide {done, next_goal, final_answer};
    ///   3. si !done y hay next_goal y quedan iteraciones: re-planifica y despacha;
    ///   4. repite hasta done / tope de iteraciones / evaluador sin respuesta.
    ///
    /// Todo corre en el hilo de dispatch (bg). El progreso se emite por recordEvent
    /// (seguro desde el bg thread); NUNCA se escribe ledger.db aquí.
    pub fn agenticExecute(
        self: *Superagent,
        outcome: *OrderOutcome,
        backend: planner.PlannerBackend,
        llm_fn: ?worker_backend.NativeWorker.LlmFn,
        llm_ctx: ?*anyopaque,
        catalog_path: ?[]const u8,
        goal: []const u8,
        evaluator_fn: ?EvaluatorFn,
        evaluator_ctx: ?*anyopaque,
    ) !DispatchResult {
        // GATE: default (1) o sin evaluador → un solo paso, idéntico a hoy.
        if (self.max_agent_iterations <= 1 or evaluator_fn == null or evaluator_ctx == null) {
            return self.approveAndDispatch(outcome, llm_fn, llm_ctx, catalog_path);
        }

        // En modo agéntico las iteraciones son internas: ninguna posee el estado
        // terminal ni publica la respuesta definitiva.
        self.defer_order_finalization = true;
        defer self.defer_order_finalization = false;
        var dr = try self.approveAndDispatch(outcome, llm_fn, llm_ctx, catalog_path);
        errdefer dr.deinit(self.allocator);

        // Fail closed: approveAndDispatch ya agotó su auditoría/corrección. Una
        // iteración con tareas fallidas no puede ser reemplazada y olvidada por
        // un follow-up del evaluador (orden 356 terminó done tras perder t1 failed).
        // AUDIT-UNAVAILABLE-P0: una iteración sin auditoría válida tampoco sigue —
        // la orden queda bloqueada hasta el reintento manual, no la tapa un
        // next_goal posterior.
        if (dr.order_failed or dr.order_cancelled or dr.order_audit_unavailable) {
            self.defer_order_finalization = false;
            try self.finalizeDeferredOrder(outcome.order_id, &dr);
            return dr;
        }

        // T8: plan vigente de la orden, origen del siguiente replan_v1.
        var current_plan_id: ?i64 = outcome.plan_id;
        var iteration: usize = 1;
        while (iteration < self.max_agent_iterations) : (iteration += 1) {
            // OBSERVE: ¿está cumplido el objetivo del usuario?
            const eval_prompt = buildEvaluatorPrompt(self.allocator, goal, dr.final_answer) catch break;
            defer self.allocator.free(eval_prompt);
            const raw = evaluator_fn.?(evaluator_ctx.?, EVALUATOR_SYSTEM_PROMPT, eval_prompt);
            if (raw.len == 0) break; // el evaluador no respondió (proveedores agotados) → parar.
            var decision = parseEvaluatorDecision(self.allocator, raw);
            defer decision.deinit(self.allocator);

            // Progreso del loop visible en el timeline.
            {
                var it_out: std.Io.Writer.Allocating = .init(self.allocator);
                defer it_out.deinit();
                var it_js: std.json.Stringify = .{ .writer = &it_out.writer, .options = .{} };
                it_js.beginObject() catch {};
                it_js.objectField("iteration") catch {};
                it_js.write(iteration) catch {};
                it_js.objectField("done") catch {};
                it_js.write(decision.done) catch {};
                if (decision.next_goal) |ng| {
                    it_js.objectField("next_goal") catch {};
                    it_js.write(ng) catch {};
                }
                it_js.endObject() catch {};
                self.recordEvent("agent_iteration", it_out.written());
            }

            if (decision.done) {
                // El evaluador puede consolidar una respuesta final mejor que el
                // último artefacto: si la da, reemplaza la de dr. La respuesta se
                // publica una sola vez al finalizar el loop.
                if (decision.final_answer) |fa| {
                    const dup = self.allocator.dupe(u8, fa) catch break;
                    if (dr.final_answer.len > 0) self.allocator.free(dr.final_answer);
                    dr.final_answer = dup;
                }
                break;
            }

            const next_goal = decision.next_goal orelse break;
            // Re-planifica y despacha el siguiente paso bajo la misma orden.
            var outcome2 = self.replanFollowUp(outcome.order_id, current_plan_id, next_goal, backend) catch break;
            current_plan_id = outcome2.plan_id;
            const dr2 = self.approveAndDispatch(&outcome2, llm_fn, llm_ctx, catalog_path) catch {
                outcome2.deinit();
                break;
            };
            outcome2.deinit();
            dr.deinit(self.allocator);
            dr = dr2;
            if (dr.order_failed or dr.order_cancelled or dr.order_audit_unavailable) break;
        }
        self.defer_order_finalization = false;
        try self.finalizeDeferredOrder(outcome.order_id, &dr);
        return dr;
    }

    /// el motor ejecuta los programas que produce SIN argumentos.
    /// Un programa de linea de ordenes al que eso no le vale sale con codigo != 0
    /// y su mensaje de uso por stderr: comportamiento correcto, no un fallo de la
    /// tarea. Cuando la ejecucion acaba ASI (exit 1 o 2, sin traza del
    /// interprete, salida = solo un mensaje de uso), se marca el outcome con
    /// `usage_only` para que las decisiones de exit (taskExecutionSucceeded y
    /// los criterios del auto-auditor) no lo cuenten como fallo de ejecucion, y
    /// se emite `exec_skipped` con la razon, el comando, el archivo y la salida
    /// (un SKIP en silencio es un fallo, igual que en).
    ///
    /// R2-1: SOLO se llama desde `governedExecute` (ejecucion por ARCHIVO, el
    /// motor construye el argv sin argumentos del usuario). Las rutas
    /// `governedExecuteRaw` que llevan `parsed.args` NO lo llaman: un comando
    /// lanzado CON argumentos que falla es un fallo real, aunque imprima su uso.
    fn marcarUsoSinArgumentos(self: *Superagent, task_id: []const u8, command: []const u8, file: []const u8, outcome: *ExecOutcome) void {
        if (!outcome.ran or outcome.exit_code == 0 or outcome.needs_approval or outcome.timed_out) return;
        const stdout = outcome.stdout orelse "";
        if (!usageOnlyExit(outcome.exit_code, stdout, outcome.stderr)) return;
        outcome.usage_only = true;
        var uso_out: std.Io.Writer.Allocating = .init(self.allocator);
        defer uso_out.deinit();
        var uso_js: std.json.Stringify = .{ .writer = &uso_out.writer, .options = .{} };
        uso_js.beginObject() catch {};
        uso_js.objectField("task_id") catch {};
        uso_js.write(task_id) catch {};
        uso_js.objectField("command") catch {};
        uso_js.write(command) catch {};
        uso_js.objectField("file") catch {};
        uso_js.write(file) catch {};
        uso_js.objectField("razon") catch {};
        uso_js.write("programa_requiere_argumentos") catch {};
        uso_js.objectField("exit_code") catch {};
        uso_js.write(@as(i64, outcome.exit_code)) catch {};
        uso_js.objectField("stdout") catch {};
        uso_js.write(stdout) catch {};
        uso_js.objectField("stderr") catch {};
        uso_js.write(outcome.stderr) catch {};
        uso_js.endObject() catch {};
        self.recordEvent("exec_skipped", uso_out.written());
    }

    /// Intenta ejecutar/compilar `path` (relativo al workspace) usando la política
    /// gobernada. Las salidas se añaden a `outputs`; los rechazos de política se
    /// convierten en `ApprovalRequest` en `pending`.
    /// Devuelve un `ExecOutcome` que el llamador debe propagar al `TaskRunResult`.
    fn governedExecute(
        self: *Superagent,
        path: []const u8,
        task_id: []const u8,
        outputs: *std.ArrayList(WorkerOutput),
        pending: *std.ArrayList(ApprovalRequest),
    ) !ExecOutcome {
        const dir = std.fs.path.dirname(path) orelse ".";
        const file = std.fs.path.basename(path);

        // D3-FIX: Usar effectiveRoot (lógica centralizada) para resolver la raíz efectiva.
        // Esto garantiza que governedExecute use la MISMA raíz que persistTask, evitando
        // PathOutsideSandbox cuando persistTask reanchora pero governedExecute no.
        var er_buf: [4096]u8 = undefined;
        const ws_abs: []const u8 = workspace.effectiveRoot(&er_buf);

        const cmd = inferCommand(file) orelse {
            // P-EXEC-2: no es un archivo con extensión conocida — intentar como
            // comando crudo (e.g. `python -c "print(2+2)"`, `git status`).
            var parsed = (parseRawCommand(self.allocator, path) catch null) orelse return ExecOutcome{
                .ran = false,
                .exit_code = 0,
                .needs_approval = false,
                .stderr = try self.allocator.dupe(u8, "no executable extension"),
            };
            defer parsed.deinit();
            return try self.governedExecuteRaw(parsed.exe, parsed.args, task_id, outputs, pending);
        };

        // Los argumentos se construyen en este frame: inferCommand solo devuelve
        // una estrategia y nunca slices que apunten a un array local ya destruido.
        var args_storage: [3][]const u8 = undefined;
        const args: []const []const u8 = switch (cmd.kind) {
            .script => blk: {
                args_storage[0] = file;
                break :blk args_storage[0..1];
            },
            .go_run => blk: {
                // E-GOV.4 (rama e5-gov, reescrito en la tanda 3): un paquete que no
                // es `main` es una biblioteca; `go run` la rechaza siempre («is not
                // a main package») y el gobierno reprobaba trabajo correcto. Se
                // compila con `go build`, que la comprueba y descarta el resultado.
                args_storage[0] = if (goFileIsMainPackage(self.allocator, path)) "run" else "build";
                args_storage[1] = file;
                break :blk args_storage[0..2];
            },
            .zig_build => blk: {
                args_storage[0] = "build-exe";
                args_storage[1] = file;
                break :blk args_storage[0..2];
            },
            .c_build, .cpp_build => blk: {
                args_storage[0] = file;
                args_storage[1] = "-o";
                args_storage[2] = "a.exe";
                break :blk args_storage[0..3];
            },
        };

        // La línea efectiva (exe + argv) viaja en `command`; `exe` queda como
        // campo aparte. El display es lo que la card debe mostrar y lo que
        // correlaciona running→delta→done.
        const display = renderCommandLine(self.allocator, cmd.exe, args) catch try self.allocator.dupe(u8, cmd.exe);
        defer self.allocator.free(display);

        // P3: emit shell_command event (status: running) for timeline command card.
        {
            var sc_out: std.Io.Writer.Allocating = .init(self.allocator);
            defer sc_out.deinit();
            var sc_js: std.json.Stringify = .{ .writer = &sc_out.writer, .options = .{} };
            sc_js.beginObject() catch {};
            sc_js.objectField("command") catch {};
            sc_js.write(display) catch {};
            sc_js.objectField("exe") catch {};
            sc_js.write(cmd.exe) catch {};
            sc_js.objectField("task_id") catch {};
            sc_js.write(task_id) catch {};
            sc_js.objectField("file") catch {};
            sc_js.write(file) catch {};
            sc_js.objectField("status") catch {};
            sc_js.write("running") catch {};
            sc_js.endObject() catch {};
            self.recordEvent("shell_command", sc_out.written());
        }

        // P2: verificar permisos antes de ejecutar. denylist siempre pide;
        // allowlist/session_allow auto; modo decide el resto.
        // Un plan aprobado no autoriza denylist ni código inline de intérpretes.
        const perm_decision = executor.checkPrefix(cmd.exe, self.permission_config);
        const human_only = self.order_origin.requiresHumanApproval();
        if ((command_policy.decide(cmd.exe, args, self.permission_config.deny_prefixes, .{ .allocator = self.allocator, .workspace_root = ws_abs, .cwd = dir, .read_only_only = human_only }) != .exempt or (perm_decision == .ask and (!self.plan_approved or human_only))) and !try self.inlineApproved(cmd.exe, args, dir)) {
            const request = try executionApproval(self.allocator, self.permission_config, cmd.exe, args, dir, task_id, self.order_origin);
            pending.append(self.allocator, request) catch |e| {
                request.deinit(self.allocator);
                return e;
            };
            return ExecOutcome{
                .ran = false,
                .exit_code = 0,
                .needs_approval = true,
                .stderr = try self.allocator.dupe(u8, "permission required"),
            };
        }

        // FASE-0 / EXEC-02: programas con interfaz gráfica se lanzan detached (sin
        // bloquear el despacho). Antes se usaba runGoverned con timeout 120 s, lo que
        // mantenía la orden en "Ejecutando…" durante 2 minutos hasta que el timeout
        // mataba el proceso. Ahora se lanza como app independiente y la orden termina
        // inmediatamente con order_done.
        const is_gui = isGuiProgram(self.allocator, path);

        if (is_gui) {
            // GOBERNANZA-EJECUCION: si ESTA orden ya lanzó esta misma ruta como app GUI
            // (p.ej. la tarea "programar" que la generó ya la auto-lanzó), la tarea
            // "ejecutar" dedicada al mismo archivo no debe volver a abrirla — sería un
            // segundo proceso/ventana idéntico. Se reporta éxito sin relanzar.
            if (containsPath(self.launched_gui_paths.items, path)) {
                const msg = try std.fmt.allocPrint(self.allocator, "App GUI ya estaba corriendo (lanzada por una tarea anterior de esta orden) — no se relanza.", .{});
                try outputs.append(self.allocator, .{
                    .worker_id = try self.allocator.dupe(u8, "executor"),
                    .stream = try self.allocator.dupe(u8, "stdout"),
                    .text = msg,
                });
                return ExecOutcome{
                    .ran = true,
                    .exit_code = 0,
                    .needs_approval = false,
                    .stderr = try self.allocator.dupe(u8, ""),
                };
            }
            const dr = executor.runDetached(self.allocator, executor.Policy{ .origin = self.order_origin, .workspace_root = ws_abs }, cmd.exe, args, dir) catch |e| {
                // P05: emitir process_launched failure event when detached fails.
                {
                    var pl_out: std.Io.Writer.Allocating = .init(self.allocator);
                    defer pl_out.deinit();
                    var pl_js: std.json.Stringify = .{ .writer = &pl_out.writer, .options = .{} };
                    pl_js.beginObject() catch {};
                    pl_js.objectField("command") catch {};
                    pl_js.write(cmd.exe) catch {};
                    pl_js.objectField("task_id") catch {};
                    pl_js.write(task_id) catch {};
                    pl_js.objectField("file") catch {};
                    pl_js.write(file) catch {};
                    pl_js.objectField("status") catch {};
                    pl_js.write("failed") catch {};
                    pl_js.objectField("error") catch {};
                    pl_js.write(@errorName(e)) catch {};
                    pl_js.endObject() catch {};
                    self.recordEvent("process_launched", pl_out.written());
                }
                const base = executor.stripExe(executor.basename(cmd.exe));
                const desc = try std.fmt.allocPrint(self.allocator, "Ejecutar {s} en {s} requiere aprobación: {s}", .{
                    cmd.exe, dir, @errorName(e),
                });
                try pending.append(self.allocator, .{
                    .task_id = try self.allocator.dupe(u8, task_id),
                    .description = desc,
                    .command_prefix = try self.allocator.dupe(u8, base),
                    .exe = try self.allocator.dupe(u8, cmd.exe),
                    .args_json = try serializeArgsJson(self.allocator, args),
                });
                return ExecOutcome{
                    .ran = false,
                    .exit_code = 0,
                    .needs_approval = true,
                    .stderr = try self.allocator.dupe(u8, @errorName(e)),
                };
            };
            // GOBERNANZA-EJECUCION: registrar esta ruta como ya-lanzada ANTES de
            // cualquier return posterior, para que una tarea "ejecutar" del mismo
            // archivo (ejecutada después en la misma orden) la detecte y no relance.
            self.launched_gui_paths.append(self.allocator, try self.allocator.dupe(u8, path)) catch {};
            // P05: emitir process_launched success event para mostrar tarjeta inline.
            {
                var pl_out: std.Io.Writer.Allocating = .init(self.allocator);
                defer pl_out.deinit();
                var pl_js: std.json.Stringify = .{ .writer = &pl_out.writer, .options = .{} };
                pl_js.beginObject() catch {};
                pl_js.objectField("command") catch {};
                pl_js.write(cmd.exe) catch {};
                pl_js.objectField("task_id") catch {};
                pl_js.write(task_id) catch {};
                pl_js.objectField("file") catch {};
                pl_js.write(file) catch {};
                pl_js.objectField("status") catch {};
                pl_js.write("running") catch {};
                pl_js.objectField("pid") catch {};
                pl_js.write(@as(i64, @intCast(dr.pid))) catch {};
                pl_js.objectField("mode") catch {};
                pl_js.write("detached") catch {};
                pl_js.endObject() catch {};
                self.recordEvent("process_launched", pl_out.written());
            }
            const msg = try std.fmt.allocPrint(self.allocator, "App GUI lanzada como proceso independiente (PID {d})", .{dr.pid});
            try outputs.append(self.allocator, .{
                .worker_id = try self.allocator.dupe(u8, "executor"),
                .stream = try self.allocator.dupe(u8, "stdout"),
                .text = msg,
            });
            return ExecOutcome{
                .ran = true,
                .exit_code = 0,
                .needs_approval = false,
                .stderr = try self.allocator.dupe(u8, ""),
            };
        }

        const timeout_ms: u32 = 10_000;

        // H-06: streaming sink — cada trozo leído del pipe ConPTY se emite como
        // worker_output independiente EN VIVO (no un lote al final).
        // P4: también emite un evento shell_command delta por chunk a runtime.db
        // para que el webview vea el output progresivamente (no todo al final).
        const SinkCtx = struct {
            sa: *Superagent,
            outputs: *std.ArrayList(WorkerOutput),
            task_id: []const u8,
            display: []const u8,
        };
        var sink_ctx = SinkCtx{ .sa = self, .outputs = outputs, .task_id = task_id, .display = display };
        const sink_fn = struct {
            fn sink(ctx: ?*anyopaque, chunk: []const u8, stream: executor.StreamKind) void {
                const sc: *SinkCtx = @ptrCast(@alignCast(ctx.?));
                const stream_name = if (stream == .stderr) "stderr" else "stdout";
                const text = sc.sa.allocator.dupe(u8, chunk) catch return;
                const worker_id = sc.sa.allocator.dupe(u8, "executor") catch {
                    sc.sa.allocator.free(text);
                    return;
                };
                const stream_dup = sc.sa.allocator.dupe(u8, stream_name) catch {
                    sc.sa.allocator.free(text);
                    sc.sa.allocator.free(worker_id);
                    return;
                };
                const task_id_dup = sc.sa.allocator.dupe(u8, sc.task_id) catch {
                    sc.sa.allocator.free(text);
                    sc.sa.allocator.free(worker_id);
                    sc.sa.allocator.free(stream_dup);
                    return;
                };
                sc.outputs.append(sc.sa.allocator, .{
                    .worker_id = worker_id,
                    .stream = stream_dup,
                    .task_id = task_id_dup,
                    .text = text,
                }) catch {
                    sc.sa.allocator.free(text);
                    sc.sa.allocator.free(worker_id);
                    sc.sa.allocator.free(stream_dup);
                    sc.sa.allocator.free(task_id_dup);
                    return;
                };
                // P4: emit live delta event to runtime.db for webview polling.
                // `command` viaja también en cada delta: sin él la UI no puede
                // correlacionar el chunk con la card de la operación y el
                // stdout en vivo acababa en "eventos sin clasificar".
                var delta_out: std.Io.Writer.Allocating = .init(sc.sa.allocator);
                defer delta_out.deinit();
                var delta_js: std.json.Stringify = .{ .writer = &delta_out.writer, .options = .{} };
                delta_js.beginObject() catch return;
                delta_js.objectField("task_id") catch return;
                delta_js.write(sc.task_id) catch return;
                delta_js.objectField("command") catch return;
                delta_js.write(sc.display) catch return;
                delta_js.objectField("status") catch return;
                delta_js.write("delta") catch return;
                delta_js.objectField("stream") catch return;
                delta_js.write(stream_name) catch return;
                delta_js.objectField("chunk") catch return;
                delta_js.write(chunk) catch return;
                delta_js.endObject() catch return;
                sc.sa.recordEvent("shell_command", delta_out.written());
            }
        }.sink;

        const er = executor.runGoverned(self.allocator, executor.Policy{ .origin = self.order_origin, .timeout_ms = timeout_ms, .workspace_root = ws_abs }, cmd.exe, args, dir, self.executor_spawn_fn, sink_fn, &sink_ctx);
        if (er) |r| {
            defer r.deinit(self.allocator);
            // EXEC-SHOW: si el programa no terminó dentro del timeout (reloj/servidor),
            // runGoverned ahora devuelve la salida capturada con timed_out=true. Se MUESTRA
            // igual (header lo indica) y NO se trata como fallo de exit.
            const header = if (r.timed_out)
                "exit=timeout (el programa seguia corriendo; salida capturada en pantalla)\n"
            else
                "";
            const trunc_note = try execTruncationNote(self.allocator, r);
            defer self.allocator.free(trunc_note);
            const text = if (r.timed_out)
                try std.fmt.allocPrint(self.allocator, "{s}{s}{s}{s}", .{ header, r.stdout, if (r.stderr.len > 0) r.stderr else "", trunc_note })
            else
                try std.fmt.allocPrint(self.allocator, "exit={d}\n{s}{s}{s}", .{ r.exit_code, r.stdout, if (r.stderr.len > 0) r.stderr else "", trunc_note });
            try outputs.append(self.allocator, .{
                .worker_id = try self.allocator.dupe(u8, "executor"),
                .stream = try self.allocator.dupe(u8, "stdout"),
                .text = text,
            });
            // P3: emit shell_command event (status: done) with exit_code + output for command card.
            {
                var sc_out: std.Io.Writer.Allocating = .init(self.allocator);
                defer sc_out.deinit();
                var sc_js: std.json.Stringify = .{ .writer = &sc_out.writer, .options = .{} };
                sc_js.beginObject() catch {};
                sc_js.objectField("command") catch {};
                sc_js.write(display) catch {};
                sc_js.objectField("exe") catch {};
                sc_js.write(cmd.exe) catch {};
                sc_js.objectField("task_id") catch {};
                sc_js.write(task_id) catch {};
                sc_js.objectField("file") catch {};
                sc_js.write(file) catch {};
                sc_js.objectField("status") catch {};
                sc_js.write("done") catch {};
                sc_js.objectField("exit_code") catch {};
                sc_js.write(r.exit_code) catch {};
                sc_js.objectField("stdout") catch {};
                sc_js.write(r.stdout) catch {};
                sc_js.objectField("stderr") catch {};
                sc_js.write(if (r.stderr.len > 0) r.stderr else "") catch {};
                sc_js.objectField("stdout_truncated") catch {};
                sc_js.write(r.stdoutTruncated()) catch {};
                sc_js.objectField("stdout_total_bytes") catch {};
                sc_js.write(r.stdout_total_bytes) catch {};
                sc_js.objectField("stderr_truncated") catch {};
                sc_js.write(r.stderrTruncated()) catch {};
                sc_js.objectField("stderr_total_bytes") catch {};
                sc_js.write(r.stderr_total_bytes) catch {};
                sc_js.endObject() catch {};
                self.recordEvent("shell_command", sc_out.written());
            }
            var outcome = ExecOutcome{
                .ran = true,
                .exit_code = r.exit_code,
                .needs_approval = false,
                .stderr = try self.allocator.dupe(u8, if (r.stderr.len > 0) r.stderr else ""),
                .stdout = try self.allocator.dupe(u8, r.stdout),
                .timed_out = r.timed_out,
            };
            // R2-1/R2-3: aqui SI es una ejecucion por ARCHIVO sin argumentos del
            // usuario; un mensaje de uso no es veredicto y se registra con su
            // command/file para que la cabina sepa QUE no se ejecuto.
            self.marcarUsoSinArgumentos(task_id, display, file, &outcome);
            return outcome;
        } else |e| {
            const base = executor.stripExe(executor.basename(cmd.exe));
            const desc = try std.fmt.allocPrint(self.allocator, "Ejecutar {s} en {s} requiere aprobación: {s}", .{
                cmd.exe, dir, @errorName(e),
            });
            try pending.append(self.allocator, .{
                .task_id = try self.allocator.dupe(u8, task_id),
                .description = desc,
                .command_prefix = try self.allocator.dupe(u8, base),
                .exe = try self.allocator.dupe(u8, cmd.exe),
                .args_json = try serializeArgsJson(self.allocator, args),
            });
            return ExecOutcome{
                .ran = false,
                .exit_code = 0,
                .needs_approval = true,
                .stderr = try self.allocator.dupe(u8, @errorName(e)),
            };
        }
    }

    /// Decisión humana en línea (solo pruebas): null/false publica la tarjeta.
    fn inlineApproved(self: *const Superagent, exe: []const u8, args: []const []const u8, cwd: []const u8) !bool {
        if (self.order_origin.requiresHumanApproval()) return false;
        const approve = self.approve_command_fn orelse return false;
        return approve(self.approve_command_ctx, exe, args, cwd);
    }

    /// P-EXEC-2: ejecuta un comando crudo (exe + args) gobernado por la misma
    /// política P2 que governedExecute. Usa el workspace root como cwd.
    /// Reusa el mismo checkPrefix (denylist siempre pide; Normal pide; Bypass auto)
    /// y emite los mismos eventos/aprobaciones que governedExecute.
    fn governedExecuteRaw(
        self: *Superagent,
        exe: []const u8,
        args: []const []const u8,
        task_id: []const u8,
        outputs: *std.ArrayList(WorkerOutput),
        pending: *std.ArrayList(ApprovalRequest),
    ) !ExecOutcome {
        var er_buf: [4096]u8 = undefined;
        return self.governedExecuteRawAtCwd(exe, args, task_id, outputs, pending, workspace.effectiveRoot(&er_buf));
    }

    /// `console.assert` solo escribe stderr y conserva exit 0. Para una prueba
    /// Node, se carga un módulo interno antes del archivo del usuario para que
    /// una aserción fallida lance AssertionError y el proceso reporte fracaso.
    /// El guard se crea únicamente dentro del cwd ya materializado y se borra
    /// después de ejecutar; ningún texto del productor decide su contenido.
    fn governedExecuteTestRawAtCwd(
        self: *Superagent,
        exe: []const u8,
        args: []const []const u8,
        task_id: []const u8,
        outputs: *std.ArrayList(WorkerOutput),
        pending: *std.ArrayList(ApprovalRequest),
        cwd: []const u8,
    ) !ExecOutcome {
        const base = executor.stripExe(executor.basename(exe));
        if (!std.ascii.eqlIgnoreCase(base, "node")) {
            return self.governedExecuteRawAtCwd(exe, args, task_id, outputs, pending, cwd);
        }
        var root_buf: [4096]u8 = undefined;
        const root = workspace.effectiveRoot(&root_buf);
        // No materializar ningún archivo auxiliar si la misma política que usa
        // el executor va a pedir aprobación y por tanto no habrá proceso.
        const perm_decision = executor.checkPrefix(exe, self.permission_config);
        const human_only = self.order_origin.requiresHumanApproval();
        if (command_policy.decide(exe, args, self.permission_config.deny_prefixes, .{ .allocator = self.allocator, .workspace_root = root, .cwd = cwd, .read_only_only = human_only }) != .exempt or (perm_decision == .ask and (!self.plan_approved or human_only))) {
            return self.governedExecuteRawAtCwd(exe, args, task_id, outputs, pending, cwd);
        }

        var pinned_cwd = try pinGovernedCwd(self.allocator, root, cwd);
        defer pinned_cwd.deinit();

        // Las tareas de test pueden correr en paralelo sobre el mismo productor;
        // el nombre determinista por task evita que una borre el guard de otra.
        const guard_name = try std.fmt.allocPrint(self.allocator, ".__devagents_console_assert_guard_{x}.cjs", .{std.hash.Wyhash.hash(0, task_id)});
        defer self.allocator.free(guard_name);
        const guard_path = try std.fs.path.join(self.allocator, &.{ pinned_cwd.canonical, guard_name });
        defer self.allocator.free(guard_path);
        // Exclusive creation and deletion use the SAME retained handle.
        // READ sharing lets Node load it; WRITE/DELETE sharing stays denied.
        var guard = try pinned_cwd.openMutation(guard_name, .exclusive_temporary);
        defer guard.deinit();
        errdefer guard.remove() catch |err| std.log.err("Node guard cleanup: {s}", .{@errorName(err)});
        try guard.writeAll(
            \\const assert = require('node:assert/strict');
            \\const util = require('node:util');
            \\console.assert = function(condition, ...args) {
            \\  if (condition) return;
            \\  const message = args.length == 0 ? 'console.assert failed' : util.format(...args);
            \\  throw new assert.AssertionError({ actual: condition, expected: true, operator: '==', message });
            \\};
            \\
        );

        const guarded_args = try self.allocator.alloc([]const u8, args.len + 2);
        defer self.allocator.free(guarded_args);
        guarded_args[0] = "--require";
        guarded_args[1] = guard_path;
        @memcpy(guarded_args[2..], args);
        const outcome = try self.governedExecuteRawAtCwdPolicy(exe, guarded_args, args, task_id, outputs, pending, pinned_cwd.canonical);
        errdefer {
            self.allocator.free(outcome.stderr);
            if (outcome.stdout) |stdout| self.allocator.free(stdout);
        }
        try guard.remove();
        return outcome;
    }

    /// Igual que governedExecuteRaw, con cwd explícito para pruebas que viven en
    /// la carpeta de su productor. El sandbox siempre conserva como raíz el
    /// workspace completo; el cwd solo puede ser un descendiente validado.
    fn governedExecuteRawAtCwd(
        self: *Superagent,
        exe: []const u8,
        args: []const []const u8,
        task_id: []const u8,
        outputs: *std.ArrayList(WorkerOutput),
        pending: *std.ArrayList(ApprovalRequest),
        cwd: []const u8,
    ) !ExecOutcome {
        return self.governedExecuteRawAtCwdPolicy(exe, args, args, task_id, outputs, pending, cwd);
    }

    /// `policy_args` es lo que ven la política y la tarjeta de aprobación; `args`
    /// es lo que se lanza. Difieren solo cuando el motor antepone un preload suyo
    /// (el guard de Node): la decisión se toma sobre el argv que pidió el plan,
    /// nunca sobre la inyección propia ni sobre texto del productor.
    fn governedExecuteRawAtCwdPolicy(
        self: *Superagent,
        exe: []const u8,
        args: []const []const u8,
        policy_args: []const []const u8,
        task_id: []const u8,
        outputs: *std.ArrayList(WorkerOutput),
        pending: *std.ArrayList(ApprovalRequest),
        cwd: []const u8,
    ) !ExecOutcome {
        var root_buf: [4096]u8 = undefined;
        const root = workspace.effectiveRoot(&root_buf);
        var pinned_cwd = try pinGovernedCwd(self.allocator, root, cwd);
        defer pinned_cwd.deinit();

        // REPL pelado (powershell/bash/python… sin args): el proceso imprime
        // su banner, lee un stdin ya cerrado y sale 0 — falso éxito medido en
        // la orden #527 (audit PASS sobre un banner). Se rechaza ANTES del
        // evento running: el outcome llega como failure honesto, no como
        // ejecución vacía. La ruta de archivo legítima nunca llega aquí con
        // args vacío (inferCommand siempre construye argv).
        if (isInteractiveWithoutArgs(exe, policy_args.len)) {
            var ce_out: std.Io.Writer.Allocating = .init(self.allocator);
            defer ce_out.deinit();
            var ce_js: std.json.Stringify = .{ .writer = &ce_out.writer, .options = .{} };
            ce_js.beginObject() catch {};
            ce_js.objectField("task_id") catch {};
            ce_js.write(task_id) catch {};
            ce_js.objectField("command") catch {};
            ce_js.write(exe) catch {};
            ce_js.objectField("razon") catch {};
            ce_js.write("shell_sin_comando") catch {};
            ce_js.endObject() catch {};
            self.recordEvent("exec_skipped", ce_out.written());
            return ExecOutcome{
                .ran = false,
                .exit_code = 0,
                .needs_approval = false,
                .stderr = try self.allocator.dupe(u8, "shell interactivo sin comando: el proceso solo mostraria su banner"),
            };
        }

        // La línea efectiva completa (exe + argv) es lo que el usuario ve y lo
        // que correlaciona running→delta→done en la UI. Antes solo viajaba el
        // exe: `powershell -Command "<script>"` se mostraba como "powershell"
        // a secas y los delta — sin `command` — caían en "sin clasificar".
        const display = renderCommandLine(self.allocator, exe, args) catch try self.allocator.dupe(u8, exe);
        defer self.allocator.free(display);

        // P3: emit shell_command event (status: running).
        {
            var sc_out: std.Io.Writer.Allocating = .init(self.allocator);
            defer sc_out.deinit();
            var sc_js: std.json.Stringify = .{ .writer = &sc_out.writer, .options = .{} };
            sc_js.beginObject() catch {};
            sc_js.objectField("command") catch {};
            sc_js.write(display) catch {};
            sc_js.objectField("exe") catch {};
            sc_js.write(exe) catch {};
            sc_js.objectField("task_id") catch {};
            sc_js.write(task_id) catch {};
            sc_js.objectField("status") catch {};
            sc_js.write("running") catch {};
            sc_js.endObject() catch {};
            self.recordEvent("shell_command", sc_out.written());
        }

        // P2: verificar permisos — denylist siempre pide; allowlist/session_allow auto;
        // modo decide el resto. Misma ruta que governedExecute.
        // Un plan aprobado no autoriza denylist ni código inline de intérpretes.
        const perm_decision = executor.checkPrefix(exe, self.permission_config);
        const human_only = self.order_origin.requiresHumanApproval();
        if ((command_policy.decide(exe, policy_args, self.permission_config.deny_prefixes, .{ .allocator = self.allocator, .workspace_root = root, .cwd = cwd, .read_only_only = human_only }) != .exempt or (perm_decision == .ask and (!self.plan_approved or human_only))) and !try self.inlineApproved(exe, policy_args, cwd)) {
            const request = try executionApproval(self.allocator, self.permission_config, exe, policy_args, cwd, task_id, self.order_origin);
            pending.append(self.allocator, request) catch |e| {
                request.deinit(self.allocator);
                return e;
            };
            return ExecOutcome{
                .ran = false,
                .exit_code = 0,
                .needs_approval = true,
                .stderr = try self.allocator.dupe(u8, "permission required"),
            };
        }

        const timeout_ms: u32 = 10_000;

        // H-06: streaming sink — mismo que governedExecute.
        // P4: también emite delta events a runtime.db para streaming en vivo.
        const SinkCtx = struct {
            sa: *Superagent,
            outputs: *std.ArrayList(WorkerOutput),
            task_id: []const u8,
            display: []const u8,
        };
        var sink_ctx = SinkCtx{ .sa = self, .outputs = outputs, .task_id = task_id, .display = display };
        const sink_fn = struct {
            fn sink(ctx: ?*anyopaque, chunk: []const u8, stream: executor.StreamKind) void {
                const sc: *SinkCtx = @ptrCast(@alignCast(ctx.?));
                const stream_name = if (stream == .stderr) "stderr" else "stdout";
                const text = sc.sa.allocator.dupe(u8, chunk) catch return;
                const worker_id = sc.sa.allocator.dupe(u8, "executor") catch {
                    sc.sa.allocator.free(text);
                    return;
                };
                const stream_dup = sc.sa.allocator.dupe(u8, stream_name) catch {
                    sc.sa.allocator.free(text);
                    sc.sa.allocator.free(worker_id);
                    return;
                };
                const task_id_dup = sc.sa.allocator.dupe(u8, sc.task_id) catch {
                    sc.sa.allocator.free(text);
                    sc.sa.allocator.free(worker_id);
                    sc.sa.allocator.free(stream_dup);
                    return;
                };
                sc.outputs.append(sc.sa.allocator, .{
                    .worker_id = worker_id,
                    .stream = stream_dup,
                    .task_id = task_id_dup,
                    .text = text,
                }) catch {
                    sc.sa.allocator.free(text);
                    sc.sa.allocator.free(worker_id);
                    sc.sa.allocator.free(stream_dup);
                    sc.sa.allocator.free(task_id_dup);
                    return;
                };
                // P4: emit live delta event to runtime.db for webview polling.
                var delta_out: std.Io.Writer.Allocating = .init(sc.sa.allocator);
                defer delta_out.deinit();
                var delta_js: std.json.Stringify = .{ .writer = &delta_out.writer, .options = .{} };
                delta_js.beginObject() catch return;
                delta_js.objectField("task_id") catch return;
                delta_js.write(sc.task_id) catch return;
                delta_js.objectField("command") catch return;
                delta_js.write(sc.display) catch return;
                delta_js.objectField("status") catch return;
                delta_js.write("delta") catch return;
                delta_js.objectField("stream") catch return;
                delta_js.write(stream_name) catch return;
                delta_js.objectField("chunk") catch return;
                delta_js.write(chunk) catch return;
                delta_js.endObject() catch return;
                sc.sa.recordEvent("shell_command", delta_out.written());
            }
        }.sink;

        const er = executor.runGoverned(self.allocator, executor.Policy{ .origin = self.order_origin, .timeout_ms = timeout_ms, .workspace_root = root }, exe, args, pinned_cwd.canonical, self.executor_spawn_fn, sink_fn, &sink_ctx);
        if (er) |r| {
            defer r.deinit(self.allocator);
            const header = if (r.timed_out)
                "exit=timeout (el programa seguia corriendo; salida capturada en pantalla)\n"
            else
                "";
            const trunc_note = try execTruncationNote(self.allocator, r);
            defer self.allocator.free(trunc_note);
            const text = if (r.timed_out)
                try std.fmt.allocPrint(self.allocator, "{s}{s}{s}{s}", .{ header, r.stdout, if (r.stderr.len > 0) r.stderr else "", trunc_note })
            else
                try std.fmt.allocPrint(self.allocator, "exit={d}\n{s}{s}{s}", .{ r.exit_code, r.stdout, if (r.stderr.len > 0) r.stderr else "", trunc_note });
            try outputs.append(self.allocator, .{
                .worker_id = try self.allocator.dupe(u8, "executor"),
                .stream = try self.allocator.dupe(u8, "stdout"),
                .text = text,
            });
            // P3: emit shell_command event (status: done).
            {
                var sc_out: std.Io.Writer.Allocating = .init(self.allocator);
                defer sc_out.deinit();
                var sc_js: std.json.Stringify = .{ .writer = &sc_out.writer, .options = .{} };
                sc_js.beginObject() catch {};
                sc_js.objectField("command") catch {};
                sc_js.write(display) catch {};
                sc_js.objectField("exe") catch {};
                sc_js.write(exe) catch {};
                sc_js.objectField("task_id") catch {};
                sc_js.write(task_id) catch {};
                sc_js.objectField("status") catch {};
                sc_js.write("done") catch {};
                sc_js.objectField("exit_code") catch {};
                sc_js.write(r.exit_code) catch {};
                sc_js.objectField("stdout") catch {};
                sc_js.write(r.stdout) catch {};
                sc_js.objectField("stderr") catch {};
                sc_js.write(if (r.stderr.len > 0) r.stderr else "") catch {};
                sc_js.objectField("stdout_truncated") catch {};
                sc_js.write(r.stdoutTruncated()) catch {};
                sc_js.objectField("stdout_total_bytes") catch {};
                sc_js.write(r.stdout_total_bytes) catch {};
                sc_js.objectField("stderr_truncated") catch {};
                sc_js.write(r.stderrTruncated()) catch {};
                sc_js.objectField("stderr_total_bytes") catch {};
                sc_js.write(r.stderr_total_bytes) catch {};
                sc_js.endObject() catch {};
                self.recordEvent("shell_command", sc_out.written());
            }
            return ExecOutcome{
                .ran = true,
                .exit_code = r.exit_code,
                .needs_approval = false,
                .stderr = try self.allocator.dupe(u8, if (r.stderr.len > 0) r.stderr else ""),
                .stdout = try self.allocator.dupe(u8, r.stdout),
                .timed_out = r.timed_out,
            };
        } else |e| {
            const base = executor.stripExe(executor.basename(exe));
            const desc = try std.fmt.allocPrint(self.allocator, "Ejecutar {s} requiere aprobación: {s}", .{
                exe, @errorName(e),
            });
            try pending.append(self.allocator, .{
                .task_id = try self.allocator.dupe(u8, task_id),
                .description = desc,
                .command_prefix = try self.allocator.dupe(u8, base),
                .exe = try self.allocator.dupe(u8, exe),
                .args_json = try serializeArgsJson(self.allocator, args),
            });
            return ExecOutcome{
                .ran = false,
                .exit_code = 0,
                .needs_approval = true,
                .stderr = try self.allocator.dupe(u8, @errorName(e)),
            };
        }
    }

    /// Detecta si el contenido de un artefacto persistido es trivialmente inválido
    /// para su lenguaje (vacío, demasiado corto sin tokens reales, o basura literal
    /// como "python" — el caso real de FIRE-02).
    /// CHECKPOINT-T2: existe el artefacto persistido en disco. Un checkpoint
    /// que declara la tarea 'completed' pero cuyo archivo desapareció ya no
    /// vale — la auditoría la manda a corrección/re-ejecución.
    fn savedFileExists(self: *Superagent, path: []const u8) bool {
        const path_z = self.allocator.dupeZ(u8, path) catch return false;
        defer self.allocator.free(path_z);
        const h = CreateFileA(path_z.ptr, GENERIC_READ, FILE_SHARE_READ, null, OPEN_EXISTING, 0, null);
        if (h == INVALID_HANDLE_VALUE) return false;
        _ = CloseHandle(h);
        return true;
    }

    fn isContentTriviallyInvalid(self: *Superagent, path: []const u8) bool {
        return self.isContentTriviallyInvalidForTask(path, null, false);
    }

    fn isContentTriviallyInvalidForTask(self: *Superagent, path: []const u8, task: ?planner.PlannedTask, es_auditoria: bool) bool {
        return self.isContentTriviallyInvalidWith(path, task, es_auditoria, null);
    }

    /// / E-GOV.1: la procedencia del motor distingue una omisión
    /// heredada de una nueva. Sin procedencia (`null`) el gate sigue estricto.
    fn isContentTriviallyInvalidWith(self: *Superagent, path: []const u8, task: ?planner.PlannedTask, es_auditoria: bool, inherited: ?[]const artifact_quality.LineHash) bool {
        const path_z = self.allocator.dupeZ(u8, path) catch return true;
        defer self.allocator.free(path_z);

        const h = CreateFileA(path_z.ptr, GENERIC_READ, FILE_SHARE_READ, null, OPEN_EXISTING, 0, null);
        if (h == INVALID_HANDLE_VALUE) return true;
        defer _ = CloseHandle(h);

        var buf: [64 * 1024]u8 = undefined;
        var read: u32 = 0;
        if (ReadFile(h, &buf, buf.len, &read, null) == 0) return true;
        return contentInvalidWith(path, buf[0..read], task, es_auditoria, inherited);
    }

    fn contentInvalidWith(path: []const u8, content: []const u8, task: ?planner.PlannedTask, es_auditoria: bool, inherited: ?[]const artifact_quality.LineHash) bool {
        if (artifact_quality.invalidReason(path, content, inherited) != null) return true;
        if (task) |pt| {
            // a standalone audit's report IS the prose deliverable,
            // so the real task description must reach the rule (an order that
            // asks to explain cannot be satisfied with a trivial "OK"). The
            // internal audit report of a CODE order is product evidence, not a
            // prose delivery, so it keeps the empty description — the same
            // distinction evaluateSemanticGate makes on the prose inventory.
            const description = if (pt.task_type == .auditar and !es_auditoria) "" else pt.description;
            if (prose_artifact.isProseDelivery(path, pt.task_type) and
                prose_artifact.invalidReason(path, content, description) != null) return true;
        }
        return false;
    }

    /// Procedencia de `path` dentro del resultado: huellas de la línea base que
    /// el motor propagó al artefacto (diff o checkpoint restaurado).
    fn inheritedFor(self: *Superagent, result: TaskRunResult, path: []const u8) ?[]const artifact_quality.LineHash {
        const root = result.worktree_root orelse return null;
        const want = std.fs.path.resolve(self.allocator, &.{path}) catch return null;
        defer self.allocator.free(want);
        for (result.artifacts) |artifact| {
            const real = std.fs.path.resolve(self.allocator, &.{ root, artifact.path }) catch continue;
            defer self.allocator.free(real);
            if (@import("platform.zig").pathEqual(real, want)) return artifact.inherited_placeholders;
        }
        return null;
    }

    fn isResultContentTriviallyInvalid(self: *Superagent, result: TaskRunResult, path: []const u8, task: ?planner.PlannedTask, es_auditoria: bool) bool {
        if (result.restored) {
            if (result.worktree_root) |root| return self.restoredContentInvalid(result, root, path, task, es_auditoria);
        }
        // El archivo principal no puede ocultar una omisión añadida en otro
        // archivo del diff. Las eliminaciones no tienen contenido que auditar.
        if (result.worktree_root != null and !result.restored) {
            for (result.artifacts) |artifact| {
                if (artifact.content.len > 0 and artifact_quality.invalidReason(artifact.path, artifact.content, artifact.inherited_placeholders) != null) return true;
            }
        }
        return self.isContentTriviallyInvalidWith(path, task, es_auditoria, self.inheritedFor(result, path));
    }

    /// E-GOV.1 rondas 4 y 5 (rama e5-gov, reescritas en la tanda 3): un
    /// checkpoint restaurado se valida archivo por archivo, no solo el
    /// principal, y cada lectura pasa por la MISMA raíz confinada: sus handles
    /// quedan retenidos desde que se valida la ruta canónica hasta que se lee,
    /// sin seguir junctions ni enlaces, así que sustituir la raíz o un archivo
    /// por un enlace entre validar y leer no cuela contenido ajeno.
    fn restoredContentInvalid(self: *Superagent, result: TaskRunResult, root_path: []const u8, path: []const u8, task: ?planner.PlannedTask, es_auditoria: bool) bool {
        var root = confined_fs.Root.init(self.allocator, root_path) catch return true;
        defer root.deinit();
        var primary_checked = false;
        const primary = root.relativePath(path) catch return true;
        defer self.allocator.free(primary);
        for (result.artifacts) |artifact| {
            if (artifact.content.len == 0) continue; // Borrado persistido: nada que leer.
            const is_primary = std.ascii.eqlIgnoreCase(artifact.path, primary);
            if (is_primary) primary_checked = true;
            if (self.confinedContentInvalid(&root, artifact.path, if (is_primary) task else null, es_auditoria, artifact.inherited_placeholders)) return true;
        }
        if (!primary_checked and self.confinedContentInvalid(&root, primary, task, es_auditoria, self.inheritedFor(result, path))) return true;
        return false;
    }

    fn confinedContentInvalid(self: *Superagent, root: *const confined_fs.Root, relative: []const u8, task: ?planner.PlannedTask, es_auditoria: bool, inherited: ?[]const artifact_quality.LineHash) bool {
        const file = root.open(relative) catch return true;
        defer @import("platform.zig").closeHandle(file.handle);
        var threaded = std.Io.Threaded.init(self.allocator, .{});
        defer threaded.deinit();
        var buf: [64 * 1024]u8 = undefined;
        const read = file.readPositionalAll(threaded.io(), &buf, 0) catch return true;
        return contentInvalidWith(relative, buf[0..read], task, es_auditoria, inherited);
    }

    fn hasInvalidSavedProse(self: *Superagent, ctx: *const FanoutContext, task: planner.PlannedTask, es_auditoria: bool) bool {
        for (ctx.saved.items, ctx.saved_owner.items) |path, owner| {
            if (std.mem.eql(u8, owner, task.id) and prose_artifact.isProseDelivery(path, task.task_type) and
                self.isContentTriviallyInvalidForTask(path, task, es_auditoria)) return true;
        }
        return false;
    }

    /// Extensiones de texto libre: allí el contenido <10 bytes puede ser el
    /// entregable literal pedido por el usuario, no un artefacto roto.
    fn isFreeTextPath(path: []const u8) bool {
        const ext = std.fs.path.extension(path);
        if (ext.len == 0) return true;
        const text_exts = [_][]const u8{ ".txt", ".md", ".markdown", ".text", ".log", ".csv" };
        for (text_exts) |te| {
            if (std.ascii.eqlIgnoreCase(ext, te)) return true;
        }
        return false;
    }

    fn systemPromptForDept(self: *Superagent, dept: []const u8) ![]const u8 {
        // PIXEL-DEVTEAM-05: preferir especialista del registro unificado.
        if (self.registry) |reg| {
            if (reg.findByDepartment(dept)) |spec| {
                return try self.allocator.dupe(u8, spec.system_prompt);
            }
        }
        // Fallback a los 5 departamentos nativos.
        const content = if (std.mem.eql(u8, dept, "programacion"))
            agent_def.PROGRAMACION_DEF
        else if (std.mem.eql(u8, dept, "testing"))
            agent_def.TESTING_DEF
        else if (std.mem.eql(u8, dept, "auditoria"))
            agent_def.AUDITORIA_DEF
        else if (std.mem.eql(u8, dept, "correccion"))
            agent_def.CORRECCION_DEF
        else if (std.mem.eql(u8, dept, "documentacion"))
            agent_def.DOCUMENTACION_DEF
        else if (std.mem.eql(u8, dept, "diseno"))
            agent_def.DISENO_DEF
        else
            return error.UnknownDepartment;

        const def = try agent_def.parseAgentDef(self.allocator, content);
        defer def.deinit(self.allocator);
        return try self.allocator.dupe(u8, def.system_prompt);
    }

    /// System prompt de una tarea concreta: el rol del departamento más la
    /// instrucción de idioma cuando la tarea es de prosa y el idioma de la
    /// orden es concluyente.
    fn systemPromptForTask(self: *Superagent, dept: []const u8, task_type: model_router.TaskType, description: []const u8) ![]const u8 {
        const role = try self.systemPromptForDept(dept);
        defer self.allocator.free(role);
        // T7 (e): las reglas del proyecto acompañan al rol de cada
        // tarea de Orquestado, Colmena y delegate_tasks (mismo despacho).
        const rules = try (self.rules_context orelse project_rules.Context{}).blockForApi(self.allocator, null);
        defer self.allocator.free(rules);
        const base = try std.mem.concat(self.allocator, u8, &.{ role, rules });
        defer self.allocator.free(base);
        return buildWorkerSystemPrompt(self.allocator, base, task_type, description, task_type == .auditar and ordenEsAuditoria(self, self.event_order_id));
    }

    fn recordSidekickTask(self: *Superagent, task: planner.PlannedTask, assignment: ?ModelAssignment, actual_model: []const u8) void {
        var provider: []const u8 = "";
        if (assignment) |a| {
            if (std.mem.eql(u8, a.model_name, actual_model)) provider = a.provider_name;
            for (a.fallbacks) |fb| if (std.mem.eql(u8, fb.model_name, actual_model)) {
                provider = fb.provider_name;
                break;
            };
        }
        const payload = std.json.Stringify.valueAlloc(self.allocator, .{ .task_id = task.id, .kind = @tagName(task.task_type), .provider = provider, .model = actual_model }, .{}) catch {
            self.notarEventoPerdido();
            return;
        };
        defer self.allocator.free(payload);
        self.recordEvent("sidekick_task_v1", payload);
    }

    /// Construye un `Sandbox` cuya raíz es el directorio propio de la tarea (FR-006).
    pub fn sandboxForTask(self: *Superagent, task_id: []const u8) !sandbox.Sandbox {
        const root = try std.fmt.allocPrint(self.allocator, "sandbox/{s}", .{task_id});
        defer self.allocator.free(root);
        return sandbox.Sandbox.init(self.allocator, root);
    }

    // ── Validación de contrato por tarea ────────────────────────────────

    /// Por qué se rechazó una pieza. `null` en `motivo` significa que pasó.
    ///
    /// Existe porque el evento `task_failed` venía diciendo
    /// `cause: validation_failed, error_msg: validation_failed`: la etiqueta
    /// repetida como si fuera su propia explicación. Con eso no se puede saber
    /// si el modelo entregó basura, si entregó bien y el contrato no lo
    /// reconoció, ni qué campo faltaba — y el lazo de corrección reintenta a
    /// ciegas porque tampoco recibe nada que corregir.
    pub const RechazoPieza = struct {
        /// Texto para el humano Y para el worker de corrección. Lo libera quien lo recibe.
        motivo: ?[]u8 = null,

        pub fn deinit(self: RechazoPieza, allocator: std.mem.Allocator) void {
            if (self.motivo) |m| allocator.free(m);
        }
    };

    /// ¿Este campo del contrato pide el NOMBRE del archivo entregado? Los
    /// planificadores lo nombran de varias formas y no siempre lo marcan
    /// opcional; la lista es corta a propósito: solo campos cuyo contenido
    /// esperado es un nombre, nunca el contenido del archivo.
    fn esCampoNombreDeArchivo(name: []const u8) bool {
        const nombres = [_][]const u8{ "filename", "file_name", "filepath", "file_path", "path", "archivo", "nombre_archivo" };
        for (nombres) |n| {
            if (std.ascii.eqlIgnoreCase(name, n)) return true;
        }
        return false;
    }

    /// Resumen corto de lo que SÍ trajo la respuesta, para que el motivo del
    /// rechazo se pueda contrastar de un vistazo: "trajo index.html (7573 B)".
    fn resumenArtefactos(allocator: std.mem.Allocator, artifacts: []const worker_backend.Artifact) []u8 {
        if (artifacts.len == 0) return allocator.dupe(u8, "no trajo ningun campo") catch "";
        var out: std.Io.Writer.Allocating = .init(allocator);
        defer out.deinit();
        for (artifacts, 0..) |art, i| {
            if (i > 0) out.writer.writeAll(", ") catch break;
            out.writer.print("{s} ({d} B)", .{ art.path, art.content.len }) catch break;
        }
        return allocator.dupe(u8, out.written()) catch "";
    }

    fn validatePieceForTask(self: *Superagent, pt: planner.PlannedTask, artifacts: []const worker_backend.Artifact) !bool {
        var rechazo = try self.validatePieceForTaskDetallado(pt, artifacts);
        defer rechazo.deinit(self.allocator);
        return rechazo.motivo == null;
    }

    fn validatePieceForTaskDetallado(self: *Superagent, pt: planner.PlannedTask, artifacts: []const worker_backend.Artifact) !RechazoPieza {
        // una auditoria INDEPENDIENTE (la orden entera pide auditar)
        // entrega prosa como .documentar/.investigar/.resumir: su informe se mide
        // contra la descripcion real de la tarea. El informe INTERNO de auditoria
        // de una orden de codigo no es prosa entregable y sigue fuera. El
        // discriminador se calcula con la misma fuente que el gate semantico y
        // se propaga a la seleccion de cuerpo (workspace.planOutFiles).
        const es_auditoria = ordenEsAuditoria(self, self.event_order_id);
        const aplica_prosa = switch (pt.task_type) {
            .documentar, .investigar, .resumir => true,
            .auditar => es_auditoria,
            else => false,
        };
        if (aplica_prosa) {
            var names = std.ArrayList(u8).empty;
            defer names.deinit(self.allocator);
            const files = workspace.planOutFiles(self.allocator, pt, artifacts, &names, es_auditoria) catch |err| {
                if (err != error.InvalidArtifact) return err;
                return .{ .motivo = try self.allocator.dupe(u8, "entregable de prosa invalido: solo metadatos o contenido insuficiente") };
            };
            if (files) |list| {
                defer self.allocator.free(list);
                for (list) |file| {
                    if (!prose_artifact.isProseDelivery(file.name, pt.task_type)) continue;
                    if (prose_artifact.invalidReason(file.name, file.body, pt.description)) |why| {
                        return .{ .motivo = try std.fmt.allocPrint(self.allocator, "prosa '{s}': {s}", .{ file.name, why }) };
                    }
                    // la validación de la pieza también rechaza prosa
                    // en un idioma concluyente distinto al de la orden.
                    if (prose_artifact.languageMismatchReason(file.body, pt.description)) |why| {
                        return .{ .motivo = try std.fmt.allocPrint(self.allocator, "prosa '{s}': {s}", .{ file.name, why }) };
                    }
                }
            }
        }
        var contract = try buildContract(self.allocator, pt);
        defer contract.deinit();

        const piece = try self.allocator.alloc(contracts.ProducedField, pt.contract_fields.len);
        defer self.allocator.free(piece);
        for (pt.contract_fields, 0..) |f, i| {
            var found = false;
            for (artifacts) |art| {
                if (std.mem.eql(u8, art.path, f.name)) {
                    found = true;
                    break;
                }
            }
            // FIRE-2026-07-10: los modelos suelen devolver el NOMBRE DE ARCHIVO en
            // "field" (p.ej. "digital_clock.py") en vez del nombre del campo del
            // contrato ("source"/"verdict") — comportamiento razonable que la
            // igualdad literal convertía en "Integración por contrato: rechazada"
            // aunque el entregable existiera y estuviera bien (orden 331: el reloj
            // ESCRITO en disco con la tarea marcada fallida). El campo STRING
            // PRIMARIO del contrato se considera satisfecho por cualquier artefacto
            // con contenido sustantivo (la basura ya la corta looksLikeBarePath /
            // ALTA-1 en el worker y las puertas de ejecución del motor).
            if (!found and f.required) {
                const primary_string = f.field_type == .string and i == 0;
                if (primary_string) {
                    for (artifacts) |art| {
                        // el worker ya pudo renombrar el cuerpo
                        // («source») al único archivo esperado (recovery.py);
                        // ese archivo, el que NOMBRA la tarea, ES el campo
                        // primario aunque sea corto (D3-RECOVERY). Un auxiliar
                        // no nombrado (helper.py) no lo cumple (el segundo auditor, r4).
                        const renamed_body = workspace.hasKnownCodeExtension(art.path) and
                            std.mem.trim(u8, art.content, " \t\r\n").len > 0 and
                            std.mem.indexOf(u8, pt.description, std.fs.path.basename(art.path)) != null;
                        if (art.content.len >= 20 or renamed_body) {
                            found = true;
                            break;
                        }
                    }
                }
                // CONTRATO-FILENAME (orden #213): el contrato pedía `filename`
                // como obligatorio y el modelo había entregado el archivo con su
                // NOMBRE en el campo — `index.html` (2900 B), perfecto y usable.
                // La igualdad literal lo daba por ausente, la tarea se marcaba
                // fallida y la orden entera moría con un entregable correcto en
                // la mano. Si algún artefacto ya se llama como un archivo, el
                // nombre de archivo está entregado: eso ES el campo.
                if (!found and esCampoNombreDeArchivo(f.name)) {
                    for (artifacts) |art| {
                        if (workspace.hasKnownCodeExtension(art.path)) {
                            found = true;
                            break;
                        }
                    }
                }
                // CONTRATO-FILENAME-FIJADO (órdenes #560/#561): el contrato ya
                // fija el nombre en `f.value` (d2EnsureFilenameField) y el
                // modelo entrega el contenido del archivo sin re-declarar el
                // nombre. Exigir el campo de nuevo mata la tarea con el
                // entregable correcto en disco — el nombre no está ausente,
                // está decidido por el contrato.
                if (!found and esCampoNombreDeArchivo(f.name)) {
                    if (f.value) |v| {
                        if (v.len > 0) found = true;
                    }
                }
                if (!found) {
                    const trajo = resumenArtefactos(self.allocator, artifacts);
                    defer self.allocator.free(trajo);
                    return .{ .motivo = try std.fmt.allocPrint(
                        self.allocator,
                        "falta el campo obligatorio «{s}» del contrato; la respuesta trajo: {s}",
                        .{ f.name, trajo },
                    ) };
                }
            }
            piece[i] = .{ .name = f.name, .field_type = f.field_type };
        }
        contracts.Assembler.assemble(&contract, piece) catch |e| {
            const trajo = resumenArtefactos(self.allocator, artifacts);
            defer self.allocator.free(trajo);
            return .{ .motivo = try std.fmt.allocPrint(
                self.allocator,
                "el ensamblador rechazo la pieza ({s}); campos del contrato: {d}; la respuesta trajo: {s}",
                .{ @errorName(e), pt.contract_fields.len, trajo },
            ) };
        };
        return .{};
    }

    // ── Asignación de modelos + persistencia ────────────────────────────

    fn buildDispatchManifest(self: *Superagent, outcome: *const OrderOutcome) !?[]const u8 {
        // El resumen del planner no reemplaza los requisitos originales. Consultar
        // la orden persistida cubre también CLI/MCP y la rehidratación de la GUI.
        const stmt = try self.runtime.prepare("SELECT user_prompt FROM orders WHERE id=?");
        defer self.runtime.finalize(stmt);
        try db.bindInt(stmt, 1, outcome.order_id);
        const stored: ?[]const u8 = if (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW)
            (if (db.c.sqlite3_column_text(stmt, 0)) |text| std.mem.span(text) else null)
        else
            null;
        const original = self.order_text orelse stored orelse outcome.plan.understanding;
        const goal = try std.fmt.allocPrint(self.allocator, "{s}\n\nALCANCE DEL PLAN APROBADO (ejecuta solo tu tarea asignada):\n{s}", .{ original, outcome.plan.understanding });
        defer self.allocator.free(goal);
        return buildPlanManifest(self.allocator, goal, outcome.plan.tasks);
    }

    fn correctionChoice(self: *const Superagent, assignments: []const ModelAssignment, task_id: []const u8, used_model: []const u8, tried: []const CorrectionAttempt) ?CorrectionChoice {
        // Pin manual: manda y NO rota. La corrección del modelo fijado no busca
        // alternativa ni siquiera si `used_model` coincide con el pin.
        if (self.forced_provider) |provider| {
            if (self.forced_model) |model| return .{ .provider_name = provider, .model_name = model, .is_free = true };
        }
        const assigned = findAssignment(assignments, task_id);
        // el "siguiente candidato apto" es el respaldo del router de
        // ESTA tarea (la misma cadena que armó `assignModel`), nunca el modelo que
        // acaba de fallar. Sin esto, una orden de una sola tarea reintentaba con el
        // MISMO modelo que devolvió basura — no era un reintento, era repetir.
        //
        // r2 (P1): el despacho original ya probó el primario y TODA la
        // cadena de respaldos hasta `used_model`. Se excluye el primario y todo el
        // tramo probado (hasta `used_model` inclusive, en orden de la cadena) para
        // no repetir un candidato ya intentado ni duplicar gasto. Y se excluye
        // además lo ya despachado como corrección (`tried`), porque una corrección
        // fallida NO actualiza `used_model`: sin esta lista, el ciclo siguiente de
        // MAX_AUDIT_CYCLES elegía otra vez el mismo respaldo.
        if (assigned) |a| {
            var tried_until: usize = 0; // 0 = solo se excluye el primario
            for (a.fallbacks, 0..) |fb, i| {
                if (std.mem.eql(u8, fb.model_name, used_model)) {
                    tried_until = i + 1;
                    break;
                }
            }
            for (a.fallbacks, 0..) |fb, i| {
                if (i < tried_until) continue;
                if (std.mem.eql(u8, fb.model_name, a.model_name)) continue;
                if (attemptAlreadyTried(tried, task_id, fb.model_name)) continue;
                return .{ .provider_name = fb.provider_name, .model_name = fb.model_name, .is_free = fb.is_free };
            }
        }
        for (assignments) |a| {
            if (!a.assigned) continue;
            if (std.mem.eql(u8, a.model_name, used_model)) continue;
            if (attemptAlreadyTried(tried, task_id, a.model_name)) continue;
            if (assigned) |orig| {
                if (chainModelAlreadyTried(orig, a.model_name, used_model)) continue;
            }
            return .{ .provider_name = a.provider_name, .model_name = a.model_name, .is_free = a.is_free };
        }
        // r3 (P1): ningún candidato CONOCIDO queda sin probar. No se
        // repite el modelo que falló ni se inventa un proveedor de reserva: el
        // llamador deja la tarea fallida con un motivo honesto (ver
        // `markCorrectionChainExhausted`). La r2 devolvía aquí `used_model` con
        // el proveedor literal "OpenCode", que por HTTP nunca responde a los
        // modelos gratis: el «reintento» era otro fallo seguro.
        return null;
    }

    /// r3 (P1): candidato EFECTIVO de una reparación ya elegido y
    /// medido; `null` cuando la cadena no deja ningún candidato sin probar y la
    /// reparación no debe re-despachar un modelo ya intentado.
    const RepairChoice = struct {
        provider_name: []const u8,
        model_name: []const u8,
        mode: TaskToolMode,
    };

    /// #874: candidato EFECTIVO de una reparación (.corregir) con su modo de
    /// tools. Consulta la MISMA puerta de capacidad medida que las productoras
    /// (`agenticGateFor`): si el candidato elegido por `correctionChoice` no
    /// admite tools, prueba el siguiente candidato asignado que sí las admita;
    /// si ninguno las admite, degrada a `.none` (reparación sin herramientas,
    /// como las productoras) en vez de gastar la reparación en un HTTP 422.
    /// Un modelo fijado a mano (pin) NUNCA se rota: el pin es obligatorio y
    /// mantiene governed_exec aunque no haya medición.
    /// r3 (P1): si `correctionChoice` no encuentra candidato, aquí
    /// tampoco se fabrica uno: devuelve `null` y el llamador deja la tarea
    /// fallida con motivo honesto.
    fn repairToolChoice(self: *const Superagent, catalog: ?db.Connection, assignments: []const ModelAssignment, task_id: []const u8, used_model: []const u8, tried: []const CorrectionAttempt) ?RepairChoice {
        const base = self.correctionChoice(assignments, task_id, used_model, tried) orelse return null;
        // Pin manual: el propietario fijó el par. Se respeta incluso sin catálogo.
        if (self.forced_provider != null and self.forced_model != null)
            return .{ .provider_name = base.provider_name, .model_name = base.model_name, .mode = .governed_exec };
        // Sin catálogo (o `:memory:`) no hay medición viva: degrada a `.none`,
        // igual que decideTaskToolMode, para no abrir tools sin medir (el segundo auditor P1).
        const conn = catalog orelse return .{ .provider_name = base.provider_name, .model_name = base.model_name, .mode = .none };
        // El candidato base no puede ser el modelo que acaba de fallar aunque
        // esté medido como apto: correctionChoice lo devuelve si no encuentra
        // otro (el segundo auditor P2, segunda vuelta).
        if (!std.mem.eql(u8, base.model_name, used_model) and
            model_router.agenticGateFor(conn, base.provider_name, base.model_name, self.now) == .ok)
            return .{ .provider_name = base.provider_name, .model_name = base.model_name, .mode = .governed_exec };
        // Siguiente candidato apto, excluyendo el modelo que REALMENTE falló
        // (`used_model`/res.model_used), no el de la asignación (el segundo auditor P1): con
        // fallback, el asignado puede diferir del efectivo. También se excluye
        // lo ya despachado como corrección (r2 P1) y el tramo de la
        // cadena del despacho original (r3 P1): repetir un candidato
        // probado no es una reparación nueva.
        const assigned = findAssignment(assignments, task_id);
        for (assignments) |a| {
            if (!a.assigned) continue;
            if (std.mem.eql(u8, a.model_name, used_model)) continue;
            if (attemptAlreadyTried(tried, task_id, a.model_name)) continue;
            if (assigned) |orig| {
                if (chainModelAlreadyTried(orig, a.model_name, used_model)) continue;
            }
            if (model_router.agenticGateFor(conn, a.provider_name, a.model_name, self.now) == .ok)
                return .{ .provider_name = a.provider_name, .model_name = a.model_name, .mode = .governed_exec };
        }
        // Ninguno admite tools: se degrada sin herramientas (nunca un 422).
        return .{ .provider_name = base.provider_name, .model_name = base.model_name, .mode = .none };
    }

    /// Rebuilds only the owned assignment snapshot. The plan, contracts and
    /// persisted task rows are intentionally untouched; this is dispatch-time
    /// routing, not plan mutation.
    pub fn refreshAssignmentsForDispatch(self: *Superagent, outcome: *OrderOutcome) !void {
        self.composer_order_id = outcome.order_id;
        if (try order_attachments.hasImages(self.runtime, outcome.order_id)) {
            for (outcome.plan.tasks) |*task| task.needs_vision = true;
        }
        if (self.router == null) return;
        var fresh = std.ArrayList(ModelAssignment).empty;
        errdefer {
            for (fresh.items) |assignment| assignment.deinit(self.allocator);
            fresh.deinit(self.allocator);
        }
        // FR-001 / AUDIT-INDEP: el re-ruteo de dispatch respeta la misma regla
        // que la asignación inicial — en orden de olas, con los productores ya
        // asignados como `prior`, para que el auditor excluya al constructor.
        // Sin esto, el refresh podía reseleccionar al productor como auditor.
        if (resolveWaves(outcome.plan.tasks, self.allocator)) |waves| {
            defer {
                for (waves) |wave| self.allocator.free(wave);
                self.allocator.free(waves);
            }
            for (waves) |wave| {
                for (wave) |pt| {
                    const assignment = try self.assignModel(pt, outcome.plan.tasks, fresh.items);
                    fresh.append(self.allocator, assignment) catch |e| {
                        assignment.deinit(self.allocator);
                        return e;
                    };
                }
            }
        } else |_| {
            for (outcome.plan.tasks) |pt| {
                const assignment = try self.assignModel(pt, outcome.plan.tasks, fresh.items);
                fresh.append(self.allocator, assignment) catch |e| {
                    assignment.deinit(self.allocator);
                    return e;
                };
            }
        }
        try composer_roles.persistReview(self.allocator, self.runtime, outcome.order_id, outcome.plan.tasks, fresh.items);
        const replacement = try fresh.toOwnedSlice(self.allocator);
        const previous = outcome.assignments;
        outcome.assignments = replacement;
        for (previous) |assignment| assignment.deinit(self.allocator);
        self.allocator.free(previous);
    }

    /// E5.18: pub para el runner de best-of-N — cada candidata persiste sus
    /// propias filas de tareas bajo su plan_id.
    pub fn assignAndPersist(self: *Superagent, plan_id: i64, tasks: []const planner.PlannedTask) ![]ModelAssignment {
        const order_query = try self.runtime.prepare("SELECT order_id FROM plans WHERE id=?");
        defer self.runtime.finalize(order_query);
        try db.bindInt(order_query, 1, plan_id);
        const order_rc = db.c.sqlite3_step(order_query);
        if (order_rc == db.c.SQLITE_ROW) self.composer_order_id = db.c.sqlite3_column_int64(order_query, 0) else if (order_rc != db.c.SQLITE_DONE) return error.StepFailed;
        var list = std.ArrayList(ModelAssignment).empty;
        errdefer {
            for (list.items) |a| a.deinit(self.allocator);
            list.deinit(self.allocator);
        }

        // FR-001 / AUDIT-INDEP: asignar en orden topológico (olas) para que todo
        // productor tenga su modelo fijado ANTES de que el auditor que lo revisa
        // pida el suyo. Solo así `exclude_models` puede cerrar la auto-auditoría.
        // Si el grafo no resuelve (ciclo/dependencia desconocida — no debería
        // llegar aquí porque la ejecución lo valida antes), se conserva el orden
        // del plan y la exclusión cubre lo ya asignado.
        if (resolveWaves(tasks, self.allocator)) |waves| {
            defer {
                for (waves) |wave| self.allocator.free(wave);
                self.allocator.free(waves);
            }
            for (waves) |wave| {
                for (wave) |pt| try self.assignOne(plan_id, pt, tasks, list.items, &list);
            }
        } else |_| {
            for (tasks) |pt| try self.assignOne(plan_id, pt, tasks, list.items, &list);
        }
        try composer_roles.persistReview(self.allocator, self.runtime, self.composer_order_id, tasks, list.items);
        return list.toOwnedSlice(self.allocator);
    }

    fn assignOne(self: *Superagent, plan_id: i64, pt: planner.PlannedTask, all_tasks: []const planner.PlannedTask, prior: []const ModelAssignment, list: *std.ArrayList(ModelAssignment)) !void {
        const contract_id = try self.insertContract(plan_id, pt);
        const asg = try self.assignModel(pt, all_tasks, prior);
        const model_id: ?i64 = if (asg.assigned) try self.lookupModelId(asg.model_name) else null;
        try self.insertTask(plan_id, pt, contract_id, model_id);
        try list.append(self.allocator, asg);
    }

    /// FR-001 / AUDIT-INDEP: ids de catálogo de los modelos que produjeron lo que
    /// esta tarea va a auditar. Un auditor nunca puede ser el modelo constructor:
    /// la auto-auditoría no es auditoría independiente (deriveStatus la descarta,
    /// así que además aquí se evita que ocurra). La resolución usa
    /// `effectiveDependencyIds` — la misma semántica que la ejecución: depends_on
    /// explícito, o todos los productores del plan si el consumidor no declara.
    fn producerModelIds(self: *Superagent, pt: planner.PlannedTask, all_tasks: []const planner.PlannedTask, prior: []const ModelAssignment) ![]i64 {
        var excluded = std.ArrayList(i64).empty;
        errdefer excluded.deinit(self.allocator);
        const dep_ids = effectiveDependencyIds(self.allocator, pt, all_tasks) catch return excluded.toOwnedSlice(self.allocator);
        defer self.allocator.free(dep_ids);
        for (dep_ids) |dep_id| {
            const pa = findAssignment(prior, dep_id) orelse continue;
            if (!pa.assigned) continue;
            const mid = (self.lookupModelId(pa.model_name) catch null) orelse continue;
            var dup = false;
            for (excluded.items) |x| {
                if (x == mid) {
                    dup = true;
                    break;
                }
            }
            if (!dup) try excluded.append(self.allocator, mid);
        }
        // E5.08 — AUDITORÍA CRUZADA IMPUESTA: si el productor fue un agente
        // externo (`agent:*`), NINGÚN modelo del catálogo de su mismo
        // fabricante puede auditarlo (claude-code ↔ Claude/Anthropic, codex ↔
        // GPT/OpenAI, gemini-cli ↔ Gemini/Google AI Studio, opencode ↔
        // OpenCode). El control negativo de la fila: sin esta exclusión el
        // auditor sale del mismo fabricante y la prueba lo caza.
        for (dep_ids) |dep_id| {
            const pa = findAssignment(prior, dep_id) orelse continue;
            if (!pa.assigned) continue;
            const man = external_agents.modelManufacturer(pa.provider_name, pa.model_name);
            const mids = try self.catalogIdsOfManufacturer(man);
            defer self.allocator.free(mids);
            for (mids) |mid| {
                var dup = false;
                for (excluded.items) |x| {
                    if (x == mid) {
                        dup = true;
                        break;
                    }
                }
                if (!dup) try excluded.append(self.allocator, mid);
            }
        }
        return excluded.toOwnedSlice(self.allocator);
    }

    fn visionMeasured(self: *Superagent, provider: []const u8, model: []const u8) bool {
        const router = self.router orelse return false;
        return model_router.capVisionLiveProbed(router.catalog, provider, model, router.now);
    }

    fn loadOrderImageParts(self: *Superagent, order_id: i64) ![]const providers.connector.ImagePart {
        const filename = db.c.sqlite3_db_filename(self.runtime.db, "main");
        if (filename == null) return error.AttachmentStorageUnavailable;
        const path = std.mem.span(filename);
        if (path.len == 0) return error.AttachmentStorageUnavailable;
        const directory = std.fs.path.dirname(path) orelse ".";
        var threaded = std.Io.Threaded.init(self.allocator, .{});
        defer threaded.deinit();
        var loaded = try order_attachments.loadImages(self.allocator, threaded.io(), self.runtime, directory, order_id);
        defer loaded.deinit();
        if (loaded.items.items.len == 0) return error.OrderAttachmentsMissing;
        const images = try self.allocator.alloc(providers.connector.ImagePart, loaded.items.items.len);
        var initialized: usize = 0;
        errdefer {
            for (images[0..initialized]) |image| self.allocator.free(image.base64);
            self.allocator.free(images);
        }
        for (loaded.items.items, images) |image, *part| {
            const encoded = try self.allocator.alloc(u8, std.base64.standard.Encoder.calcSize(image.bytes.len));
            part.* = .{ .mime_type = image.mime_type, .base64 = std.base64.standard.Encoder.encode(encoded, image.bytes) };
            initialized += 1;
        }
        return images;
    }

    fn assignModel(self: *Superagent, pt: planner.PlannedTask, all_tasks: []const planner.PlannedTask, prior: []const ModelAssignment) !ModelAssignment {
        const router = self.router orelse return unassigned(self.allocator, pt.id, if (pt.needs_vision) "ningún modelo con visión medida disponible" else "sin router configurado (planificación sin proveedores)");
        const justification: ?[]const u8 = if (pt.task_type.allowsPaidEscalation())
            "tarea crítica del plan; escalada permitida si no hay free"
        else
            null;
        // PIXEL-DEVTEAM-05: hint de modelo preferido por especialista (nunca forzado).
        const preferred_model: ?[]const u8 = if (self.registry) |reg|
            reg.modelHintForDept(pt.department)
        else
            null;

        // FR-001 / AUDIT-INDEP: para `auditar`, excluir del ruteo los modelos que
        // produjeron los artefactos bajo revisión. Como el filtro vive en
        // `rankCandidates`, cubre al primario Y a los respaldos — no hay camino
        // de fallback que reseleccione al constructor. El pin manual
        // (plan_set_model) NO se ve afectado: es elección explícita del usuario,
        // y deriveStatus seguirá sin contarla como auditoría independiente.
        const exclude_models: []const i64 = if (pt.task_type == .auditar)
            try self.producerModelIds(pt, all_tasks, prior)
        else
            &.{};
        defer if (exclude_models.len > 0) self.allocator.free(exclude_models);

        const req = model_router.RouteRequest{
            .task_type = pt.task_type,
            .required_context = self.required_context,
            .needs_vision = pt.needs_vision,
            .allow_paid_when_no_free = true,
            .escalation_justification = justification,
            .preferred_model = preferred_model,
            .exclude_models = exclude_models,
        };

        // MODELO-MANUAL-ORQUESTACION: si el usuario fijó un modelo, este es el
        // PRIMARIO obligatorio de la tarea — nunca el resultado del ruteo
        // free-first. ROLES-MODELO: el pin que manda es el del ROL de la tarea
        // (auditar → audit pin ?? orden; resto → exec pin ?? orden). Se consulta
        // is_free en el catálogo solo para clasificación/telemetría; el pin
        // no puede eludir el modo Free aunque el usuario lo haya fijado.
        const swarm_active = self.swarm.len > 0 and try composer_roles.swarmForOrder(self.runtime, router.catalog, self.composer_order_id);
        var pin = self.pinFor(pt.task_type);
        const roles_json = try composer_roles.forOrder(self.allocator, self.runtime, router.catalog, self.composer_order_id);
        defer self.allocator.free(roles_json);
        const roles = try std.json.parseFromSlice([]composer_roles.Pin, self.allocator, roles_json, .{});
        defer roles.deinit();
        var explicit_specialist = false;
        var audit_index: usize = 0;
        if (pt.task_type == .auditar) {
            for (all_tasks) |task| {
                if (std.mem.eql(u8, task.id, pt.id)) break;
                if (task.task_type == .auditar) audit_index += 1;
            }
        }
        const role: ?[]const u8 = switch (pt.task_type) {
            .programar, .programar_c, .programar_cpp, .programar_zig => "programmer",
            .investigar, .resumir, .documentar => "sidekick",
            .auditar => if (audit_index % 2 == 1) "second_audit" else null,
            else => null,
        };
        if (role) |selected_role| for (roles.value) |extra| {
            if (std.mem.eql(u8, extra.role, selected_role)) {
                pin = .{ .provider = extra.provider, .model = extra.model };
                explicit_specialist = true;
                break;
            }
        };
        // A pinned executor remains available for corrections; producers still
        // fan out through the independently enabled swarm. Specialist pins only
        // override their own task type.
        if (swarm_active and !explicit_specialist and switch (pt.task_type) {
            .programar, .programar_c, .programar_cpp, .programar_zig, .investigar, .resumir, .documentar, .disenar, .testear => true,
            else => false,
        }) pin = .{ .provider = null, .model = null };
        // ENJAMBRE: sin pin fijado, las productoras se reparten de forma
        // determinista entre los miembros del conjunto elegido por el usuario
        // y el auditor usa el primer miembro que no produjo lo que revisa.
        // null = sin enjambre, o auditor sin miembro independiente (cae al
        // router con exclusión: la independencia manda sobre el conjunto).
        const swarm_idx: ?usize = if (swarm_active and pin.provider == null)
            try self.pickSwarmIndex(pt, all_tasks, prior)
        else
            null;
        var candidate: model_router.Candidate = if (pin.provider) |fp| blk: {
            const fm = pin.model.?;
            if (pt.needs_vision and !self.visionMeasured(fp, fm))
                return unassigned(self.allocator, pt.id, "ningún modelo con visión medida disponible");
            // E5.08 — auditoría cruzada impuesta en el pin también: un auditor
            // fijado del mismo fabricante que un productor externo (`agent:*`),
            // o un pin `agent:*` del mismo fabricante que un productor de
            // catálogo, no es auditoría independiente. Fallo honesto.
            if (pt.task_type == .auditar) {
                const pin_deps = effectiveDependencyIds(self.allocator, pt, all_tasks) catch &.{};
                defer if (pin_deps.len > 0) self.allocator.free(pin_deps);
                var pin_conflict = false;
                for (pin_deps) |dep_id| {
                    const pa = findAssignment(prior, dep_id) orelse continue;
                    if (!pa.assigned) continue;
                    if (external_agents.crossModelManufacturerExcluded(pa.provider_name, pa.model_name, fp, fm)) {
                        pin_conflict = true;
                        break;
                    }
                }
                if (pin_conflict) {
                    return .{
                        .task_id = pt.id,
                        .assigned = false,
                        .provider_name = try self.allocator.dupe(u8, fp),
                        .model_name = try self.allocator.dupe(u8, fm),
                        .is_free = false,
                        .reason = try self.allocator.dupe(u8, "auditoria cruzada E5.08: el auditor fijado es del mismo fabricante que el productor"),
                        .fallbacks = try self.allocator.alloc(ModelChoice, 0),
                    };
                }
            }
            const is_free = self.isModelFree(fp, fm);
            // El pin elige modelo, pero nunca autoriza gasto dentro de Free.
            if (router.getGovernanceMode() == .free_tier_first and !is_free) {
                return .{
                    .task_id = pt.id,
                    .assigned = false,
                    .provider_name = try self.allocator.dupe(u8, fp),
                    .model_name = try self.allocator.dupe(u8, fm),
                    .is_free = false,
                    .reason = try self.allocator.dupe(u8, "Free: el modelo fijado no esta catalogado como gratuito; cambia el modelo o el modo de coste"),
                    .fallbacks = try self.allocator.alloc(ModelChoice, 0),
                };
            }
            break :blk model_router.Candidate{
                .provider_id = 0,
                .provider_name = try self.allocator.dupe(u8, fp),
                .model_id = 0,
                .model_name = try self.allocator.dupe(u8, fm),
                .api_key_id = 0,
                .is_free = is_free,
                .score = 1.0,
                .health_factor = 1.0,
                // P8: el modelo fijado manualmente se considera que SÍ tiene
                // historial a los efectos de la clase (el usuario lo eligió).
                .proven = true,
                .reason = try self.allocator.dupe(u8, "modelo fijado manualmente (plan_set_model)"),
            };
        } else if (swarm_idx) |si| blk: {
            const m = self.swarm[si];
            break :blk model_router.Candidate{
                .provider_id = 0,
                .provider_name = try self.allocator.dupe(u8, m.provider),
                .model_id = 0,
                .model_name = try self.allocator.dupe(u8, m.model),
                .api_key_id = 0,
                .is_free = self.isModelFree(m.provider, m.model),
                .score = 1.0,
                .health_factor = 1.0,
                .proven = true,
                .reason = try std.fmt.allocPrint(self.allocator, "enjambre: reparto {d}/{d} elegido por el usuario", .{ si + 1, self.swarm.len }),
            };
        } else if (swarm_active and pt.task_type != .auditar) {
            // ENJAMBRE-AGOTADO: hay conjunto fijado pero ningún miembro pasa la
            // gobernanza vigente. Fallo honesto nombrando el enjambre — nunca
            // un salto silencioso al router, que traicionaría la elección.
            return ModelAssignment{
                .task_id = pt.id,
                .assigned = false,
                .provider_name = try self.allocator.dupe(u8, "enjambre"),
                .model_name = try self.allocator.dupe(u8, "enjambre"),
                .is_free = false,
                .reason = try self.allocator.dupe(u8, if (pt.needs_vision) "ningún modelo con visión medida disponible" else "enjambre agotado: ningun miembro es usable bajo la gobernanza vigente (modo Solo gratis, modelo no generador o proveedor sin clave)"),
                .fallbacks = try self.allocator.alloc(ModelChoice, 0),
            };
        } else router.route(req) catch |e| {
            const reason = if (pt.needs_vision) try self.allocator.dupe(u8, "ningún modelo con visión medida disponible") else try std.fmt.allocPrint(self.allocator, "sin asignación: {s}", .{@errorName(e)});
            return ModelAssignment{
                .task_id = pt.id,
                .assigned = false,
                .provider_name = try self.allocator.dupe(u8, "none"),
                .model_name = try self.allocator.dupe(u8, "none"),
                .is_free = false,
                .reason = reason,
                .fallbacks = try self.allocator.alloc(ModelChoice, 0),
            };
        };
        defer candidate.deinit(self.allocator);

        // MODO-DETERMINISTA: cero respaldos. El modelo que fijó el usuario hace la
        // tarea entera o la tarea falla nombrándolo. Va ANTES de recolectar nada
        // para que no haya forma de que un respaldo se cuele por un camino nuevo.
        // ROLES-MODELO: aplica al pin del ROL de la tarea (pin ya resuelto arriba).
        // / E-GOV.3 (rama e5-gov): un agente CLI fijado tampoco
        // lleva respaldos en su asignación; el despacho ya no los usaría
        // y la tarjeta no debe prometerlos.
        const agent_pin = self.pinFor(pt.task_type).provider != null and external_agents.isAgentProvider(candidate.provider_name);
        if (self.deterministic or agent_pin) {
            return ModelAssignment{
                .task_id = pt.id,
                .assigned = true,
                .provider_name = try self.allocator.dupe(u8, candidate.provider_name),
                .model_name = try self.allocator.dupe(u8, candidate.model_name),
                .is_free = candidate.is_free,
                .reason = try self.allocator.dupe(u8, if (self.deterministic) "modo determinista: modelo fijado por el usuario, sin respaldos" else "ejecutor fijado por el usuario: sin respaldos no autorizados"),
                .fallbacks = try self.allocator.alloc(ModelChoice, 0),
            };
        }

        // MODELO-LOCAL: un modelo que corre en la máquina del usuario (Ollama)
        // no engancha respaldos automáticos — ni de la nube ni de otros
        // modelos. "Funciona solo con el modelo local" es el comportamiento
        // seguro por defecto: la cadena podría saltar a otro proveedor o
        // multiplicar la carga sin que el usuario lo pidiera. El enjambre
        // explícito sigue repartiendo miembros entre tareas; lo que se
        // suprime es la cola de respaldo de cada asignación.
        // Opt-in explícito: DEVAGENTS_LOCAL_ALLOW_FALLBACK=1.
        if (providers.providers.isLocalProviderName(candidate.provider_name) and
            !providers.providers.envFlagEnabled("DEVAGENTS_LOCAL_ALLOW_FALLBACK"))
        {
            return ModelAssignment{
                .task_id = pt.id,
                .assigned = true,
                .provider_name = try self.allocator.dupe(u8, candidate.provider_name),
                .model_name = try self.allocator.dupe(u8, candidate.model_name),
                .is_free = candidate.is_free,
                .reason = try self.allocator.dupe(u8, "modelo local: ejecucion exacta sin respaldos (opt-in: DEVAGENTS_LOCAL_ALLOW_FALLBACK=1)"),
                .fallbacks = try self.allocator.alloc(ModelChoice, 0),
            };
        }

        // FIX-5 / FALLBACK-01: recolectar hasta 3 candidatos FREE de respaldo (distintos del
        // primario) desde el ranking del router, para reintentar si el primario falla.
        var fallbacks = std.ArrayList(ModelChoice).empty;
        errdefer {
            for (fallbacks.items) |fc| fc.deinit(self.allocator);
            fallbacks.deinit(self.allocator);
        }
        if (swarm_idx) |si| {
            // ENJAMBRE-RESPALDOS: la cadena de respaldo también sale del
            // conjunto elegido — nada fuera de él. Rotación desde el primario;
            // para el auditor se respeta la misma exclusión de productores.
            const dep_ids: []const []const u8 = if (pt.task_type == .auditar)
                effectiveDependencyIds(self.allocator, pt, all_tasks) catch &.{}
            else
                &.{};
            defer if (dep_ids.len > 0) self.allocator.free(dep_ids);
            const free_first = self.router != null and
                self.router.?.getGovernanceMode() == .free_tier_first;
            for (1..self.swarm.len) |k| {
                const m = self.swarm[(si + k) % self.swarm.len];
                if (!self.swarmMemberUsable(free_first, m)) continue;
                if (pt.task_type == .auditar and swarmAuditExcluded(dep_ids, prior, m)) continue;
                try fallbacks.append(self.allocator, .{
                    .provider_name = try self.allocator.dupe(u8, m.provider),
                    .model_name = try self.allocator.dupe(u8, m.model),
                    .is_free = self.isModelFree(m.provider, m.model),
                });
            }
        } else if (router.rankCandidates(req)) |ranked_val| {
            var ranked = ranked_val;
            defer {
                for (ranked.items) |c| c.deinit(self.allocator);
                ranked.deinit(self.allocator);
            }
            const MAX_FALLBACKS: usize = 5;
            const MAX_PER_FAMILY: usize = 2;
            // GOBERNANZA-RESPALDOS: con "Prioriza pago" los respaldos NO pueden
            // ser solo gratuitos. El filtro `!c.is_free` estaba escrito a fuego,
            // así que elegir pago no cambiaba nada: la cadena seguía siendo
            // free-first y los de pago quedaban relegados a los dos últimos
            // huecos. `rankCandidates` ya devuelve el orden correcto según la
            // gobernanza, así que basta con no descartar por precio cuando el
            // usuario ha pedido pago.
            // GOBERNANZA-HIBRIDO: la decisión free/pago la toma `prefersFreeFirst`,
            // que también contempla Híbrido por etapa (planificar/auditar → pago).
            // Antes esto solo miraba `!= .paid_tier_first`, así que en Híbrido los
            // respaldos de una auditoría seguían siendo exclusivamente gratuitos.
            const gov = router.getGovernanceMode();
            const solo_gratis_en_respaldos = model_router.prefersFreeFirst(gov, pt.task_type);
            // ROSTER-PRUEBAS: esta cola se arma desde `rankCandidates`, o sea sin
            // pasar por `route`, así que el roster hay que aplicarlo aquí también.
            // Mientras no estuvo, el roster acotaba la cadena viva y esta cola se
            // colaba por detrás (orden #211: Cohere/north-mini-code-1-0).
            const roster_activo = model_router.rosterCubreAlguno(ranked.items);
            for (ranked.items) |c| {
                if (fallbacks.items.len >= MAX_FALLBACKS) break;
                if (model_router.rosterDescarta(roster_activo, c)) continue;
                if (solo_gratis_en_respaldos and !c.is_free) continue;
                if (std.mem.eql(u8, c.model_name, candidate.model_name)) continue;
                // FIRE-2026-07-10: los modelos que no generan texto (rerank/lyria/
                // imagen/tts/...) JAMÁS entran como respaldo de una tarea de texto.
                // Penalizarlos en el prior no bastaba: con la salud degradando por
                // igual a todos los :free (rate-limits masivos), quemaban los 5
                // huecos y la orden moría en provider_exhausted (órdenes 316-318).
                if (model_router.isNonTextGenModel(c.model_name)) continue;
                const fam = modelFamily(c.model_name);
                // FIX-6: limitar respaldos por familia para forzar diversidad cross-familia
                // (un generalista de otra familia rescata si la familia primaria se agota).
                var fam_count: usize = 0;
                for (fallbacks.items) |ex| {
                    if (std.mem.eql(u8, modelFamily(ex.model_name), fam)) fam_count += 1;
                }
                if (fam_count >= MAX_PER_FAMILY) continue;
                try fallbacks.append(self.allocator, .{
                    .provider_name = try self.allocator.dupe(u8, c.provider_name),
                    .model_name = try self.allocator.dupe(u8, c.model_name),
                    .is_free = c.is_free,
                });
            }
            // FIRE-2026-07-10: escalada a pago como ÚLTIMO recurso — SIEMPRE que la
            // tarea lo permita (allowsPaidEscalation), anexar hasta 2 respaldos de
            // pago AL FINAL de la cola (free-first intacto: solo se alcanzan si
            // TODOS los free fallaron en runtime). Antes solo se probaba pago si no
            // existía ningún free en catálogo — pero el modo real de fallo es que
            // los :free EXISTEN y se caen uno a uno por rate-limit (órdenes 316-323:
            // el caso D probó que Cohere respondía mientras los :free morían).
            if (pt.task_type.allowsPaidEscalation()) {
                const MAX_PAID_FALLBACKS: usize = 2;
                var paid_added: usize = 0;
                for (ranked.items) |c| {
                    if (paid_added >= MAX_PAID_FALLBACKS) break;
                    if (model_router.rosterDescarta(roster_activo, c)) continue;
                    if (c.is_free) continue;
                    if (std.mem.eql(u8, c.model_name, candidate.model_name)) continue;
                    if (model_router.isNonTextGenModel(c.model_name)) continue;
                    var dup = false;
                    for (fallbacks.items) |ex| {
                        if (std.mem.eql(u8, ex.model_name, c.model_name)) {
                            dup = true;
                            break;
                        }
                    }
                    if (dup) continue;
                    try fallbacks.append(self.allocator, .{
                        .provider_name = try self.allocator.dupe(u8, c.provider_name),
                        .model_name = try self.allocator.dupe(u8, c.model_name),
                        .is_free = c.is_free,
                    });
                    paid_added += 1;
                }
            }
        } else |_| {}

        return ModelAssignment{
            .task_id = pt.id,
            .assigned = true,
            .provider_name = try self.allocator.dupe(u8, candidate.provider_name),
            .model_name = try self.allocator.dupe(u8, candidate.model_name),
            .is_free = candidate.is_free,
            .reason = try self.allocator.dupe(u8, candidate.reason),
            .fallbacks = try fallbacks.toOwnedSlice(self.allocator),
        };
    }

    /// ENJAMBRE: índice del miembro que le toca a `pt` dentro de self.swarm.
    /// Productoras: la N-ésima tarea productora (orden de `prior`) recibe el
    /// miembro N % len — con 2+ miembros, tareas paralelas del mismo plan usan
    /// modelos distintos. Auditor: primer miembro que no produjo lo que revisa.
    /// null = sin enjambre, o ningún miembro usable (el caller decide).
    fn pickSwarmIndex(
        self: *Superagent,
        pt: planner.PlannedTask,
        all_tasks: []const planner.PlannedTask,
        prior: []const ModelAssignment,
    ) !?usize {
        if (self.swarm.len == 0) return null;
        const free_first = self.router != null and
            self.router.?.getGovernanceMode() == .free_tier_first;
        if (pt.task_type == .auditar) {
            const dep_ids = effectiveDependencyIds(self.allocator, pt, all_tasks) catch return null;
            defer if (dep_ids.len > 0) self.allocator.free(dep_ids);
            for (self.swarm, 0..) |m, i| {
                if (pt.needs_vision and !self.visionMeasured(m.provider, m.model)) continue;
                if (!swarmMemberUsable(self, free_first, m)) continue;
                if (swarmAuditExcluded(dep_ids, prior, m)) continue;
                return i;
            }
            return null;
        }
        var producers: usize = 0;
        for (prior) |pa| {
            const t = findPlannedTask(all_tasks, pa.task_id) orelse continue;
            if (t.task_type != .auditar) producers += 1;
        }
        for (0..self.swarm.len) |k| {
            const i = (producers + k) % self.swarm.len;
            if (pt.needs_vision and !self.visionMeasured(self.swarm[i].provider, self.swarm[i].model)) continue;
            if (swarmMemberUsable(self, free_first, self.swarm[i])) return i;
        }
        return null;
    }

    /// ENJAMBRE: un miembro es usable si genera texto y pasa la gobernanza
    /// free-first (en "Prioriza pago"/Híbrido todo miembro vale; en "Solo
    /// gratis" solo valen los catalogados gratuitos — igual que el pin manual,
    /// el enjambre nunca elude el modo de coste).
    fn swarmMemberUsable(self: *Superagent, free_first: bool, m: SwarmMember) bool {
        const selection = @import("model_selection.zig");
        if (self.router) |r| {
            const preferences = selection.get(r.catalog, m.provider, m.model) catch |e| {
                std.log.warn("swarm preferences: {s}", .{@errorName(e)});
                return false;
            };
            if (!preferences.allow_automatic) return false;
            if (!external_agents.isAgentProvider(m.provider)) {
                const chat = selection.catalogTextGeneration(r.catalog, m.provider, m.model) catch |e| {
                    std.log.warn("swarm capability: {s}", .{@errorName(e)});
                    return false;
                };
                if (!chat) return false;
            }
        } else if (model_router.isNonTextGenModel(m.model)) return false;
        if (external_agents.isAgentProvider(m.provider)) {
            const status = selection.externalEligibility(self.allocator, self.external_catalog_json orelse "[]", m.provider, m.model) catch |e| {
                std.log.warn("swarm CLI catalog: {s}", .{@errorName(e)});
                return false;
            };
            if (!status.chat) return false;
        }
        if (free_first and !self.isModelFree(m.provider, m.model)) return false;
        return true;
    }

    /// E5.18 (D-C5): elige hasta `n` miembros de PROVEEDORES DISTINTOS para
    /// best-of-N. La lista explícita de la orden (`members_json`,
    /// [{provider,model}]) manda sobre el enjambre; sin ella se recorre el
    /// enjambre fijado al aprobar. Todos los candidatos pasan el mismo filtro
    /// de usabilidad que el reparto (texto + gobernanza de coste) — un
    /// miembro de pago bajo "Solo gratis" no entra ni por lista explícita.
    /// Devuelve menos de `n` si no hay suficientes proveedores distintos
    /// usables; el llamador decide si el modo sigue en pie (mínimo 2).
    /// La slice devuelta y sus strings son owned por `allocator`.
    pub fn pickBestOfNMembers(
        self: *Superagent,
        allocator: std.mem.Allocator,
        n: usize,
        members_json: ?[]const u8,
    ) ![]SwarmMember {
        const free_first = self.router != null and
            self.router.?.getGovernanceMode() == .free_tier_first;

        var pool = std.ArrayList(SwarmMember).empty;
        defer {
            // La pool guarda vistas del enjambre (no owned) o dupes de la lista
            // explícita: solo se liberan los dupes explícitos no adoptados.
            for (pool.items) |m| {
                if (!isSwarmView(self, m)) {
                    self.allocator.free(m.provider);
                    self.allocator.free(m.model);
                }
            }
            pool.deinit(self.allocator);
        }

        if (members_json) |mj| {
            const parsed_members = try best_of_n.parseMembersJson(allocator, mj);
            defer {
                for (parsed_members) |*m| m.deinit(allocator);
                allocator.free(parsed_members);
            }
            for (parsed_members) |m| {
                if (!swarmMemberUsable(self, free_first, .{ .provider = m.provider, .model = m.model })) continue;
                try pool.append(self.allocator, .{
                    .provider = try self.allocator.dupe(u8, m.provider),
                    .model = try self.allocator.dupe(u8, m.model),
                });
            }
        } else {
            for (self.swarm) |m| {
                if (swarmMemberUsable(self, free_first, m)) try pool.append(self.allocator, m);
            }
        }

        // Dedupe por proveedor sobre una vista Member (sin clonar).
        const pool_m = try self.allocator.alloc(best_of_n.Member, pool.items.len);
        defer self.allocator.free(pool_m);
        for (pool.items, 0..) |m, i| pool_m[i] = .{ .provider = m.provider, .model = m.model };
        var distinct_buf: [best_of_n.MAX_N]best_of_n.Member = undefined;
        const count = best_of_n.distinctProviders(pool_m, n, distinct_buf[0..]);

        const picked = try self.allocator.alloc(SwarmMember, count);
        var filled: usize = 0;
        errdefer {
            for (picked[0..filled]) |p| {
                self.allocator.free(p.provider);
                self.allocator.free(p.model);
            }
            self.allocator.free(picked);
        }
        for (distinct_buf[0..count]) |dm| {
            picked[filled] = .{
                .provider = try self.allocator.dupe(u8, dm.provider),
                .model = try self.allocator.dupe(u8, dm.model),
            };
            filled += 1;
        }
        return picked;
    }

    /// ¿`m` es una vista al enjambre (no owned) o un dupe de lista explícita?
    fn isSwarmView(self: *Superagent, m: SwarmMember) bool {
        for (self.swarm) |s| {
            if (s.provider.ptr == m.provider.ptr and s.model.ptr == m.model.ptr) return true;
        }
        return false;
    }

    /// ENJAMBRE: ¿este miembro produjo alguna de las dependencias que `auditar`
    /// va a revisar? Misma regla de exclusión que exclude_models del router,
    /// pero por (provider, model) porque los miembros pueden no tener catalog_id.
    /// E5.08: además, un miembro del MISMO FABRICANTE que un productor externo
    /// (`agent:*`) queda excluido — la auditoría cruzada es impuesta.
    fn swarmAuditExcluded(dep_ids: []const []const u8, prior: []const ModelAssignment, m: SwarmMember) bool {
        for (dep_ids) |dep_id| {
            const pa = findAssignment(prior, dep_id) orelse continue;
            if (!pa.assigned) continue;
            if (std.mem.eql(u8, pa.provider_name, m.provider) and
                std.mem.eql(u8, pa.model_name, m.model)) return true;
            // E5.08: exclusión por fabricante (solo cuando alguno es agente).
            if (external_agents.crossModelManufacturerExcluded(pa.provider_name, pa.model_name, m.provider, m.model)) return true;
        }
        return false;
    }

    fn lookupModelId(self: *Superagent, model_name: []const u8) !?i64 {
        const router = self.router orelse return null;
        const stmt = try router.catalog.prepare("SELECT id FROM models WHERE model_name = ? LIMIT 1");
        defer router.catalog.finalize(stmt);
        try db.bindText(stmt, 1, model_name);
        if (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW) {
            return db.c.sqlite3_column_int64(stmt, 0);
        }
        return null;
    }

    /// Consulta is_free del catálogo para (provider,model). Best-effort: si no está en
    /// catálogo (p.ej. modelo forzado escrito a mano), asume paid (false) por seguridad.
    /// E5.08: un proveedor `agent:*` corre sobre la suscripción del usuario —
    /// sin coste marginal de API, compatible con el modo Solo gratis.
    fn isModelFree(self: *Superagent, provider: []const u8, model: []const u8) bool {
        if (external_agents.isAgentProvider(provider)) {
            const status = @import("model_selection.zig").externalEligibility(self.allocator, self.external_catalog_json orelse "[]", provider, model) catch |e| {
                std.log.warn("CLI free eligibility: {s}", .{@errorName(e)});
                return false;
            };
            return status.free;
        }
        const router = self.router orelse return false;
        return model_router.catalogModelIsFree(router.catalog, provider, model);
    }

    // ── E5.08: agentes externos en el despacho gobernado ──────────────────

    /// Resultado de fallo honesto de la rama externa (sin artefactos: el diff
    /// parcial ya quedó en el ledger vía external_agent_finished).
    fn externalFail(allocator: std.mem.Allocator, task_id: []const u8, msg: []const u8) worker_backend.WorkerResult {
        return .{
            .task_id = allocator.dupe(u8, task_id) catch "",
            .artifacts = &.{},
            .success = false,
            .error_msg = allocator.dupe(u8, msg) catch "",
        };
    }

    /// deja constancia de un respaldo REAL de la tarea (falló
    /// `from`, siguió `to`) para que el cierre del chat lo declare. Se llama
    /// bajo `ctx.mutex` — los hilos de tarea comparten la lista.
    fn recordFallbackNote(
        self: *Superagent,
        ctx: *FanoutContext,
        task_id: []const u8,
        from_prov: []const u8,
        from_mdl: []const u8,
        reason: []const u8,
        to_prov: []const u8,
        to_mdl: []const u8,
    ) void {
        const allocator = self.allocator;
        const task_copy = allocator.dupe(u8, task_id) catch return;
        const from_label = executorLabel(allocator, from_prov, from_mdl) catch {
            allocator.free(task_copy);
            return;
        };
        const reason_copy = allocator.dupe(u8, reason) catch {
            allocator.free(task_copy);
            allocator.free(from_label);
            return;
        };
        const to_label = executorLabel(allocator, to_prov, to_mdl) catch {
            allocator.free(task_copy);
            allocator.free(from_label);
            allocator.free(reason_copy);
            return;
        };
        const note = FallbackNote{
            .task_id = task_copy,
            .from_label = from_label,
            .reason = reason_copy,
            .to_label = to_label,
        };
        ctx.fallback_notes.append(allocator, note) catch note.deinit(allocator);
    }

    /// Prompt de la rama externa: mismo contenido que el del worker nativo
    /// (system prompt + tarea + contrato + manifiesto + upstream) pero pide
    /// ARCHIVOS REALES en el worktree — el agente opera con sus herramientas,
    /// no devuelve el array JSON de transporte del worker nativo.
    fn buildExternalPrompt(allocator: std.mem.Allocator, ctx: *FanoutContext, pt: planner.PlannedTask) ![]u8 {
        var prompt = std.ArrayList(u8).empty;
        errdefer prompt.deinit(allocator);
        const system_prompt = ctx.sa.systemPromptForTask(pt.department, pt.task_type, pt.description) catch "";
        defer if (system_prompt.len > 0) allocator.free(system_prompt);
        // La tarea va PRIMERO, imperativa: con el rol por delante, el CLI en
        // modo exec contestaba como chat ("Entendido, indícame la tarea") y
        // no ejecutaba nada — medido en vivo con codex 0.144.4 + gpt-5.6-sol.
        try prompt.appendSlice(allocator, if (pt.task_type == .auditar) "AUDITA AHORA: lee los artefactos; no los modifiques. Devuelve el contrato JSON con verdict PASS o FAIL y hallazgos:\n" else "TAREA A EJECUTAR AHORA (produce los archivos reales en el worktree; no contestes con una charla):\n");
        try prompt.appendSlice(allocator, pt.description);
        try prompt.appendSlice(allocator, if (pt.task_type == .auditar) "\n\nCONTRATO DE LA RESPUESTA JSON (field,content):\n" else "\n\nCONTRATO (entregables a producir como ARCHIVOS REALES dentro del worktree):\n");
        for (pt.contract_fields) |cf| {
            const line = if (cf.value) |value|
                try std.fmt.allocPrint(allocator, "  - {s}: {s} (required={any}, value={s})\n", .{ cf.name, @tagName(cf.field_type), cf.required, value })
            else
                try std.fmt.allocPrint(allocator, "  - {s}: {s} (required={any})\n", .{ cf.name, @tagName(cf.field_type), cf.required });
            defer allocator.free(line);
            try prompt.appendSlice(allocator, line);
        }
        try prompt.appendSlice(allocator, "\nCONTEXTO DE ROL\n");
        try prompt.appendSlice(allocator, system_prompt);
        try prompt.appendSlice(allocator, "\n");
        if (ctx.plan_manifest) |pm| {
            try prompt.appendSlice(allocator, "\n[PLAN DE LA ORDEN — OTRAS TAREAS DE ESTA MISMA ORDEN]\n");
            try prompt.appendSlice(allocator, "Eres uno de varios agentes trabajando en la MISMA orden. Mantén nombres de archivos, módulos, funciones y símbolos EXACTAMENTE CONSISTENTES con las demás tareas.\n");
            try prompt.appendSlice(allocator, pm);
            try prompt.appendSlice(allocator, "\n");
        }
        if (ctx.current_upstream) |uc| {
            try prompt.appendSlice(allocator, "\n[ARCHIVOS YA CREADOS POR TAREAS PREVIAS DE ESTA ORDEN]\n");
            try prompt.appendSlice(allocator, uc);
            try prompt.appendSlice(allocator, "\n");
        }
        if (ctx.repo_map_text) |mt| {
            try prompt.appendSlice(allocator, "\n[MAPA DEL REPOSITORIO — archivos ordenados por relevancia para esta orden; cada línea es `ruta` seguida de `  símbolo:línea`]\n");
            try prompt.appendSlice(allocator, mt);
            try prompt.appendSlice(allocator, "[FIN MAPA DEL REPOSITORIO]\n");
        }
        if (pt.task_type != .auditar) try prompt.appendSlice(allocator, "\nActúas como agente externo de DevAgents operando DIRECTAMENTE sobre el worktree de la orden: crea y edita los archivos reales con tus herramientas (NO devuelvas un array JSON de transporte). Produce los entregables del contrato usando EXACTAMENTE los nombres indicados — cada entregable es un archivo real con ese nombre en el worktree. Lee antes los archivos existentes que cites o modifiques.\n");
        if (pt.task_type == .auditar) {
            try prompt.appendSlice(allocator, "El campo verdict del JSON debe empezar con PASS o FAIL, seguido de los hallazgos concretos con rutas y líneas reales leídas del worktree. Un comando que termina con exit 0 no demuestra por sí solo cobertura ni funcionamiento de la interfaz.\n");
        }
        return try prompt.toOwnedSlice(allocator);
    }

    /// Contexto del sink de eventos del streaming → eventos de la orden.
    const ExternalEventCtx = struct {
        ctx: *FanoutContext,
        task_id: []const u8,
    };

    const ExternalSessionCtx = struct {
        ctx: *FanoutContext,
        key: @import("external_session.zig").Key,

        fn call(raw: *anyopaque, kind: @import("external_session.zig").Kind, id: ?[]const u8, reason: []const u8) anyerror!void {
            const self: *@This() = @ptrCast(@alignCast(raw));
            self.ctx.mutex.lock();
            defer self.ctx.mutex.unlock();
            const sa = self.ctx.sa;
            try @import("external_session.zig").record(sa.allocator, sa.event_conn orelse sa.runtime, self.key, kind, id, reason);
            // Reuse the visible external-agent status stream as well as the
            // typed checkpoint event; the UI need not know a new event kind.
            const text = try std.fmt.allocPrint(sa.allocator, "{s}: CLI {s}; sesion {s}; tarea {s}; {s}", .{ @import("external_session.zig").eventName(kind), self.key.cli, id orelse "sin id", self.key.task_id, reason });
            defer sa.allocator.free(text);
            const body = try std.json.Stringify.valueAlloc(sa.allocator, .{ .task_id = self.key.task_id, .kind = "status", .text = text }, .{});
            defer sa.allocator.free(body);
            sa.recordEvent("external_agent_event", body);
        }
    };

    /// Cada evento del agente (contenido, herramienta, plan…) es un
    /// `external_agent_event` del ledger — misma superficie que content_delta.
    /// El texto se acota a 2 KiB: la transcripción completa ya va acotada en
    /// external_agent_finished.
    fn externalEventSink(raw: *anyopaque, kind: headless_adapter.EventKind, text: []const u8) void {
        const ectx: *ExternalEventCtx = @ptrCast(@alignCast(raw));
        const ctx = ectx.ctx;
        const allocator = ctx.sa.allocator;
        var out: std.Io.Writer.Allocating = .init(allocator);
        defer out.deinit();
        var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
        js.beginObject() catch return;
        js.objectField("task_id") catch return;
        js.write(ectx.task_id) catch return;
        js.objectField("kind") catch return;
        js.write(@tagName(kind)) catch return;
        js.objectField("text") catch return;
        js.write(text[0..@min(text.len, 2048)]) catch return;
        js.endObject() catch return;
        ctx.mutex.lock();
        defer ctx.mutex.unlock();
        ctx.sa.recordEvent("external_agent_event", out.written());
    }

    /// P1-1 (R2 A1): como `directo_started_v1`, el arranque guarda con qué
    /// modo de permisos y con qué CLI (versión y ruta de la detección, el
    /// pin) se lanzó. Sin pin (auditor por completion, o fallo antes de
    /// resolverlo) `cli_version` y `cli_path` quedan null.
    /// QA-B 2c: aviso de rotación de cuenta de una tarea de Orquestado o
    /// Colmena: evento `cli_account_rotated_v1` (el mismo que Directo).
    const ExternalAccountRotation = struct {
        ctx: *FanoutContext,
        task_id: []const u8,

        fn notify(raw: ?*anyopaque, notice: @import("cli_accounts.zig").RotationNotice) void {
            const self: *ExternalAccountRotation = @ptrCast(@alignCast(raw.?));
            const allocator = self.ctx.sa.allocator;
            const text = @import("cli_accounts.zig").noticeText(allocator, notice) catch |e| {
                std.log.warn("aviso de rotación de cuenta no construido: {s}", .{@errorName(e)});
                return;
            };
            defer allocator.free(text);
            const payload = std.json.Stringify.valueAlloc(allocator, .{ .task_id = self.task_id, .cli = notice.cli, .from = notice.from_id, .to = notice.to_id, .message = text }, .{}) catch |e| {
                std.log.warn("aviso de rotación de cuenta no serializado: {s}", .{@errorName(e)});
                return;
            };
            defer allocator.free(payload);
            self.ctx.mutex.lock();
            defer self.ctx.mutex.unlock();
            self.ctx.sa.recordEvent("cli_account_rotated_v1", payload);
        }
    };

    fn emitExternalStarted(ctx: *FanoutContext, task_id: []const u8, meta: external_agents.AgentMeta, prov: []const u8, pin: ?*const external_registry.Pin) void {
        const allocator = ctx.sa.allocator;
        var out: std.Io.Writer.Allocating = .init(allocator);
        defer out.deinit();
        var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
        js.beginObject() catch return;
        js.objectField("task_id") catch return;
        js.write(task_id) catch return;
        js.objectField("provider") catch return;
        js.write(prov) catch return;
        js.objectField("cli") catch return;
        js.write(meta.cli_id) catch return;
        js.objectField("display") catch return;
        js.write(meta.display) catch return;
        js.objectField("manufacturer") catch return;
        js.write(meta.manufacturer.text()) catch return;
        js.objectField("acp") catch return;
        js.write(meta.acp_argv != null) catch return;
        var root_buf: [4096]u8 = undefined;
        js.objectField("worktree_root") catch return;
        js.write(workspace.effectiveRoot(&root_buf)) catch return;
        js.objectField("permission_mode") catch return;
        js.write(@tagName(ctx.sa.permission_config.mode)) catch return;
        js.objectField("cli_version") catch return;
        js.write(if (pin) |p| @as(?[]const u8, p.version) else null) catch return;
        js.objectField("cli_path") catch return;
        js.write(if (pin) |p| @as(?[]const u8, p.exe) else null) catch return;
        js.endObject() catch return;
        ctx.mutex.lock();
        defer ctx.mutex.unlock();
        ctx.sa.recordEvent("external_agent_started", out.written());
    }

    /// external_agent_finished: CLI, versión, argv censurado, salida (cola
    /// acotada del detalle), duración y turnos — el payload pide la fila.
    fn emitExternalFinished(ctx: *FanoutContext, task_id: []const u8, meta: external_agents.AgentMeta, prov: []const u8, outcome: ?*const external_agents.RunOutcome, run_err: ?anyerror) void {
        emitExternalFinishedDiagnostic(ctx, task_id, meta, prov, outcome, run_err, null, null);
    }

    fn emitExternalFinishedDiagnostic(ctx: *FanoutContext, task_id: []const u8, meta: external_agents.AgentMeta, prov: []const u8, outcome: ?*const external_agents.RunOutcome, run_err: ?anyerror, diagnostic: ?[]const u8, repair: ?*const headless_adapter.SnapshotDiagnostic) void {
        const allocator = ctx.sa.allocator;
        var out: std.Io.Writer.Allocating = .init(allocator);
        defer out.deinit();
        var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
        js.beginObject() catch return;
        js.objectField("task_id") catch return;
        js.write(task_id) catch return;
        js.objectField("provider") catch return;
        js.write(prov) catch return;
        js.objectField("cli") catch return;
        js.write(meta.cli_id) catch return;
        if (outcome) |o| {
            js.objectField("version") catch return;
            js.write(o.agent_version) catch return;
            js.objectField("argv") catch return;
            js.write(o.argv_censored) catch return;
            js.objectField("output") catch return;
            js.write(o.detail[0..@min(o.detail.len, 4096)]) catch return;
            js.objectField("declaration") catch return;
            js.write(o.declaration[0..@min(o.declaration.len, 4096)]) catch return;
            js.objectField("duration_ms") catch return;
            js.write(o.duration_ms) catch return;
            js.objectField("turns") catch return;
            js.write(o.turns) catch return;
            js.objectField("exit_code") catch return;
            if (o.exit_code) |c| {
                js.write(c) catch return;
            } else {
                js.write(@as(?u8, null)) catch return;
            }
            js.objectField("success") catch return;
            js.write(o.success) catch return;
            js.objectField("timed_out") catch return;
            js.write(o.timed_out) catch return;
            js.objectField("turn_limited") catch return;
            js.write(o.turn_limited) catch return;
            js.objectField("prompt_tokens") catch return;
            js.write(o.prompt_tokens) catch return;
            js.objectField("completion_tokens") catch return;
            js.write(o.completion_tokens) catch return;
            js.objectField("artifacts") catch return;
            js.beginArray() catch return;
            for (o.artifacts) |a| js.write(a.path) catch return;
            js.endArray() catch return;
            if (o.env_warnings.len > 0) {
                js.objectField("env_warnings") catch return;
                js.beginArray() catch return;
                for (o.env_warnings) |w| js.write(w) catch return;
                js.endArray() catch return;
            }
        } else {
            js.objectField("success") catch return;
            js.write(run_err == null) catch return;
            js.objectField("error") catch return;
            js.write(diagnostic orelse if (run_err) |e| @errorName(e) else "") catch return;
            if (diagnostic != null) {
                js.objectField("error_code") catch return;
                js.write(if (run_err) |e| @errorName(e) else "") catch return;
            }
            // Raíz e identidad del espacio rechazado: la reparación explícita
            // actúa solo sobre esa carpeta y comprueba que siga siendo ella.
            if (repair) |snapshot| if (snapshot.repairRoot()) |root| if (snapshot.repairId()) |id| {
                js.objectField("workspace_root") catch return;
                js.write(root) catch return;
                js.objectField("workspace_id") catch return;
                js.write(id) catch return;
            };
        }
        js.endObject() catch return;
        ctx.mutex.lock();
        defer ctx.mutex.unlock();
        ctx.sa.recordEvent("external_agent_finished", out.written());
    }

    /// Contexto del puente session/request_permission → gobernanza + cabina.
    const ExternalPermCtx = struct {
        sa: *Superagent,
        task_id: []const u8,
        /// Sandbox raíz del WORKTREE (no el sandbox/<task_id> del contrato).
        sb: *const sandbox.Sandbox,
        cli: []const u8,
        /// Reutilizable: el optionId elegido vive aquí entre llamadas
        /// (PermissionOutcome.selected es prestado — el cliente lo serializa
        /// dentro de la llamada y no lo libera).
        last_opt: std.ArrayList(u8) = .empty,
    };

    /// Consulta la resolución de una aprobación persistida.
    const ApprovalState = struct { resolved: bool, approved: bool };
    fn queryApprovalState(conn: db.Connection, approval_id: i64) ApprovalState {
        const stmt = conn.prepare("SELECT approved, resolved FROM approvals WHERE id = ?") catch return .{ .resolved = false, .approved = false };
        defer conn.finalize(stmt);
        db.bindInt(stmt, 1, approval_id) catch return .{ .resolved = false, .approved = false };
        if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return .{ .resolved = false, .approved = false };
        return .{
            .resolved = db.c.sqlite3_column_int(stmt, 1) != 0,
            .approved = db.c.sqlite3_column_int(stmt, 0) != 0,
        };
    }

    fn emitPermissionEvent(p: *ExternalPermCtx, status: []const u8, tool_call_json: []const u8) void {
        const allocator = p.sa.allocator;
        var out: std.Io.Writer.Allocating = .init(allocator);
        defer out.deinit();
        var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
        js.beginObject() catch return;
        js.objectField("task_id") catch return;
        js.write(p.task_id) catch return;
        js.objectField("cli") catch return;
        js.write(p.cli) catch return;
        js.objectField("status") catch return;
        js.write(status) catch return;
        js.objectField("tool_call") catch return;
        js.write(tool_call_json[0..@min(tool_call_json.len, 512)]) catch return;
        js.endObject() catch return;
        p.sa.recordEvent("external_agent_permission", out.written());
    }

    /// Tarjeta de aprobación de la cabina para un comando del agente externo:
    /// persiste en `approvals` (la cabina la lista) y espera la resolución.
    /// Tope de espera 10 min — el deadline del turno sigue mandando fuera.
    /// Devuelve true solo si el usuario aprobó.
    fn waitAcpApproval(p: *ExternalPermCtx, tool_call_json: []const u8) bool {
        const allocator = p.sa.allocator;
        const conn = p.sa.event_conn orelse p.sa.runtime;
        const desc = std.fmt.allocPrint(allocator, "agente externo {s} solicita permiso: {s}", .{ p.cli, tool_call_json[0..@min(tool_call_json.len, 400)] }) catch return false;
        defer allocator.free(desc);
        const aid = persistApprovalRequest(conn, .{
            .task_id = p.task_id,
            .description = desc,
            .command_prefix = external_agents.ACP_APPROVAL_PREFIX,
        }, p.sa.event_order_id, health.nowMillis(conn)) catch return false;
        emitPermissionEvent(p, "waiting", tool_call_json);
        defer emitPermissionEvent(p, "resolved", tool_call_json);
        const deadline = GetTickCount64() +| 10 * 60 * 1000;
        while (GetTickCount64() < deadline) {
            if (p.sa.cancel_token) |t| {
                if (t.isCancelled()) return false;
            }
            const res = queryApprovalState(conn, aid);
            if (res.resolved) return res.approved;
            Sleep(250);
        }
        return false;
    }

    /// Seam session/request_permission del cliente ACP → gobernanza E5.08:
    /// fs dentro del worktree → allow; fuera → deny siempre; comandos →
    /// checkPrefix (normal/accept_edits → tarjeta; bypass/autonomous → auto).
    fn acpPermissionBridge(raw: ?*anyopaque, _: []const u8, tool_call_json: []const u8, options_json: []const u8) anyerror!acp_client.PermissionOutcome {
        const p: *ExternalPermCtx = @ptrCast(@alignCast(raw orelse return .cancelled));
        const allocator = p.sa.allocator;
        const verdict = external_agents.classifyPermission(allocator, tool_call_json, p.sb.*, p.sa.permission_config);
        const allow = switch (verdict) {
            .allow => true,
            .deny => false,
            .ask => waitAcpApproval(p, tool_call_json),
        };
        const opt = external_agents.pickOption(allocator, options_json, allow) orelse {
            emitPermissionEvent(p, if (allow) "no_allow_option" else "rejected", tool_call_json);
            return .cancelled;
        };
        defer allocator.free(opt);
        p.last_opt.clearRetainingCapacity();
        p.last_opt.appendSlice(allocator, opt) catch return error.OutOfMemory;
        emitPermissionEvent(p, if (allow) "approved" else "denied", tool_call_json);
        return .{ .selected = p.last_opt.items };
    }

    /// Rama de despacho de un agente externo (E5.08). Mismo contrato que el
    /// worker nativo: devuelve WorkerResult y deja que los gates, la
    /// auditoría, el ship y el checkpoint/resume existentes lo procesen.
    /// El sandbox de la corrida se ancla al WORKTREE de la orden (no al
    /// sandbox/<task_id> del contrato) porque el agente edita archivos reales.
    fn dispatchExternalAgent(
        ctx: *FanoutContext,
        allocator: std.mem.Allocator,
        pt: planner.PlannedTask,
        meta: external_agents.AgentMeta,
        prov: []const u8,
        mdl: []const u8,
    ) worker_backend.WorkerResult {
        // Presupuesto de orden: reloj y turnos acumulados por despachos previos.
        if (@import("cli_quota.zig").dispatchBlock(allocator, if (ctx.sa.router) |r| r.catalog else null, ctx.sa.event_conn, ctx.sa.event_order_id, prov)) |quota_reason| {
            defer allocator.free(quota_reason);
            return externalFail(allocator, pt.id, quota_reason);
        }
        const lim = ctx.sa.external_limits;
        ctx.mutex.lock();
        const ms_used = ctx.external_ms_used;
        const turns_used = ctx.external_turns_used;
        ctx.mutex.unlock();
        const over_ms = lim.order_timeout_ms > 0 and ms_used >= lim.order_timeout_ms;
        const over_turns = lim.order_max_turns > 0 and turns_used >= lim.order_max_turns;
        if (over_ms or over_turns) {
            const msg = std.fmt.allocPrint(allocator, "limite de orden de agentes externos agotado (reloj {d}/{d} ms, turnos {d}/{d})", .{ ms_used, lim.order_timeout_ms, turns_used, lim.order_max_turns }) catch "limite de orden de agentes externos agotado";
            defer allocator.free(msg);
            return externalFail(allocator, pt.id, msg);
        }
        const eff_timeout = if (lim.order_timeout_ms > 0)
            @min(lim.task_timeout_ms, lim.order_timeout_ms -| ms_used)
        else
            lim.task_timeout_ms;
        const eff_turns = if (lim.order_max_turns > 0)
            @min(lim.task_max_turns, lim.order_max_turns -| turns_used)
        else
            lim.task_max_turns;

        // El worktree de la orden: cwd del proceso y raíz del diff/sandbox.
        var wt_buf: [4096]u8 = undefined;
        const worktree = workspace.effectiveRoot(&wt_buf);
        var wt_sb = sandbox.Sandbox.init(allocator, worktree) catch |e| {
            const msg = std.fmt.allocPrint(allocator, "sandbox del worktree: {s}", .{@errorName(e)}) catch "sandbox del worktree fallo";
            defer allocator.free(msg);
            return externalFail(allocator, pt.id, msg);
        };
        defer wt_sb.deinit();

        const prompt = buildExternalPrompt(allocator, ctx, pt) catch |e| {
            const msg = std.fmt.allocPrint(allocator, "prompt externo: {s}", .{@errorName(e)}) catch "prompt externo fallo";
            defer allocator.free(msg);
            return externalFail(allocator, pt.id, msg);
        };
        defer allocator.free(prompt);

        var ev_ctx = ExternalEventCtx{ .ctx = ctx, .task_id = pt.id };
        const inherit_personal_context = if (ctx.sa.router) |router|
            @import("external_context.zig").load(router.catalog) catch |e| {
                emitExternalFinished(ctx, pt.id, meta, prov, null, e);
                return externalFail(allocator, pt.id, @errorName(e));
            }
        else
            false;
        const sessions = @import("external_session.zig");
        var session_ctx = ExternalSessionCtx{ .ctx = ctx, .key = .{
            .order_id = ctx.outcome.order_id,
            .task_id = pt.id,
            .cli = meta.cli_id,
            .model = mdl,
            .worktree = worktree,
            .inherit_personal_context = inherit_personal_context,
        } };
        const can_resume = std.mem.eql(u8, meta.cli_id, "claude-code") or std.mem.eql(u8, meta.cli_id, "codex") or std.mem.eql(u8, meta.cli_id, "opencode");
        const session_id = if (can_resume and ctx.sa.resume_checkpoint != null) blk: {
            ctx.mutex.lock();
            defer ctx.mutex.unlock();
            break :blk sessions.load(allocator, ctx.sa.event_conn orelse ctx.sa.runtime, session_ctx.key) catch |e| return externalFail(allocator, pt.id, @errorName(e));
        } else null;
        defer if (session_id) |id| allocator.free(id);
        if (can_resume and ctx.sa.resume_checkpoint != null and session_id == null) {
            ExternalSessionCtx.call(&session_ctx, .restart, null, "no se pudo reanudar: sin sesion compatible con la politica de herencia; se relanza") catch |e| return externalFail(allocator, pt.id, @errorName(e));
        }
        var perm_ctx = ExternalPermCtx{ .sa = ctx.sa, .task_id = pt.id, .sb = &wt_sb, .cli = meta.cli_id };
        defer perm_ctx.last_opt.deinit(allocator);

        // An auditor returns the governed verdict contract, with no file writes.
        if (pt.task_type == .auditar and std.mem.eql(u8, prov, "agent:codex")) {
            const catalog_conn = if (ctx.sa.router) |r| r.catalog else return externalFail(allocator, pt.id, "catalogo de suscripcion no disponible");
            const audit_prompt = ctx.sa.systemPromptForTask(pt.department, pt.task_type, pt.description) catch |e| return externalFail(allocator, pt.id, @errorName(e));
            defer allocator.free(audit_prompt);
            emitExternalStarted(ctx, pt.id, meta, prov, null);
            const response = @import("external_completion.zig").completeWithSession(allocator, catalog_conn, prov, mdl, audit_prompt, prompt, worktree, if (ctx.cancel_token) |t| &t.flag else null, null, .{ .sink = .{ .ctx = &session_ctx, .callFn = ExternalSessionCtx.call }, .resume_session = session_id, .timeout_ms = eff_timeout, .event_sink = .{ .ctx = &ev_ctx, .callFn = externalEventSink }, .inherit_personal_context = inherit_personal_context }) catch |e| {
                emitExternalFinished(ctx, pt.id, meta, prov, null, e);
                return externalFail(allocator, pt.id, @errorName(e));
            };
            defer allocator.free(response);
            var response_ctx = struct {
                text: []const u8,
                fn call(ptr: *anyopaque, _: []const u8, _: []const u8) []const u8 {
                    const self: *@This() = @ptrCast(@alignCast(ptr));
                    return self.text;
                }
            }{ .text = response };
            var native = worker_backend.NativeWorker.init(audit_prompt);
            native.setLlmFn(&response_ctx, @TypeOf(response_ctx).call);
            const result = native.backend().run(allocator, pt, wt_sb) catch |e| {
                emitExternalFinished(ctx, pt.id, meta, prov, null, e);
                return externalFail(allocator, pt.id, @errorName(e));
            };
            if (ctx.sa.event_conn) |ec| @import("external_completion.zig").recordTextCall(allocator, ec, ctx.sa.event_order_id, pt.id, prov, mdl, result.success) catch |e| {
                result.deinit(allocator);
                return externalFail(allocator, pt.id, @errorName(e));
            };
            emitExternalFinished(ctx, pt.id, meta, prov, null, if (result.success) null else error.InvalidArtifact);
            return result;
        }

        // Un CLI externo ejecuta comandos y escribe con sus propios permisos:
        // el plan confirmado por un cliente MCP no es aprobación humana.
        if (ctx.sa.order_origin.requiresHumanApproval()) {
            return externalFail(allocator, pt.id, "agente externo requiere aprobacion humana en la cabina; las ordenes iniciadas por MCP no lo ejecutan");
        }

        // Codex conserva PATH y perfil, pero nunca recibe las claves API
        // del anfitrión. Los demás CLIs mantienen su guardia de facturación.
        var threaded = std.Io.Threaded.init(allocator, .{ .environ = @import("platform.zig").environ() });
        defer threaded.deinit();
        const cli_policy = @import("external_cli_policy.zig");
        var child_env: ?std.process.Environ.Map = null;
        defer if (child_env) |*env| env.deinit();
        if (std.mem.eql(u8, meta.cli_id, "codex")) {
            var parent_env = @import("platform.zig").environ().createMap(allocator) catch |e| {
                emitExternalStarted(ctx, pt.id, meta, prov, null);
                return externalFail(allocator, pt.id, @errorName(e));
            };
            defer parent_env.deinit();
            child_env = cli_policy.codexEnvironment(allocator, &parent_env) catch |e| {
                emitExternalStarted(ctx, pt.id, meta, prov, null);
                return externalFail(allocator, pt.id, @errorName(e));
            };
        }

        // P1-1 (R2 A1): el arranque se registra DESPUÉS de resolver el pin
        // para llevar la versión y la ruta de la CLI; si el pin falla, se
        // registra igual (sin CLI) antes del fallo, como hasta ahora.
        var chosen: ?external_registry.Pin = null;
        if (ctx.sa.external_catalog_json) |cat| {
            const catalog_conn = if (ctx.sa.router) |router| router.catalog else {
                emitExternalStarted(ctx, pt.id, meta, prov, null);
                return externalFail(allocator, pt.id, "external catalog unavailable");
            };
            chosen = (if (child_env != null and ctx.sa.external_run_fn == null and ctx.sa.external_capture_fn == null)
                external_registry.revalidateCodexPin(allocator, catalog_conn, cat, mdl, threaded.io(), &child_env.?)
            else
                external_registry.resolvePin(allocator, catalog_conn, cat, prov, mdl)) catch |e| {
                emitExternalStarted(ctx, pt.id, meta, prov, null);
                const msg = std.fmt.allocPrint(allocator, "external model unavailable: {s}", .{@errorName(e)}) catch return externalFail(allocator, pt.id, "external model unavailable");
                defer allocator.free(msg);
                return externalFail(allocator, pt.id, msg);
            };
        } else if (ctx.sa.external_run_fn == null and ctx.sa.external_capture_fn == null) {
            emitExternalStarted(ctx, pt.id, meta, prov, null);
            return externalFail(allocator, pt.id, "external CLI detection unavailable; refresh models before dispatch");
        }
        defer if (chosen) |pin| pin.deinit(allocator);
        emitExternalStarted(ctx, pt.id, meta, prov, if (chosen) |*pin| pin else null);
        const run_fn = ctx.sa.external_run_fn orelse external_agents.defaultRun;
        var snapshot_diagnostic: headless_adapter.SnapshotDiagnostic = .{};
        // QA-B 2c: Orquestado y Colmena usan la cuenta elegida para la CLI y
        // rotan por cuota igual que Directo (cli_accounts.runWithSelected); la
        // rotación queda como evento de la tarea.
        var rotation = ExternalAccountRotation{ .ctx = ctx, .task_id = pt.id };
        var outcome = @import("cli_accounts.zig").runWithSelected(run_fn, ctx.sa.external_run_ctx, allocator, threaded.io(), pt, .{
            .meta = meta,
            .model = mdl,
            .exe_path = if (chosen) |pin| pin.exe else null,
            .zero_cost = if (chosen) |pin| pin.zero_cost else false,
            .detected_version = if (chosen) |pin| pin.version else null,
            .reasoning_effort = if (chosen) |pin| pin.effort else null,
            .worktree = worktree,
            .prompt = prompt,
            .timeout_ms = eff_timeout,
            .max_turns = eff_turns,
            .event_sink = .{ .ctx = &ev_ctx, .callFn = externalEventSink },
            .session_sink = if (can_resume) .{ .ctx = &session_ctx, .callFn = ExternalSessionCtx.call } else null,
            .resume_session = session_id,
            .permission_fn = acpPermissionBridge,
            .permission_ctx = &perm_ctx,
            // governedToolsCancelled desreferencia el ctx: sin token de orden
            // la seam queda ausente (null), nunca un puntero nulo dereferenciable.
            .is_cancelled_fn = if (ctx.cancel_token != null) governedToolsCancelled else null,
            .cancelled_ctx = if (ctx.cancel_token) |t| @as(?*anyopaque, @ptrCast(@constCast(t))) else null,
            .capture_fn = ctx.sa.external_capture_fn,
            .getenv = ctx.sa.external_getenv_fn,
            .snapshot_diagnostic = &snapshot_diagnostic,
            .inherit_personal_context = inherit_personal_context,
            .deny_shell = external_agents.denyShellFor(ctx.sa.permission_config.mode),
            .environ_map = if (child_env) |*env| env else null,
        }, wt_sb, if (ctx.sa.router) |router| router.catalog else null, if (child_env) |*env| env else null, ExternalAccountRotation.notify, &rotation) catch |e| {
            emitExternalFinishedDiagnostic(ctx, pt.id, meta, prov, null, e, if (snapshot_diagnostic.len > 0) snapshot_diagnostic.message() else null, &snapshot_diagnostic);
            // 10-nov (USUARIO-NUEVO A3): el motivo en lenguaje llano; el
            // diagnóstico técnico sigue en el evento de arriba.
            if (snapshot_diagnostic.len > 0) {
                const msg = std.fmt.allocPrint(allocator, "agente externo fallo: {s}", .{snapshot_diagnostic.message()}) catch return externalFail(allocator, pt.id, "sin memoria al describir el fallo");
                defer allocator.free(msg);
                return externalFail(allocator, pt.id, msg);
            }
            const plain = @import("external_context.zig").plainStartFailure(allocator, meta.display, e) catch return externalFail(allocator, pt.id, "sin memoria al describir el fallo");
            defer allocator.free(plain);
            return externalFail(allocator, pt.id, plain);
        };
        defer outcome.deinit(allocator);

        // Acumulado de orden + fila de consumo subscription + finished.
        ctx.mutex.lock();
        ctx.external_ms_used +|= outcome.duration_ms;
        ctx.external_turns_used +|= outcome.turns;
        ctx.mutex.unlock();
        if (ctx.sa.event_conn) |ec| {
            external_agents.recordSubscriptionUsage(ec, ctx.sa.event_order_id, pt.id, prov, mdl, outcome.prompt_tokens, outcome.completion_tokens);
        }
        emitExternalFinished(ctx, pt.id, meta, prov, &outcome, null);

        if (outcome.success) {
            // Mover los artefactos al WorkerResult (el resto se libera).
            const arts = outcome.artifacts;
            outcome.artifacts = &.{};
            return .{
                .task_id = allocator.dupe(u8, pt.id) catch "",
                .artifacts = arts,
                .success = true,
                .error_msg = allocator.dupe(u8, "") catch "",
                // E5.09: los artefactos del diff son archivos REALES del
                // worktree (rutas relativas a su raíz) — el llamador los
                // registra en su sitio, no copias aplanadas en orden-<id>.
                .worktree_root = allocator.dupe(u8, worktree) catch null,
            };
        }
        // Fallo honesto con la causa real (timeout / tope de turnos / exit).
        // cuando hubo proceso, el motivo incluye el código de
        // salida y la primera línea con contenido del detalle (stdout+stderr
        // mezclados en el modo headless): el chat y el ledger deben poder
        // decir QUÉ pasó, no solo que el agente «terminó sin éxito».
        var cause_owned: ?[]u8 = null;
        defer if (cause_owned) |c| allocator.free(c);
        var cause: []const u8 = "agente externo termino sin exito";
        if (outcome.timed_out) {
            cause = "timeout del limite de tarea del agente externo";
        } else if (outcome.turn_limited) {
            cause = "tope de turnos del agente externo alcanzado";
        } else {
            const first = firstContentLine(outcome.detail[0..@min(outcome.detail.len, 400)]);
            if (outcome.exit_code) |code| {
                cause_owned = if (first.len > 0)
                    std.fmt.allocPrint(allocator, "código de salida {d}: {s}", .{ code, first }) catch null
                else
                    std.fmt.allocPrint(allocator, "código de salida {d}", .{code}) catch null;
                if (cause_owned) |c| cause = c;
            } else if (first.len > 0) {
                cause = first;
            }
        }
        return externalFail(allocator, pt.id, cause);
    }

    /// D-C1 (E5.11): resuelve el modo de tools para el candidato EFECTIVO
    /// (provider, model) de una tarea. Las productoras candidatas abren el
    /// modo agéntico solo con `cap_tool_calls='yes'` medida en vivo
    /// (live_probe, foto fresca) — cualquier otra evidencia cae a `.none`
    /// y deja el evento `agentic_unavailable {modelo, motivo}`.
    fn resolveTaskToolMode(ctx: *FanoutContext, allocator: std.mem.Allocator, task_type: model_router.TaskType, task_id: []const u8, prov: []const u8, mdl: []const u8) TaskToolMode {
        var catalog_conn: ?db.Connection = null;
        defer if (catalog_conn) |*conn| conn.close();
        if (ctx.catalog_path) |cp| {
            if (cp.len > 0 and !std.mem.eql(u8, cp, ":memory:")) {
                catalog_conn = db.Connection.open(allocator, cp) catch null;
            }
        }
        const decision = decideTaskToolMode(catalog_conn, ctx.sa.now, task_type, prov, mdl);
        // El ajuste de pasos agénticos de la cabina también apaga el modo: en
        // 1 (su default) la orden corre por la vía de una sola llamada — es el
        // control de la comparación de E5.12 y la posición conservadora.
        if (decision.mode == .agentic and ctx.sa.max_agent_iterations <= 1) return .none;
        if (decision.motivo) |motivo| {
            ctx.mutex.lock();
            defer ctx.mutex.unlock();
            var out: std.Io.Writer.Allocating = .init(allocator);
            defer out.deinit();
            var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
            js.beginObject() catch {};
            js.objectField("task_id") catch {};
            js.write(task_id) catch {};
            js.objectField("modelo") catch {};
            var modelo_buf: [320]u8 = undefined;
            const modelo = std.fmt.bufPrint(&modelo_buf, "{s}/{s}", .{ prov, mdl }) catch mdl;
            js.write(modelo) catch {};
            js.objectField("motivo") catch {};
            js.write(motivo) catch {};
            js.endObject() catch {};
            ctx.sa.recordEvent("agentic_unavailable", out.written());
        }
        return decision.mode;
    }

    /// D-C1 (E5.11): prompt de sistema del modo agéntico — el rol del
    /// departamento + la declaración de las tools REALES que el ejecutor
    /// gobernado sirve y el contrato de `finish`. Sin esta declaración el
    /// modelo no sabe que las tools existen ni que la sesión solo se cierra
    /// llamando a `finish`.
    fn buildAgenticSystemPrompt(allocator: std.mem.Allocator, base: []const u8) ![]u8 {
        return std.fmt.allocPrint(allocator, "{s}\n\n[MODO AGÉNTICO — HERRAMIENTAS REALES SOBRE EL WORKTREE]\n" ++
            "Tienes herramientas reales, gobernadas y confinadas al worktree de la orden. Úsalas para trabajar de verdad; no escribas el entregable como texto de la respuesta.\n" ++
            "- read_file{{path, offset?, limit?}}: lee un archivo de texto del worktree.\n" ++
            "- list_dir{{path?, recursive?}}: lista un directorio.\n" ++
            "- grep_files{{pattern, path?, ignore_case?, max_results?}}: busca un texto literal en archivos.\n" ++
            "- write_file{{path, content}}: crea o sobrescribe un archivo de texto UTF-8 (content = contenido COMPLETO del archivo). Crea los directorios padre necesarios.\n" ++
            "- edit_file{{path, old, new}}: sustituye la ÚNICA aparición de `old` por `new` en un archivo existente (error si `old` aparece 0 o más de 1 vez — acota el ancla).\n" ++
            "- run_command{{exe, args, cwd?, background?}}: ejecuta un programa gobernado dentro del worktree (exe = nombre del ejecutable, args = array de strings, cwd opcional). Puede requerir aprobación. En la cabina de Windows usa background=true para ventanas, servidores o procesos que deben continuar después de la orden. Consulta con process_logs y detén con process_stop usando el identificador y la generación. Si un comando en primer plano vence, explica el corte y ofrece relanzarlo en segundo plano.\n" ++
            "- finish{{summary, files}}: OBLIGATORIA para cerrar la tarea. `summary` resume lo hecho; `files` lista las rutas relativas al worktree creadas o modificadas.\n" ++
            "Reglas innegociables: lee antes de editar; verifica con run_command cuando la tarea lo pida (por ejemplo correr los tests); y termina SIEMPRE con finish. Una respuesta sin llamada a finish no cuenta como trabajo entregado.\n", .{base});
    }

    /// D-C1 (E5.11): prompt de usuario del modo agéntico — la misma tarea,
    /// contrato, manifiesto y upstream del worker nativo, pero el cierre es
    /// la tool `finish` y los entregables son ARCHIVOS REALES del worktree,
    /// no un array JSON de transporte.
    fn buildAgenticUserPrompt(allocator: std.mem.Allocator, ctx: *FanoutContext, pt: planner.PlannedTask, effective_upstream: ?[]const u8) ![]u8 {
        var prompt = std.ArrayList(u8).empty;
        errdefer prompt.deinit(allocator);
        // La tarea va PRIMERO, imperativa — la misma lección medida con los
        // CLIs externos (E5.09): el rol por delante diluye la orden.
        try prompt.appendSlice(allocator, if (pt.task_type == .auditar) "AUDITORIA: lee los archivos del worktree y devuelve el contrato JSON [{field,content}]. El campo verdict empieza por PASS o FAIL con evidencia. No escribas archivos ni ejecutes comandos.\n" else "TAREA A COMPLETAR AHORA (produce los archivos reales en el worktree con las herramientas):\n");
        try prompt.appendSlice(allocator, pt.description);
        try prompt.appendSlice(allocator, if (pt.task_type == .auditar) "\n\nCONTRATO DE LA RESPUESTA JSON (field,content):\n" else "\n\nCONTRATO (entregables a producir como ARCHIVOS REALES dentro del worktree):\n");
        for (pt.contract_fields) |cf| {
            const line = if (cf.value) |value|
                try std.fmt.allocPrint(allocator, "  - {s}: {s} (required={any}, value={s})\n", .{ cf.name, @tagName(cf.field_type), cf.required, value })
            else
                try std.fmt.allocPrint(allocator, "  - {s}: {s} (required={any})\n", .{ cf.name, @tagName(cf.field_type), cf.required });
            defer allocator.free(line);
            try prompt.appendSlice(allocator, line);
        }
        if (ctx.plan_manifest) |pm| {
            try prompt.appendSlice(allocator, "\n[PLAN DE LA ORDEN — OTRAS TAREAS DE ESTA MISMA ORDEN]\n");
            try prompt.appendSlice(allocator, "Eres uno de varios agentes trabajando en la MISMA orden. Mantén nombres de archivos, módulos, funciones y símbolos EXACTAMENTE CONSISTENTES con las demás tareas: si otra tarea implementa un módulo, usa EXACTAMENTE ese nombre de archivo y esos nombres (no inventes variantes). Escribe SOLAMENTE los archivos asignados a ESTA tarea.\n");
            try prompt.appendSlice(allocator, pm);
            try prompt.appendSlice(allocator, "\n");
        }
        if (effective_upstream) |uc| {
            try prompt.appendSlice(allocator, "\n[ARCHIVOS YA CREADOS POR TAREAS PREVIAS DE ESTA ORDEN]\n");
            try prompt.appendSlice(allocator, "Estos archivos YA existen en el proyecto. Referencia EXACTAMENTE estos nombres de archivo y los nombres de funciones/clases/símbolos que aparecen abajo. NO inventes nombres distintos ni asumas otra interfaz.\n");
            try prompt.appendSlice(allocator, uc);
            try prompt.appendSlice(allocator, "\n");
        }
        if (ctx.repo_map_text) |mt| {
            try prompt.appendSlice(allocator, "\n[MAPA DEL REPOSITORIO — archivos ordenados por relevancia para esta orden; cada línea es `ruta` seguida de `  símbolo:línea`]\n");
            try prompt.appendSlice(allocator, mt);
            try prompt.appendSlice(allocator, "[FIN MAPA DEL REPOSITORIO]\n");
        }
        try prompt.appendSlice(allocator, "\nCuando el trabajo esté hecho en el worktree, llama a la herramienta `finish` con el resumen y la lista de archivos creados o modificados.\n");
        return prompt.toOwnedSlice(allocator);
    }

    /// D-C1 (E5.11): una tarea productora en modo agéntico. El modelo opera
    /// con las tools gobernadas sobre el worktree y cierra con `finish`; los
    /// artefactos salen del DIFF REAL del worktree (la misma fuente que los
    /// agentes externos de E5.09) — nunca de lo que el modelo diga que
    /// escribió. Sin `finish` la tarea queda `incomplete`, jamás `done`.
    fn runAgenticTask(
        ctx: *FanoutContext,
        allocator: std.mem.Allocator,
        pt: planner.PlannedTask,
        llm: *live_worker.LiveLlm,
        system_prompt: []const u8,
        effective_upstream: ?[]const u8,
    ) worker_backend.WorkerResult {
        var wt_buf: [4096]u8 = undefined;
        const worktree = workspace.effectiveRoot(&wt_buf);
        var wt_sb = sandbox.Sandbox.init(allocator, worktree) catch |e| {
            const msg = std.fmt.allocPrint(allocator, "sandbox del worktree: {s}", .{@errorName(e)}) catch "sandbox del worktree fallo";
            defer allocator.free(msg);
            return externalFail(allocator, pt.id, msg);
        };
        defer wt_sb.deinit();

        // Commit base ANTES de que la sesión toque el worktree: el diff de
        // artefactos se mide contra este punto (misma semántica que el
        // adaptador headless). La captura es la seam de siempre — producción
        // = git real con guardia anti-prompt, tests inyectan una.
        const capture = ctx.sa.external_capture_fn orelse headless_adapter.defaultCapture;
        var threaded = std.Io.Threaded.init(allocator, .{ .environ = @import("platform.zig").environ() });
        defer threaded.deinit();
        var baseline = headless_adapter.captureArtifactBaseline(allocator, threaded.io(), capture, worktree, null) catch |e| {
            const msg = std.fmt.allocPrint(allocator, "línea base del espacio: {s}", .{@errorName(e)}) catch "línea base del espacio falló";
            defer allocator.free(msg);
            return externalFail(allocator, pt.id, msg);
        };
        defer baseline.deinit(allocator);

        const sys = buildAgenticSystemPrompt(allocator, system_prompt) catch |e| {
            const msg = std.fmt.allocPrint(allocator, "prompt de sistema agéntico: {s}", .{@errorName(e)}) catch "prompt de sistema agéntico fallo";
            defer allocator.free(msg);
            return externalFail(allocator, pt.id, msg);
        };
        defer allocator.free(sys);
        const user_prompt = buildAgenticUserPrompt(allocator, ctx, pt, effective_upstream) catch |e| {
            const msg = std.fmt.allocPrint(allocator, "prompt agéntico: {s}", .{@errorName(e)}) catch "prompt agéntico fallo";
            defer allocator.free(msg);
            return externalFail(allocator, pt.id, msg);
        };
        defer allocator.free(user_prompt);

        // La respuesta final es prosa — la señal de cumplimiento la lleva
        // `last_agentic_finished` (la escribió la tool `finish` del ejecutor).
        const agentic_call = ctx.sa.agentic_run_fn orelse defaultAgenticRun;
        const final_text = agentic_call(ctx.sa.agentic_run_ctx, llm, sys, user_prompt);
        _ = final_text;

        if (!llm.last_agentic_finished) {
            const summary_state: []const u8 = if (llm.last_dispatch_cancelled)
                "cancelada"
            else
                "terminó sin llamar a `finish`";
            const msg = std.fmt.allocPrint(allocator, "sesión agéntica {s}: la tarea queda INCOMPLETE — sin finish no hay entrega", .{summary_state}) catch "sesión agéntica incompleta";
            defer allocator.free(msg);
            var res = externalFail(allocator, pt.id, msg);
            res.incomplete = true;
            return res;
        }

        // Artefactos = diff del worktree contra el commit base — la evidencia
        // real, no la declaración del modelo en finish.files.
        const arts = headless_adapter.collectArtifactChanges(allocator, threaded.io(), capture, worktree, baseline, wt_sb) catch |e| {
            const msg = std.fmt.allocPrint(allocator, "diff de artefactos agénticos: {s}", .{@errorName(e)}) catch "diff de artefactos agénticos fallo";
            defer allocator.free(msg);
            return externalFail(allocator, pt.id, msg);
        };
        errdefer {
            for (arts) |*a| a.deinit(allocator);
            allocator.free(arts);
        }

        // La declaración del modelo queda registrada como evento — sirve para
        // contrastar lo que dice haber hecho con lo que el diff muestra.
        {
            ctx.mutex.lock();
            defer ctx.mutex.unlock();
            var out: std.Io.Writer.Allocating = .init(allocator);
            defer out.deinit();
            var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
            js.beginObject() catch {};
            js.objectField("task_id") catch {};
            js.write(pt.id) catch {};
            js.objectField("summary") catch {};
            js.write(llm.last_agentic_summary orelse "") catch {};
            js.objectField("files") catch {};
            js.beginArray() catch {};
            for (llm.last_agentic_files) |f| js.write(f) catch {};
            js.endArray() catch {};
            js.objectField("diff_files") catch {};
            js.write(arts.len) catch {};
            js.endObject() catch {};
            ctx.sa.recordEvent("agentic_finish", out.written());
        }

        return .{
            .task_id = allocator.dupe(u8, pt.id) catch "",
            .artifacts = arts,
            .success = true,
            .error_msg = allocator.dupe(u8, "") catch "",
            // Los artefactos del diff son archivos REALES del worktree (rutas
            // relativas a su raíz) — el llamador los registra en su sitio.
            .worktree_root = allocator.dupe(u8, worktree) catch null,
        };
    }

    /// E5.08: ids de catálogo de TODOS los modelos de los proveedores del
    /// mismo fabricante (auditoría cruzada — un agente `agent:*` no puede
    /// ser auditado por un modelo de su propio fabricante).
    fn catalogIdsOfManufacturer(self: *Superagent, man: external_agents.Manufacturer) ![]i64 {
        const router = self.router orelse return try self.allocator.alloc(i64, 0);
        var list = std.ArrayList(i64).empty;
        errdefer list.deinit(self.allocator);
        const stmt = try router.catalog.prepare("SELECT m.id,p.name,m.model_name FROM models m JOIN providers p ON m.provider_id=p.id");
        defer router.catalog.finalize(stmt);
        while (true) {
            const rc = db.c.sqlite3_step(stmt);
            if (rc == db.c.SQLITE_DONE) break;
            if (rc != db.c.SQLITE_ROW) return error.StepFailed;
            const prov = std.mem.span(db.c.sqlite3_column_text(stmt, 1));
            const model = std.mem.span(db.c.sqlite3_column_text(stmt, 2));
            const candidate_man = external_agents.modelManufacturer(prov, model);
            if (man == .unknown or candidate_man == .unknown or man == candidate_man)
                try list.append(self.allocator, db.c.sqlite3_column_int64(stmt, 0));
        }
        return list.toOwnedSlice(self.allocator);
    }
    // ── Persistencia (parámetros enlazados SIEMPRE; nunca interpolación) ──

    fn insertOrder(self: *Superagent, project_id: []const u8, prompt: []const u8, status: []const u8) !i64 {
        return insertOrderRow(self.runtime, project_id, prompt, status, self.now);
    }

    /// Inserta la fila de una orden y devuelve su rowid. Pública para que el
    /// submit async reserve la fila ANTES de planificar.
    pub fn insertOrderRow(conn: db.Connection, project_id: []const u8, prompt: []const u8, status: []const u8, now: i64) !i64 {
        const stmt = try conn.prepare("INSERT INTO orders (project_id, user_prompt, status, created_at) VALUES (?, ?, ?, ?)");
        defer conn.finalize(stmt);
        try db.bindText(stmt, 1, project_id);
        try db.bindText(stmt, 2, prompt);
        try db.bindText(stmt, 3, status);
        try db.bindInt(stmt, 4, now);
        if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE) return error.ExecFailed;
        return db.c.sqlite3_last_insert_rowid(conn.db);
    }

    /// E5.18: pub para que el runner de best-of-N clone el plan aprobado en
    /// una fila por candidata (sus tareas quedan trazadas por separado).
    pub fn insertPlan(self: *Superagent, order_id: i64, understanding: []const u8, answers: []const planner.ClarificationAnswer) !i64 {
        const clarifications_json = try answersToJson(self.allocator, answers);
        defer self.allocator.free(clarifications_json);
        const stmt = try self.runtime.prepare("INSERT INTO plans (order_id, understanding, clarifications_json, approved, created_at) VALUES (?, ?, ?, 0, ?)");
        defer self.runtime.finalize(stmt);
        try db.bindInt(stmt, 1, order_id);
        try db.bindText(stmt, 2, understanding);
        try db.bindText(stmt, 3, clarifications_json);
        try db.bindInt(stmt, 4, self.now);
        if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE) return error.ExecFailed;
        return db.c.sqlite3_last_insert_rowid(self.runtime.db);
    }

    fn insertContract(self: *Superagent, plan_id: i64, pt: planner.PlannedTask) !i64 {
        const interface_spec = try contractFieldsToJson(self.allocator, pt.contract_fields);
        defer self.allocator.free(interface_spec);
        const depends_json = try stringsToJson(self.allocator, pt.depends_on);
        defer self.allocator.free(depends_json);
        const stmt = try self.runtime.prepare("INSERT INTO contracts (plan_id, name, interface_spec, consumers_json, producers_json) VALUES (?, ?, ?, ?, ?)");
        defer self.runtime.finalize(stmt);
        try db.bindInt(stmt, 1, plan_id);
        try db.bindText(stmt, 2, pt.id);
        try db.bindText(stmt, 3, interface_spec);
        try db.bindText(stmt, 4, depends_json);
        try db.bindText(stmt, 5, "[]");
        if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE) return error.ExecFailed;
        return db.c.sqlite3_last_insert_rowid(self.runtime.db);
    }

    fn insertTask(self: *Superagent, plan_id: i64, pt: planner.PlannedTask, contract_id: i64, model_id: ?i64) !void {
        const stmt = try self.runtime.prepare("INSERT INTO tasks (plan_id, department, task_type, description, contract_id, assigned_model_id, status, created_at) VALUES (?, ?, ?, ?, ?, ?, 'planned', ?)");
        defer self.runtime.finalize(stmt);
        try db.bindInt(stmt, 1, plan_id);
        try db.bindText(stmt, 2, pt.department);
        try db.bindText(stmt, 3, pt.task_type.toText());
        try db.bindText(stmt, 4, pt.description);
        try db.bindInt(stmt, 5, contract_id);
        if (model_id) |mid| {
            try db.bindInt(stmt, 6, mid);
        } else {
            if (db.c.sqlite3_bind_null(stmt, 6) != db.c.SQLITE_OK) return error.BindFailed;
        }
        try db.bindInt(stmt, 7, self.now);
        if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE) return error.ExecFailed;
    }

    /// TERMINAL-STATE-DESIGN-2026-07-12 (P0 cierre): guardado contra pisar un
    /// terminal ya comprometido — una escritura no-terminal (running, clarifying,
    /// awaiting_approval, incluso un "failed" temprano de processOrder) nunca debe
    /// ganarle a done/failed/rejected/cancelled. Si la orden ya es terminal, el
    /// UPDATE afecta 0 filas y esto es un no-op silencioso (SQLITE_DONE de todos
    /// modos), no un error: mismo contrato que antes para todos los call-sites.
    fn updateOrderStatus(self: *Superagent, order_id: i64, status: []const u8) !void {
        const stmt = try self.runtime.prepare(
            "UPDATE orders SET status = ? WHERE id = ? AND status NOT IN ('done','failed','rejected','cancelled')",
        );
        defer self.runtime.finalize(stmt);
        try db.bindText(stmt, 1, status);
        try db.bindInt(stmt, 2, order_id);
        if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE) return error.ExecFailed;
    }

    fn updatePlanTasksStatus(self: *Superagent, plan_id: i64, status: []const u8) !void {
        const stmt = try self.runtime.prepare("UPDATE tasks SET status = ? WHERE plan_id = ?");
        defer self.runtime.finalize(stmt);
        try db.bindText(stmt, 1, status);
        try db.bindInt(stmt, 2, plan_id);
        if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE) return error.ExecFailed;
    }

    fn markPlanApproved(self: *Superagent, plan_id: i64) !void {
        const stmt = try self.runtime.prepare("UPDATE plans SET approved = 1 WHERE id = ?");
        defer self.runtime.finalize(stmt);
        try db.bindInt(stmt, 1, plan_id);
        if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE) return error.ExecFailed;
    }

    fn buildReport(self: *Superagent, outcome: *OrderOutcome, completed: usize, failed: usize, integrated: usize, rejected: usize, saved: []const []const u8, audit_pass: usize, audit_fail: usize, audit_unavailable: usize, corrected: usize, concurrency_peak: usize, restored: usize, semantic_ran: bool, semantic_note: ?[]const u8, screenshot_path: ?[]const u8) ![]u8 {
        var out = std.ArrayList(u8).empty;
        errdefer out.deinit(self.allocator);
        const a = self.allocator;
        try out.appendSlice(a, "=== Reporte consolidado del superagente ===\n");
        const head = try std.fmt.allocPrint(a, "Orden #{d} (plan #{d})\n", .{ outcome.order_id, outcome.plan_id orelse -1 });
        defer a.free(head);
        try out.appendSlice(a, head);
        try out.appendSlice(a, "Entendimiento: ");
        try out.appendSlice(a, outcome.plan.understanding);
        try out.appendSlice(a, "\n\nTareas:\n");
        for (outcome.plan.tasks) |pt| {
            const asg = findAssignment(outcome.assignments, pt.id);
            const line = try std.fmt.allocPrint(a, "  [{s}] {s} ({s}) → modelo: {s}/{s} free={any} sandbox=sandbox/{s}\n", .{
                pt.id,                                    pt.description,                        pt.task_type.toText(),
                if (asg) |x| x.provider_name else "none", if (asg) |x| x.model_name else "none", if (asg) |x| x.is_free else false,
                pt.id,
            });
            defer a.free(line);
            try out.appendSlice(a, line);
        }
        // BUG-1: si se perdieron eventos, el reporte lo DICE. Una traza
        // incompleta que se lee como «no paso nada» es peor que no tenerla.
        const perdidos = self.eventosPerdidos();
        const stats = if (perdidos == 0)
            try std.fmt.allocPrint(a, "\nEjecución: {d} completadas, {d} fallidas.\nIntegración por contrato: {d} integradas, {d} rechazadas.\nParalelismo máximo (tareas simultáneas): {d}\n", .{ completed, failed, integrated, rejected, concurrency_peak })
        else
            try std.fmt.allocPrint(a, "\nEjecución: {d} completadas, {d} fallidas.\nIntegración por contrato: {d} integradas, {d} rechazadas.\nParalelismo máximo (tareas simultáneas): {d}\nOJO: {d} evento(s) NO llegaron a la base — la traza de esta orden esta INCOMPLETA.\n", .{ completed, failed, integrated, rejected, concurrency_peak, perdidos });
        defer a.free(stats);
        try out.appendSlice(a, stats);
        // CHECKPOINT-T2: el reporte declara honestamente que esta orden se
        // reanudó — cuántas tareas se saltaron por ya completadas y cuántas
        // se re-ejecutaron enteras.
        if (restored > 0) {
            const resume_line = try std.fmt.allocPrint(a, "Reanudación: {d} tarea(s) restauradas desde checkpoint (no re-ejecutadas); el resto corrió completo.\n", .{restored});
            defer a.free(resume_line);
            try out.appendSlice(a, resume_line);
        }
        // SEMANTIC-GATE-T3: el reporte declara el veredicto del gate — PASS
        // cuando el observable se cumplió, FAIL con la diferencia concreta.
        if (semantic_ran and semantic_note == null) {
            try out.appendSlice(a, "Gate semántico: PASS — el observable declarado se cumple.\n");
        }
        if (semantic_note) |note| {
            try out.appendSlice(a, "Gate semántico: FAIL — el observable declarado no se cumple:\n");
            try out.appendSlice(a, note);
            try out.appendSlice(a, "\n");
        }
        if (saved.len > 0) {
            try out.appendSlice(a, "\nProgramas guardados (workspace):\n");
            for (saved) |p| {
                const line = try std.fmt.allocPrint(a, "  - {s}\n", .{p});
                defer a.free(line);
                try out.appendSlice(a, line);
            }
        }
        if (outcome.discovery_needed.len > 0 or outcome.discovery_missing.len > 0) {
            try out.appendSlice(a, "Herramientas: ");
            const tools = try std.fmt.allocPrint(a, "necesarias={d}, faltantes={d}\n", .{ outcome.discovery_needed.len, outcome.discovery_missing.len });
            defer a.free(tools);
            try out.appendSlice(a, tools);
        }
        const audit_stats = try std.fmt.allocPrint(a, "\nAuto-auditoría: {d} pasadas, {d} falladas, {d} corregidas.\n", .{ audit_pass, audit_fail, corrected });
        defer a.free(audit_stats);
        try out.appendSlice(a, audit_stats);
        // AUDIT-UNAVAILABLE-P0: el reporte dice cuando el auditor no llegó a
        // revisar — la orden no está aprobada ni fallida, está SIN AUDITAR.
        if (audit_unavailable > 0) {
            const line = try std.fmt.allocPrint(a, "Auditoría de modelos: {d} tarea(s) de auditoría sin veredicto usable — la orden queda SIN AUDITAR (la entrega sigue bloqueada hasta un reintento manual).\n", .{audit_unavailable});
            defer a.free(line);
            try out.appendSlice(a, line);
        }
        if (screenshot_path) |sp| {
            const ss_line = try std.fmt.allocPrint(a, "\nAutoevaluación visual: {s}\n", .{sp});
            defer a.free(ss_line);
            try out.appendSlice(a, ss_line);
        }
        try out.appendSlice(a, "\nPróximos pasos:\n");
        try out.appendSlice(a, "  - Re-validación y reporte final consolidado.\n");
        try out.appendSlice(a, "Evidencias: .verifications/ zig build test, audit_ledger.\n");
        return out.toOwnedSlice(a);
    }
};

const CommandKind = enum {
    script,
    go_run,
    zig_build,
    c_build,
    cpp_build,
};

const CommandHint = struct {
    exe: []const u8,
    kind: CommandKind,
};

/// P-EXEC-2: comando crudo parseado desde un string (e.g. `python -c "print(2+2)"`).
/// Posee la memoria de exe y args; debe llamarse deinit() al terminar.
const ParsedCommand = struct {
    exe: []const u8,
    args: []const []const u8,
    alloc: std.mem.Allocator,

    fn deinit(self: *ParsedCommand) void {
        self.alloc.free(self.exe);
        for (self.args) |a| self.alloc.free(a);
        self.alloc.free(self.args);
    }
};

/// P09-T3: Extrae la URL del resultado JSON de od_status.
/// El formato es {"content":"{\"running\":true,\"url\":\"http://...\"}","is_error":false}.
/// Devuelve null si no se encuentra URL.
fn extractOdUrl(allocator: std.mem.Allocator, json_str: []const u8) !?[]const u8 {
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, json_str, .{}) catch return null;
    defer parsed.deinit();
    const root = parsed.value;
    if (root != .object) return null;
    const content_val = root.object.get("content") orelse return null;
    if (content_val != .string) return null;
    var content_parsed = std.json.parseFromSlice(std.json.Value, allocator, content_val.string, .{}) catch return null;
    defer content_parsed.deinit();
    const content_root = content_parsed.value;
    if (content_root != .object) return null;
    if (content_root.object.get("url")) |url_val| {
        if (url_val == .string and url_val.string.len > 0) {
            return try allocator.dupe(u8, url_val.string);
        }
    }
    return null;
}

/// P-EXEC-3: extrae el comando crudo de la description de una tarea `ejecutar`.
/// El formato esperado es "Ejecutar <comando>" (producido por deterministicExecutePlan
/// o por el LLM siguiendo el system prompt). Devuelve null si no coincide.
/// UI-ACTION: el allowlist vive en `executor.zig` (única fuente; lo comparten
/// la tarea `ui`, la tool `ui_action` y `da_ui_action_request`).
const UI_MAX_FIELD_BYTES: usize = 256;

/// Construye el payload JSON de un evento `ui_action` desde los contract_fields
/// de una tarea `ui`. `action` es obligatoria y debe pasar el allowlist; los
/// args conocidos (theme/view/session_id/text) se copian con tope de tamaño.
/// Devuelve null si la tarea no declara una acción válida — el caller marca la
/// tarea como fallida (honesto, nunca se ejecuta algo no listado).
fn buildUiActionPayload(allocator: std.mem.Allocator, pt: planner.PlannedTask) ?[]u8 {
    var action: ?[]const u8 = null;
    var theme: ?[]const u8 = null;
    var view: ?[]const u8 = null;
    var session_id: ?[]const u8 = null;
    var text: ?[]const u8 = null;
    for (pt.contract_fields) |f| {
        const v = f.value orelse continue;
        if (v.len == 0 or v.len > UI_MAX_FIELD_BYTES) continue;
        if (std.mem.eql(u8, f.name, "action")) {
            action = v;
        } else if (std.mem.eql(u8, f.name, "theme")) {
            theme = v;
        } else if (std.mem.eql(u8, f.name, "view")) {
            view = v;
        } else if (std.mem.eql(u8, f.name, "session_id")) {
            session_id = v;
        } else if (std.mem.eql(u8, f.name, "text")) {
            text = v;
        }
    }
    const act = action orelse return null;
    if (!executor.uiActionAllowed(act)) return null;

    var out: std.Io.Writer.Allocating = .init(allocator);
    defer out.deinit();
    var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
    js.beginObject() catch return null;
    js.objectField("action") catch return null;
    js.write(act) catch return null;
    js.objectField("task_id") catch return null;
    js.write(pt.id) catch return null;
    js.objectField("args") catch return null;
    js.beginObject() catch return null;
    if (theme) |v| {
        js.objectField("theme") catch return null;
        js.write(v) catch return null;
    }
    if (view) |v| {
        js.objectField("view") catch return null;
        js.write(v) catch return null;
    }
    if (session_id) |v| {
        js.objectField("session_id") catch return null;
        js.write(v) catch return null;
    }
    if (text) |v| {
        js.objectField("text") catch return null;
        js.write(v) catch return null;
    }
    js.endObject() catch return null;
    js.endObject() catch return null;
    return allocator.dupe(u8, out.written()) catch null;
}

fn extractCommandFromDesc(desc: []const u8) ?[]const u8 {
    const prefix = "Ejecutar ";
    if (std.mem.startsWith(u8, desc, prefix)) {
        const cmd = std.mem.trim(u8, desc[prefix.len..], " \t\r\n");
        if (cmd.len > 0) return cmd;
    }
    return null;
}

/// P-EXEC-5: extrae el comando del contract_field `command` (valor ya resuelto).
/// Devuelve null si la tarea no tiene ese campo o su value es null.
fn extractCommandFromContract(fields: []const planner.ContractField) ?[]const u8 {
    return extractContractField(fields, "command");
}

/// Cualquier contract_field por nombre; el mismo parser sirve para `command`
/// y para el `target` heredado que los planners antiguos rellenaban con la
/// línea de comando completa.
fn extractContractField(fields: []const planner.ContractField, name: []const u8) ?[]const u8 {
    for (fields) |f| {
        if (std.mem.eql(u8, f.name, name)) {
            if (f.value) |v| {
                const t = std.mem.trim(u8, v, " \t\r\n");
                if (t.len > 0) return t;
            }
        }
    }
    return null;
}

/// El worker materializa su respuesta `[{field,content}]` como artifacts:
/// `art.path` es el nombre del campo. Los modelos que siguen el contrato al
/// pie de la letra devuelven `command` con la línea completa (orden #527:
/// Cohere lo emitió y el fallback lo ignoraba porque solo miraba `target`).
fn extractArtifactField(artifacts: []const worker_backend.Artifact, name: []const u8) ?[]const u8 {
    for (artifacts) |art| {
        if (std.mem.eql(u8, art.path, name)) {
            const t = std.mem.trim(u8, art.content, " \t\r\n");
            if (t.len > 0) return t;
        }
    }
    return null;
}

/// Exes que invocados SIN argumentos abren un REPL o shell interactivo: el
/// proceso imprime su banner, lee un stdin ya cerrado y sale con código 0
/// sin haber ejecutado nada — el falso éxito medido en la orden #527
/// (`powershell` pelado → banner → audit PASS). Un modelo que emite el exe
/// solo no está pidiendo un shell interactivo: está perdiendo el comando.
fn isInteractiveWithoutArgs(exe: []const u8, args_len: usize) bool {
    if (args_len != 0) return false;
    const base = executor.stripExe(executor.basename(exe));
    const repls = [_][]const u8{ "powershell", "pwsh", "cmd", "bash", "sh", "python", "py", "node", "ruby", "perl" };
    for (repls) |r| {
        if (std.ascii.eqlIgnoreCase(base, r)) return true;
    }
    return false;
}

/// Primer token del string (sin espacios iniciales).
fn firstToken(raw: []const u8) []const u8 {
    var i: usize = 0;
    while (i < raw.len and (raw[i] == ' ' or raw[i] == '\t')) i += 1;
    const start = i;
    while (i < raw.len and raw[i] != ' ' and raw[i] != '\t') i += 1;
    return raw[start..i];
}

/// Cmdlet de PowerShell: token `Verbo-Nombre` con guion interno y letras a
/// ambos lados (Get-ChildItem, Write-Output, Start-Sleep…).
fn isCmdletToken(tok: []const u8) bool {
    if (tok.len < 4) return false;
    const dash = std.mem.indexOfScalar(u8, tok, '-') orelse return false;
    if (dash == 0 or dash == tok.len - 1) return false;
    const alpha = struct {
        fn f(s: []const u8) bool {
            for (s) |c| {
                if (!std.ascii.isAlphabetic(c)) return false;
            }
            return s.len > 0;
        }
    }.f;
    return alpha(tok[0..dash]) and alpha(tok[dash + 1 ..]);
}

/// Decide si el string es un COMANDO DE SHELL que ningún parser de argv
/// respetaría (pipes, redirecciones, variables, cmdlets), y por tanto la
/// ruta correcta es envolverlo en un shell allowlisted.
///
/// Regla anti-prosa (orden #528): el planner puede volcar en `command` la
/// frase del usuario ("exactamente este comando de PowerShell y dime la
/// salida: 1..4 | ForEach-Object…"), que CONTIENE metacaracteres. Si el
/// primer token es una palabra alfabética sin guion y no es un ejecutable
/// allowlisted, el string es prosa que menciona un comando — no un comando —
/// y envolverlo solo produciría un error de sintaxis incomprensible.
fn looksLikeShellSyntax(raw: []const u8) bool {
    const tok = firstToken(raw);
    if (tok.len == 0) return false;
    // Prosa: palabra alfabética pura, sin guion, no allowlisted → no es comando.
    var all_alpha = true;
    for (tok) |c| {
        if (!std.ascii.isAlphabetic(c)) {
            all_alpha = false;
            break;
        }
    }
    if (all_alpha and !executor.isAllowlisted(executor.stripExe(executor.basename(tok)))) return false;
    // Cmdlet como primer token → shell seguro aunque no haya metacaracteres.
    if (isCmdletToken(tok)) return true;
    // Metacaracteres de shell en cualquier posición.
    if (std.mem.indexOfAny(u8, raw, "|><;&`$") != null) return true;
    if (std.mem.indexOf(u8, raw, "&&") != null or std.mem.indexOf(u8, raw, "||") != null) return true;
    return false;
}

/// Flags que introducen un script inline: tras ellos, TODO el resto de la
/// línea es UN argumento (el script). Trocearlo por comillas rompe los
/// scripts con comillas internas (orden #529: `powershell -Command
/// "1..4 | ForEach-Object { Write-Output ("tick " + $_) }"` quedó
/// fragmentado → MissingEndParenthesisInExpression).
const SCRIPT_FLAGS = [_][]const u8{ "-Command", "-c", "/c", "-e", "--eval", "-EncodedCommand" };

/// Parser especializado para `shell -Command "<script>"`: exe + args previos
/// + flag + script ENTERO como un único arg. Las comillas externas del script
/// son sintaxis del shell — se quitan; las internas pertenecen al script y se
/// conservan intactas para que appendArg las reescape bien a CreateProcess.
fn parseShellScriptInvocation(allocator: std.mem.Allocator, raw: []const u8) !?ParsedCommand {
    const exe_tok = firstToken(raw);
    if (exe_tok.len == 0) return null;
    if (!executor.isAllowlisted(executor.stripExe(executor.basename(exe_tok)))) return null;

    // Recorrer tokens hasta encontrar el flag de script. Lo que haya antes
    // (p. ej. -NoProfile) se conserva como args; lo que siga es el script.
    var args = std.ArrayList([]const u8).empty;
    var flag_seen = false;
    errdefer {
        for (args.items) |a| allocator.free(a);
        args.deinit(allocator);
    }
    var i: usize = exe_tok.len;
    while (i < raw.len) {
        while (i < raw.len and (raw[i] == ' ' or raw[i] == '\t')) i += 1;
        if (i >= raw.len) break;
        const start = i;
        while (i < raw.len and raw[i] != ' ' and raw[i] != '\t') i += 1;
        const tok = raw[start..i];
        var is_script_flag = false;
        for (SCRIPT_FLAGS) |flag| {
            if (std.ascii.eqlIgnoreCase(tok, flag)) {
                is_script_flag = true;
                break;
            }
        }
        if (!is_script_flag) {
            try args.append(allocator, try allocator.dupe(u8, tok));
            continue;
        }
        flag_seen = true;
        // Tras el flag: el resto de la línea es el script, como UN arg.
        while (i < raw.len and (raw[i] == ' ' or raw[i] == '\t')) i += 1;
        if (i >= raw.len) {
            // `powershell -Command` a secas: mismo falso éxito que el REPL —
            // banner/EOF/exit 0 sin ejecutar nada. Sin script no hay orden.
            for (args.items) |a| allocator.free(a);
            args.deinit(allocator);
            return null;
        }
        try args.append(allocator, try allocator.dupe(u8, tok));
        var script = raw[i..];
        const exe_base = executor.stripExe(executor.basename(exe_tok));
        const is_powershell = std.ascii.eqlIgnoreCase(exe_base, "powershell") or
            std.ascii.eqlIgnoreCase(exe_base, "pwsh");
        var unescape = false;
        // Comillas EXTERNAS emparejadas: se quitan (son del shell). Las
        // comillas internas quedan dentro del script.
        if (script.len >= 2 and
            (script[0] == '"' or script[0] == '\'') and
            script[script.len - 1] == script[0])
        {
            // Los escapes `\"`/`\\` del contenido existían SOLO para sobrevivir
            // al quoting exterior que acabamos de quitar — hay que deshacerlos
            // (orden #529: PowerShell recibió `\"` literal → CommandNotFound).
            unescape = script[0] == '"';
            script = script[1 .. script.len - 1];
        }
        if (script.len == 0) {
            for (args.items) |a| allocator.free(a);
            args.deinit(allocator);
            return null;
        }
        var script_buf = std.ArrayList(u8).empty;
        errdefer script_buf.deinit(allocator);
        if (unescape and std.mem.indexOfScalar(u8, script, '\\') != null) {
            var s: usize = 0;
            while (s < script.len) : (s += 1) {
                if (script[s] == '\\' and s + 1 < script.len and
                    (script[s + 1] == '"' or script[s + 1] == '\\'))
                {
                    s += 1;
                }
                try script_buf.append(allocator, script[s]);
            }
        } else {
            try script_buf.appendSlice(allocator, script);
        }
        // PowerShell -Command devuelve exit 0 aunque el script falle con
        // errores NO terminantes (orden #530: CommandNotFoundException →
        // exit 0 → task_done + audit PASS = falso éxito). El patrón de CI
        // (GitHub Actions / Azure DevOps): ErrorActionPreference=Stop hace
        // que cualquier error termine con exit≠0 → veredicto honesto.
        if (is_powershell and
            std.mem.indexOf(u8, script_buf.items, "ErrorActionPreference") == null and
            std.mem.indexOf(u8, script_buf.items, "-ErrorAction") == null)
        {
            var guarded = std.ArrayList(u8).empty;
            errdefer guarded.deinit(allocator);
            try guarded.appendSlice(allocator, "$ErrorActionPreference='Stop'; ");
            try guarded.appendSlice(allocator, script_buf.items);
            script_buf.deinit(allocator);
            script_buf = guarded;
        }
        try args.append(allocator, try script_buf.toOwnedSlice(allocator));
        break;
    }
    // Sin flag de script esto no aplica: que lo resuelvan las rutas genéricas
    // (metacaracteres sueltos, wrap por sintaxis, anti-REPL…).
    if (!flag_seen) {
        for (args.items) |a| allocator.free(a);
        args.deinit(allocator);
        return null;
    }
    return ParsedCommand{
        .exe = try allocator.dupe(u8, exe_tok),
        .args = try args.toOwnedSlice(allocator),
        .alloc = allocator,
    };
}

/// El argv troceado contiene un metacarácter de shell SUELTO (`|`, `>`,
/// `&&`…): el modelo escribió sintaxis de shell, no argumentos — el parser
/// de argv los pasaría literales al proceso (orden #518: `ls` recibió `-3`
/// de `| head -3` como opción). La línea entera va al shell allowlisted.
fn hasLooseShellMetachars(args: []const []const u8) bool {
    for (args) |a| {
        if (a.len == 0) continue;
        if (a.len == 1 and std.mem.indexOfScalar(u8, "|><;&", a[0]) != null) return true;
        if (std.mem.eql(u8, a, "&&") or std.mem.eql(u8, a, "||")) return true;
    }
    return false;
}

/// Envuelve una línea de shell en `powershell -NoProfile -Command "<raw>"`:
/// el intérprete allowlisted que el modelo ya podía invocar a mano. El wrap
/// no crea un canal nuevo ni amplía privilegios — normaliza lo que el modelo
/// ya podía pedir, y la línea efectiva completa queda visible en los eventos.
fn wrapInShell(allocator: std.mem.Allocator, raw: []const u8) !ParsedCommand {
    const args = try allocator.alloc([]const u8, 3);
    args[0] = try allocator.dupe(u8, "-NoProfile");
    args[1] = try allocator.dupe(u8, "-Command");
    // ErrorActionPreference=Stop: sin ella, errores no terminantes dejan
    // exit 0 y el veredicto sería un falso éxito (ver parseShellScript…).
    args[2] = try std.fmt.allocPrint(allocator, "$ErrorActionPreference='Stop'; {s}", .{raw});
    return ParsedCommand{
        .exe = try allocator.dupe(u8, "powershell"),
        .args = args,
        .alloc = allocator,
    };
}

/// Convierte el STRING de comando que emitió el modelo (de cualquier fuente)
/// en un ParsedCommand ejecutable:
///   1. `parseRawCommand` — exe allowlisted + argv limpio (ruta segura).
///   2. Si el argv trae metacaracteres sueltos o el primer token no es
///      ejecutable pero hay sintaxis de shell real → wrap gobernado.
///   3. `powershell`/`python`… a pelo (sin args) → REPL vacío, falso éxito:
///      se rechaza aquí con error honesto en vez de correr un banner.
///   4. Prosa con un comando mencionado → null: el candidato se descarta y
///      el resolvedor prueba la siguiente fuente (orden #528).
fn commandToParsed(allocator: std.mem.Allocator, raw: []const u8) !?ParsedCommand {
    // `shell -Command "<script>"` primero: el script va entero como un arg,
    // nunca troceado por sus comillas internas.
    if (try parseShellScriptInvocation(allocator, raw)) |parsed| {
        var p = parsed;
        if (isInteractiveWithoutArgs(p.exe, p.args.len)) {
            p.deinit();
            return null;
        }
        return p;
    }
    if (parseRawCommand(allocator, raw) catch null) |parsed| {
        var p = parsed;
        if (isInteractiveWithoutArgs(p.exe, p.args.len)) {
            p.deinit();
            return null;
        }
        // `powershell -Command` a secas o con script vacío (`-Command ""`):
        // flag de script como último arg, o último arg vacío tras un flag —
        // mismo falso éxito que el REPL: nada que ejecutar.
        // SEC2 R6/H5: un comando permitido sin argumentos (`ls`, `git`, `zig`…)
        // no es un REPL ni un script vacio: no hay "ultimo argumento" que leer.
        if (p.args.len == 0) return p;
        const last = p.args[p.args.len - 1];
        if (last.len == 0) {
            p.deinit();
            return null;
        }
        for (SCRIPT_FLAGS) |flag| {
            if (std.ascii.eqlIgnoreCase(last, flag)) {
                p.deinit();
                return null;
            }
        }
        if (hasLooseShellMetachars(p.args)) {
            p.deinit();
            return try wrapInShell(allocator, raw);
        }
        return p;
    }
    if (!looksLikeShellSyntax(raw)) return null;
    return try wrapInShell(allocator, raw);
}

/// Resuelve el comando de una tarea `ejecutar` probando TODAS las fuentes en
/// orden de precedencia contractual y quedándose con la primera que produce
/// un ParsedCommand ejecutable:
///
///   1. contract_field `command` del planner (schema nuevo)
///   2. artifact `command` del worker (orden #527: Cohere lo emite bien)
///   3. prefijo "Ejecutar <cmd>" de la description
///   4. `target` (contract o artifact) cuando contiene un comando — los
///      planners antiguos y algunos workers rellenan el comando ahí
///
/// Un candidato que no parsea (prosa del usuario volcada en el contract —
/// orden #528 — o un REPL pelado) se DESCARTA y se prueba la siguiente
/// fuente: ninguna fuente gana por ser la primera con texto, gana la primera
/// ejecutable. Devuelve null cuando ninguna fuente produce comando — un
/// `target` que es path de archivo sigue yendo por governedExecute.
fn resolveTaskCommand(
    allocator: std.mem.Allocator,
    pt: planner.PlannedTask,
    artifacts: []const worker_backend.Artifact,
) !?ParsedCommand {
    const candidates = [_]?[]const u8{
        extractContractField(pt.contract_fields, "command"),
        extractArtifactField(artifacts, "command"),
        extractCommandFromDesc(pt.description),
        extractContractField(pt.contract_fields, "target"),
        extractArtifactField(artifacts, "target"),
    };
    for (candidates) |maybe_raw| {
        const raw = maybe_raw orelse continue;
        if (try commandToParsed(allocator, raw)) |parsed| return parsed;
    }
    return null;
}

/// Primer candidato textual disponible, para el mensaje de error honesto
/// cuando ninguna fuente produce un comando ejecutable.
fn firstCommandCandidate(
    pt: planner.PlannedTask,
    artifacts: []const worker_backend.Artifact,
) ?[]const u8 {
    const candidates = [_]?[]const u8{
        extractContractField(pt.contract_fields, "command"),
        extractArtifactField(artifacts, "command"),
        extractCommandFromDesc(pt.description),
        extractContractField(pt.contract_fields, "target"),
        extractArtifactField(artifacts, "target"),
    };
    for (candidates) |maybe_raw| {
        if (maybe_raw) |raw| return raw;
    }
    return null;
}

const renderCommandLine = executor.renderCommandLine;

/// P-EXEC-2: parsea un string como comando crudo (exe + args), manejando comillas.
/// Retorna null si el primer token no está en el ALLOWLIST del executor.
fn parseRawCommand(allocator: std.mem.Allocator, raw: []const u8) !?ParsedCommand {
    var tokens: std.ArrayList([]const u8) = .empty;
    defer {
        for (tokens.items) |t| allocator.free(t);
        tokens.deinit(allocator);
    }

    var i: usize = 0;
    while (i < raw.len) {
        while (i < raw.len and (raw[i] == ' ' or raw[i] == '\t')) i += 1;
        if (i >= raw.len) break;

        if (raw[i] == '"' or raw[i] == '\'') {
            const quote_char = raw[i];
            i += 1;
            const start = i;
            while (i < raw.len and raw[i] != quote_char) i += 1;
            const token = try allocator.dupe(u8, raw[start..i]);
            try tokens.append(allocator, token);
            if (i < raw.len) i += 1;
        } else {
            const start = i;
            while (i < raw.len and raw[i] != ' ' and raw[i] != '\t') i += 1;
            const token = try allocator.dupe(u8, raw[start..i]);
            try tokens.append(allocator, token);
        }
    }

    if (tokens.items.len == 0) return null;

    const base = executor.stripExe(executor.basename(tokens.items[0]));
    if (!executor.isAllowlisted(base)) return null;

    const exe = try allocator.dupe(u8, tokens.items[0]);
    const args = try allocator.alloc([]const u8, tokens.items.len - 1);
    for (tokens.items[1..], 0..) |t, idx| {
        args[idx] = try allocator.dupe(u8, t);
    }

    return ParsedCommand{
        .exe = exe,
        .args = args,
        .alloc = allocator,
    };
}

