const FILE_SHARE_READ: u32 = 0x00000001;
const OPEN_EXISTING: u32 = 3;
const INVALID_HANDLE_VALUE: std.os.windows.HANDLE = @ptrFromInt(~@as(usize, 0));
const NODE_GUARD_FILE_ATTRIBUTE_NORMAL: u32 = 0x80;

