}.GetFullPathNameA else @import("providers").posix_files.GetFullPathNameA;
const Sleep = @import("platform.zig").sleep;
const GetTickCount64 = @import("platform.zig").ticks;

/// Materialize only a descendant of the pinned workspace. Retain the created
/// components until Root.initMutation has acquired its own complete chain.
fn pinGovernedCwd(a: std.mem.Allocator, workspace_root: []const u8, cwd: []const u8) !confined_fs.Root {
    if (!std.fs.path.isAbsolute(cwd)) return error.PathOutsideSandbox;
    var root = try confined_fs.createRoot(a, workspace_root);
    defer root.deinit();
    const normalized = try std.fs.path.resolve(a, &.{cwd});
    defer a.free(normalized);
    if (@import("platform.zig").pathEqual(root.canonical, normalized)) return confined_fs.Root.initMutation(a, normalized);
    const relative = root.relativePath(normalized) catch |err| switch (err) {
        error.SandboxDenied => return error.PathOutsideSandbox,
        else => return err,
    };
    defer a.free(relative);
    var directory = try root.openMutation(relative, .directory);
    defer directory.deinit();
    return confined_fs.Root.initMutation(a, normalized);
}

test "SEC-FS superagent cwd creation pins parents and rejects outside and junction" {
    if (@import("builtin").os.tag != .windows) return @import("platform.zig").skip("T9: crea junctions con cmd.exe mklink /J (Windows); en Linux los enlaces los rechaza confined_posix y lo prueba su propia prueba");
    const a = std.testing.allocator;
    const io = std.testing.io;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.createDirPath(io, "work");
    try tmp.dir.createDirPath(io, "outside");
    const path = try tmp.dir.realPathFileAlloc(io, "work", a);
    defer a.free(path);
    const outside = try tmp.dir.realPathFileAlloc(io, "outside", a);
    defer a.free(outside);
    const nested = try std.fmt.allocPrint(a, "{s}" ++ std.fs.path.sep_str ++ "new" ++ std.fs.path.sep_str ++ "nested", .{path});
    defer a.free(nested);
    {
        var cwd = try pinGovernedCwd(a, path, nested);
        defer cwd.deinit();
        try cwd.writeFile("proof.txt", "inside");
        if (tmp.dir.rename("work/new", tmp.dir, "moved", io)) |_| {
            return error.TestUnexpectedResult;
        } else |err| {
            try std.testing.expect(err == error.AccessDenied or err == error.FileBusy);
        }
    }
    try std.testing.expectError(error.PathOutsideSandbox, pinGovernedCwd(a, path, outside));
    const junction = try std.fmt.allocPrint(a, "{s}" ++ std.fs.path.sep_str ++ "alias", .{path});
    defer a.free(junction);
    var mk = try providers.github.runCmdCaptureWin32(a, &.{ "cmd.exe", "/d", "/c", "mklink", "/J", junction, outside }, null);
    defer mk.deinit(a);
    try std.testing.expectEqual(@as(u32, 0), mk.exit_code);
    defer tmp.dir.deleteDir(io, "work/alias") catch |err| std.debug.print("cwd junction cleanup: {s}\n", .{@errorName(err)});
    const child = try std.fmt.allocPrint(a, "{s}" ++ std.fs.path.sep_str ++ "must-not-exist", .{junction});
    defer a.free(child);
    try std.testing.expectError(error.SandboxDenied, pinGovernedCwd(a, path, child));
    try std.testing.expectError(error.FileNotFound, tmp.dir.openDir(io, "outside/must-not-exist", .{}));
}

/// Detecta si un archivo fuente parece ser una aplicación con interfaz gráfica
/// (GUI) para no matarla con el timeout corto del executor (10 s por defecto).
/// GOBERNANZA-EJECUCION: true si `path` ya está en la lista de rutas GUI lanzadas
/// por esta orden. Extraída de governedExecute para poder testearla sin necesitar
/// un archivo real en disco ni spawnear un proceso (isGuiProgram/runDetached sí
/// los requieren, ver comentario de `launched_gui_paths` más arriba).
/// FASE-AGENTIC-2: nombres de artefacto que son texto humano-legible dirigido
/// al usuario (una respuesta/síntesis), a diferencia de "source"/"code"/
/// "content" que casi siempre son el archivo de código generado — mostrar
/// código crudo como "respuesta del asistente" sería confuso en el chat.
/// Nombre base sin directorio ni extensión ("t1.zig" -> "t1", "docs/response.md" -> "response").
/// Implementado a mano (sin std.fs.path) porque estas rutas son lógicas del worker,
/// no rutas de filesystem reales que deban resolverse con esa API.
fn basenameStem(path: []const u8) []const u8 {
    var start: usize = 0;
    if (std.mem.lastIndexOfAny(u8, path, "/\\")) |i| start = i + 1;
    const base = path[start..];
    if (std.mem.lastIndexOfScalar(u8, base, '.')) |dot| {
        if (dot > 0) return base[0..dot];
    }
    return base;
}

fn isReadableArtifactName(name: []const u8) bool {
    const readable = &[_][]const u8{
        "response", "answer",    "summary", "markdown",
        "result",   "text",      "doc",     "documentation",
        "readme",   "respuesta", "resumen", "resultado",
    };
    const stem = basenameStem(name);
    for (readable) |r| {
        if (std.ascii.eqlIgnoreCase(stem, r)) return true;
    }
    return false;
}

/// FASE-AGENTIC-4: tipos de tarea cuyo propósito ES producir narrativa (no
/// código/artefactos técnicos) — su artefacto es legible sin importar cómo el
/// worker/modelo lo haya nombrado. Sin esto, una tarea "investigar" cuyo
/// artefacto termina llamándose "t1.zig" (visto en vivo: el modelo de fallback
/// eligió esa extensión) cae siempre al resumen genérico aunque el contenido
/// SÍ sea la respuesta pedida.
fn isNarrativeTaskType(t: model_router.TaskType) bool {
    return switch (t) {
        .investigar, .resumir, .documentar => true,
        else => false,
    };
}

test "live attribution uses last actual provider model and unknown without attempts" {
    const allocator = std.testing.allocator;
    var llm = live_worker.LiveLlm{
        .allocator = allocator,
        .lives = &.{},
        .buffer = .empty,
    };
    defer llm.deinit();
    try llm.attempts.append(allocator, .{ .provider = "provider-a", .model = "first-model", .status = "error" });
    try llm.attempts.append(allocator, .{ .provider = "provider-b", .model = "actual-fallback-model", .status = "ok" });
    var model_used: []const u8 = "generic";
    var owned_model: ?[]u8 = null;
    defer if (owned_model) |owned| allocator.free(owned);
    setModelUsedFromLive(allocator, &llm, &model_used, &owned_model);
    try std.testing.expectEqualStrings("actual-fallback-model", model_used);
    llm.clearAttempts();
    setModelUsedFromLive(allocator, &llm, &model_used, &owned_model);
    try std.testing.expectEqualStrings("unknown", model_used);
}

