/// FASE-AGENTIC-2: construye el ENTREGABLE que se muestra al usuario como
/// respuesta del asistente — a diferencia de buildReport() (estadísticas de
/// tareas: cuántas completaron, qué modelo usó cada una), esto es el
/// CONTENIDO real que pidió (p.ej. la comparativa de una tarea "investigar").
///
/// Prioriza el artefacto de texto legible de la ÚLTIMA tarea completada que
/// produjo uno: el worker de esa tarea ya recibió los resultados de
/// web_search inyectados en su prompt (ver effective_upstream en
/// runTaskInWave), así que su artefacto YA es la síntesis pedida — no hace
/// falta una segunda llamada LLM para re-sintetizar lo que el worker ya
/// sintetizó (más simple, más barato, y no introduce un punto de fallo LLM
/// adicional en un codebase con historial de fragilidad ahí).
///
/// Si ninguna tarea produjo un artefacto legible (plan de solo
/// programar/ejecutar sin narrativa, p.ej.), cae a un resumen determinista
/// corto — nunca deja al usuario sin respuesta visible en el chat.
fn cloneArtifacts(allocator: std.mem.Allocator, source: []const worker_backend.Artifact) ![]const worker_backend.Artifact {
    if (source.len == 0) return &.{};
    const cloned = try allocator.alloc(worker_backend.Artifact, source.len);
    var initialized: usize = 0;
    errdefer {
        for (cloned[0..initialized]) |*artifact| artifact.deinit(allocator);
        allocator.free(cloned);
    }
    for (source, 0..) |artifact, index| {
        const path = try allocator.dupe(u8, artifact.path);
        const content = allocator.dupe(u8, artifact.content) catch |err| {
            allocator.free(path);
            return err;
        };
        // / E-GOV.1 (e5-gov): la procedencia viaja con la copia; sin
        // ella una corrección volvería al gate estricto y marcaría el TODO heredado.
        const inherited = if (artifact.inherited_placeholders) |lines| allocator.dupe(@import("artifact_quality.zig").LineHash, lines) catch |err| {
            allocator.free(path);
            allocator.free(content);
            return err;
        } else null;
        cloned[index] = .{ .path = path, .content = content, .inherited_placeholders = inherited };
        initialized += 1;
    }
    return cloned;
}

fn freeOwnedArtifacts(allocator: std.mem.Allocator, artifacts: []const worker_backend.Artifact) void {
    if (artifacts.len == 0) return;
    for (artifacts) |*artifact| artifact.deinit(allocator);
    allocator.free(artifacts);
}

/// etiqueta legible de un candidato para las notas de respaldo y
/// el fallo honesto: el nombre de pantalla del agente CLI ("Claude Code") o
/// "provider/model" del catálogo.
fn executorLabel(allocator: std.mem.Allocator, prov: []const u8, mdl: []const u8) ![]u8 {
    if (external_agents.metaForProvider(prov)) |meta| return allocator.dupe(u8, meta.display);
    return std.fmt.allocPrint(allocator, "{s}/{s}", .{ prov, mdl });
}

/// fallo honesto de un ejecutor FIJADO que no cae a respaldo.
/// Consume `res` y devuelve su resultado con el motivo que nombra al ejecutor
/// fijado y la política (no se usó otro proveedor porque lo fijaste).
fn pinnedExecutorFailed(allocator: std.mem.Allocator, prov: []const u8, mdl: []const u8, res: worker_backend.WorkerResult) worker_backend.WorkerResult {
    var out = res;
    const why: []const u8 = if (res.error_msg.len > 0) res.error_msg else "terminó sin éxito y sin detalle";
    const label = executorLabel(allocator, prov, mdl) catch null;
    defer if (label) |l| allocator.free(l);
    const msg = std.fmt.allocPrint(
        allocator,
        "{s} falló: {s}; no se usó otro proveedor porque lo fijaste",
        .{ label orelse prov, why },
    ) catch return out;
    allocator.free(res.error_msg);
    out.error_msg = msg;
    return out;
}

/// guarda (con propietario) el motivo del último candidato fallido,
/// para que el siguiente `provider_fallback` y la nota del resumen lo
/// declaren en vez de saltar de proveedor en silencio.
fn rememberFailureReason(slot: *?[]u8, allocator: std.mem.Allocator, reason: []const u8) void {
    if (slot.*) |old| allocator.free(old);
    slot.* = allocator.dupe(u8, reason) catch null;
}

/// Primera línea con contenido de un texto (código de salida / detalle del
/// CLI): el motivo honesto se lee en la salida, no en una cola cruda.
fn firstContentLine(text: []const u8) []const u8 {
    var it = std.mem.tokenizeAny(u8, text, "\r\n");
    while (it.next()) |line| {
        const trimmed = std.mem.trim(u8, line, " \t");
        if (trimmed.len > 0) return trimmed;
    }
    return "";
}

/// respaldo realmente ocurrido durante el despacho — quién falló,
/// por qué y quién siguió. Alimenta la declaración del resumen final del chat:
/// sin esto, el trabajo de otro proveedor se presentaba como si lo hubiera
/// hecho el ejecutor fijado (orden #890: Claude Code falló y la hizo Cohere,
/// pero el chat solo dijo «Listo — 1 tarea(s) completada(s)»).
const FallbackNote = struct {
    task_id: []const u8,
    from_label: []const u8,
    reason: []const u8,
    to_label: []const u8,

    fn deinit(self: *const FallbackNote, allocator: std.mem.Allocator) void {
        allocator.free(self.task_id);
        allocator.free(self.from_label);
        allocator.free(self.reason);
        allocator.free(self.to_label);
    }
};

fn synthesizeFinalAnswer(
    allocator: std.mem.Allocator,
    results: []const Superagent.TaskRunResult,
    tasks: []const planner.PlannedTask,
    outputs: []const WorkerOutput,
    completed: usize,
    fallback_notes: []const FallbackNote,
) ![]const u8 {
    const base = blk: {
        var best: ?[]const u8 = null;
        for (results) |res| {
            if (!res.success) continue;
            var narrative_task = false;
            for (tasks) |t| {
                if (std.mem.eql(u8, t.id, res.task_id)) {
                    narrative_task = isNarrativeTaskType(t.task_type);
                    break;
                }
            }
            for (res.artifacts) |art| {
                if (art.content.len == 0) continue;
                if (narrative_task or isReadableArtifactName(art.path)) {
                    best = art.content; // el último gana: más "final" en el orden de ejecución.
                }
            }
        }
        if (best) |b| break :blk try allocator.dupe(u8, b);
        // Para órdenes de programación/ejecución, stdout es el entregable más fiel:
        // proviene del proceso real, no de una narración del modelo. También da al
        // evaluador agéntico evidencia suficiente para no pedir ejecutar otra vez.
        var last_stdout: ?[]const u8 = null;
        for (outputs) |output| {
            if (output.text.len > 0 and std.ascii.eqlIgnoreCase(output.stream, "stdout")) {
                last_stdout = output.text;
            }
        }
        if (last_stdout) |text| break :blk try allocator.dupe(u8, std.mem.trim(u8, text, " \t\r\n"));
        if (completed == 0) {
            break :blk try allocator.dupe(u8, "No pude completar la orden — revisa el reporte para más detalle.");
        }
        break :blk try std.fmt.allocPrint(
            allocator,
            "Listo — {d} tarea(s) completada(s). Esta orden no generó una respuesta narrativa (revisa el reporte o los archivos generados para el detalle).",
            .{completed},
        );
    };
    // (criterio 2): cuando hubo respaldo real, el cierre del chat lo
    // declara — quién falló, con qué motivo y quién terminó la tarea. Si el
    // respaldo falla en construir el aviso, es preferible la respuesta base a
    // quedarse sin cierre.
    if (fallback_notes.len == 0) return base;
    const notice = buildFallbackNotice(allocator, fallback_notes, results) catch return base;
    defer allocator.free(notice);
    if (notice.len == 0) return base;
    const combined = std.fmt.allocPrint(allocator, "{s}\n\n{s}", .{ base, notice }) catch return base;
    allocator.free(base);
    return combined;
}

/// línea legible del respaldo para el resumen final. Nombra cada
/// salto (quién falló, motivo, quién siguió) y, si la tarea acabó bien, con qué
/// modelo — el `model_used` real del resultado, no una suposición.
fn buildFallbackNotice(allocator: std.mem.Allocator, notes: []const FallbackNote, results: []const Superagent.TaskRunResult) ![]u8 {
    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    try out.appendSlice(allocator, "Respaldo: ");
    for (notes, 0..) |note, i| {
        if (i > 0) try out.appendSlice(allocator, " | ");
        try out.appendSlice(allocator, note.task_id);
        try out.appendSlice(allocator, ": ");
        try out.appendSlice(allocator, note.from_label);
        try out.appendSlice(allocator, " falló (");
        try appendSingleLine(allocator, &out, note.reason);
        try out.appendSlice(allocator, "); siguió ");
        try out.appendSlice(allocator, note.to_label);
    }
    // Quién la hizo al final: el resultado exitoso de la tarea, una vez por
    // tarea (varias notas pueden encadenar el mismo task_id).
    for (notes, 0..) |note, i| {
        var ya_declarada = false;
        for (notes[0..i]) |previa| {
            if (std.mem.eql(u8, previa.task_id, note.task_id)) ya_declarada = true;
        }
        if (ya_declarada) continue;
        for (results) |res| {
            if (!res.success) continue;
            if (!std.mem.eql(u8, res.task_id, note.task_id)) continue;
            try out.appendSlice(allocator, " | ");
            try out.appendSlice(allocator, note.task_id);
            try out.appendSlice(allocator, " la hizo ");
            try out.appendSlice(allocator, res.model_used);
            break;
        }
    }
    return out.toOwnedSlice(allocator);
}

/// Aplana el motivo a UNA línea: el resumen del chat es una frase, no una
/// transcripción; los saltos de línea del detalle del CLI se vuelven espacios.
fn appendSingleLine(allocator: std.mem.Allocator, out: *std.ArrayList(u8), text: []const u8) !void {
    var ultimo_espacio = false;
    for (text) |ch| {
        const es_espacio = ch == '\n' or ch == '\r' or ch == '\t' or ch == ' ';
        if (es_espacio) {
            if (ultimo_espacio) continue;
            try out.append(allocator, ' ');
            ultimo_espacio = true;
        } else {
            try out.append(allocator, ch);
            ultimo_espacio = false;
        }
    }
}

