// ── FASE-AGENTIC-3: loop observe → re-planifica ────────────────────────────
// El agente, tras ejecutar el plan, se AUTO-OBSERVA: un paso evaluador (LLM)
// decide si el objetivo del usuario ya está cumplido o si hace falta otro paso.
// Todo gated por `Superagent.max_agent_iterations` (default 1 = comportamiento
// de un solo paso, idéntico a hoy — el código del loop NO corre). Ver
// agenticExecute() más abajo.

/// FASE-AGENTIC-3: firma del paso evaluador — misma forma que un completeObject
/// (system+user → objeto JSON como string). c_api la envuelve sobre LiveLlm.
pub const EvaluatorFn = *const fn (ctx: *anyopaque, system_prompt: []const u8, user_prompt: []const u8) []const u8;

/// Decisión del paso evaluador. Las cadenas opcionales las posee el llamador.
pub const EvaluatorDecision = struct {
    /// true = el objetivo del usuario ya está cumplido; no hacer más iteraciones.
    done: bool,
    /// Si !done: el objetivo concreto del SIGUIENTE paso (para re-planificar).
    next_goal: ?[]const u8 = null,
    /// Respuesta final consolidada para el usuario (si el evaluador la provee).
    final_answer: ?[]const u8 = null,

    pub fn deinit(self: *EvaluatorDecision, allocator: std.mem.Allocator) void {
        if (self.next_goal) |g| allocator.free(g);
        if (self.final_answer) |a| allocator.free(a);
    }
};

/// FASE-AGENTIC-3: parsea la respuesta JSON del evaluador. FAIL-SAFE: ante
/// cualquier duda (JSON inválido, campos ausentes, next_goal vacío) devuelve
/// `done=true` — NUNCA se arriesga a un loop desbocado por una respuesta
/// ambigua. Solo continúa el loop si el evaluador dice explícitamente
/// done=false Y aporta un next_goal no vacío.
fn parseEvaluatorDecision(allocator: std.mem.Allocator, json: []const u8) EvaluatorDecision {
    const trimmed = std.mem.trim(u8, json, " \t\r\n");
    if (trimmed.len < 2 or trimmed[0] != '{') return .{ .done = true };
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, trimmed, .{}) catch return .{ .done = true };
    defer parsed.deinit();
    if (parsed.value != .object) return .{ .done = true };
    const obj = parsed.value.object;

    var done = true;
    if (obj.get("done")) |d| {
        if (d == .bool) done = d.bool;
    }

    var next_goal: ?[]const u8 = null;
    if (obj.get("next_goal")) |g| {
        if (g == .string) {
            const t = std.mem.trim(u8, g.string, " \t\r\n");
            if (t.len > 0) next_goal = allocator.dupe(u8, t) catch null;
        }
    }

    var final_answer: ?[]const u8 = null;
    if (obj.get("final_answer")) |a| {
        if (a == .string) {
            const t = std.mem.trim(u8, a.string, " \t\r\n");
            if (t.len > 0) final_answer = allocator.dupe(u8, t) catch null;
        }
    }

    // FAIL-SAFE: si dice "no terminado" pero no da hacia dónde seguir, se trata
    // como terminado (no hay nada accionable → no iterar en vacío).
    if (!done and next_goal == null) done = true;

    return .{ .done = done, .next_goal = next_goal, .final_answer = final_answer };
}

test "parseEvaluatorDecision: done=false con next_goal continua el loop" {
    const allocator = std.testing.allocator;
    var d = parseEvaluatorDecision(allocator, "{\"done\":false,\"next_goal\":\"escribe los tests\"}");
    defer d.deinit(allocator);
    try std.testing.expect(!d.done);
    try std.testing.expectEqualStrings("escribe los tests", d.next_goal.?);
}

test "parseEvaluatorDecision: done=true detiene el loop y guarda final_answer" {
    const allocator = std.testing.allocator;
    var d = parseEvaluatorDecision(allocator, "{\"done\":true,\"final_answer\":\"Listo, aquí está la comparativa.\"}");
    defer d.deinit(allocator);
    try std.testing.expect(d.done);
    try std.testing.expect(d.next_goal == null);
    try std.testing.expectEqualStrings("Listo, aquí está la comparativa.", d.final_answer.?);
}

test "parseEvaluatorDecision: JSON invalido es FAIL-SAFE (done=true, no loop)" {
    const allocator = std.testing.allocator;
    var d1 = parseEvaluatorDecision(allocator, "esto no es json");
    defer d1.deinit(allocator);
    try std.testing.expect(d1.done);
    var d2 = parseEvaluatorDecision(allocator, "");
    defer d2.deinit(allocator);
    try std.testing.expect(d2.done);
}

test "parseEvaluatorDecision: done=false SIN next_goal cae a done=true (no itera en vacio)" {
    const allocator = std.testing.allocator;
    var d = parseEvaluatorDecision(allocator, "{\"done\":false}");
    defer d.deinit(allocator);
    try std.testing.expect(d.done);
    try std.testing.expect(d.next_goal == null);
}

/// FASE-AGENTIC-3: system prompt del evaluador — pide EXACTAMENTE el JSON que
/// parseEvaluatorDecision espera, y lo instruye a ser conservador (preferir
/// done=true salvo que falte algo claramente accionable).
const EVALUATOR_SYSTEM_PROMPT =
    \\Eres el evaluador de un agente de programación. Se te da el objetivo original del usuario
    \\y un resumen de lo que ya se hizo/produjo. Decide si el objetivo YA está cumplido o si falta
    \\un paso concreto más. Responde SOLO con un objeto JSON, sin texto adicional, con esta forma:
    \\{"done": true|false, "next_goal": "objetivo del siguiente paso (solo si done=false)", "final_answer": "respuesta final para el usuario (solo si done=true)"}
    \\Sé CONSERVADOR: si el objetivo está razonablemente cumplido, responde done=true. Solo pon
    \\done=false cuando falte algo claramente accionable (p.ej. se generó código pero no se ejecutó/probó
    \\y el usuario lo pidió). NUNCA inventes pasos que el usuario no pidió.
;

/// FASE-AGENTIC-3: arma el user prompt del evaluador con el objetivo + lo hecho.
fn buildEvaluatorPrompt(allocator: std.mem.Allocator, goal: []const u8, work_so_far: []const u8) ![]const u8 {
    return std.fmt.allocPrint(
        allocator,
        "OBJETIVO ORIGINAL DEL USUARIO:\n{s}\n\nLO QUE YA SE HIZO/PRODUJO:\n{s}\n\n¿Está cumplido el objetivo? Responde solo el JSON.",
        .{ goal, work_so_far },
    );
}

test "buildEvaluatorPrompt: incluye objetivo y trabajo hecho" {
    const allocator = std.testing.allocator;
    const p = try buildEvaluatorPrompt(allocator, "haz un reloj", "generé clock.py");
    defer allocator.free(p);
    try std.testing.expect(std.mem.indexOf(u8, p, "haz un reloj") != null);
    try std.testing.expect(std.mem.indexOf(u8, p, "generé clock.py") != null);
}

fn containsPath(launched: []const []const u8, path: []const u8) bool {
    for (launched) |already| {
        if (std.mem.eql(u8, already, path)) return true;
    }
    return false;
}

test "containsPath: detecta una ruta ya lanzada, ignora las demás" {
    const launched = [_][]const u8{ "workspace/orden-1/a.py", "workspace/orden-1/analog_roman_clock.py" };
    try std.testing.expect(containsPath(&launched, "workspace/orden-1/analog_roman_clock.py"));
    try std.testing.expect(!containsPath(&launched, "workspace/orden-1/other.py"));
    try std.testing.expect(!containsPath(&.{}, "anything.py"));
}

/// GOBERNANZA-EJECUCION: true si `tasks` incluye una tarea `ejecutar` que depende
/// de `producer_id`. Usada para omitir la vista previa automática (FASE-0/EXEC-02)
/// de una tarea "programar" cuando el plan ya trae una tarea "ejecutar" dedicada
/// para su artefacto — el plan explícito manda sobre la heurística de preview.
fn hasDedicatedExecutorTask(tasks: []const planner.PlannedTask, producer_id: []const u8) bool {
    for (tasks) |t| {
        if (t.task_type != .ejecutar) continue;
        for (t.depends_on) |dep| {
            if (std.mem.eql(u8, dep, producer_id)) return true;
        }
    }
    return false;
}

test "hasDedicatedExecutorTask: detecta tarea ejecutar dependiente, ignora las que no aplican" {
    var dep_t2 = [_][]const u8{"t1"};
    const tasks = [_]planner.PlannedTask{
        .{ .id = "t1", .task_type = .programar, .department = "programacion", .description = "reloj", .contract_fields = &.{}, .depends_on = &.{} },
        .{ .id = "t2", .task_type = .ejecutar, .department = "programacion", .description = "ejecutar reloj", .contract_fields = &.{}, .depends_on = dep_t2[0..] },
    };
    try std.testing.expect(hasDedicatedExecutorTask(&tasks, "t1"));
    try std.testing.expect(!hasDedicatedExecutorTask(&tasks, "t2"));

    const solo_programar = [_]planner.PlannedTask{
        .{ .id = "t1", .task_type = .programar, .department = "programacion", .description = "reloj", .contract_fields = &.{}, .depends_on = &.{} },
    };
    try std.testing.expect(!hasDedicatedExecutorTask(&solo_programar, "t1"));
}

/// — ¿es este `.js` código de NAVEGADOR y no un programa de Node?
///
/// El fallo, medido en las órdenes #343 y #349 del 2026-08-15: el motor escribe
/// el `script.js` de una página web y acto seguido lo ejecuta con `node`. Node
/// no tiene `document`, así que revienta con `ReferenceError: document is not
/// defined`, la tarea se marca fallida y **la orden entera acaba `failed` con
/// los tres archivos correctos en disco**. El caso `web-multiarchivo` del gate
/// no podía cerrar en verde por diseño: su JavaScript SIEMPRE es de navegador.
///
/// Que el gate dijera «PASA» a la vez (mira el disco, no ejecuta) es la otra
/// mitad del mismo agujero, y está anotada como.
///
/// El criterio es el contenido, igual que `isGuiProgram` hace con tkinter y
/// compañía: si el archivo toca el DOM o el navegador, no es un programa de
/// consola y no se ejecuta con `node`. Sin adivinar por el nombre del archivo
/// ni por lo que haya alrededor.
fn isBrowserScript(allocator: std.mem.Allocator, path: []const u8) bool {
    const ext = std.fs.path.extension(path);
    if (!std.mem.eql(u8, ext, ".js")) return false;

    const path_z = allocator.dupeZ(u8, path) catch return false;
    defer allocator.free(path_z);

    const h = CreateFileA(path_z.ptr, GENERIC_READ, FILE_SHARE_READ, null, OPEN_EXISTING, 0, null);
    if (h == INVALID_HANDLE_VALUE) return false;
    defer _ = CloseHandle(h);

    var buf: [64 * 1024]u8 = undefined;
    var read: u32 = 0;
    if (ReadFile(h, &buf, buf.len, &read, null) == 0) return false;
    const content = buf[0..read];

    // Marcas que NO existen en Node. `window.` y `document.` con el punto para
    // no cazar una variable local llamada `document`; `localStorage` y
    // `DOMContentLoaded` son inequívocas.
    const marcas = &[_][]const u8{
        "document.",        "window.",
        "localStorage",     "sessionStorage",
        "DOMContentLoaded", "querySelector",
        "getElementById",   "addEventListener(",
        "HTMLElement",      "navigator.",
    };
    for (marcas) |m| {
        if (std.mem.indexOf(u8, content, m) != null) return true;
    }
    return false;
}

fn isGuiProgram(allocator: std.mem.Allocator, path: []const u8) bool {
    const path_z = allocator.dupeZ(u8, path) catch return false;
    defer allocator.free(path_z);

    const h = CreateFileA(path_z.ptr, GENERIC_READ, FILE_SHARE_READ, null, OPEN_EXISTING, 0, null);
    if (h == INVALID_HANDLE_VALUE) return false;
    defer _ = CloseHandle(h);

    var buf: [64 * 1024]u8 = undefined;
    var read: u32 = 0;
    if (ReadFile(h, &buf, buf.len, &read, null) == 0) return false;
    const content = buf[0..read];

    const markers = &[_][]const u8{
        "tkinter",     "pygame",   "PyQt",    "PySide", "kivy",   "dearpygui",
        "pysimplegui", "wxPython", "webview", "curses", "OpenGL", "glfw",
    };
    for (markers) |m| {
        if (std.mem.indexOf(u8, content, m) != null) return true;
    }
    return false;
}

/// E-GOV.4: ¿el archivo Go declara `package main`? Se salta la cabecera de
/// comentarios (`//` y `/* */`). Un archivo ilegible cuenta como `main`, que es
/// el comportamiento de siempre (`go run`); sin cláusula `package`, no.
fn goFileIsMainPackage(allocator: std.mem.Allocator, path: []const u8) bool {
    const path_z = allocator.dupeZ(u8, path) catch return true;
    defer allocator.free(path_z);
    const h = CreateFileA(path_z.ptr, GENERIC_READ, FILE_SHARE_READ, null, OPEN_EXISTING, 0, null);
    if (h == INVALID_HANDLE_VALUE) return true;
    defer _ = CloseHandle(h);
    var buf: [64 * 1024]u8 = undefined;
    var read: u32 = 0;
    if (ReadFile(h, &buf, buf.len, &read, null) == 0) return true;
    return goSourceIsMainPackage(buf[0..read]);
}

fn goSourceIsMainPackage(content: []const u8) bool {
    var lines = std.mem.splitScalar(u8, content, '\n');
    var block_comment = false;
    while (lines.next()) |line| {
        var trimmed = std.mem.trim(u8, line, " \t\r");
        while (true) {
            if (block_comment) {
                const end = std.mem.indexOf(u8, trimmed, "*/") orelse break;
                trimmed = std.mem.trimStart(u8, trimmed[end + 2 ..], " \t");
                block_comment = false;
            }
            if (!std.mem.startsWith(u8, trimmed, "/*")) break;
            block_comment = true;
            trimmed = trimmed[2..];
        }
        if (block_comment or trimmed.len == 0 or std.mem.startsWith(u8, trimmed, "//")) continue;
        var words = std.mem.tokenizeAny(u8, trimmed, " \t\r;");
        if (!std.mem.eql(u8, words.next() orelse "", "package")) return false;
        const name = words.next() orelse return false;
        return std.mem.eql(u8, name, "main") or std.mem.startsWith(u8, name, "main//") or std.mem.startsWith(u8, name, "main/*");
    }
    return false;
}

test "E-GOV.4: un archivo Go que no es package main se compila, no se ejecuta" {
    try std.testing.expect(!goSourceIsMainPackage("// package main\n/* header */\npackage pflag\nfunc Get() {}"));
    try std.testing.expect(goSourceIsMainPackage("/* header\n comment */ package main\nfunc main() {}"));
    try std.testing.expect(goSourceIsMainPackage("// Copyright\n\npackage main // entry\n\nfunc main() {}\n"));
    try std.testing.expect(goSourceIsMainPackage("package main\r\n"));
    try std.testing.expect(!goSourceIsMainPackage("/* a */ /* b */ package mainly\n"));
    try std.testing.expect(!goSourceIsMainPackage("invalid"));
    try std.testing.expect(!goSourceIsMainPackage("package"));
    try std.testing.expect(!goSourceIsMainPackage(""));
}

/// Infiere un comando allowlisted para ejecutar/compilar un archivo según su
/// extensión. Devuelve slices estáticos: `args` apunta a `file`, que debe vivir
/// al menos durante la llamada a `runGoverned`.
fn inferCommand(file: []const u8) ?CommandHint {
    const ext = std.fs.path.extension(file);
    if (std.mem.eql(u8, ext, ".py")) return .{ .exe = "python", .kind = .script };
    if (std.mem.eql(u8, ext, ".js")) return .{ .exe = "node", .kind = .script };
    if (std.mem.eql(u8, ext, ".go")) return .{ .exe = "go", .kind = .go_run };
    if (std.mem.eql(u8, ext, ".zig")) return .{ .exe = "zig", .kind = .zig_build };
    if (std.mem.eql(u8, ext, ".c")) return .{ .exe = "gcc", .kind = .c_build };
    if (std.mem.eql(u8, ext, ".cpp") or std.mem.eql(u8, ext, ".cc")) return .{ .exe = "clang++", .kind = .cpp_build };
    return null;
}

/// ¿la salida contiene una traza de error del interprete (un fallo
/// de ejecución real, no un mensaje de uso)? Python escribe `Traceback (...`
/// y termina en `xxxError: ...`; node escribe `throw err;` y `Error: ...` /
/// `SyntaxError` / `ReferenceError`; además `ModuleNotFoundError`. Con cualquiera
/// de ellas presente, la salida ya NO es "solo un mensaje de uso".
fn tieneTrazaErrorInterprete(salida: []const u8) bool {
    const marcas = [_][]const u8{
        // Python / node.
        "Traceback",
        "SyntaxError",
        "ModuleNotFoundError",
        "ReferenceError",
        "Error:",
        // Java / Kotlin / C#.
        "Exception",
        "Unhandled",
        // Go / Rust.
        "panic",
        // gcc / clang / rustc / npm escriben el diagnostico en minuscula.
        "error:",
        // Segfault.
        "Segmentation",
    };
    for (marcas) |marca| {
        if (std.mem.indexOf(u8, salida, marca) != null) return true;
    }
    return false;
}

fn esPrefijoCi(texto: []const u8, prefijo: []const u8) bool {
    if (texto.len < prefijo.len) return false;
    for (texto[0..prefijo.len], prefijo) |c, p| {
        if (std.ascii.toLower(c) != std.ascii.toLower(p)) return false;
    }
    return true;
}

/// Primera línea con contenido real (no solo blancos/salto de línea) del texto.
fn primeraLineaConContenido(texto: []const u8) ?[]const u8 {
    var it = std.mem.splitScalar(u8, texto, '\n');
    while (it.next()) |linea| {
        if (std.mem.trim(u8, linea, " \t\r").len > 0) return linea;
    }
    return null;
}

/// R2-2a: la línea tiene que EMPEZAR por el mensaje de uso, no contenerlo en
/// cualquier posición. Se admite el prefijo «<programa>: usage:» (el nombre del
/// programa sin espacios). Así «Disk usage: 95% exceeded» NO es un uso.
fn lineaEsMensajeDeUso(linea: []const u8) bool {
    const texto = std.mem.trim(u8, linea, " \t\r");
    if (esPrefijoCi(texto, "uso:") or esPrefijoCi(texto, "usage:")) return true;
    const colon = std.mem.indexOfScalar(u8, texto, ':') orelse return false;
    if (colon == 0) return false;
    const programa = texto[0..colon];
    for (programa) |c| {
        if (std.ascii.isWhitespace(c)) return false;
    }
    const resto = std.mem.trim(u8, texto[colon + 1 ..], " \t\r");
    return esPrefijoCi(resto, "uso:") or esPrefijoCi(resto, "usage:");
}

fn streamTieneMensajeDeUso(texto: []const u8) bool {
    const primera = primeraLineaConContenido(texto) orelse return false;
    return lineaEsMensajeDeUso(primera);
}

///, función que decide (sin modelos, sin I/O): ¿esta ejecución es un
/// "programa requiere argumentos" y no un fallo del artefacto?
///
/// Condiciones (todas obligatorias):
///  - exit 1 o 2 (R2-2c). Cualquier otro código (139, 0xC0000005, 127…) es
///    fallo real: un segfault o un proceso que no arrancó no es "pide argv".
///  - ni stdout ni stderr contienen traza de error del intérprete (R2-2b):
///    Traceback, Exception, panic, error:, Segmentation, Unhandled…
///  - la primera línea con contenido de ALGUNO de los dos flujos EMPIEZA por
///    «uso:»/«usage:» (R2-2a y R2-2d). Se miran ambos porque en Windows/PowerShell
///    el uso puede caer por stderr mientras stdout trae un aviso.
///
/// exit 0 nunca entra; una salida sin mensaje de uso, tampoco: sigue siendo un
/// fallo de ejecución.
fn usageOnlyExit(exit_code: i32, stdout: []const u8, stderr: []const u8) bool {
    if (exit_code != 1 and exit_code != 2) return false;
    if (tieneTrazaErrorInterprete(stdout) or tieneTrazaErrorInterprete(stderr)) return false;
    return streamTieneMensajeDeUso(stdout) or streamTieneMensajeDeUso(stderr);
}

fn taskExecutionSucceeded(
    task_type: model_router.TaskType,
    worker_success: bool,
    validation_ok: bool,
    exec: Superagent.ExecOutcome,
) bool {
    if (!worker_success or !validation_ok) return false;
    // B3 (orden 159): una tarea que NO es `.ejecutar` (programar/auditar) se
    // anunciaba SIEMPRE como exitosa si el worker respondía y el contrato de
    // validación pasaba, SIN mirar qué pasó al EJECUTAR su artefacto. En la 159:
    // t1 escribió t1.py, `python t1.py` falló con SyntaxError (exit 1), y aun así
    // se emitió `task_done success:true`. La orden cerraba `order_failed
    // cause=all_tasks_failed` (0 completadas, 2 fallidas). Las dos sentencias NO
    // pueden ser ciertas a la vez: el que mentía era el evento per-tarea, porque
    // el auto-auditor usa exactamente el criterio de abajo (superagent.zig
    // "Criterio 2 (FIRE-05): ejecutó y devolvió exit_code != 0") para marcar la
    // misma tarea como fallida. Aquí se alinea el evento con ese veredicto: un
    // artefacto que se ejecutó y falló hace FALLIDAR la tarea, sea cual sea su
    // tipo. Las tareas que no ejecutan nada (auditorías textuales, informes) no
    // corren por aquí: `exec.ran == false` y quedan igual de exitosas que antes.
    //
    // `needs_approval`/`timed_out` nunca son fallo de exit (EXEC-SHOW: un
    // proceso que corrió y mostró salida hasta el timeout no es exit=1), igual
    // que en el propio criterio del auditor (Criterio 2 exige
    // `exit_code != 0 AND !timed_out`).
    // `usage_only` tampoco — el motor lanzó el programa SIN
    // argumentos y solo recibió su mensaje de uso: no hubo veredicto sobre el
    // artefacto, así que la tarea sigue su curso (sus dependientes se ejecutan).
    if (exec.needs_approval) return true;
    if (exec.ran and exec.exit_code != 0 and !exec.timed_out and !exec.usage_only) return false;
    if (task_type == .ejecutar) return exec.ran;
    return true;
}

/// P5: ¿este fallo de ejecución es del ENTORNO y no del modelo?
///
/// Medido en la orden 157: el script de la calculadora moría en `input()` con
/// `EOFError: EOF when reading a line` porque el proceso se ejecuta SIN stdin
/// (programas de consola → stdout capturado, stdin muerto). La orden lo
/// re-ejecutó CUATRO veces, muriendo idéntico las cuatro.
///
/// Esa es la distinción que pide el usuario: si el modelo escribió algo mal,
/// reintentar (o pedirle una corrección LLM) SÍ tiene sentido; si el ENTORNO
/// no puede ejecutar esto, reintentar es desperdicio puro y además hincha la
/// traza con errores idénticos. Este clasificador marca el segundo caso.
///
/// Firma medible: un programa que pide entrada y recibe EOF lo dice en stderr
/// con `EOFError` (Python) / `EOF when reading a line`. Neutral y sin adivinar:
/// no mira el contenido del archivo, mira el error que el propio entorno dejó.
fn execFailureIsEnvironmental(stderr: []const u8) bool {
    return std.mem.indexOf(u8, stderr, "EOFError") != null or
        std.mem.indexOf(u8, stderr, "EOF when reading a line") != null;
}

test "P5: EOFError por stdin muerto se clasifica como fallo de ENTORNO" {
    const stderr = "Traceback (most recent call last):\n  File \"orden-157\\calculadora.py\", line 23, in mostrar_menu\n    return int(input('Opcion: '))\nEOFError: EOF when reading a line\n";
    try std.testing.expect(execFailureIsEnvironmental(stderr));
}

test "P5: un exit code por fallo de LOGICA del programa NO es fallo de entorno" {
    const stderr = "AssertionError: la suma devolvió 3 en vez de 2\n";
    try std.testing.expect(!execFailureIsEnvironmental(stderr));
}

test "P5: stderr vacío no es nunca fallo de entorno" {
    try std.testing.expect(!execFailureIsEnvironmental(""));
}

fn correctionMaySucceedWithoutArtifact(task_type: model_router.TaskType) bool {
    return switch (task_type) {
        .planificar, .testear, .auditar, .documentar, .investigar, .resumir, .disenar, .ui => true,
        .programar, .programar_c, .programar_cpp, .programar_zig, .corregir, .ejecutar => false,
    };
}

fn buildCorrectionHandoffDescription(a: std.mem.Allocator, runtime: db.Connection, order_id: i64, fallback_goal: []const u8, nw: *const worker_backend.NativeWorker, task: planner.PlannedTask, window: u32, live: ?*live_worker.LiveLlm) ![]u8 {
    const handoff = @import("external_context.zig");
    var transcript = try handoff.loadOrderTranscript(a, runtime, order_id, fallback_goal);
    defer transcript.deinit();
    var empty_task = task;
    empty_task.description = "";
    const framing = try nw.buildPrompt(a, empty_task);
    defer a.free(framing);
    const counter = handoff.defaultTokenCounter();
    // NativeWorker repeats its system prompt in the user envelope; charge both
    // occurrences plus the actual contract/manifest/upstream text and 16 tokens
    // for the provider's system/user message structure.
    const transport_fixed = if (live) |l| blk: {
        if (l.lives.len == 0) return error.UnknownContextWindow;
        const previous_schema = l.json_schema;
        l.json_schema = live_worker.ARTIFACTS_JSON_SCHEMA;
        defer l.json_schema = previous_schema;
        break :blk try l.handoffFixedPromptTokens(l.lives[0], nw.system_prompt);
    } else counter.count(nw.system_prompt) + counter.count("system") + counter.count("user") + 16;
    const fixed = counter.count(framing) + transport_fixed;
    if (fixed > std.math.maxInt(u32)) return error.HandoffTooLarge;
    return handoff.buildHandoffPrompt(a, transcript.original, task.description, transcript.records, window, @intCast(fixed), counter);
}

fn buildCorrectionDescription(
    allocator: std.mem.Allocator,
    original_goal: []const u8,
    task_description: []const u8,
    verified_error: []const u8,
) ![]u8 {
    return std.fmt.allocPrint(
        allocator,
        "CORRECCIÓN OBLIGATORIA.\nOBJETIVO ORIGINAL (debe cumplirse completo):\n{s}\n\nTAREA QUE FALLÓ:\n{s}\n\nEVIDENCIA REAL DE COMPILACIÓN/EJECUCIÓN:\n{s}\n\nDevuelve el artefacto completo corregido, sin pseudocódigo, omisiones, TODOs ni dependencias prohibidas. Conserva todos los requisitos del objetivo, no solo el error local.",
        .{ original_goal, task_description, verified_error },
    );
}

fn containsAsciiIgnoreCase(haystack: []const u8, needle: []const u8) bool {
    if (needle.len == 0) return true;
    if (needle.len > haystack.len) return false;
    var start: usize = 0;
    while (start + needle.len <= haystack.len) : (start += 1) {
        var i: usize = 0;
        while (i < needle.len and
            std.ascii.toLower(haystack[start + i]) == std.ascii.toLower(needle[i])) : (i += 1)
        {}
        if (i == needle.len) return true;
    }
    return false;
}

fn contentDeclaresPlaceholder(content: []const u8) bool {
    const markers = [_][]const u8{
        "TODO:",
        "TODO ",
        "simulación del",
        "simulacion del",
        "omitida por",
        "omitido por",
        "omitted for",
        "would be implemented",
        "se implementaría",
        "se implementaria",
        "pseudocódigo",
        "pseudocodigo",
        "placeholder implementation",
    };
    for (markers) |marker| {
        if (containsAsciiIgnoreCase(content, marker)) return true;
    }
    return false;
}

test "E2E-RESULT: Go se compila y ejecuta mediante go run" {
    const cmd = inferCommand("main.go") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("go", cmd.exe);
    try std.testing.expectEqual(CommandKind.go_run, cmd.kind);
}

test "E2E-RESULT: una tarea ejecutar solo es exitosa si corrio o espera aprobacion" {
    const not_run = Superagent.ExecOutcome{
        .ran = false,
        .exit_code = 0,
        .needs_approval = false,
        .stderr = "",
    };
    try std.testing.expect(!taskExecutionSucceeded(.ejecutar, true, true, not_run));

    const failed = Superagent.ExecOutcome{
        .ran = true,
        .exit_code = 1,
        .needs_approval = false,
        .stderr = "compile failed",
    };
    try std.testing.expect(!taskExecutionSucceeded(.ejecutar, true, true, failed));

    const passed = Superagent.ExecOutcome{
        .ran = true,
        .exit_code = 0,
        .needs_approval = false,
        .stderr = "",
    };
    try std.testing.expect(taskExecutionSucceeded(.ejecutar, true, true, passed));

    const pending = Superagent.ExecOutcome{
        .ran = false,
        .exit_code = 0,
        .needs_approval = true,
        .stderr = "permission required",
    };
    try std.testing.expect(taskExecutionSucceeded(.ejecutar, true, true, pending));
    try std.testing.expect(taskExecutionSucceeded(.programar, true, true, not_run));
}

test "B3: una tarea programar cuyo artefacto se ejecuto y fallo NO es task_done (orden 159)" {
    // Orden 159 medida (runtime.db): t1 escribio t1.py, `python t1.py` murio con
    // SyntaxError (exit 1), y aun asi se emitio task_done success:true — luego la
    // orden cerraba order_failed cause=all_tasks_failed. El mismo criterio que el
    // auto-auditor usa para marcar la tarea como fallida ("ejecuto y devolvio
    // exit_code != 0") debe gobernar el evento per-tarea.
    const syntax_error = Superagent.ExecOutcome{
        .ran = true,
        .exit_code = 1,
        .needs_approval = false,
        .stderr = "  File \"orden-159\\t1.py\", line 1\nSyntaxError: invalid syntax",
    };
    try std.testing.expect(!taskExecutionSucceeded(.programar, true, true, syntax_error));
    // El mismo programa, corriendo bien, si es exitoso.
    const ran_ok = Superagent.ExecOutcome{
        .ran = true,
        .exit_code = 0,
        .needs_approval = false,
        .stderr = "",
    };
    try std.testing.expect(taskExecutionSucceeded(.programar, true, true, ran_ok));
    // Una auditoria textual (sin artefacto ejecutable) no se castiga: sigue exitosa.
    const sin_ejecutar = Superagent.ExecOutcome{
        .ran = false,
        .exit_code = 0,
        .needs_approval = false,
        .stderr = "",
    };
    try std.testing.expect(taskExecutionSucceeded(.auditar, true, true, sin_ejecutar));
}

test "CK-MOT-034: uso sin argumentos con exit 1 no tumba la tarea" {
