test "CK-MOT-034: usageOnlyExit reconoce el mensaje de uso con exit 1 y con exit 2" {
    // Python escribiendo su uso por stderr (el caso medido, con CRLF).
    try std.testing.expect(usageOnlyExit(1, "", "Uso: python rpn.py 'expresion'\r\n"));
    try std.testing.expect(usageOnlyExit(2, "", "Uso: python rpn.py 'expresion'\r\n"));
    // Unix tools escribiendo su uso por stdout, con mayusculas o con prefijo de programa.
    try std.testing.expect(usageOnlyExit(1, "usage: cli.py <ruta> [opciones]\n", ""));
    try std.testing.expect(usageOnlyExit(2, "USAGE:\n  tool [opciones] entrada salida\n", ""));
    try std.testing.expect(usageOnlyExit(1, "", "pdftotext: usage: pdftotext entrada.pdf\n"));
    // Lineas en blanco antes del uso.
    try std.testing.expect(usageOnlyExit(1, "\r\n\r\nUsage: backup.py <origen> <destino>\r\n", ""));
}

test "CK-MOT-034: usageOnlyExit NO reconoce usos con traza de interprete y exit 0" {
    // Fallo real de Python.
    try std.testing.expect(!usageOnlyExit(1, "", "Traceback (most recent call last):\n  File \"cli.py\", line 4, in <module>\nTypeError: bad operand\n"));
    try std.testing.expect(!usageOnlyExit(1, "", "SyntaxError: invalid syntax\n"));
    try std.testing.expect(!usageOnlyExit(1, "algo\n", "ModuleNotFoundError: No module named 'foo'\n"));
    // Fallo real de node.
    try std.testing.expect(!usageOnlyExit(1, "", "throw err;\n^Error: Cannot find module './x'\n"));
    try std.testing.expect(!usageOnlyExit(1, "", "ReferenceError: foo is not defined\n"));
    // Un programa que imprime su uso y ademas una traza: es fallo real.
    try std.testing.expect(!usageOnlyExit(1, "usage: cli.py <exp>\n", "Traceback (most recent call last):\n"));
    // Sin mensaje de uso: como hoy, es un fallo de ejecucion.
    try std.testing.expect(!usageOnlyExit(1, "", "AssertionError: 3 != 7\n"));
    try std.testing.expect(!usageOnlyExit(1, "", ""));
    try std.testing.expect(!usageOnlyExit(1, "resultado: 7\n", ""));
    // exit 0: como hoy, nunca se marca.
    try std.testing.expect(!usageOnlyExit(0, "", "usage: cli.py <exp>\n"));
    try std.testing.expect(!usageOnlyExit(0, "de acuerdo\n", ""));
}

