test "CK-MOT-034 R2-2b: trazas Java/Go/Rust/panic/error en minuscula son fallo real" {
    try std.testing.expect(!usageOnlyExit(1, "", "usage: java App\nException in thread \"main\" java.lang.RuntimeException: boom\n"));
    try std.testing.expect(!usageOnlyExit(1, "usage: prog\n", "panic: runtime error: index out of range\n"));
    try std.testing.expect(!usageOnlyExit(1, "", "Usage: prog\nthread 'main' panicked at src/main.rs:3:5\n"));
    try std.testing.expect(!usageOnlyExit(1, "", "usage: tool\nfatal error: no input files\n"));
    try std.testing.expect(!usageOnlyExit(1, "", "usage: tool\nUnhandled exception. System.NullReferenceException\n"));
    try std.testing.expect(!usageOnlyExit(1, "", "usage: tool\nSegmentation fault\n"));
    // Salida larga: el uso esta en la primera linea y la traza llega cientos de
    // lineas despues. La traza se busca en TODO el texto, no solo al principio.
    try std.testing.expect(!usageOnlyExit(1, "Usage: tool <args>\n" ++ ("opcion valida\n" ** 200) ++ "Traceback (most recent call last):\n", ""));
}

