test "CK-MOT-034 R2-3: exec_skipped lleva command y file" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.setEventConn(runtime, 991342);
    var outcome = Superagent.ExecOutcome{
        .ran = true,
        .exit_code = 1,
        .needs_approval = false,
        .stderr = "Uso: python rpn.py 'expresion'\n",
    };
    sa.marcarUsoSinArgumentos("T1", "python rpn.py", "rpn.py", &outcome);
    const stmt = try runtime.prepare("SELECT payload_json FROM events WHERE kind = 'exec_skipped' ORDER BY id DESC LIMIT 1");
    defer runtime.finalize(stmt);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
    const pptr = db.c.sqlite3_column_text(stmt, 0);
    const plen = db.c.sqlite3_column_bytes(stmt, 0);
    const payload = pptr[0..@intCast(plen)];
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"command\":\"python rpn.py\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"file\":\"rpn.py\"") != null);
}

test "CK-MOT-034 R2-4: governedExecute (punto de llamada real) marca uso sin argumentos" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.permission_config.mode = .bypass;
    sa.plan_approved = true;
    sa.executor_spawn_fn = struct {
        fn f(a: std.mem.Allocator, _: []const u8, _: []const []const u8, _: []const u8, _: u32, _: usize, _: ?executor.StreamSink, _: ?*anyopaque, _: []const u8) executor.ExecutorError!executor.RunResult {
            return .{ .exit_code = 1, .stdout = try a.dupe(u8, ""), .stderr = try a.dupe(u8, "Uso: python rpn.py 'expresion'\r\n") };
        }
    }.f;
    const task = planner.PlannedTask{
        .id = "T1",
        .task_type = .programar,
        .department = "programacion",
        .description = "write rpn.py",
        .contract_fields = &.{},
        .depends_on = &.{},
    };
    const artifacts = [_]worker_backend.Artifact{
        .{ .path = "rpn.py", .content = "import sys\nprint(sys.argv[1])\n" },
    };
    const path = (try workspace.persistTask(allocator, 991340, task, &artifacts)) orelse return error.TestUnexpectedResult;
    defer allocator.free(path);
    var outputs = std.ArrayList(WorkerOutput).empty;
    defer {
        for (outputs.items) |o| {
            allocator.free(o.worker_id);
            allocator.free(o.stream);
            if (o.task_id.len > 0) allocator.free(o.task_id);
            allocator.free(o.text);
        }
        outputs.deinit(allocator);
    }
    var pending = std.ArrayList(ApprovalRequest).empty;
    defer {
        for (pending.items) |r| r.deinit(allocator);
        pending.deinit(allocator);
    }
    const outcome = try sa.governedExecute(path, "T1", &outputs, &pending);
    defer {
        allocator.free(outcome.stderr);
        if (outcome.stdout) |stdout| allocator.free(stdout);
    }
    try std.testing.expect(outcome.ran);
    try std.testing.expect(outcome.usage_only);
    try std.testing.expect(taskExecutionSucceeded(.ejecutar, true, true, outcome));
}

