fn unassigned(allocator: std.mem.Allocator, task_id: []const u8, reason: []const u8) !ModelAssignment {
    return ModelAssignment{
        .task_id = task_id,
        .assigned = false,
        .provider_name = try allocator.dupe(u8, "none"),
        .model_name = try allocator.dupe(u8, "none"),
        .is_free = false,
        .reason = try allocator.dupe(u8, reason),
        .fallbacks = try allocator.alloc(ModelChoice, 0),
    };
}

/// Vuelca como eventos los intentos anotados por un LiveLlm por-tarea.
///
/// El LiveLlm de cada tarea NO tiene `event_conn` (FIX-SEGFAULT-P0: varios hilos
/// de la misma ola escribiendo en una sola conexión SQLite mataban el proceso),
/// así que sus intentos no llegaban a la traza. Se emiten desde aquí, bajo el
/// mismo mutex que `task_done`/`task_failed`, que es el punto donde ya está
/// serializada la escritura de eventos.
fn setModelUsedFromLive(
    allocator: std.mem.Allocator,
    llm: *const live_worker.LiveLlm,
    model_used: *[]const u8,
    owned_model: *?[]u8,
) void {
    const attempts = llm.takeAttempts();
    if (attempts.len == 0) {
        if (owned_model.*) |old| allocator.free(old);
        owned_model.* = null;
        model_used.* = "unknown";
        return;
    }
    const actual = attempts[attempts.len - 1].model;
    const copy = allocator.dupe(u8, actual) catch {
        if (owned_model.*) |old| allocator.free(old);
        owned_model.* = null;
        model_used.* = "unknown";
        return;
    };
    if (owned_model.*) |old| allocator.free(old);
    owned_model.* = copy;
    model_used.* = copy;
}

fn emitLlmAttempts(ctx: anytype, pt: planner.PlannedTask, llm: *live_worker.LiveLlm) void {
    const intentos = llm.takeAttempts();
    if (intentos.len == 0) return;
    ctx.mutex.lock();
    defer ctx.mutex.unlock();
    for (intentos) |a| {
        const is_ok = std.mem.eql(u8, a.status, "ok");
        var out: std.Io.Writer.Allocating = .init(ctx.sa.allocator);
        defer out.deinit();
        var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
        js.beginObject() catch continue;
        js.objectField("task_id") catch continue;
        js.write(pt.id) catch continue;
        js.objectField("provider") catch continue;
        js.write(a.provider) catch continue;
        js.objectField("model") catch continue;
        js.write(a.model) catch continue;
        js.objectField("status") catch continue;
        js.write(a.status) catch continue;
        // 10-nov (remate D3): un intento ok no lleva motivo de fallo. Antes
        // `reason()` sin código HTTP devolvía «fallo de transporte o respuesta
        // no valida» y el evento `task_provider_ok` lo arrastraba.
        if (!is_ok) {
            js.objectField("http_status") catch continue;
            js.write(a.diagnostic.http_status) catch continue;
            js.objectField("reason") catch continue;
            js.write(if (std.mem.eql(u8, a.status, "empty")) "respuesta vacia o sin contrato JSON valido" else a.diagnostic.reason()) catch continue;
            js.objectField("excerpt") catch continue;
            js.write(a.diagnostic.message()) catch continue;
            // Remate D2: lo que la Parte A ya sabe del 429 (cuota diaria)
            // viaja con el intento para explicar después por qué quedó sin
            // auditar una subtarea delegada.
            js.objectField("rate_daily") catch continue;
            js.write(a.diagnostic.rate.daily) catch continue;
        }
        if (a.key_label.len > 0) {
            js.objectField("key_label") catch continue;
            js.write(a.key_label) catch continue;
        }
        if (a.error_name.len > 0) {
            js.objectField("error_name") catch continue;
            js.write(a.error_name) catch continue;
        }
        if (a.sample.len > 0) {
            js.objectField("sample") catch continue;
            js.write(a.sample) catch continue;
            // El tamaño completo y si cerró el array van SIEMPRE que haya muestra:
            // sin ellos, un `empty` no distingue "no contestó" de "escribió 8 KB y
            // se cortó", que piden arreglos opuestos.
            js.objectField("total_len") catch continue;
            js.write(a.total_len) catch continue;
            js.objectField("closed") catch continue;
            js.write(a.closed) catch continue;
        }
        js.endObject() catch continue;
        ctx.sa.recordEvent(if (is_ok) "task_provider_ok" else "task_provider_failed", out.written());
        // GOBERNANZA-HIBRIDO-LEDGER: un intento sobre modelo is_free=0 consumió
        // autorización de pago — la fila ESCALATION justificada va por la cola
        // serializada (FIX-ENGINE-8: el Router de producción tiene ledger=null
        // a propósito, así que sin este apunte el gasto quedaba sin motivo).
        if (!ctx.sa.isModelFree(a.provider, a.model)) {
            const nota = std.fmt.allocPrint(
                ctx.sa.allocator,
                "politica de gobernanza: etapa '{s}' asignada a pago (intento status={s} key={s})",
                .{ pt.task_type.toText(), a.status, if (a.key_label.len > 0) a.key_label else "?" },
            ) catch "";
            defer if (nota.len > 0) ctx.sa.allocator.free(nota);
            Superagent.appendAuditEntry(ctx.sa.allocator, &ctx.audit_entries, ctx.sa.event_conn, ctx.sa.event_order_id, .{
                .ts = 0,
                .subject_kind = "model_router",
                .subject_id = Superagent.idToInt(pt.id),
                .action = "ESCALATION",
                .verdict = "PASS",
                .model_id = a.model,
                .provider = a.provider,
                .evidence_ref = pt.id,
                .notes = nota,
            });
        }
    }
    llm.clearAttempts();
}

fn findAssignment(assignments: []const ModelAssignment, task_id: []const u8) ?ModelAssignment {
    for (assignments) |a| {
        if (std.mem.eql(u8, a.task_id, task_id)) return a;
    }
    return null;
}

fn findPlannedTask(tasks: []const planner.PlannedTask, task_id: []const u8) ?planner.PlannedTask {
    for (tasks) |task| {
        if (std.mem.eql(u8, task.id, task_id)) return task;
    }
    return null;
}

fn effectiveDependencyIds(
    allocator: std.mem.Allocator,
    task: planner.PlannedTask,
    all_tasks: []const planner.PlannedTask,
) ![][]const u8 {
    if (!isConsumerType(task.task_type) or task.depends_on.len != 0) {
        return allocator.dupe([]const u8, task.depends_on);
    }

    var count: usize = 0;
    for (all_tasks) |candidate| {
        if (isProducerType(candidate.task_type) and !std.mem.eql(u8, candidate.id, task.id)) count += 1;
    }
    const deps = try allocator.alloc([]const u8, count);
    var i: usize = 0;
    for (all_tasks) |candidate| {
        if (isProducerType(candidate.task_type) and !std.mem.eql(u8, candidate.id, task.id)) {
            deps[i] = candidate.id;
            i += 1;
        }
    }
    return deps;
}

fn dependenciesSucceeded(
    allocator: std.mem.Allocator,
    task: planner.PlannedTask,
    all_tasks: []const planner.PlannedTask,
    results: []const Superagent.TaskRunResult,
) bool {
    const dependencies = effectiveDependencyIds(allocator, task, all_tasks) catch return false;
    defer allocator.free(dependencies);
    for (dependencies) |dependency_id| {
        var found_success = false;
        for (results) |result| {
            if (std.mem.eql(u8, result.task_id, dependency_id)) {
                found_success = result.success and result.integrated;
                break;
            }
        }
        if (!found_success) return false;
    }
    return true;
}

fn dependencySavedPath(
    task: planner.PlannedTask,
    results: []const Superagent.TaskRunResult,
) ?[]const u8 {
    for (task.depends_on) |dependency_id| {
        for (results) |result| {
            if (!std.mem.eql(u8, result.task_id, dependency_id)) continue;
            if (result.success and result.integrated) return result.saved_path;
        }
    }
    return null;
}

test "E2E-RESULT: una dependencia fallida bloquea testing y auditoria" {
    var dependencies = [_][]const u8{"t1"};
    const task = planner.PlannedTask{
        .id = "t2",
        .task_type = .testear,
        .department = "testing",
        .description = "probar",
        .contract_fields = &.{},
        .depends_on = &dependencies,
    };
    const failed = [_]Superagent.TaskRunResult{.{
        .task_id = "t1",
        .artifacts = &.{},
        .success = false,
        .error_msg = "provider exhausted",
        .integrated = false,
        .model_used = "none",
        .exec = .{ .ran = false, .exit_code = 0, .needs_approval = false, .stderr = "" },
        .saved_path = null,
    }};
    try std.testing.expect(!dependenciesSucceeded(std.testing.allocator, task, &.{task}, &failed));
    try std.testing.expect(!dependenciesSucceeded(std.testing.allocator, task, &.{task}, &.{}));
}

test "E2E-RESULT: dependencia implicita fallida bloquea consumidor sin depends_on y no llama al worker" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var mp = planner.MockPlanner.init(allocator);
    const pb = mp.backend();
    defer pb.deinit();

    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    var outcome = try sa.processOrder("proj-implicit-dep", "construye una calculadora CLI en C con tests", &.{}, pb, null, null);
    defer outcome.deinit();

    // El plan conserva un consumidor sin dependencia explicita: resolveWaves debe
    // aplicarle la misma dependencia implicita que uso para ordenar las olas.
    const old_deps = outcome.plan.tasks[1].depends_on;
    for (old_deps) |dep| allocator.free(dep);
    allocator.free(old_deps);
    outcome.plan.tasks[1].depends_on = try allocator.alloc([]const u8, 0);

    // t1 falla por respuesta invalida. Si t2 se despacha, consume la segunda
    // respuesta y el test detecta la fuga de la regla implicita.
    //
    // t1 (productor) muere sin artefacto y ahora se reintenta de forma
    // acotada — por eso el worker puede llamarse más de una vez, siempre para t1.
    // Lo que este test garantiza sigue intacto: los consumidores t2/t3 NUNCA se
    // despachan mientras t1 siga fallido. El discriminador es el encabezado `TAREA`
    // del propio prompt (el manifiesto del plan lista todas las descripciones, así
    // que buscar la descripción suelta daría falsos positivos).
    const ImplicitLlm = struct {
        calls: usize = 0,
        consumer_calls: usize = 0,
        fn call(ctx: *anyopaque, _: []const u8, user: []const u8) []const u8 {
            const self: *@This() = @ptrCast(@alignCast(ctx));
            self.calls += 1;
            if (std.mem.indexOf(u8, user, "TAREA\nEscribir y ejecutar pruebas") != null or
                std.mem.indexOf(u8, user, "TAREA\nAuditar la implementación") != null)
            {
                self.consumer_calls += 1;
            }
            // El reintento tampoco produce un artefacto válido: t1 sigue fallido y
            // sus consumidores siguen bloqueados por la dependencia implícita.
            return if (self.calls == 1) "not-json" else "[{\"field\":\"tests_passed\",\"content\":\"1\"}]";
        }
    };
    var llm = ImplicitLlm{};
    var dr = try sa.approveAndDispatch(&outcome, ImplicitLlm.call, &llm, null);
    defer dr.deinit(allocator);

    try std.testing.expectEqual(@as(usize, 0), llm.consumer_calls);
    try std.testing.expect(llm.calls >= 1);
    try std.testing.expect(dr.failed_count >= 2);
}

/// AUDIT-UNAVAILABLE-P0 (S22, orden 500): clasificación estricta del veredicto
/// de una tarea `auditar`.
///  - `pass`/`fail`: el auditor-modelo produjo un veredicto real — la primera
///    palabra del campo `verdict` es de la familia PASS o FAIL, con borde de
///    palabra. Un "FAIL" sin razón sigue siendo un FAIL del producto.
///  - `unavailable`: el auditor NO produjo veredicto usable — proveedor
///    agotado, respuesta sin JSON, campo `verdict` ausente, vacío o con token
///    irreconocible ("PASSING", ruido). Ni PASS ni FAIL: es la AUSENCIA de
///    revisión, y bloquea la entrega hasta un reintento manual del usuario.
///  - `none`: la tarea no es de auditoría (estado por defecto del resto).
pub const AuditVerdict = enum { none, pass, fail, unavailable };

/// Lee el campo `verdict` y lo clasifica estrictamente. Un token que no es
/// reconocible NO vale como PASS — "PASSING..." queda fuera por borde de
/// palabra, igual que un texto libre que jamás fue un veredicto.
/// comprueba las citas `archivo:línea` del informe de una tarea
/// `auditar` con la misma herramienta de lectura que usó el auditor. Deja
/// constancia en `audit_citations_v1` siempre que haya citas; si alguna no se
/// sostiene, la tarea pasa a `audit_unavailable`.
/// ¿La orden en curso se declara auditoría? El texto en memoria si lo hay;
/// si no, el que quedó guardado en `orders` (CLI, MCP, rehidratación).
fn ordenDeclaraAuditoria(sa: *Superagent) bool {
    return ordenEsAuditoria(sa, sa.event_order_id);
}

fn ordenEsAuditoria(sa: *Superagent, order_id: i64) bool {
    if (sa.order_text) |t| return esOrdenDeAuditoria(t);
    if (order_id <= 0) return false;
    const stmt = sa.runtime.prepare("SELECT user_prompt FROM orders WHERE id=?") catch return false;
    defer sa.runtime.finalize(stmt);
    db.bindInt(stmt, 1, order_id) catch return false;
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return false;
    const txt = db.c.sqlite3_column_text(stmt, 0) orelse return false;
    return esOrdenDeAuditoria(std.mem.span(txt));
}

fn verificaCitasDelInforme(sa: *Superagent, allocator: std.mem.Allocator, order_id: i64, task_id: []const u8, run_res: anytype) void {
    var informe = std.ArrayList(u8).empty;
    defer informe.deinit(allocator);
    for (run_res.artifacts) |art| {
        informe.appendSlice(allocator, art.content) catch return;
        informe.append(allocator, '\n') catch return;
    }
    var root_buf: [4096]u8 = undefined;
    const raiz = workspace.effectiveRoot(&root_buf);
    // FASE0-B2: lo que escribió la orden está en `<raíz>\orden-<id>\`; el
    // auditor lo cita relativo a esa carpeta (verificaDeOrden).
    var res = audit_citas.verificaDeOrden(allocator, raiz, order_id, informe.items) catch return;
    defer res.deinit(allocator);
    // En una orden que SE DECLARA auditoría, el informe tiene que traer al
    // menos una cita comprobable. Medido en vivo el 22-09 (orden 8 de la
    // prueba): el modelo de respaldo «auditó» escribiendo un archivo Zig
    // inventado, sin citar nada, y la orden cerró done. Las auditorías dentro
    // de un encargo de construcción no cambian: ahí no se exige cita.
    const exige = ordenDeclaraAuditoria(sa);
    if (res.total == 0 and !exige) return;

    var ev: std.Io.Writer.Allocating = .init(allocator);
    defer ev.deinit();
    var js: std.json.Stringify = .{ .writer = &ev.writer, .options = .{} };
    js.beginObject() catch return;
    js.objectField("task_id") catch return;
    js.write(task_id) catch return;
    js.objectField("citas") catch return;
    js.write(res.total) catch return;
    js.objectField("verificadas") catch return;
    js.write(res.verificadas) catch return;
    js.objectField("solo_existencia") catch return;
    js.write(res.solo_existencia) catch return;
    js.objectField("fallidas") catch return;
    js.write(res.fallidas) catch return;
    js.objectField("exige_citas") catch return;
    js.write(exige) catch return;
    if (res.fallidas > 0) {
        js.objectField("detalle") catch return;
        js.write(res.resumen) catch return;
    }
    js.endObject() catch return;
    sa.recordEvent("audit_citations_v1", ev.written());

    const comprobables = res.verificadas + res.solo_existencia;
    if (res.fallidas == 0 and (!exige or comprobables > 0)) return;
    run_res.audit_verdict = .unavailable;
    run_res.success = false;
    run_res.integrated = false;
    const msg = (if (res.fallidas > 0)
        std.fmt.allocPrint(allocator, "audit_unavailable: {d} de {d} citas del informe no se sostienen al abrir el archivo: {s}", .{ res.fallidas, res.total, res.resumen })
    else
        allocator.dupe(u8, "audit_unavailable: la orden es una auditoría y el informe no cita ninguna evidencia comprobable (archivo:línea); un veredicto sin evidencia no es una auditoría")) catch return;
    allocator.free(run_res.error_msg);
    run_res.error_msg = msg;
}

fn auditVerdictOf(artifacts: []const worker_backend.Artifact) AuditVerdict {
    for (artifacts) |artifact| {
        if (!std.ascii.eqlIgnoreCase(artifact.path, "verdict")) continue;
        const trimmed = std.mem.trim(u8, artifact.content, " \t\r\n`*_#[]{}()\"");
        if (failureToken(trimmed)) return .fail;
        const end = std.mem.indexOfAny(u8, trimmed, " \t\r\n:;,.=-") orelse trimmed.len;
        const token = trimmed[0..end];
        if (std.ascii.eqlIgnoreCase(token, "pass") or
            std.ascii.eqlIgnoreCase(token, "passed") or
            std.ascii.eqlIgnoreCase(token, "ok") or
            std.ascii.eqlIgnoreCase(token, "apto") or
            std.ascii.eqlIgnoreCase(token, "aprobado") or
            std.ascii.eqlIgnoreCase(token, "approved")) return .pass;
        return .unavailable;
    }
    return .unavailable;
}

fn failureToken(content: []const u8) bool {
    const trimmed = std.mem.trim(u8, content, " \t\r\n`*_#[]{}()\"");
    const end = std.mem.indexOfAny(u8, trimmed, " \t\r\n:;,.=-") orelse trimmed.len;
    const token = trimmed[0..end];
    return std.ascii.eqlIgnoreCase(token, "fail") or
        std.ascii.eqlIgnoreCase(token, "failed") or
        std.ascii.eqlIgnoreCase(token, "failure") or
        std.ascii.eqlIgnoreCase(token, "reject") or
        std.ascii.eqlIgnoreCase(token, "rejected") or
        std.ascii.eqlIgnoreCase(token, "fallo") or
        std.ascii.eqlIgnoreCase(token, "fallida") or
        std.ascii.eqlIgnoreCase(token, "fallido");
}

fn concreteAuditFailureReason(artifacts: []const worker_backend.Artifact) ?[]const u8 {
    for (artifacts) |artifact| {
        if (!std.ascii.eqlIgnoreCase(artifact.path, "verdict")) continue;
        const trimmed = std.mem.trim(u8, artifact.content, " \t\r\n`*_#[]{}()\"");
        if (!failureToken(trimmed)) continue;
        const end = std.mem.indexOfAny(u8, trimmed, " \t\r\n:;,.=-") orelse trimmed.len;
        if (end == trimmed.len) continue;
        const reason = std.mem.trim(u8, trimmed[end..], " \t\r\n:;,.=-");
        if (reason.len > 0) return trimmed;
    }
    return null;
}

/// Un reporte de pruebas/auditoria que declara fallo es evidencia negativa aunque
/// el JSON tenga todos los campos requeridos. Solo interpreta campos semánticos
/// conocidos para no confundir palabras como "fail-safe" dentro de código fuente.
/// Contenido del artefacto que corresponde a un archivo YA ESCRITO, para adjuntarlo al
/// evento `file_written` (tarjeta de diff del chat, P3).
///
/// Primero por nombre: desde M1 el modelo entrega `{"field":"index.html"}`, así que el
/// campo casa con el archivo. Si no casa ninguno —entrega de un solo campo `source`, o
/// varios archivos troceados de un mismo texto— solo se devuelve el cuerpo cuando hay UN
/// único archivo escrito; con varios no se puede saber cuál es cuál, y adjuntar el
/// contenido de otro archivo sería peor que no adjuntar ninguno.
fn artifactContentFor(
    artifacts: []const worker_backend.Artifact,
    written_name: []const u8,
) ?[]const u8 {
    // D2: primero la ruta relativa completa (`docs/dos.txt` = `docs\dos.txt`);
    // después, como siempre, el último componente.
    for (artifacts) |art| {
        if (samePathLoose(art.path, written_name)) return art.content;
    }
    for (artifacts) |art| {
        if (std.ascii.eqlIgnoreCase(std.fs.path.basename(art.path), std.fs.path.basename(written_name))) return art.content;
    }
    return null;
}

/// Igualdad de rutas relativas sin distinguir mayúsculas ni '/' de '\'.
fn samePathLoose(a: []const u8, b: []const u8) bool {
    if (a.len != b.len) return false;
    for (a, b) |x, y| {
        const nx = if (x == '/') '\\' else std.ascii.toLower(x);
        const ny = if (y == '/') '\\' else std.ascii.toLower(y);
        if (nx != ny) return false;
    }
    return true;
}

/// E-GOV.1: diagnóstico del gate determinista para la fila AUDIT FAIL. Dice
/// tarea y archivo, qué se esperaba y qué se observó, la causa registrada, el
/// código de salida con su stderr (acotado) y, por archivo, la omisión que lo
/// invalida. Nunca devuelve una cadena vacía.
fn deterministicFailureNotes(allocator: std.mem.Allocator, result: Superagent.TaskRunResult, task: ?planner.PlannedTask) ![]u8 {
    var out: std.Io.Writer.Allocating = .init(allocator);
    defer out.deinit();
    const w = &out.writer;
    try w.print("DETERMINISTIC_GATE: tarea {s}; archivo {s}. ", .{ result.task_id, result.saved_path orelse "sin artefacto" });
    try w.print("Se esperaba success=true e integrated=true; observado success={any}, integrated={any}. ", .{ result.success, result.integrated });
    if (result.error_msg.len > 0) try w.print("Causa: {s}. ", .{result.error_msg[0..@min(result.error_msg.len, 2048)]});
    if (result.exec.ran and result.exec.exit_code != 0 and !result.exec.timed_out)
        try w.print("Se esperaba exit=0; observado exit={d}; stderr: {s}. ", .{ result.exec.exit_code, result.exec.stderr[0..@min(result.exec.stderr.len, 1024)] });
    if (!result.restored) {
        for (result.artifacts) |artifact| {
            if (artifact.content.len == 0) continue;
            if (artifact_quality.invalidReason(artifact.path, artifact.content, artifact.inherited_placeholders)) |observed|
                try w.print("Archivo {s}: se esperaba contenido completo sin nuevas omisiones; observado: {s}. ", .{ artifact.path, observed });
        }
    }
    if (task) |pt| {
        if (taskArtifactsDeclareFailure(pt.task_type, result.artifacts)) try w.writeAll("Se esperaba veredicto PASS/exit=0; el artefacto declara FAIL o exit no cero. ");
        if (pt.task_type == .testear and pt.depends_on.len > 0 and !Superagent.hasExecutableTestEvidence(result)) try w.writeAll("Se esperaba un comando de test exitoso sobre la revisión del productor; no hay evidencia ejecutable. ");
    }
    return allocator.dupe(u8, out.written());
}

test "E-GOV.1 rondas 4 y 5: el checkpoint restaurado se valida archivo por archivo por la raiz confinada" {
    const a = std.testing.allocator;
    var threaded = std.Io.Threaded.init(a, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.createDirPath(io, "src");
    try tmp.dir.writeFile(io, .{ .sub_path = "main.py", .data = "def main():\n    return 1\n" });
    try tmp.dir.writeFile(io, .{ .sub_path = "src/util.py", .data = "def util():\n    return 2\n" });
    const root = try tmp.dir.realPathFileAlloc(io, ".", a);
    defer a.free(root);
    const primary = try std.fs.path.join(a, &.{ root, "main.py" });
    defer a.free(primary);
    var runtime = try openRuntime(a);
    defer runtime.close();
    var sa = Superagent.init(a, runtime, null, NoopMemory.backend(), 1);
    const artifacts = [_]worker_backend.Artifact{
        .{ .path = "main.py", .content = "present" },
        .{ .path = "src\\util.py", .content = "present" },
        .{ .path = "borrado.py", .content = "" },
    };
    var result = Superagent.TaskRunResult{
        .task_id = "T1",
        .artifacts = &artifacts,
        .success = true,
        .error_msg = "",
        .integrated = true,
        .model_used = "checkpoint",
        .exec = .{ .ran = false, .exit_code = 0, .needs_approval = false, .stderr = "" },
        .saved_path = primary,
        .restored = true,
        .worktree_root = root,
    };
    // Todo completo: pasa, y el borrado persistido no se intenta leer.
    try std.testing.expect(!sa.isResultContentTriviallyInvalid(result, primary, null, false));
    // Una omision nueva en un archivo que NO es el principal ya no se cuela.
    try tmp.dir.writeFile(io, .{ .sub_path = "src/util.py", .data = "def util():\n    pass  # TODO: implementar\n" });
    try std.testing.expect(sa.isResultContentTriviallyInvalid(result, primary, null, false));
    try tmp.dir.writeFile(io, .{ .sub_path = "src/util.py", .data = "def util():\n    return 2\n" });
    // Un archivo presente que desaparecio invalida el checkpoint.
    try tmp.dir.deleteFile(io, "src/util.py");
    try std.testing.expect(sa.isResultContentTriviallyInvalid(result, primary, null, false));
    // Un principal fuera de la raiz confinada no se lee.
    result.saved_path = "C:\\Windows\\win.ini";
    try std.testing.expect(sa.isResultContentTriviallyInvalid(result, "C:\\Windows\\win.ini", null, false));
}

test "E-GOV.1: el FAIL del gate explica archivo, esperado, observado y causa" {
    const a = std.testing.allocator;
    const artifacts = [_]worker_backend.Artifact{.{ .path = "src/timed.py", .content = "def f():\n    pass  # TODO: implementar\n" }};
    const result = Superagent.TaskRunResult{
        .task_id = "T4",
        .artifacts = &artifacts,
        .success = false,
        .error_msg = "BUG_SEEDED",
        .integrated = false,
        .model_used = "",
        .exec = .{ .ran = true, .exit_code = 2, .needs_approval = false, .stderr = "Traceback: NameError" },
        .saved_path = "C:\\ws\\orden-4\\src\\timed.py",
    };
    const notes = try deterministicFailureNotes(a, result, null);
    defer a.free(notes);
    for ([_][]const u8{ "DETERMINISTIC_GATE: tarea T4", "orden-4", "success=false", "Causa: BUG_SEEDED", "observado exit=2", "NameError" }) |needle|
        try std.testing.expect(std.mem.indexOf(u8, notes, needle) != null);
    const bare = Superagent.TaskRunResult{ .task_id = "T1", .artifacts = &.{}, .success = false, .error_msg = "", .integrated = false, .model_used = "", .exec = .{ .ran = false, .exit_code = 0, .needs_approval = false, .stderr = "" }, .saved_path = null };
    const bare_notes = try deterministicFailureNotes(a, bare, null);
    defer a.free(bare_notes);
    try std.testing.expect(std.mem.indexOf(u8, bare_notes, "sin artefacto") != null);
}

fn taskArtifactsDeclareFailure(task_type: model_router.TaskType, artifacts: []const worker_backend.Artifact) bool {
    if (task_type != .testear and task_type != .auditar) return false;
    for (artifacts) |artifact| {
        if (task_type == .auditar and std.ascii.eqlIgnoreCase(artifact.path, "verdict")) {
            if (failureToken(artifact.content)) return true;
        }
        if (task_type == .testear and std.ascii.eqlIgnoreCase(artifact.path, "tests_passed")) {
            const value = std.mem.trim(u8, artifact.content, " \t\r\n");
            if (std.fmt.parseInt(i64, value, 10)) |count| {
                if (count <= 0) return true;
            } else |_| {
                if (failureToken(value)) return true;
            }
        }
    }
    return false;
}

/// A dependent audit verdict is evidence about its producer. Re-answering the
/// audit task can only rewrite that verdict; it cannot create new producer or
/// test evidence. Such audits may run again only through the existing
/// dependency-invalidation path after a producer changes.
fn genericCorrectionAllowed(task: planner.PlannedTask, artifacts: []const worker_backend.Artifact) bool {
    if (task.task_type == .testear and task.depends_on.len > 0) return false;
    if (task.task_type == .auditar and task.depends_on.len > 0 and taskArtifactsDeclareFailure(task.task_type, artifacts)) return false;
    return true;
}

test "TERMINAL-P0 P1-FALSE-GREEN: verdict FAIL y cero tests son fallos semanticos" {
    const audit = [_]worker_backend.Artifact{.{ .path = "verdict", .content = "FAIL: la salida real no coincide" }};
    const tests_zero = [_]worker_backend.Artifact{.{ .path = "tests_passed", .content = "0" }};
    const tests_ok = [_]worker_backend.Artifact{.{ .path = "tests_passed", .content = "3" }};
    const source = [_]worker_backend.Artifact{.{ .path = "source", .content = "const fail_safe = true;" }};

    try std.testing.expect(taskArtifactsDeclareFailure(.auditar, &audit));
    try std.testing.expect(taskArtifactsDeclareFailure(.testear, &tests_zero));
    try std.testing.expect(!taskArtifactsDeclareFailure(.testear, &tests_ok));
    try std.testing.expect(!taskArtifactsDeclareFailure(.programar, &source));
}

test "D3: auditor dependiente FAIL no entra en correccion generica" {
    const audit = [_]worker_backend.Artifact{.{ .path = "verdict", .content = "FAIL: la salida real no coincide" }};
    var deps = [_][]const u8{"producer"};
    const dependent_audit = planner.PlannedTask{
        .id = "audit",
        .task_type = .auditar,
        .department = "auditoria",
        .description = "verificar productor",
        .contract_fields = &.{},
        .depends_on = deps[0..],
    };
    try std.testing.expect(!genericCorrectionAllowed(dependent_audit, &audit));

    var standalone_audit = dependent_audit;
    standalone_audit.depends_on = &.{};
    try std.testing.expect(genericCorrectionAllowed(standalone_audit, &audit));
}

test "D3: solo un FAIL con razon concreta se promociona" {
    const concrete = [_]worker_backend.Artifact{.{ .path = "verdict", .content = "FAIL: falta validar el resultado" }};
    const generic = [_]worker_backend.Artifact{.{ .path = "verdict", .content = "FAIL" }};
    try std.testing.expect(concreteAuditFailureReason(&concrete) != null);
