test "D3: identidad de productor ignora el orden de campos" {
    const a = std.testing.allocator;
    const original = [_]worker_backend.Artifact{
        .{ .path = "app.js", .content = "export const add = (a,b) => a - b;" },
        .{ .path = "README.md", .content = "calculator" },
    };
    const same_content_reordered = [_]worker_backend.Artifact{
        .{ .path = "README.md", .content = "calculator" },
        .{ .path = "app.js", .content = "export const add = (a,b) => a - b;" },
    };
    const changed = [_]worker_backend.Artifact{
