    try std.testing.expect(!Superagent.artifactSetsEqual(a, &original, &changed));
}

const DependentAuditCorrectionCtx = struct {
    producer_response: []const u8,
    audit_fail_response: []const u8,
    correction_pass_response: []const u8,
    call_count: usize = 0,
};

fn dependentAuditCorrectionLlm(ctx: *anyopaque, _: []const u8, _: []const u8) []const u8 {
    const state: *DependentAuditCorrectionCtx = @ptrCast(@alignCast(ctx));
    state.call_count += 1;
    return switch (state.call_count) {
        1 => state.producer_response,
        2 => state.audit_fail_response,
        else => state.correction_pass_response,
    };
}

test "D3 E2E: auditor FAIL dependiente no se corrige con PASS textual" {
    const allocator = std.testing.allocator;
