        ,
        .audit_fail_response =
        \\ [{"field":"verdict","content":"FAIL"}]
        ,
        .correction_pass_response =
        \\ [{"field":"verdict","content":"PASS"}]
        ,
    };

    var dispatch = try sa.approveAndDispatch(&outcome, dependentAuditCorrectionLlm, &llm, null);
    defer dispatch.deinit(allocator);
    try std.testing.expectEqual(@as(usize, 2), llm.call_count);
    try std.testing.expect(dispatch.order_failed);
    try std.testing.expectEqual(@as(usize, 1), dispatch.failed_count);
}

const PromotedAuditEvidenceCtx = struct {
    producer_bug_response: []const u8,
    audit_fail_response: []const u8,
    producer_fixed_response: []const u8,
    audit_pass_response: []const u8,
    call_count: usize = 0,
};

fn promotedAuditEvidenceLlm(ctx: *anyopaque, _: []const u8, _: []const u8) []const u8 {
    const state: *PromotedAuditEvidenceCtx = @ptrCast(@alignCast(ctx));
    state.call_count += 1;
    return switch (state.call_count) {
        1 => state.producer_bug_response,
        2 => state.audit_fail_response,
        3 => state.producer_fixed_response,
        else => state.audit_pass_response,
    };
}

