const UnchangedProducerAuditCtx = struct {
    call_count: usize = 0,
    fn call(ctx: *anyopaque, _: []const u8, _: []const u8) []const u8 {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        self.call_count += 1;
        return switch (self.call_count) {
            1, 3 =>
            \\ [{"field":"source","content":"def add(a, b):\n    return a - b"}]
            ,
            2 =>
            \\ [{"field":"verdict","content":"FAIL: el resultado usa resta y debe sumar"}]
            ,
            // Si se volviera a llamar al auditor, un PASS narrativo no debe
            // ocultar que el productor de la llamada 3 fue idéntico.
            else =>
            \\ [{"field":"verdict","content":"PASS"}]
            ,
        };
    }
};

