fn openRuntime(allocator: std.mem.Allocator) !db.Connection {
    var conn = try db.Connection.open(allocator, ":memory:");
    errdefer conn.close();
    const migrator = db.Migrator.init(allocator);
    try migrator.migrate(conn, &db.runtime_schema);
    return conn;
}

test "E-33: una aprobacion pendiente del CLI queda visible para `devagents approvals`" {
    // El fallo real: 54 ordenes en `awaiting_approval` con la tabla `approvals`
    // VACIA. El camino de la cabina escribia la fila; el del CLI solo imprimia
    // el numero. Una orden pausada sin fila que resolver no la desbloquea nadie.
    //
    // La consulta de abajo es LITERALMENTE la de `cli_driver.cmdApprovals` y la
    // de `c_api.loadApprovals`: si la fila no aparece ahi, no existe para el
    // usuario, este el dato en memoria o no.
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    try runtime.exec("INSERT INTO orders (id, project_id, user_prompt, status, created_at) VALUES (77, 'cli', 'x', 'awaiting_approval', 1)");

    const req = ApprovalRequest{
        .task_id = "t1",
        .description = "Ejecutar python requiere aprobacion (modo: normal)",
        .command_prefix = "python",
        .exe = "python",
        .args_json = "[\"t1.py\"]",
    };
    const id = try persistApprovalRequest(runtime, req, 77, 1234);
    try std.testing.expect(id > 0);

    const stmt = try runtime.prepare("SELECT id, task_id, description, exe, order_id FROM approvals WHERE resolved = 0 ORDER BY id");
    defer runtime.finalize(stmt);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
    try std.testing.expectEqual(id, db.c.sqlite3_column_int64(stmt, 0));
    const exe_ptr = db.c.sqlite3_column_text(stmt, 3) orelse return error.TestUnexpectedNull;
    try std.testing.expectEqualStrings("python", exe_ptr[0..std.mem.len(exe_ptr)]);
    // `order_id` es lo que usa `checkAndAdvanceOrder` para saber a que orden
    // desbloquear: sin el, resolver la aprobacion no cierra nada.
    try std.testing.expectEqual(@as(i64, 77), db.c.sqlite3_column_int64(stmt, 4));
    // Una sola fila, no dos.
    try std.testing.expectEqual(db.c.SQLITE_DONE, db.c.sqlite3_step(stmt));
}

test "E-33: plan_approved decide si un comando corre o deja la orden pausada" {
    // Fija la semantica de P-EXEC-6 que el CLI incumplia. `governedExecuteRaw`
    // consulta `self.plan_approved`: con el plan aprobado, un `.ask` que NO
    // esta en la denylist se ejecuta inline; sin aprobar, genera una
    // ApprovalRequest con `exe` != null — y ese `exe` es exactamente lo que
    // pone la orden en `awaiting_approval` (approveAndDispatch, has_exec_approvals).
    //
    // La cabina ponia el flag (c_api.zig `sup.plan_approved = true`); el CLI no.
    // Mismo motor, dos comportamientos: por eso 54 ordenes del CLI se quedaron
    // pausadas con todo el trabajo hecho.
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();

    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.permission_config = .{ .mode = .normal };
    // Nada se ejecuta de verdad: el spawn es el mock de exit=0.
    sa.executor_spawn_fn = testExecutorSpawnOk;

    const Caso = struct { aprobado: bool, espera_aprobacion: bool };
    for ([_]Caso{
        .{ .aprobado = false, .espera_aprobacion = true },
        .{ .aprobado = true, .espera_aprobacion = false },
    }) |caso| {
        sa.plan_approved = caso.aprobado;
        var outputs = std.ArrayList(WorkerOutput).empty;
        defer {
            for (outputs.items) |o| {
                allocator.free(o.worker_id);
                allocator.free(o.stream);
                allocator.free(o.text);
            }
            outputs.deinit(allocator);
        }
        var pending = std.ArrayList(ApprovalRequest).empty;
        defer {
            for (pending.items) |a| a.deinit(allocator);
            pending.deinit(allocator);
        }

        const out = try sa.governedExecuteRaw("npm", &.{"--version"}, "t1", &outputs, &pending);
        defer allocator.free(out.stderr);
        defer if (out.stdout) |stdout| allocator.free(stdout);

        try std.testing.expectEqual(caso.espera_aprobacion, out.needs_approval);
        try std.testing.expectEqual(caso.espera_aprobacion, !out.ran);
        try std.testing.expectEqual(@as(usize, if (caso.espera_aprobacion) 1 else 0), pending.items.len);
        if (caso.espera_aprobacion) try std.testing.expect(pending.items[0].exe != null);
    }
}

