/// Planner exclusivo del test C-11: devuelve el plan conversacional que el
/// parser real desenvuelve de `{"kind":"chat","reply":...}` — understanding con
/// la respuesta y CERO tareas. Antes del cierre, esa orden quedaba `planned`
/// para siempre (62% de la muestra de planned en runtime.db).
const ChatFixturePlanner = struct {
    fn backend(self: *@This()) planner.PlannerBackend {
        return .{ .ptr = self, .planFn = plan, .deinitFn = deinit };
    }
    fn deinit(_: *anyopaque) void {}
    fn plan(_: *anyopaque, a: std.mem.Allocator, _: []const u8, _: []const planner.ClarificationAnswer, _: ?[]const u8) planner.PlannerError!planner.Plan {
        return .{
            .allocator = a,
            .understanding = try a.dupe(u8, "Hola. Soy tu superagente; dime que construimos."),
            .questions = try a.alloc(planner.ClarificationQuestion, 0),
            .tasks = try a.alloc(planner.PlannedTask, 0),
            .kind = .chat,
        };
    }
};

/// El otro lado de C-11: un plan con 0 tareas que NO es charla (el LLM no
/// produjo nada para una orden de trabajo — el «No pude planificar» de
/// llm_planner marca kind=.failed). Cerrarlo `done` sería falso éxito.
const FailedFixturePlanner = struct {
    fn backend(self: *@This()) planner.PlannerBackend {
        return .{ .ptr = self, .planFn = plan, .deinitFn = deinit };
    }
    fn deinit(_: *anyopaque) void {}
    fn plan(_: *anyopaque, a: std.mem.Allocator, _: []const u8, _: []const planner.ClarificationAnswer, _: ?[]const u8) planner.PlannerError!planner.Plan {
        return .{
            .allocator = a,
            .understanding = try a.dupe(u8, "No pude planificar: no se obtuvo una respuesta válida del modelo."),
            .questions = try a.alloc(planner.ClarificationQuestion, 0),
            .tasks = try a.alloc(planner.PlannedTask, 0),
            .kind = .failed,
        };
    }
};

test "C-11: plan conversacional (0 tareas) cierra la orden en done, no planned" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var cp = ChatFixturePlanner{};
    const pb = cp.backend();
    defer pb.deinit();

    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    var outcome = try sa.processOrder("proj-1", "hola, que puedes hacer?", &.{}, pb, null, null);
    defer outcome.deinit();

    // La respuesta conversacional ES el producto: la orden termina, no espera
    // una aprobacion sobre un plan vacio.
    try std.testing.expectEqual(OrderStatus.done, outcome.status);
    const status = try fetchOrderStatus(allocator, runtime, outcome.order_id);
    defer allocator.free(status);
    try std.testing.expectEqualStrings("done", status);
    // El plan queda persistido (traza honesta) y el evento terminal grabado.
    try std.testing.expectEqual(@as(i32, 1), try countRows(runtime, "plans"));
    try std.testing.expectEqual(@as(i32, 0), try countRows(runtime, "tasks"));
    try std.testing.expectEqual(@as(i32, 1), try countRows(runtime, "events WHERE kind = 'order_done'"));
}

/// Remate D1: una vuelta de «DevAgents» que delegó. Mientras «responde», la
/// herramienta deja en el ledger de la orden lo que `delegate_tasks` escribe
/// (una línea por subtarea y el cierre con el recuento).
const DelegatingChatPlanner = struct {
    conn: db.Connection,
    subtasks: []const []const u8,
    finished: []const u8,
    fn backend(self: *@This()) planner.PlannerBackend {
        return .{ .ptr = self, .planFn = plan, .deinitFn = deinit };
    }
    fn deinit(_: *anyopaque) void {}
    fn plan(raw: *anyopaque, a: std.mem.Allocator, _: []const u8, _: []const planner.ClarificationAnswer, _: ?[]const u8) planner.PlannerError!planner.Plan {
        const self: *@This() = @ptrCast(@alignCast(raw));
        for (self.subtasks) |p| self.insert("delegation_subtask_finished_v1", p);
        self.insert("delegation_finished_v1", self.finished);
        return .{
            .allocator = a,
            .understanding = try a.dupe(u8, "He repartido el trabajo en dos subtareas."),
            .questions = try a.alloc(planner.ClarificationQuestion, 0),
            .tasks = try a.alloc(planner.PlannedTask, 0),
            .kind = .chat,
        };
    }
    fn insert(self: *@This(), kind: []const u8, payload: []const u8) void {
        const stmt = self.conn.prepare("INSERT INTO events (ts, source, kind, payload_json, order_id) VALUES (1, 'core', ?, ?, (SELECT MAX(id) FROM orders))") catch return;
        defer self.conn.finalize(stmt);
        db.bindText(stmt, 1, kind) catch return;
        db.bindText(stmt, 2, payload) catch return;
        _ = db.c.sqlite3_step(stmt);
    }
};

test "Remate D1: una delegación sin integrar no cierra «hecha»: sin auditar, fallida o parcial con su recuento" {
    const allocator = std.testing.allocator;
    const Case = struct { subs: []const []const u8, fin: []const u8, want: OrderStatus, kind: []const u8 };
    const cases = [_]Case{
        // 0 de 2, ambas sin auditar (cuota del auditor agotada): P0.1.
        .{ .subs = &.{ "{\"index\":1,\"integrated\":false,\"unaudited\":true,\"verdict\":\"sin auditar\",\"status\":\"audit_unavailable\"}", "{\"index\":2,\"integrated\":false,\"unaudited\":true,\"verdict\":\"sin auditar\",\"status\":\"audit_unavailable\"}" }, .fin = "{\"cancelled\":false,\"integrated\":0,\"count\":2}", .want = .audit_unavailable, .kind = "order_audit_unavailable_v1" },
        // 0 de 2, fallidas (la productora no entregó): sin entregar.
        .{ .subs = &.{ "{\"index\":1,\"integrated\":false,\"unaudited\":false,\"verdict\":\"sin auditar\",\"status\":\"failed\"}", "{\"index\":2,\"integrated\":false,\"unaudited\":false,\"verdict\":\"FAIL\",\"status\":\"done\"}" }, .fin = "{\"cancelled\":false,\"integrated\":0,\"count\":2}", .want = .failed, .kind = "order_failed" },
        // 1 de 2: hecha, con el recuento en su cierre.
        .{ .subs = &.{ "{\"index\":1,\"integrated\":true,\"unaudited\":false,\"verdict\":\"PASS\",\"status\":\"done\"}", "{\"index\":2,\"integrated\":false,\"unaudited\":false,\"verdict\":\"FAIL\",\"status\":\"done\"}" }, .fin = "{\"cancelled\":false,\"integrated\":1,\"count\":2}", .want = .done, .kind = "order_done" },
        // 2 de 2: hecha, como siempre.
        .{ .subs = &.{ "{\"index\":1,\"integrated\":true,\"unaudited\":false}", "{\"index\":2,\"integrated\":true,\"unaudited\":false}" }, .fin = "{\"cancelled\":false,\"integrated\":2,\"count\":2}", .want = .done, .kind = "order_done" },
    };
    for (cases, 0..) |c, i| {
        var runtime = try openRuntime(allocator);
        defer runtime.close();
        var dp = DelegatingChatPlanner{ .conn = runtime, .subtasks = c.subs, .finished = c.fin };
        const pb = dp.backend();
        defer pb.deinit();
        var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
        var outcome = try sa.processOrder("proj-1", "haz dos cosas a la vez", &.{}, pb, null, null);
        defer outcome.deinit();
        try std.testing.expectEqual(c.want, outcome.status);
        const status = try fetchOrderStatus(allocator, runtime, outcome.order_id);
        defer allocator.free(status);
        try std.testing.expectEqualStrings(c.want.toText(), status);
        const q = try runtime.prepare("SELECT payload_json FROM events WHERE order_id = ? AND kind = ?");
        defer runtime.finalize(q);
        try db.bindInt(q, 1, outcome.order_id);
        try db.bindText(q, 2, c.kind);
        try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(q));
        const payload = std.mem.span(db.c.sqlite3_column_text(q, 0));
        if (i < 3) {
            // El cierre lleva el recuento que la cabina enseña («0 de 2»).
            try std.testing.expect(std.mem.indexOf(u8, payload, "subtareas integradas") != null);
            try std.testing.expect(std.mem.indexOf(u8, payload, "\"count\":2") != null);
        } else {
            try std.testing.expect(std.mem.indexOf(u8, payload, "plan_conversacional") != null);
        }
    }
    // Sin delegación, una charla sigue cerrando «hecha» (C-11).
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    const tally = try sa.delegationTally(42);
    try std.testing.expectEqual(@as(i64, 0), tally.count);
}

