test "CK-MOT-013: 32 explicit files fit the finite dispatch budget without 32 artificial waves" {
    const allocator = std.testing.allocator;
    var mp = planner.MockPlanner.init(allocator);
    const pb = mp.backend();
    defer pb.deinit();
    var text = std.ArrayList(u8).empty;
    defer text.deinit(allocator);
    try text.appendSlice(allocator, "crea ");
    for (0..32) |i| {
        const name = try std.fmt.allocPrint(allocator, "f{d}.js", .{i});
        defer allocator.free(name);
        if (i > 0) try text.appendSlice(allocator, ", ");
        try text.appendSlice(allocator, name);
    }
    try text.appendSlice(allocator, " con pruebas");
    var plan = try pb.plan(allocator, text.items, &.{}, null);
    defer plan.deinit();
    try expandExplicitMultiFilePlan(allocator, &plan, text.items);
    try chainSiblingProducers(allocator, &plan);
    const waves = try Superagent.resolveWaves(plan.tasks, allocator);
    defer {
        for (waves) |wave| allocator.free(wave);
        allocator.free(waves);
    }
    // The mock planner also appends QA/audit consumers after all producers.
    try std.testing.expectEqual(@as(usize, 34), plan.tasks.len);
    try std.testing.expect(waves.len <= d2MaxChain() + 2);
    // Repeating normalization must not extend the same synthetic chain.
    try chainSiblingProducers(allocator, &plan);
    const repeated = try Superagent.resolveWaves(plan.tasks, allocator);
    defer {
        for (repeated) |wave| allocator.free(wave);
        allocator.free(repeated);
    }
    try std.testing.expectEqual(waves.len, repeated.len);
    var produced: usize = 0;
    var simulated_ms: u64 = D2_CHAIN_RESERVE_MS;
    for (waves) |wave| {
        // Simulated workers finish together at the model-call limit of a wave.
        simulated_ms +|= live_worker.getModelCallTimeoutMs();
        for (wave) |task| if (d2IsProducer(task.task_type)) {
            produced += 1;
        };
    }
    try std.testing.expectEqual(@as(usize, 32), produced);
    try std.testing.expect(simulated_ms <= D2_DISPATCH_CAP_MS);
    std.debug.print("CK-MOT-013 explicit: files={d}, waves={d}, simulated_ms={d}, cap_ms={d}\n", .{ produced, waves.len, simulated_ms, D2_DISPATCH_CAP_MS });
}

test "CK-MOT-013: 32 independent workers share one wave and explicit chains remain ordered" {
    const allocator = std.testing.allocator;
    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var tasks: [32]planner.PlannedTask = undefined;
    for (&tasks, 0..) |*task, i| {
        const id = try std.fmt.allocPrint(a, "t{d}", .{i});
        const file = try std.fmt.allocPrint(a, "f{d}.js", .{i});
        const owns = try a.alloc([]const u8, 1);
        owns[0] = file;
        task.* = .{ .id = id, .task_type = .programar, .department = "p", .description = file, .contract_fields = &.{}, .depends_on = &.{}, .owns = owns, .deliverable = id };
    }
    var plan = planner.Plan{ .allocator = a, .understanding = "32 independent modules", .questions = &.{}, .tasks = &tasks };
    try chainSiblingProducers(a, &plan);
    const independent = try Superagent.resolveWaves(&tasks, a);
    try std.testing.expectEqual(@as(usize, 1), independent.len);
    try std.testing.expectEqual(@as(usize, 32), independent[0].len);
    for (tasks[1..], 0..) |*task, i| {
        const deps = try a.alloc([]const u8, 1);
        deps[0] = tasks[i].id;
        task.depends_on = deps;
    }
    try chainSiblingProducers(a, &plan);
    const chained = try Superagent.resolveWaves(&tasks, a);
    try std.testing.expectEqual(@as(usize, 32), chained.len);
    var finished = std.StringHashMap(void).init(a);
    for (chained) |wave| {
        try std.testing.expectEqual(@as(usize, 1), wave.len);
        for (wave) |task| {
            for (task.depends_on) |dep| try std.testing.expect(finished.contains(dep));
            try finished.put(task.id, {});
        }
    }
    try std.testing.expectEqual(@as(usize, 32), finished.count());
}

test "CK-MOT-013 r2: overlapping owns and filename serialize across deliverables and preserve reverse dependencies" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    for ([_]bool{ false, true }) |reverse| {
        var shared_field = [_]planner.ContractField{.{ .name = "filename", .field_type = .string, .required = true, .value = "SHARED.js" }};
        var tasks = [_]planner.PlannedTask{
            .{ .id = "a", .task_type = .programar, .department = "p", .description = "a", .contract_fields = &.{}, .depends_on = &.{}, .owns = &.{"shared.js"}, .deliverable = "one" },
            .{ .id = "b", .task_type = .programar, .department = "p", .description = "b", .contract_fields = &shared_field, .depends_on = &.{}, .owns = &.{"extra.js"}, .deliverable = "two" },
            .{ .id = "c", .task_type = .programar, .department = "p", .description = "c", .contract_fields = &.{}, .depends_on = &.{}, .owns = &.{"extra.js"}, .deliverable = "three" },
            .{ .id = "d", .task_type = .programar, .department = "p", .description = "d", .contract_fields = &.{}, .depends_on = &.{}, .owns = &.{"independent.js"}, .deliverable = "four" },
        };
        if (reverse) {
            const deps = try a.alloc([]const u8, 1);
            deps[0] = "b";
            tasks[0].depends_on = deps;
        }
        var plan = planner.Plan{ .allocator = a, .understanding = "overlapping producers", .questions = &.{}, .tasks = &tasks };
        // Normalization is idempotent, including mandatory file dependencies.
        try chainSiblingProducers(a, &plan);
        try chainSiblingProducers(a, &plan);
        const waves = try Superagent.resolveWaves(&tasks, a);
        var wave_of: [4]usize = undefined;
        for (waves, 0..) |wave, index| {
            for (wave) |task| {
                for (tasks, 0..) |original, ti| {
                    if (std.mem.eql(u8, original.id, task.id)) wave_of[ti] = index;
                }
            }
        }
        try std.testing.expect(wave_of[0] != wave_of[1]);
        try std.testing.expect(wave_of[1] < wave_of[2]);
        try std.testing.expectEqual(@as(usize, 0), wave_of[3]);
        if (reverse) try std.testing.expect(wave_of[1] < wave_of[0]);
    }
}

