test "CK-MOT-013 r2: 32 simulated workers stay within scheduler concurrency including sequential locals" {
    const Simulated = struct {
        mutex: sync.Mutex = sync.Mutex.init(),
        active: usize = 0,
        peak: usize = 0,
        local_active: usize = 0,
        local_peak: usize = 0,
        completed: usize = 0,
        seen: [32]usize = @splat(0),

        fn local(_: *@This(), task: planner.PlannedTask) bool {
            return std.mem.eql(u8, task.department, "local");
        }

        fn run(self: *@This(), task: planner.PlannedTask) void {
            const index = std.fmt.parseInt(usize, task.id, 10) catch unreachable;
            self.mutex.lock();
            self.active += 1;
            self.peak = @max(self.peak, self.active);
            if (local(self, task)) {
                self.local_active += 1;
                self.local_peak = @max(self.local_peak, self.local_active);
            }
            self.mutex.unlock();
            Sleep(10);
            self.mutex.lock();
            self.active -= 1;
            if (local(self, task)) self.local_active -= 1;
            self.completed += 1;
            self.seen[index] += 1;
            self.mutex.unlock();
        }
    };
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var tasks: [32]planner.PlannedTask = undefined;
    for (&tasks, 0..) |*task, index| {
        task.* = .{ .id = try std.fmt.allocPrint(a, "{d}", .{index}), .task_type = .programar, .department = "remote", .description = "simulated", .contract_fields = &.{}, .depends_on = &.{} };
    }
    const waves = try Superagent.resolveWaves(&tasks, a);
    try std.testing.expectEqual(@as(usize, 1), waves.len);
    for ([_]usize{ 1, 3, (scheduler.SchedulerConfig{}).num_workers }) |limit| {
        for ([_]bool{ false, true }) |mixed| {
            for (&tasks, 0..) |*task, index| task.department = if (mixed and index % 3 == 0) "local" else "remote";
            for ([_]bool{ false, true }) |allow_local_parallel| {
                var simulated = Simulated{};
                const reported = try dispatchWaveTasks(a, &tasks, limit, &simulated, Simulated.run, Simulated.local, allow_local_parallel);
                try std.testing.expect(simulated.peak <= limit);
                try std.testing.expect(reported <= limit);
                if (!allow_local_parallel) try std.testing.expect(simulated.local_peak <= 1);
                try std.testing.expectEqual(@as(usize, 32), simulated.completed);
                try std.testing.expectEqual(@as(usize, 0), simulated.active);
                for (simulated.seen) |count| try std.testing.expectEqual(@as(usize, 1), count);
                std.debug.print("CK-MOT-013 r2: tasks=32 limit={d} mixed={} local_parallel={} measured_peak={d} reported_bound={d}\n", .{ limit, mixed, allow_local_parallel, simulated.peak, reported });
            }
        }
    }
    var simulated = Simulated{};
    try std.testing.expectError(error.InvalidConcurrencyLimit, dispatchWaveTasks(a, &tasks, 0, &simulated, Simulated.run, Simulated.local, false));
    try std.testing.expectEqual(@as(usize, 0), simulated.completed);
}

test "D2: explicit multi-file creation expands one producer and rewires consumers" {
    const allocator = std.testing.allocator;
    var mp = planner.MockPlanner.init(allocator);
    const pb = mp.backend();
    defer pb.deinit();

    var plan = try pb.plan(allocator, "crea index.html, styles.css y script.js con pruebas", &.{}, null);
    defer plan.deinit();

    try expandExplicitMultiFilePlan(allocator, &plan, "crea index.html, styles.css y script.js con pruebas");
    try std.testing.expectEqual(@as(usize, 5), plan.tasks.len);
    try std.testing.expectEqualStrings("t1", plan.tasks[0].id);
    try std.testing.expectEqualStrings("t1-file-2", plan.tasks[1].id);
    try std.testing.expectEqualStrings("t1-file-3", plan.tasks[2].id);
    for (plan.tasks[0..3], [_][]const u8{ "index.html", "styles.css", "script.js" }) |task, expected| {
        var filename: ?[]const u8 = null;
        var has_exit_code = false;
        for (task.contract_fields) |field| {
            if (std.mem.eql(u8, field.name, "filename")) filename = field.value;
            if (std.mem.eql(u8, field.name, "exit_code")) has_exit_code = true;
        }
        try std.testing.expectEqualStrings(expected, filename.?);
        try std.testing.expect(has_exit_code);
    }
    try std.testing.expectEqual(@as(usize, 3), plan.tasks[3].depends_on.len);
    try std.testing.expectEqualStrings("t1", plan.tasks[3].depends_on[0]);
    try std.testing.expectEqualStrings("t1-file-2", plan.tasks[3].depends_on[1]);
    try std.testing.expectEqualStrings("t1-file-3", plan.tasks[3].depends_on[2]);
    try std.testing.expectEqual(@as(usize, 3), plan.tasks[4].depends_on.len);
}

test "D2-XFILE (orden 437): los archivos de un entregable se encadenan para verse entre si" {
    const allocator = std.testing.allocator;
    var mp = planner.MockPlanner.init(allocator);
    const pb = mp.backend();
    defer pb.deinit();

    const orden = "crea index.html, styles.css y script.js con pruebas";
    var plan = try pb.plan(allocator, orden, &.{}, null);
    defer plan.deinit();
    try expandExplicitMultiFilePlan(allocator, &plan, orden);

    // El primero no depende de ningun hermano: es el que fija la interfaz.
    try std.testing.expectEqual(@as(usize, 0), plan.tasks[0].depends_on.len);
    // Los siguientes SI, y en cadena. Esto es lo que le faltaba a la orden 437:
    // el productor de `app.js` corria en la misma ola que el del HTML y no podia
    // leer que el boton era `type="button"`.
    try std.testing.expectEqual(@as(usize, 1), plan.tasks[1].depends_on.len);
    try std.testing.expectEqualStrings("t1", plan.tasks[1].depends_on[0]);
    try std.testing.expectEqual(@as(usize, 1), plan.tasks[2].depends_on.len);
    try std.testing.expectEqualStrings("t1-file-2", plan.tasks[2].depends_on[0]);

    // Con esas dependencias, las olas dejan de mezclar productores hermanos.
    const waves = try Superagent.resolveWaves(plan.tasks, allocator);
    defer {
        for (waves) |w| allocator.free(w);
        allocator.free(waves);
    }
    try std.testing.expectEqual(@as(usize, 1), waves[0].len);
    try std.testing.expectEqualStrings("t1", waves[0][0].id);
    try std.testing.expectEqual(@as(usize, 1), waves[1].len);
    try std.testing.expectEqualStrings("t1-file-2", waves[1][0].id);

    // El cierre transitivo de `script.js` incluye a los DOS anteriores, que es
    // lo que `indicesVisibles` usa para armar su contexto.
    const ancestros = try subagent.ancestrosDe(allocator, plan.tasks, "t1-file-3");
    defer allocator.free(ancestros);
    var vio_html = false;
    var vio_css = false;
    for (ancestros) |id| {
        if (std.mem.eql(u8, id, "t1")) vio_html = true;
        if (std.mem.eql(u8, id, "t1-file-2")) vio_css = true;
    }
    try std.testing.expect(vio_html);
    try std.testing.expect(vio_css);
}

test "H3: el plan REAL de la 437 traia cuatro productores sueltos y ahora se encadenan" {
    const allocator = std.testing.allocator;
    // Forma exacta del plan que devolvio el proveedor en la orden 437: cuatro
    // productores, los tres primeros SIN dependencias entre ellos. Con este
    // plan, `expandExplicitMultiFilePlan` se rinde en su primer return.
    var f_html = [_]planner.ContractField{.{ .name = "filename", .field_type = .string, .required = true, .value = "index.html" }};
    var f_css = [_]planner.ContractField{.{ .name = "filename", .field_type = .string, .required = true, .value = "styles.css" }};
    var f_js = [_]planner.ContractField{.{ .name = "filename", .field_type = .string, .required = true, .value = "app.js" }};
    var f_test = [_]planner.ContractField{.{ .name = "filename", .field_type = .string, .required = true, .value = "test_app.js" }};
    var sin_deps = [_][]const u8{};
    var dep_t3 = [_][]const u8{"t3"};

    var tasks = [_]planner.PlannedTask{
        .{ .id = "t1", .task_type = .programar, .department = "programacion", .description = "index.html", .contract_fields = &f_html, .depends_on = sin_deps[0..] },
        .{ .id = "t2", .task_type = .programar, .department = "programacion", .description = "styles.css", .contract_fields = &f_css, .depends_on = sin_deps[0..] },
        .{ .id = "t3", .task_type = .programar, .department = "programacion", .description = "app.js", .contract_fields = &f_js, .depends_on = sin_deps[0..] },
        .{ .id = "t4", .task_type = .programar, .department = "programacion", .description = "test_app.js", .contract_fields = &f_test, .depends_on = dep_t3[0..] },
    };
    var plan = planner.Plan{ .allocator = allocator, .understanding = "calculadora web", .questions = &.{}, .tasks = tasks[0..] };
    try chainSiblingProducers(allocator, &plan);
    defer {
        // Solo se liberan las dependencias que ESTE test hizo crecer.
        for (plan.tasks) |t| {
            if (t.depends_on.len > 0 and t.depends_on.ptr != sin_deps[0..].ptr and t.depends_on.ptr != dep_t3[0..].ptr) {
                for (t.depends_on) |d| allocator.free(d);
                allocator.free(t.depends_on);
            }
        }
    }

    try std.testing.expectEqual(@as(usize, 0), plan.tasks[0].depends_on.len);
    try std.testing.expectEqual(@as(usize, 1), plan.tasks[1].depends_on.len);
    try std.testing.expectEqualStrings("t1", plan.tasks[1].depends_on[0]);
    try std.testing.expectEqual(@as(usize, 1), plan.tasks[2].depends_on.len);
    try std.testing.expectEqualStrings("t2", plan.tasks[2].depends_on[0]);
    // t4 ya venia ordenado por el planificador: no se le toca.
    try std.testing.expectEqual(@as(usize, 1), plan.tasks[3].depends_on.len);
    try std.testing.expectEqualStrings("t3", plan.tasks[3].depends_on[0]);

    // Y con eso, el productor de app.js deja de correr a ciegas: ve el HTML.
    const ancestros = try subagent.ancestrosDe(allocator, plan.tasks, "t3");
    defer allocator.free(ancestros);
    var vio_html = false;
    for (ancestros) |id| {
        if (std.mem.eql(u8, id, "t1")) vio_html = true;
    }
    try std.testing.expect(vio_html);
}

test "H3: encadenar nunca cierra un ciclo ni pisa el orden del planificador" {
    const allocator = std.testing.allocator;
    var f_a = [_]planner.ContractField{.{ .name = "filename", .field_type = .string, .required = true, .value = "a.js" }};
    var f_b = [_]planner.ContractField{.{ .name = "filename", .field_type = .string, .required = true, .value = "b.js" }};
    // El planificador ya dijo que `t1` depende de `t2`. Encadenar en orden de
    // plan querria anadir `t2 -> t1`, que cerraria el ciclo.
    var dep_t2 = [_][]const u8{"t2"};
    var sin_deps = [_][]const u8{};
    var tasks = [_]planner.PlannedTask{
        .{ .id = "t1", .task_type = .programar, .department = "p", .description = "a", .contract_fields = &f_a, .depends_on = dep_t2[0..] },
        .{ .id = "t2", .task_type = .programar, .department = "p", .description = "b", .contract_fields = &f_b, .depends_on = sin_deps[0..] },
    };
    var plan = planner.Plan{ .allocator = allocator, .understanding = "x", .questions = &.{}, .tasks = tasks[0..] };
    try chainSiblingProducers(allocator, &plan);
    try std.testing.expectEqual(@as(usize, 1), plan.tasks[0].depends_on.len);
    try std.testing.expectEqualStrings("t2", plan.tasks[0].depends_on[0]);
    try std.testing.expectEqual(@as(usize, 0), plan.tasks[1].depends_on.len);
}

test "H4: la cadena se para en el tope derivado del presupuesto, no en 8" {
    // Auditoría del motor 09-09: con 180 s por llamada, ocho productores
    // encadenados llegan a 24 min — por encima del cap de 15 de la orden.
    // El tope real es `d2MaxChain()`: con el cap de 60 min (E1.24, 17-09),
    // (3600 s − 240 s de reserva) / 180 s = 18 → manda D2_MAX_CHAIN = 8.
    const allocator = std.testing.allocator;
    var fields: [10][1]planner.ContractField = undefined;
    var tasks: [10]planner.PlannedTask = undefined;
    var sin_deps = [_][]const u8{};
    var nombres: [10][]const u8 = undefined;
    var ids: [10][]const u8 = undefined;
    for (0..10) |i| {
        nombres[i] = try std.fmt.allocPrint(allocator, "f{d}.js", .{i});
        ids[i] = try std.fmt.allocPrint(allocator, "t{d}", .{i + 1});
        fields[i] = .{.{ .name = "filename", .field_type = .string, .required = true, .value = nombres[i] }};
        tasks[i] = .{ .id = ids[i], .task_type = .programar, .department = "p", .description = nombres[i], .contract_fields = &fields[i], .depends_on = sin_deps[0..] };
    }
    defer {
        for (nombres) |n| allocator.free(n);
        for (ids) |i| allocator.free(i);
    }
    var plan = planner.Plan{ .allocator = allocator, .understanding = "diez archivos", .questions = &.{}, .tasks = tasks[0..] };
    try chainSiblingProducers(allocator, &plan);
    defer {
        for (plan.tasks) |t| {
            if (t.depends_on.len > 0) {
                for (t.depends_on) |d| allocator.free(d);
                allocator.free(t.depends_on);
            }
        }
    }

    const tope = d2MaxChain();
    var aristas: usize = 0;
    for (plan.tasks) |t| aristas += t.depends_on.len;
    try std.testing.expectEqual(tope, aristas);
    // Y el número es el presupuesto, no la constante: con los valores por
    // defecto caben tres aristas — nunca las ocho que la cuenta optimista
    // del comentario original prometía.
    try std.testing.expect(tope <= D2_MAX_CHAIN);
    try std.testing.expect(tope >= 2);
    try std.testing.expect(@as(u64, tope) *| live_worker.getModelCallTimeoutMs() <=
        D2_DISPATCH_CAP_MS -| D2_CHAIN_RESERVE_MS +| live_worker.getModelCallTimeoutMs());
}

test "B1: productores de entregables distintos NO se encadenan" {
    // Dos entregables declarados: la web (html+js) y el script de backup. Con la
    // cadena global anterior, backup.py esperaba a app.js — serialización que no
    // le enseñaba nada y gastaba plazo. Ahora cada entregable es su propia cadena.
    const allocator = std.testing.allocator;
    var sin_deps = [_][]const u8{};
    var owns_a = [_][]const u8{"index.html"};
    var owns_b = [_][]const u8{"app.js"};
    var owns_c = [_][]const u8{"backup.py"};
    var owns_d = [_][]const u8{"restore.py"};
    var tasks = [_]planner.PlannedTask{
        .{ .id = "t1", .task_type = .programar, .department = "p", .description = "index.html", .contract_fields = &.{}, .depends_on = sin_deps[0..], .owns = owns_a[0..], .deliverable = "web" },
        .{ .id = "t2", .task_type = .programar, .department = "p", .description = "app.js", .contract_fields = &.{}, .depends_on = sin_deps[0..], .owns = owns_b[0..], .deliverable = "web" },
        .{ .id = "t3", .task_type = .programar, .department = "p", .description = "backup.py", .contract_fields = &.{}, .depends_on = sin_deps[0..], .owns = owns_c[0..], .deliverable = "backup" },
        .{ .id = "t4", .task_type = .programar, .department = "p", .description = "restore.py", .contract_fields = &.{}, .depends_on = sin_deps[0..], .owns = owns_d[0..], .deliverable = "backup" },
    };
    var plan = planner.Plan{ .allocator = allocator, .understanding = "web + backup", .questions = &.{}, .tasks = tasks[0..] };
    try chainSiblingProducers(allocator, &plan);
    defer {
        for (plan.tasks) |t| {
            if (t.depends_on.len > 0 and t.depends_on.ptr != sin_deps[0..].ptr) {
                for (t.depends_on) |d| allocator.free(d);
                allocator.free(t.depends_on);
            }
        }
    }
    try std.testing.expectEqual(@as(usize, 0), plan.tasks[0].depends_on.len);
    try std.testing.expectEqual(@as(usize, 1), plan.tasks[1].depends_on.len);
    try std.testing.expectEqualStrings("t1", plan.tasks[1].depends_on[0]);
    // La cadena del backup arranca en t3, no continúa desde la web.
    try std.testing.expectEqual(@as(usize, 0), plan.tasks[2].depends_on.len);
    try std.testing.expectEqual(@as(usize, 1), plan.tasks[3].depends_on.len);
    try std.testing.expectEqualStrings("t3", plan.tasks[3].depends_on[0]);
}

test "CK-MOT-013 B1: owns compartido serializa escritores sin alterar la cadena de interfaz" {
    const allocator = std.testing.allocator;
