        .{ .id = "t1", .task_type = .programar, .department = "p", .description = "main.c", .contract_fields = &.{}, .depends_on = sin_deps[0..], .owns = owns_dup[0..] },
        .{ .id = "t2", .task_type = .programar, .department = "p", .description = "main.c otra vez", .contract_fields = &.{}, .depends_on = sin_deps[0..], .owns = owns_dup[0..] },
        .{ .id = "t3", .task_type = .programar, .department = "p", .description = "util.c", .contract_fields = &.{}, .depends_on = sin_deps[0..], .owns = owns_otro[0..] },
    };
