test "D2-XFILE: el manifiesto obliga a respetar la interfaz real de los hermanos" {
    const allocator = std.testing.allocator;
    var html_fields = [_]planner.ContractField{
        .{ .name = "filename", .field_type = .string, .required = true, .value = "index.html" },
    };
    var js_fields = [_]planner.ContractField{
        .{ .name = "filename", .field_type = .string, .required = true, .value = "app.js" },
    };
    var sin_deps = [_][]const u8{};
    const tasks = [_]planner.PlannedTask{
        .{ .id = "t1", .task_type = .programar, .department = "programacion", .description = "html", .contract_fields = &html_fields, .depends_on = sin_deps[0..] },
        .{ .id = "t2", .task_type = .programar, .department = "programacion", .description = "js", .contract_fields = &js_fields, .depends_on = sin_deps[0..] },
    };
    const manifest = (try buildPlanManifest(allocator, "calculadora web", &tasks)).?;
    defer allocator.free(manifest);

    try std.testing.expect(std.mem.indexOf(u8, manifest, "CONTRATO DE INTERFAZ COMPARTIDA") != null);
    try std.testing.expect(std.mem.indexOf(u8, manifest, "index.html") != null);
    try std.testing.expect(std.mem.indexOf(u8, manifest, "app.js") != null);
    // La regla que nombra el defecto exacto de la 437.
    try std.testing.expect(std.mem.indexOf(u8, manifest, "NO dispara el submit") != null);
    // Y la que impide cambiar un invento por otro cuando el hermano no se ve.
    try std.testing.expect(std.mem.indexOf(u8, manifest, "no supongas su interfaz") != null);
    // El objetivo original sigue intacto: el contrato se suma, no sustituye.
    try std.testing.expect(std.mem.indexOf(u8, manifest, "calculadora web") != null);
}

