/// Planner exclusivo de fixtures: preserva el comando también al replanificar.
const ExecutableFixturePlanner = struct {
    mock: planner.MockPlanner,
    fn init(a: std.mem.Allocator) @This() {
        return .{ .mock = planner.MockPlanner.init(a) };
    }
    fn backend(self: *@This()) planner.PlannerBackend {
        return .{ .ptr = self, .planFn = plan, .deinitFn = deinit };
    }
    fn deinit(_: *anyopaque) void {}
    fn plan(ctx: *anyopaque, a: std.mem.Allocator, order: []const u8, answers: []const planner.ClarificationAnswer, memory: ?[]const u8) planner.PlannerError!planner.Plan {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        var result = try self.mock.backend().plan(a, order, answers, memory);
        errdefer result.deinit();
        for (result.tasks) |*task| {
            if (task.task_type != .testear) continue;
            const fields = try a.alloc(planner.ContractField, task.contract_fields.len + 1);
            @memcpy(fields[0..task.contract_fields.len], task.contract_fields);
            const name = a.dupe(u8, "command") catch {
                a.free(fields);
                return error.OutOfMemory;
            };
            const value = a.dupe(u8, "python --version") catch {
                a.free(name);
                a.free(fields);
                return error.OutOfMemory;
            };
            fields[task.contract_fields.len] = .{ .name = name, .field_type = .string, .required = false, .value = value };
            a.free(task.contract_fields);
            task.contract_fields = fields;
        }
        return result;
    }
};

fn fixtureSuccessfulLlm(_: *anyopaque, _: []const u8, _: []const u8) []const u8 {
    return "[{\"field\":\"filename\",\"content\":\"fixture.c\"},{\"field\":\"source\",\"content\":\"int main(){return 0;}\"},{\"field\":\"exit_code\",\"content\":\"0\"},{\"field\":\"tests_passed\",\"content\":\"1\"},{\"field\":\"verdict\",\"content\":\"PASS\"}]";
}

