test "TERMINAL-P0 C2: cancel_token pre-establecido hace que approveAndDispatch termine en cancelled, no done" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();

    var mp = planner.MockPlanner.init(allocator);
    const pb = mp.backend();
    defer pb.deinit();

    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    var outcome = try sa.processOrder("proj-1", "construye una calculadora CLI en C con tests", &.{}, pb, null, null);
    defer outcome.deinit();

    // Cancelación solicitada ANTES de despachar — igual que una orden nueva de una
    // ola/tarea posterior a que se pidió cancelar (requisito C: "detiene la cadena
    // completa"). MockWorker completaría las tareas con éxito si se le dejara;
    // cancelled_now debe ganar la decisión terminal de todos modos.
    const token = try live_worker.CancellationToken.create(allocator);
    defer token.release();
    sa.cancel_token = token;
    sa.requestCancel();

    var dr = try sa.approveAndDispatch(&outcome, null, null, null);
    defer dr.deinit(allocator);

    try std.testing.expect(dr.order_cancelled);
    try std.testing.expect(!dr.order_failed);

    const status2 = try fetchOrderStatus(allocator, runtime, outcome.order_id);
    defer allocator.free(status2);
    try std.testing.expectEqualStrings("cancelled", status2);

    // Requisito D: como máximo un terminal — nunca order_done + order_cancelled.
    const cnt_stmt = try runtime.prepare("SELECT COUNT(*) FROM events WHERE order_id = ? AND kind IN ('order_done','order_failed','order_cancelled')");
    defer runtime.finalize(cnt_stmt);
    try db.bindInt(cnt_stmt, 1, outcome.order_id);
    try std.testing.expect(db.c.sqlite3_step(cnt_stmt) == db.c.SQLITE_ROW);
    try std.testing.expectEqual(@as(c_int, 1), db.c.sqlite3_column_int(cnt_stmt, 0));

    const kind_stmt = try runtime.prepare("SELECT kind FROM events WHERE order_id = ? AND kind IN ('order_done','order_failed','order_cancelled')");
    defer runtime.finalize(kind_stmt);
    try db.bindInt(kind_stmt, 1, outcome.order_id);
    try std.testing.expect(db.c.sqlite3_step(kind_stmt) == db.c.SQLITE_ROW);
    const kptr = db.c.sqlite3_column_text(kind_stmt, 0) orelse return error.TestUnexpectedNull;
    const klen = db.c.sqlite3_column_bytes(kind_stmt, 0);
    try std.testing.expectEqualStrings("order_cancelled", kptr[0..@intCast(klen)]);
}

// FASE-AGENTIC-3: evaluador mock con estado — dice "no terminado, sigue" las
// primeras `stop_after` veces, luego "terminado". Sirve para ejercitar el loop
// sin un LLM real. Devuelve un JSON estático (el buffer vive en el struct).
const MockEvaluator = struct {
    calls: usize = 0,
    stop_after: usize,
    buf: [256]u8 = undefined,

    fn evalFn(ctx: *anyopaque, system_prompt: []const u8, user_prompt: []const u8) []const u8 {
        _ = system_prompt;
        _ = user_prompt;
        const self: *MockEvaluator = @ptrCast(@alignCast(ctx));
        self.calls += 1;
        if (self.calls >= self.stop_after) {
            return "{\"done\":true,\"final_answer\":\"listo consolidado\"}";
        }
        // next_goal = un prompt que MockPlanner SÍ planifica (no vago), para
        // ejercitar la ruta de re-planificación del loop en vez del fail-safe
        // de clarificación.
        return "{\"done\":false,\"next_goal\":\"construye una calculadora CLI en C con tests\"}";
    }
};

