    try std.testing.expectEqual(@as(usize, 0), evaluator.calls);
    try std.testing.expect(std.mem.indexOf(u8, dr.report, "Reporte consolidado") != null);
}

test "FASE-AGENTIC-3: max_agent_iterations=3 con evaluador que pide 1 paso más → 2 dispatches, para en done" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var mp = ExecutableFixturePlanner.init(allocator);
    const pb = mp.backend();
    defer pb.deinit();

    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.max_agent_iterations = 3;
    var outcome = try sa.processOrder("proj-loop2", "construye una calculadora CLI en C con tests", &.{}, pb, null, null);
    defer outcome.deinit();
    sa.permission_config.mode = .bypass;
    sa.executor_spawn_fn = testExecutorSpawnOk;
    sa.setEventConn(runtime, outcome.order_id);

    // stop_after=2 → 1ª evaluación dice "sigue" (re-planifica), 2ª dice "done".
    var evaluator = MockEvaluator{ .stop_after = 2 };
    var llm_marker: u8 = 0;
    var dr = try sa.agenticExecute(&outcome, pb, fixtureSuccessfulLlm, &llm_marker, null, "objetivo", MockEvaluator.evalFn, &evaluator);
    defer dr.deinit(allocator);
    if (dr.order_failed) {
        const diag = try runtime.prepare("SELECT kind,payload_json FROM events WHERE kind IN ('test_evidence_v1','task_failed','auto_audit_failed','auto_audit')");
        defer runtime.finalize(diag);
        while (db.c.sqlite3_step(diag) == db.c.SQLITE_ROW) std.debug.print("fixture {s}: {s}\n", .{ std.mem.span(db.c.sqlite3_column_text(diag, 0).?), std.mem.span(db.c.sqlite3_column_text(diag, 1).?) });
    }

    // El evaluador se llamó 2 veces (una por iteración del loop tras el dispatch inicial).
    try std.testing.expectEqual(@as(usize, 2), evaluator.calls);
    // El evaluador consolidó la respuesta final.
    try std.testing.expectEqualStrings("listo consolidado", dr.final_answer);

    const terminal_stmt = try runtime.prepare(
        "SELECT COUNT(*) FROM events WHERE order_id = ? AND kind IN ('order_done','order_failed','order_cancelled')",
    );
    defer runtime.finalize(terminal_stmt);
    try db.bindInt(terminal_stmt, 1, outcome.order_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(terminal_stmt));
    try std.testing.expectEqual(@as(i64, 1), db.c.sqlite3_column_int64(terminal_stmt, 0));
}

