const TestLlmCtx = struct {
    response: []const u8,
};

fn testLlmFn(ctx: *anyopaque, _: []const u8, _: []const u8) []const u8 {
    const c: *TestLlmCtx = @ptrCast(@alignCast(ctx));
    return c.response;
}

/// Detector de reentrada: rastrea cuántas llamadas concurrentes hay al llm_fn.
/// Usado por el test de fallback concurrente para demostrar que no hay carrera.
const ReentrancyCtx = struct {
    mutex: sync.Mutex,
    active: usize,
    max_active: usize,
    response: []const u8,
};

fn reentrantLlmFn(ctx: *anyopaque, _: []const u8, _: []const u8) []const u8 {
    const self: *ReentrancyCtx = @ptrCast(@alignCast(ctx));
    self.mutex.lock();
    self.active += 1;
    if (self.active > self.max_active) self.max_active = self.active;
    self.mutex.unlock();
    // Ampliar la ventana de carrera: si no estuviera serializado, otra tarea entraría aquí.
    Sleep(10);
    self.mutex.lock();
    self.active -= 1;
    self.mutex.unlock();
    return self.response;
}

/// Spawn mock para tests: evita ejecutar binarios reales del host, forzando la
/// ruta de aprobación del executor y manteniendo los tests deterministas.
fn testExecutorSpawn(_: std.mem.Allocator, _: []const u8, _: []const []const u8, _: []const u8, _: u32, _: usize, _: ?executor.StreamSink, _: ?*anyopaque, _: []const u8) executor.ExecutorError!executor.RunResult {
    return error.SpawnFailed;
}

/// Spawn mock que simula ejecución exitosa (exit=0) para tests de auditoría.
fn testExecutorSpawnOk(a: std.mem.Allocator, _: []const u8, _: []const []const u8, _: []const u8, _: u32, _: usize, _: ?executor.StreamSink, _: ?*anyopaque, _: []const u8) executor.ExecutorError!executor.RunResult {
    return executor.RunResult{ .exit_code = 0, .stdout = try a.dupe(u8, "ok"), .stderr = try a.dupe(u8, "") };
}

/// Spawn mock que simula ejecución fallida (exit=1) para tests de auditoría.
fn testExecutorSpawnFail(a: std.mem.Allocator, _: []const u8, _: []const []const u8, _: []const u8, _: u32, _: usize, _: ?executor.StreamSink, _: ?*anyopaque, _: []const u8) executor.ExecutorError!executor.RunResult {
    return executor.RunResult{ .exit_code = 1, .stdout = try a.dupe(u8, ""), .stderr = try a.dupe(u8, "runtime error") };
}

/// Spawn mock con estado: 1ª ejecución falla (exit=1), las siguientes pasan (exit=0).
/// Simula que la CORRECCIÓN arregla el artefacto. Reinicia g_exec_call_count en el test.
var g_exec_call_count: usize = 0;
fn testExecutorSpawnFailThenOk(a: std.mem.Allocator, _: []const u8, _: []const []const u8, _: []const u8, _: u32, _: usize, _: ?executor.StreamSink, _: ?*anyopaque, _: []const u8) executor.ExecutorError!executor.RunResult {
    defer g_exec_call_count += 1;
    if (g_exec_call_count == 0) {
        return executor.RunResult{ .exit_code = 1, .stdout = try a.dupe(u8, ""), .stderr = try a.dupe(u8, "runtime error") };
    }
    return executor.RunResult{ .exit_code = 0, .stdout = try a.dupe(u8, "ok"), .stderr = try a.dupe(u8, "") };
}

/// EXEC-SHOW: spawn mock que simula un programa CONTINUO (reloj/servidor) que no termina:
/// devuelve la salida capturada con timed_out=true (como hace runGoverned al timeout).
fn testExecutorSpawnTimeout(a: std.mem.Allocator, _: []const u8, _: []const []const u8, _: []const u8, _: u32, _: usize, _: ?executor.StreamSink, _: ?*anyopaque, _: []const u8) executor.ExecutorError!executor.RunResult {
    return executor.RunResult{ .exit_code = 124, .stdout = try a.dupe(u8, "Hora actual: 12:00:00\n"), .stderr = try a.dupe(u8, ""), .timed_out = true };
}

fn countRows(conn: db.Connection, table: []const u8) !i32 {
    // `table` es un literal interno del test, no entrada externa.
    var buf: [64]u8 = undefined;
    const sql = try std.fmt.bufPrint(&buf, "SELECT COUNT(*) FROM {s}", .{table});
    const stmt = try conn.prepare(sql);
    defer conn.finalize(stmt);
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return error.StepFailed;
    return db.c.sqlite3_column_int(stmt, 0);
}

fn fetchOrderStatus(allocator: std.mem.Allocator, conn: db.Connection, order_id: i64) ![]const u8 {
    const stmt = try conn.prepare("SELECT status FROM orders WHERE id = ?");
    defer conn.finalize(stmt);
    try db.bindInt(stmt, 1, order_id);
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return error.StepFailed;
    const ptr = db.c.sqlite3_column_text(stmt, 0);
    // El puntero de SQLite muere al finalizar el stmt: duplicar para devolverlo vivo.
    return allocator.dupe(u8, ptr[0..std.mem.len(ptr)]);
}

fn seedCatalog(conn: db.Connection) !void {
    try conn.exec("INSERT INTO providers (id, name, base_url, api_style, is_free_tier) VALUES (1, 'OpenCode', 'local://opencode', 'opencode', 1)");
    try conn.exec("INSERT INTO api_keys (id, provider_id, label, key_ciphertext, quota_limit, quota_used, status) VALUES (1, 1, 'free-a', x'00', 100, 0, 'active')");
    try conn.exec("INSERT INTO models (id, provider_id, model_name, context_window, is_free, latency_p50_ms, available) VALUES (1, 1, 'deepseek-coder-free', 128000, 1, 900, 1)");
    try conn.exec("INSERT INTO models (id, provider_id, model_name, context_window, is_free, latency_p50_ms, available) VALUES (2, 1, 'gemini-flash-free', 128000, 1, 800, 1)");
