test "E5.17: hermanas del fanout caen en la primera ola válida (resolveWaves)" {
    const allocator = std.testing.allocator;
    // Estructura que produce plan_fanout.apply sobre "t1" con salidas en dos
    // módulos: hermanas sin deps propias (heredan las del original, aquí
    // ninguna) y un consumidor reescrito a depender de ambas.
    var sin_deps = [_][]const u8{};
    var owns_a = [_][]const u8{"frontend/app.ts"};
    var owns_b = [_][]const u8{"backend/api.zig"};
    var owns_c = [_][]const u8{"docs/manual.md"};
    var deps_doc = [_][]const u8{ "t1-m1", "t1-m2" };
    var tasks = [_]planner.PlannedTask{
        .{ .id = "t1-m1", .task_type = .programar, .department = "p", .description = "app.ts", .contract_fields = &.{}, .depends_on = sin_deps[0..], .owns = owns_a[0..] },
        .{ .id = "t1-m2", .task_type = .programar, .department = "p", .description = "api.zig", .contract_fields = &.{}, .depends_on = sin_deps[0..], .owns = owns_b[0..] },
        .{ .id = "t2", .task_type = .documentar, .department = "docs", .description = "manual", .contract_fields = &.{}, .depends_on = deps_doc[0..], .owns = owns_c[0..] },
    };
    const waves = try Superagent.resolveWaves(tasks[0..], allocator);
    defer {
        for (waves) |w| allocator.free(w);
        allocator.free(waves);
    }
    // Regla (c): las dos hermanas son independientes → misma primera ola;
    // la consumidora queda en la siguiente.
    try std.testing.expectEqual(@as(usize, 2), waves.len);
    try std.testing.expectEqual(@as(usize, 2), waves[0].len);
    try std.testing.expectEqual(@as(usize, 1), waves[1].len);
    try std.testing.expectEqualStrings("t2", waves[1][0].id);
}

