// S21: la regla <10 bytes es para artefactos estructurados rotos (un .py que
// solo dice "python"). En texto libre una palabra corta es el entregable —
// medido en la orden 500: a.txt="UNO" marcada FAIL pese al gate semántico PASS.
test "MOT018 semantic gate checks prose even without declared observables" {
    const a = std.testing.allocator;
    var runtime = try openRuntime(a);
    defer runtime.close();
    var mp = planner.MockPlanner.init(a);
    const pb = mp.backend();
    defer pb.deinit();
    var sa = Superagent.init(a, runtime, null, NoopMemory.backend(), 1);
    var outcome = try sa.processOrder("mot018", "Documenta brevemente en un texto los riesgos de guardar claves de API en texto plano", &.{}, pb, null, null);
    defer outcome.deinit();
    var threaded = std.Io.Threaded.init(a, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.writeFile(io, .{ .sub_path = "risks.txt", .data = "Riesgos de API." });
    const path = try tmp.dir.realPathFileAlloc(io, "risks.txt", a);
    defer a.free(path);
    var ctx = Superagent.FanoutContext{
        .mutex = .init(),
        .completed = 1,
        .failed = 0,
        .integrated = 1,
        .rejected = 0,
        .outputs = .empty,
        .pending = .empty,
        .saved = .empty,
        .saved_owner = .empty,
        .results = .empty,
        .sa = &sa,
        .outcome = &outcome,
        .llm_fn = null,
        .llm_ctx = null,
        .catalog_path = null,
        .needed_resources = &.{},
    };
    defer ctx.saved.deinit(a);
    defer ctx.saved_owner.deinit(a);
    try tmp.dir.writeFile(io, .{ .sub_path = "valid.txt", .data = "Las claves de API en texto plano pueden filtrarse en repositorios y copias de seguridad. Usa un gestor de secretos, limita los permisos y revoca las claves expuestas." });
    const valid_path = try tmp.dir.realPathFileAlloc(io, "valid.txt", a);
    defer a.free(valid_path);
    try ctx.saved.append(a, valid_path);
    try ctx.saved_owner.append(a, outcome.plan.tasks[0].id);
    try ctx.saved.append(a, path);
    try ctx.saved_owner.append(a, outcome.plan.tasks[0].id);
    const verdict = try sa.evaluateSemanticGate(&ctx, &outcome);
    defer if (verdict.note) |note| a.free(note);
    try std.testing.expect(verdict.ran);
    try std.testing.expect(verdict.failed);
    try std.testing.expect(sa.hasInvalidSavedProse(&ctx, outcome.plan.tasks[0], false));
    const invalid = try runtime.prepare("UPDATE orders SET expected_result = 'not-json' WHERE id = ?");
    defer runtime.finalize(invalid);
    try db.bindInt(invalid, 1, outcome.order_id);
    try std.testing.expectEqual(db.c.SQLITE_DONE, db.c.sqlite3_step(invalid));
    const despite_invalid = try sa.evaluateSemanticGate(&ctx, &outcome);
    defer if (despite_invalid.note) |note| a.free(note);
    try std.testing.expect(despite_invalid.ran and despite_invalid.failed);
}

