test "MOT018 fix integration and disk gates preserve nonprose and requested short deliveries" {
    const a = std.testing.allocator;
    var runtime = try openRuntime(a);
    defer runtime.close();
    var mp = planner.MockPlanner.init(a);
    const pb = mp.backend();
    defer pb.deinit();
    var sa = Superagent.init(a, runtime, null, NoopMemory.backend(), 1);
    var outcome = try sa.processOrder("mot018", "Documenta brevemente en un texto los riesgos de guardar claves de API en texto plano", &.{}, pb, null, null);
    defer outcome.deinit();
    try std.testing.expect(outcome.plan.tasks.len > 0);
    var threaded = std.Io.Threaded.init(a, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var ctx = Superagent.FanoutContext{
        .mutex = .init(),
        .completed = 1,
        .failed = 0,
        .integrated = 1,
        .rejected = 0,
        .outputs = .empty,
        .pending = .empty,
        .saved = .empty,
        .saved_owner = .empty,
        .results = .empty,
        .sa = &sa,
        .outcome = &outcome,
        .llm_fn = null,
        .llm_ctx = null,
        .catalog_path = null,
        .needed_resources = &.{},
    };
    defer ctx.saved.deinit(a);
    defer ctx.saved_owner.deinit(a);
    const cases = [_]struct { kind: model_router.TaskType, path: []const u8, body: []const u8, request: []const u8 }{
        .{ .kind = .programar, .path = "settings.txt", .body = "document=enabled", .request = "Crea settings.txt con la opcion document" },
        .{ .kind = .documentar, .path = "settings.txt", .body = "document=enabled", .request = "Crea un archivo de configuracion con la opcion document" },
        .{ .kind = .documentar, .path = "data.txt", .body = "{\"document\":true}", .request = "Documenta el resultado como JSON en data.txt" },
        .{ .kind = .documentar, .path = "code.txt", .body = "print(42)", .request = "Documenta el ejemplo con codigo Python en code.txt" },
        .{ .kind = .documentar, .path = "note.txt", .body = "Usa un gestor de secretos.", .request = "Documenta una nota breve sobre claves API" },
        .{ .kind = .resumir, .path = "summary.txt", .body = "Las claves expuestas permiten acceso y gastos no autorizados", .request = "Resume en una frase los riesgos de guardar claves de API" },
        .{ .kind = .documentar, .path = "risks.txt", .body = "docs/risks.txt", .request = "Escribe literalmente 'docs/risks.txt' en risks.txt" },
        .{ .kind = .programar, .path = "Dockerfile", .body = "FROM scratch", .request = "Documenta el build y crea Dockerfile" },
        .{ .kind = .programar, .path = "Makefile", .body = "all:\n\t@echo ok", .request = "Documenta el build y crea Makefile" },
        .{ .kind = .programar, .path = "LICENSE", .body = "MIT", .request = "Crea LICENSE y documenta la licencia" },
        .{ .kind = .testear, .path = "events.log", .body = "ok", .request = "Analiza y documenta el resultado del test en events.log" },
        .{ .kind = .programar, .path = "data.csv", .body = "a,b\n1,2", .request = "Documenta el resultado en data.csv" },
        .{ .kind = .programar, .path = "status.txt", .body = "documentacion", .request = "Crea status.txt para el campo document" },
    };
    for (cases) |c| {
        errdefer std.debug.print("MOT018 CASE={s} TASK={s} REQUEST={s}\n", .{ c.path, @tagName(c.kind), c.request });
        const task = planner.PlannedTask{ .id = outcome.plan.tasks[0].id, .task_type = c.kind, .department = "documentacion", .description = c.request, .contract_fields = &.{}, .depends_on = &.{} };
        var rejection = try sa.validatePieceForTaskDetallado(task, &.{.{ .path = c.path, .content = c.body }});
        defer rejection.deinit(a);
        try std.testing.expect(rejection.motivo == null);
        try tmp.dir.writeFile(io, .{ .sub_path = c.path, .data = c.body });
        const path = try tmp.dir.realPathFileAlloc(io, c.path, a);
        defer a.free(path);
        try std.testing.expect(!sa.isContentTriviallyInvalidForTask(path, task, false));
        a.free(outcome.plan.tasks[0].description);
        outcome.plan.tasks[0].description = try a.dupe(u8, c.request);
        outcome.plan.tasks[0].task_type = c.kind;
        ctx.saved.clearRetainingCapacity();
        ctx.saved_owner.clearRetainingCapacity();
        try ctx.saved.append(a, path);
        try ctx.saved_owner.append(a, task.id);
        const verdict = try sa.evaluateSemanticGate(&ctx, &outcome);
        defer if (verdict.note) |note| a.free(note);
        try std.testing.expect(!verdict.failed);
        try std.testing.expect(!sa.hasInvalidSavedProse(&ctx, task, false));
    }
}

