/// runs the semantic prose gate for one file owned by an audit
/// task. `order_text` decides whether the order is a standalone audit; the
/// audit task always gets an explanation-requesting description, so a trivial
/// body must be rejected only when the order itself is an audit.
const Mot018AuditGate = struct { ran: bool, failed: bool };

fn mot018RunAuditGate(a: std.mem.Allocator, order_text: []const u8, body: []const u8) !Mot018AuditGate {
    var runtime = try openRuntime(a);
    defer runtime.close();
    var mp = planner.MockPlanner.init(a);
    const pb = mp.backend();
    defer pb.deinit();
    var sa = Superagent.init(a, runtime, null, NoopMemory.backend(), 1);
    var outcome = try sa.processOrder("mot018", order_text, &.{}, pb, null, null);
    defer outcome.deinit();
    var audit_idx: ?usize = null;
    for (outcome.plan.tasks, 0..) |t, i| {
        if (t.task_type == .auditar) {
            audit_idx = i;
            break;
        }
    }
    try std.testing.expect(audit_idx != null);
    a.free(outcome.plan.tasks[audit_idx.?].description);
    outcome.plan.tasks[audit_idx.?].description = try a.dupe(u8, "Explica los riesgos de guardar claves de API en texto plano");
    var threaded = std.Io.Threaded.init(a, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.writeFile(io, .{ .sub_path = "informe.txt", .data = body });
    const path = try tmp.dir.realPathFileAlloc(io, "informe.txt", a);
    defer a.free(path);
    var ctx = Superagent.FanoutContext{
        .mutex = .init(),
        .completed = 1,
        .failed = 0,
        .integrated = 1,
        .rejected = 0,
        .outputs = .empty,
        .pending = .empty,
        .saved = .empty,
        .saved_owner = .empty,
        .results = .empty,
        .sa = &sa,
        .outcome = &outcome,
        .llm_fn = null,
        .llm_ctx = null,
        .catalog_path = null,
        .needed_resources = &.{},
    };
    defer ctx.saved.deinit(a);
    defer ctx.saved_owner.deinit(a);
    try ctx.saved.append(a, path);
    try ctx.saved_owner.append(a, outcome.plan.tasks[audit_idx.?].id);
    const verdict = try sa.evaluateSemanticGate(&ctx, &outcome);
    defer if (verdict.note) |note| a.free(note);
    return .{ .ran = verdict.ran, .failed = verdict.failed };
}

