test "isContentTriviallyInvalid no veta texto libre corto; sí estructurado" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);

    const GENERIC_WRITE: u32 = 0x40000000;
    const CREATE_ALWAYS: u32 = 2;
    const FILE_ATTRIBUTE_NORMAL: u32 = 0x80;

    const cases = [_]struct { path: []const u8, content: []const u8, invalid: bool }{
        .{ .path = "s21_trivial_a.txt", .content = "UNO", .invalid = false },
        .{ .path = "s21_trivial_b.md", .content = "DOS", .invalid = false },
        .{ .path = "s21_trivial_c", .content = "TRES", .invalid = false },
        .{ .path = "s21_trivial_d.py", .content = "python", .invalid = true },
        .{ .path = "s21_trivial_e.txt", .content = "", .invalid = true },
    };
    for (cases) |c| {
        const pz = try allocator.dupeZ(u8, c.path);
        defer allocator.free(pz);
        if (c.content.len > 0) {
            const h = CreateFileA(pz.ptr, GENERIC_WRITE, FILE_SHARE_READ, null, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, null);
            try std.testing.expect(h != INVALID_HANDLE_VALUE);
            var written: u32 = 0;
            try std.testing.expect(WriteFile(h, c.content.ptr, @intCast(c.content.len), &written, null) != 0);
            _ = CloseHandle(h);
        } else {
            // Archivo vacío: lo crea CreateFileA sin escritura.
            const h = CreateFileA(pz.ptr, GENERIC_WRITE, FILE_SHARE_READ, null, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, null);
            try std.testing.expect(h != INVALID_HANDLE_VALUE);
            _ = CloseHandle(h);
        }
        defer _ = DeleteFileA(pz.ptr);
        try std.testing.expectEqual(c.invalid, sa.isContentTriviallyInvalid(c.path));
    }
}

const TestLlmCtxWithCounter = struct {
    response: []const u8,
    correction_response: []const u8,
    call_count: usize = 0,
};

fn testLlmFnWithCounter(ctx: *anyopaque, _: []const u8, _: []const u8) []const u8 {
    const tc: *TestLlmCtxWithCounter = @ptrCast(@alignCast(ctx));
    tc.call_count += 1;
    if (tc.call_count == 1) return tc.response;
    return tc.correction_response;
}

/// r2 (P1): devuelve basura al primer intento y, en esa misma llamada,
/// pide cancelación — reproduce que el usuario (o el watchdog de plazo) cancela
/// justo después de que el worker falle por artefacto.
const TestLlmCancelOnFirstCtx = struct {
    response: []const u8,
    token: *live_worker.CancellationToken,
    call_count: usize = 0,
};

fn testLlmFnCancelOnFirst(ctx: *anyopaque, _: []const u8, _: []const u8) []const u8 {
    const tc: *TestLlmCancelOnFirstCtx = @ptrCast(@alignCast(ctx));
    tc.call_count += 1;
    if (tc.call_count == 1) {
        tc.token.cancel();
        return tc.response;
    }
    return tc.response;
}

test "approveAndDispatch auto-audit detects exit_code != 0 and reports failure (FIRE-05)" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var mp = planner.MockPlanner.init(allocator);
    const pb = mp.backend();
    defer pb.deinit();

    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.executor_spawn_fn = testExecutorSpawnFail;
    // AUDIT-UNAVAILABLE-P0: sin bypass la ejecución quedaba pendiente de
    // aprobación y failed_count lo aportaba la tarea de auditoría (que ahora
    // cierra audit_unavailable, no failed). El test debe ejercitar de verdad
    // lo que su nombre dice: ejecutar y detectar exit_code != 0.
    sa.permission_config.mode = .bypass;
    var outcome = try sa.processOrder("proj-1", "suma en Python", &.{}, pb, null, null);
    defer outcome.deinit();

    // Código que parece real (tiene tokens de código) pero ejecuta y devuelve exit=1.
    // La corrección devuelve un JSON inválido para forzar corr_ok=false.
    var ctx = TestLlmCtxWithCounter{
        .response =
        \\ [{"field":"source","content":"def main():\n  pass"},{"field":"filename","content":"sumar.py"},{"field":"exit_code","content":"0"},{"field":"tests_passed","content":"1"},{"field":"verdict","content":"PASS"}]
        ,
        .correction_response =
        \\ [{"field":"source","content":"broken"}]
        ,
    };
    var dr = try sa.approveAndDispatch(&outcome, testLlmFnWithCounter, &ctx, null);
    defer dr.deinit(allocator);

    // La tarea t1 debe quedar fallida porque ejecutó y devolvió exit_code != 0
    // y la corrección mock no pudo generar un artefacto válido.
    try std.testing.expect(dr.failed_count > 0);
    try std.testing.expect(std.mem.indexOf(u8, dr.report, "fallidas") != null);

    // Limpieza del archivo escrito.
    const path = try std.fmt.allocPrint(allocator, "devagents-workspace\\orden-{d}\\sumar.py", .{outcome.order_id});
    defer allocator.free(path);
    const path_z = allocator.dupeZ(u8, path) catch "";
    defer allocator.free(path_z);
    _ = DeleteFileA(path_z.ptr);
}

test "approveAndDispatch auto-audit passes valid artifact with exit=0" {
    const allocator = std.testing.allocator;
