    defer allocator.free(path);
    const path_z = allocator.dupeZ(u8, path) catch "";
    defer allocator.free(path_z);
    _ = DeleteFileA(path_z.ptr);
}

// ── CHECKPOINT-T2: reanudación por checkpoint por tarea ─────────────────────

const CountingLlmCtx = struct {
    response: []const u8,
    call_count: usize = 0,
};

fn countingLlmFn(ctx: *anyopaque, _: []const u8, _: []const u8) []const u8 {
    const tc: *CountingLlmCtx = @ptrCast(@alignCast(ctx));
    tc.call_count += 1;
    return tc.response;
}

test "CHECKPOINT-T2: persistTaskCheckpoint escribe el estado por contrato (running→completed)" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var mp = planner.MockPlanner.init(allocator);
    const pb = mp.backend();
    defer pb.deinit();

    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    var outcome = try sa.processOrder("proj-ck", "suma en Python con tests", &.{}, pb, null, null);
    defer outcome.deinit();
    const pid = outcome.plan_id.?;

    const statusIs = struct {
        // El texto de la columna solo vive mientras la sentencia está abierta:
        // comparar dentro del scope, nunca devolver el puntero.
        fn query(conn: db.Connection, plan_id: i64, name: []const u8, expected: []const u8) bool {
            const stmt = conn.prepare(
                "SELECT t.status FROM tasks t JOIN contracts c ON c.id = t.contract_id WHERE t.plan_id = ? AND c.name = ?",
            ) catch return false;
            defer conn.finalize(stmt);
            db.bindInt(stmt, 1, plan_id) catch return false;
            db.bindText(stmt, 2, name) catch return false;
            if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return false;
            const ptr = db.c.sqlite3_column_text(stmt, 0) orelse return false;
            const len = db.c.sqlite3_column_bytes(stmt, 0);
            return std.mem.eql(u8, expected, ptr[0..@intCast(len)]);
        }
    }.query;

    // Al nacer, la tarea está 'planned'; el checkpoint la mueve a 'running'
    // (lo que queda si el proceso muere a mitad) y luego a 'completed'.
    try std.testing.expect(statusIs(runtime, pid, "t1", "planned"));
    sa.persistTaskCheckpoint(pid, "t1", "running");
    try std.testing.expect(statusIs(runtime, pid, "t1", "running"));
    sa.persistTaskCheckpoint(pid, "t1", "completed");
    try std.testing.expect(statusIs(runtime, pid, "t1", "completed"));

    // Un task_id sin contrato no toca nada — la clave es c.name, no la
    // descripción (dos tareas pueden compartir texto).
    sa.persistTaskCheckpoint(pid, "tX-inexistente", "running");
    try std.testing.expect(statusIs(runtime, pid, "t1", "completed"));
    try std.testing.expect(statusIs(runtime, pid, "t2", "planned"));
}

test "CHECKPOINT-T2: reanudar salta las completadas y re-ejecuta enteras las demás" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var mp = planner.MockPlanner.init(allocator);
    const pb = mp.backend();
    defer pb.deinit();

    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.executor_spawn_fn = testExecutorSpawnOk;
    var outcome = try sa.processOrder("proj-resume", "suma en Python", &.{}, pb, null, null);
    defer outcome.deinit();
    sa.setEventConn(runtime, outcome.order_id);

    // El plan del MockPlanner tiene t1 (programar) y t3 (auditar, dep t1).
    // Simular la interrupción: t1 quedó COMPLETADA con su artefacto en disco
    // (lo que persistiría tasks.artifact_path) y no debe volver a correr;
    // t3 quedó 'running' a medias → se reporta como interrumpida y se
    // re-ejecuta ENTERA — una tarea a medias no tiene continuidad interna.
    const t1_dir = try std.fmt.allocPrint(allocator, "devagents-workspace\\orden-{d}", .{outcome.order_id});
    defer allocator.free(t1_dir);
    const t1_dir_z = try allocator.dupeZ(u8, t1_dir);
    defer allocator.free(t1_dir_z);
    _ = CreateDirectoryA("devagents-workspace", null);
    _ = CreateDirectoryA(t1_dir_z.ptr, null);
    const t1_path = try std.fmt.allocPrint(allocator, "{s}" ++ std.fs.path.sep_str ++ "sumar.py", .{t1_dir});
    defer allocator.free(t1_path);
    const t1_path_z = try allocator.dupeZ(u8, t1_path);
    defer allocator.free(t1_path_z);
    {
        const GENERIC_WRITE: u32 = 0x40000000;
        const CREATE_ALWAYS: u32 = 2;
        const FILE_ATTRIBUTE_NORMAL: u32 = 0x80;
        const hf = CreateFileA(t1_path_z.ptr, GENERIC_WRITE, 0, null, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, null);
        try std.testing.expect(hf != INVALID_HANDLE_VALUE);
        const body = "def main():\n  return 0\n";
        var written: u32 = 0;
        try std.testing.expect(WriteFile(hf, body.ptr, @intCast(body.len), &written, null) != 0);
        _ = CloseHandle(hf);
    }
    const restored = [_]RestoredTask{.{ .task_id = "t1", .artifact_path = t1_path }};
    const interrupted = [_][]const u8{"t3"};
    sa.resume_checkpoint = .{ .restored = &restored, .interrupted = &interrupted };

    var ctx = CountingLlmCtx{ .response =
        \\ [{"field":"source","content":"def main():\n  return 0"},{"field":"filename","content":"sumar.py"},{"field":"exit_code","content":"0"},{"field":"tests_passed","content":"1"},{"field":"verdict","content":"PASS"}]
    };
    var dr = try sa.approveAndDispatch(&outcome, countingLlmFn, &ctx, null);
    defer dr.deinit(allocator);

    // t1 restaurada NO corrió: solo t3 llamó al worker — y la dependencia
    // t3→t1 se resolvió gracias al resultado restaurado (success+integrated),
    // así que la reanudación arranca en la primera tarea incompleta sin
    // rehacer lo hecho.
    try std.testing.expectEqual(@as(usize, 1), ctx.call_count);
    try std.testing.expectEqual(@as(usize, 2), dr.completed_count);
    try std.testing.expectEqual(@as(usize, 0), dr.failed_count);
    try std.testing.expect(std.mem.indexOf(u8, dr.report, "restauradas desde checkpoint") != null);

    // El evento declara honestamente qué se restauró y qué quedó a medias.
    const estmt = try runtime.prepare("SELECT payload_json FROM events WHERE order_id = ? AND kind = 'order_resumed'");
    defer runtime.finalize(estmt);
    try db.bindInt(estmt, 1, outcome.order_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(estmt));
    const pptr = db.c.sqlite3_column_text(estmt, 0);
    const plen = db.c.sqlite3_column_bytes(estmt, 0);
    const payload = pptr[0..@intCast(plen)];
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"restored\":1") != null);
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"rerun\":1") != null);
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"restored_tasks\":[\"t1\"]") != null);
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"interrupted_tasks\":[\"t3\"]") != null);
    try std.testing.expectEqual(db.c.SQLITE_DONE, db.c.sqlite3_step(estmt));

    // Limpieza del artefacto sembrado y del escrito por la tarea re-ejecutada.
    const path = try std.fmt.allocPrint(allocator, "devagents-workspace\\orden-{d}\\sumar.py", .{outcome.order_id});
    defer allocator.free(path);
    const path_z = allocator.dupeZ(u8, path) catch "";
    defer allocator.free(path_z);
    _ = DeleteFileA(path_z.ptr);
}

test "CHECKPOINT-T2: un resultado restaurado re-verifica su artefacto en la auditoría" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var mp = planner.MockPlanner.init(allocator);
    const pb = mp.backend();
    defer pb.deinit();

    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.executor_spawn_fn = testExecutorSpawnOk;
    var outcome = try sa.processOrder("proj-resume2", "suma en Python", &.{}, pb, null, null);
    defer outcome.deinit();

    // El checkpoint declara t1 'completed' pero su artefacto NO existe en
    // disco — la auditoría no puede creerse el checkpoint: lo manda a
    // corrección (re-ejecución del productor) y el consumidor cuya
    // evidencia quedó obsoleta vuelve a correr.
    const restored = [_]RestoredTask{.{ .task_id = "t1", .artifact_path = "C:\\no\\existe\\t1.py" }};
    sa.resume_checkpoint = .{ .restored = &restored, .interrupted = &.{} };

    var ctx = CountingLlmCtx{ .response =
        \\ [{"field":"source","content":"def main():\n  return 0"},{"field":"filename","content":"sumar.py"},{"field":"exit_code","content":"0"},{"field":"tests_passed","content":"1"},{"field":"verdict","content":"PASS"}]
    };
    var dr = try sa.approveAndDispatch(&outcome, countingLlmFn, &ctx, null);
    defer dr.deinit(allocator);

    // 1 llamada de la ola (t3) + 1 de corrección de t1 + 1 del consumidor
    // re-ejecutado tras la corrección. Lo que NUNCA puede pasar es que el
    // checkpoint inválido se acepte sin verificación.
    try std.testing.expectEqual(@as(usize, 3), ctx.call_count);
    try std.testing.expectEqual(@as(usize, 2), dr.completed_count);
    try std.testing.expectEqual(@as(usize, 0), dr.failed_count);

    // Limpieza del archivo escrito por las tareas ejecutadas.
    const path = try std.fmt.allocPrint(allocator, "devagents-workspace\\orden-{d}\\sumar.py", .{outcome.order_id});
    defer allocator.free(path);
    const path_z = allocator.dupeZ(u8, path) catch "";
    defer allocator.free(path_z);
    _ = DeleteFileA(path_z.ptr);
}

// ── SEMANTIC-GATE-T3: gate de intención sobre el gate de ejecución ─────────
// El falso verde C1: la calculadora que devuelve 999 para 6+3 pasaba porque el
// gate medía alcance, no corrección. Ahora el 'done' exige que el observable
// DECLARADO (orders.expected_result o 'expects' del plan) se cumpla de verdad.

test "SEMANTIC-GATE-T3: observable declarado satisfecho deja la orden en done" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var mp = planner.MockPlanner.init(allocator);
    const pb = mp.backend();
    defer pb.deinit();

    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.executor_spawn_fn = testExecutorSpawnOk;
    sa.permission_config.mode = .bypass;
    sa.plan_approved = true;
    var outcome = try sa.processOrder("proj-sem1", "un programa en C", &.{}, pb, null, null);
    defer outcome.deinit();
    sa.setEventConn(runtime, outcome.order_id);

    // La orden declara su observable: el archivo producido debe contener el
    // literal que el programa imprime. El worker entrega exactamente eso.
    {
        const st = try runtime.prepare("UPDATE orders SET expected_result = ? WHERE id = ?");
        defer runtime.finalize(st);
        try db.bindText(st, 1, "[{\"kind\":\"file_contains\",\"path\":\"suma.c\",\"needle\":\"HOLA MUNDO\"}]");
        try db.bindInt(st, 2, outcome.order_id);
        try std.testing.expectEqual(db.c.SQLITE_DONE, db.c.sqlite3_step(st));
    }

    var ctx = CountingLlmCtx{ .response =
        \\ [{"field":"source","content":"#include <stdio.h>\nint main(){ printf(\"HOLA MUNDO\"); }"},{"field":"filename","content":"suma.c"},{"field":"verdict","content":"PASS"}]
    };
    var dr = try sa.approveAndDispatch(&outcome, countingLlmFn, &ctx, null);
    defer dr.deinit(allocator);

    try std.testing.expectEqual(@as(usize, 2), dr.completed_count);
    try std.testing.expectEqual(@as(usize, 0), dr.failed_count);
    try std.testing.expect(std.mem.indexOf(u8, dr.report, "Gate semántico: PASS") != null);

    // El evento del gate registra ran:true + verdict:pass.
    const st = try runtime.prepare("SELECT payload_json FROM events WHERE order_id = ? AND kind = 'semantic_gate_v1'");
    defer runtime.finalize(st);
    try db.bindInt(st, 1, outcome.order_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(st));
    const ptr = db.c.sqlite3_column_text(st, 0);
    const payload = ptr[0..@intCast(db.c.sqlite3_column_bytes(st, 0))];
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"verdict\":\"pass\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"fuente\":\"orden\"") != null);

    // La orden termina done — el gate de ejecución Y el semántico pasaron.
    const ds = try runtime.prepare("SELECT COUNT(*) FROM events WHERE order_id = ? AND kind = 'order_done'");
    defer runtime.finalize(ds);
    try db.bindInt(ds, 1, outcome.order_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(ds));
    try std.testing.expectEqual(@as(i64, 1), db.c.sqlite3_column_int64(ds, 0));

    const fpath = try std.fmt.allocPrint(allocator, "devagents-workspace\\orden-{d}\\suma.c", .{outcome.order_id});
    defer allocator.free(fpath);
    const fz = allocator.dupeZ(u8, fpath) catch "";
    defer allocator.free(fz);
    _ = DeleteFileA(fz.ptr);
}

test "SEMANTIC-GATE-T3: observable declarado incumplido impide el done con la diferencia" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var mp = planner.MockPlanner.init(allocator);
    const pb = mp.backend();
    defer pb.deinit();

    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.executor_spawn_fn = testExecutorSpawnOk;
    sa.permission_config.mode = .bypass;
    sa.plan_approved = true;
    var outcome = try sa.processOrder("proj-sem2", "un programa en C", &.{}, pb, null, null);
    defer outcome.deinit();
    sa.setEventConn(runtime, outcome.order_id);

    // La orden espera un literal que el programa NO imprime — el equivalente
    // del 999 de la calculadora: todo corrió, pero el resultado no es el pedido.
    {
        const st = try runtime.prepare("UPDATE orders SET expected_result = ? WHERE id = ?");
        defer runtime.finalize(st);
        try db.bindText(st, 1, "[{\"kind\":\"file_contains\",\"path\":\"suma.c\",\"needle\":\"EL RESULTADO ES 9\"}]");
        try db.bindInt(st, 2, outcome.order_id);
        try std.testing.expectEqual(db.c.SQLITE_DONE, db.c.sqlite3_step(st));
    }

    var ctx = CountingLlmCtx{ .response =
        \\ [{"field":"source","content":"#include <stdio.h>\nint main(){ printf(\"999\"); }"},{"field":"filename","content":"suma.c"},{"field":"verdict","content":"PASS"}]
    };
    var dr = try sa.approveAndDispatch(&outcome, countingLlmFn, &ctx, null);
    defer dr.deinit(allocator);

    // Las tareas completaron — el gate de ejecución pasó. La orden falla SOLO
    // por el observable declarado, y el reporte nombra la diferencia concreta.
    try std.testing.expectEqual(@as(usize, 2), dr.completed_count);
    try std.testing.expect(std.mem.indexOf(u8, dr.report, "Gate semántico: FAIL") != null);
    try std.testing.expect(std.mem.indexOf(u8, dr.report, "EL RESULTADO ES 9") != null);

    const ds = try runtime.prepare("SELECT COUNT(*) FROM events WHERE order_id = ? AND kind = 'order_done'");
    defer runtime.finalize(ds);
    try db.bindInt(ds, 1, outcome.order_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(ds));
    try std.testing.expectEqual(@as(i64, 0), db.c.sqlite3_column_int64(ds, 0));

    // El order_failed declara la causa semántica y la diferencia concreta.
    const fs = try runtime.prepare("SELECT payload_json FROM events WHERE order_id = ? AND kind = 'order_failed'");
    defer runtime.finalize(fs);
    try db.bindInt(fs, 1, outcome.order_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(fs));
    const ptr = db.c.sqlite3_column_text(fs, 0);
    const fpayload = ptr[0..@intCast(db.c.sqlite3_column_bytes(fs, 0))];
    try std.testing.expect(std.mem.indexOf(u8, fpayload, "semantic_gate_failed") != null);
    try std.testing.expect(std.mem.indexOf(u8, fpayload, "EL RESULTADO ES 9") != null);

    const fpath = try std.fmt.allocPrint(allocator, "devagents-workspace\\orden-{d}\\suma.c", .{outcome.order_id});
    defer allocator.free(fpath);
    const fz = allocator.dupeZ(u8, fpath) catch "";
    defer allocator.free(fz);
    _ = DeleteFileA(fz.ptr);
}

test "SEMANTIC-GATE-T3: el observable derivado del plan (expects del contrato) también gobierna" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var mp = planner.MockPlanner.init(allocator);
    const pb = mp.backend();
    defer pb.deinit();

    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.executor_spawn_fn = testExecutorSpawnOk;
    sa.permission_config.mode = .bypass;
    sa.plan_approved = true;
    var outcome = try sa.processOrder("proj-sem3", "un programa en C", &.{}, pb, null, null);
    defer outcome.deinit();
    sa.setEventConn(runtime, outcome.order_id);

    // Sin expected_result en la orden: el plan declara el observable en el
    // contract field 'expects' de t1 (lo que emite el planner LLM). La tarea
    // produce un archivo que no lo cumple → la orden NO puede darse por hecha.
    const expects_json = "[{\"kind\":\"file_contains\",\"path\":\"suma.c\",\"needle\":\"RESULTADO CORRECTO\"}]";
    const old_fields = outcome.plan.tasks[0].contract_fields;
    const new_fields = try allocator.alloc(planner.ContractField, old_fields.len + 1);
    @memcpy(new_fields[0..old_fields.len], old_fields);
    new_fields[old_fields.len] = .{
        .name = "expects",
        .field_type = .string,
        .required = false,
        .value = expects_json,
    };
    outcome.plan.tasks[0].contract_fields = new_fields;
    defer {
        outcome.plan.tasks[0].contract_fields = old_fields;
        allocator.free(new_fields);
    }

    var ctx = CountingLlmCtx{ .response =
        \\ [{"field":"source","content":"int main(){ return 0; }"},{"field":"filename","content":"suma.c"},{"field":"verdict","content":"PASS"}]
    };
    var dr = try sa.approveAndDispatch(&outcome, countingLlmFn, &ctx, null);
    defer dr.deinit(allocator);

    try std.testing.expectEqual(@as(usize, 2), dr.completed_count);
    try std.testing.expect(std.mem.indexOf(u8, dr.report, "Gate semántico: FAIL") != null);

    const st = try runtime.prepare("SELECT payload_json FROM events WHERE order_id = ? AND kind = 'semantic_gate_v1'");
    defer runtime.finalize(st);
    try db.bindInt(st, 1, outcome.order_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(st));
    const ptr = db.c.sqlite3_column_text(st, 0);
    const payload = ptr[0..@intCast(db.c.sqlite3_column_bytes(st, 0))];
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"verdict\":\"fail\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"fuente\":\"plan\"") != null);

    const fpath = try std.fmt.allocPrint(allocator, "devagents-workspace\\orden-{d}\\suma.c", .{outcome.order_id});
    defer allocator.free(fpath);
    const fz = allocator.dupeZ(u8, fpath) catch "";
    defer allocator.free(fz);
    _ = DeleteFileA(fz.ptr);
}

/// añade un `expects` a la tarea `auditar` (t2) del plan de
/// AuditUnavailablePlanner y despacha; devuelve el payload del gate.
fn gatePayloadConHipotesisDeAuditor(allocator: std.mem.Allocator, runtime: db.Connection, orden: []const u8) ![]u8 {
    var marker: u8 = 0;
    const backend = planner.PlannerBackend{ .ptr = &marker, .planFn = AuditUnavailablePlanner.plan, .deinitFn = AuditUnavailablePlanner.deinit };
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.permission_config.mode = .bypass;
    sa.plan_approved = true;
    var outcome = try sa.processOrder("proj-e122", orden, &.{}, backend, null, null);
    defer outcome.deinit();
    sa.setEventConn(runtime, outcome.order_id);

    // Lo que escribió el planificador en la orden 7: la pregunta de la
    // auditoría convertida en «el archivo contiene…», sobre código que la
    // orden no produce.
    const t2 = &outcome.plan.tasks[1];
    const old_fields = t2.contract_fields;
    const new_fields = try allocator.alloc(planner.ContractField, old_fields.len + 1);
    @memcpy(new_fields[0..old_fields.len], old_fields);
    new_fields[old_fields.len] = .{ .name = "expects", .field_type = .string, .required = false, .value = "[{\"kind\":\"file_contains\",\"path\":\"core/src/no_esta_e122.zig\",\"needle\":\"busy_timeout\"}]" };
    t2.contract_fields = new_fields;
    defer {
        t2.contract_fields = old_fields;
        allocator.free(new_fields);
    }

    var llm = AuditSeqLlm{
        .producer_response = "[{\"field\":\"source\",\"content\":\"def add(a, b):\\n    return a + b\"},{\"field\":\"filename\",\"content\":\"calculator.py\"}]",
        .audit_response = "[{\"field\":\"verdict\",\"content\":\"PASS: la suma es correcta\"}]",
    };
    var dr = try sa.approveAndDispatch(&outcome, AuditSeqLlm.call, &llm, null);
    defer dr.deinit(allocator);

    const st = try runtime.prepare("SELECT payload_json FROM events WHERE order_id = ? AND kind = 'semantic_gate_v1'");
    defer runtime.finalize(st);
    try db.bindInt(st, 1, outcome.order_id);
    if (db.c.sqlite3_step(st) != db.c.SQLITE_ROW) return error.TestUnexpectedResult;
    const ptr = db.c.sqlite3_column_text(st, 0);
    return allocator.dupe(u8, ptr[0..@intCast(db.c.sqlite3_column_bytes(st, 0))]);
}

test "E-122: en una orden de auditoría, la hipótesis de la tarea auditar no es un criterio de éxito" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    const payload = try gatePayloadConHipotesisDeAuditor(allocator, runtime, "Eres un AUDITOR INDEPENDIENTE: revisa si fija busy_timeout");
    defer allocator.free(payload);
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"reason\":\"orden_de_auditoria\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"verdict\":\"fail\"") == null);
}

test "E-122: la misma expectativa en un encargo de construcción se sigue evaluando" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    const payload = try gatePayloadConHipotesisDeAuditor(allocator, runtime, "calculator in python");
