    defer pb.deinit();

    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.executor_spawn_fn = testExecutorSpawnOk;
    sa.permission_config.mode = .bypass;
    sa.plan_approved = true;
    var outcome = try sa.processOrder("proj-sem4", "suma en Python", &.{}, pb, null, null);
    defer outcome.deinit();
    sa.setEventConn(runtime, outcome.order_id);

    var ctx = CountingLlmCtx{ .response =
        \\ [{"field":"source","content":"def main():\n  return 0"},{"field":"filename","content":"sumar.py"},{"field":"verdict","content":"PASS"}]
    };
    var dr = try sa.approveAndDispatch(&outcome, countingLlmFn, &ctx, null);
    defer dr.deinit(allocator);

    // Comportamiento intacto cuando nadie declaró nada: done normal + evento
    // honesto que dice que el gate no corrió (no fabrica un chequeo).
    try std.testing.expectEqual(@as(usize, 2), dr.completed_count);
    const st = try runtime.prepare("SELECT payload_json FROM events WHERE order_id = ? AND kind = 'semantic_gate_v1'");
    defer runtime.finalize(st);
    try db.bindInt(st, 1, outcome.order_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(st));
    const ptr = db.c.sqlite3_column_text(st, 0);
    const payload = ptr[0..@intCast(db.c.sqlite3_column_bytes(st, 0))];
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"ran\":false") != null);
    try std.testing.expect(std.mem.indexOf(u8, payload, "sin_observable_declarado") != null);

    const fpath = try std.fmt.allocPrint(allocator, "devagents-workspace\\orden-{d}\\sumar.py", .{outcome.order_id});
    defer allocator.free(fpath);
    const fz = allocator.dupeZ(u8, fpath) catch "";
    defer allocator.free(fz);
    _ = DeleteFileA(fz.ptr);
}

test "EXEC-SHOW: programa continuo (timed_out) muestra su salida y NO es fallo de auditoria" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var mp = planner.MockPlanner.init(allocator);
    const pb = mp.backend();
    defer pb.deinit();

    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.executor_spawn_fn = testExecutorSpawnTimeout;
    sa.permission_config.mode = .bypass;
    var outcome = try sa.processOrder("proj-1", "reloj en Python que imprime la hora", &.{}, pb, null, null);
    defer outcome.deinit();

    var ctx = TestLlmCtx{ .response =
        \\ [{"field":"source","content":"import time\nwhile True:\n  print('Hora actual')\n  time.sleep(1)"},{"field":"filename","content":"reloj.py"},{"field":"exit_code","content":"0"},{"field":"tests_passed","content":"1"},{"field":"verdict","content":"PASS"}]
    };
    var dr = try sa.approveAndDispatch(&outcome, testLlmFn, &ctx, null);
    defer dr.deinit(allocator);

    // El proceso corrió (timed_out) → su salida se MUESTRA y NO cuenta como fallo de exit.
    try std.testing.expectEqual(@as(usize, 0), dr.failed_count);
    try std.testing.expect(dr.completed_count > 0);
    var saw_output = false;
    for (dr.outputs) |o| {
        if (std.mem.indexOf(u8, o.text, "timeout") != null or std.mem.indexOf(u8, o.text, "Hora actual") != null) saw_output = true;
    }
    try std.testing.expect(saw_output);

    // Limpieza.
    const rpath = try std.fmt.allocPrint(allocator, "devagents-workspace\\orden-{d}\\reloj.py", .{outcome.order_id});
    defer allocator.free(rpath);
    const rpath_z = allocator.dupeZ(u8, rpath) catch "";
    defer allocator.free(rpath_z);
    _ = DeleteFileA(rpath_z.ptr);
}

test "approveAndDispatch re-ejecuta la corrección y la APRUEBA si ahora corre (FANOUT-02)" {
    const allocator = std.testing.allocator;
    g_exec_call_count = 0;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var mp = planner.MockPlanner.init(allocator);
    const pb = mp.backend();
    defer pb.deinit();

    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.executor_spawn_fn = testExecutorSpawnFailThenOk;
    var outcome = try sa.processOrder("proj-1", "suma en Python", &.{}, pb, null, null);
    defer outcome.deinit();

    // Original: código válido cuya 1ª ejecución (exit=1) lo marca fallido.
    // Corrección (2ª respuesta LLM): código válido cuya 2ª ejecución (exit=0) lo aprueba.
    var ctx = TestLlmCtxWithCounter{
        .response =
        \\ [{"field":"source","content":"def main():\n  return 1"},{"field":"response","content":"D3_RESULTADO_ANTIGUO"},{"field":"filename","content":"sumar.py"},{"field":"exit_code","content":"0"},{"field":"tests_passed","content":"1"},{"field":"verdict","content":"PASS"}]
        ,
        .correction_response =
        \\ [{"field":"source","content":"def main():\n  return 0"},{"field":"response","content":"D3_RESULTADO_CORREGIDO"},{"field":"filename","content":"sumar.py"},{"field":"exit_code","content":"0"},{"field":"tests_passed","content":"1"},{"field":"verdict","content":"PASS"}]
        ,
    };
    var dr = try sa.approveAndDispatch(&outcome, testLlmFnWithCounter, &ctx, null);
    defer dr.deinit(allocator);

    // Se corrigió y RE-EJECUTÓ con exit=0 → exitosa (no falso-rojo) y verificada (no falso-verde).
    try std.testing.expectEqual(@as(usize, 0), dr.failed_count);
    try std.testing.expect(dr.completed_count > 0);
    try std.testing.expectEqualStrings("D3_RESULTADO_CORREGIDO", dr.final_answer);

    const path = try std.fmt.allocPrint(allocator, "devagents-workspace\\orden-{d}\\sumar.py", .{outcome.order_id});
    defer allocator.free(path);
    const path_z = allocator.dupeZ(u8, path) catch "";
    defer allocator.free(path_z);
    _ = DeleteFileA(path_z.ptr);
}

test "FIX-3: buildUpstreamContext lee artefactos previos y los formatea" {
    const allocator = std.testing.allocator;

    // Crear un archivo temporal directamente con la API Windows (mismo estilo que
    // isContentTriviallyInvalid / buildUpstreamContext) para testear la lectura.
    const test_path = "fix3_test_upstream.py";
    const content = "def suma(a, b):\n    return a + b\n";
    {
        const path_z = try allocator.dupeZ(u8, test_path);
        defer allocator.free(path_z);
        const GENERIC_WRITE: u32 = 0x40000000;
        const CREATE_ALWAYS: u32 = 2;
        const FILE_ATTRIBUTE_NORMAL: u32 = 0x80;
        const h = CreateFileA(path_z.ptr, GENERIC_WRITE, FILE_SHARE_READ, null, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, null);
        if (h == INVALID_HANDLE_VALUE) return error.CreateFileFailed;
        defer _ = CloseHandle(h);
        var written: u32 = 0;
        const len: u32 = @intCast(content.len);
        if (WriteFile(h, content.ptr, len, &written, null) == 0) return error.WriteFileFailed;
    }
    defer {
        const sz = allocator.dupeZ(u8, test_path) catch "";
        defer allocator.free(sz);
        _ = DeleteFileA(sz.ptr);
    }

    const paths = [_][]const u8{test_path};
    const uc = (try buildUpstreamContext(allocator, &paths)) orelse return error.TestUnexpectedResult;
    defer allocator.free(uc);
    try std.testing.expect(std.mem.indexOf(u8, uc, "fix3_test_upstream.py") != null);
    try std.testing.expect(std.mem.indexOf(u8, uc, "def suma") != null);

    // Sin rutas → null (primera ola).
    try std.testing.expect((try buildUpstreamContext(allocator, &.{})) == null);
}

test "E2E-RESULT: buildPlanManifest conserva el objetivo completo para cada worker" {
    const allocator = std.testing.allocator;

    var t1_dep = [_][]const u8{};
    var t2_dep = [_][]const u8{};
    const tasks = [_]planner.PlannedTask{
        .{ .id = "t1", .task_type = .programar, .department = "programacion", .description = "Implementar mathx.py con factorial, gcd", .contract_fields = &.{}, .depends_on = t1_dep[0..] },
        .{ .id = "t2", .task_type = .testear, .department = "testing", .description = "tests que importan de mathx", .contract_fields = &.{}, .depends_on = t2_dep[0..] },
    };
    const goal = "Reloj Go sin dependencias, números romanos, manos, ratón y Hola mundo parpadeante";
    const pm = (try buildPlanManifest(allocator, goal, &tasks)) orelse return error.TestUnexpectedResult;
    defer allocator.free(pm);
    try std.testing.expect(std.mem.indexOf(u8, pm, goal) != null);
    try std.testing.expect(std.mem.indexOf(u8, pm, "t1 [programar/programacion]") != null);
    try std.testing.expect(std.mem.indexOf(u8, pm, "mathx.py con factorial, gcd") != null);
    try std.testing.expect(std.mem.indexOf(u8, pm, "t2 [testear/testing]") != null);

    // Incluso una sola tarea debe recibir el objetivo original, no solo su resumen.
    const single = (try buildPlanManifest(allocator, goal, tasks[0..1])) orelse return error.TestUnexpectedResult;
    defer allocator.free(single);
    try std.testing.expect(std.mem.indexOf(u8, single, goal) != null);
}

