        .depends_on = try allocator.alloc([]const u8, 0),
    };
    const plan = planner.Plan{
        .allocator = allocator,
        .understanding = try allocator.dupe(u8, "goal"),
        .questions = try allocator.alloc(planner.ClarificationQuestion, 0),
        .tasks = tasks,
    };
    var stale = try allocator.alloc(ModelAssignment, 1);
    stale[0] = .{
        .task_id = tasks[0].id,
        .assigned = true,
        .provider_name = try allocator.dupe(u8, "OpenRouter"),
        .model_name = try allocator.dupe(u8, "model-a"),
