    try std.testing.expectEqualStrings("OpenRouter", outcome.assignments[0].provider_name);
    try std.testing.expectEqualStrings("model-b", outcome.assignments[0].model_name);
    try std.testing.expectEqualStrings("t1", outcome.plan.tasks[0].id);
    try std.testing.expectEqualStrings("unchanged goal", outcome.plan.tasks[0].description);
}

test "MODO-DETERMINISTA: con modelo fijado, assignModel no devuelve NINGUN respaldo" {
    // El modo existe para poder contestar "¿este modelo concreto cumple el
    // contrato de artefactos?". Con respaldos esa pregunta no tiene respuesta:
    // cuando el fijado falla, contesta otro y el veredicto se mezcla.
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var catalog = try db.Connection.open(allocator, ":memory:");
    defer catalog.close();
    const migrator = db.Migrator.init(allocator);
    try migrator.migrate(catalog, &db.catalog_schema);
    try catalog.exec("INSERT INTO providers (id,name,base_url,api_style,is_free_tier) VALUES (1,'OpenRouter','x','openai',1)");
    try catalog.exec("INSERT INTO api_keys (id,provider_id,label,key_ciphertext,quota_limit,quota_used,status) VALUES (1,1,'k',x'00',100,0,'active')");
    try catalog.exec("INSERT INTO models (id,provider_id,model_name,context_window,is_free,latency_p50_ms,available) VALUES (1,1,'deepseek/deepseek-chat',128000,1,800,1)");
    try catalog.exec("INSERT INTO models (id,provider_id,model_name,context_window,is_free,latency_p50_ms,available) VALUES (2,1,'ai21/jamba-large-1.7',128000,1,900,1)");
    try catalog.exec("INSERT INTO models (id,provider_id,model_name,context_window,is_free,latency_p50_ms,available) VALUES (3,1,'qwen/qwen-2.5-coder',128000,1,900,1)");
    var router = model_router.Router.init(allocator, catalog, null, 1);
    try router.seedInitialScores();
    var sa = Superagent.init(allocator, runtime, &router, NoopMemory.backend(), 1);
    const pt = planner.PlannedTask{ .id = "t1", .task_type = .programar, .department = "programacion", .description = "x", .contract_fields = &.{}, .depends_on = &.{} };

    // Sin modo determinista: el forzado es primario PERO hay respaldos detras.
    sa.setForcedModel("OpenRouter", "ai21/jamba-large-1.7");
    const con_respaldos = try sa.assignModel(pt, &.{}, &.{});
    defer con_respaldos.deinit(allocator);
    try std.testing.expectEqualStrings("ai21/jamba-large-1.7", con_respaldos.model_name);
    try std.testing.expect(con_respaldos.fallbacks.len > 0);

    // Con modo determinista: mismo primario, CERO respaldos.
    sa.deterministic = true;
    const sin_respaldos = try sa.assignModel(pt, &.{}, &.{});
    defer sin_respaldos.deinit(allocator);
    try std.testing.expect(sin_respaldos.assigned);
    try std.testing.expectEqualStrings("ai21/jamba-large-1.7", sin_respaldos.model_name);
    try std.testing.expectEqualStrings("OpenRouter", sin_respaldos.provider_name);
    try std.testing.expectEqual(@as(usize, 0), sin_respaldos.fallbacks.len);
}

