test "MODELO-LOCAL: taskUsesLocalProvider distingue tareas locales por asignacion y por pin" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var catalog = try db.Connection.open(allocator, ":memory:");
    defer catalog.close();
    const migrator = db.Migrator.init(allocator);
    try migrator.migrate(catalog, &db.catalog_schema);
    try catalog.exec("INSERT INTO providers (id,name,base_url,api_style,is_free_tier) VALUES (1,'OpenRouter','x','openai',1)");
    try catalog.exec("INSERT INTO api_keys (id,provider_id,label,key_ciphertext,quota_limit,quota_used,status) VALUES (1,1,'k',x'00',100,0,'active')");
    try catalog.exec("INSERT INTO models (id,provider_id,model_name,context_window,is_free,latency_p50_ms,available) VALUES (1,1,'deepseek/deepseek-chat',128000,1,800,1)");
    var router = model_router.Router.init(allocator, catalog, null, 1);
    try router.seedInitialScores();
    var sa = Superagent.init(allocator, runtime, &router, NoopMemory.backend(), 1);

    const pt_local = planner.PlannedTask{ .id = "t1", .task_type = .programar, .department = "programacion", .description = "x", .contract_fields = &.{}, .depends_on = &.{} };
    const pt_cloud = planner.PlannedTask{ .id = "t2", .task_type = .programar, .department = "programacion", .description = "y", .contract_fields = &.{}, .depends_on = &.{} };
    var assignments = [_]ModelAssignment{
        .{ .task_id = "t1", .assigned = true, .provider_name = "Ollama", .model_name = "llama3.1:8b", .is_free = true, .reason = "", .fallbacks = try allocator.alloc(ModelChoice, 0) },
        .{ .task_id = "t2", .assigned = true, .provider_name = "OpenRouter", .model_name = "deepseek/deepseek-chat", .is_free = true, .reason = "", .fallbacks = try allocator.alloc(ModelChoice, 0) },
    };
    var tasks = [_]planner.PlannedTask{ pt_local, pt_cloud };
    const plan = planner.Plan{ .allocator = allocator, .understanding = "goal", .questions = try allocator.alloc(planner.ClarificationQuestion, 0), .tasks = &tasks };
    var outcome = OrderOutcome{
        .allocator = allocator,
        .order_id = 1,
        .plan_id = 1,
        .status = .running,
        .plan = plan,
        .assignments = &assignments,
        .discovery_needed = try allocator.alloc([]const u8, 0),
        .discovery_missing = try allocator.alloc([]const u8, 0),
        .discovery_needed_resources = try allocator.alloc(tool_discovery.Resource, 0),
    };
    var ctx = Superagent.FanoutContext{
        .mutex = sync.Mutex.init(),
        .completed = 0,
        .failed = 0,
        .integrated = 0,
        .rejected = 0,
        .outputs = .empty,
        .pending = .empty,
        .saved = .empty,
        .saved_owner = .empty,
        .results = .empty,
        .sa = &sa,
        .outcome = &outcome,
        .llm_fn = null,
        .llm_ctx = null,
        .catalog_path = null,
        .needed_resources = &.{},
    };
    try std.testing.expect(Superagent.taskUsesLocalProvider(&ctx, pt_local));
    try std.testing.expect(!Superagent.taskUsesLocalProvider(&ctx, pt_cloud));
    // Sin asignación resuelta, el pin del rol decide: pin local → tarea local.
    outcome.assignments = &.{};
    sa.setForcedModel("Ollama", "llama3.1:8b");
    try std.testing.expect(Superagent.taskUsesLocalProvider(&ctx, pt_local));
    sa.setForcedModel("OpenRouter", "deepseek/deepseek-chat");
    try std.testing.expect(!Superagent.taskUsesLocalProvider(&ctx, pt_local));
}

