test "ROLES-MODELO: ejecutor y auditor usan pines separados" {
    // El pin de la orden (plan) sigue siendo el general; los pines por rol lo
    // pisan solo para su rol. coordinador=plan pin, ejecutor=exec pin,
    // auditor=audit pin — tres modelos distintos en la misma orden.
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var catalog = try db.Connection.open(allocator, ":memory:");
    defer catalog.close();
    const migrator = db.Migrator.init(allocator);
    try migrator.migrate(catalog, &db.catalog_schema);
    try catalog.exec("INSERT INTO providers (id,name,base_url,api_style,is_free_tier) VALUES (1,'OpenRouter','x','openai',1)");
    try catalog.exec("INSERT INTO api_keys (id,provider_id,label,key_ciphertext,quota_limit,quota_used,status) VALUES (1,1,'k',x'00',100,0,'active')");
    try catalog.exec("INSERT INTO models (id,provider_id,model_name,context_window,is_free,latency_p50_ms,available) VALUES (1,1,'deepseek/deepseek-chat',128000,1,800,1)");
    try catalog.exec("INSERT INTO models (id,provider_id,model_name,context_window,is_free,latency_p50_ms,available) VALUES (2,1,'ai21/jamba-large-1.7',128000,1,900,1)");
    try catalog.exec("INSERT INTO models (id,provider_id,model_name,context_window,is_free,latency_p50_ms,available) VALUES (3,1,'qwen/qwen-2.5-coder',128000,1,900,1)");
    var router = model_router.Router.init(allocator, catalog, null, 1);
    try router.seedInitialScores();
    var sa = Superagent.init(allocator, runtime, &router, NoopMemory.backend(), 1);
    // Mismo orden que c_api: setForcedModel fija el productor y setAuditForcedModel fija el auditor.
    sa.setForcedModel("OpenRouter", "ai21/jamba-large-1.7");
    sa.setAuditForcedModel("OpenRouter", "qwen/qwen-2.5-coder");

    const pt_build = planner.PlannedTask{ .id = "t1", .task_type = .programar, .department = "programacion", .description = "x", .contract_fields = &.{}, .depends_on = &.{} };
    const asg_build = try sa.assignModel(pt_build, &.{}, &.{});
    defer asg_build.deinit(allocator);
    try std.testing.expectEqualStrings("ai21/jamba-large-1.7", asg_build.model_name);

    var dep = [_][]const u8{"t1"};
    const pt_audit = planner.PlannedTask{ .id = "t2", .task_type = .auditar, .department = "auditoria", .description = "x", .contract_fields = &.{}, .depends_on = dep[0..] };
    const asg_audit = try sa.assignModel(pt_audit, &.{pt_build}, &.{asg_build});
    defer asg_audit.deinit(allocator);
    try std.testing.expectEqualStrings("qwen/qwen-2.5-coder", asg_audit.model_name);
}

test "ENJAMBRE: reparto determinista entre miembros y respaldos dentro del conjunto" {
    // Con N miembros, la N-ésima productora toma el miembro N%len: tareas
    // paralelas del mismo plan usan modelos distintos. Los respaldos también
    // salen SOLO del conjunto — nada del router.
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var catalog = try db.Connection.open(allocator, ":memory:");
    defer catalog.close();
    const migrator = db.Migrator.init(allocator);
    try migrator.migrate(catalog, &db.catalog_schema);
    try catalog.exec("INSERT INTO providers (id,name,base_url,api_style,is_free_tier) VALUES (1,'OpenRouter','x','openai',1)");
    try catalog.exec("INSERT INTO api_keys (id,provider_id,label,key_ciphertext,quota_limit,quota_used,status) VALUES (1,1,'k',x'00',100,0,'active')");
    try catalog.exec("INSERT INTO models (id,provider_id,model_name,context_window,is_free,latency_p50_ms,available) VALUES (1,1,'model-a',128000,1,800,1)");
    try catalog.exec("INSERT INTO models (id,provider_id,model_name,context_window,is_free,latency_p50_ms,available) VALUES (2,1,'model-b',128000,1,900,1)");
    try catalog.exec("INSERT INTO models (id,provider_id,model_name,context_window,is_free,latency_p50_ms,available) VALUES (3,1,'model-c',128000,1,900,1)");
    var router = model_router.Router.init(allocator, catalog, null, 1);
    try router.seedInitialScores();
    var sa = Superagent.init(allocator, runtime, &router, NoopMemory.backend(), 1);
    sa.setSwarmJson("[{\"provider\":\"OpenRouter\",\"model\":\"model-a\"},{\"provider\":\"OpenRouter\",\"model\":\"model-b\"}]");
    defer sa.deinitSwarm();

    const pt1 = planner.PlannedTask{ .id = "t1", .task_type = .programar, .department = "programacion", .description = "x", .contract_fields = &.{}, .depends_on = &.{} };
    const pt2 = planner.PlannedTask{ .id = "t2", .task_type = .programar, .department = "programacion", .description = "x", .contract_fields = &.{}, .depends_on = &.{} };
    const pt3 = planner.PlannedTask{ .id = "t3", .task_type = .programar, .department = "programacion", .description = "x", .contract_fields = &.{}, .depends_on = &.{} };
    const tasks = [_]planner.PlannedTask{ pt1, pt2, pt3 };

    const a1 = try sa.assignModel(pt1, &tasks, &.{});
    defer a1.deinit(allocator);
    try std.testing.expectEqualStrings("model-a", a1.model_name);
    var prior1 = [_]ModelAssignment{a1};
    const a2 = try sa.assignModel(pt2, &tasks, prior1[0..]);
    defer a2.deinit(allocator);
    try std.testing.expectEqualStrings("model-b", a2.model_name);
    var prior2 = [_]ModelAssignment{ a1, a2 };
    const a3 = try sa.assignModel(pt3, &tasks, prior2[0..]);
    defer a3.deinit(allocator);
    try std.testing.expectEqualStrings("model-a", a3.model_name);

    // Los respaldos salen SOLO del conjunto: a1 solo puede caer a model-b,
    // jamás a model-c aunque esté en el catálogo.
    try std.testing.expectEqual(@as(usize, 1), a1.fallbacks.len);
    try std.testing.expectEqualStrings("model-b", a1.fallbacks[0].model_name);
}

