test "ENJAMBRE: gobernanza Solo gratis deja fuera a miembros de pago" {
    // El enjambre elige modelos, pero nunca autoriza gasto dentro de Free —
    // misma regla que el pin manual. Todos de pago → fallo honesto nombrando
    // el enjambre, no un salto silencioso al router.
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var catalog = try db.Connection.open(allocator, ":memory:");
    defer catalog.close();
    const migrator = db.Migrator.init(allocator);
    try migrator.migrate(catalog, &db.catalog_schema);
    try catalog.exec("INSERT INTO providers (id,name,base_url,api_style,is_free_tier) VALUES (1,'OpenRouter','x','openai',1)");
    try catalog.exec("INSERT INTO api_keys (id,provider_id,label,key_ciphertext,quota_limit,quota_used,status) VALUES (1,1,'k',x'00',100,0,'active')");
    try catalog.exec("INSERT INTO models (id,provider_id,model_name,context_window,is_free,latency_p50_ms,available) VALUES (1,1,'model-free',128000,1,800,1)");
    try catalog.exec("INSERT INTO models (id,provider_id,model_name,context_window,is_free,latency_p50_ms,available) VALUES (2,1,'model-paid',128000,0,900,1)");
    var router = model_router.Router.init(allocator, catalog, null, 1);
    try router.seedInitialScores();
    try router.setGovernanceMode(.free_tier_first);
    var sa = Superagent.init(allocator, runtime, &router, NoopMemory.backend(), 1);
    sa.setSwarmJson("[{\"provider\":\"OpenRouter\",\"model\":\"model-paid\"},{\"provider\":\"OpenRouter\",\"model\":\"model-free\"}]");
    defer sa.deinitSwarm();

    const pt1 = planner.PlannedTask{ .id = "t1", .task_type = .programar, .department = "programacion", .description = "x", .contract_fields = &.{}, .depends_on = &.{} };
    const a1 = try sa.assignModel(pt1, &.{pt1}, &.{});
    defer a1.deinit(allocator);
    // El reparto empezaba en model-paid, pero Solo gratis lo salta → model-free.
    try std.testing.expectEqualStrings("model-free", a1.model_name);

    // Todos de pago → enjambre agotado: sin asignación, razón honesta.
    sa.setSwarmJson("[{\"provider\":\"OpenRouter\",\"model\":\"model-paid\"}]");
    const a2 = try sa.assignModel(pt1, &.{pt1}, &.{});
    defer a2.deinit(allocator);
    try std.testing.expect(!a2.assigned);
    try std.testing.expect(std.mem.indexOf(u8, a2.reason, "enjambre") != null);
}

test "ENJAMBRE: pin de ejecutor respeta el interruptor y el conjunto vacío no cambia nada" {
    // el pin no apaga el reparto; el interruptor lo gobierna.
    // Sin enjambre (null, "[]" o JSON roto) el ruteo es el de siempre.
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var catalog = try db.Connection.open(allocator, ":memory:");
    defer catalog.close();
    const migrator = db.Migrator.init(allocator);
    try migrator.migrate(catalog, &db.catalog_schema);
    try catalog.exec("INSERT INTO providers (id,name,base_url,api_style,is_free_tier) VALUES (1,'OpenRouter','x','openai',1)");
    try catalog.exec("INSERT INTO api_keys (id,provider_id,label,key_ciphertext,quota_limit,quota_used,status) VALUES (1,1,'k',x'00',100,0,'active')");
    try catalog.exec("INSERT INTO models (id,provider_id,model_name,context_window,is_free,latency_p50_ms,available) VALUES (1,1,'model-a',128000,1,800,1)");
    try catalog.exec("INSERT INTO models (id,provider_id,model_name,context_window,is_free,latency_p50_ms,available) VALUES (2,1,'model-b',128000,1,900,1)");
    var router = model_router.Router.init(allocator, catalog, null, 1);
    try router.seedInitialScores();
    var sa = Superagent.init(allocator, runtime, &router, NoopMemory.backend(), 1);
    const pt = planner.PlannedTask{ .id = "t1", .task_type = .programar, .department = "programacion", .description = "x", .contract_fields = &.{}, .depends_on = &.{} };

    sa.setSwarmJson("[{\"provider\":\"OpenRouter\",\"model\":\"model-a\"}]");
    defer sa.deinitSwarm();
    sa.setExecForcedModel("OpenRouter", "model-b");
    const pinned = try sa.assignModel(pt, &.{pt}, &.{});
    defer pinned.deinit(allocator);
    try std.testing.expectEqualStrings("model-a", pinned.model_name);
    try composer_roles.setSwarmEnabled(catalog, false);
    const disabled = try sa.assignModel(pt, &.{pt}, &.{});
    defer disabled.deinit(allocator);
    try std.testing.expectEqualStrings("model-b", disabled.model_name);
    try composer_roles.setSwarmEnabled(catalog, true);

    // "[]" y JSON roto = Automático: cae al router como siempre.
    sa.setExecForcedModel(null, null);
    sa.setSwarmJson("[]");
    const auto1 = try sa.assignModel(pt, &.{pt}, &.{});
    defer auto1.deinit(allocator);
    try std.testing.expect(auto1.assigned);
    try std.testing.expectEqual(@as(usize, 0), sa.swarm.len);

    sa.setSwarmJson("esto no es json");
    try std.testing.expectEqual(@as(usize, 0), sa.swarm.len);
}

