    try catalog.exec("INSERT INTO models (id,provider_id,model_name,context_window,is_free,latency_p50_ms,available) VALUES (2,1,'minimax/minimax-m1',128000,1,810,1)");
    try catalog.exec("INSERT INTO models (id,provider_id,model_name,context_window,is_free,latency_p50_ms,available) VALUES (3,1,'minimax/minimax-m2',128000,1,820,1)");
    try catalog.exec("INSERT INTO models (id,provider_id,model_name,context_window,is_free,latency_p50_ms,available) VALUES (4,1,'qwen/qwen-2.5-coder-32b-instruct',128000,1,830,1)");
    try catalog.exec("INSERT INTO models (id,provider_id,model_name,context_window,is_free,latency_p50_ms,available) VALUES (5,1,'deepseek/deepseek-chat',128000,1,840,1)");
    var router = model_router.Router.init(allocator, catalog, null, 1);
