    const asg = try sa.assignModel(pt, &.{}, &.{});
    defer asg.deinit(allocator);
    try std.testing.expect(asg.assigned);
    var families: usize = 0;
    var minimax_count: usize = 0;
    var seen: [8][]const u8 = undefined;
    for (asg.fallbacks) |fc| {
        const fam = modelFamily(fc.model_name);
        if (std.mem.eql(u8, fam, "minimax")) minimax_count += 1;
        var nuevo = true;
        var i: usize = 0;
        while (i < families) : (i += 1) {
            if (std.mem.eql(u8, seen[i], fam)) {
                nuevo = false;
                break;
            }
        }
        if (nuevo and families < seen.len) {
            seen[families] = fam;
            families += 1;
        }
    }
    try std.testing.expect(families >= 2);
    try std.testing.expect(minimax_count <= 2);
}

// ── H-06: Test de streaming (Etapa 2) ──────────────────────────────────

/// Spawn mock que simula streaming ConPTY: llama al sink con 3 trozos y
/// devuelve RunResult con la salida completa acumulada.
fn testExecutorSpawnStreaming(a: std.mem.Allocator, _: []const u8, _: []const []const u8, _: []const u8, _: u32, _: usize, sink: ?executor.StreamSink, sink_ctx: ?*anyopaque, _: []const u8) executor.ExecutorError!executor.RunResult {
    if (sink) |s| {
        s(sink_ctx, "tick 1\n", .stdout);
        s(sink_ctx, "tick 2\n", .stdout);
        s(sink_ctx, "tick 3\n", .stdout);
    }
    return executor.RunResult{
        .exit_code = 0,
        .stdout = try a.dupe(u8, "tick 1\ntick 2\ntick 3\n"),
        .stderr = try a.dupe(u8, ""),
    };
}

var egov4_command: [256]u8 = undefined;
var egov4_command_len: usize = 0;

fn egov4RecordingSpawn(a: std.mem.Allocator, exe: []const u8, args: []const []const u8, _: []const u8, _: u32, _: usize, _: ?executor.StreamSink, _: ?*anyopaque, _: []const u8) executor.ExecutorError!executor.RunResult {
    var w: std.Io.Writer = .fixed(&egov4_command);
    w.writeAll(std.fs.path.basename(exe)) catch {};
    for (args) |arg| {
        w.writeByte(' ') catch {};
        w.writeAll(arg) catch {};
    }
    egov4_command_len = w.end;
    return executor.RunResult{ .exit_code = 0, .stdout = try a.dupe(u8, ""), .stderr = try a.dupe(u8, "") };
}

test "E-GOV.4: un productor de biblioteca Go se verifica con go build, sin go run" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var mp = planner.MockPlanner.init(allocator);
    const pb = mp.backend();
    defer pb.deinit();
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.executor_spawn_fn = egov4RecordingSpawn;
    sa.permission_config.mode = .bypass;
    var outcome = try sa.processOrder("proj-1", "reloj en Go que imprime la hora", &.{}, pb, null, null);
    defer outcome.deinit();
    var ctx = TestLlmCtx{ .response =
        \\ [{"field":"source","content":"package pflag\nfunc Get() string { return \"x\" }\n"},{"field":"filename","content":"flag.go"},{"field":"exit_code","content":"0"},{"field":"tests_passed","content":"1"},{"field":"verdict","content":"PASS"}]
    };
    egov4_command_len = 0;
    var dr = try sa.approveAndDispatch(&outcome, testLlmFn, &ctx, null);
    defer dr.deinit(allocator);
    // `go` es un lanzador indirecto: aun en bypass pide tarjeta. La prueba vale
    // por cualquiera de los dos caminos (ejecutado o tarjeta pendiente), y en
    // ambos el comando debe ser `go build flag.go`, nunca `go run`.
    var card_buf: [512]u8 = undefined;
    var command: []const u8 = egov4_command[0..egov4_command_len];
    for (dr.pending_approvals) |ap| {
        if (ap.args_json) |args| command = std.fmt.bufPrint(&card_buf, "{s} {s}", .{ ap.exe orelse "", args }) catch command;
    }
    // Tarjeta: `go {"args":["build","flag.go"],…}`; ejecución: `go build flag.go`.
    const built = std.mem.indexOf(u8, command, "\"args\":[\"build\",\"flag.go\"]") != null or std.mem.indexOf(u8, command, "go build flag.go") != null;
    if (!built) std.debug.print("[E-GOV.4] comando inesperado: {s}\n", .{command});
    try std.testing.expect(built);
    try std.testing.expect(std.mem.indexOf(u8, command, "\"run\"") == null and std.mem.indexOf(u8, command, " run flag.go") == null);
    const path = try std.fmt.allocPrint(allocator, "devagents-workspace\\orden-{d}\\flag.go", .{outcome.order_id});
    defer allocator.free(path);
    const path_z = allocator.dupeZ(u8, path) catch "";
    defer allocator.free(path_z);
    _ = DeleteFileA(path_z.ptr);
}

test "H-06: governedExecute emite worker_output por cada trozo de streaming + resumen final" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
