    defer outcome.deinit();

    var ctx = TestLlmCtx{ .response =
        \\ [{"field":"source","content":"import time\nwhile True:\n  print('tick')\n  time.sleep(1)"},{"field":"filename","content":"reloj.py"},{"field":"exit_code","content":"0"},{"field":"tests_passed","content":"1"},{"field":"verdict","content":"PASS"}]
    };
    var dr = try sa.approveAndDispatch(&outcome, testLlmFn, &ctx, null);
    defer dr.deinit(allocator);

    // Debe haber worker_outputs: 3 trozos streaming + 1 resumen final = 4 mínimo.
    try std.testing.expect(dr.outputs.len >= 4);

    // Los 3 primeros deben ser los trozos de streaming en orden.
    var found_tick1 = false;
    var found_tick2 = false;
    var found_tick3 = false;
    var found_summary = false;
    for (dr.outputs) |o| {
