        if (std.mem.eql(u8, o.text, "tick 2\n")) found_tick2 = true;
        if (std.mem.eql(u8, o.text, "tick 3\n")) found_tick3 = true;
        if (std.mem.indexOf(u8, o.text, "exit=0") != null) found_summary = true;
    }
    try std.testing.expect(found_tick1);
    try std.testing.expect(found_tick2);
    try std.testing.expect(found_tick3);
    try std.testing.expect(found_summary);

    // Limpieza.
    const path = try std.fmt.allocPrint(allocator, "devagents-workspace\\orden-{d}\\reloj.py", .{outcome.order_id});
    defer allocator.free(path);
    const path_z = allocator.dupeZ(u8, path) catch "";
    defer allocator.free(path_z);
    _ = DeleteFileA(path_z.ptr);
}

// ── FIX-DISPATCH-P0: Tests for dispatch stability under provider failure ──

/// LLM fn that simulates a provider 401/auth_failed: returns empty string
/// (same as live_worker.llmFn when all providers are exhausted).
const FailingLlmCtx = struct {
    call_count: usize = 0,
};

fn failingLlmFn(ctx: *anyopaque, _: []const u8, _: []const u8) []const u8 {
    const c: *FailingLlmCtx = @ptrCast(@alignCast(ctx));
    c.call_count += 1;
    // Simulate all providers returning 401 → empty string (InvalidArtifact → task failed)
    return "";
}

test "FIX-DISPATCH-P0: provider 401 during dispatch does not crash" {
