    sa.executor_spawn_fn = testExecutorSpawn;
    var outcome = try sa.processOrder("proj-1", "construye una calculadora CLI en C con tests", &.{}, pb, null, null);
    defer outcome.deinit();

    var ctx = FailingLlmCtx{};
    var dr = try sa.approveAndDispatch(&outcome, failingLlmFn, &ctx, null);
    defer dr.deinit(allocator);

    // Dispatch completed without crash — all tasks failed due to empty LLM response.
    try std.testing.expect(ctx.call_count > 0);
    try std.testing.expect(dr.failed_count > 0);
    try std.testing.expectEqual(@as(usize, 0), dr.completed_count);
}

