    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.setEventConn(runtime, 1);

    const won = try runtime.tryCommitTerminal(1, OrderStatus.done.toText(), "order_done", "test", "{}", 1);
    try std.testing.expect(won);

    sa.recordEvent("agent_message", "{\"text\":\"a\"}");
    sa.recordEvent("agent_message", "{\"text\":\"b\"}");

    const stmt = try runtime.prepare("SELECT COUNT(*) FROM events WHERE order_id = 1 AND kind = 'agent_message'");
    defer runtime.finalize(stmt);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
    try std.testing.expectEqual(@as(c_int, 2), db.c.sqlite3_column_int(stmt, 0));
}

test "TERMINAL-P0 F: dispatch_failed stays informational and never blocks a later real terminal" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    try runtime.exec("INSERT INTO orders (id, project_id, user_prompt, status, created_at) VALUES (1, 'p', 'hi', 'running', 1)");

    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.setEventConn(runtime, 1);

    sa.recordEvent("dispatch_failed", "{\"error\":\"boom\"}");

    // dispatch_failed no fuerza estado terminal: la orden sigue 'running'.
    const mid_status = try fetchOrderStatus(allocator, runtime, 1);
    defer allocator.free(mid_status);
    try std.testing.expectEqualStrings("running", mid_status);

    // Un terminal real posterior no queda bloqueado por dispatch_failed.
    const won = try runtime.tryCommitTerminal(1, OrderStatus.done.toText(), "order_done", "superagente", "{}", 2);
    try std.testing.expect(won);

    const final_status = try fetchOrderStatus(allocator, runtime, 1);
    defer allocator.free(final_status);
    try std.testing.expectEqualStrings("done", final_status);

    // Ambos eventos coexisten: dispatch_failed no es autoridad terminal.
    const stmt = try runtime.prepare("SELECT COUNT(*) FROM events WHERE order_id = 1 AND kind IN ('dispatch_failed','order_done')");
    defer runtime.finalize(stmt);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
    try std.testing.expectEqual(@as(c_int, 2), db.c.sqlite3_column_int(stmt, 0));
}

test "MULTISESSION-P0 G: fan-out threads in the same wave never lose recordEvent writes to an unsynchronized race" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var mp = planner.MockPlanner.init(allocator);
    const pb = mp.backend();
    defer pb.deinit();

    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    var outcome = try sa.processOrder("proj-fanout", "construye una calculadora CLI en C con tests", &.{}, pb, null, null);
    defer outcome.deinit();
    sa.setEventConn(runtime, outcome.order_id);

    // MockPlanner produce t1 (programar, ola 1) + t2 (testear) + t3 (auditar),
    // ambas dependientes SOLO de t1 (no entre sí) → misma ola 2, 2 hilos reales
    // en paralelo. Antes del fix (MULTISESSION-P0), sus recordEvent("task_started")
    // corrían sin coordinar contra el mismo event_conn.
    try std.testing.expectEqual(@as(usize, 3), outcome.plan.tasks.len);

    var dr = try sa.approveAndDispatch(&outcome, null, null, null);
    defer dr.deinit(allocator);

    const stmt = try runtime.prepare("SELECT COUNT(*) FROM events WHERE order_id = ? AND kind = 'task_started'");
    defer runtime.finalize(stmt);
    try db.bindInt(stmt, 1, outcome.order_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
    try std.testing.expectEqual(@as(c_int, 3), db.c.sqlite3_column_int(stmt, 0));
}

