test "MOT017 worker system prompt imposes the order language for prose tasks" {
    const a = std.testing.allocator;
    const es_order = "Documenta brevemente en un texto los riesgos de guardar claves de API en texto plano";
    const en_order = "Document the risks of storing API keys in plain text";
    const base = "Eres un agente de documentacion.";

    const es_prompt = try buildWorkerSystemPrompt(a, base, .documentar, es_order, false);
    defer a.free(es_prompt);
    try std.testing.expect(std.mem.indexOf(u8, es_prompt, "Responde en español") != null);

    const en_prompt = try buildWorkerSystemPrompt(a, base, .documentar, en_order, false);
    defer a.free(en_prompt);
    try std.testing.expect(std.mem.indexOf(u8, en_prompt, "Responde en inglés") != null);

    // Sin idioma concluyente no se impone nada.
