fn tareaConContrato(fields: []planner.ContractField) planner.PlannedTask {
    return .{
        .id = "t1",
        .task_type = .programar,
        .department = "programacion",
        .description = "una web con un contador",
        .contract_fields = fields,
        .depends_on = &.{},
    };
}

