test "F8-T6: cross-turn messages are safely discarded without breaking sub-agent streams" {
    const allocator = std.testing.allocator;
    var conn = try db.Connection.open(allocator, ":memory:");
    defer conn.close();

    var sa = Superagent.init(allocator, conn, null, NoopMemory.backend(), 1);
    sa.setEventConn(conn, 100);

    // Record stream events from current turn
    sa.recordEvent("subagent_stream_start", "{\"turn_id\":10, \"agent\":\"worker-1\"}");
    sa.recordEvent("subagent_stream_chunk", "{\"turn_id\":10, \"chunk\":\"output fragment\"}");

    // Simulate cross-turn event from old turn (turn_id 9)
    sa.recordEvent("cross_turn_event", "{\"turn_id\":9, \"stale\":true}");

    // Stream continues without crash
    sa.recordEvent("subagent_stream_end", "{\"turn_id\":10, \"status\":\"success\"}");
}

// ── BUG-1: un evento perdido por contencion QUEDA CONTADO ─────────────────

test "BUG-1: con la base bloqueada por otro escritor, el evento se pierde y se CUENTA" {
    const allocator = std.testing.allocator;
    // Hace falta un ARCHIVO: `:memory:` da bases aisladas por conexion y no hay
    // contencion posible, que es justo lo que se quiere reproducir.
    const ruta = ".zig-cache/bug1-contencion.db";
    // Nombre fijo bajo `.zig-cache`, que es descartable: SQLite reabre y reusa.

    var escritor = try db.Connection.open(allocator, ruta);
    defer escritor.close();
    var migrator = db.Migrator.init(allocator);
    try migrator.migrate(escritor, &db.runtime_schema);

    var emisor = try db.Connection.open(allocator, ruta);
    defer emisor.close();

    // El otro hilo del motor (despacho, planificador...) sosteniendo su
    // transaccion de escritura: exactamente la situacion de la orden #237, con
    // `journal_mode = DELETE` y un solo escritor permitido.
    try escritor.exec("PRAGMA busy_timeout = 0");
    try emisor.exec("PRAGMA busy_timeout = 0");
    try escritor.exec("BEGIN EXCLUSIVE");
    defer escritor.exec("COMMIT") catch {};

    var runtime = try db.Connection.open(allocator, ":memory:");
    defer runtime.close();
    try migrator.migrate(runtime, &db.runtime_schema);
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.setEventConn(emisor, 1);

    try std.testing.expectEqual(@as(usize, 0), sa.eventosPerdidos());
    sa.recordEvent("task_started", "{}");
    // Antes esto se tragaba el SQLITE_BUSY y devolvia como si nada: la orden
    // acababa `done` con cero eventos y nadie sabia que se habian perdido.
    try std.testing.expectEqual(@as(usize, 1), sa.eventosPerdidos());
}

