/// (red real): detector de reentrada en el spawn de procesos.
///
/// `governedExecute` se llama DENTRO de la sección crítica de `runTaskInWave`
/// (el `ctx.mutex.lock()` con `defer unlock` que abarca hasta el final de la
/// función), y pasa por `executor_spawn_fn`. Si esa exclusión mutua desaparece,
/// dos hilos de la misma ola entran a la vez y `max_active` sube a 2.
///
/// El `Sleep` ensancha la ventana a propósito: sin él, una carrera real puede
/// no llegar a solaparse en una máquina rápida y el chequeo daría verde por
/// suerte, que es exactamente el defecto que reabrió.
const SpawnReentrancyCtx = struct {
    mutex: sync.Mutex,
    active: usize = 0,
    max_active: usize = 0,
    calls: usize = 0,
};

var g_spawn_reentrancy: ?*SpawnReentrancyCtx = null;

/// Planificador de prueba: N tareas de programación SIN dependencias, o sea
/// todas en la MISMA ola. El `MockPlanner` no sirve para esto — su plan es
/// t1 → {t2 testear, t3 auditar}, y de esos solo t1 llega a ejecutar nada, así
/// que un detector de reentrada sobre el spawn no tenía a quién solaparse (lo
/// cazó la guarda `calls >= 2` en la primera corrida de este test).
const ParallelPlanner = struct {
    n: usize,

    fn backend(self: *ParallelPlanner) planner.PlannerBackend {
        return .{ .ptr = self, .planFn = planImpl, .deinitFn = noopDeinit };
    }

    fn noopDeinit(_: *anyopaque) void {}

    fn planImpl(ctx: *anyopaque, allocator: std.mem.Allocator, order_text: []const u8, _: []const planner.ClarificationAnswer, _: ?[]const u8) planner.PlannerError!planner.Plan {
        const self: *ParallelPlanner = @ptrCast(@alignCast(ctx));
        var list = std.ArrayList(planner.PlannedTask).empty;
        errdefer list.deinit(allocator);

        var i: usize = 0;
        while (i < self.n) : (i += 1) {
            const cf = try allocator.alloc(planner.ContractField, 1);
            errdefer allocator.free(cf);
            cf[0] = .{ .name = try allocator.dupe(u8, "source"), .field_type = .string, .required = true };
            try list.append(allocator, .{
                .id = try std.fmt.allocPrint(allocator, "t{d}", .{i + 1}),
                .task_type = .programar_c,
                .department = try allocator.dupe(u8, "programacion"),
                // El prefijo «Ejecutar » es lo que `extractCommandFromDesc`
                // reconoce: lleva a `governedExecuteRaw`, que vive DENTRO de la
                // sección crítica. Es el punto de observación del test.
                .description = try std.fmt.allocPrint(allocator, "Ejecutar npm --version {d}", .{i + 1}),
                .contract_fields = cf,
                .depends_on = try allocator.alloc([]const u8, 0),
            });
        }

        return .{
            .allocator = allocator,
            .understanding = try std.fmt.allocPrint(allocator, "Orden: \"{s}\". {d} piezas independientes.", .{ order_text, self.n }),
            .questions = try allocator.alloc(planner.ClarificationQuestion, 0),
            .tasks = try list.toOwnedSlice(allocator),
        };
    }
};

fn reentrantSpawnFn(a: std.mem.Allocator, _: []const u8, _: []const []const u8, _: []const u8, _: u32, _: usize, _: ?executor.StreamSink, _: ?*anyopaque, _: []const u8) executor.ExecutorError!executor.RunResult {
    if (g_spawn_reentrancy) |c| {
        c.mutex.lock();
        c.active += 1;
        c.calls += 1;
        if (c.active > c.max_active) c.max_active = c.active;
        c.mutex.unlock();

        Sleep(25);

        c.mutex.lock();
        c.active -= 1;
        c.mutex.unlock();
    }
    return executor.RunResult{ .exit_code = 0, .stdout = try a.dupe(u8, "ok"), .stderr = try a.dupe(u8, "") };
}

/// D7: planificador de prueba con dos productores independientes (t1, t2) y un
/// tercero (t3) que depende SOLO de t1. t1 y t2 caen en la ola 0, t3 en la 1 —
/// o sea, cuando t3 arranca, los dos archivos ya están en disco. Es el montaje
/// determinista que hace falta: si t3 ve el archivo de t2, es por el contexto
/// compartido, no por una carrera.
const D7Planner = struct {
    fn backend(self: *D7Planner) planner.PlannerBackend {
        return .{ .ptr = self, .planFn = planImpl, .deinitFn = noopDeinit };
    }
    fn noopDeinit(_: *anyopaque) void {}

    fn tarea(allocator: std.mem.Allocator, id: []const u8, desc: []const u8, deps: []const []const u8) !planner.PlannedTask {
        const cf = try allocator.alloc(planner.ContractField, 1);
        errdefer allocator.free(cf);
        cf[0] = .{ .name = try allocator.dupe(u8, "source"), .field_type = .string, .required = true };
        const dd = try allocator.alloc([]const u8, deps.len);
        errdefer allocator.free(dd);
        for (deps, 0..) |d, i| dd[i] = try allocator.dupe(u8, d);
        return .{
            .id = try allocator.dupe(u8, id),
            .task_type = .programar,
            .department = try allocator.dupe(u8, "programacion"),
            .description = try allocator.dupe(u8, desc),
            .contract_fields = cf,
            .depends_on = dd,
        };
    }

    fn planImpl(_: *anyopaque, allocator: std.mem.Allocator, order_text: []const u8, _: []const planner.ClarificationAnswer, _: ?[]const u8) planner.PlannerError!planner.Plan {
        var list = std.ArrayList(planner.PlannedTask).empty;
        errdefer list.deinit(allocator);
        try list.append(allocator, try tarea(allocator, "t1", "PIEZA_A independiente", &.{}));
        try list.append(allocator, try tarea(allocator, "t2", "PIEZA_B independiente", &.{}));
        try list.append(allocator, try tarea(allocator, "t3", "PIEZA_C que depende solo de PIEZA_A", &.{"t1"}));
        return .{
            .allocator = allocator,
            .understanding = try allocator.dupe(u8, order_text),
            .questions = try allocator.alloc(planner.ClarificationQuestion, 0),
            .tasks = try list.toOwnedSlice(allocator),
        };
    }
};

const D7LlmCtx = struct {
    mutex: sync.Mutex,
    allocator: std.mem.Allocator,
    /// Copia del prompt de usuario que recibió CADA tarea. Es lo que se audita:
    /// no lo que creemos que se le pasó, sino lo que se le pasó.
    prompts: std.ArrayList([]const u8),

    fn deinit(self: *D7LlmCtx) void {
        for (self.prompts.items) |p| self.allocator.free(p);
        self.prompts.deinit(self.allocator);
    }
};

fn d7LlmFn(ctx: *anyopaque, _: []const u8, user: []const u8) []const u8 {
    const c: *D7LlmCtx = @ptrCast(@alignCast(ctx));
    c.mutex.lock();
    defer c.mutex.unlock();
    if (c.allocator.dupe(u8, user)) |copia| {
        c.prompts.append(c.allocator, copia) catch c.allocator.free(copia);
    } else |_| {}

    // El discriminador tiene que ser el encabezado `TAREA` del propio prompt, no
    // la descripción a secas: el manifiesto del plan lista TODAS las tareas de la
    // orden, así que las tres descripciones aparecen en los tres prompts. Con el
    // marcador flojo, las tres tareas devolvían el mismo contenido y el test daba
    // un falso rojo que parecía del aislamiento.
    if (std.mem.indexOf(u8, user, "TAREA\nPIEZA_A") != null) {
        return "[{\"field\":\"source\",\"content\":\"MARCA_DE_LA_RAMA_A = 1;\"}]";
    }
    if (std.mem.indexOf(u8, user, "TAREA\nPIEZA_B") != null) {
        return "[{\"field\":\"source\",\"content\":\"MARCA_DE_LA_RAMA_B = 2;\"}]";
    }
    return "[{\"field\":\"source\",\"content\":\"MARCA_DE_LA_RAMA_C = 3;\"}]";
}

test "E-50: un .js de navegador NO se ejecuta con node" {
    // Ordenes #343 y #349 (2026-08-15): el motor escribia el `script.js` de una
    // pagina web y lo lanzaba con `node`. `ReferenceError: document is not
    // defined`, tarea fallida, ORDEN fallida — con el HTML y el CSS perfectos y
    // el propio JavaScript correcto para lo que es. El caso `web-multiarchivo`
    // del gate no podia cerrar en verde por diseño.
    const allocator = std.testing.allocator;

    const Caso = struct { nombre: []const u8, contenido: []const u8, es_navegador: bool };
    const casos = [_]Caso{
        .{ .nombre = "e50-navegador.js", .contenido = "document.querySelector('#b').addEventListener('click', f);", .es_navegador = true },
        .{ .nombre = "e50-dom2.js", .contenido = "window.addEventListener('DOMContentLoaded', init);", .es_navegador = true },
        .{ .nombre = "e50-guardado.js", .contenido = "localStorage.setItem('k','v');", .es_navegador = true },
        // Y lo que SI es de Node y debe seguir ejecutandose: si esto diera true,
        // el arreglo habria apagado la ejecucion de todo el JavaScript.
        .{ .nombre = "e50-consola.js", .contenido = "const fs = require('fs'); console.log('hola');", .es_navegador = false },
        .{ .nombre = "e50-puro.js", .contenido = "function suma(a,b){return a+b;} console.log(suma(2,3));", .es_navegador = false },
        // La extension manda: un .py con `document.` dentro no es js de navegador.
        .{ .nombre = "e50-falso.py", .contenido = "# document.querySelector", .es_navegador = false },
    };

    const GENERIC_WRITE: u32 = 0x40000000;
    const CREATE_ALWAYS: u32 = 2;

    for (casos) |c| {
        const ruta_z = try allocator.dupeZ(u8, c.nombre);
        defer allocator.free(ruta_z);
        {
            const h = CreateFileA(ruta_z.ptr, GENERIC_WRITE, 0, null, CREATE_ALWAYS, 0, null);
            try std.testing.expect(h != INVALID_HANDLE_VALUE);
            defer _ = CloseHandle(h);
            var escritos: u32 = 0;
            _ = WriteFile(h, c.contenido.ptr, @intCast(c.contenido.len), &escritos, null);
        }
        defer _ = DeleteFileA(ruta_z.ptr);
        try std.testing.expectEqual(c.es_navegador, isBrowserScript(allocator, c.nombre));
    }

    // Un archivo que no existe no es «de navegador»: no se inventa un veredicto
    // sobre algo que no se pudo leer.
    try std.testing.expect(!isBrowserScript(allocator, "e50-no-existe.js"));
}

test "D7: una rama NO ve el artefacto de una rama con la que no tiene dependencia" {
    // El criterio de aceptación de D7, contra el despacho real.
    //
    // Antes de `subagent.zig`, `buildUpstreamContext` metía TODOS los archivos
    // guardados en un solo bloque y se lo daba igual a todas las tareas de la
    // ola siguiente. t3 depende solo de t1, y aun así recibía el artefacto de
    // t2 —una rama con la que no tiene ninguna relación— gastando su contexto
    // y su presupuesto de tokens en algo que no le incumbe.
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var dp = D7Planner{};
    const pb = dp.backend();
    defer pb.deinit();

    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.executor_spawn_fn = testExecutorSpawnOk;
    var outcome = try sa.processOrder("proj-d7", "tres piezas", &.{}, pb, null, null);
    defer outcome.deinit();

    var lctx = D7LlmCtx{ .mutex = sync.Mutex.init(), .allocator = allocator, .prompts = std.ArrayList([]const u8).empty };
    defer lctx.deinit();

    var dr = try sa.approveAndDispatch(&outcome, d7LlmFn, &lctx, null);
    defer dr.deinit(allocator);

    // El prompt de t3 es el único que menciona PIEZA_C.
    var prompt_c: ?[]const u8 = null;
    for (lctx.prompts.items) |p| {
        if (std.mem.indexOf(u8, p, "TAREA\nPIEZA_C") != null) prompt_c = p;
    }
    const pc = prompt_c orelse return error.TestUnexpectedResult;
    // Ve a su ancestro…
    try std.testing.expect(std.mem.indexOf(u8, pc, "MARCA_DE_LA_RAMA_A") != null);
    // …y NO ve a la rama ajena. Esta es la línea que falla sin el aislamiento.
    try std.testing.expect(std.mem.indexOf(u8, pc, "MARCA_DE_LA_RAMA_B") == null);

    // R14: si t1 y t2 no hubieran escrito nada, lo de arriba sería verdad por
    // vacío. Se comprueba que la rama A existió de verdad.
    try std.testing.expect(dr.completed_count >= 2);

    // Limpieza de los archivos que el despacho dejó en disco.
    for ([_][]const u8{ "t1", "t2", "t3" }) |tid| {
        const path = std.fmt.allocPrint(allocator, "devagents-workspace\\orden-{d}\\{s}.txt", .{ outcome.order_id, tid }) catch continue;
        defer allocator.free(path);
        const path_z = allocator.dupeZ(u8, path) catch continue;
        defer allocator.free(path_z);
        _ = DeleteFileA(path_z.ptr);
    }
}

test "E-32: la seccion critica de runTaskInWave excluye de verdad a los hilos de la ola" {
    // Por qué existe este test, dicho sin adornos: el que había antes se ponía
    // SU PROPIO `ctx.mutex.lock()` dentro del hilo de prueba y llamaba a
    // `appendAuditEntry` a mano. Pasaba igual con el cerrojo de PRODUCCIÓN
    // retirado, porque nunca ejecutaba `runTaskInWave`. Cobertura falsa: eso es
    // lo que reabrió el 2026-08-15.
    //
    // Este entra por `approveAndDispatch` → olas reales → `runTaskInWave`, y
    // observa desde dentro de la sección crítica (a través de `executor_spawn_fn`,
    // que `governedExecute` invoca ahí dentro).
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var pp = ParallelPlanner{ .n = 4 };
    const pb = pp.backend();
    defer pb.deinit();

    var reent = SpawnReentrancyCtx{ .mutex = sync.Mutex.init() };
    g_spawn_reentrancy = &reent;
    defer g_spawn_reentrancy = null;

    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.executor_spawn_fn = reentrantSpawnFn;
    // P-EXEC-6: sin esto cada comando pararía en la aprobación y no se
    // ejecutaría ninguno — no habría nada que solapar.
    sa.plan_approved = true;
    // Cuatro tareas sin dependencias: una sola ola, cuatro hilos a la vez.
    var outcome = try sa.processOrder("proj-1", "cuatro piezas en C", &.{}, pb, null, null);
    defer outcome.deinit();

    var ctx = TestLlmCtx{ .response =
        \\ [{"field":"source","content":"int main(){return 0;}"}]
    };
    var dr = try sa.approveAndDispatch(&outcome, testLlmFn, &ctx, null);
    defer dr.deinit(allocator);

    // R14: un chequeo que no puede fallar no es un chequeo. Si el spawn no se
    // llegó a invocar dos veces, `max_active == 1` sería verdad por vacío.
    try std.testing.expect(reent.calls >= 2);
    try std.testing.expectEqual(@as(usize, 1), reent.max_active);

    // Y el efecto observable que protege el cerrojo: una entrada de auditoría
    // por tarea completada, ni perdida ni duplicada.
    try std.testing.expect(dr.audit_entries.len >= dr.completed_count);
}

test "E-32: appendAuditEntry concurrente desde hilos fanout bajo ctx.mutex no tiene carreras" {
    // NOTA (2026-08-15): este test NO prueba el cerrojo de producción — se pone
    // el suyo. Se conserva porque sí cubre que `appendAuditEntry` duplica bien
    // cada campo bajo concurrencia, pero la red de es el test de arriba.
    const allocator = std.testing.allocator;

    var fanout_ctx = Superagent.FanoutContext{
        .mutex = sync.Mutex.init(),
        .completed = 0,
        .failed = 0,
        .integrated = 0,
        .rejected = 0,
        .outputs = std.ArrayList(WorkerOutput).empty,
        .pending = std.ArrayList(ApprovalRequest).empty,
        .saved = std.ArrayList([]const u8).empty,
        .saved_owner = std.ArrayList([]const u8).empty,
        .results = std.ArrayList(Superagent.TaskRunResult).empty,
        .sa = undefined,
        .outcome = undefined,
        .llm_fn = null,
        .llm_ctx = null,
        .catalog_path = null,
        .needed_resources = &.{},
        .audit_entries = std.ArrayList(AuditEntry).empty,
    };
    defer {
        for (fanout_ctx.audit_entries.items) |e| e.deinit(allocator);
        fanout_ctx.audit_entries.deinit(allocator);
    }

    const num_threads = 16;
    const entries_per_thread = 50;

    const ThreadRunner = struct {
        fn worker(ctx: *Superagent.FanoutContext, thread_id: usize, alloc: std.mem.Allocator) void {
            var i: usize = 0;
            while (i < entries_per_thread) : (i += 1) {
                ctx.mutex.lock();
                defer ctx.mutex.unlock();

                const task_num = thread_id * 1000 + i;
                Superagent.appendAuditEntry(alloc, &ctx.audit_entries, null, 1, .{
                    .ts = 123456,
                    .subject_kind = "task",
                    .subject_id = @intCast(task_num),
                    .action = "BUILD",
                    .verdict = "PASS",
                    .model_id = "test-model",
                    .provider = "test-provider",
                    .evidence_ref = "test/path.txt",
                    .notes = "artifact generated concurrently",
                });
            }
        }
    };

    var threads: [num_threads]std.Thread = undefined;
    for (&threads, 0..) |*t, i| {
        t.* = try std.Thread.spawn(.{}, ThreadRunner.worker, .{ &fanout_ctx, i, allocator });
    }

    for (threads) |t| {
        t.join();
    }

    try std.testing.expectEqual(@as(usize, num_threads * entries_per_thread), fanout_ctx.audit_entries.items.len);
    for (fanout_ctx.audit_entries.items) |entry| {
        try std.testing.expectEqualStrings("task", entry.subject_kind);
        try std.testing.expectEqualStrings("BUILD", entry.action);
        try std.testing.expectEqualStrings("PASS", entry.verdict);
        try std.testing.expectEqualStrings("test-model", entry.model_id);
        try std.testing.expectEqualStrings("test-provider", entry.provider);
        try std.testing.expectEqualStrings("test/path.txt", entry.evidence_ref);
        try std.testing.expectEqualStrings("artifact generated concurrently", entry.notes);
    }
}

