    try catalog.exec("INSERT INTO providers(id,name,base_url,api_style,is_free_tier) VALUES (1,'Gemini','x','gemini',1)");
    try catalog.exec("INSERT INTO models(id,provider_id,model_name,context_window,is_free,available) VALUES (1,1,'gemini-paid-x',128000,0,1)");
    try catalog.exec("INSERT INTO models(id,provider_id,model_name,context_window,is_free,available) VALUES (2,1,'gemini-free-x',128000,1,1)");
    var router = model_router.Router.init(allocator, catalog, null, 1);
    var sa = Superagent.init(allocator, runtime, &router, NoopMemory.backend(), 1);
    var ctx = Superagent.FanoutContext{
        .mutex = sync.Mutex.init(),
        .completed = 0,
        .failed = 0,
        .integrated = 0,
        .rejected = 0,
        .outputs = std.ArrayList(WorkerOutput).empty,
        .pending = std.ArrayList(ApprovalRequest).empty,
        .saved = std.ArrayList([]const u8).empty,
        .saved_owner = std.ArrayList([]const u8).empty,
        .results = std.ArrayList(Superagent.TaskRunResult).empty,
        .sa = &sa,
        .outcome = undefined,
        .llm_fn = null,
        .llm_ctx = null,
        .catalog_path = null,
        .needed_resources = &.{},
        .audit_entries = std.ArrayList(AuditEntry).empty,
    };
    defer {
        for (ctx.audit_entries.items) |e| e.deinit(allocator);
        ctx.audit_entries.deinit(allocator);
    }
    const pt = planner.PlannedTask{ .id = "t1", .task_type = .programar, .department = "programacion", .description = "fixture", .contract_fields = &.{}, .depends_on = &.{} };
    var llm = live_worker.LiveLlm{
        .allocator = allocator,
        .lives = &.{},
        .buffer = std.ArrayList(u8).empty,
    };
    try llm.attempts.append(allocator, .{ .provider = "Gemini", .model = "gemini-paid-x", .status = "ok", .key_label = "GEMINI_01" });
    try llm.attempts.append(allocator, .{ .provider = "Gemini", .model = "gemini-free-x", .status = "ok" });
    defer llm.attempts.deinit(allocator);
    emitLlmAttempts(&ctx, pt, &llm);
    try std.testing.expectEqual(@as(usize, 1), ctx.audit_entries.items.len);
    const e = ctx.audit_entries.items[0];
    try std.testing.expectEqualStrings("ESCALATION", e.action);
    try std.testing.expectEqualStrings("model_router", e.subject_kind);
    try std.testing.expectEqualStrings("gemini-paid-x", e.model_id);
    try std.testing.expectEqualStrings("Gemini", e.provider);
    try std.testing.expect(std.mem.indexOf(u8, e.notes, "asignada a pago") != null);
    try std.testing.expect(std.mem.indexOf(u8, e.notes, "GEMINI_01") != null);
}
test "Remate D3: task_provider_ok no lleva motivo de fallo; el fallo lleva el suyo y la cuota diaria" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var catalog = try db.Connection.open(allocator, ":memory:");
    defer catalog.close();
    const migrator = db.Migrator.init(allocator);
    try migrator.migrate(catalog, &db.catalog_schema);
    try catalog.exec("INSERT INTO providers(id,name,base_url,api_style,is_free_tier) VALUES (1,'OpenRouter','x','openai',1)");
    try catalog.exec("INSERT INTO models(id,provider_id,model_name,context_window,is_free,available) VALUES (1,1,'a:free',128000,1,1),(2,1,'b:free',128000,1,1)");
    var router = model_router.Router.init(allocator, catalog, null, 1);
    var sa = Superagent.init(allocator, runtime, &router, NoopMemory.backend(), 1);
    sa.event_conn = runtime;
    sa.event_order_id = 77;
    var ctx = Superagent.FanoutContext{
        .mutex = sync.Mutex.init(),
        .completed = 0,
        .failed = 0,
        .integrated = 0,
        .rejected = 0,
        .outputs = std.ArrayList(WorkerOutput).empty,
        .pending = std.ArrayList(ApprovalRequest).empty,
        .saved = std.ArrayList([]const u8).empty,
        .saved_owner = std.ArrayList([]const u8).empty,
        .results = std.ArrayList(Superagent.TaskRunResult).empty,
        .sa = &sa,
        .outcome = undefined,
        .llm_fn = null,
        .llm_ctx = null,
        .catalog_path = null,
        .needed_resources = &.{},
        .audit_entries = std.ArrayList(AuditEntry).empty,
    };
    defer {
        for (ctx.audit_entries.items) |e| e.deinit(allocator);
        ctx.audit_entries.deinit(allocator);
    }
    const pt = planner.PlannedTask{ .id = "t2", .task_type = .auditar, .department = "auditoria", .description = "fixture", .contract_fields = &.{}, .depends_on = &.{} };
    var llm = live_worker.LiveLlm{ .allocator = allocator, .lives = &.{}, .buffer = std.ArrayList(u8).empty };
    var quota = providers.external_error.Diagnostic{};
    quota.capture(429, "{\"error\":{\"message\":\"Rate limit exceeded: free-models-per-day.\",\"code\":429}}", null);
    try llm.attempts.append(allocator, .{ .provider = "OpenRouter", .model = "a:free", .status = "rate_limited", .diagnostic = quota });
    try llm.attempts.append(allocator, .{ .provider = "OpenRouter", .model = "b:free", .status = "ok" });
    defer llm.attempts.deinit(allocator);
    emitLlmAttempts(&ctx, pt, &llm);
    const q = try runtime.prepare("SELECT kind, payload_json FROM events WHERE order_id = 77 AND kind LIKE 'task_provider_%' ORDER BY id");
    defer runtime.finalize(q);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(q));
    try std.testing.expectEqualStrings("task_provider_failed", std.mem.span(db.c.sqlite3_column_text(q, 0)));
    const failed = std.mem.span(db.c.sqlite3_column_text(q, 1));
    try std.testing.expect(std.mem.indexOf(u8, failed, "\"http_status\":429") != null);
    try std.testing.expect(std.mem.indexOf(u8, failed, "\"rate_daily\":true") != null);
    try std.testing.expect(std.mem.indexOf(u8, failed, "free-models-per-day") != null);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(q));
    try std.testing.expectEqualStrings("task_provider_ok", std.mem.span(db.c.sqlite3_column_text(q, 0)));
    const ok_payload = std.mem.span(db.c.sqlite3_column_text(q, 1));
    try std.testing.expect(std.mem.indexOf(u8, ok_payload, "fallo") == null);
    try std.testing.expect(std.mem.indexOf(u8, ok_payload, "\"reason\"") == null);
    try std.testing.expect(std.mem.indexOf(u8, ok_payload, "\"status\":\"ok\"") != null);
}
