test "D3-RESULT: corrected artifact replaces original final answer" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    const OnePiece = struct {
        fn plan(_: *anyopaque, a: std.mem.Allocator, goal: []const u8, _: []const planner.ClarificationAnswer, _: ?[]const u8) planner.PlannerError!planner.Plan {
            const tasks = try a.alloc(planner.PlannedTask, 1);
            tasks[0] = try D7Planner.tarea(a, "d3-piece", "Implementar d3-result.py", &.{});
            return .{ .allocator = a, .understanding = try a.dupe(u8, goal), .questions = try a.alloc(planner.ClarificationQuestion, 0), .tasks = tasks };
        }
        fn deinit(_: *anyopaque) void {}
    };
    var marker: u8 = 0;
    const backend = planner.PlannerBackend{ .ptr = &marker, .planFn = OnePiece.plan, .deinitFn = OnePiece.deinit };
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    g_exec_call_count = 0;
    sa.executor_spawn_fn = testExecutorSpawnFailThenOk;
    sa.permission_config.mode = .bypass; // Test executor only; no real command is spawned.
    var outcome = try sa.processOrder("d3-fixture", "Implementar una pieza Python", &.{}, backend, null, null);
    defer outcome.deinit();
    var ctx = TestLlmCtxWithCounter{
        .response =
        \\ [{"field":"source","content":"print(1)"},{"field":"filename","content":"d3-result.py"},{"field":"response","content":"D3_RESULTADO_ANTIGUO"}]
        ,
        .correction_response =
        \\ [{"field":"source","content":"print(2)"},{"field":"filename","content":"d3-result.py"},{"field":"response","content":"D3_RESULTADO_CORREGIDO"}]
        ,
    };
    var dr = try sa.approveAndDispatch(&outcome, testLlmFnWithCounter, &ctx, null);
    defer dr.deinit(allocator);
    const path = try std.fmt.allocPrintSentinel(allocator, "devagents-workspace\\orden-{d}\\d3-result.py", .{outcome.order_id}, 0);
    defer allocator.free(path);
    defer _ = DeleteFileA(path.ptr);
    try std.testing.expectEqual(@as(usize, 2), ctx.call_count);
    try std.testing.expectEqual(@as(usize, 2), g_exec_call_count);
    try std.testing.expectEqual(@as(usize, 0), dr.failed_count);
    try std.testing.expect(!dr.order_failed);
    try std.testing.expectEqualStrings("D3_RESULTADO_CORREGIDO", dr.final_answer);
}

test "D3-RECOVERY: contract rejection is corrected and blocked consumer runs once" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    const RecoveryPlanner = struct {
        fn task(a: std.mem.Allocator, id: []const u8, kind: model_router.TaskType, department: []const u8, description: []const u8, fields: []const []const u8, deps: []const []const u8) !planner.PlannedTask {
            const contract_fields = try a.alloc(planner.ContractField, fields.len);
            errdefer a.free(contract_fields);
            for (fields, 0..) |field, i| contract_fields[i] = .{ .name = try a.dupe(u8, field), .field_type = .string, .required = true };
            const depends_on = try a.alloc([]const u8, deps.len);
            errdefer a.free(depends_on);
            for (deps, 0..) |dep, i| depends_on[i] = try a.dupe(u8, dep);
            return .{ .id = try a.dupe(u8, id), .task_type = kind, .department = try a.dupe(u8, department), .description = try a.dupe(u8, description), .contract_fields = contract_fields, .depends_on = depends_on };
        }
        fn plan(_: *anyopaque, a: std.mem.Allocator, goal: []const u8, _: []const planner.ClarificationAnswer, _: ?[]const u8) planner.PlannerError!planner.Plan {
            // El arreglo está deliberadamente invertido C -> B -> A. Solo
            // resolveWaves puede recuperar ambos consumidores en una pasada.
            const tasks = try a.alloc(planner.PlannedTask, 3);
            tasks[0] = try task(a, "consumer-c", .auditar, "auditoria", "AUDITOR_C verifica el informe de B", &.{"verdict"}, &.{"consumer-b"});
            tasks[1] = try task(a, "consumer-b", .auditar, "auditoria", "AUDITOR_B verifica recovery.py", &.{"verdict"}, &.{"producer-a"});
            tasks[2] = try task(a, "producer-a", .programar, "programacion", "PRODUCTOR_A crea recovery.py", &.{ "source", "marker" }, &.{});
            return .{ .allocator = a, .understanding = try a.dupe(u8, goal), .questions = try a.alloc(planner.ClarificationQuestion, 0), .tasks = tasks };
        }
        fn deinit(_: *anyopaque) void {}
    };
    const RecoveryLlm = struct {
        calls: usize = 0,
        fn call(ctx: *anyopaque, _: []const u8, _: []const u8) []const u8 {
            const self: *@This() = @ptrCast(@alignCast(ctx));
            self.calls += 1;
            return switch (self.calls) {
                // Producer misses its non-primary mandatory contract field.
                1 => "[{\"field\":\"source\",\"content\":\"print(1)\"},{\"field\":\"filename\",\"content\":\"recovery.py\"}]",
                // D3 correction repairs the same producer.
                2 => "[{\"field\":\"source\",\"content\":\"print(2)\"},{\"field\":\"filename\",\"content\":\"recovery.py\"},{\"field\":\"marker\",\"content\":\"fixed\"}]",
                // B y C solo se llaman tras recuperar la cadena topológica.
                3, 4 => "[{\"field\":\"verdict\",\"content\":\"PASS\"}]",
                else => unreachable,
            };
        }
    };
    var marker: u8 = 0;
    const backend = planner.PlannerBackend{ .ptr = &marker, .planFn = RecoveryPlanner.plan, .deinitFn = RecoveryPlanner.deinit };
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    // No process is spawned: this deterministic fixture reports execution success.
    g_exec_call_count = 1;
    sa.executor_spawn_fn = testExecutorSpawnFailThenOk;
    sa.permission_config.mode = .bypass;
    var outcome = try sa.processOrder("d3-recovery", "corrige productor y verifica consumidor", &.{}, backend, null, null);
    defer outcome.deinit();
    var llm = RecoveryLlm{};
    var dr = try sa.approveAndDispatch(&outcome, RecoveryLlm.call, &llm, null);
    defer dr.deinit(allocator);
    const path = try std.fmt.allocPrintSentinel(allocator, "devagents-workspace\\orden-{d}\\recovery.py", .{outcome.order_id}, 0);
    defer allocator.free(path);
    defer _ = DeleteFileA(path.ptr);
    try std.testing.expectEqual(@as(usize, 4), llm.calls);
    try std.testing.expectEqual(@as(usize, 0), dr.failed_count);
    try std.testing.expect(!dr.order_failed);
    try std.testing.expectEqual(@as(usize, 3), dr.completed_count);
}

test "D3-RECOVERY: no corrige rechazos sin artefacto ni fallos de entorno" {
    const no_artifact = Superagent.TaskRunResult{
        .task_id = "t1",
