test "CK-MOT-011: worker_failed sin artefacto es reintentable; el fallo de entorno no" {
    const provider_failure = Superagent.TaskRunResult{
        .task_id = "t1",
        .artifacts = &.{},
        .success = false,
        .error_msg = "OpenRouter/foo: InvalidArtifact; sin respuesta HTTP; respuesta vacia o sin artefactos validos",
        .integrated = false,
        .model_used = "foo",
        .exec = .{ .ran = false, .exit_code = 0, .needs_approval = false, .stderr = "" },
        .saved_path = null,
    };
    const dependency_blocked = Superagent.TaskRunResult{
        .task_id = "t2",
        .artifacts = &.{},
        .success = false,
        .error_msg = "dependency failed or missing",
        .integrated = false,
        .model_used = "not-run",
        .exec = .{ .ran = false, .exit_code = 0, .needs_approval = false, .stderr = "" },
        .saved_path = null,
    };
    const budget_blocked = Superagent.TaskRunResult{
        .task_id = "t3",
        .artifacts = &.{},
        .success = false,
        .error_msg = "paid_budget_exhausted",
        .integrated = false,
        .paid_budget_exhausted = true,
        .model_used = "foo",
        .exec = .{ .ran = false, .exit_code = 0, .needs_approval = false, .stderr = "" },
        .saved_path = null,
    };
    // r2 (P1): los fallos que NO son del artefacto no se reintentan.
    // Transporte/red (LlmCallFailed + «sin respuesta HTTP» + timeout), genérico
    // sin causa de artefacto y agotamiento de proveedor.
    const transport_failure = Superagent.TaskRunResult{
        .task_id = "t4",
        .artifacts = &.{},
        .success = false,
        .error_msg = "OpenRouter/foo: LlmCallFailed; sin respuesta HTTP; timeout: el proveedor no respondio dentro del plazo",
        .integrated = false,
        .model_used = "foo",
        .exec = .{ .ran = false, .exit_code = 0, .needs_approval = false, .stderr = "" },
        .saved_path = null,
    };
    const generic_worker_failed = Superagent.TaskRunResult{
        .task_id = "t5",
        .artifacts = &.{},
        .success = false,
        .error_msg = "native worker failed: SpawnFailed",
        .integrated = false,
        .model_used = "foo",
        .exec = .{ .ran = false, .exit_code = 0, .needs_approval = false, .stderr = "" },
        .saved_path = null,
    };
    const provider_exhausted = Superagent.TaskRunResult{
        .task_id = "t6",
        .artifacts = &.{},
        .success = false,
        .error_msg = "provider_exhausted: todos los proveedores agotados",
        .integrated = false,
        .model_used = "foo",
        .exec = .{ .ran = false, .exit_code = 0, .needs_approval = false, .stderr = "" },
        .saved_path = null,
    };
    const json_parse = Superagent.TaskRunResult{
        .task_id = "t7",
        .artifacts = &.{},
        .success = false,
        .error_msg = "native worker failed: JsonParseError",
        .integrated = false,
        .model_used = "foo",
        .exec = .{ .ran = false, .exit_code = 0, .needs_approval = false, .stderr = "" },
        .saved_path = null,
    };
    try std.testing.expect(Superagent.isRepairableWorkerFailure(provider_failure));
    try std.testing.expect(Superagent.isRepairableWorkerFailure(json_parse));
    try std.testing.expect(!Superagent.isRepairableWorkerFailure(dependency_blocked));
    try std.testing.expect(!Superagent.isRepairableWorkerFailure(budget_blocked));
    try std.testing.expect(!Superagent.isRepairableWorkerFailure(transport_failure));
    try std.testing.expect(!Superagent.isRepairableWorkerFailure(generic_worker_failed));
    try std.testing.expect(!Superagent.isRepairableWorkerFailure(provider_exhausted));
    // Política de gasto: gratis siempre; de pago solo con pin manual.
    try std.testing.expect(Superagent.workerRetryAllowed(true, false));
    try std.testing.expect(!Superagent.workerRetryAllowed(false, false));
    try std.testing.expect(Superagent.workerRetryAllowed(false, true));
}

test "CK-MOT-011: un worker_failed se reintenta con otro candidato y no condena la orden" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();

    const CkPlanner = struct {
        fn plan(_: *anyopaque, a: std.mem.Allocator, goal: []const u8, _: []const planner.ClarificationAnswer, _: ?[]const u8) planner.PlannerError!planner.Plan {
            const tasks = try a.alloc(planner.PlannedTask, 1);
            tasks[0] = try D7Planner.tarea(a, "t1", "PIEZA_A sin extension", &.{});
            return .{ .allocator = a, .understanding = try a.dupe(u8, goal), .questions = try a.alloc(planner.ClarificationQuestion, 0), .tasks = tasks };
        }
        fn deinit(_: *anyopaque) void {}
    };
    var marker: u8 = 0;
    const backend = planner.PlannerBackend{ .ptr = &marker, .planFn = CkPlanner.plan, .deinitFn = CkPlanner.deinit };
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    // No se lanza ningún proceso real: el ejecutor determinista reporta éxito.
    g_exec_call_count = 1;
    sa.executor_spawn_fn = testExecutorSpawnFailThenOk;
    sa.permission_config.mode = .bypass;
    // r4 (control positivo): token presente pero NUNCA cancelado.
    // El mismo guard de cancelación deja pasar el reintento y este se
    // persiste: contraparte exacta del cero de la prueba de cancelación.
    const retry_token = try live_worker.CancellationToken.create(allocator);
    defer retry_token.release();
    sa.cancel_token = retry_token;
    var outcome = try sa.processOrder("ck-mot-011", "implementa una pieza con una sola salida", &.{}, backend, null, null);
    defer outcome.deinit();
    sa.setEventConn(runtime, outcome.order_id);

    // Cadena del plan: el primer candidato devuelve basura y el respaldo (otro
    // candidato, nunca el mismo) resuelve el reintento. Sin catálogo vivo la
    // política de gasto no aplica: no hay proveedor al que cobrar.
    var chain_fallbacks = try allocator.alloc(ModelChoice, 1);
    chain_fallbacks[0] = .{ .provider_name = try allocator.dupe(u8, "Local"), .model_name = try allocator.dupe(u8, "CandidatoDos"), .is_free = true };
    try ckMot011SetAssignment(allocator, &outcome, "Local", "CandidatoUno", true, chain_fallbacks);

    var llm = TestLlmCtxWithCounter{
        // Primera respuesta del candidato: basura ilegible → InvalidArtifact →
        // el worker termina sin artefacto (worker_failed).
        .response = "respuesta invalida del modelo: ni JSON ni codigo",
        // Reintento acotado (replan): un artefacto real que sí cumple el contrato.
        // El contenido supera el umbral de "campo string primario" del validador.
        .correction_response = "[{\"field\":\"source\",\"content\":\"MARCA = 1;\\nCK_MOT_011_OK = true;\"},{\"field\":\"filename\",\"content\":\"ck_mot_011.js\"}]",
    };
    var dr = try sa.approveAndDispatch(&outcome, testLlmFnWithCounter, &llm, null);
    defer dr.deinit(allocator);
    const path = try std.fmt.allocPrintSentinel(allocator, "devagents-workspace\\orden-{d}\\ck_mot_011.js", .{outcome.order_id}, 0);
    defer allocator.free(path);
    defer _ = DeleteFileA(path.ptr);

    // Un candidato que devuelve basura no puede condenar la orden: hubo un
    // reintento acotado que el segundo intento resolvió.
    try std.testing.expectEqual(@as(usize, 2), llm.call_count);
    try std.testing.expectEqual(@as(usize, 1), dr.completed_count);
    try std.testing.expectEqual(@as(usize, 0), dr.failed_count);
    try std.testing.expect(!dr.order_failed);

    // Control positivo (r4): con la cadena y el token SIN cancelar, la orden
    // persiste exactamente 1 `task_retry` — el flujo que la prueba de
    // cancelación congela reintentaría de verdad.
    const retry_stmt = try runtime.prepare("SELECT COUNT(*) FROM events WHERE order_id = ? AND kind = 'task_retry'");
    defer runtime.finalize(retry_stmt);
    try db.bindInt(retry_stmt, 1, outcome.order_id);
    try std.testing.expect(db.c.sqlite3_step(retry_stmt) == db.c.SQLITE_ROW);
    try std.testing.expectEqual(@as(c_int, 1), db.c.sqlite3_column_int(retry_stmt, 0));
}

test "CK-MOT-011 r2: una orden cancelada tras el fallo de artefacto no reintenta" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();

    const CkPlanner = struct {
        fn plan(_: *anyopaque, a: std.mem.Allocator, goal: []const u8, _: []const planner.ClarificationAnswer, _: ?[]const u8) planner.PlannerError!planner.Plan {
            const tasks = try a.alloc(planner.PlannedTask, 1);
            tasks[0] = try D7Planner.tarea(a, "t1", "PIEZA_A sin extension", &.{});
            return .{ .allocator = a, .understanding = try a.dupe(u8, goal), .questions = try a.alloc(planner.ClarificationQuestion, 0), .tasks = tasks };
        }
        fn deinit(_: *anyopaque) void {}
    };
    var marker: u8 = 0;
    const backend = planner.PlannerBackend{ .ptr = &marker, .planFn = CkPlanner.plan, .deinitFn = CkPlanner.deinit };
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    g_exec_call_count = 1;
    sa.executor_spawn_fn = testExecutorSpawnFailThenOk;
    sa.permission_config.mode = .bypass;

    const token = try live_worker.CancellationToken.create(allocator);
    defer token.release();
    sa.cancel_token = token;

    var outcome = try sa.processOrder("ck-mot-011-cancel", "implementa una pieza con una sola salida", &.{}, backend, null, null);
    defer outcome.deinit();
    // r3 (P2): sin conexión de eventos el recuento de `task_retry`
    // era vacuo (nada se persistía nunca). Con `setEventConn` el cero mide de
    // verdad que la cancelación impidió el reintento.
    sa.setEventConn(runtime, outcome.order_id);
    // r4 (P2): MISMA cadena de fixture que la prueba E2E «un
    // worker_failed se reintenta con otro candidato…». Sin la comprobación de
    // cancelación SÍ habría candidato que despachar y el flujo emitiría
    // `task_retry` (lo demuestra el rojo con el guard desactivado): el cero de
    // abajo deja de ser vacuo.
    var chain_fallbacks = try allocator.alloc(ModelChoice, 1);
    chain_fallbacks[0] = .{ .provider_name = try allocator.dupe(u8, "Local"), .model_name = try allocator.dupe(u8, "CandidatoDos"), .is_free = true };
    try ckMot011SetAssignment(allocator, &outcome, "Local", "CandidatoUno", true, chain_fallbacks);

    var llm = TestLlmCancelOnFirstCtx{
        .response = "respuesta invalida del modelo: ni JSON ni codigo",
        .token = token,
    };
    var dr = try sa.approveAndDispatch(&outcome, testLlmFnCancelOnFirst, &llm, null);
    defer dr.deinit(allocator);

    // Control positivo: la conexión de eventos está viva por la MISMA vía que
    // usa la producción (`recordEvent`). Otros escritores (commitTerminal)
    // persisten con `runtime` aunque falte `setEventConn`, así que contar
    // «cualquier evento» no acredita la conexión: este evento de prueba SÍ
    // desaparece si se retira `setEventConn`, y deja el cero de `task_retry`
    // con respaldo real.
    sa.recordEvent("cancel_probe", "{}");
    const probe_stmt = try runtime.prepare("SELECT COUNT(*) FROM events WHERE order_id = ? AND kind = 'cancel_probe'");
    defer runtime.finalize(probe_stmt);
    try db.bindInt(probe_stmt, 1, outcome.order_id);
    try std.testing.expect(db.c.sqlite3_step(probe_stmt) == db.c.SQLITE_ROW);
    try std.testing.expectEqual(@as(c_int, 1), db.c.sqlite3_column_int(probe_stmt, 0));

    // Y no debe existir evento task_retry para una orden cancelada. (r4: se
    // mide ANTES de las llamadas para que el rojo con el guard desactivado
    // señale directamente el `task_retry` que no debe existir.)
    const stmt = try runtime.prepare("SELECT COUNT(*) FROM events WHERE order_id = ? AND kind = 'task_retry'");
    defer runtime.finalize(stmt);
    try db.bindInt(stmt, 1, outcome.order_id);
    try std.testing.expect(db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW);
    try std.testing.expectEqual(@as(c_int, 0), db.c.sqlite3_column_int(stmt, 0));

    // El primer intento corrió y falló por artefacto; como la orden ya está
    // cancelada, NO se arranca la corrección: un solo llamado al modelo.
    try std.testing.expectEqual(@as(usize, 1), llm.call_count);
    try std.testing.expect(dr.order_cancelled);
    try std.testing.expect(!dr.order_failed);
}

test "CK-MOT-011: la corrección usa el respaldo del router y nunca el modelo que falló" {
    const a = std.testing.allocator;
    var runtime = try openRuntime(a);
    defer runtime.close();
    var sa = Superagent.init(a, runtime, null, NoopMemory.backend(), 1);

    var fallbacks = [_]ModelChoice{
        .{ .provider_name = "P1", .model_name = "FailedFallback", .is_free = true },
        .{ .provider_name = "P2", .model_name = "HealthyFallback", .is_free = true },
    };
    const assignments = [_]ModelAssignment{
        .{ .task_id = "build", .assigned = true, .provider_name = "P0", .model_name = "PrimaryThatFailed", .is_free = true, .reason = "fixture", .fallbacks = &fallbacks },
    };
    // El primario falló: el siguiente candidato apto es el primer respaldo del router.
    const next = sa.correctionChoice(&assignments, "build", "PrimaryThatFailed", &.{}) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("P1", next.provider_name);
    try std.testing.expectEqualStrings("FailedFallback", next.model_name);
    try std.testing.expect(next.is_free);

    // Si el respaldo que falló es el primero, se salta: no se repite el mismo modelo.
    const second = sa.correctionChoice(&assignments, "build", "FailedFallback", &.{}) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("P2", second.provider_name);
    try std.testing.expectEqualStrings("HealthyFallback", second.model_name);

    // r2 (P1): cadena P0 -> P1 -> P2. El despacho original probó hasta
    // P1 inclusive; la corrección NO repite P1 y salta al primer candidato NO
    // probado de la cadena.
    var chain_fallbacks = [_]ModelChoice{
        .{ .provider_name = "P1", .model_name = "FallbackOne", .is_free = true },
        .{ .provider_name = "P2", .model_name = "FallbackTwo", .is_free = false },
        .{ .provider_name = "P3", .model_name = "FallbackThree", .is_free = true },
    };
    const chain = [_]ModelAssignment{
        .{ .task_id = "build", .assigned = true, .provider_name = "P0", .model_name = "Primary", .is_free = true, .reason = "fixture", .fallbacks = &chain_fallbacks },
    };
    const after_p1 = sa.correctionChoice(&chain, "build", "FallbackOne", &.{}) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("P2", after_p1.provider_name);
    try std.testing.expectEqualStrings("FallbackTwo", after_p1.model_name);
    // El flag de gasto viaja en la elección para que el llamador aplique la política.
    try std.testing.expect(!after_p1.is_free);
    // r3 (P1): con TODA la cadena probada no hay candidato: la
    // selección devuelve «sin candidato» y NUNCA repite el modelo que falló ni
    // inventa un proveedor de reserva.
    const exhausted_tried = [_]Superagent.CorrectionAttempt{
        .{ .task_id = "build", .model_name = "FallbackOne" },
        .{ .task_id = "build", .model_name = "FallbackTwo" },
        .{ .task_id = "build", .model_name = "FallbackThree" },
    };
    try std.testing.expect(sa.correctionChoice(&chain, "build", "FallbackThree", &exhausted_tried) == null);
    // El pin manual no rota aunque coincida con el modelo que falló.
    sa.forced_provider = "Pinned";
    sa.forced_model = "PinnedModel";
    const pinned = sa.correctionChoice(&chain, "build", "PinnedModel", &.{}) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("Pinned", pinned.provider_name);
    try std.testing.expectEqualStrings("PinnedModel", pinned.model_name);
    sa.forced_provider = null;
    sa.forced_model = null;
}

test "CK-MOT-011: dos ciclos de corrección fallidos usan dos modelos distintos" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();

    const CkPlanner = struct {
        fn plan(_: *anyopaque, a: std.mem.Allocator, goal: []const u8, _: []const planner.ClarificationAnswer, _: ?[]const u8) planner.PlannerError!planner.Plan {
            const tasks = try a.alloc(planner.PlannedTask, 1);
            tasks[0] = try D7Planner.tarea(a, "t1", "PIEZA_A sin extension", &.{});
            return .{ .allocator = a, .understanding = try a.dupe(u8, goal), .questions = try a.alloc(planner.ClarificationQuestion, 0), .tasks = tasks };
        }
        fn deinit(_: *anyopaque) void {}
    };
    var marker: u8 = 0;
    const backend = planner.PlannerBackend{ .ptr = &marker, .planFn = CkPlanner.plan, .deinitFn = CkPlanner.deinit };
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    var outcome = try sa.processOrder("ck-mot-011-ciclos", "implementa una pieza con una sola salida", &.{}, backend, null, null);
    defer outcome.deinit();
    sa.setEventConn(runtime, outcome.order_id);
    try std.testing.expectEqual(@as(usize, 1), outcome.assignments.len);

    // Cadena del router P0 -> FallbackOne -> FallbackTwo, los tres gratis: el
    // lazo de corrección debe recorrerla candidato a candidato. Se reemplaza la
    // asignación (sin router queda `unassigned`) por una cadena real de fixture.
    {
        const prev = outcome.assignments[0];
        allocator.free(prev.provider_name);
        allocator.free(prev.model_name);
        allocator.free(prev.reason);
        allocator.free(prev.fallbacks);
        allocator.free(outcome.assignments);
        var fallbacks = try allocator.alloc(ModelChoice, 2);
        fallbacks[0] = .{ .provider_name = try allocator.dupe(u8, "P1"), .model_name = try allocator.dupe(u8, "FallbackOne"), .is_free = true };
        fallbacks[1] = .{ .provider_name = try allocator.dupe(u8, "P2"), .model_name = try allocator.dupe(u8, "FallbackTwo"), .is_free = true };
        const fresh = try allocator.alloc(ModelAssignment, 1);
        fresh[0] = .{
            .task_id = prev.task_id, // prestado del plan: sigue vivo
            .assigned = true,
            .provider_name = try allocator.dupe(u8, "P0"),
            .model_name = try allocator.dupe(u8, "Primary"),
            .is_free = true,
            .reason = try allocator.dupe(u8, "fixture"),
            .fallbacks = fallbacks,
        };
        outcome.assignments = fresh;
    }

    // TODAS las llamadas devuelven basura: el intento original y las DOS
    // correcciones (MAX_AUDIT_CYCLES=2) mueren sin artefacto. Cada corrección
    // fallida deja `res.model_used` intacto, que es justo el escenario del P1.
    var llm = TestLlmCtxWithCounter{
        .response = "respuesta invalida del modelo: ni JSON ni codigo",
        .correction_response = "respuesta invalida del modelo: ni JSON ni codigo",
    };
    var dr = try sa.approveAndDispatch(&outcome, testLlmFnWithCounter, &llm, null);
    defer dr.deinit(allocator);

    // Una llamada original + dos correcciones: el lazo no se rinde tras el primer fallo.
    try std.testing.expectEqual(@as(usize, 3), llm.call_count);
    try std.testing.expectEqual(@as(usize, 0), dr.completed_count);
    try std.testing.expectEqual(@as(usize, 1), dr.failed_count);

    // Los dos eventos task_retry deben nombrar modelos DISTINTOS: un ciclo que
    // repite candidato no es un reintento (defecto P1 de la auditoría).
    const count_stmt = try runtime.prepare("SELECT COUNT(*) FROM events WHERE order_id = ? AND kind = 'task_retry'");
    defer runtime.finalize(count_stmt);
    try db.bindInt(count_stmt, 1, outcome.order_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(count_stmt));
    try std.testing.expectEqual(@as(c_int, 2), db.c.sqlite3_column_int(count_stmt, 0));

    var payloads: [2][]u8 = undefined;
    for (0..2) |i| {
        const q = try std.fmt.allocPrint(allocator, "SELECT payload_json FROM events WHERE order_id = ? AND kind = 'task_retry' ORDER BY id LIMIT 1 OFFSET {d}", .{i});
        defer allocator.free(q);
        const st = try runtime.prepare(q);
        defer runtime.finalize(st);
        try db.bindInt(st, 1, outcome.order_id);
        try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(st));
        const ptr = db.c.sqlite3_column_text(st, 0);
        try std.testing.expect(ptr != null);
        payloads[i] = try allocator.dupe(u8, std.mem.span(ptr));
    }
    defer {
        for (payloads) |p| allocator.free(p);
    }
    try std.testing.expect(std.mem.indexOf(u8, payloads[0], "\"retry_model\":\"FallbackOne\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, payloads[1], "\"retry_model\":\"FallbackTwo\"") != null);
}

/// r3: reemplaza la asignación del plan (sin router queda
/// `unassigned`) por una cadena de fixture para los tests del ciclo de
/// corrección. La tarea del plan sobrevive (el `task_id` es prestado).
fn ckMot011SetAssignment(allocator: std.mem.Allocator, outcome: *OrderOutcome, provider: []const u8, model: []const u8, is_free: bool, fallbacks: []ModelChoice) !void {
    const prev = outcome.assignments[0];
    allocator.free(prev.provider_name);
    allocator.free(prev.model_name);
    allocator.free(prev.reason);
    allocator.free(prev.fallbacks);
    allocator.free(outcome.assignments);
    const fresh = try allocator.alloc(ModelAssignment, 1);
    fresh[0] = .{
        .task_id = prev.task_id,
        .assigned = true,
        .provider_name = try allocator.dupe(u8, provider),
        .model_name = try allocator.dupe(u8, model),
        .is_free = is_free,
        .reason = try allocator.dupe(u8, "fixture"),
        .fallbacks = fallbacks,
    };
    outcome.assignments = fresh;
}

test "CK-MOT-011 r3: cadena agotada no re-despacha el mismo modelo y falla con motivo" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();

    const CkPlanner = struct {
        fn plan(_: *anyopaque, a: std.mem.Allocator, goal: []const u8, _: []const planner.ClarificationAnswer, _: ?[]const u8) planner.PlannerError!planner.Plan {
            const tasks = try a.alloc(planner.PlannedTask, 1);
            tasks[0] = try D7Planner.tarea(a, "t1", "PIEZA_A sin extension", &.{});
            return .{ .allocator = a, .understanding = try a.dupe(u8, goal), .questions = try a.alloc(planner.ClarificationQuestion, 0), .tasks = tasks };
        }
        fn deinit(_: *anyopaque) void {}
    };
    var marker: u8 = 0;
    const backend = planner.PlannerBackend{ .ptr = &marker, .planFn = CkPlanner.plan, .deinitFn = CkPlanner.deinit };
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    var outcome = try sa.processOrder("ck-mot-011-agotada", "implementa una pieza con una sola salida", &.{}, backend, null, null);
    defer outcome.deinit();
    sa.setEventConn(runtime, outcome.order_id);
    try std.testing.expectEqual(@as(usize, 1), outcome.assignments.len);

    // Cadena de UN solo candidato: sin router no hay respaldos. El despacho
    // original lo prueba y falla sin artefacto; ya no queda ninguno sin probar.
    try ckMot011SetAssignment(allocator, &outcome, "P0", "Unico", true, try allocator.alloc(ModelChoice, 0));

    var llm = TestLlmCtxWithCounter{
        .response = "respuesta invalida del modelo: ni JSON ni codigo",
        .correction_response = "respuesta invalida del modelo: ni JSON ni codigo",
    };
    var dr = try sa.approveAndDispatch(&outcome, testLlmFnWithCounter, &llm, null);
    defer dr.deinit(allocator);

    // UN solo despacho: la cadena agotada no re-despacha al mismo modelo.
    try std.testing.expectEqual(@as(usize, 1), llm.call_count);
    try std.testing.expectEqual(@as(usize, 0), dr.completed_count);
    try std.testing.expectEqual(@as(usize, 1), dr.failed_count);
    try std.testing.expect(dr.order_failed);

    const count_stmt = try runtime.prepare("SELECT COUNT(*) FROM events WHERE order_id = ? AND kind = 'task_retry'");
    defer runtime.finalize(count_stmt);
    try db.bindInt(count_stmt, 1, outcome.order_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(count_stmt));
    try std.testing.expectEqual(@as(c_int, 0), db.c.sqlite3_column_int(count_stmt, 0));

    // El motivo honesto viaja en el terminal de la orden.
    const fail_stmt = try runtime.prepare("SELECT payload_json FROM events WHERE order_id = ? AND kind = 'order_failed'");
    defer runtime.finalize(fail_stmt);
    try db.bindInt(fail_stmt, 1, outcome.order_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(fail_stmt));
    const fail_ptr = db.c.sqlite3_column_text(fail_stmt, 0);
    try std.testing.expect(fail_ptr != null);
    const fail_payload = std.mem.span(fail_ptr);
    try std.testing.expect(std.mem.indexOf(u8, fail_payload, "cadena de modelos agotada") != null);
}

test "CK-MOT-011 r3: con catálogo real el candidato de pago se bloquea y el gratis se despacha" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();

    // Catálogo REAL en disco (nunca `:memory:`): es lo que activa la rama de
    // política de gasto del reintento (superagent.zig:4330-4336). Sin clave
    // utilizable, el despacho de la corrección cae al callback inyectado: la
    // prueba no sale a la red.
    var threaded = std.Io.Threaded.init(allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const dir_path = try tmp.dir.realPathFileAlloc(io, ".", allocator);
    defer allocator.free(dir_path);
    const cat_path = try std.fs.path.join(allocator, &.{ dir_path, "catalog.db" });
    defer allocator.free(cat_path);
    {
        var catalog = try db.Connection.open(allocator, cat_path);
        defer catalog.close();
        try db.Migrator.init(allocator).migrate(catalog, &db.catalog_schema);
        try catalog.exec("INSERT INTO providers (id,name,base_url,api_style,is_free_tier) VALUES (1,'OpenRouter','http://127.0.0.1:9','openai',1)");
        try catalog.exec("INSERT INTO models (id,provider_id,model_name,context_window,is_free,latency_p50_ms,available) VALUES (1,1,'free-fixture',128000,1,800,1)");
        try catalog.exec("INSERT INTO models (id,provider_id,model_name,context_window,is_free,latency_p50_ms,available) VALUES (2,1,'paid-fixture',128000,0,900,1)");
    }

    const CkPlanner = struct {
        fn plan(_: *anyopaque, a: std.mem.Allocator, goal: []const u8, _: []const planner.ClarificationAnswer, _: ?[]const u8) planner.PlannerError!planner.Plan {
            const tasks = try a.alloc(planner.PlannedTask, 1);
            tasks[0] = try D7Planner.tarea(a, "t1", "PIEZA_A sin extension", &.{});
            return .{ .allocator = a, .understanding = try a.dupe(u8, goal), .questions = try a.alloc(planner.ClarificationQuestion, 0), .tasks = tasks };
        }
        fn deinit(_: *anyopaque) void {}
    };
    var marker: u8 = 0;
    const backend = planner.PlannerBackend{ .ptr = &marker, .planFn = CkPlanner.plan, .deinitFn = CkPlanner.deinit };

    // Escenario 1 — candidato de pago: el original falla y el respaldo de pago
    // NO se despacha sin pin manual (live_catalog aplica la política).
    {
        var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
        var outcome = try sa.processOrder("ck-mot-011-pago", "implementa una pieza con una sola salida", &.{}, backend, null, null);
        defer outcome.deinit();
        sa.setEventConn(runtime, outcome.order_id);
        var paid_fallbacks = try allocator.alloc(ModelChoice, 1);
        paid_fallbacks[0] = .{ .provider_name = try allocator.dupe(u8, "OpenRouter"), .model_name = try allocator.dupe(u8, "paid-fixture"), .is_free = false };
        try ckMot011SetAssignment(allocator, &outcome, "OpenRouter", "free-fixture", true, paid_fallbacks);

        var llm = TestLlmCtxWithCounter{
            .response = "respuesta invalida del modelo: ni JSON ni codigo",
            .correction_response = "[{\"field\":\"source\",\"content\":\"MARCA = 1;\\nCK_MOT_011_OK = true;\"},{\"field\":\"filename\",\"content\":\"ck_mot_011.js\"}]",
        };
        var dr = try sa.approveAndDispatch(&outcome, testLlmFnWithCounter, &llm, cat_path);
        defer dr.deinit(allocator);

        try std.testing.expectEqual(@as(usize, 1), llm.call_count);
        try std.testing.expectEqual(@as(usize, 0), dr.completed_count);
        try std.testing.expectEqual(@as(usize, 1), dr.failed_count);

        const retry_stmt = try runtime.prepare("SELECT COUNT(*) FROM events WHERE order_id = ? AND kind = 'task_retry'");
        defer runtime.finalize(retry_stmt);
        try db.bindInt(retry_stmt, 1, outcome.order_id);
        try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(retry_stmt));
        try std.testing.expectEqual(@as(c_int, 0), db.c.sqlite3_column_int(retry_stmt, 0));
    }

    // Escenario 2 — candidato gratis: el respaldo gratuito SÍ se despacha y la
    // corrección cierra la tarea.
    {
        var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
        g_exec_call_count = 1;
        sa.executor_spawn_fn = testExecutorSpawnFailThenOk;
        sa.permission_config.mode = .bypass;
        var outcome = try sa.processOrder("ck-mot-011-gratis", "implementa una pieza con una sola salida", &.{}, backend, null, null);
        defer outcome.deinit();
        sa.setEventConn(runtime, outcome.order_id);
        var free_fallbacks = try allocator.alloc(ModelChoice, 1);
        free_fallbacks[0] = .{ .provider_name = try allocator.dupe(u8, "OpenRouter"), .model_name = try allocator.dupe(u8, "free-fixture"), .is_free = true };
        try ckMot011SetAssignment(allocator, &outcome, "OpenRouter", "free-fixture-failed", true, free_fallbacks);

        var llm = TestLlmCtxWithCounter{
            .response = "respuesta invalida del modelo: ni JSON ni codigo",
            .correction_response = "[{\"field\":\"source\",\"content\":\"MARCA = 1;\\nCK_MOT_011_OK = true;\"},{\"field\":\"filename\",\"content\":\"ck_mot_011.js\"}]",
        };
        var dr = try sa.approveAndDispatch(&outcome, testLlmFnWithCounter, &llm, cat_path);
        defer dr.deinit(allocator);
        const path = try std.fmt.allocPrintSentinel(allocator, "devagents-workspace\\orden-{d}\\ck_mot_011.js", .{outcome.order_id}, 0);
        defer allocator.free(path);
        defer _ = DeleteFileA(path.ptr);

        // El original falló y el reintento gratuito SÍ se despachó: dos llamadas.
        try std.testing.expectEqual(@as(usize, 2), llm.call_count);
        try std.testing.expectEqual(@as(usize, 1), dr.completed_count);
        try std.testing.expectEqual(@as(usize, 0), dr.failed_count);
        try std.testing.expect(!dr.order_failed);

        const retry_stmt = try runtime.prepare("SELECT payload_json FROM events WHERE order_id = ? AND kind = 'task_retry'");
        defer runtime.finalize(retry_stmt);
        try db.bindInt(retry_stmt, 1, outcome.order_id);
        try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(retry_stmt));
        const retry_ptr = db.c.sqlite3_column_text(retry_stmt, 0);
        try std.testing.expect(retry_ptr != null);
        const retry_payload = std.mem.span(retry_ptr);
        try std.testing.expect(std.mem.indexOf(u8, retry_payload, "\"retry_model\":\"free-fixture\"") != null);
    }
}

var qa_v1_assertion_runs: usize = 0;

/// Simula la decision de la cabina sobre ESTE argv exacto (solo pruebas).
fn testHumanApprovesInline(_: ?*anyopaque, exe: []const u8, args: []const []const u8, _: []const u8) anyerror!bool {
    return std.mem.eql(u8, exe, "python") and args.len >= 2 and std.mem.eql(u8, args[0], "-c");
}

fn qaV1Spawn(a: std.mem.Allocator, _: []const u8, args: []const []const u8, _: []const u8, _: u32, _: usize, _: ?executor.StreamSink, _: ?*anyopaque, _: []const u8) executor.ExecutorError!executor.RunResult {
    // The producer itself is runnable; only its requirement-bound test command
    // detects that add(2,3) would yield 3.
    if (args.len >= 2 and std.mem.eql(u8, args[0], "-c")) {
        qa_v1_assertion_runs += 1;
        if (qa_v1_assertion_runs == 1) {
            return .{ .exit_code = 1, .stdout = try a.dupe(u8, ""), .stderr = try a.dupe(u8, "AssertionError: add(2,3) returned 3") };
        }
        return .{ .exit_code = 0, .stdout = try a.dupe(u8, "2+3=5"), .stderr = try a.dupe(u8, "") };
    }
    return .{ .exit_code = 0, .stdout = try a.dupe(u8, "producer ran"), .stderr = try a.dupe(u8, "") };
}

test "QA-V1: calculator self-declared PASS cannot close without executable evidence" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();

    const QaPlanner = struct {
        const Field = struct { name: []const u8, value: ?[]const u8 = null, required: bool = false };

        fn task(a: std.mem.Allocator, id: []const u8, kind: model_router.TaskType, department: []const u8, description: []const u8, fields: []const Field, deps: []const []const u8) !planner.PlannedTask {
            const contract_fields = try a.alloc(planner.ContractField, fields.len);
            errdefer a.free(contract_fields);
            for (fields, 0..) |field, i| contract_fields[i] = .{
                .name = try a.dupe(u8, field.name),
                .field_type = .string,
                .required = field.required,
                .value = if (field.value) |value| try a.dupe(u8, value) else null,
            };
            const depends_on = try a.alloc([]const u8, deps.len);
            errdefer a.free(depends_on);
            for (deps, 0..) |dep, i| depends_on[i] = try a.dupe(u8, dep);
            return .{
                .id = try a.dupe(u8, id),
                .task_type = kind,
                .department = try a.dupe(u8, department),
                .description = try a.dupe(u8, description),
                .contract_fields = contract_fields,
                .depends_on = depends_on,
            };
        }

        fn plan(_: *anyopaque, a: std.mem.Allocator, goal: []const u8, _: []const planner.ClarificationAnswer, _: ?[]const u8) planner.PlannerError!planner.Plan {
            const tasks = try a.alloc(planner.PlannedTask, 3);
            tasks[0] = try task(a, "build", .programar, "programacion", "Implement calculator.py", &.{.{ .name = "source", .required = true }}, &.{});
            tasks[1] = try task(a, "test", .testear, "testing", "Run requirement assertion", &.{
                .{ .name = "tests_passed" },
                .{ .name = "command", .value = "python -c \"from calculator import add; assert add(2,3) == 5\"" },
            }, &.{"build"});
            tasks[2] = try task(a, "audit", .auditar, "auditoria", "Audit calculator", &.{.{ .name = "verdict", .required = true }}, &.{"build"});
            return .{ .allocator = a, .understanding = try a.dupe(u8, goal), .questions = try a.alloc(planner.ClarificationQuestion, 0), .tasks = tasks };
        }

        fn deinit(_: *anyopaque) void {}
    };
    const QaLlm = struct {
        calls: usize = 0,
        fn call(ctx: *anyopaque, _: []const u8, _: []const u8) []const u8 {
            const self: *@This() = @ptrCast(@alignCast(ctx));
            self.calls += 1;
            return switch (self.calls) {
                1 => "[{\"field\":\"source\",\"content\":\"def add(a, b):\\n    return a + b - 2\"},{\"field\":\"filename\",\"content\":\"calculator.py\"}]",
                2 => "[{\"field\":\"tests_passed\",\"content\":\"1\"}]",
                3 => "[{\"field\":\"verdict\",\"content\":\"PASS\"}]",
                4 => "[{\"field\":\"source\",\"content\":\"def add(a, b):\\n    return a + b\"},{\"field\":\"filename\",\"content\":\"calculator.py\"}]",
                5 => "[{\"field\":\"tests_passed\",\"content\":\"1\"}]",
                6 => "[{\"field\":\"verdict\",\"content\":\"PASS\"}]",
                else => unreachable,
            };
        }
    };

    var marker: u8 = 0;
    const backend = planner.PlannerBackend{ .ptr = &marker, .planFn = QaPlanner.plan, .deinitFn = QaPlanner.deinit };
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.permission_config.mode = .bypass;
    sa.executor_spawn_fn = qaV1Spawn;
    // `python -c` es codigo inline: la politica exige tarjeta humana por comando.
    sa.approve_command_fn = testHumanApprovesInline;
    qa_v1_assertion_runs = 0;
    var outcome = try sa.processOrder("qa-v1", "calculator must make 2+3 equal 5", &.{}, backend, null, null);
    defer outcome.deinit();
    sa.setEventConn(runtime, outcome.order_id);
    var llm = QaLlm{};
    var dispatch = try sa.approveAndDispatch(&outcome, QaLlm.call, &llm, null);
    defer dispatch.deinit(allocator);

    try std.testing.expectEqual(@as(usize, 2), qa_v1_assertion_runs);
    try std.testing.expect(!dispatch.order_failed);
    try std.testing.expectEqual(@as(usize, 0), dispatch.failed_count);
    const stmt = try runtime.prepare("SELECT payload_json FROM events WHERE order_id = ? AND kind = 'test_evidence_v1' ORDER BY id");
    defer runtime.finalize(stmt);
    try db.bindInt(stmt, 1, outcome.order_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
    const payload = std.mem.span(db.c.sqlite3_column_text(stmt, 0).?);
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"exit_code\":1") != null);
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"producer_task_id\":\"build\"") != null);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
    const repaired_payload = std.mem.span(db.c.sqlite3_column_text(stmt, 0).?);
    try std.testing.expect(std.mem.indexOf(u8, repaired_payload, "\"exit_code\":0") != null);
    try std.testing.expect(std.mem.indexOf(u8, repaired_payload, "\"stdout\":\"2+3=5\"") != null);
}

test "QA-V1: executable test command runs from producer order directory" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.permission_config.mode = .bypass;
    sa.plan_approved = true;

    const producer_task = planner.PlannedTask{
        .id = "producer",
        .task_type = .programar,
        .department = "programacion",
        .description = "write calculator.py",
        .contract_fields = &.{},
        .depends_on = &.{},
    };
    var test_dependencies = [_][]const u8{"producer"};
    const test_task = planner.PlannedTask{
        .id = "test",
        .task_type = .testear,
        .department = "testing",
        .description = "write test_app.py",
        .contract_fields = &.{},
        .depends_on = test_dependencies[0..],
    };
    const producer_artifacts = [_]worker_backend.Artifact{
        .{ .path = "calculator.py", .content = "def add(a, b):\n    return a + b\n" },
    };
    const test_artifacts = [_]worker_backend.Artifact{
        .{ .path = "test_app.py", .content = "from calculator import add\nassert add(2, 3) == 5\nprint('cwd-proof')\n" },
    };
