fn commandOnlyTest(pt: planner.PlannedTask) bool {
    if (pt.task_type != .testear or pt.depends_on.len == 0 or pt.contract_fields.len != 1) return false;
    const field = pt.contract_fields[0];
    return std.mem.eql(u8, field.name, "command") and field.field_type == .string and
        field.value != null and std.mem.trim(u8, field.value.?, " \t\r\n").len > 0;
}

fn commandTestArtifact(a: std.mem.Allocator, pt: planner.PlannedTask) !worker_backend.WorkerResult {
    const id = try a.dupe(u8, pt.id);
    errdefer a.free(id);
    const message = try a.dupe(u8, "");
    errdefer a.free(message);
    const artifacts = try a.alloc(worker_backend.Artifact, 1);
    errdefer a.free(artifacts);
    const name = try a.dupe(u8, "command");
    errdefer a.free(name);
    artifacts[0] = .{ .path = name, .content = try a.dupe(u8, pt.contract_fields[0].value.?) };
    return .{ .task_id = id, .artifacts = artifacts, .success = true, .error_msg = message };
}

test "QA-V1 command-only test executes without calling an LLM" {
    const a = std.testing.allocator;
    var runtime = try openRuntime(a);
    defer runtime.close();
    const P = struct {
        fn plan(_: *anyopaque, alloc: std.mem.Allocator, goal: []const u8, _: []const planner.ClarificationAnswer, _: ?[]const u8) planner.PlannerError!planner.Plan {
            const tasks = try alloc.alloc(planner.PlannedTask, 2);
            tasks[0] = try D7Planner.tarea(alloc, "producer", "Implement fixture.c", &.{});
            tasks[1] = try D7Planner.tarea(alloc, "qa", "Run the existing command", &.{"producer"});
            tasks[1].task_type = .testear;
            for (tasks[1].contract_fields) |field| {
                alloc.free(field.name);
                if (field.value) |value| alloc.free(value);
            }
            alloc.free(tasks[1].contract_fields);
            tasks[1].contract_fields = try alloc.alloc(planner.ContractField, 1);
            tasks[1].contract_fields[0] = .{ .name = try alloc.dupe(u8, "command"), .field_type = .string, .required = true, .value = try alloc.dupe(u8, "python --version") };
            return .{ .allocator = alloc, .understanding = try alloc.dupe(u8, goal), .questions = try alloc.alloc(planner.ClarificationQuestion, 0), .tasks = tasks };
        }
        fn deinit(_: *anyopaque) void {}
    };
    const L = struct {
        calls: usize = 0,
        fn call(ctx: *anyopaque, _: []const u8, _: []const u8) []const u8 {
            const self: *@This() = @ptrCast(@alignCast(ctx));
            self.calls += 1;
            return "[{\"field\":\"source\",\"content\":\"int main() { return 0; }\"},{\"field\":\"filename\",\"content\":\"fixture.c\"}]";
        }
    };
    var marker: u8 = 0;
    var sa = Superagent.init(a, runtime, null, NoopMemory.backend(), 1);
    sa.permission_config.mode = .bypass;
    sa.executor_spawn_fn = testExecutorSpawnOk;
    var outcome = try sa.processOrder("qa-command-fixture", "Implement fixture", &.{}, .{ .ptr = &marker, .planFn = P.plan, .deinitFn = P.deinit }, null, null);
    defer outcome.deinit();
    sa.setEventConn(runtime, outcome.order_id);
    var llm = L{};
    var dispatch = try sa.approveAndDispatch(&outcome, L.call, &llm, null);
    defer dispatch.deinit(a);
    try std.testing.expectEqual(@as(usize, 1), llm.calls);
    try std.testing.expect(!dispatch.order_failed);
    const stmt = try runtime.prepare("SELECT payload_json FROM events WHERE order_id=? AND kind='test_evidence_v1' ORDER BY id DESC LIMIT 1");
    defer runtime.finalize(stmt);
    try db.bindInt(stmt, 1, outcome.order_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
    const payload = std.mem.span(db.c.sqlite3_column_text(stmt, 0).?);
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"ran\":true") != null);
    try std.testing.expect(std.mem.indexOf(u8, payload, "\"exit_code\":0") != null);
}

