test "UI-ACTION: buildUiActionPayload emite solo acciones del allowlist con args acotados" {
    const allocator = std.testing.allocator;

    // Accion valida con arg conocido -> payload con action, task_id y args.
    {
        const fields = try allocator.dupe(planner.ContractField, &[_]planner.ContractField{
            .{ .name = "action", .field_type = .string, .required = true, .value = "set_theme" },
            .{ .name = "theme", .field_type = .string, .required = true, .value = "nord" },
        });
        defer allocator.free(fields);
        const pt = planner.PlannedTask{ .id = "t1", .task_type = .ui, .department = "programacion", .description = "ui", .contract_fields = fields, .depends_on = &.{} };
        const payload = buildUiActionPayload(allocator, pt);
        try std.testing.expect(payload != null);
        defer allocator.free(payload.?);
        try std.testing.expect(std.mem.indexOf(u8, payload.?, "\"set_theme\"") != null);
        try std.testing.expect(std.mem.indexOf(u8, payload.?, "\"nord\"") != null);
        try std.testing.expect(std.mem.indexOf(u8, payload.?, "\"t1\"") != null);
    }
    // Accion fuera del allowlist -> null (nunca se emite el evento).
    {
        const fields = try allocator.dupe(planner.ContractField, &[_]planner.ContractField{
            .{ .name = "action", .field_type = .string, .required = true, .value = "set_permission_config" },
        });
        defer allocator.free(fields);
        const pt = planner.PlannedTask{ .id = "t1", .task_type = .ui, .department = "programacion", .description = "ui", .contract_fields = fields, .depends_on = &.{} };
        try std.testing.expect(buildUiActionPayload(allocator, pt) == null);
    }
    // Sin action -> null. Arg desconocido -> se ignora, no se cuela al payload.
    {
        const fields = try allocator.dupe(planner.ContractField, &[_]planner.ContractField{
            .{ .name = "theme", .field_type = .string, .required = true, .value = "nord" },
        });
        defer allocator.free(fields);
        const pt = planner.PlannedTask{ .id = "t1", .task_type = .ui, .department = "programacion", .description = "ui", .contract_fields = fields, .depends_on = &.{} };
        try std.testing.expect(buildUiActionPayload(allocator, pt) == null);
    }
    {
        const fields = try allocator.dupe(planner.ContractField, &[_]planner.ContractField{
            .{ .name = "action", .field_type = .string, .required = true, .value = "notify" },
            .{ .name = "text", .field_type = .string, .required = true, .value = "hola" },
            .{ .name = "command", .field_type = .string, .required = false, .value = "rm -rf" },
        });
        defer allocator.free(fields);
        const pt = planner.PlannedTask{ .id = "t1", .task_type = .ui, .department = "programacion", .description = "ui", .contract_fields = fields, .depends_on = &.{} };
        const payload = buildUiActionPayload(allocator, pt);
        try std.testing.expect(payload != null);
        defer allocator.free(payload.?);
        try std.testing.expect(std.mem.indexOf(u8, payload.?, "rm -rf") == null);
        try std.testing.expect(std.mem.indexOf(u8, payload.?, "\"hola\"") != null);
    }
}

test "UI-ACTION: tarea ui emite evento ui_action y task_done sin llamar a un modelo" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();

    const UiPlanner = struct {
        fn plan(_: *anyopaque, a: std.mem.Allocator, goal: []const u8, _: []const planner.ClarificationAnswer, _: ?[]const u8) planner.PlannerError!planner.Plan {
            const cf = try a.alloc(planner.ContractField, 2);
            cf[0] = .{ .name = try a.dupe(u8, "action"), .field_type = .string, .required = true, .value = try a.dupe(u8, "set_theme") };
            cf[1] = .{ .name = try a.dupe(u8, "theme"), .field_type = .string, .required = true, .value = try a.dupe(u8, "midnight") };
            const tasks = try a.alloc(planner.PlannedTask, 1);
            tasks[0] = .{
                .id = try a.dupe(u8, "t1"),
                .task_type = .ui,
                .department = try a.dupe(u8, "programacion"),
                .description = try a.dupe(u8, "UI action set_theme"),
                .contract_fields = cf,
                .depends_on = try a.alloc([]const u8, 0),
            };
            return .{ .allocator = a, .understanding = try a.dupe(u8, goal), .questions = try a.alloc(planner.ClarificationQuestion, 0), .tasks = tasks };
        }
        fn deinit(_: *anyopaque) void {}
    };
    var marker: u8 = 0;
    const backend = planner.PlannerBackend{ .ptr = &marker, .planFn = UiPlanner.plan, .deinitFn = UiPlanner.deinit };

    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.executor_spawn_fn = testExecutorSpawn;
    sa.setEventConn(runtime, 1);
    var outcome = try sa.processOrder("proj-ui", "cambia el tema a midnight", &.{}, backend, null, null);
    defer outcome.deinit();

    // llm_fn que marca un test fallido si se llama — la tarea ui nunca toca un modelo.
    const failLlm = struct {
        fn call(ctx: *anyopaque, _: []const u8, _: []const u8) []const u8 {
            const c: *u8 = @ptrCast(@alignCast(ctx));
            c.* = 1;
            return ""; // empty = fallo del worker; nunca deberia ocurrir
        }
    }.call;
    var llm_ctx: u8 = 0;
    var dr = try sa.approveAndDispatch(&outcome, failLlm, &llm_ctx, null);
    defer dr.deinit(allocator);
    try std.testing.expectEqual(@as(u8, 0), llm_ctx); // el LLM jamas fue invocado

    // El evento ui_action quedo en el stream de la orden con el tema pedido.
    const stmt = try runtime.prepare("SELECT payload_json FROM events WHERE order_id = ? AND kind = 'ui_action' LIMIT 1");
    defer runtime.finalize(stmt);
    try db.bindInt(stmt, 1, outcome.order_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
    const ptr = db.c.sqlite3_column_text(stmt, 0);
    try std.testing.expect(ptr != null);
    const payload = ptr[0..std.mem.len(ptr)];
    try std.testing.expect(std.mem.indexOf(u8, payload, "set_theme") != null);
    try std.testing.expect(std.mem.indexOf(u8, payload, "midnight") != null);

    // Y la tarea cerro como task_done determinista (sin modelo).
    const stmt2 = try runtime.prepare("SELECT payload_json FROM events WHERE order_id = ? AND kind = 'task_done' LIMIT 1");
    defer runtime.finalize(stmt2);
    try db.bindInt(stmt2, 1, outcome.order_id);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt2));
    const ptr2 = db.c.sqlite3_column_text(stmt2, 0);
    try std.testing.expect(ptr2 != null);
    try std.testing.expect(std.mem.indexOf(u8, ptr2[0..std.mem.len(ptr2)], "deterministic") != null);
}

// ── AUDIT-UNAVAILABLE-P0 (S22, orden 500) ────────────────────────────────────
// La orden 500 cerró "auditada" sin que el auditor respondiera nunca: el
// fallback local fabricaba verdict=PASS al ver ".py" en el contexto, y
// promoteFailedAuditEvidence asentaba ese PASS en el ledger sobre el productor.
// Estas pruebas fijan el diseño aprobado: sin veredicto usable NO hay PASS,
// la orden cierra 'audit_unavailable' (ni done ni failed), la entrega sigue
// bloqueada y solo el usuario puede reintentar la auditoría a mano.

test "AUDIT-UNAVAILABLE-P0: auditVerdictOf clasifica estricto — PASS/FAIL de verdad, todo lo demás unavailable" {
    const pass = [_]worker_backend.Artifact{.{ .path = "verdict", .content = "PASS" }};
    try std.testing.expectEqual(AuditVerdict.pass, auditVerdictOf(&pass));
    const pass_reason = [_]worker_backend.Artifact{.{ .path = "verdict", .content = "PASS: sin hallazgos en calculator.py" }};
    try std.testing.expectEqual(AuditVerdict.pass, auditVerdictOf(&pass_reason));
    const fail = [_]worker_backend.Artifact{.{ .path = "verdict", .content = "FAIL: el resultado usa resta y debe sumar" }};
    try std.testing.expectEqual(AuditVerdict.fail, auditVerdictOf(&fail));
    const fail_bare = [_]worker_backend.Artifact{.{ .path = "verdict", .content = "FAIL" }};
    try std.testing.expectEqual(AuditVerdict.fail, auditVerdictOf(&fail_bare));

    // Lo que NO es un veredicto nunca se lee como PASS:
    // - "PASSING" con borde de palabra (un token prefijado no vale).
    const passing = [_]worker_backend.Artifact{.{ .path = "verdict", .content = "PASSING the torch" }};
    try std.testing.expectEqual(AuditVerdict.unavailable, auditVerdictOf(&passing));
    // - ruido libre del mock/proveedor ("mock-value", prosa, markdown).
    const mock_noise = [_]worker_backend.Artifact{.{ .path = "verdict", .content = "mock-value" }};
    try std.testing.expectEqual(AuditVerdict.unavailable, auditVerdictOf(&mock_noise));
    const prose = [_]worker_backend.Artifact{.{ .path = "verdict", .content = "el código parece correcto en general" }};
    try std.testing.expectEqual(AuditVerdict.unavailable, auditVerdictOf(&prose));
    // - vacío o ausente.
    const empty = [_]worker_backend.Artifact{.{ .path = "verdict", .content = "   " }};
    try std.testing.expectEqual(AuditVerdict.unavailable, auditVerdictOf(&empty));
    const missing = [_]worker_backend.Artifact{.{ .path = "notes", .content = "algo" }};
    try std.testing.expectEqual(AuditVerdict.unavailable, auditVerdictOf(&missing));
    try std.testing.expectEqual(AuditVerdict.unavailable, auditVerdictOf(&.{}));
}

/// Plan mínimo para las pruebas de esta red: tarea productora + auditoría que
/// depende de ella. Réplica del contrato real de `auditar` (verdict requerido).
const AuditUnavailablePlanner = struct {
    fn task(a: std.mem.Allocator, id: []const u8, kind: model_router.TaskType, department: []const u8, description: []const u8, verdict_field: bool, deps: []const []const u8) !planner.PlannedTask {
        var contract_fields = std.ArrayList(planner.ContractField).empty;
        if (kind == .programar) {
            try contract_fields.append(a, .{ .name = try a.dupe(u8, "source"), .field_type = .string, .required = true, .value = null });
        }
        if (verdict_field) {
            try contract_fields.append(a, .{ .name = try a.dupe(u8, "verdict"), .field_type = .string, .required = true, .value = null });
        }
        const depends_on = try a.alloc([]const u8, deps.len);
        for (deps, 0..) |dep, i| depends_on[i] = try a.dupe(u8, dep);
        return .{
            .id = try a.dupe(u8, id),
            .task_type = kind,
            .department = try a.dupe(u8, department),
            .description = try a.dupe(u8, description),
            .contract_fields = try contract_fields.toOwnedSlice(a),
            .depends_on = depends_on,
        };
    }

    fn plan(_: *anyopaque, a: std.mem.Allocator, goal: []const u8, _: []const planner.ClarificationAnswer, _: ?[]const u8) planner.PlannerError!planner.Plan {
        const tasks = try a.alloc(planner.PlannedTask, 2);
        tasks[0] = try task(a, "t1", .programar, "programacion", "Implement calculator.py", false, &.{});
        tasks[1] = try task(a, "t2", .auditar, "auditoria", "Audit calculator.py", true, &.{"t1"});
        return .{ .allocator = a, .understanding = try a.dupe(u8, goal), .questions = try a.alloc(planner.ClarificationQuestion, 0), .tasks = tasks };
    }

    fn deinit(_: *anyopaque) void {}
};

const AuditSeqLlm = struct {
    calls: usize = 0,
    producer_response: []const u8,
    audit_response: []const u8,
    fn call(ctx: *anyopaque, _: []const u8, _: []const u8) []const u8 {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        self.calls += 1;
        // Ola 1 = productor (t1); ola 2 = auditor (t2). Sin corrección en este
        // escenario: audit_unavailable se salta el lazo por diseño.
        return if (self.calls == 1) self.producer_response else self.audit_response;
    }
};

test "AUDIT-UNAVAILABLE-P0: auditor sin veredicto usable cierra la orden audit_unavailable (ni done ni failed)" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();

    var marker: u8 = 0;
    const backend = planner.PlannerBackend{ .ptr = &marker, .planFn = AuditUnavailablePlanner.plan, .deinitFn = AuditUnavailablePlanner.deinit };
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.permission_config.mode = .bypass;
    sa.plan_approved = true;
    var outcome = try sa.processOrder("proj-au", "calculator in python", &.{}, backend, null, null);
    defer outcome.deinit();
    sa.setEventConn(runtime, outcome.order_id);

    var llm = AuditSeqLlm{
        .producer_response = "[{\"field\":\"source\",\"content\":\"def add(a, b):\\n    return a + b\"},{\"field\":\"filename\",\"content\":\"calculator.py\"}]",
        // El auditor respondió — pero el campo verdict es ruido irreconocible,
        // lo mismo que produjo el fallback local en la orden 500 sin que nadie
        // revisara nada. No es PASS ni FAIL: es la ausencia de revisión.
        .audit_response = "[{\"field\":\"verdict\",\"content\":\"mock-value\"}]",
    };
    var dispatch = try sa.approveAndDispatch(&outcome, AuditSeqLlm.call, &llm, null);
    defer dispatch.deinit(allocator);

    try std.testing.expect(dispatch.order_audit_unavailable);
    try std.testing.expect(!dispatch.order_failed);
    try std.testing.expect(!dispatch.order_cancelled);
    try std.testing.expectEqual(@as(usize, 1), dispatch.audit_unavailable_count);
    // El productor completó — su trabajo se conserva; solo falta la revisión.
    try std.testing.expectEqual(@as(usize, 1), dispatch.completed_count);
    try std.testing.expectEqual(@as(usize, 0), dispatch.failed_count);

    // El terminal comprometido en DB es el tercero honesto.
    const status = try fetchOrderStatus(allocator, runtime, outcome.order_id);
    defer allocator.free(status);
    try std.testing.expectEqualStrings("audit_unavailable", status);

    // La tarea de auditoría quedó 'audit_unavailable' (ni completed ni failed)
    // — el checkpoint de reintento la re-ejecuta sin tocar al productor.
    const tstmt = try runtime.prepare("SELECT status FROM tasks WHERE plan_id = ? AND status = 'audit_unavailable'");
    defer runtime.finalize(tstmt);
    if (outcome.plan_id) |pid| try db.bindInt(tstmt, 1, pid);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(tstmt));

    // Eventos versionados: la tarea y la orden narran su estado real — ningún
    // order_done/order_failed puede coexistir con este cierre.
    {
        const estmt = try runtime.prepare("SELECT COUNT(*) FROM events WHERE order_id = ? AND kind = 'task_audit_unavailable_v1'");
        defer runtime.finalize(estmt);
        try db.bindInt(estmt, 1, outcome.order_id);
        try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(estmt));
        try std.testing.expectEqual(@as(c_int, 1), db.c.sqlite3_column_int(estmt, 0));
    }
    {
        const estmt = try runtime.prepare("SELECT payload_json FROM events WHERE order_id = ? AND kind = 'order_audit_unavailable_v1'");
        defer runtime.finalize(estmt);
        try db.bindInt(estmt, 1, outcome.order_id);
        try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(estmt));
        const payload = std.mem.span(db.c.sqlite3_column_text(estmt, 0).?);
        try std.testing.expect(std.mem.indexOf(u8, payload, "\"cause\":\"audit_unavailable\"") != null);
        try std.testing.expect(std.mem.indexOf(u8, payload, "\"t2\"") != null);
        try std.testing.expect(db.c.sqlite3_step(estmt) != db.c.SQLITE_ROW); // un solo cierre
    }
    {
        const estmt = try runtime.prepare("SELECT COUNT(*) FROM events WHERE order_id = ? AND kind IN ('order_done','order_failed')");
        defer runtime.finalize(estmt);
        try db.bindInt(estmt, 1, outcome.order_id);
        try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(estmt));
        try std.testing.expectEqual(@as(c_int, 0), db.c.sqlite3_column_int(estmt, 0));
    }
    // El ledger NO asienta un veredicto sobre la auditoría que no ocurrió:
    // ninguna fila toca a t2 y ningún AUDIT viene firmado por un modelo. Las
    // entradas legítimas del motor sobre el productor (BUILD, gate
    // determinista, provider sin modelo) sí pueden existir — son evidencia real.
    for (dispatch.audit_entries) |e| {
        if (e.subject_id == 2) return error.TestUnexpectedResult; // t2 sin fila alguna
        if (std.mem.eql(u8, e.action, "AUDIT") and e.model_id.len > 0)
            return error.TestUnexpectedResult; // nadie auditó → ningún veredicto de modelo
    }
}

