// ── T8: eventos reales del motor para el grafo de la orden ──
// Cada prueba PROVOCA el evento con una orden de verdad (planificador y
// trabajador de prueba de la suite) y comprueba su forma; ninguna lo inserta.

/// Payloads de un tipo de evento de la orden, en orden de llegada.
fn t8Payloads(a: std.mem.Allocator, conn: db.Connection, order_id: i64, kind: []const u8) !std.ArrayList([]u8) {
    var list = std.ArrayList([]u8).empty;
    errdefer {
        for (list.items) |p| a.free(p);
        list.deinit(a);
    }
    const st = try conn.prepare("SELECT payload_json FROM events WHERE order_id = ? AND kind = ? ORDER BY id");
    defer conn.finalize(st);
    try db.bindInt(st, 1, order_id);
    try db.bindText(st, 2, kind);
    while (db.c.sqlite3_step(st) == db.c.SQLITE_ROW) {
        const ptr = db.c.sqlite3_column_text(st, 0);
        try list.append(a, try a.dupe(u8, ptr[0..@intCast(db.c.sqlite3_column_bytes(st, 0))]));
    }
    return list;
}

fn t8FreePayloads(a: std.mem.Allocator, list: *std.ArrayList([]u8)) void {
    for (list.items) |p| a.free(p);
    list.deinit(a);
}

/// Productor + dos auditores del mismo productor: la segunda ola tiene dos
/// tareas (colmena real) y la segunda `auditar` es la del segundo auditor.
const T8TwoAuditorsPlanner = struct {
    fn plan(_: *anyopaque, a: std.mem.Allocator, goal: []const u8, _: []const planner.ClarificationAnswer, _: ?[]const u8) planner.PlannerError!planner.Plan {
        const tasks = try a.alloc(planner.PlannedTask, 3);
        tasks[0] = try AuditUnavailablePlanner.task(a, "t1", .programar, "programacion", "Implement calculator.py", false, &.{});
        tasks[1] = try AuditUnavailablePlanner.task(a, "t2", .auditar, "auditoria", "Audit calculator.py", true, &.{"t1"});
        tasks[2] = try AuditUnavailablePlanner.task(a, "t3", .auditar, "auditoria", "Second audit of calculator.py", true, &.{"t1"});
        return .{ .allocator = a, .understanding = try a.dupe(u8, goal), .questions = try a.alloc(planner.ClarificationQuestion, 0), .tasks = tasks };
    }
    fn deinit(_: *anyopaque) void {}
};

/// Como AuditSeqLlm, pero con contador atómico: los dos auditores corren en
/// hilos a la vez.
const T8SeqLlm = struct {
    calls: std.atomic.Value(usize) = .init(0),
    fn call(ctx: *anyopaque, _: []const u8, _: []const u8) []const u8 {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        const n = self.calls.fetchAdd(1, .monotonic);
        return if (n == 0)
            "[{\"field\":\"source\",\"content\":\"def add(a, b):\\n    return a + b\"},{\"field\":\"filename\",\"content\":\"calculator.py\"}]"
        else
            "[{\"field\":\"verdict\",\"content\":\"PASS: la suma es correcta\"}]";
    }
};

test "T8 swarm_group_v1 nace de la ola real y task_audit distingue al segundo auditor" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var marker: u8 = 0;
    const backend = planner.PlannerBackend{ .ptr = &marker, .planFn = T8TwoAuditorsPlanner.plan, .deinitFn = T8TwoAuditorsPlanner.deinit };
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.permission_config.mode = .bypass;
