    var outcome = try sa.processOrder("proj-t8-audit", "calculator in python", &.{}, backend, null, null);
    defer outcome.deinit();
    sa.setEventConn(runtime, outcome.order_id);
    var llm = T8SeqLlm{};
    var dispatch = try sa.approveAndDispatch(&outcome, T8SeqLlm.call, &llm, null);
    defer dispatch.deinit(allocator);

    // Una sola ola con más de una tarea: la de los dos auditores.
    var groups = try t8Payloads(allocator, runtime, outcome.order_id, "swarm_group_v1");
    defer t8FreePayloads(allocator, &groups);
    try std.testing.expectEqual(@as(usize, 1), groups.items.len);
    const Group = struct { wave: usize, members: []const []const u8, size: usize, parallel: bool };
    const g = try std.json.parseFromSlice(Group, allocator, groups.items[0], .{});
    defer g.deinit();
    try std.testing.expectEqual(@as(usize, 2), g.value.wave);
    try std.testing.expectEqual(@as(usize, 2), g.value.size);
    try std.testing.expectEqual(@as(usize, 2), g.value.members.len);
    try std.testing.expectEqualStrings("t2", g.value.members[0]);
    try std.testing.expectEqualStrings("t3", g.value.members[1]);
    try std.testing.expect(g.value.parallel);

    // Veredictos de modelo sobre t1: uno del primer auditor y otro del segundo.
    var audits = try t8Payloads(allocator, runtime, outcome.order_id, "task_audit");
    defer t8FreePayloads(allocator, &audits);
    const Audit = struct { task_id: i64, verdict: []const u8, auditor_index: u8, role: []const u8 };
    var first = false;
    var second = false;
    for (audits.items) |p| {
        const v = try std.json.parseFromSlice(Audit, allocator, p, .{ .ignore_unknown_fields = true });
        defer v.deinit();
        switch (v.value.auditor_index) {
            0 => try std.testing.expectEqualStrings("deterministic_gate", v.value.role),
            1 => {
                try std.testing.expectEqualStrings("audit", v.value.role);
                try std.testing.expectEqual(@as(i64, 1), v.value.task_id);
                first = true;
            },
            2 => {
                try std.testing.expectEqualStrings("second_audit", v.value.role);
                try std.testing.expectEqual(@as(i64, 1), v.value.task_id);
                try std.testing.expectEqualStrings("PASS", v.value.verdict);
                second = true;
            },
            else => return error.TestUnexpectedResult,
        }
    }
    try std.testing.expect(first and second);
}

