/// Memoria de prueba con el formato real de LocalMemory (arreglo JSON de
/// filas {content…}); la primera lección tiene la forma de las que guarda el
/// motor al fallar una orden.
const T8LessonsMemory = struct {
    var saved: usize = 0;
    var accept: bool = true;
    /// La prueba de guardado no da lecciones: así el plan es el mismo que
    /// el de la prueba MOT018 de la que copia el escenario.
    var serve: bool = true;
    fn backend() MemoryBackend {
        return .{ .ptr = undefined, .loadContextFn = load, .saveFindingFn = save, .sessionSummaryFn = summary, .saveLessonFn = saveLesson, .loadLessonsFn = loadLessons };
    }
    fn load(_: *anyopaque, _: std.mem.Allocator, _: []const u8) ?[]const u8 {
        return null;
    }
    fn save(_: *anyopaque, _: []const u8) void {}
    fn summary(_: *anyopaque, _: []const u8, _: []const u8) void {}
    fn saveLesson(_: *anyopaque, _: []const u8, _: []const u8) bool {
        if (accept) saved += 1;
        return accept;
    }
    fn loadLessons(_: *anyopaque, allocator: std.mem.Allocator, _: []const u8, _: usize) ?[]const u8 {
        if (!serve) return null;
        return allocator.dupe(u8,
            \\[{"id":1,"content":"{\"order_id\":7,\"prompt\":\"construye la calculadora\\ny mas cosas\",\"cause\":\"all_tasks_failed\"}","project":"p","created_at":1},
            \\ {"id":2,"content":"<img src=x onerror=alert(1)> una lección escrita a mano que es bastante más larga que ochenta bytes en total","project":"p","created_at":2}]
        ) catch null;
    }
};

