test "T8 replan_v1: changes se acota a 512 bytes sin partir un carácter" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var mp = planner.MockPlanner.init(allocator);
    const pb = mp.backend();
    defer pb.deinit();
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    var outcome = try sa.processOrder("proj-t8-replan", "construye una calculadora CLI en C con tests", &.{}, pb, null, null);
    defer outcome.deinit();
    const first_plan = outcome.plan_id.?;
    // Lo mismo que hace da_order_replan_async: misma fila y cambios del usuario.
    const changes = "x" ++ "ñ" ** 400;
    sa.reuse_order_id = outcome.order_id;
    sa.replan_changes = changes;
    var outcome2 = try sa.processOrder("proj-t8-replan", "construye una calculadora CLI en C con tests", &.{}, pb, null, null);
    defer outcome2.deinit();
    try std.testing.expectEqual(outcome.order_id, outcome2.order_id);
    var ev = try t8Payloads(allocator, runtime, outcome.order_id, "replan_v1");
    defer t8FreePayloads(allocator, &ev);
    try std.testing.expectEqual(@as(usize, 1), ev.items.len);
    const Replan = struct { reason: []const u8, from_plan_id: ?i64, to_plan_id: i64, same_row: bool, changes: []const u8 };
    const v = try std.json.parseFromSlice(Replan, allocator, ev.items[0], .{ .ignore_unknown_fields = true });
    defer v.deinit();
    try std.testing.expectEqualStrings("user_changes", v.value.reason);
    try std.testing.expectEqual(first_plan, v.value.from_plan_id.?);
    try std.testing.expectEqual(outcome2.plan_id.?, v.value.to_plan_id);
    try std.testing.expect(v.value.same_row);
    // 1 + 255*2 = 511 bytes: el siguiente carácter ya no cabe entero.
    try std.testing.expectEqual(@as(usize, 511), v.value.changes.len);
    try std.testing.expect(std.unicode.utf8ValidateSlice(v.value.changes));
}

test "T8 sidekick_task_v1: solo la tarea que corre con el modelo del rol sidekick" {
