    try catalog.exec("INSERT INTO models (id,provider_id,model_name,context_window,is_free,latency_p50_ms,available) VALUES (2,1,'claude-fixture',128000,1,900,1)");
    var router = model_router.Router.init(allocator, catalog, null, 1);
    try router.seedInitialScores();
    try composer_roles.set(allocator, catalog, "sidekick", "OpenRouter", "claude-fixture");
    const SidekickPlanner = struct {
        fn plan(_: *anyopaque, a: std.mem.Allocator, goal: []const u8, _: []const planner.ClarificationAnswer, _: ?[]const u8) planner.PlannerError!planner.Plan {
            const tasks = try a.alloc(planner.PlannedTask, 2);
            tasks[0] = try AuditUnavailablePlanner.task(a, "t1", .investigar, "documentacion", "Investiga la API de suma", false, &.{});
            tasks[1] = try AuditUnavailablePlanner.task(a, "t2", .programar, "programacion", "Implement calculator.py", false, &.{});
            return .{ .allocator = a, .understanding = try a.dupe(u8, goal), .questions = try a.alloc(planner.ClarificationQuestion, 0), .tasks = tasks };
        }
        fn deinit(_: *anyopaque) void {}
    };
    var marker: u8 = 0;
    const backend = planner.PlannerBackend{ .ptr = &marker, .planFn = SidekickPlanner.plan, .deinitFn = SidekickPlanner.deinit };
    var sa = Superagent.init(allocator, runtime, &router, NoopMemory.backend(), 1);
    sa.permission_config.mode = .bypass;
    sa.plan_approved = true;
    var outcome = try sa.processOrder("proj-t8-side", "calculator in python", &.{}, backend, null, null);
    defer outcome.deinit();
    sa.setEventConn(runtime, outcome.order_id);
    var llm = TestLlmCtx{ .response = "[{\"field\":\"source\",\"content\":\"def add(a, b):\\n    return a + b\"},{\"field\":\"filename\",\"content\":\"calculator.py\"}]" };
    var dr = try sa.approveAndDispatch(&outcome, testLlmFn, &llm, null);
    defer dr.deinit(allocator);
    var ev = try t8Payloads(allocator, runtime, outcome.order_id, "sidekick_task_v1");
    defer t8FreePayloads(allocator, &ev);
    try std.testing.expectEqual(@as(usize, 1), ev.items.len);
    const Side = struct { task_id: []const u8, kind: []const u8, provider: []const u8, model: []const u8 };
    const v = try std.json.parseFromSlice(Side, allocator, ev.items[0], .{});
    defer v.deinit();
    try std.testing.expectEqualStrings("t1", v.value.task_id);
    try std.testing.expectEqualStrings("investigar", v.value.kind);
    // The injected test worker is generic; telemetry must not claim the planned model ran.
    try std.testing.expectEqualStrings("generic", v.value.model);

    // VG1 B-8: emulate the completed fallback assignment after quota exhaustion.
    var fallback = [_]ModelChoice{.{ .provider_name = "Google", .model_name = "actual-after-quota", .is_free = true }};
    const assignment = ModelAssignment{ .task_id = "t1", .assigned = true, .provider_name = "OpenRouter", .model_name = "claude-fixture", .is_free = true, .reason = "fixture", .fallbacks = &fallback };
    sa.recordSidekickTask(outcome.plan.tasks[0], assignment, "actual-after-quota");
    var replaced = try t8Payloads(allocator, runtime, outcome.order_id, "sidekick_task_v1");
    defer t8FreePayloads(allocator, &replaced);
    const actual = try std.json.parseFromSlice(Side, allocator, replaced.items[replaced.items.len - 1], .{});
    defer actual.deinit();
    try std.testing.expectEqualStrings("actual-after-quota", actual.value.model);
    try std.testing.expectEqualStrings("Google", actual.value.provider);

    // Sin pin de sidekick, la misma orden no anuncia ningún sidekick.
    try composer_roles.set(allocator, catalog, "sidekick", "", "");
    var outcome2 = try sa.processOrder("proj-t8-side", "calculator in python", &.{}, backend, null, null);
    defer outcome2.deinit();
    sa.setEventConn(runtime, outcome2.order_id);
    var dr2 = try sa.approveAndDispatch(&outcome2, testLlmFn, &llm, null);
    defer dr2.deinit(allocator);
    var none = try t8Payloads(allocator, runtime, outcome2.order_id, "sidekick_task_v1");
    defer t8FreePayloads(allocator, &none);
    try std.testing.expectEqual(@as(usize, 0), none.items.len);
}

