    sa.plan_approved = true;
    var outcome = try sa.processOrder("proj-au4", "calculator in python", &.{}, backend, null, null);
    defer outcome.deinit();

    // FAIL sin razón concreta: la evidencia no se promociona al productor (D3)
    // y no hay corrección que agote ciclos — la orden falla, no queda sin auditar.
    var llm = AuditSeqLlm{
        .producer_response = "[{\"field\":\"source\",\"content\":\"def add(a, b):\\n    return a - b\"},{\"field\":\"filename\",\"content\":\"calculator.py\"}]",
        .audit_response = "[{\"field\":\"verdict\",\"content\":\"FAIL\"}]",
    };
    var dispatch = try sa.approveAndDispatch(&outcome, AuditSeqLlm.call, &llm, null);
    defer dispatch.deinit(allocator);

    try std.testing.expect(!dispatch.order_audit_unavailable);
    try std.testing.expect(dispatch.order_failed);
    const status = try fetchOrderStatus(allocator, runtime, outcome.order_id);
    defer allocator.free(status);
    try std.testing.expectEqualStrings("failed", status);
}

test "AUDIT-UNAVAILABLE-P0: tryCommitTerminal admite el par audit_unavailable y el reintento puede comprometer done" {
    const allocator = std.testing.allocator;
    var conn = try openRuntime(allocator);
    defer conn.close();

    try conn.exec("INSERT INTO orders (id, project_id, user_prompt, status, created_at) VALUES (1, 'p', 'x', 'running', 0)");

    // El par es válido y compromete status+evento atómicamente.
    const won = try conn.tryCommitTerminal(1, "audit_unavailable", "order_audit_unavailable_v1", "test", "{}", 2);
    try std.testing.expect(won);

    const status = try fetchOrderStatus(allocator, conn, 1);
    defer allocator.free(status);
    try std.testing.expectEqualStrings("audit_unavailable", status);

    // NO es un terminal irreversible: el reintento manual (resume → nueva
    // auditoría) compromete done después — si estuviera en la lista de
    // excluidas del UPDATE, este commit devolvería false y la orden quedaría
    // clavada para siempre.
    const won2 = try conn.tryCommitTerminal(1, "done", "order_done", "superagente", "{}", 3);
    try std.testing.expect(won2);

    const status2 = try fetchOrderStatus(allocator, conn, 1);
    defer allocator.free(status2);
    try std.testing.expectEqualStrings("done", status2);

    // El índice único no cubre order_audit_unavailable_v1: volver a quedar sin
    // auditar tras un reintento emite un evento nuevo (la traza conserva cada
    // cierre, no los colapsa).
    const won3 = try conn.tryCommitTerminal(1, "audit_unavailable", "order_audit_unavailable_v1", "test", "{}", 4);
    try std.testing.expect(!won3); // done ya ganó — irreversible de verdad
}

// ---------------------------------------------------------------------------
// B1 — contrato planner↔worker↔executor (orden #527: `powershell` pelado
// produjo un banner, exit 0 y audit PASS sin haber ejecutado nada).
// ---------------------------------------------------------------------------

test "B1: el artefacto `command` del worker gana al `target` (orden #527)" {
    const allocator = std.testing.allocator;
    // El caso medido: el planner llenó `target` con el exe y el worker
    // devolvió el comando real en `command`. El fallback viejo solo miraba
    // `target` y ejecutaba el exe sin argumentos.
    var fields = [_]planner.ContractField{
        .{ .name = "target", .field_type = .string, .required = false, .value = "powershell" },
    };
    const pt = planner.PlannedTask{
        .id = "t1",
        .task_type = .ejecutar,
        .department = "ops",
        .description = "Ejecutar el comando indicado",
        .contract_fields = fields[0..],
        .depends_on = &.{},
    };
    const artifacts = [_]worker_backend.Artifact{
        .{ .path = "command", .content = "powershell -Command \"1..4 | ForEach-Object { Write-Output ('tick ' + $_) }\"" },
        .{ .path = "target", .content = "powershell" },
    };
    var parsed = (try resolveTaskCommand(allocator, pt, &artifacts)) orelse return error.TestUnexpectedResult;
    defer parsed.deinit();
    try std.testing.expectEqualStrings("powershell", parsed.exe);
    try std.testing.expectEqual(@as(usize, 2), parsed.args.len);
    try std.testing.expect(std.mem.indexOf(u8, parsed.args[1], "ForEach-Object") != null);
}

