test "B1: prosa en `command` del planner NO gana — gana el artefacto del worker (orden #528)" {
    const allocator = std.testing.allocator;
    // El planner volcó la frase del usuario en `command` ("exactamente este
    // comando de PowerShell y dime la salida: 1..4 | ..."): contiene `|` pero
    // empieza con prosa. Ese candidato se descarta y gana el `command` real
    // del worker — antes el wrap tragaba la prosa entera y PowerShell fallaba
    // con un error de sintaxis incomprensible.
    var fields = [_]planner.ContractField{
        .{ .name = "command", .field_type = .string, .required = false, .value = "exactamente este comando de PowerShell y dime la salida: 1..4 | ForEach-Object { Write-Output (\"tick \" + $_) }" },
        .{ .name = "target", .field_type = .string, .required = false, .value = null },
    };
    const pt = planner.PlannedTask{
        .id = "t1",
        .task_type = .ejecutar,
        .department = "ops",
        .description = "Ejecutar exactamente este comando de PowerShell y dime la salida: 1..4 | ForEach-Object { Write-Output (\"tick \" + $_) }",
        .contract_fields = fields[0..],
        .depends_on = &.{},
    };
    const artifacts = [_]worker_backend.Artifact{
        .{ .path = "command", .content = "powershell -Command \"1..4 | ForEach-Object { Write-Output ('tick ' + $_) }\"" },
        .{ .path = "target", .content = "powershell" },
    };
    var parsed = (try resolveTaskCommand(allocator, pt, &artifacts)) orelse return error.TestUnexpectedResult;
    defer parsed.deinit();
    try std.testing.expectEqualStrings("powershell", parsed.exe);
    try std.testing.expectEqual(@as(usize, 2), parsed.args.len);
    try std.testing.expectEqualStrings("-Command", parsed.args[0]);
}

