test "B1: commandToParsed rechaza un REPL pelado (falso éxito #527)" {
    const allocator = std.testing.allocator;
    // `powershell` sin args: banner + exit 0 sin ejecutar nada. Mejor null
    // (la orden falla honesta) que un PASS sobre un banner.
    try std.testing.expect((try commandToParsed(allocator, "powershell")) == null);
    try std.testing.expect((try commandToParsed(allocator, "bash")) == null);
    // SEC2 conserva #527: la política de intérpretes no lo relaja.
    for ([_][]const u8{ "pwsh", "cmd", "python", "node", "py", "ruby", "perl", "sh" }) |exe| {
        try std.testing.expect((try commandToParsed(allocator, exe)) == null);
    }
    // Pero CON args sí es un comando legítimo.
    var parsed = (try commandToParsed(allocator, "bash -c \"echo ok\"")) orelse
        return error.TestUnexpectedResult;
    defer parsed.deinit();
    try std.testing.expectEqualStrings("bash", parsed.exe);
}

