test "B1: governedExecuteRawAtCwd no ejecuta un REPL sin comando" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.permission_config.mode = .bypass;
    sa.plan_approved = true;
    // Spawn trampa: si se invocara, el falso éxito siguió vivo.
    sa.executor_spawn_fn = struct {
        fn f(a: std.mem.Allocator, _: []const u8, _: []const []const u8, _: []const u8, _: u32, _: usize, _: ?executor.StreamSink, _: ?*anyopaque, _: []const u8) executor.ExecutorError!executor.RunResult {
            return .{ .exit_code = 0, .stdout = try a.dupe(u8, "BANNER"), .stderr = try a.dupe(u8, "") };
        }
    }.f;

    var root_buf: [4096]u8 = undefined;
    const cwd = workspace.effectiveRoot(&root_buf);
    var outputs = std.ArrayList(WorkerOutput).empty;
    defer {
        for (outputs.items) |o| {
            allocator.free(o.worker_id);
            allocator.free(o.stream);
            if (o.task_id.len > 0) allocator.free(o.task_id);
            allocator.free(o.text);
        }
        outputs.deinit(allocator);
    }
    var pending = std.ArrayList(ApprovalRequest).empty;
    defer {
        for (pending.items) |r| r.deinit(allocator);
        pending.deinit(allocator);
    }
    const outcome = try sa.governedExecuteRawAtCwd("powershell", &.{}, "t1", &outputs, &pending, cwd);
    defer allocator.free(outcome.stderr);
    // NO corrió: el motor lo dice, no lo esconde detrás de un banner exit 0.
    try std.testing.expect(!outcome.ran);
    try std.testing.expect(std.mem.indexOf(u8, outcome.stderr, "shell interactivo") != null);
    // SEC2: tampoco pide aprobación para un comando que no existe.
    try std.testing.expectEqual(@as(usize, 0), pending.items.len);
}

test "SEC2 wrapInShell output is inline PowerShell: approval per command even after plan approval" {
    const allocator = std.testing.allocator;
    var parsed = (try commandToParsed(allocator, "ls -lS | head -3")) orelse return error.TestUnexpectedResult;
    defer parsed.deinit();
