    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.permission_config.mode = .bypass;
    sa.plan_approved = true;
    const Spawn = struct {
        var calls: usize = 0;
        fn f(a: std.mem.Allocator, _: []const u8, _: []const []const u8, _: []const u8, _: u32, _: usize, _: ?executor.StreamSink, _: ?*anyopaque, _: []const u8) executor.ExecutorError!executor.RunResult {
            calls += 1;
            return .{ .exit_code = 0, .stdout = try a.dupe(u8, "ok"), .stderr = try a.dupe(u8, "") };
        }
    };
    sa.executor_spawn_fn = Spawn.f;
    Spawn.calls = 0;
    var root_buf: [4096]u8 = undefined;
    const cwd = workspace.effectiveRoot(&root_buf);
    var outputs = std.ArrayList(WorkerOutput).empty;
    defer {
        for (outputs.items) |o| {
            allocator.free(o.worker_id);
            allocator.free(o.stream);
            if (o.task_id.len > 0) allocator.free(o.task_id);
            allocator.free(o.text);
        }
        outputs.deinit(allocator);
    }
    var pending = std.ArrayList(ApprovalRequest).empty;
    defer {
        for (pending.items) |r| r.deinit(allocator);
        pending.deinit(allocator);
    }
    const outcome = try sa.governedExecuteRawAtCwd(parsed.exe, parsed.args, "t-wrap", &outputs, &pending, cwd);
    defer allocator.free(outcome.stderr);
    if (outcome.stdout) |text| allocator.free(text);
    try std.testing.expect(!outcome.ran and outcome.needs_approval);
    try std.testing.expectEqual(@as(usize, 0), Spawn.calls);
    try std.testing.expectEqual(@as(usize, 1), pending.items.len);
    try std.testing.expectEqualStrings("shell_command", pending.items[0].command_prefix.?);
}

test "SEC2 MCP-origin order cannot run commands on a plan confirmed over MCP" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.permission_config.mode = .bypass;
    sa.plan_approved = true;
    const Spawn = struct {
        var calls: usize = 0;
        fn f(a: std.mem.Allocator, _: []const u8, _: []const []const u8, _: []const u8, _: u32, _: usize, _: ?executor.StreamSink, _: ?*anyopaque, _: []const u8) executor.ExecutorError!executor.RunResult {
            calls += 1;
            return .{ .exit_code = 0, .stdout = try a.dupe(u8, "ok"), .stderr = try a.dupe(u8, "") };
        }
    };
    sa.executor_spawn_fn = Spawn.f;
    var root_buf: [4096]u8 = undefined;
    const cwd = workspace.effectiveRoot(&root_buf);
    var outputs = std.ArrayList(WorkerOutput).empty;
    defer {
        for (outputs.items) |o| {
            allocator.free(o.worker_id);
            allocator.free(o.stream);
            if (o.task_id.len > 0) allocator.free(o.task_id);
            allocator.free(o.text);
        }
        outputs.deinit(allocator);
    }
    var pending = std.ArrayList(ApprovalRequest).empty;
    defer {
        for (pending.items) |r| r.deinit(allocator);
        pending.deinit(allocator);
    }
    // Control: origen local + plan aprobado ejecuta `echo` directamente.
    Spawn.calls = 0;
    const local = try sa.governedExecuteRawAtCwd("echo", &.{"hola"}, "t-local", &outputs, &pending, cwd);
    defer allocator.free(local.stderr);
    if (local.stdout) |text| allocator.free(text);
    try std.testing.expect(local.ran);
    try std.testing.expectEqual(@as(usize, 1), Spawn.calls);
    try std.testing.expectEqual(@as(usize, 0), pending.items.len);
    // Mismo plan y mismo modo, pero iniciado por MCP: tarjeta exacta, sin spawn.
    sa.order_origin = .mcp;
    Spawn.calls = 0;
    const mcp = try sa.governedExecuteRawAtCwd("echo", &.{"hola"}, "t-mcp", &outputs, &pending, cwd);
    defer allocator.free(mcp.stderr);
    if (mcp.stdout) |text| allocator.free(text);
    try std.testing.expect(!mcp.ran and mcp.needs_approval);
    try std.testing.expectEqual(@as(usize, 0), Spawn.calls);
    try std.testing.expectEqual(@as(usize, 1), pending.items.len);
    try std.testing.expectEqualStrings("shell_command", pending.items[0].command_prefix.?);
    // Las consultas de version acotadas siguen siendo automaticas.
    const version = try sa.governedExecuteRawAtCwd("git", &.{"--version"}, "t-version", &outputs, &pending, cwd);
    defer allocator.free(version.stderr);
    if (version.stdout) |text| allocator.free(text);
    try std.testing.expect(version.ran);
}

test "B1: `shell -Command \"script con comillas\"` conserva el script entero (orden #529)" {
    const allocator = std.testing.allocator;
    // El worker escribe el comando como lo escribiría un humano: las comillas
    // EXTERNAS son del shell, las INTERNAS pertenecen al script. Trocear por
    // comillas fragmentaba el script → MissingEndParenthesisInExpression.
    var parsed = (try commandToParsed(allocator, "powershell -Command \"1..4 | ForEach-Object { Write-Output (\"tick \" + $_); Start-Sleep -Milliseconds 900 }\"")) orelse
        return error.TestUnexpectedResult;
    defer parsed.deinit();
    try std.testing.expectEqualStrings("powershell", parsed.exe);
    try std.testing.expectEqual(@as(usize, 2), parsed.args.len);
    try std.testing.expectEqualStrings("-Command", parsed.args[0]);
    // El script llega ENTERO con sus comillas internas intactas, precedido
    // de la guarda EA=Stop que hace que los errores den exit≠0.
    try std.testing.expect(std.mem.startsWith(u8, parsed.args[1], "$ErrorActionPreference='Stop'; "));
    try std.testing.expect(std.mem.indexOf(u8, parsed.args[1], "Write-Output (\"tick \" + $_)") != null);
    try std.testing.expect(std.mem.indexOf(u8, parsed.args[1], "Start-Sleep -Milliseconds 900") != null);
}

test "B1: escapes del quoting exterior se deshacen al strippear (orden #529 real)" {
    const allocator = std.testing.allocator;
    // El modelo escribió \" para escapar comillas dentro de las comillas
    // externas. Al quitarlas hay que deshacer el escape: si pasan literales,
    // PowerShell los toma como `\tick` → CommandNotFoundException.
    var parsed = (try commandToParsed(allocator, "powershell -Command \"1..4 | ForEach-Object { Write-Output (\\\"tick \\\" + $_) }\"")) orelse
        return error.TestUnexpectedResult;
    defer parsed.deinit();
