test "E3.35: -EncodedCommand queda inválido por la guarda EA=Stop (fail-closed)" {
    const allocator = std.testing.allocator;
    // En el path del worker, -EncodedCommand es script-flag: el b64 se
    // prepende con `$ErrorActionPreference='Stop'; `, que NO es base64 —
