    try std.testing.expectEqualStrings("powershell", parsed.exe);
    const last = parsed.args[parsed.args.len - 1];
    try std.testing.expect(std.mem.startsWith(u8, last, "$ErrorActionPreference='Stop'; "));
    const display = try executor.renderCommandLine(allocator, parsed.exe, parsed.args);
    defer allocator.free(display);
    try std.testing.expect(std.mem.indexOf(u8, display, "-EncodedCommand") != null);
}

