// ── pruebas ─────────────────────────────────────────────────────

fn tareaFixture(a: std.mem.Allocator, id: []const u8, tt: model_router.TaskType, deps: []const []const u8) !planner.PlannedTask {
    const campos = try a.alloc(planner.ContractField, 1);
    campos[0] = .{ .name = try a.dupe(u8, "source"), .field_type = .string, .required = true };
    const d = try a.alloc([]const u8, deps.len);
    for (deps, 0..) |dep, i| d[i] = try a.dupe(u8, dep);
    return .{
        .id = try a.dupe(u8, id),
        .task_type = tt,
        .department = try a.dupe(u8, if (tt == .auditar) "auditoria" else "programacion"),
        .description = try a.dupe(u8, "fixture"),
        .contract_fields = campos,
        .depends_on = d,
    };
}

/// La forma exacta del plan de la #746: dos `programar` de exploración y
/// lectura, t2 detrás de t1, y ninguna tarea que audite.
const PlanSinAuditarPlanner = struct {
    fn backend(self: *@This()) planner.PlannerBackend {
        return .{ .ptr = self, .planFn = plan, .deinitFn = deinit };
    }
    fn deinit(_: *anyopaque) void {}
    fn plan(_: *anyopaque, a: std.mem.Allocator, _: []const u8, _: []const planner.ClarificationAnswer, _: ?[]const u8) planner.PlannerError!planner.Plan {
        const tareas = try a.alloc(planner.PlannedTask, 2);
        tareas[0] = tareaFixture(a, "t1", .programar, &.{}) catch return error.OutOfMemory;
        tareas[1] = tareaFixture(a, "t2", .programar, &.{"t1"}) catch return error.OutOfMemory;
        return .{
            .allocator = a,
            .understanding = try a.dupe(u8, "explorar y leer la evidencia"),
            .questions = try a.alloc(planner.ClarificationQuestion, 0),
            .tasks = tareas,
        };
    }
};

test "E-101: una orden de auditoría sin tarea auditar sale del superagente terminando en auditar" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var pp = PlanSinAuditarPlanner{};
    const pb = pp.backend();
    defer pb.deinit();

    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.setEventConn(runtime, 0);
    // El arranque real de las órdenes r4 (#733-#752).
    var outcome = try sa.processOrder("auditoria-motor", "Eres un AUDITOR INDEPENDIENTE ejecutándote como orden real dentro de DevAgents. Declara tu modelo al inicio del informe.", &.{}, pb, null, null);
    defer outcome.deinit();

    try std.testing.expectEqual(@as(usize, 3), outcome.plan.tasks.len);
    const ultima = outcome.plan.tasks[2];
    try std.testing.expectEqual(model_router.TaskType.auditar, ultima.task_type);
    try std.testing.expectEqualStrings("auditoria", ultima.department);
    // Depende de la hoja (t2), que a su vez espera a t1: audita todo el plan.
    try std.testing.expectEqual(@as(usize, 1), ultima.depends_on.len);
    try std.testing.expectEqualStrings("t2", ultima.depends_on[0]);
    try std.testing.expectEqualStrings("verdict", ultima.contract_fields[0].name);
    // Persistida como tarea de verdad y visible en la traza.
    try std.testing.expectEqual(@as(i32, 3), try countRows(runtime, "tasks"));
    try std.testing.expectEqual(@as(i32, 1), try countRows(runtime, "tasks WHERE task_type = 'auditar'"));
    try std.testing.expectEqual(@as(i32, 1), try countRows(runtime, "events WHERE kind LIKE 'plan_audit_enf%'"));
}

