test "E-101: un plan que ya audita no se toca, y el id añadido nunca pisa uno existente" {
    const a = std.testing.allocator;
    {
        const tareas = try a.alloc(planner.PlannedTask, 2);
        tareas[0] = try tareaFixture(a, "t1", .programar, &.{});
        tareas[1] = try tareaFixture(a, "t2", .auditar, &.{"t1"});
        var plan = planner.Plan{ .allocator = a, .understanding = try a.dupe(u8, "x"), .questions = try a.alloc(planner.ClarificationQuestion, 0), .tasks = tareas };
        defer plan.deinit();
        try std.testing.expect((try aseguraAuditoriaTerminal(&plan)) == null);
        try std.testing.expectEqual(@as(usize, 2), plan.tasks.len);
    }
    {
        const tareas = try a.alloc(planner.PlannedTask, 2);
        tareas[0] = try tareaFixture(a, "t-auditoria", .programar, &.{});
        tareas[1] = try tareaFixture(a, "t9", .investigar, &.{});
        var plan = planner.Plan{ .allocator = a, .understanding = try a.dupe(u8, "x"), .questions = try a.alloc(planner.ClarificationQuestion, 0), .tasks = tareas };
        defer plan.deinit();
        const nueva = (try aseguraAuditoriaTerminal(&plan)).?;
        try std.testing.expectEqualStrings("t-auditoria-1", nueva);
        // Dos hojas independientes: la auditoría espera a las dos.
        try std.testing.expectEqual(@as(usize, 2), plan.tasks[2].depends_on.len);
    }
}

