test "CK-COMP-002 dispatch reloads the task session from runtime ledger on order resume" {
    if (@import("builtin").os.tag != .windows) return @import("platform.zig").skip("T9: CLI externa (Codex, OpenCode, Claude, Gemini) no disponible en Linux en esta version (ExternalCliUnavailableOnLinux en external_cli_policy)");
    const a = std.testing.allocator;
    const sessions = @import("external_session.zig");
    const Stub = struct {
        calls: usize = 0,
        saw_resume: bool = false,
        fn run(raw: ?*anyopaque, alloc: std.mem.Allocator, io: std.Io, task: planner.PlannedTask, req: external_agents.RunRequest, sb: sandbox.Sandbox) anyerror!external_agents.RunOutcome {
            const self: *@This() = @ptrCast(@alignCast(raw.?));
            self.calls += 1;
            const sink = req.session_sink orelse return error.MissingSessionSink;
            if (req.resume_session) |id| {
                try std.testing.expectEqualStrings("saved-123", id);
                self.saw_resume = true;
                try sink.call(.resumed, id, "");
            }
            try sink.call(.saved, "saved-123", "");
            var fake = FakeExternalRun{};
            return FakeExternalRun.run(&fake, alloc, io, task, req, sb);
        }
    };
    var threaded = std.Io.Threaded.init(a, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const wt = try tmp.dir.realPathFileAlloc(io, ".", a);
    defer a.free(wt);
    workspace.setOrderRootOverride(wt);
    defer workspace.setOrderRootOverride(null);
    for ([_][]const u8{ "claude-code", "codex", "opencode" }) |cli| {
        var runtime = try openRuntime(a);
        defer runtime.close();
        var sa = Superagent.init(a, runtime, null, NoopMemory.backend(), 1);
        sa.setEventConn(runtime, 7);
        var stub = Stub{};
        sa.external_run_fn = Stub.run;
        sa.external_run_ctx = &stub;
        var outcome = OrderOutcome{
            .allocator = a,
            .order_id = 7,
            .plan_id = 0,
            .status = .planned,
            .plan = .{ .allocator = a, .understanding = "", .questions = &.{}, .tasks = &.{} },
            .assignments = &.{},
            .discovery_needed = &.{},
            .discovery_missing = &.{},
            .discovery_needed_resources = &.{},
        };
        var ctx = Superagent.FanoutContext{
            .mutex = .init(),
            .completed = 0,
            .failed = 0,
            .integrated = 0,
            .rejected = 0,
            .outputs = .empty,
            .pending = .empty,
            .saved = .empty,
            .saved_owner = .empty,
            .results = .empty,
            .sa = &sa,
            .outcome = &outcome,
            .llm_fn = null,
            .llm_ctx = null,
            .catalog_path = null,
            .needed_resources = &.{},
        };
        var task: planner.PlannedTask = .{ .id = "t1", .task_type = .programar_c, .department = "programacion", .description = "produce code", .contract_fields = &.{}, .depends_on = &.{} };
        const meta = external_agents.metaForCliId(cli).?;
        const key: sessions.Key = .{ .order_id = 7, .task_id = task.id, .cli = cli, .model = "m", .worktree = wt };
        {
            var result = Superagent.dispatchExternalAgent(&ctx, a, task, meta, "agent:fixture", "m");
            defer result.deinit(a);
            try std.testing.expect(result.success);
            try std.testing.expect(!stub.saw_resume);
        }
        const saved = (try sessions.load(a, runtime, key)).?;
        defer a.free(saved);
        try std.testing.expectEqualStrings("saved-123", saved);
        sa.resume_checkpoint = .{ .restored = &.{}, .interrupted = &.{"t1"} };
        {
            var result = Superagent.dispatchExternalAgent(&ctx, a, task, meta, "agent:fixture", "m");
            defer result.deinit(a);
            try std.testing.expect(result.success);
            try std.testing.expect(stub.saw_resume);
        }
        stub.saw_resume = false;
        task.id = "t2";
        {
            var result = Superagent.dispatchExternalAgent(&ctx, a, task, meta, "agent:fixture", "m");
            defer result.deinit(a);
            try std.testing.expect(result.success);
            try std.testing.expect(!stub.saw_resume);
        }
        const q = try runtime.prepare("SELECT COUNT(*) FROM events WHERE kind='external_session_restart' AND json_extract(payload_json,'$.task_id')='t2' AND payload_json LIKE '%sin sesion compatible con la politica de herencia%'");
        defer runtime.finalize(q);
        try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(q));
        try std.testing.expectEqual(@as(i64, 1), db.c.sqlite3_column_int64(q, 0));
        const visible = try runtime.prepare("SELECT COUNT(*) FROM events WHERE kind='external_agent_event' AND payload_json LIKE '%external_session_resumed%' AND payload_json LIKE '%saved-123%'");
        defer runtime.finalize(visible);
        try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(visible));
        try std.testing.expectEqual(@as(i64, 1), db.c.sqlite3_column_int64(visible, 0));
        try std.testing.expectEqual(@as(usize, 3), stub.calls);
    }
}

/// RunFn de prueba: simula una corrida de agente externo sin proceso real —
/// devuelve un RunOutcome con un artefacto y registra lo que el superagente
/// le pasó (permisos, sink, topes efectivos) para las aserciones.
const FakeExternalRun = struct {
    calls: usize = 0,
    turns: u32 = 1,
    duration_ms: u64 = 50,
    fail: bool = false,
    /// código de salida y detalle que devuelve la corrida fallida
    /// (un CLI real sale con código distinto de cero y deja stderr).
    fail_exit_code: ?u8 = 1,
    fail_detail: []const u8 = "error: login required (fixture)",
    saw_permission_fn: bool = false,
    saw_event_sink: bool = false,
    saw_opencode_free: bool = false,
    last_timeout_ms: u64 = 0,
    last_max_turns: u32 = 0,

    fn run(ctx: ?*anyopaque, a: std.mem.Allocator, io: std.Io, task: planner.PlannedTask, req: external_agents.RunRequest, sb: sandbox.Sandbox) anyerror!external_agents.RunOutcome {
        _ = io;
        _ = task;
        _ = sb;
        const self: *@This() = @ptrCast(@alignCast(ctx.?));
        self.calls += 1;
        self.saw_permission_fn = self.saw_permission_fn or req.permission_fn != null;
        self.saw_event_sink = self.saw_event_sink or req.event_sink != null;
        self.saw_opencode_free = self.saw_opencode_free or (std.mem.eql(u8, req.meta.cli_id, "opencode") and
            req.zero_cost and
            std.mem.eql(u8, req.model orelse "", "opencode/x-free") and
            std.mem.eql(u8, req.exe_path orelse "", "C:/fixture/opencode.exe"));
        self.last_timeout_ms = req.timeout_ms;
        self.last_max_turns = req.max_turns;
        const arts = try a.alloc(worker_backend.Artifact, 1);
        arts[0] = .{
            .path = try a.dupe(u8, "entrega.py"),
            .content = try a.dupe(u8, "print('hecho por el agente externo')\n"),
        };
        return .{
            .success = !self.fail,
            .timed_out = false,
            .turn_limited = false,
            .exit_code = if (self.fail) self.fail_exit_code else 0,
            .duration_ms = self.duration_ms,
            .turns = self.turns,
            .agent_version = try a.dupe(u8, "0.0.0-test"),
            .argv_censored = try a.dupe(u8, "agente --test"),
            .declaration = try a.dupe(u8, "declaracion del agente externo"),
            .detail = try a.dupe(u8, if (self.fail) self.fail_detail else "salida acotada del agente"),
            .artifacts = arts,
        };
    }
};

/// QA-B 2c: CLI simulada que agota la cuota con la primera cuenta y termina
/// con la segunda; apunta qué carpeta de cuenta (CLAUDE_CONFIG_DIR) recibió.
const AccountRotationFake = struct {
    calls: usize = 0,
    first_home: [64]u8 = undefined,
    first_len: usize = 0,
    saw_second: bool = false,

    fn run(ctx: ?*anyopaque, a: std.mem.Allocator, _: std.Io, _: planner.PlannedTask, req: external_agents.RunRequest, _: sandbox.Sandbox) anyerror!external_agents.RunOutcome {
        const self: *@This() = @ptrCast(@alignCast(ctx.?));
        self.calls += 1;
        const home = if (req.environ_map) |env| env.get("CLAUDE_CONFIG_DIR") orelse "" else "";
        if (self.calls == 1) {
            self.first_len = @min(home.len, self.first_home.len);
            @memcpy(self.first_home[0..self.first_len], home[0..self.first_len]);
        }
        if (std.mem.endsWith(u8, home, "claude-code-2")) self.saw_second = true;
        const exhausted = std.mem.endsWith(u8, home, "claude-code-1");
        const arts = try a.alloc(worker_backend.Artifact, 1);
        arts[0] = .{ .path = try a.dupe(u8, "main.c"), .content = try a.dupe(u8, "int main(void){return 0;}\n") };
        return .{
            .success = !exhausted,
            .agent_version = try a.dupe(u8, "0.0.0-test"),
            .argv_censored = try a.dupe(u8, "claude --test"),
            .declaration = try a.dupe(u8, if (exhausted) "" else "hecho"),
            .detail = try a.dupe(u8, if (exhausted) "Claude AI usage limit reached" else ""),
            .artifacts = arts,
        };
    }
};

