    try std.testing.expectEqualStrings("1.18.25", s.get("cli_version").?.string);
    try std.testing.expectEqualStrings("C:/fixture/opencode.exe", s.get("cli_path").?.string);
    try std.testing.expectEqualStrings("opencode", s.get("cli").?.string);
}

test "E5.08: pin agent:* despacha por la rama externa con eventos y usage subscription" {
    if (@import("builtin").os.tag != .windows) return @import("platform.zig").skip("T9: CLI externa (Codex, OpenCode, Claude, Gemini) no disponible en Linux en esta version (ExternalCliUnavailableOnLinux en external_cli_policy)");
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var catalog = try db.Connection.open(allocator, ":memory:");
    defer catalog.close();
    var ledger = try db.Connection.open(allocator, ":memory:");
    defer ledger.close();
    const migrator = db.Migrator.init(allocator);
    try migrator.migrate(catalog, &db.catalog_schema);
    try migrator.migrate(ledger, &db.ledger_schema);
    try seedCatalog(catalog);
    var router = model_router.Router.init(allocator, catalog, ledger, 1);
    try router.seedInitialScores();

    var mp = planner.MockPlanner.init(allocator);
    const pb = mp.backend();
    defer pb.deinit();

    var sa = Superagent.init(allocator, runtime, &router, NoopMemory.backend(), 1);
    // Ejecutor = agente externo (suscripción); auditor = catálogo de OTRO
    // fabricante (opencode ≠ openai) para que la auditoría cruzada lo admita.
    sa.setExecForcedModel("agent:codex", "codex");
    sa.setAuditForcedModel("OpenCode", "gemini-flash-free");
    var fake = FakeExternalRun{};
    sa.external_run_fn = FakeExternalRun.run;
    sa.external_run_ctx = &fake;

    var outcome = try sa.processOrder("proj-1", "construye una calculadora CLI en C con tests", &.{}, pb, null, null);
    defer outcome.deinit();
    sa.permission_config.mode = .bypass;
    sa.executor_spawn_fn = testExecutorSpawnOk;
    sa.setEventConn(runtime, outcome.order_id);

    var llm_marker: u8 = 0;
    var dr = try sa.approveAndDispatch(&outcome, fixtureSuccessfulLlm, &llm_marker, null);
    defer dr.deinit(allocator);

    // El agente externo corrió las tareas productoras — NUNCA por el LLM
    // nativo. El sink de eventos y el puente de permisos viajaron en la
    // petición con los topes por defecto de la fila.
    try std.testing.expect(fake.calls >= 1);
    try std.testing.expect(fake.saw_event_sink);
    try std.testing.expect(fake.saw_permission_fn);
    const default_limits = external_agents.Limits{};
    try std.testing.expectEqual(default_limits.task_max_turns, fake.last_max_turns);
    try std.testing.expectEqual(default_limits.task_timeout_ms, fake.last_timeout_ms);

    // Ledger: external_agent_started + external_agent_finished con el cli.
    {
        const stmt = try runtime.prepare("SELECT COUNT(*) FROM events WHERE kind='external_agent_started'");
        defer runtime.finalize(stmt);
        try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
        try std.testing.expect(db.c.sqlite3_column_int64(stmt, 0) >= 1);
    }
    {
        const stmt = try runtime.prepare("SELECT COUNT(*) FROM events WHERE kind='external_agent_finished' AND payload_json LIKE '%codex%'");
        defer runtime.finalize(stmt);
        try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
        try std.testing.expect(db.c.sqlite3_column_int64(stmt, 0) >= 1);
    }
    // Contable: usage_records categoría subscription — NO api (la escalada de
    // pago no debe contarla como llamada API de cobro).
    {
        const stmt = try runtime.prepare("SELECT cost_category, provider, model FROM usage_records WHERE provider='agent:codex'");
        defer runtime.finalize(stmt);
        try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
        const cat_ptr = db.c.sqlite3_column_text(stmt, 0) orelse return error.TestUnexpectedNull;
        try std.testing.expectEqualStrings("subscription", cat_ptr[0..std.mem.len(cat_ptr)]);
        const model_ptr = db.c.sqlite3_column_text(stmt, 2) orelse return error.TestUnexpectedNull;
        try std.testing.expectEqualStrings("codex", model_ptr[0..std.mem.len(model_ptr)]);
    }
}

