test "E5.08: auditor de catálogo excluido por fabricante del productor agente" {
    // El productor fue agent:claude-code (Anthropic). NINGÚN modelo del
    // catálogo de Anthropic/Claude puede auditarlo — el control negativo de
    // la fila: sin la exclusión el auditor saldría del mismo fabricante.
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var catalog = try db.Connection.open(allocator, ":memory:");
    defer catalog.close();
    const migrator = db.Migrator.init(allocator);
    try migrator.migrate(catalog, &db.catalog_schema);
    try catalog.exec("INSERT INTO providers (id,name,base_url,api_style,is_free_tier) VALUES (1,'Claude','x','anthropic',1)");
    try catalog.exec("INSERT INTO providers (id,name,base_url,api_style,is_free_tier) VALUES (2,'GPT','x','openai',1)");
    try catalog.exec("INSERT INTO api_keys (id,provider_id,label,key_ciphertext,quota_limit,quota_used,status) VALUES (1,1,'k',x'00',100,0,'active')");
    try catalog.exec("INSERT INTO api_keys (id,provider_id,label,key_ciphertext,quota_limit,quota_used,status) VALUES (2,2,'k',x'00',100,0,'active')");
    try catalog.exec("INSERT INTO models (id,provider_id,model_name,context_window,is_free,latency_p50_ms,available) VALUES (1,1,'claude-sonnet',128000,1,800,1)");
    try catalog.exec("INSERT INTO models (id,provider_id,model_name,context_window,is_free,latency_p50_ms,available) VALUES (2,2,'gpt-5',128000,1,900,1)");
    var router = model_router.Router.init(allocator, catalog, null, 1);
    try router.seedInitialScores();
    var sa = Superagent.init(allocator, runtime, &router, NoopMemory.backend(), 1);
    sa.setExecForcedModel("agent:claude-code", "claude-code");

    const pt1 = planner.PlannedTask{ .id = "t1", .task_type = .programar, .department = "programacion", .description = "x", .contract_fields = &.{}, .depends_on = &.{} };
    var dep = [_][]const u8{"t1"};
    const pt2 = planner.PlannedTask{ .id = "t2", .task_type = .auditar, .department = "auditoria", .description = "x", .contract_fields = &.{}, .depends_on = dep[0..] };
    const tasks = [_]planner.PlannedTask{ pt1, pt2 };

    const a1 = try sa.assignModel(pt1, &tasks, &.{});
    defer a1.deinit(allocator);
    try std.testing.expect(a1.assigned);
    try std.testing.expectEqualStrings("agent:claude-code", a1.provider_name);

    const a2 = try sa.assignModel(pt2, &tasks, &.{a1});
    defer a2.deinit(allocator);
    try std.testing.expect(a2.assigned);
    // Claude (Anthropic) quedó excluido por fabricante — el auditor es GPT.
    try std.testing.expectEqualStrings("gpt-5", a2.model_name);
}

