test "CK-CAB-024: ejecutor CLI fijado que falla no cae a otro proveedor y el motivo es honesto" {
    // Criterio 1: con `agent:claude-code` fijado y la corrida fallando, NO hay
    // provider_fallback hacia otro proveedor; la tarea queda fallida con el
    // motivo real (código de salida + primera línea) en su evento. Reproduce la
    // orden #890: Claude Code salió con código 1 en 2,8 s y la tarea la terminó
    // Cohere en silencio.
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var catalog = try db.Connection.open(allocator, ":memory:");
    defer catalog.close();
    const migrator = db.Migrator.init(allocator);
    try migrator.migrate(catalog, &db.catalog_schema);
    try seedCatalog(catalog);
    var router = model_router.Router.init(allocator, catalog, null, 1);
    try router.seedInitialScores();

    var mp = planner.MockPlanner.init(allocator);
    const pb = mp.backend();
    defer pb.deinit();

    const Counter = struct {
        calls: usize = 0,
        fn call(ctx: *anyopaque, _: []const u8, _: []const u8) []const u8 {
            const self: *@This() = @ptrCast(@alignCast(ctx));
            self.calls += 1;
            return "[{\"field\":\"filename\",\"content\":\"fixture.c\"},{\"field\":\"source\",\"content\":\"int main(){return 0;}\"},{\"field\":\"exit_code\",\"content\":\"0\"},{\"field\":\"tests_passed\",\"content\":\"1\"},{\"field\":\"verdict\",\"content\":\"PASS\"}]";
        }
    };
    var counter = Counter{};

    var sa = Superagent.init(allocator, runtime, &router, NoopMemory.backend(), 1);
    sa.setExecForcedModel("agent:claude-code", "claude-code");
    sa.setAuditForcedModel("OpenCode", "gemini-flash-free");
    var fake = FakeExternalRun{ .fail = true };
    sa.external_run_fn = FakeExternalRun.run;
    sa.external_run_ctx = &fake;

    var outcome = try sa.processOrder("proj-1", "construye una calculadora CLI en C con tests", &.{}, pb, null, null);
    defer outcome.deinit();
    sa.permission_config.mode = .bypass;
    sa.executor_spawn_fn = testExecutorSpawnOk;
    sa.setEventConn(runtime, outcome.order_id);

    var dr = try sa.approveAndDispatch(&outcome, Counter.call, &counter, null);
    defer dr.deinit(allocator);

    // El ejecutor fijado corrió UNA vez y falló.
    try std.testing.expectEqual(@as(usize, 1), fake.calls);
    // NINGÚN proveedor de respaldo hizo la tarea por el fijado.
    try std.testing.expectEqual(@as(usize, 0), counter.calls);
    {
        const stmt = try runtime.prepare("SELECT COUNT(*) FROM events WHERE kind='provider_fallback'");
        defer runtime.finalize(stmt);
        try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
        try std.testing.expectEqual(@as(i64, 0), db.c.sqlite3_column_int64(stmt, 0));
    }
    // La tarea fallida nombra al ejecutor fijado y la política.
    {
        const stmt = try runtime.prepare("SELECT payload_json FROM events WHERE kind='task_failed' AND payload_json LIKE '%\"task_id\":\"t1\"%'");
        defer runtime.finalize(stmt);
        try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
        const payload = std.mem.span(db.c.sqlite3_column_text(stmt, 0).?);
        try std.testing.expect(std.mem.indexOf(u8, payload, "Claude Code fall") != null);
        try std.testing.expect(std.mem.indexOf(u8, payload, "porque lo fijaste") != null);
        // Motivo honesto: código de salida real + primera línea del detalle.
        try std.testing.expect(std.mem.indexOf(u8, payload, "salida 1: error: login required (fixture)") != null);
    }
    // El cierre honesto: sin tareas completadas no se finge un "listo".
    {
        const stmt = try runtime.prepare("SELECT payload_json FROM events WHERE kind='agent_message' ORDER BY id DESC LIMIT 1");
        defer runtime.finalize(stmt);
        try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
        const payload = std.mem.span(db.c.sqlite3_column_text(stmt, 0).?);
        try std.testing.expect(std.mem.indexOf(u8, payload, "No pude completar la orden") != null);
    }
}

// ── D-C1 (E5.11): modo agéntico por-tarea ────────────────────────────────────

/// Inserta una fila de discovery_snapshots_v2 con la casilla cap_tool_calls
/// parametrizada (el resto de capacidades queda 'unknown'/'not_probed').
fn insertAgenticMatrixRow(catalog: db.Connection, provider: []const u8, model_id: []const u8, status: []const u8, provenance: []const u8, updated_at: []const u8) !void {
    const stmt = try catalog.prepare(
        \\INSERT OR REPLACE INTO discovery_snapshots_v2 (
        \\  provider, model_id, api_style, wire_protocol, endpoint_url,
        \\  cap_chat_status, cap_chat_provenance,
        \\  cap_streaming_status, cap_streaming_provenance,
        \\  cap_tool_calls_status, cap_tool_calls_provenance,
        \\  cap_structured_output_status, cap_structured_output_provenance,
        \\  cap_vision_status, cap_vision_provenance,
        \\  cap_reasoning_status, cap_reasoning_provenance,
        \\  cap_audio_input_status, cap_audio_input_provenance,
        \\  cap_audio_output_status, cap_audio_output_provenance,
        \\  cap_embeddings_status, cap_embeddings_provenance,
        \\  cost_category, auth_required,
        \\  metadata_source, metadata_updated_at, metadata_payload_type, health_state
        \\) VALUES (?,?,'test','test','test://endpoint',
        \\  'unknown','not_probed','unknown','not_probed', ?,?,
        \\  'unknown','not_probed','unknown','not_probed','unknown','not_probed',
        \\  'unknown','not_probed','unknown','not_probed','unknown','not_probed',
        \\  'free',1,'test',?,'live_probe','unknown')
    );
    defer catalog.finalize(stmt);
    try db.bindText(stmt, 1, provider);
    try db.bindText(stmt, 2, model_id);
    try db.bindText(stmt, 3, status);
    try db.bindText(stmt, 4, provenance);
    try db.bindText(stmt, 5, updated_at);
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_DONE) return error.ExecFailed;
}

test "D-C1 GATE: el modo agéntico solo se abre con cap_tool_calls medida en vivo" {
    const allocator = std.testing.allocator;
    var catalog = try db.Connection.open(allocator, ":memory:");
    defer catalog.close();
    const migrator = db.Migrator.init(allocator);
    try migrator.migrate(catalog, &db.catalog_schema);
    const now: i64 = 1_800_000_000;

    // Capacidad medida en vivo → modo agéntico.
    try insertAgenticMatrixRow(catalog, "OpenCode", "deepseek-coder-free", "yes", "live_probe", "1800000000");
    const yes = decideTaskToolMode(catalog, now, .programar, "OpenCode", "deepseek-coder-free");
    try std.testing.expectEqual(TaskToolMode.agentic, yes.mode);
    try std.testing.expect(yes.motivo == null);

    // Los ocho tipos elegibles pasan la puerta con evidencia viva.
    inline for (.{ .programar, .programar_c, .programar_cpp, .programar_zig, .testear, .documentar, .ui, .disenar }) |tt| {
        try std.testing.expectEqual(TaskToolMode.agentic, decideTaskToolMode(catalog, now, tt, "OpenCode", "deepseek-coder-free").mode);
    }

    // Medida en vivo pero NEGATIVA → none con motivo.
    try insertAgenticMatrixRow(catalog, "OpenCode", "mimo-free", "no", "live_probe", "1800000000");
    const no = decideTaskToolMode(catalog, now, .testear, "OpenCode", "mimo-free");
    try std.testing.expectEqual(TaskToolMode.none, no.mode);
    try std.testing.expectEqualStrings("cap_tool_calls medida 'no' en vivo", no.motivo.?);

    // Evidencia declarada (provenance != live_probe) → none.
    try insertAgenticMatrixRow(catalog, "Cohere", "command-r", "yes", "declared", "1800000000");
    const decl = decideTaskToolMode(catalog, now, .programar_zig, "Cohere", "command-r");
    try std.testing.expectEqual(TaskToolMode.none, decl.mode);
    try std.testing.expect(std.mem.indexOf(u8, decl.motivo.?, "live_probe") != null);

    // Sin fila → none.
    const sin = decideTaskToolMode(catalog, now, .documentar, "OpenCode", "inexistente");
    try std.testing.expectEqual(TaskToolMode.none, sin.mode);
    try std.testing.expect(std.mem.indexOf(u8, sin.motivo.?, "sin_fila") != null);

    // Foto caducada (updated_at fuera del TTL) → none.
    try insertAgenticMatrixRow(catalog, "OpenCode", "viejo", "yes", "live_probe", "1");
    const viejo = decideTaskToolMode(catalog, now, .ui, "OpenCode", "viejo");
    try std.testing.expectEqual(TaskToolMode.none, viejo.mode);
    try std.testing.expectEqualStrings("foto de capacidades caducada", viejo.motivo.?);

    // Sin catálogo → none con motivo.
    const sin_cat = decideTaskToolMode(null, now, .programar, "X", "y");
    try std.testing.expectEqual(TaskToolMode.none, sin_cat.mode);
    try std.testing.expectEqualStrings("sin_catalogo", sin_cat.motivo.?);

    // #874: la reparación (.corregir) SÍ consulta la matriz — antes abría tools
    // incondicionalmente y gastaba la reparación en un 422. Sin catálogo degrada.
    const corr_sin = decideTaskToolMode(null, now, .corregir, "X", "y");
    try std.testing.expectEqual(TaskToolMode.none, corr_sin.mode);
    try std.testing.expectEqualStrings("sin_catalogo", corr_sin.motivo.?);
    // Con evidencia viva positiva abre governed_exec; con negativa degrada.
    try insertAgenticMatrixRow(catalog, "Cohere", "command-a-03-2025", "yes", "live_probe", "1800000000");
    try std.testing.expectEqual(TaskToolMode.governed_exec, decideTaskToolMode(catalog, now, .corregir, "Cohere", "command-a-03-2025").mode);
    const corr_no = decideTaskToolMode(catalog, now, .corregir, "OpenCode", "mimo-free");
    try std.testing.expectEqual(TaskToolMode.none, corr_no.mode);
    try std.testing.expectEqualStrings("cap_tool_calls medida 'no' en vivo", corr_no.motivo.?);

    // `auditar` (governed_read) y los no elegibles conservan su base sin matriz.
    try std.testing.expectEqual(TaskToolMode.governed_read, decideTaskToolMode(null, now, .auditar, "X", "y").mode);
    try std.testing.expectEqual(TaskToolMode.none, decideTaskToolMode(catalog, now, .investigar, "OpenCode", "deepseek-coder-free").mode);
    try std.testing.expectEqual(TaskToolMode.none, decideTaskToolMode(catalog, now, .ejecutar, "OpenCode", "deepseek-coder-free").mode);
}

test "D-C1 #874: la reparación elige el siguiente candidato apto o degrada sin tools" {
    const allocator = std.testing.allocator;
    var catalog = try db.Connection.open(allocator, ":memory:");
    defer catalog.close();
    const migrator = db.Migrator.init(allocator);
    try migrator.migrate(catalog, &db.catalog_schema);
    const now: i64 = 1_800_000_000;
    // El modelo que produjo el artefacto fallido NO admite tools (medido en
    // vivo); un segundo candidato de la misma orden SÍ las admite.
    try insertAgenticMatrixRow(catalog, "Cohere", "command-a-reasoning-08-2025", "no", "live_probe", "1800000000");
    try insertAgenticMatrixRow(catalog, "Cohere", "command-a-03-2025", "yes", "live_probe", "1800000000");
    try insertAgenticMatrixRow(catalog, "Cohere", "command-x-reasoning", "no", "live_probe", "1800000000");

    var sa = Superagent.init(allocator, catalog, null, NoopMemory.backend(), now);

    // Caso apto: el candidato elegido por correctionChoice no admite tools, pero
    // otro asignado SÍ → la reparación rota a él con governed_exec.
    {
        const assignments = [_]ModelAssignment{
            .{ .task_id = "t1", .assigned = true, .provider_name = "Cohere", .model_name = "command-a-reasoning-08-2025", .is_free = true, .reason = "" },
            .{ .task_id = "t2", .assigned = true, .provider_name = "Cohere", .model_name = "command-x-reasoning", .is_free = true, .reason = "" },
            .{ .task_id = "t3", .assigned = true, .provider_name = "Cohere", .model_name = "command-a-03-2025", .is_free = true, .reason = "" },
        };
        const rc = sa.repairToolChoice(catalog, &assignments, "t1", "command-a-reasoning-08-2025", &.{}).?;
        try std.testing.expectEqual(TaskToolMode.governed_exec, rc.mode);
        try std.testing.expectEqualStrings("command-a-03-2025", rc.model_name);
        try std.testing.expectEqualStrings("Cohere", rc.provider_name);
    }
    // Caso sin apto: ningún candidato admite tools → degrada a none (sin 422).
    {
        const assignments = [_]ModelAssignment{
            .{ .task_id = "t1", .assigned = true, .provider_name = "Cohere", .model_name = "command-a-reasoning-08-2025", .is_free = true, .reason = "" },
            .{ .task_id = "t2", .assigned = true, .provider_name = "Cohere", .model_name = "command-x-reasoning", .is_free = true, .reason = "" },
        };
        const rc = sa.repairToolChoice(catalog, &assignments, "t1", "command-a-reasoning-08-2025", &.{}).?;
        try std.testing.expectEqual(TaskToolMode.none, rc.mode);
    }
    // r3 (P1): si el único candidato es el modelo que falló, la
    // cadena está agotada: no hay reparación (antes devolvía el mismo modelo
    // con `.none`, que repetía un candidato ya intentado).
    {
        const assignments = [_]ModelAssignment{
            .{ .task_id = "t1", .assigned = true, .provider_name = "Cohere", .model_name = "command-a-03-2025", .is_free = true, .reason = "" },
        };
        try std.testing.expect(sa.repairToolChoice(catalog, &assignments, "t1", "command-a-03-2025", &.{}) == null);
    }
    // el segundo auditor P1: sin catálogo (o `:memory:`) la reparación degrada a none — no
    // abre tools sin medición, igual que decideTaskToolMode.
    {
        const assignments = [_]ModelAssignment{
            .{ .task_id = "t1", .assigned = true, .provider_name = "Cohere", .model_name = "command-a-03-2025", .is_free = true, .reason = "" },
            .{ .task_id = "t2", .assigned = true, .provider_name = "Cohere", .model_name = "command-b-03-2025", .is_free = true, .reason = "" },
        };
        const rc = sa.repairToolChoice(null, &assignments, "t1", "command-a-03-2025", &.{}).?;
        try std.testing.expectEqual(TaskToolMode.none, rc.mode);
        try std.testing.expectEqualStrings("command-b-03-2025", rc.model_name);
    }
    // el segundo auditor P1: el pin manual mantiene governed_exec aunque no haya medición.
    {
        sa.forced_provider = "Cohere";
        sa.forced_model = "command-a-reasoning-08-2025";
        defer {
            sa.forced_provider = null;
            sa.forced_model = null;
        }
        const rc = sa.repairToolChoice(null, &[_]ModelAssignment{}, "t1", "command-a-reasoning-08-2025", &.{}).?;
        try std.testing.expectEqual(TaskToolMode.governed_exec, rc.mode);
        try std.testing.expectEqualStrings("command-a-reasoning-08-2025", rc.model_name);
        try std.testing.expectEqualStrings("Cohere", rc.provider_name);
    }
    // r3 (P1): el tramo de la cadena del despacho original también
    // queda excluido — el asignado de t1 ya se probó en el despacho original y
    // el que falló fue un respaldo; ninguno se repite.
    {
        const assignments = [_]ModelAssignment{
            .{ .task_id = "t1", .assigned = true, .provider_name = "Cohere", .model_name = "command-a-03-2025", .is_free = true, .reason = "" },
            .{ .task_id = "t2", .assigned = true, .provider_name = "Cohere", .model_name = "command-a-reasoning-08-2025", .is_free = true, .reason = "" },
        };
        // t1 (asignado apto) ya se probó en el despacho original; t2 es el que
        // falló. Sin candidato sin probar, la reparación no existe.
        try std.testing.expect(sa.repairToolChoice(catalog, &assignments, "t1", "command-a-reasoning-08-2025", &.{}) == null);
    }
}

