// Seam scriptada de la sesión agéntica: escribe en el worktree lo que la tool
// `finish` dejaría en el ejecutor → LiveLlm, sin proveedor ni bucle de red.
const AgenticSessionStub = struct {
    io: std.Io,
    dir: std.Io.Dir,
    call_finish: bool,
};

fn agenticSessionStub(ctx: ?*anyopaque, llm: *live_worker.LiveLlm, _: []const u8, _: []const u8) []const u8 {
    const stub: *AgenticSessionStub = @ptrCast(@alignCast(ctx.?));
    if (!stub.call_finish) return "prosa final sin finish";
    // Lo que toolFinish copia al LiveLlm tras adoptAgenticState.
    llm.last_agentic_finished = true;
    llm.last_agentic_summary = llm.allocator.dupe(u8, "escribi salida.txt") catch null;
    const files = llm.allocator.alloc([]u8, 1) catch return "";
    files[0] = llm.allocator.dupe(u8, "salida.txt") catch return "";
    llm.last_agentic_files = files;
    // La sesión real escribe con write_file gobernado; el stub lo hace directo.
    stub.dir.writeFile(stub.io, .{ .sub_path = "salida.txt", .data = "contenido producido por la sesion agentica\n" }) catch {};
    return "hecho";
}

// Captura git scriptada para el diff del modo agéntico (mismo patrón que el
// `scriptedCapture` de headless_adapter, que es privado de su archivo).
var agentic_script_entries: []const [2][]const u8 = &.{};

fn agenticScriptedCapture(allocator: std.mem.Allocator, argv: []const []const u8, cwd: ?[]const u8) anyerror!providers.github.CmdCapture {
    for (argv) |arg| if (std.mem.eql(u8, arg, "--show-toplevel")) {
        return .{ .exit_code = 0, .stdout = try allocator.dupe(u8, cwd orelse ""), .stderr = try allocator.dupe(u8, "") };
    };
    var joined = std.ArrayList(u8).empty;
    defer joined.deinit(allocator);
    for (argv, 0..) |a, i| {
        if (i > 0) try joined.append(allocator, ' ');
        try joined.appendSlice(allocator, a);
    }
    for (agentic_script_entries) |e| {
        if (std.mem.indexOf(u8, joined.items, e[0]) != null) {
            return .{
                .exit_code = 0,
                .stdout = try allocator.dupe(u8, e[1]),
                .stderr = try allocator.dupe(u8, ""),
            };
        }
    }
    return .{
        .exit_code = 0,
        .stdout = try allocator.dupe(u8, ""),
        .stderr = try allocator.dupe(u8, ""),
    };
}

fn agenticTestCtx(sa: *Superagent, outcome: *OrderOutcome) Superagent.FanoutContext {
    return .{
        .mutex = sync.Mutex.init(),
        .completed = 0,
        .failed = 0,
        .integrated = 0,
        .rejected = 0,
        .outputs = std.ArrayList(WorkerOutput).empty,
        .pending = std.ArrayList(ApprovalRequest).empty,
        .saved = std.ArrayList([]const u8).empty,
        .saved_owner = std.ArrayList([]const u8).empty,
        .results = std.ArrayList(Superagent.TaskRunResult).empty,
        .sa = sa,
        .outcome = outcome,
        .llm_fn = null,
        .llm_ctx = null,
        .catalog_path = null,
        .needed_resources = &.{},
    };
}

fn agenticTestOutcome(allocator: std.mem.Allocator) OrderOutcome {
    return .{
        .allocator = allocator,
        .order_id = 9,
        .plan_id = 0,
        .status = .planned,
        .plan = .{ .allocator = allocator, .understanding = "", .questions = &.{}, .tasks = &.{} },
        .assignments = &.{},
        .discovery_needed = &.{},
        .discovery_missing = &.{},
        .discovery_needed_resources = &.{},
    };
}

test "D-C1 AGENTIC: sin `finish` la tarea es incomplete, nunca done" {
    const allocator = std.testing.allocator;
    var threaded = std.Io.Threaded.init(allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const wt = try tmp.dir.realPathFileAlloc(io, ".", allocator);
    defer allocator.free(wt);

    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    var stub = AgenticSessionStub{ .io = io, .dir = tmp.dir, .call_finish = false };
    sa.agentic_run_fn = agenticSessionStub;
    sa.agentic_run_ctx = &stub;
    sa.external_capture_fn = agenticScriptedCapture;
    agentic_script_entries = &.{.{ "rev-parse HEAD", "base123\n" }};
    defer agentic_script_entries = &.{};

    var llm = live_worker.LiveLlm{ .allocator = allocator, .lives = &.{}, .buffer = std.ArrayList(u8).empty, .catalog_path = "" };
    defer llm.deinit();
    var outcome = agenticTestOutcome(allocator);
    var ctx = agenticTestCtx(&sa, &outcome);

    workspace.setOrderRootOverride(wt);
    defer workspace.setOrderRootOverride(null);

    const pt = planner.PlannedTask{ .id = "t1", .task_type = .programar, .department = "programacion", .description = "escribe salida.txt", .contract_fields = &.{}, .depends_on = &.{} };
    const res = Superagent.runAgenticTask(&ctx, allocator, pt, &llm, "sys", null);
    defer res.deinit(allocator);

    try std.testing.expect(!res.success);
    try std.testing.expect(res.incomplete);
    try std.testing.expect(std.mem.indexOf(u8, res.error_msg, "finish") != null);
}

test "D-C1 AGENTIC: con `finish` los artefactos salen del diff del worktree" {
    const allocator = std.testing.allocator;
    var threaded = std.Io.Threaded.init(allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const wt = try tmp.dir.realPathFileAlloc(io, ".", allocator);
    defer allocator.free(wt);

    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.setEventConn(runtime, 9);
    var stub = AgenticSessionStub{ .io = io, .dir = tmp.dir, .call_finish = true };
    sa.agentic_run_fn = agenticSessionStub;
    sa.agentic_run_ctx = &stub;
    sa.external_capture_fn = agenticScriptedCapture;
    agentic_script_entries = &.{
        .{ "rev-parse HEAD", "base123\n" },
        .{ "diff --name-only", "salida.txt\x00" },
        .{ "ls-files --others", "" },
    };
    defer agentic_script_entries = &.{};

    var llm = live_worker.LiveLlm{ .allocator = allocator, .lives = &.{}, .buffer = std.ArrayList(u8).empty, .catalog_path = "" };
    defer llm.deinit();
    var outcome = agenticTestOutcome(allocator);
    var ctx = agenticTestCtx(&sa, &outcome);

    workspace.setOrderRootOverride(wt);
    defer workspace.setOrderRootOverride(null);

    const pt = planner.PlannedTask{ .id = "t1", .task_type = .programar, .department = "programacion", .description = "escribe salida.txt", .contract_fields = &.{}, .depends_on = &.{} };
    const res = Superagent.runAgenticTask(&ctx, allocator, pt, &llm, "sys", null);
    defer res.deinit(allocator);

    try std.testing.expect(res.success);
    try std.testing.expect(!res.incomplete);
    // El artefacto es el archivo REAL del worktree — contenido leído del disco,
    // no lo que el modelo declaró en finish.files.
    try std.testing.expectEqual(@as(usize, 1), res.artifacts.len);
    try std.testing.expectEqualStrings("salida.txt", res.artifacts[0].path);
    try std.testing.expectEqualStrings("contenido producido por la sesion agentica\n", res.artifacts[0].content);
    try std.testing.expect(res.worktree_root != null);
    try std.testing.expectEqualStrings(wt, res.worktree_root.?);
    // El evento agentic_finish dejó la declaración del modelo en el ledger.
    const stmt = try runtime.prepare("SELECT COUNT(*) FROM events WHERE kind='agentic_finish' AND payload_json LIKE '%salida.txt%'");
    defer runtime.finalize(stmt);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
    try std.testing.expectEqual(@as(c_int, 1), db.c.sqlite3_column_int(stmt, 0));
}

