test "D-C1 AGENTIC: configureTaskLiveLlm en modo agéntico declara el set completo con el techo de rondas" {
    const allocator = std.testing.allocator;
    var llm = live_worker.LiveLlm{ .allocator = allocator, .lives = &.{}, .buffer = std.ArrayList(u8).empty, .catalog_path = "" };
    defer llm.deinit();
    var token = live_worker.CancellationToken{};

    configureTaskLiveLlm(&llm, .agentic, ".", .{ .mode = .bypass }, true, .local, null, &token, 200);

    try std.testing.expect(llm.use_connector_v2_dispatch);
    // El ajuste de la cabina queda acotado al techo duro de 32.
    try std.testing.expectEqual(@as(usize, 32), llm.max_tool_rounds);
    const source = llm.governed_tools_source.?;
    try std.testing.expect(source.agentic);
    try std.testing.expect(!source.read_only);

    // Rondas por debajo del mínimo viable se elevan a 2 (una sola ronda no
    // puede ejecutar una tool y leer su resultado — el contrato `finish`
    // sería inalcanzable por construcción).
    var llm2 = live_worker.LiveLlm{ .allocator = allocator, .lives = &.{}, .buffer = std.ArrayList(u8).empty, .catalog_path = "" };
    defer llm2.deinit();
    configureTaskLiveLlm(&llm2, .agentic, ".", .{ .mode = .bypass }, true, .local, null, null, 0);
    try std.testing.expectEqual(@as(usize, 2), llm2.max_tool_rounds);
}

test "D-C1 AGENTIC: el ajuste de pasos en 1 apaga el modo agéntico aunque haya live_probe" {
    const allocator = std.testing.allocator;
    var threaded = std.Io.Threaded.init(allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const dir_path = try tmp.dir.realPathFileAlloc(io, ".", allocator);
    defer allocator.free(dir_path);
    const cat_path = try std.fs.path.join(allocator, &.{ dir_path, "catalog.db" });
    defer allocator.free(cat_path);

    // Catálogo real en disco con evidencia live_probe='yes' — el gate pasaría
    // si no mediara el ajuste de la cabina.
    var catalog = try db.Connection.open(allocator, cat_path);
    const migrator = db.Migrator.init(allocator);
    try migrator.migrate(catalog, &db.catalog_schema);
    try insertAgenticMatrixRow(catalog, "OpenCode", "deepseek-coder-free", "yes", "live_probe", "1800000000");
    catalog.close();

    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1_800_000_000);
    sa.setEventConn(runtime, 7);
    var outcome = agenticTestOutcome(allocator);
    var ctx = agenticTestCtx(&sa, &outcome);
    ctx.catalog_path = cat_path;

    // Default de la cabina (1 = una sola llamada): la evidencia viva no basta —
    // el modo se apaga y NO se emite agentic_unavailable (no es un problema de
    // capacidad, es la posición elegida).
    sa.max_agent_iterations = 1;
    try std.testing.expectEqual(TaskToolMode.none, Superagent.resolveTaskToolMode(&ctx, allocator, .programar, "t1", "OpenCode", "deepseek-coder-free"));

    // Con el ajuste activo (>=2) la misma evidencia abre el modo.
    sa.max_agent_iterations = 8;
    try std.testing.expectEqual(TaskToolMode.agentic, Superagent.resolveTaskToolMode(&ctx, allocator, .programar, "t1", "OpenCode", "deepseek-coder-free"));

    const stmt = try runtime.prepare("SELECT COUNT(*) FROM events WHERE kind='agentic_unavailable'");
    defer runtime.finalize(stmt);
    try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(stmt));
    try std.testing.expectEqual(@as(c_int, 0), db.c.sqlite3_column_int(stmt, 0));
}

test "E5.18: pickBestOfNMembers — proveedores distintos, lista explícita manda" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    defer sa.deinitSwarm();

    // Enjambre con un proveedor duplicado (case-insensitive) y uno no-texto.
    sa.setSwarmJson("[{\"provider\":\"OpenRouter\",\"model\":\"free-a\"},{\"provider\":\"openrouter\",\"model\":\"free-b\"},{\"provider\":\"NVIDIA\",\"model\":\"free-c\"},{\"provider\":\"Cohere\",\"model\":\"free-d\"}]");
    const picked = try sa.pickBestOfNMembers(allocator, 3, null);
    defer {
        for (picked) |m| {
            allocator.free(m.provider);
            allocator.free(m.model);
        }
        allocator.free(picked);
    }
    try std.testing.expectEqual(@as(usize, 3), picked.len);
    try std.testing.expectEqualStrings("OpenRouter", picked[0].provider);
    try std.testing.expectEqualStrings("NVIDIA", picked[1].provider);
    try std.testing.expectEqualStrings("Cohere", picked[2].provider);

    // La lista explícita de la orden manda sobre el enjambre.
    const explicit = try sa.pickBestOfNMembers(allocator, 2, "[{\"provider\":\"Mistral\",\"model\":\"m1\"},{\"provider\":\"Groq\",\"model\":\"g1\"},{\"provider\":\"mistral\",\"model\":\"m2\"}]");
    defer {
        for (explicit) |m| {
            allocator.free(m.provider);
            allocator.free(m.model);
        }
        allocator.free(explicit);
    }
    try std.testing.expectEqual(@as(usize, 2), explicit.len);
    try std.testing.expectEqualStrings("Mistral", explicit[0].provider);
    try std.testing.expectEqualStrings("Groq", explicit[1].provider);

    // Pocos proveedores distintos → devuelve menos (el llamador decide, no miente).
    const few = try sa.pickBestOfNMembers(allocator, 4, "[{\"provider\":\"Solo\",\"model\":\"s1\"}]");
    defer {
        for (few) |m| {
            allocator.free(m.provider);
            allocator.free(m.model);
        }
        allocator.free(few);
    }
