    const task = planner.PlannedTask{ .id = "visual", .task_type = .programar, .department = "programacion", .description = "capture", .contract_fields = &.{}, .depends_on = &.{}, .needs_vision = true };
    const absent = try sa.assignModel(task, &.{}, &.{});
