const SnapOrderPlanner = struct {
    fn backend(self: *@This()) planner.PlannerBackend {
        return .{ .ptr = self, .planFn = plan, .deinitFn = noop };
    }
    fn noop(_: *anyopaque) void {}
    fn plan(_: *anyopaque, a: std.mem.Allocator, _: []const u8, _: []const planner.ClarificationAnswer, _: ?[]const u8) planner.PlannerError!planner.Plan {
        const tasks = try a.alloc(planner.PlannedTask, 3);
        tasks[0] = try tareaFixture(a, "t1", .programar, &.{});
        tasks[1] = try tareaFixture(a, "t2", .ejecutar, &.{"t1"});
        a.free(tasks[1].contract_fields[0].name);
        tasks[1].contract_fields[0].name = try a.dupe(u8, "command");
        tasks[1].contract_fields[0].value = try a.dupe(u8, "python reloj.py");
        tasks[2] = try tareaFixture(a, "t3", .auditar, &.{"t2"});
        a.free(tasks[2].contract_fields[0].name);
        tasks[2].contract_fields[0].name = try a.dupe(u8, "verdict");
        return .{ .allocator = a, .understanding = try a.dupe(u8, "reloj simulado"), .questions = try a.alloc(planner.ClarificationQuestion, 0), .tasks = tasks };
    }
};

const SnapExternalRun = struct {
    exe: []const u8,
    fail_snapshot: bool = false,
    calls: usize = 0,
    fn run(raw: ?*anyopaque, a: std.mem.Allocator, io: std.Io, task: planner.PlannedTask, req: external_agents.RunRequest, sb: sandbox.Sandbox) !external_agents.RunOutcome {
        const self: *@This() = @ptrCast(@alignCast(raw.?));
        self.calls += 1;
        if (self.fail_snapshot) {
            var impossible = try headless_adapter.captureArtifactBaselineContext(a, io, headless_adapter.defaultCapture, "Z:\\missing-snap-order", null, .{ .diagnostic = req.snapshot_diagnostic, .sink = req.event_sink });
            impossible.deinit(a);
            return error.TestUnexpectedResult;
        }
        const version = try a.dupe(u8, "mock-codex");
        errdefer a.free(version);
        if (task.task_type == .ejecutar) {
            const argv = try a.dupe(u8, "cli-worker-mock --headless clock; Codex profile");
            errdefer a.free(argv);
            const arts = try a.alloc(worker_backend.Artifact, 1);
            errdefer a.free(arts);
            arts[0] = .{ .path = try a.dupe(u8, "command"), .content = try a.dupe(u8, "python reloj.py") };
            return .{ .success = true, .exit_code = 0, .agent_version = version, .argv_censored = argv, .declaration = try a.dupe(u8, "command simulado"), .detail = try a.dupe(u8, "command simulado"), .artifacts = arts };
        }
        // el caso mide instantáneas y ejecución real con el mock,
        // no el bloqueo de AGENTS globales; la herencia explícita lo aparta.
        var profile = headless_adapter.CODEX;
        profile.inherit_personal_context = true;
        var report = try headless_adapter.run(a, io, task, sb, .{
            .profile = profile,
            .spawn_prefix = &.{ self.exe, "--headless", "clock" },
            .worktree = req.worktree,
            .timeout_ms = 30000,
            .event_sink = req.event_sink,
            .snapshot_diagnostic = req.snapshot_diagnostic,
            .getenv = struct {
                fn absent(_: std.mem.Allocator, _: []const u8) anyerror!?[]u8 {
                    return null;
                }
            }.absent,
        });
        errdefer report.deinit(a);
        return .{ .success = report.success, .exit_code = report.exit_code, .agent_version = version, .argv_censored = report.argv_censored.?, .declaration = report.declaration, .detail = report.transcript, .artifacts = report.artifacts, .env_warnings = report.env_warnings };
    }
};

