fn snapOrderFixture(fail_snapshot: bool) !void {
    const a = std.testing.allocator;
    var threaded = std.Io.Threaded.init(a, .{ .environ = @import("platform.zig").environ() });
    defer threaded.deinit();
    const io = threaded.io();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const parent = try tmp.dir.realPathFileAlloc(io, ".", a);
    defer a.free(parent);
    const root = try std.fmt.allocPrint(a, "{s}" ++ std.fs.path.sep_str ++ "devagents-workspace", .{parent});
    defer a.free(root);
    workspace.setOrderRootOverride(root);
    defer workspace.setOrderRootOverride(null);
    var runtime = try openRuntime(a);
    defer runtime.close();
    var catalog = try db.Connection.open(a, ":memory:");
    defer catalog.close();
    try db.Migrator.init(a).migrate(catalog, &db.catalog_schema);
    try seedCatalog(catalog);
    var router = model_router.Router.init(a, catalog, null, 1);
    try router.seedInitialScores();
    var pp = SnapOrderPlanner{};
    const pb = pp.backend();
    var sa = Superagent.init(a, runtime, &router, NoopMemory.backend(), 1);
    sa.setExecForcedModel("agent:codex", "codex");
    sa.setAuditForcedModel("OpenCode", "gemini-flash-free");
    sa.deterministic = true;
    sa.permission_config.mode = .bypass;
    const bin = (try headless_adapter.defaultGetEnv(a, "BEATS_TEST_BIN_DIR")) orelse return error.MissingMockBin;
    defer a.free(bin);
    const exe = try std.fs.path.join(a, &.{ bin, "cli-worker-mock" ++ comptime @import("builtin").target.exeFileExt() });
    defer a.free(exe);
    var fake = SnapExternalRun{ .exe = exe, .fail_snapshot = fail_snapshot };
    sa.external_run_fn = SnapExternalRun.run;
    sa.external_run_ctx = &fake;
    var outcome = try sa.processOrder("default", "Haz un reloj y ejecutalo", &.{}, pb, null, null);
    defer outcome.deinit();
    sa.setEventConn(runtime, outcome.order_id);
    var marker: u8 = 0;
    var result = try sa.approveAndDispatch(&outcome, fixtureSuccessfulLlm, &marker, null);
    defer result.deinit(a);
    const stmt = try runtime.prepare("SELECT kind,payload_json FROM events WHERE kind IN ('external_agent_finished','task_failed','task_done','order_failed','shell_command','exec_result')");
    defer runtime.finalize(stmt);
    var detailed: usize = 0;
    var executed: bool = false;
    while (db.c.sqlite3_step(stmt) == db.c.SQLITE_ROW) {
        const kind = std.mem.span(db.c.sqlite3_column_text(stmt, 0).?);
        const payload = std.mem.span(db.c.sqlite3_column_text(stmt, 1).?);
        std.debug.print("SNAP_EVENT {s} {s}\n", .{ kind, payload });
        if (fail_snapshot and (std.mem.eql(u8, kind, "external_agent_finished") or std.mem.eql(u8, kind, "task_failed") or std.mem.eql(u8, kind, "order_failed")) and std.mem.indexOf(u8, payload, "etapa=raiz; ruta=.; error=FileNotFound") != null) detailed += 1;
        if (!fail_snapshot and std.mem.eql(u8, kind, "shell_command") and std.mem.indexOf(u8, payload, "\"status\":\"done\"") != null and std.mem.indexOf(u8, payload, "\"exit_code\":0") != null) executed = true;
    }
    if (fail_snapshot) {
        try std.testing.expect(result.order_failed);
        try std.testing.expect(detailed >= 3);
    } else {
        try std.testing.expect(!result.order_failed);
        try std.testing.expect(executed);
        try std.testing.expect(fake.calls >= 1);
        var safe = try @import("confined_fs.zig").Root.init(a, root);
        defer safe.deinit();
        const file = try safe.open("reloj.py");
        defer file.close(io);
        var content: [64]u8 = undefined;
        const n = try file.readPositionalAll(io, &content, 0);
        try std.testing.expectEqualStrings("print('reloj-simulado')\n", content[0..n]);
    }
}

test "SEC-FS superagent keeps guard pinned through Node and removes it" {
    if (@import("builtin").os.tag != .windows) return @import("platform.zig").skip("T9: el guard queda fijado porque Windows abre sin compartir DELETE; en POSIX un archivo abierto se puede borrar y el guard no se puede fijar asi");
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.permission_config.mode = .bypass;
    sa.plan_approved = true;

    const producer_task = planner.PlannedTask{
        .id = "producer",
        .task_type = .programar,
        .department = "programacion",
        .description = "write passing node assertion fixture",
        .contract_fields = &.{},
        .depends_on = &.{},
    };
    const artifacts = [_]worker_backend.Artifact{
        .{ .path = "test_guard_pinned.js", .content = "const fs = require('node:fs'); const assert = require('node:assert/strict'); assert.throws(() => fs.unlinkSync(process.execArgv[1])); assert.throws(() => fs.writeFileSync(process.execArgv[1], 'evil'));\n" },
    };
    const producer_path = (try workspace.persistTask(allocator, 991105, producer_task, &artifacts)) orelse return error.TestUnexpectedResult;
    defer allocator.free(producer_path);
    const cwd = std.fs.path.dirname(producer_path) orelse return error.TestUnexpectedResult;
    var outputs = std.ArrayList(WorkerOutput).empty;
    defer {
        for (outputs.items) |output| {
            allocator.free(output.worker_id);
            allocator.free(output.stream);
            if (output.task_id.len > 0) allocator.free(output.task_id);
            allocator.free(output.text);
        }
        outputs.deinit(allocator);
    }
    var pending = std.ArrayList(ApprovalRequest).empty;
    defer {
        for (pending.items) |request| request.deinit(allocator);
        pending.deinit(allocator);
    }
    const outcome = try sa.governedExecuteTestRawAtCwd("node", &.{"test_guard_pinned.js"}, "test", &outputs, &pending, cwd);
    defer {
        allocator.free(outcome.stderr);
        if (outcome.stdout) |stdout| allocator.free(stdout);
    }
    try std.testing.expect(outcome.ran);
    try std.testing.expectEqual(@as(i32, 0), outcome.exit_code);
    try std.testing.expectEqualStrings("", outcome.stderr);
    const guard_name = try std.fmt.allocPrint(allocator, ".__devagents_console_assert_guard_{x}.cjs", .{std.hash.Wyhash.hash(0, "test")});
    defer allocator.free(guard_name);
    var root = try @import("confined_fs.zig").Root.init(allocator, cwd);
    defer root.deinit();
    try std.testing.expectError(error.FileNotFound, root.open(guard_name));
}

