test "CK-PRV-003 P1-a: effective router assignments decide order review not empty auditor pin" {
    const a = std.testing.allocator;
    var runtime = try openRuntime(a);
    defer runtime.close();
    var catalog = try db.Connection.open(a, ":memory:");
    defer catalog.close();
    const migrator = db.Migrator.init(a);
    try migrator.migrate(catalog, &db.catalog_schema);
    try catalog.exec("INSERT INTO providers(id,name,base_url,api_style,is_free_tier) VALUES(1,'OpenRouter','x','openai',1)");
    try catalog.exec("INSERT INTO api_keys(id,provider_id,label,key_ciphertext,quota_limit,quota_used,status) VALUES(1,1,'fixture',x'00',100,0,'active')");
    try catalog.exec("INSERT INTO models(id,provider_id,model_name,context_window,is_free,latency_p50_ms,available) VALUES(1,1,'gpt-fixture',128000,1,800,1),(2,1,'claude-fixture',128000,1,900,1)");
    var router = model_router.Router.init(a, catalog, null, 1);
    try router.seedInitialScores();
    var sa = Superagent.init(a, runtime, &router, NoopMemory.backend(), 1);
    sa.setExecForcedModel("OpenRouter", "gpt-fixture");
    const build = planner.PlannedTask{ .id = "build", .task_type = .programar, .department = "programacion", .description = "x", .contract_fields = &.{}, .depends_on = &.{} };
    var audit_dependencies = [_][]const u8{"build"};
    const audit = planner.PlannedTask{ .id = "audit", .task_type = .auditar, .department = "auditoria", .description = "x", .contract_fields = &.{}, .depends_on = &audit_dependencies };
    const tasks = [_]planner.PlannedTask{ build, audit };
    for ([_][]const u8{ "independent_pending", "self_reviewed", "self_reviewed" }, 0..) |expected, scenario| {
        if (scenario == 1) sa.setAuditForcedModel("OpenRouter", "gpt-fixture");
        const order_id = try sa.insertOrder("prv003-r3", "fixture", "planned");
        const plan_id = try sa.insertPlan(order_id, "fixture", &.{});
        const assignments = try sa.assignAndPersist(plan_id, if (scenario == 2) tasks[0..1] else &tasks);
        defer {
            for (assignments) |assignment| assignment.deinit(a);
            a.free(assignments);
        }
        try std.testing.expect(assignments[0].assigned);
        if (scenario == 0) {
            try std.testing.expect(sa.audit_forced_model == null);
            try std.testing.expect(assignments[1].assigned);
            try std.testing.expectEqualStrings("claude-fixture", assignments[1].model_name);
        } else if (scenario == 1) {
            try std.testing.expectEqualStrings(assignments[0].model_name, assignments[1].model_name);
        }
        const q = try runtime.prepare("SELECT payload_json FROM events WHERE order_id=? AND kind='composer_review_v1' ORDER BY id DESC LIMIT 1");
        defer runtime.finalize(q);
        try db.bindInt(q, 1, order_id);
        try std.testing.expectEqual(db.c.SQLITE_ROW, db.c.sqlite3_step(q));
        const json = std.mem.span(db.c.sqlite3_column_text(q, 0));
        const parsed = try std.json.parseFromSlice(std.json.Value, a, json, .{});
        defer parsed.deinit();
        try std.testing.expectEqualStrings(expected, parsed.value.object.get("mode").?.string);
    }
}

test "CK-COMP-009 B task retry with another model keeps raw original turns and failure evidence" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();

    const CkPlanner = struct {
        fn plan(_: *anyopaque, a: std.mem.Allocator, goal: []const u8, _: []const planner.ClarificationAnswer, _: ?[]const u8) planner.PlannerError!planner.Plan {
            const tasks = try a.alloc(planner.PlannedTask, 1);
            tasks[0] = try D7Planner.tarea(a, "t1", "PIEZA_A sin extension", &.{});
            return .{ .allocator = a, .understanding = try a.dupe(u8, goal), .questions = try a.alloc(planner.ClarificationQuestion, 0), .tasks = tasks };
        }
        fn deinit(_: *anyopaque) void {}
    };
    var marker: u8 = 0;
    const backend = planner.PlannerBackend{ .ptr = &marker, .planFn = CkPlanner.plan, .deinitFn = CkPlanner.deinit };
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    // No se lanza ningún proceso real: el ejecutor determinista reporta éxito.
    g_exec_call_count = 1;
    sa.executor_spawn_fn = testExecutorSpawnFailThenOk;
    sa.permission_config.mode = .bypass;
    // r4 (control positivo): token presente pero NUNCA cancelado.
    // El mismo guard de cancelación deja pasar el reintento y este se
    // persiste: contraparte exacta del cero de la prueba de cancelación.
    const retry_token = try live_worker.CancellationToken.create(allocator);
    defer retry_token.release();
    sa.cancel_token = retry_token;
    var outcome = try sa.processOrder("ck-mot-011", "implementa una pieza con una sola salida", &.{}, backend, null, null);
    defer outcome.deinit();
    sa.setEventConn(runtime, outcome.order_id);

    // Cadena del plan: el primer candidato devuelve basura y el respaldo (otro
    // candidato, nunca el mismo) resuelve el reintento. Sin catálogo vivo la
    // política de gasto no aplica: no hay proveedor al que cobrar.
    var chain_fallbacks = try allocator.alloc(ModelChoice, 1);
    chain_fallbacks[0] = .{ .provider_name = try allocator.dupe(u8, "Local"), .model_name = try allocator.dupe(u8, "CandidatoDos"), .is_free = true };
    try ckMot011SetAssignment(allocator, &outcome, "Local", "CandidatoUno", true, chain_fallbacks);

    try runtime.exec("INSERT INTO messages(order_id,role,content,created_at) SELECT id,'assistant','TURN BEFORE FAILURE',2 FROM orders");
    allocator.free(outcome.plan.understanding);
    outcome.plan.understanding = try allocator.dupe(u8, "summarized goal");
    const RetryDouble = struct {
        call_count: usize = 0,
        original: bool = false,
        transcript: bool = false,
        evidence: bool = false,
        response: []const u8,
        correction_response: []const u8,
        fn call(ptr: *anyopaque, _: []const u8, prompt: []const u8) []const u8 {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.call_count += 1;
            if (self.call_count == 1) return self.response;
            self.original = std.mem.indexOf(u8, prompt, "implementa una pieza con una sola salida") != null;
            self.transcript = std.mem.indexOf(u8, prompt, "TURN BEFORE FAILURE") != null;
            self.evidence = std.mem.indexOf(u8, prompt, "InvalidArtifact") != null;
            return self.correction_response;
        }
    };
    var llm = RetryDouble{
        // Primera respuesta del candidato: basura ilegible → InvalidArtifact →
        // el worker termina sin artefacto (worker_failed).
        .response = "respuesta invalida del modelo: ni JSON ni codigo",
        // Reintento acotado (replan): un artefacto real que sí cumple el contrato.
        // El contenido supera el umbral de "campo string primario" del validador.
        .correction_response = "[{\"field\":\"source\",\"content\":\"MARCA = 1;\\nCK_MOT_011_OK = true;\"},{\"field\":\"filename\",\"content\":\"ck_mot_011.js\"}]",
    };
    var dr = try sa.approveAndDispatch(&outcome, RetryDouble.call, &llm, null);
    defer dr.deinit(allocator);
    const path = try std.fmt.allocPrintSentinel(allocator, "devagents-workspace\\orden-{d}\\ck_mot_011.js", .{outcome.order_id}, 0);
    defer allocator.free(path);
    defer _ = DeleteFileA(path.ptr);

    // Un candidato que devuelve basura no puede condenar la orden: hubo un
    // reintento acotado que el segundo intento resolvió.
    try std.testing.expectEqual(@as(usize, 2), llm.call_count);
    try std.testing.expectEqual(@as(usize, 1), dr.completed_count);
    try std.testing.expectEqual(@as(usize, 0), dr.failed_count);
    try std.testing.expect(!dr.order_failed);
    try std.testing.expect(llm.original);
    try std.testing.expect(llm.transcript);
    try std.testing.expect(llm.evidence);
    const selected = try runtime.prepare("SELECT payload_json FROM events WHERE kind='task_retry'");
    defer runtime.finalize(selected);
    try std.testing.expect(db.c.sqlite3_step(selected) == db.c.SQLITE_ROW);
    try std.testing.expect(std.mem.indexOf(u8, std.mem.span(db.c.sqlite3_column_text(selected, 0).?), "CandidatoDos") != null);

    // Control positivo (r4): con la cadena y el token SIN cancelar, la orden
    // persiste exactamente 1 `task_retry` — el flujo que la prueba de
    // cancelación congela reintentaría de verdad.
    const retry_stmt = try runtime.prepare("SELECT COUNT(*) FROM events WHERE order_id = ? AND kind = 'task_retry'");
    defer runtime.finalize(retry_stmt);
    try db.bindInt(retry_stmt, 1, outcome.order_id);
    try std.testing.expect(db.c.sqlite3_step(retry_stmt) == db.c.SQLITE_ROW);
    try std.testing.expectEqual(@as(c_int, 1), db.c.sqlite3_column_int(retry_stmt, 0));
}

