    try std.testing.expectError(error.UnknownContextWindow, buildCorrectionHandoffDescription(a, runtime, 9, "summary", &nw, task, 0, null));
    try std.testing.expectError(error.HandoffTooLarge, buildCorrectionHandoffDescription(a, runtime, 9, "summary", &nw, task, 100, null));
    const description = try buildCorrectionHandoffDescription(a, runtime, 9, "summary", &nw, task, 20000, null);
    defer a.free(description);
