    try handoff.checkHandoffPrompt(prompt, 20000, @intCast(counter.count(nw.system_prompt) + 16), counter);
}

// c3: fixtures sin proveedores; el spawn se conserva en el despacho real.
const Mot034Spawn = struct {
    var calls: usize = 0;
    var fail_first: bool = false;
    var retry_dependency: bool = false;
    var explicit_args: bool = false;
    var code: i32 = 1;
    var trace: bool = false;
    var argv_ok: bool = true;
    fn reset() void {
        calls = 0;
        fail_first = false;
        retry_dependency = false;
        explicit_args = false;
        code = 1;
        trace = false;
        argv_ok = true;
    }
    fn spawn(a: std.mem.Allocator, exe: []const u8, args: []const []const u8, _: []const u8, _: u32, _: usize, _: ?executor.StreamSink, _: ?*anyopaque, _: []const u8) executor.ExecutorError!executor.RunResult {
        calls += 1;
        if (explicit_args) {
            argv_ok = argv_ok and std.mem.eql(u8, exe, "python") and args.len == 4;
            if (args.len == 4) for (args, [_][]const u8{ "cli.py", "add", "1", "2" }) |got, want| {
                argv_ok = argv_ok and std.mem.eql(u8, got, want);
            };
        } else {
            argv_ok = argv_ok and args.len == 1;
        }
        const fails = trace or (fail_first and calls == 1) or (retry_dependency and calls == 2);
        const exit: i32 = if (retry_dependency and calls == 1) 0 else if (fails) 1 else code;
        return .{ .exit_code = exit, .stdout = try a.dupe(u8, ""), .stderr = try a.dupe(u8, if (fails) "Traceback (most recent call last):\nRuntimeError: fixture\n" else if (exit == 0) "" else "usage: cli.py <args>\n") };
    }
};

fn mot034Task(id: []const u8, kind: model_router.TaskType, description: []const u8, deps: []const []const u8) planner.PlannedTask {
    return .{ .id = id, .task_type = kind, .department = "programacion", .description = description, .contract_fields = &.{}, .depends_on = @constCast(deps) };
}

fn mot034Event(a: std.mem.Allocator, conn: db.Connection, kind: []const u8, task: []const u8) !?[]const u8 {
    const stmt = try conn.prepare("SELECT payload_json FROM events WHERE kind = ? AND json_extract(payload_json, '$.task_id') = ? ORDER BY id DESC LIMIT 1");
    defer conn.finalize(stmt);
    try db.bindText(stmt, 1, kind);
    try db.bindText(stmt, 2, task);
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return null;
    const ptr = db.c.sqlite3_column_text(stmt, 0);
    const len: usize = @intCast(db.c.sqlite3_column_bytes(stmt, 0));
    return try a.dupe(u8, ptr[0..len]);
}

fn mot034ExpectSkip(entries: []const AuditEntry, task: []const u8, expected: usize) !void {
    var count: usize = 0;
    for (entries) |entry| {
        if (entry.subject_id != Superagent.idToInt(task) or !std.mem.eql(u8, entry.action, "EXEC") or !std.mem.eql(u8, entry.verdict, "SKIP")) continue;
        count += 1;
        try std.testing.expect(std.mem.indexOf(u8, entry.notes, "programa_requiere_argumentos") != null);
    }
    try std.testing.expectEqual(expected, count);
}

fn mot034ExpectNote(text: []const u8) !void {
    try std.testing.expect(std.mem.indexOf(u8, text, "programa_requiere_argumentos") != null);
    try std.testing.expect(std.mem.indexOf(u8, text, "no se verifico") != null);
}

fn mot034DispatchFile(check_omission: bool, with_consumer: bool) !void {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var threaded = std.Io.Threaded.init(a, .{});
    defer threaded.deinit();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try tmp.dir.realPathFileAlloc(threaded.io(), ".", a);
    var runtime = try openRuntime(a);
    defer runtime.close();
    var sa = Superagent.init(a, runtime, null, NoopMemory.backend(), 1);
    sa.permission_config.mode = .bypass;
    sa.plan_approved = true;
    sa.executor_spawn_fn = Mot034Spawn.spawn;
    sa.setEventConn(runtime, 991343);
    var outcome = agenticTestOutcome(a);
    outcome.order_id = 991343;
    outcome.plan_id = 0;
    var tasks = [_]planner.PlannedTask{
        mot034Task("t1", .programar, "crear rpn.py", &.{}),
        mot034Task("t2", .ejecutar, "lanzar el productor", &.{"t1"}),
    };
    outcome.plan.tasks = if (with_consumer) &tasks else tasks[0..1];
    var llm = TestLlmCtx{ .response = "[{\"field\":\"source\",\"content\":\"import sys\nprint(sys.argv[1])\n\"},{\"field\":\"filename\",\"content\":\"rpn.py\"}]" };
    var ctx = agenticTestCtx(&sa, &outcome);
    ctx.order_root = root;
    ctx.llm_fn = testLlmFn;
    ctx.llm_ctx = &llm;
    Superagent.runTaskInWave(&ctx, tasks[0]);
    try std.testing.expectEqual(@as(usize, 1), ctx.results.items.len);
    try std.testing.expect(ctx.results.items[0].exec.ran);
    try std.testing.expectEqual(check_omission, ctx.results.items[0].exec.usage_only);
    if (with_consumer) Superagent.runTaskInWave(&ctx, tasks[1]);
    for (ctx.results.items) |res| {
        try std.testing.expect(res.exec.ran);
        try std.testing.expectEqual(check_omission, res.exec.usage_only);
        if (check_omission) {
            try std.testing.expect(res.success);
            try mot034ExpectNote(res.error_msg);
            try mot034ExpectSkip(ctx.audit_entries.items, res.task_id, 1);
            const payload = (try mot034Event(a, runtime, "task_done", res.task_id)) orelse return error.MissingTaskDone;
            try std.testing.expect(std.mem.indexOf(u8, payload, "\"exec_omitted\":true") != null);
            try std.testing.expect(std.mem.indexOf(u8, payload, "\"exec_omitted_reason\":\"programa_requiere_argumentos\"") != null);
            const skipped = (try mot034Event(a, runtime, "exec_skipped", res.task_id)) orelse return error.MissingExecSkipped;
            try std.testing.expect(std.mem.indexOf(u8, skipped, "\"command\":") != null);
            try std.testing.expect(std.mem.indexOf(u8, skipped, "\"file\":") != null);
            try std.testing.expect(std.mem.indexOf(u8, skipped, "usage: cli.py") != null);
        } else {
            try std.testing.expect(std.mem.indexOf(u8, res.error_msg, "programa_requiere_argumentos") == null);
            try mot034ExpectSkip(ctx.audit_entries.items, res.task_id, 0);
            try std.testing.expect((try mot034Event(a, runtime, "exec_skipped", res.task_id)) == null);
            try std.testing.expectEqual(!Mot034Spawn.trace, res.success);
        }
    }
    try std.testing.expect(Mot034Spawn.argv_ok);
    try std.testing.expectEqual(@as(usize, if (with_consumer) 2 else 1), Mot034Spawn.calls);
}

