fn mot034RawDispatch(source: enum { contract, description, worker }) !void {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var threaded = std.Io.Threaded.init(a, .{});
    defer threaded.deinit();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try tmp.dir.realPathFileAlloc(threaded.io(), ".", a);
    var runtime = try openRuntime(a);
    defer runtime.close();
    var sa = Superagent.init(a, runtime, null, NoopMemory.backend(), 1);
    sa.permission_config.mode = .bypass;
    sa.plan_approved = true;
    sa.approve_command_fn = struct {
        fn approve(_: ?*anyopaque, exe: []const u8, args: []const []const u8, _: []const u8) anyerror!bool {
            return std.mem.eql(u8, exe, "python") and args.len == 4 and std.mem.eql(u8, args[0], "cli.py") and std.mem.eql(u8, args[1], "add") and std.mem.eql(u8, args[2], "1") and std.mem.eql(u8, args[3], "2");
        }
    }.approve;
    sa.executor_spawn_fn = Mot034Spawn.spawn;
    sa.setEventConn(runtime, 991344);
    var outcome = agenticTestOutcome(a);
    outcome.order_id = 991344;
    outcome.plan_id = 0;
    var fields = [_]planner.ContractField{.{ .name = "command", .field_type = .string, .required = true, .value = "python cli.py add 1 2" }};
    var task = mot034Task("t3", .ejecutar, if (source == .description) "Ejecutar python cli.py add 1 2" else "lanzar comando resuelto", &.{});
    if (source == .contract) task.contract_fields = &fields;
    var tasks = [_]planner.PlannedTask{task};
    outcome.plan.tasks = &tasks;
    workspace.setOrderRootOverride(root);
    defer workspace.setOrderRootOverride(null);
    _ = try workspace.persistTask(a, outcome.order_id, mot034Task("setup", .programar, "cli.py", &.{}), &.{.{ .path = "cli.py", .content = "print(1)\n" }});
    var llm = TestLlmCtx{ .response = "[{\"field\":\"command\",\"content\":\"python cli.py add 1 2\"}]" };
    var ctx = agenticTestCtx(&sa, &outcome);
    ctx.order_root = root;
    ctx.llm_fn = testLlmFn;
    ctx.llm_ctx = &llm;
    Mot034Spawn.reset();
    Mot034Spawn.explicit_args = true;
    Mot034Spawn.code = 2;
    Superagent.runTaskInWave(&ctx, task);
    if (Mot034Spawn.calls != 1) std.debug.print("C3 raw fixture calls={d}, results={d}, stderr={s}\n", .{ Mot034Spawn.calls, ctx.results.items.len, if (ctx.results.items.len > 0) ctx.results.items[0].exec.stderr else "no result" });
    try std.testing.expectEqual(@as(usize, 1), Mot034Spawn.calls);
    try std.testing.expect(Mot034Spawn.argv_ok);
    try std.testing.expectEqual(@as(usize, 1), ctx.results.items.len);
    const res = ctx.results.items[0];
    try std.testing.expect(res.exec.ran);
    try std.testing.expect(!res.exec.usage_only);
    try std.testing.expect(!res.success);
    const event = (try mot034Event(a, runtime, "task_failed", task.id)) orelse return error.MissingTaskFailed;
    try std.testing.expect(std.mem.indexOf(u8, event, "\"cause\":\"execution_failed\"") != null);
    try std.testing.expect((try mot034Event(a, runtime, "exec_skipped", task.id)) == null);
}

