const Mot034RecoveryPlanner = struct {
    consumer: bool,
    fn plan(raw: *anyopaque, a: std.mem.Allocator, goal: []const u8, _: []const planner.ClarificationAnswer, _: ?[]const u8) planner.PlannerError!planner.Plan {
        const self: *@This() = @ptrCast(@alignCast(raw));
        const tasks = try a.alloc(planner.PlannedTask, if (self.consumer) 2 else 1);
        tasks[0] = try D7Planner.tarea(a, "t1", "crear rpn.py", &.{});
        if (self.consumer) {
            tasks[1] = try D7Planner.tarea(a, "t2", "lanzar el productor", &.{"t1"});
            tasks[1].task_type = .ejecutar;
        }
        return .{ .allocator = a, .understanding = try a.dupe(u8, goal), .questions = try a.alloc(planner.ClarificationQuestion, 0), .tasks = tasks };
    }
    fn deinit(_: *anyopaque) void {}
};

fn mot034Recovery(consumer: bool) !void {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var threaded = std.Io.Threaded.init(a, .{});
    defer threaded.deinit();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try tmp.dir.realPathFileAlloc(threaded.io(), ".", a);
    workspace.setOrderRootOverride(root);
    defer workspace.setOrderRootOverride(null);
    var runtime = try openRuntime(a);
    defer runtime.close();
    var sa = Superagent.init(a, runtime, null, NoopMemory.backend(), 1);
    sa.permission_config.mode = .bypass;
    sa.plan_approved = true;
    sa.executor_spawn_fn = Mot034Spawn.spawn;
    var pp = Mot034RecoveryPlanner{ .consumer = consumer };
    const pb = planner.PlannerBackend{ .ptr = &pp, .planFn = Mot034RecoveryPlanner.plan, .deinitFn = Mot034RecoveryPlanner.deinit };
    var outcome = try sa.processOrder("mot034-fixture", "pieza Python", &.{}, pb, null, null);
    defer outcome.deinit();
    sa.setEventConn(runtime, outcome.order_id);
    var llm = TestLlmCtxWithCounter{
        .response = "[{\"field\":\"source\",\"content\":\"import sys\nprint(sys.argv[1])\n\"},{\"field\":\"filename\",\"content\":\"rpn.py\"}]",
        .correction_response = "[{\"field\":\"source\",\"content\":\"import sys\nprint(str(sys.argv[1]))\n\"},{\"field\":\"filename\",\"content\":\"rpn.py\"}]",
    };
    Mot034Spawn.reset();
    Mot034Spawn.code = 2;
    Mot034Spawn.retry_dependency = consumer;
    Mot034Spawn.fail_first = !consumer;
    var dr = try sa.approveAndDispatch(&outcome, testLlmFnWithCounter, &llm, null);
    defer dr.deinit(a);
    try std.testing.expect(Mot034Spawn.argv_ok);
    try std.testing.expectEqual(@as(usize, if (consumer) 3 else 2), Mot034Spawn.calls);
    try std.testing.expectEqual(@as(usize, 0), dr.failed_count);
    const task = if (consumer) "t2" else "t1";
    try mot034ExpectSkip(dr.audit_entries, task, 1);
    const done = (try mot034Event(a, runtime, "task_done", task)) orelse return error.MissingRecoveredTaskDone;
    try mot034ExpectNote(done);
    try std.testing.expect(std.mem.indexOf(u8, done, "\"exec_omitted\":true") != null);
    try std.testing.expect(std.mem.indexOf(u8, done, "\"exec_omitted_reason\":\"programa_requiere_argumentos\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, done, "REEJECUTADO") == null);
    var fixes: usize = 0;
    for (dr.audit_entries) |entry| {
        if (entry.subject_id != Superagent.idToInt(task) or !std.mem.eql(u8, entry.action, "FIX") or !std.mem.eql(u8, entry.verdict, "PASS")) continue;
        fixes += 1;
        try std.testing.expect(std.mem.indexOf(u8, entry.notes, "re-executed") == null);
    }
    try std.testing.expectEqual(@as(usize, 1), fixes);
    const skipped = (try mot034Event(a, runtime, "exec_skipped", task)) orelse return error.MissingExecSkipped;
    try std.testing.expect(std.mem.indexOf(u8, skipped, "\"command\":") != null);
    try std.testing.expect(std.mem.indexOf(u8, skipped, "\"file\":") != null);
}

