// / E-GOV.3 (rama e5-gov, prueba reaplicada el 11-nov sobre el motor de hoy). E-GOV.4 de superagent y las notas del gate de E-GOV.1 no se reaplicaron.
// Sin checkpoint_root_fn (los handles retenidos de las rondas 4-5 no se reaplicaron).

// Reproducciones con los contratos y el archivo exactos de la medición;
// ejecución/LLM inyectados, sin cuenta, proveedor ni datos del propietario.
const GovRecordedPlanner = struct {
    record: std.json.Value,

    fn backend(self: *@This()) planner.PlannerBackend {
        return .{ .ptr = self, .planFn = plan, .deinitFn = noop };
    }
    fn noop(_: *anyopaque) void {}
    fn plan(raw: *anyopaque, a: std.mem.Allocator, _: []const u8, _: []const planner.ClarificationAnswer, _: ?[]const u8) planner.PlannerError!planner.Plan {
        const self: *@This() = @ptrCast(@alignCast(raw));
        const task = self.record.object.get("tasks").?.array.items[0];
        const spec = self.record.object.get("contracts").?.array.items[0].object.get("interface_spec").?.string;
        const parsed = std.json.parseFromSlice(std.json.Value, a, spec, .{}) catch return error.OutOfMemory;
        defer parsed.deinit();
        const fields = try a.alloc(planner.ContractField, parsed.value.array.items.len);
        for (parsed.value.array.items, 0..) |field, i| fields[i] = .{
            .name = try a.dupe(u8, field.object.get("name").?.string),
            .field_type = .string,
            .required = field.object.get("required").?.bool,
            .value = if (field.object.get("value")) |v| try a.dupe(u8, v.string) else null,
        };
        const tasks = try a.alloc(planner.PlannedTask, 1);
        tasks[0] = .{ .id = try a.dupe(u8, "t1"), .task_type = .programar, .department = try a.dupe(u8, "programacion"), .description = try a.dupe(u8, task.object.get("description").?.string), .contract_fields = fields, .depends_on = try a.alloc([]const u8, 0) };
        return .{ .allocator = a, .understanding = try a.dupe(u8, self.record.object.get("plans").?.array.items[0].object.get("understanding").?.string), .questions = try a.alloc(planner.ClarificationQuestion, 0), .tasks = tasks };
    }
};

fn govRecorded(a: std.mem.Allocator, io: std.Io) !std.json.Parsed(std.json.Value) {
    const path = if (@import("builtin").os.tag != .windows)
        try a.dupe(u8, if (std.c.getenv("BEATS_GOV_RECORDED")) |raw| std.mem.span(raw) else "gov-recorded.json")
    else if (std.testing.environ.getWindows(std.unicode.utf8ToUtf16LeStringLiteral("BEATS_GOV_RECORDED"))) |wide|
        try std.unicode.utf16LeToUtf8Alloc(a, wide)
    else
        try a.dupe(u8, "gov-recorded.json");
    defer a.free(path);
    const raw = try std.Io.Dir.cwd().readFileAlloc(io, path, a, .limited(128 * 1024));
    defer a.free(raw);
    return std.json.parseFromSlice(std.json.Value, a, raw, .{ .allocate = .alloc_always });
}

fn govCount(a: std.mem.Allocator, conn: db.Connection, table: []const u8) !i32 {
    const sql = try std.fmt.allocPrint(a, "SELECT COUNT(*) FROM {s}", .{table});
    defer a.free(sql);
    const stmt = try conn.prepare(sql);
    defer conn.finalize(stmt);
    if (db.c.sqlite3_step(stmt) != db.c.SQLITE_ROW) return error.StepFailed;
    return db.c.sqlite3_column_int(stmt, 0);
}

const GovExternalRun = struct {
    content: []const u8 = "",
    inherited: []const u8 = "",
    fail: bool = false,
    calls: usize = 0,
    fn run(raw: ?*anyopaque, a: std.mem.Allocator, io: std.Io, _: planner.PlannedTask, req: external_agents.RunRequest, sb: sandbox.Sandbox) anyerror!external_agents.RunOutcome {
        const self: *@This() = @ptrCast(@alignCast(raw.?));
        self.calls += 1;
        if (self.fail) return error.ArtifactTooLarge;
        var root = try std.Io.Dir.cwd().openDir(io, req.worktree, .{});
        defer root.close(io);
        try root.createDirPath(io, "src/itsdangerous");
        try root.writeFile(io, .{ .sub_path = "src/itsdangerous/timed.py", .data = self.inherited });
        try root.writeFile(io, .{ .sub_path = "src/itsdangerous/timed.py", .data = self.content });
        _ = sb;
        // Trusted engine seam: fingerprints computed from the exact pre-edit
        // file. Filesystem confinement is exercised separately by E-GOV.2.
        const artifacts = try a.alloc(worker_backend.Artifact, 1);
        artifacts[0] = .{ .path = try a.dupe(u8, "src/itsdangerous/timed.py"), .content = try a.dupe(u8, self.content), .inherited_placeholders = try artifact_quality.placeholderLines(a, self.inherited) };
        return .{ .success = true, .timed_out = false, .turn_limited = false, .exit_code = 0, .duration_ms = 1, .turns = 1, .agent_version = try a.dupe(u8, "fixture"), .argv_censored = try a.dupe(u8, "fixture"), .declaration = try a.dupe(u8, "archivo editado"), .detail = try a.dupe(u8, "fixture sin proveedores"), .artifacts = artifacts };
    }
};

test "E-GOV.3: pin externo sin respaldo y fallo ArtifactTooLarge preservado sin llamada nativa" {
    if (@import("builtin").os.tag != .windows) return @import("platform.zig").skip("T9: CLI externa (Codex, OpenCode, Claude, Gemini) no disponible en Linux en esta version (ExternalCliUnavailableOnLinux en external_cli_policy)");
    const a = std.testing.allocator;
    var threaded = std.Io.Threaded.init(a, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const wt = try tmp.dir.realPathFileAlloc(io, ".", a);
    defer a.free(wt);
    workspace.setOrderRootOverride(wt);
    defer workspace.setOrderRootOverride(null);
    const recorded = try govRecorded(a, io);
    defer recorded.deinit();
    const record = recorded.value.object.get("orden_9").?;
    var runtime = try openRuntime(a);
    defer runtime.close();
    var catalog = try db.Connection.open(a, ":memory:");
    defer catalog.close();
    try db.Migrator.init(a).migrate(catalog, &db.catalog_schema);
    try seedCatalog(catalog);
    var router = model_router.Router.init(a, catalog, null, 1);
    try router.seedInitialScores();
    var pp = GovRecordedPlanner{ .record = record };
    var sa = Superagent.init(a, runtime, &router, NoopMemory.backend(), 1);
    sa.setExecForcedModel("agent:codex", "codex");
    var fake = GovExternalRun{ .fail = true };
    sa.external_run_fn = GovExternalRun.run;
    sa.external_run_ctx = &fake;
    sa.permission_config.mode = .bypass;
    sa.executor_spawn_fn = testExecutorSpawnOk;
    var outcome = try sa.processOrder("gov", record.object.get("order").?.object.get("user_prompt").?.string, &.{}, pp.backend(), null, null);
    defer outcome.deinit();
    try std.testing.expectEqual(@as(usize, 0), outcome.assignments[0].fallbacks.len);
    sa.setEventConn(runtime, outcome.order_id);
    var marker: u8 = 0;
    var result = try sa.approveAndDispatch(&outcome, fixtureSuccessfulLlm, &marker, null);
    defer result.deinit(a);
    try std.testing.expectEqual(@as(usize, 1), fake.calls);
    try std.testing.expectEqual(@as(usize, 1), result.failed_count);
    try std.testing.expectEqual(@as(i32, 0), try govCount(a, runtime, "events WHERE kind='task_provider_ok'"));
    try std.testing.expectEqual(@as(i32, 1), try govCount(a, runtime, "events WHERE kind='task_failed' AND payload_json LIKE '%ArtifactTooLarge%' AND payload_json LIKE '%agent:codex%'"));
    // Una asignación restaurada/antigua con respaldo tampoco puede cruzar el
    // pin en ejecución, aunque no pase por assignModel en este despacho.
    var stale = try sa.processOrder("gov", record.object.get("order").?.object.get("user_prompt").?.string, &.{}, pp.backend(), null, null);
    defer stale.deinit();
    const assignment = &stale.assignments[0];
    for (assignment.fallbacks) |choice| choice.deinit(a);
    a.free(assignment.fallbacks);
    assignment.fallbacks = try a.alloc(ModelChoice, 1);
    assignment.fallbacks[0] = .{ .provider_name = try a.dupe(u8, "OpenCode"), .model_name = try a.dupe(u8, "gemini-flash-free"), .is_free = true };
    a.free(assignment.provider_name);
    a.free(assignment.model_name);
    assignment.provider_name = try a.dupe(u8, "Cohere");
    assignment.model_name = try a.dupe(u8, "command-r");
    sa.router = null;
    sa.setEventConn(runtime, stale.order_id);
    var stale_result = try sa.approveAndDispatch(&stale, fixtureSuccessfulLlm, &marker, null);
    defer stale_result.deinit(a);
    try std.testing.expectEqual(@as(usize, 1), fake.calls);
    try std.testing.expectEqual(@as(usize, 1), stale_result.failed_count);
    try std.testing.expectEqual(@as(i32, 1), try govCount(a, runtime, "events WHERE kind='task_failed' AND payload_json LIKE '%PIN_ASSIGNMENT_MISMATCH%' AND payload_json LIKE '%agent:codex%' AND payload_json LIKE '%Cohere%'"));
    a.free(assignment.provider_name);
    a.free(assignment.model_name);
    assignment.provider_name = try a.dupe(u8, "agent:codex");
    assignment.model_name = try a.dupe(u8, "obsolete-model");
    var wrong_model = try sa.approveAndDispatch(&stale, fixtureSuccessfulLlm, &marker, null);
    defer wrong_model.deinit(a);
    try std.testing.expectEqual(@as(usize, 1), fake.calls);
    try std.testing.expectEqual(@as(usize, 1), wrong_model.failed_count);
    try std.testing.expectEqual(@as(i32, 1), try govCount(a, runtime, "events WHERE kind='task_failed' AND payload_json LIKE '%PIN_ASSIGNMENT_MISMATCH%' AND payload_json LIKE '%obsolete-model%'"));
}

const T7RulesCapture = struct {
    calls: usize = 0,
    with_rules: usize = 0,
    fn call(ctx: *anyopaque, system: []const u8, _: []const u8) []const u8 {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        self.calls += 1;
        if (std.mem.indexOf(u8, system, project_rules.HEADER) != null and
            std.mem.indexOf(u8, system, "REGLA-T7: nombres en castellano") != null and
            std.mem.indexOf(u8, system, project_rules.PRECEDENCE_NOTE) != null) self.with_rules += 1;
        return "[{\"field\":\"source\",\"content\":\"print(1)\"}]";
    }
};

test "T7 reglas del proyecto: Orquestado y Colmena las llevan en el prompt de cada tarea" {
    const allocator = std.testing.allocator;
    for ([_]?[]const u8{ null, "[{\"provider\":\"OpenRouter\",\"model\":\"model-a\"},{\"provider\":\"OpenRouter\",\"model\":\"model-b\"}]" }) |swarm| {
        var runtime = try openRuntime(allocator);
        defer runtime.close();
        var mp = planner.MockPlanner.init(allocator);
        const pb = mp.backend();
        defer pb.deinit();
        var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
        sa.rules_context = .{ .custom = "REGLA-T7: nombres en castellano." };
        defer sa.deinitSwarm();
        sa.setSwarmJson(swarm);
        var outcome = try sa.processOrder("proj-t7-reglas", "construye una calculadora CLI en C con tests", &.{}, pb, null, null);
        defer outcome.deinit();
        var capture = T7RulesCapture{};
        var dr = try sa.approveAndDispatch(&outcome, T7RulesCapture.call, &capture, null);
        defer dr.deinit(allocator);
        // Cada llamada a un modelo (programar, testear, auditar…) llevó el bloque.
        try std.testing.expect(capture.calls > 0);
        try std.testing.expectEqual(capture.calls, capture.with_rules);
    }
}

test "T7 reglas del proyecto: las subtareas de delegate_tasks las reciben (rol y auditoria)" {
    const allocator = std.testing.allocator;
    var runtime = try openRuntime(allocator);
    defer runtime.close();
    var sa = Superagent.init(allocator, runtime, null, NoopMemory.backend(), 1);
    sa.rules_context = .{ .custom = "REGLA-T7: nombres en castellano." };
    var instruction = "Crea hola.py".*;
    const sub = delegation.Subtask{ .role = delegation.roleFor("programar").?, .instruction = &instruction, .files = &.{} };
    const text = try delegation.planJson(allocator, sub);
    defer allocator.free(text);
    var plan = try llm_planner.planFromJson(allocator, text);
    defer plan.deinit();
    try std.testing.expectEqual(@as(usize, 2), plan.tasks.len);
    // El despachador construye el prompt de cada hija con systemPromptForTask
    // (ver las llamadas del fan-out); aquí se captura su texto exacto.
    for (plan.tasks) |task| {
        const system = try sa.systemPromptForTask(task.department, task.task_type, task.description);
        defer allocator.free(system);
        try std.testing.expect(std.mem.indexOf(u8, system, project_rules.HEADER) != null);
        try std.testing.expect(std.mem.indexOf(u8, system, "REGLA-T7: nombres en castellano.") != null);
    }
}
